                    //    判据 = 日志 `框宽 200.0000 = 新建一条 Label 的 20.0000`。
                    var hudProbe = HudCanvas.RootRect != null
                        ? Label.CreateUgui(HudCanvas.RootRect, "X", new Vector3(0f, 99f, 0f), 3,
                                           Color.white, new Vector2(0.5f, 0.5f), "HudNoBoxProbe")
                        : null;
                    var hudProbeTmp = hudProbe != null ? hudProbe.GetComponentInChildren<TMPro.TMP_Text>(true) : null;
                    Check(hudProbeTmp != null,
                          "（前提）无框对照探针建起来了（`Label.CreateUgui` 那条路 = 与那 2 颗同路）"
                        + " —— 不成立时下面那 3 条（⑥ 一条 + 那 2 颗各一条）等于没验");
                    if (hudProbeTmp != null)
                    {
                        float defSd = hudProbeTmp.rectTransform.sizeDelta.x;
                        //  🔴 **2026-10-10（G0 · 铁律 5 就地订正）**：下面这 6 条原来还断「`min/max == 0`」——
                        //    **那是个错的期望值**（实测恒 **18/72**，这 6 条一起红）。**它不是我们给的缺省**：
                        //    TMP 自己的 `Awake`（`TextMeshPro.cs:549`）在**新建对象**那一刻调
                        //    `LoadDefaultSettings()`（`TextMeshPro.cs:607`），后者按 `TMP_Text.cs:5966-6000` 写进去 ——
                        //     `m_fontSize = m_fontSizeBase = TMP_Settings.defaultFontSize;`（`:5998`）
                        //     · `m_fontSizeMin = m_fontSize × defaultTextAutoSizingMinRatio;`（`:5999`）
                        //     · `m_fontSizeMax = m_fontSize × defaultTextAutoSizingMaxRatio;`（`:6000`）。
                        //    三份值的实读 = `Assets/TextMesh Pro/Resources/TMP Settings.asset:29-31`
                        //    （`m_defaultFontSize: 36` · `m_defaultAutoSizeMinRatio: 0.5` · `m_defaultAutoSizeMaxRatio: 2`）
                        //    ⇒ **36 × 0.5 = 18 · 36 × 2 = 72**，与实况逐位吻合。
                        //    🔴 而且这一对是**死值**（`m_enableAutoSizing` 是 false ⇒ TMP 一个字节都不采它）——
                        //    本文件 `Label.AutoSizing` 的 doc 早就写着这一条（「没开自适应时它们只是死值」）。
                        //    ⇒ ⛔ 断 `== 0` 恒红；断字面量 `18/72` 又是**拿 TMP 的内部常数当尺子**（换 TMP 版本就崩）。
                        //    ✅ 改成**同路对照**（与上面 `defSd` 同一形态）：「这一对从没被 `SetAutoFitBox` 写过」
                        //    是真命题，但它的判据 = 「与同一条建造路径下、同样没给框的那条 Label **逐位相等**」，
                        //    不是某个绝对值 ⇒ 给框（`SetAutoFitBox` 会写 `cur × minPx/nomPx`）就必然不相等。
                        float defMin = hudProbe.FontSizeMin, defMax = hudProbe.FontSizeMax;
                        //  ⑥ 一条**成本极低的保险**：`A1213①` 只动了 `BattleDriver.Hud` 的**形参**
                        //     （那些形参是**局部**的：别的路建 Label 根本走不到）⇒ 「不给框」那一态逐位不变。
                        //     ⚠️ 删掉 `min/max` 那一格之后本条**没有变松**：`!AutoSizing` 挡「共用件里偷偷调
                        //     `SetAutoFitBox`」，`WrappingMode == 0` 再挡一层「共用件里调 `SetWrapWidth` /
                        //     `SetAutoFitBox`」（`BuildTmp` 硬写 `NoWrap`，一给框就会被那条路改成 `Normal`）。
                        Check(!hudProbe.AutoSizing && hudProbe.WrappingMode == 0,
                              $"★（⑥）`Hud` **之外**那条路（`Label.Create`）建出来的字**没有**自适应、也没折行"
                            + $"（`AutoSizing={hudProbe.AutoSizing}` · 折行档 {hudProbe.WrappingMode}）"
                            + " —— `A1213①` 只动了 `Hud` 的形参，没碰共用件"
                            + $"（诊断：`min/max` = {hudProbe.FontSizeMin}/{hudProbe.FontSizeMax}"
                            + " = TMP 出厂的死值，⛔ 不作断言，见上注）");
                        foreach (var n in hudNoBox)
                        {
                            // 🔴 **2026-10-16（`EW8`）：查找口 `drv.hudRoot.Find` → **根画布**（与 `CheckHudBox` 同一条口径）。
                            //    这 4 颗也走 `Hud()` ⇒ 挂在根画布下、**不在 `hudRoot` 下**（根画布是根对象，见
                            //    `CheckHudBox` 的 doc）⇒ 旧读法 4 条前提**恒红** + 4 条静默跳过。
                            // 🔴 **2026-10-21（`G1`）**：再收进 `FindHudNode` —— 它们现在在 `BattleHudLayer` 下。
                            var t0 = FindHudNode(n);
                            var lb0 = t0 != null ? t0.GetComponent<Label>() : null;
                            var tm0 = t0 != null ? t0.GetComponentInChildren<TMPro.TMP_Text>(true) : null;
                            Check(lb0 != null && tm0 != null,
                                  $"（前提）`{n}` 在、且走 TMP 后端 —— 不成立时它下面那条等于没验");
                            if (lb0 == null || tm0 == null) continue;
                            // 四条一起断：**没自适应**（四格没接）· **没折行**（`Hud` 建它时硬写的 `NoWrap`，
                            // 一给框就会被 `SetAutoFitBox` 内部那句 `SetWrapWidth` 改成 `Normal`）·
                            // **框宽还是建标签时的默认值** · **`min/max` 逐位等于同路对照那一对**
                            // （⇒ 那一对从没被 `SetAutoFitBox` 写过；⛔ 别改回 `== 0`、也别写死 `18/72`，见上面那条注）。
                            Check(!lb0.AutoSizing && lb0.WrappingMode == 0
                                  && Mathf.Abs(tm0.rectTransform.sizeDelta.x - defSd) <= 1e-4f
                                  && Mathf.Abs(lb0.FontSizeMin - defMin) <= 1e-4f
                                  && Mathf.Abs(lb0.FontSizeMax - defMax) <= 1e-4f,
                                  $"★ `{n}` **没有框**（`AutoSizing={lb0.AutoSizing}` · 折行档 {lb0.WrappingMode} · "
                                + $"框宽 {tm0.rectTransform.sizeDelta.x:F4} = 新建一条 Label 的 {defSd:F4} · "
                                + $"min/max {lb0.FontSizeMin}/{lb0.FontSizeMax} = 同路对照的 {defMin}/{defMax}）"
                                + " —— 原版没有此件 / 四格读不到 / 四格在「缩放假」里 ⇒ 补框 = 主动制造偏离");
                        }
                    }
                    Object.DestroyImmediate(hudProbe.gameObject);

                    // ---- ④-2 灭自证（**结构上不可能同时满足**的那一对）----
                    //  **同一颗 Label**：第一次**不给框**调、第二次**给框**再调，两次都要满足
                    //  「文字块按 anchor 摆回节点原点」，而且两次的残差**逐位相同**。
                    //  🔴 只断「新写法（给了框）是对的」是**不够**的：若被测实现与它的检测器用同一个口，
                    //     **把两边一起改回旧写法**依然全绿。这一对守的是「框**根本不进**摆位算式」——
                    //     只要有人把框的 pivot / `anchoredPosition` / `sizeDelta` 加进
                    //     `Label.RefreshBounds()` 的摆位式，两次就不相等（判据 → `Hud` 的 doc 里那一串推导）。
                    var posProbe = Label.Create(driver.transform, "测试称号", new Vector3(0f, 99f, 0f), 3,
                                                Color.white, new Vector2(0.5f, 0.5f), "HudBoxPosProbe");
                    var posProbeTmp = posProbe != null ? posProbe.GetComponentInChildren<TMPro.TMP_Text>(true) : null;
                    Check(posProbe != null && posProbeTmp != null,
                          "（前提）摆位探针走 **TMP** 后端 —— 点阵后端没有「框」这回事，下面两条等于没验");
                    if (posProbeTmp != null)
                    {
                        posProbe.SetGlyphHeight(BattleDriver.TitleFontPx / 108f);
                        var relNoBox = HudBlockRel(posProbe, posProbeTmp);        // (a) **不给框**
                        posProbe.SetAutoFitBox(LayoutSpace.Px(187.40f), LayoutSpace.Px(36.84f), 2f, 35f, 36f);
                        var relBox = HudBlockRel(posProbe, posProbeTmp);           // (b) **给框**（称号那颗原版的框 + 四格）
                        // 🔴 **2026-10-10（`G0` 报出这个薄口、调度台裁「要堵」）——【灭自证】那一半**：
                        //    `SetAutoFitBox` **必须真的把自适应打开**。
                        //    ⚠️ **不补它的后果**：若有人把 `Battle/Label.cs:909` 那句 `_tmp.enableAutoSizing = true;`
                        //    整句删掉，「给框 / 不给框」两边**都不开自适应** ⇒ 本组 6 条（⑤×5 + ⑥）**一起假绿**
                        //    （而上面 16 颗多数**仍绿**）⇒ 那一整族的判断力归零，而**没有任何一条会红**。
                        //    ⇒ 这一条是**正向**那一半，与 ⑤/⑥ 的**反向**断言**互为对照组**（本仓「灭自证」的标准形状）。
                        //    **改坏法**：删 `Battle/Label.cs:909` 的 `enableAutoSizing = true;` ⇒ 本行红。
                        Check(posProbe.AutoSizing,
                              "★★ `SetAutoFitBox` **真的打开了自适应**（`Label.AutoSizing == true`）—— "
                            + "**灭自证**：它挡住「把 `Label` 的自适应开关整句删掉 ⇒ 上面给框/不给框两边一起绿」");
                        Check(relNoBox.magnitude < 1e-4f && relBox.magnitude < 1e-4f,
                              $"★ 同一颗 Label：**不给框**与**给框**两次都满足「文字块按 anchor 摆回节点原点」"
                            + $"（残差 {relNoBox.magnitude:E2} / {relBox.magnitude:E2} 世界单位）");
                        Check((relBox - relNoBox).magnitude < 1e-6f,
                              $"★★ 而且两次**逐位相同**（差 {(relBox - relNoBox).magnitude:E2}）"
                            + " —— 框的 pivot / `anchoredPosition` / `sizeDelta` **根本不进** `RefreshBounds` 的摆位式");
                    }
                    Object.DestroyImmediate(posProbe.gameObject);
                }

                // 加时标记：**默认关着**，图要在（原版也只在加时里出现；🆕 2026-09-20 起机制接上了）
                Check(!drv.OvertimeVisible, "加时标记默认**不显示**（原版 `OvertimeUi.Awake` 也是关着的）");
                Check(drv.OvertimeTex == "40k_icon_overtime", $"……但图已经接好了：{drv.OvertimeTex}");

                // 🆕 2026-09-20 加时 splash：手动播一次，逐帧推淡入/停/淡出，并拍一张图
                //    （原版 `OvertimeUi.DisplayOvertime`：淡入 1.0 / 停 1.0 / 淡出 1.0，`fadeTime` = 资产值 1.0）
                drv.ShowOvertime();
                // 🆕 2026-09-22 加时**音效**：原版 `OvertimeUi.enteringOvertimeSound` = AudioCue `OvertimeStart`
                //    （`bundle_soundcollection_assets_all/MonoBehaviour/OvertimeStart.json`：pitch/volume 全 1.0）。
                //    音频本地原本是**缺 setup 头的 FSB5 裸流**（播不了）⇒ 已重建，见 `工具/rebuild_overtime_start_ogg.py`。
                //    判据 = **clip 真的加载得到**（只调 `Play` 不算 —— 加载不到时 `WFSoundBank.Clip` 只打警告）。
                var otClip = WarpforgeVFX.WFSoundBank.Clip("OvertimeStart");
                Check(otClip != null, "★ 加时音效 `OvertimeStart` 加载得到"
                      + "（丢了就跑 `python 工具/rebuild_overtime_start_ogg.py` 重建）");
                if (otClip != null)
                    Check(Mathf.Abs(otClip.length - 5.4211f) < 0.01f && otClip.frequency == 48000,
                          $"★ ……而且是对的这份：{otClip.length:F4} s @ {otClip.frequency} Hz（原版 `m_Length = 5.421083` s / `m_Frequency = 48000`）");
                drv.TickOvertime(0f);
                Check(drv.OvertimeSplashVisible, "★ 播加时 splash 后**它亮起来了**");
                // 🔴 **2026-10-16（`T09` 批 3 · `OverHand` 组）**：这一组（提示条 + 加时 splash）已翻到
                //   **`AboveShader`** 子画布（原版 `AboveShader` = `OverHand`/0、`AboveShader` 的子件序 8/14）。
                var aboveCvA = HudCanvas.SubCanvas("AboveShader Canvas");
                Check(aboveCvA != null && aboveCvA.overrideSorting
                      && aboveCvA.sortingLayerID == HudCanvas.SortingLayer.OverHand
                      && aboveCvA.sortingOrder == 0,
                      "★ `T09` 批 3：`AboveShader` 子画布 = `overrideSorting` + **`OverHand`** + order 0"
                    + "（原版 `AboveShader` 就是这一档）");
                Check(aboveCvA != null && aboveCvA.GetComponent<CanvasScaler>() == null,
                      "★ ……而且**不带 `CanvasScaler`**（原版全场景只有根上一个；子画布加了会**二次缩放**）");
                // 🔴 反例：**字号**。踩过：把原版的 `m_fontSize = 80` 当本工程的单位用
                //    （`SetCapHeight(80 * WorldCapPerFontSize)`）⇒ 一个字母占了大半屏 ≈335 px。
                //    跨工程能对的只有**渲染高度**：原版 80 pt ⇒ 大写高 0.72 em ≈ 57.6 px ≈ 0.533 世界单位。
                var ts = drv.OvertimeSplashTextSize;
                // 🔴 **2026-10-16（`T09` 批 3）就地换量纲**：这一组已上 uGUI 画布 ⇒ 那个口现在给**设计 px**
                //   （原来给世界单位：0.5~9 / 0.2~2.5）。判据 = 原版 80 pt ⇒ 大写高 ≈ **57.6 px**、
                //   整行 `OVERTIME!` 约两三百 px 宽 ⇒ 下面这组界就是「几十~几百 px」，屏宽 1920 px。
                Check(ts.x > 50f && ts.x < 900f && ts.y > 20f && ts.y < 200f,
                      $"★ splash 字号合理：`OVERTIME!` 渲染成 {ts.x:F2}×{ts.y:F2} **px**"
                      + "（屏宽 1920 px；照抄原版 80 当本工程单位会让它铺满整屏）");
                Check(drv.OvertimeSplashAlpha < 0.01f, $"……从 α≈0 开始淡入（现在 {drv.OvertimeSplashAlpha:F3}）");
                // 🆕 **2026-10-18（W6）**：那行字 = **原版词条** `Battle/Overtime/Title`
                //    （原来这里写死的英文 `"OVERTIME!"`；键与 TMP 原文都在本地，判据 → `Core/Loc.cs`）。
                Check(drv.OvertimeSplashText == Loc.T(BattleDriver.OvertimeTerm),
                      $"★ splash 那行字「{drv.OvertimeSplashText}」= `Loc.T({BattleDriver.OvertimeTerm})`"
                    + $"（当前语档 {Loc.Current}；原版 TMP 原文 `OVERTIME!`）");
                Check(Loc.HasEntry(BattleDriver.OvertimeTerm),
                      $"★（坑表 #18）`Loc` 表里**真有** `{BattleDriver.OvertimeTerm}`");
                drv.TickOvertime(1.0f);                       // 淡入结束
                Check(Mathf.Abs(drv.OvertimeSplashAlpha - 1f) < 0.01f,
                      $"★ 1.0 s 后淡入到满（原版 fadeTime = 1.0，现在 α={drv.OvertimeSplashAlpha:F3}）");
                Shot(cam, "33_加时splash");
                drv.TickOvertime(1.0f);                       // 停留结束
                Check(Mathf.Abs(drv.OvertimeSplashAlpha - 1f) < 0.01f, "再停 1.0 s 期间保持满");
                drv.TickOvertime(1.0f);                       // 淡出结束
                Check(drv.OvertimeSplashAlpha < 0.01f, $"★ 再 1.0 s 淡出到 0（现在 {drv.OvertimeSplashAlpha:F3}）");
                Check(!drv.OvertimeSplashVisible && !drv.OvertimeVisible,
                      "★ 播完**两个都收起来**（原版 `AppendCallback` 那条路 —— 它是「闪一下」，不是常亮）");

                Shot(cam, "23_HUD补摆件");

                // ==================================================================
                //  🆕 2026-10-18（§8b 批 B · 2a / 2b 的**断言**）：原版 Canvas 直子那三件
                //
                //  生产代码 = `BattleDriver.BuildAspectRatioFillers` / `BuildErrorBanner` /
                //  `BuildScreenAspectRatioController`（⛔ 这一节一个字都不改它）；判据全文写在
                //  `Battle/ScreenAspectRatioController.cs` 与 `Battle/ErrorMessageBanner.cs` 的文件头。
                //  ⛔ 期望值一律写**原版字面量**（连出处一起写），不读那两件里的常量 —— 读常量 = 自证。
                // ==================================================================

                // ---- 2a-① 两枚黑边件（原版 `Aspect Ratio Filler{Top,Bottom}`，13/13 战场都有）----
                // 🔴 **2026-10-17（`W17` · `T09` 批 3 连带）：查找口 `hudRoot.Find` → **根画布**（口径同 `EW8`）。**
                //   `W15` 已把这两件从 `ImageQuad` 迁成 uGUI `HudPiece`（`BattleDriver.BuildOneAspectFiller`
                //   → `HudCanvas.MakeAnchored`，⛔ 不挂 `hudRoot`），而根画布是 `new GameObject("BattleHud Canvas")`、
                //   **没有 `SetParent`** ⇒ 它是**根对象**（`HudCanvas` 文件头第 2 条：根 canvas 不能挂 HUD 根下）
                //   ⇒ `hudRoot.Find` 恒 `null`（`Transform.Find` **不递归**）⇒ 这一段原来**一条都没真在验**。
                //   ⚠️ 量纲也跟着换：uGUI 档**一个 canvas 单位 = 一个设计 px** ⇒ 直接读 `sizeDelta`
                //   （`MakeAnchored` 把 `AspectFillerW/H` 原样写进去）；⛔ 别再 `WorldW × 108`（世界档的尺，
                //   非 16:9 下只有真设计 px 的 0.75 倍 —— 判据 → `HudPiece.SizePx` 的 doc）。
                Debug.Log(P + "   --- §8b 2a：两枚黑边件 ---");
                {
                    HudPiece FindPiece(string n)
                    {
                        var t = HudCanvas.RootRect != null ? HudCanvas.RootRect.Find(n) : null;
                        return t != null ? HudPiece.Of(t as RectTransform, t.GetComponent<Image>()) : null;
                    }
                    var topQ = FindPiece("Aspect Ratio Filler Top");
                    var botQ = FindPiece("Aspect Ratio Filler Bottom");
                    Check(topQ != null && botQ != null,
                          "★ 两枚黑边件都建出来了（原版 `Aspect Ratio Filler Top` / `… Bottom`，**名字逐字相同**，"
                        + "且都在**根画布的直接子件**那一层）");
                    // 🔴 前提**当场红**（⛔ 不许写成能整段静默不跑的写法）：少一件 ⇒ 下面那 6 条等于没验
                    if (topQ != null && botQ != null)
                    {
                        var rtTop = topQ.Rect;
                        var rtBot = botQ.Rect;

                        // 0) 档位：走的是 **uGUI 档**（`W15` 那次迁移没被人改回世界档 `ImageQuad`）。
                        //    改坏法：把 `BuildOneAspectFiller` 里的 `HudCanvas.MakeAnchored` 换回旧造法 ⇒ 件会重新挂到
                        //    `hudRoot` 下，上面那条前提先红；这条再把「档位」本身说清楚（原版这两颗是 Canvas 直子、
                        //    身上**没有** Canvas/CanvasGroup）。
                        Check(topQ.IsUgui && botQ.IsUgui,
                              "★ 两枚都是 **uGUI 档**（`HudPiece.IsUgui`；原版是 `BattleHud/Canvas` 的直接子件）");

                        // 1) 尺寸 = 原版 `RectTransform_{3021,2916}.json` 的 `sizeDelta`（**未取整**）。
                        //    uGUI 档 `sizeDelta` 的单位**就是设计 px** ⇒ 直接比；⛔ 不乘 108、也不除 108。
                        var sdTop = rtTop.sizeDelta;
                        var sdBot = rtBot.sizeDelta;
                        Check(Mathf.Abs(sdTop.x - 3252.123046875f) < 1e-3f
                           && Mathf.Abs(sdTop.y - 1842.02001953125f) < 1e-3f
                           && Mathf.Abs(sdBot.x - 3252.123046875f) < 1e-3f
                           && Mathf.Abs(sdBot.y - 1842.02001953125f) < 1e-3f,
                              "★ 两枚都是原版那个矩形 **3252.123046875 × 1842.02001953125 设计 px**（`sizeDelta` 逐位）——"
                            + $" 实得 上 {sdTop.x:F3}×{sdTop.y:F3} / 下 {sdBot.x:F3}×{sdBot.y:F3}");
                        // 画出来 = 框（原版 `m_Sprite` 是 null、`m_Type = 0` + `m_PreserveAspect = 0` ⇒ 拉满那个矩形）。
                        // 改坏法：把 `MakeAnchored` 里的 `preserveAspect` 打开 ⇒ 1×1 白图按原比例内接成正方形 ⇒ 黑边缩水。
                        var imgTop = rtTop.GetComponent<Image>();
                        var imgBot = rtBot.GetComponent<Image>();
                        Check(imgTop != null && imgBot != null
                           && !imgTop.preserveAspect && !imgBot.preserveAspect,
                              "★ 画出来就是那个矩形（原版 `m_PreserveAspect = 0` ⇒ 拉满，不是按贴图比例内接）");

                        // 2) 中心 = 原版 `anchoredPosition`（上 `0.0006713899783790112 / 1641.0999755859375`、
                        //    下 `-3.051800013054162e-05 / -1641.0999755859375`，y 向上、相对 Canvas 中心）。
                        //    `HudCanvas.CenterPx` 读的是**枢轴那一点**（左上原点、y 向下）⇒ 先确认 pivot = 中心，
                        //    读到才是矩形中心（那件的 doc：非居中 pivot 会读偏，⛔ 别按名字推）。
                        Check(Mathf.Abs(rtTop.pivot.x - 0.5f) < 1e-6f && Mathf.Abs(rtTop.pivot.y - 0.5f) < 1e-6f
                           && Mathf.Abs(rtBot.pivot.x - 0.5f) < 1e-6f && Mathf.Abs(rtBot.pivot.y - 0.5f) < 1e-6f,
                              "（前提）两枚都是居中 pivot ⇒ `HudCanvas.CenterPx` 读到的就是矩形中心"
                            + "（原版这两颗 anchor/pivot 都是 (0.5,0.5)）");
                        SettleShake();          // 保留：这一节后面还要拍图；本段算式已不依赖相机（读的是 RectTransform）
                        var pcTop = HudCanvas.CenterPx(rtTop);
                        var pcBot = HudCanvas.CenterPx(rtBot);
                        Check(Mathf.Abs(pcTop.x - (960f + 0.0006713899783790112f)) < 0.05f
                           && Mathf.Abs(pcTop.y - (540f - 1641.0999755859375f)) < 0.05f
                           && Mathf.Abs(pcBot.x - (960f - 3.051800013054162e-05f)) < 0.05f
                           && Mathf.Abs(pcBot.y - (540f + 1641.0999755859375f)) < 0.05f,
                              "★ 两枚的中心落在**原版那个点**上（y 从上：上 (960.0007, −1101.1) / 下 (960.0, 2181.1)，"
                            + "= (960 + ap.x, 540 − ap.y)）——"
                            + $" 实得 上 ({pcTop.x:F4},{pcTop.y:F4}) / 下 ({pcBot.x:F4},{pcBot.y:F4})");

                        // 3) 色 = `m_Color (0,0,0,1)`（uGUI 档读 `Image.color`，`HudPiece.Tint` 转发它）
                        var cTop = topQ.Tint;
                        Check(Mathf.Abs(cTop.r) < 1e-4f && Mathf.Abs(cTop.g) < 1e-4f && Mathf.Abs(cTop.b) < 1e-4f
                              && Mathf.Abs(cTop.a - 1f) < 1e-4f,
                              $"★ 纯黑不透明（原版 `m_Color (0,0,0,1)`）—— 实得 {cTop}");
                        // 4) 层序 = **兄弟序 0 / 1**（= 原版 `BattleHud/Canvas` 的 `m_Children[0]/[1]`，画在所有 UI 之下）。
                        //    🔴 uGUI 档**没有「渲染队列」**、z 也不参与排序（`HudPiece` 根本没有 `RenderQueue`）
                        //    ⇒ 旧那半条（`RenderQueue == 2999` + `z = +5`）**在本档不适用**；替代判别 = **同一父节点内的子件序**
                        //    （uGUI 里**序小 = 画在底下**，判据 → `HudCanvas` 的「子件序 = 按 z 排」那一节）。
                        Check(rtTop.parent == HudCanvas.RootRect && rtBot.parent == HudCanvas.RootRect
                           && rtTop.GetSiblingIndex() == 0 && rtBot.GetSiblingIndex() == 1,
                              "★ 垫在**最底层**：两枚都是根画布的**直接子件**、且排 **子件序 0 / 1**"
                            + "（= 原版 `m_Children[0]/[1]`，画在所有 UI 之下）——"
                            + $" 实得 父 {(rtTop.parent != null ? rtTop.parent.name : "null")}"
                            + $" / 子件序 {rtTop.GetSiblingIndex()} · {rtBot.GetSiblingIndex()}");

                        // 5) 「看不见」是**几何**造成的，不是显隐 ⇒ **永远不该藏**（原版 `m_IsActive` 13/13 都是 true）。
                        // 内缘 = 中心 ± 半高：上那枚下缘 −180.09（**在屏幕上缘之上 180 px**）、下那枚上缘 1260.09（> 1080）
                        float halfTop = sdTop.y * 0.5f, halfBot = sdBot.y * 0.5f;   // 设计 px
                        float edgeTop = pcTop.y + halfTop, edgeBot = pcBot.y - halfBot;
                        Check(topQ.gameObject.activeSelf && botQ.gameObject.activeSelf,
                              "★ 两枚都**没有被关掉**（原版 `m_IsActive` 13/13 全是 true、全库没有任何代码开关它们）——"
                            + " 看不见是**几何**造成的，⛔ 不是加了一个「藏起来」的开关");
                        Check(edgeTop < 0f && Mathf.Abs(edgeTop + 180.0899658203125f) < 0.5f,
                              "★ 上面那枚**整块在屏幕之上**（内缘落在 −180.09 px，= 540 − 720.09）——"
                            + $" 实得内缘 {edgeTop:F3} px（负 = 在屏幕上缘之外）");
                        Check(edgeBot > 1080f && Mathf.Abs(edgeBot - 1260.0899658203125f) < 0.5f,
                              "★ 下面那枚**整块在屏幕之下**（内缘 1260.09 px > 1080）——"
                            + $" 实得内缘 {edgeBot:F3} px");
                        // 6) 不接命中 = 原版 `m_RaycastTarget = 0`。uGUI 档**有真的射线系统** ⇒ 直接读 `Image.raycastTarget`。
                        //    （⛔ 旧那半条「身上没有 Collider」是**世界档**的替代判别 —— uGUI 的指针判定不看 Collider）
                        Check(imgTop != null && imgBot != null && !imgTop.raycastTarget && !imgBot.raycastTarget,
                              "★ 两枚**都不接命中**（原版 `m_RaycastTarget = 0`）—— uGUI 档读 `Image.raycastTarget`（应 false）"
                            + $"；实得 {(imgTop == null ? "无 Image" : imgTop.raycastTarget.ToString())}"
                            + $" / {(imgBot == null ? "无 Image" : imgBot.raycastTarget.ToString())}");
                    }
                }

                // ---- 2a-② `ScreenAspectRatioController`（原版挂 `BattlePrefab`）----
                Debug.Log(P + "   --- §8b 2a：`ScreenAspectRatioController` ---");
                {
                    var aspCtl = drv.AspectRatioController;
                    Check(aspCtl != null, "★ 比例控制器建出来了（原版这一件挂在 `BattlePrefab` 上）");
                    if (aspCtl != null)
                    {
                        // 🔴 **两档要有区分**：原版 ctor 出厂值 (1.3333334 / 2.4444447) ≠ **场景那一档**
                        //    (`MonoBehaviour_5148.json` 的 1.3333330154418945 / 2.444443941116333) ——
                        //    我们取**场景那一档**（同 `BattleCameraSreenSize.sensorSizeXBigScreen` 那一族）
                        const float MINASP = 1.3333330154418945f, MAXASP = 2.444443941116333f;
                        Check(Mathf.Abs(aspCtl.MinAspectRatioTest - MINASP) < 1e-7f
                           && Mathf.Abs(aspCtl.MaxAspectRatioTest - MAXASP) < 1e-7f
                           && Mathf.Abs(aspCtl.MinAspectRatioTest - 1.3333334f) > 1e-7f
                           && Mathf.Abs(aspCtl.MaxAspectRatioTest - 2.4444447f) > 1e-7f,
                              $"★ 取的是**场景那一档** min {aspCtl.MinAspectRatioTest:F9} / max {aspCtl.MaxAspectRatioTest:F9}"
                            + "（`MonoBehaviour_5148.json`）—— ⛔ **不是** ctor 那一档 1.3333334 / 2.4444447");

                        // 两台相机都写、**顺序照原版** `[Camera_1461(3D), Camera_1462(UI)]`
                        var tcs = aspCtl.TargetCameras;
                        string cam0Name = (tcs != null && tcs.Length > 0 && tcs[0] != null) ? tcs[0].name : "null";
                        string cam1Name = (tcs != null && tcs.Length > 1 && tcs[1] != null) ? tcs[1].name : "null";
                        Check(aspCtl.TargetCameraCount == 2 && tcs != null && tcs.Length == 2
                              && tcs[0] == drv.boardCam && tcs[1] == cam,
                              $"★ 两台相机都写、顺序照原版：`[{cam0Name}, {cam1Name}]`"
                            + "（原版 = `[Camera_1461(3D BoardCamera), Camera_1462(UI 相机)]`）");
                        // 两条订阅（分辨率信号 + `beginCameraRendering`）—— 批处理里 `GL.Clear` 那条路验不了，
                        // 能钉的只有「钩子接没接」（原版 `Start` 里那三句）
                        Check(aspCtl.IsAttachedForTest && aspCtl.IsRenderingHookedForTest,
                              "★ 两条订阅都挂上了（= 原版 `Start` 的②③：分辨率变了要重算 + 每台相机开渲之前清一次色）");

                        // 纯函数四档：16:9 / 21:9 / **4:3** ⇒ 整幅；22.5:9 ⇒ 左右黑边；5:4 ⇒ 上下黑边
                        var v169 = ScreenAspectRatioController.ComputeViewport(16f / 9f, MINASP, MAXASP);
                        var v219 = ScreenAspectRatioController.ComputeViewport(21f / 9f, MINASP, MAXASP);
                        var v43 = ScreenAspectRatioController.ComputeViewport(4f / 3f, MINASP, MAXASP);
                        bool IsFull(Rect r)
                        {
                            return Mathf.Abs(r.x) < 1e-6f && Mathf.Abs(r.y) < 1e-6f
                                && Mathf.Abs(r.width - 1f) < 1e-6f && Mathf.Abs(r.height - 1f) < 1e-6f;
                        }
                        // ⚠️ 4:3 = `1.333333373`，而场景 min = `1.333333015` ⇒ **4:3 比 min 大 3.6e-7**
                        //    （余量极小 —— 这就是「别假设窄屏那一支一定恒等」的由来：真窄过 4:3 就该出黑边）
                        Check(IsFull(v169) && IsFull(v219) && IsFull(v43),
                              "★ 16:9 / 21:9 / 4:3 三档都落在 [min,max] **之内** ⇒ 视口写**整幅**（黑边不出现）——"
                            + $" 实得 {v169} / {v219} / {v43}（⚠️ 4:3 = {4f / 3f:F9} 只比 min {MINASP:F9} 大 3.6e-7）");

                        var vPill = ScreenAspectRatioController.ComputeViewport(2.5f, MINASP, MAXASP);      // 22.5:9
                        Check(vPill.x > 0f && Mathf.Abs(vPill.y) < 1e-6f && Mathf.Abs(vPill.height - 1f) < 1e-6f
                              && Mathf.Abs(vPill.x - 0.011111199855804443f) < 1e-6f
                              && Mathf.Abs(vPill.width - 0.9777776002883911f) < 1e-6f,
                              "★ 宽过 max（22.5:9）⇒ **左右**黑边：f = (1 − max/aspect)/2 = 0.0111112、宽 0.9777776 ——"
                            + $" 实得 {vPill}（⚠️ 分子是 `1 − max/aspect`；⛔ 取另一支会整条反过来）");
                        var vLetter = ScreenAspectRatioController.ComputeViewport(1.25f, MINASP, MAXASP);    // 5:4
                        Check(vLetter.y > 0f && Mathf.Abs(vLetter.x) < 1e-6f && Mathf.Abs(vLetter.width - 1f) < 1e-6f
                              && Mathf.Abs(vLetter.y - 0.0333331823348999f) < 1e-6f
                              && Mathf.Abs(vLetter.height - 0.9333336353302002f) < 1e-6f,
                              "★ 窄过 min（5:4）⇒ **上下**黑边：f = (min/aspect − 1)/2 = 0.0333332、高 0.9333336 ——"
                            + $" 实得 {vLetter}（⚠️ 这一支的分子是 `min/aspect − 1`，与上面那一支**不是**同一个式子）");

                        // 实况那条路：算一次 + 写一台/两台 + 把「清一次色」的标志置起来
                        // ⚠️ 批处理没有帧循环 ⇒ `beginCameraRendering` 只在**显式渲图**时才抬（`Shot` 会）⇒
                        //    ⛔ 别断「标志恒 true」，而是**当场调一次**再读它。
                        int nAdj = aspCtl.AdjustedCount, nSet = aspCtl.SetCamerasRectCount;
                        aspCtl.AdjustCameraViewport();
                        Check(aspCtl.AdjustedCount == nAdj + 1 && aspCtl.SetCamerasRectCount == nSet + 1
                              && aspCtl.ClearPendingForTest,
                              "★ 调一次 `AdjustCameraViewport` ⇒ 算一次 + 写一次 rect + 把标志置起来"
                            + "（原版 `__SetCamerasRect.c` 第一句就是**无条件**置 1，整幅那一档也置）");

                        float liveAspect = Screen.width / Mathf.Max(1f, (float)Screen.height);
                        var liveVp = aspCtl.CurrentViewport;
                        var wantVp = ScreenAspectRatioController.ComputeViewport(liveAspect, MINASP, MAXASP);
                        Check(Mathf.Abs(liveVp.x - wantVp.x) < 1e-6f && Mathf.Abs(liveVp.y - wantVp.y) < 1e-6f
                              && Mathf.Abs(liveVp.width - wantVp.width) < 1e-6f
                              && Mathf.Abs(liveVp.height - wantVp.height) < 1e-6f,
                              "★ 实况那条路与纯函数**同一个结果**（= 全工程只有一处公式）——"
                            + $" 写下去的是 {liveVp}、纯函数算的是 {wantVp}");
                        // ★ 前提 + 它的「藏」：批处理这一档的比例 ≥ min ⇒ 写回整幅（= 与原版 16:9 下的观感一致）
                        Check(liveAspect >= MINASP,
                              $"★ 前提：批处理这一档的实况比例 {liveAspect:F9} ≥ min {MINASP:F9}（余量只有 4e-7 ——"
                            + " 哪天批处理分辨率窄过 4:3，下面那条「整幅」的期望值就要跟着改，那时黑边是**该出现**的）");
                        Check(Mathf.Abs(liveVp.x) < 1e-6f && Mathf.Abs(liveVp.y) < 1e-6f
                              && Mathf.Abs(liveVp.width - 1f) < 1e-6f && Mathf.Abs(liveVp.height - 1f) < 1e-6f,
                              $"★ 比例在 [min,max] 之内 ⇒ 视口写回**整幅**（这就是它的「藏」；原版这一档也写 `(0,0,1,1)`）"
                            + $" —— 实得 {liveVp}");
                        if (tcs != null && tcs.Length == 2 && tcs[0] != null && tcs[1] != null)
                            Check(Mathf.Abs(tcs[0].rect.x) < 1e-6f && Mathf.Abs(tcs[0].rect.width - 1f) < 1e-6f
                               && Mathf.Abs(tcs[1].rect.x) < 1e-6f && Mathf.Abs(tcs[1].rect.width - 1f) < 1e-6f,
                                  "★ ……而且**真的写到了两台相机的 `Camera.rect` 上**（读回真值，⛔ 不读那个记账位）——"
                                + $" 3D {tcs[0].rect} / UI {tcs[1].rect}");
                    }
                }

                // ---- 2b 错误/疲劳横幅（原版 `UI Error Message Controller (MUST BE ENABLED)`）----
                Debug.Log(P + "   --- §8b 2b：错误横幅 ---");
                {
                    var errBan = drv.ErrorBanner;
                    Check(errBan != null, "★ 错误横幅建出来了（原版 `UI Error Message Controller (MUST BE ENABLED)`）");
                    if (errBan != null)
                    {
                        // ① 建件 = 原版 `Awake`：模板留在容器里 + 克隆 5 条
                        //    ⚠️ 「建出来时**全关**」这一刻验不了 —— 前面几节（打完一整局那几节）可能已经弹过
                        //       **真疲劳**横幅 ⇒ 池非空。⇒ 改成「先收干净、再看**节点**」：`HideAll` 就是
                        //       原版 `OnKill` 那一支的等价物（「关」要关在 `activeSelf` 上，⛔ 不是只改记账位）。
                        int nShownIn = errBan.ShowCount;      // 前面几节弹过几条 ⇒ 下面一律按**增量**断
                        errBan.HideAll();
                        var containT = errBan.transform.Find("Container");
                        int nItemNodes = 0, nActiveNodes = 0;
                        if (containT != null)
                            for (int ci = 1; ci < containT.childCount; ci++)   // [0] = 模板
                            {
                                nItemNodes++;
                                if (containT.GetChild(ci).gameObject.activeSelf) nActiveNodes++;
                            }
                        Check(errBan.ItemCount == 5 && errBan.TemplateBuilt && errBan.gameObject.activeInHierarchy
                              && nItemNodes == 5,
                              "★ 池 = **5 条**（原版 `NUMBER_OF_MESSAGES`）+ 建在 HUD 根下 ——"
                            + $" 实得池 {errBan.ItemCount} / 容器下 {nItemNodes} 个 item 节点");
                        Check(errBan.VisibleCount == 0 && nActiveNodes == 0,
                              "★ `HideAll` 把每一条**真的关在节点上**了（记账位归零不算数 —— 要看 `activeSelf`）——"
                            + $" 实得记账 {errBan.VisibleCount} / 节点还亮着 {nActiveNodes}");
                        var tmplRef = errBan.transform.Find("Container/Error Mensage_Ref");
                        Check(tmplRef != null && !tmplRef.gameObject.activeSelf,
                              "★ 模板 `Error Mensage_Ref` **留在容器里但关着**（原版 `Awake` 第一句 `SetActive(false)`）");

                        // ② 原版参数：参考串 `ERROR MESSAGE CONTENT` 量出来的那一组底条 870.97998046875 × 60.849998474121094
                        //    🔴 它**不是固定尺寸**（真规则是 Hug，见 ⑤）—— 拿它当固定值会让长文案溢出底条
                        var tbs = errBan.TemplateBarSizePx;
                        Check(Mathf.Abs(tbs.x - 870.97998046875f) < 0.5f
                           && Mathf.Abs(tbs.y - 60.849998474121094f) < 0.5f,
                              "★ 模板那条底条 = 原版参考串那一组 **870.98 × 60.85**（`RectTransform_{2989,2942}.json`）——"
                            + $" 实得 {tbs.x:F2}×{tbs.y:F2}");

                        // ③ 分层：世界档 = **渲染队列**（4001/4002，高过日志面板 4000 与 tooltip 3607）；
                        //    uGUI 档 = **兄弟序**（uGUI **没有**独立渲染队列 —— `Label.RenderQueue` uGUI 档恒回 −1，
                        //    见 `Label.cs:205-219`；层级由父件的子件序表达：文字建在底条**之后** ⇒ 后绘、盖在上）。
                        // 🔴 **2026-10-17（`BSC62` · W4）**：原来只断队列。`T09` 后横幅迁到画布上
                        //    （底条是 `Image` 不是 `ImageQuad` ⇒ `GetComponentsInChildren<ImageQuad>` 空、`qMin` 停在
                        //    `int.MaxValue`；文字是 uGUI `Label` 恒 −1）⇒ 读回哨兵。⇒ 按档读。
                        if (tmplRef != null)
                        {
                            if (errBan.IsUgui)
                            {
                                var barRT = tmplRef.Find("Background");
                                var txtRT = tmplRef.Find("ErrorMesage Text");
                                int iBar = barRT != null ? barRT.GetSiblingIndex() : -1;
                                int iTxt = txtRT != null ? txtRT.GetSiblingIndex() : -1;
                                Check(barRT != null && txtRT != null && iTxt > iBar,
                                      $"★ 分层（**兄弟序**，uGUI 无独立渲染队列）：底条 idx {iBar} / 文字 idx {iTxt}"
                                    + "（文字建在底条之后 ⇒ 后绘、盖在上面 —— 等价于原版那个 `SortingOrder = 1` 的独立 overlay）");
                            }
                            else
                            {
                                var qParts = tmplRef.GetComponentsInChildren<ImageQuad>(true);
                                int qMin = int.MaxValue, qMax = int.MinValue;
                                for (int qi = 0; qi < qParts.Length; qi++)
                                {
                                    if (qParts[qi] == null) continue;
                                    qMin = Mathf.Min(qMin, qParts[qi].RenderQueue);
                                    qMax = Mathf.Max(qMax, qParts[qi].RenderQueue);
                                }
                                var labRef = tmplRef.GetComponentInChildren<Label>(true);
                                Check(qParts.Length > 0 && qMin == 4001 && qMax == 4001
                                      && labRef != null && labRef.RenderQueue == 4002,
                                      $"★ 分层（**队列**，不是 z）：底条 {qMin} / 文字 {(labRef == null ? -1 : labRef.RenderQueue)}"
                                    + "（期望 4001 / 4002 —— 都要高过日志面板的 4000 与 tooltip 的 3607）");
                            }
                        }

                        // ④ 弹一条（走**生产口** `ShowError`）。⚠️ **用哪一条**由 `currentMessageIndex` 说了算
                        //    ⇒ 下面一律拿**它当场给的那个下标** `idxA` 去读，⛔ 别假设是 0（前面几节可能弹过真横幅）
                        int idxA = errBan.CurrentIndex;
                        string fat5 = BattleDriver.DamageFatigueText(true, 5);
                        errBan.ShowError(fat5);
                        Check(errBan.ShowCount == nShownIn + 1 && errBan.CurrentIndex == (idxA + 1) % 5
                              && errBan.ActiveOf(idxA) && errBan.VisibleCount == 1,
                              $"★ 弹一条：亮着 1 条 / 池游标 {idxA} → {errBan.CurrentIndex}"
                            + "（= 原版 `currentMessageIndex = ++i; if (4 < i) i = 0` 那一步）");
                        Check(Mathf.Abs(errBan.ScaleOf(idxA) - 0.3f) < 1e-3f,
                              "★ 入场从 **0.3×** 起步（原版 `appearScaleFromMultiplier` = 0.3）——"
                            + $" 实得 {errBan.ScaleOf(idxA):F4}（读的是节点上真值 `localScale.x`）");
                        var tc0 = errBan.TextColorOf(idxA);
                        Check(Mathf.Abs(tc0.r - 0.8f) < 1e-3f && tc0.g < 1e-3f && tc0.b < 1e-3f
                              && Mathf.Abs(tc0.a - 1f) < 1e-3f,
                              $"★ 文字 = 原版 `errorColor` **(0.8,0,0,1)** 且 α=1（实得 {tc0}）"
                            + " —— ⛔ 不是 TMP 自己序列化的那个 0.8019（那个数会被 `Show` 盖掉）");
                        Check(errBan.TextOf(idxA) == fat5 && !fat5.Contains("{0}") && !fat5.Contains("Battle/")
                              && fat5.Contains("5"),
                              $"★ 文字 = 疲劳文案**且 `{{0}}` 已填数**：「{errBan.TextOf(idxA)}」");
                        // 🆕 **2026-10-19（战斗线 `T17`）**：两条疲劳键**都在表里**
                        //   （原来 `Battle/Tips/DamageFatigueEnemy` 一直不在 ⇒ 对手那侧永远走兜底句）；
                        //   期望值用**官方两列原文**填数，⛔ 不拿 `Loc.T` 当期望（那是自证）。
                        {
                            string fatFoe = BattleDriver.DamageFatigueText(false, 2);
                            Check(Loc.HasEntry("Battle/Tips/DamageFatigue")
                                  && Loc.HasEntry("Battle/Tips/DamageFatigueEnemy"),
                                  "★ 两条疲劳键都在 `Loc` 表里（我方 + 对手；对手那条本轮才补）");
                            Check(fatFoe == "敌人的卡组已空。你的敌人因疲劳受到2点伤害。"
                               || fatFoe == "Enemy deck is empty. Your enemy takes 2 damage from fatigue.",
                                  $"★ 对手疲劳文案 = 官方值且 `{{0}}` 已填：「{fatFoe}」"
                                + "（⛔ 不该是我们写的兜底句「对手牌库已空 —— 其督军受到 2 点疲劳伤害」）");
                        }
                        Shot(cam, "34_错误横幅");

                        // ⑤ 底条是 **Hug**（原版 `ContentSizeFitter` PreferredSize + 内层 layout padding）
                        //    ⇒ 断**两条关系**，⛔ **不断 870.98 × 60.85**（那是参考串那一组；写死它中文/长文案会溢出）
                        var itemNodeA = (containT != null && containT.childCount > idxA + 1)
                                        ? containT.GetChild(idxA + 1) : null;   // 子件序：[0] = 模板 ⇒ 第 i 条 = [i+1]
                        var lab0 = itemNodeA != null ? itemNodeA.GetComponentInChildren<Label>(true) : null;
                        var barSz0 = errBan.BarSizeOf(idxA);
                        if (lab0 == null)
                            Check(false, "找不到那一条的 `ErrorMesage Text` 节点 ⇒ 下面两条 Hug 关系验不了");
                        else
                        {
                            // 🔴 **2026-10-17（`BSC62` · W4）：读口按档取因子。** `T09` 后横幅在画布上 ⇒
                            //   `Label.WorldW/H` **已经是设计 px**（`Label.cs:9-10`：uGUI 档单位 = 设计 px）。
                            //   原来硬编码 `* 108f` ⇒ 把一个 px 又乘 108（实得 119911 / 9824）。
                            //   生产侧 `ErrorMessageBanner.cs:649` 就是 `unitPx = _ugui ? 1f : 108f` ⇒ 断言照抄它。
                            float unitPx0 = errBan.IsUgui ? 1f : 108f;
                            float txtW0 = lab0.WorldW * unitPx0, txtH0 = lab0.WorldH * unitPx0;
                            Check(Mathf.Abs(barSz0.x - (txtW0 + 240f)) < 1.0f,
                                  "★ **Hug**：底条宽 = 文字宽 + 240（原版内层 `padding L120 + R120`）——"
                                + $" 实得 底条 {barSz0.x:F2} − 文字 {txtW0:F2} = {barSz0.x - txtW0:F2} px"
                                + "（把底条写死成 870.98 就红）");
                            Check(barSz0.y > txtH0
                               && Mathf.Abs(barSz0.y - (Mathf.Max(56.849998474121094f, txtH0) + 4f)) < 1.0f,
                                  "★ **Hug**：底条高 = max(56.85, 文字高) + 4（原版 `padding T4/B0`；56.85 = 原版字体的单行高）——"
                                + $" 实得 文字高 {txtH0:F2} ⇒ 底条 {barSz0.y:F2}（⛔ 不许矮过文字：那会被切）");
                        }

                        // ⑥ 布局 = 原版那套 `VerticalLayoutGroup`（LowerCenter）**算出来的**位置，不是存档值
                        SettleShake();
                        var cItem0 = errBan.ItemCenterPxOf(idxA);
                        Check(Mathf.Abs(cItem0.x - 960f) < 0.25f && Mathf.Abs(cItem0.y - 510.23974609375f) < 0.25f,
                              "★ 单条亮着时中心 = **(960, 510.23974609375)** px（y 从上）—— 布局组算出来的那个值，"
                            + "⛔ 不是 `RectTransform_2823.json` 里的存档 `ap (960.35, −241.29)`"
                            + $"（按存档值算是 525.24，**差 15 px**）—— 实得 ({cItem0.x:F3},{cItem0.y:F3})");
                        // 再弹一条 ⇒ **子件序里靠后**的那条恒在 510.24、靠前的那条**高 80 px**（= 项高 80.00）
                        int idxB = errBan.CurrentIndex;
                        errBan.ShowError(BattleDriver.DamageFatigueText(false, 2));
                        SettleShake();
                        int idxLo = Mathf.Min(idxA, idxB), idxHi = Mathf.Max(idxA, idxB);
                        var cEarlier = errBan.ItemCenterPxOf(idxLo);      // 子件序里靠前 ⇒ 更靠上（y 更小）
                        var cLater = errBan.ItemCenterPxOf(idxHi);
                        Check(Mathf.Abs(cEarlier.y - 430.23974609375f) < 0.25f
                              && Mathf.Abs(cLater.y - 510.23974609375f) < 0.25f
                              && Mathf.Abs(cEarlier.x - 960f) < 0.25f && Mathf.Abs(cLater.x - 960f) < 0.25f
                              && errBan.VisibleCount == 2 && errBan.CurrentIndex == (idxB + 1) % 5,
                              "★ 堆叠（LowerCenter ⇒ 从容器底往上堆）：子件序**靠后**的那条还在 510.23974609375、"
                            + "靠前的那条**上移 80 px**（= 项高 80.00）——"
                            + $" 实得 [{cEarlier.y:F3}, {cLater.y:F3}]（期望 [430.24, 510.24]）");

                        // ⑦ 轮转：再弹 3 次 ⇒ 一共 5 次 = **整整一圈**（原版 `currentMessageIndex = ++i; if (4 < i) i = 0`）
                        for (int k = 0; k < 3; k++) errBan.ShowError("轮转用例 " + (k + 3));
                        Check(errBan.ShowCount == nShownIn + 5 && errBan.CurrentIndex == idxA
                              && errBan.VisibleCount == 5,
                              $"★ 连弹 5 次 = 一整圈 ⇒ 游标**回到起点 {idxA}**、5 条**全亮**"
                            + $"（一共弹了 {errBan.ShowCount} 条 / 亮着 {errBan.VisibleCount} / 游标 {errBan.CurrentIndex}）");

                        // 🔴🔴 **2026-10-16（`T09` 批 2 · `PopUps` 组）：这一颗已翻到 uGUI 子画布。**
                        //   判据（原版宿主与档位）→ `资料/普查产出_1016战斗判据/T09c_面板到原版宿主映射.md` §一；
                        //   建法口径 → `资料/任务线/战斗线/任务/T09_整层换uGUI.md` §五·补⑨。
                        //   ⚠️ 这一组是**本批真正的自证** —— 下面那些行为断言只证明「算出来的数还对」。
                        var cvErr = HudCanvas.SubCanvas("UI Error Message Controller Canvas");
                        Check(cvErr != null && cvErr.overrideSorting
                              && cvErr.sortingLayerID == HudCanvas.SortingLayer.PopUps
                              && cvErr.sortingOrder == 1,
                              "★ `T09` 批 2：错误横幅的子画布 = `overrideSorting` + **`PopUps`** + order **1**"
                            + "（原版 `UI Error Message Controller (MUST BE ENABLED)` 就是这一档）");
                        Check(cvErr != null && cvErr.GetComponent<CanvasScaler>() == null,
                              "★ ……而且**不带 `CanvasScaler`**（原版全场景只有根上一个；子画布加了会**二次缩放**）");
                        Check(errBan.IsUgui,
                              "★ ……**战斗侧真的走 uGUI 档**｜🧨 宿主没传下去（或退回了世界档）⇒ 本条红："
                            + "那一来它既在**世界空间**自证上面的断言，又**盖不住同组的其它面板**");

                        // ⑧ 时间轴（等价物 C：原版靠 DOTween 帧循环，我们手推）
                        //    入场 0.15 → **停到 2.0** → 淡出 **0.25** → 关自身；⚠️ 中间 ⛔ 不许 `Step`（那个泵也会推它）
                        float aBefore = errBan.TextColorOf(idxA).a;
                        errBan.Advance(2.05f);
                        float aFade = errBan.TextColorOf(idxA).a;
                        Check(aBefore > 0.99f && aFade > 0.05f && aFade < 0.95f && errBan.ActiveOf(idxA),
                              "★ 过 **2.0 s 才开始淡出**（原版 `timeToStartFading` = 2.0）——"
                            + $" α {aBefore:F3} → {aFade:F3}（2.05 s 那一刻应当 ≈0.64；永不淡出就恒 1.000 ⇒ 红）");
                        Check(Mathf.Abs(errBan.ScaleOf(idxA) - 1f) < 1e-3f,
                              $"★ ……而缩放入场（0.15 s）早已结束 ⇒ 现在是 1×（实得 {errBan.ScaleOf(idxA):F3}）");
                        errBan.Advance(0.1f);
                        float aFade2 = errBan.TextColorOf(idxA).a;
                        Check(aFade2 < aFade - 0.02f && aFade2 > 0f,
                              $"★ 淡出是**单调往下**的（原版 `timeToFade` = 0.25 s）—— α {aFade:F3} → {aFade2:F3}");
                        errBan.Advance(0.2f);          // 累计 2.35 s ≥ 2.25 s = 生命终点
                        int nStillOn = 0;
                        if (containT != null)
                            for (int ci = 1; ci < containT.childCount; ci++)
                                if (containT.GetChild(ci).gameObject.activeSelf) nStillOn++;
                        Check(!errBan.ActiveOf(idxA) && errBan.VisibleCount == 0 && nStillOn == 0,
                              "★ 演完（0.15 + 2.0 + 0.25 = **2.25 s**）整池都收起来（原版 `OnComplete` ⇒ `SetActive(false)`）——"
                            + $" 实得 亮着 {errBan.VisibleCount} / **节点**还亮着 {nStillOn} /"
                            + $" 第 {idxA} 条记账 {errBan.ActiveOf(idxA)}");

                        // ⑨ **疲劳触发**（2b 的入口）：`EvtKind.Hit` + 督军槽(4) + `Amount == 疲劳值` + 那一方**牌库空**
                        //    ⇒ 弹一条；`Amount` 换成别的值 ⇒ 不弹（两态）。
                        //    ⚠️ 本机那一方是**绝对座位**（`MyIndex`），原版两条键就是按这个分的。
                        var psMe = drv.Ctx != null ? drv.Ctx.Players[drv.MyIndex] : null;
                        if (psMe == null) Check(false, "拿不到本机那一方 ⇒ 疲劳触发那两条验不了");
                        else
                        {
                            var savedDeck = new List<CardInstance>(psMe.Deck);
                            int savedFatigue = psMe.Fatigue;
                            psMe.Deck.Clear();                       // 「牌库空」是那道闸之一
                            // 先把记账位复位（语义：那一方的疲劳回 0 = 新一局 ⇒ 记账跟着清）。这条合成事件
                            // 的数值**刻意**对不上 ⇒ 它被数值那道闸挡下，只走到复位那一句。
                            psMe.Fatigue = 0;
                            drv.NoteFatigueBannersForTest(new List<BattleEvent> {
                                new BattleEvent { Kind = EvtKind.Hit, Player = drv.MyIndex,
                                                  Slot = BoardSpec.WarlordSlot, Amount = 1 } });
                            Check(drv.FatigueShownForTest(drv.MyIndex) == 0,
                                  "★ 那一方的疲劳回 0 ⇒ **记账位跟着清**（「新一局」那条语义）");
                            psMe.Fatigue = 4;
                            int nShown0 = errBan.ShowCount;
                            drv.NoteFatigueBannersForTest(new List<BattleEvent> {
                                new BattleEvent { Kind = EvtKind.Hit, Player = drv.MyIndex,
                                                  Slot = BoardSpec.WarlordSlot, Amount = 4 } });
                            Check(errBan.ShowCount == nShown0 + 1 && drv.FatigueShownForTest(drv.MyIndex) == 4,
                                  $"★ 疲劳那一条弹出来了（弹了 {errBan.ShowCount - nShown0} 条 / 记账 "
                                + $"{drv.FatigueShownForTest(drv.MyIndex)}）—— 判据 = `Hit` + **督军槽 4** + "
                                + "`Amount == 疲劳值` + **牌库空**（我们引擎把疲劳并进了 `Hit`，那七道闸在 `NoteFatigueBanners`）");
                            int nShown1 = errBan.ShowCount;
                            drv.NoteFatigueBannersForTest(new List<BattleEvent> {
                                new BattleEvent { Kind = EvtKind.Hit, Player = drv.MyIndex,
                                                  Slot = BoardSpec.WarlordSlot, Amount = 9 } });
                            Check(errBan.ShowCount == nShown1,
                                  "★ 反例：`Amount` ≠ 那一方的疲劳值 ⇒ **不弹**（把数值那道闸写松就红）");
                            psMe.Deck.Clear();
                            psMe.Deck.AddRange(savedDeck);           // 还原（后面几节还要用这一局）
                            psMe.Fatigue = 0;
                            drv.NoteFatigueBannersForTest(new List<BattleEvent> {
                                new BattleEvent { Kind = EvtKind.Hit, Player = drv.MyIndex,
                                                  Slot = BoardSpec.WarlordSlot, Amount = 1 } });
                            psMe.Fatigue = savedFatigue;             // 收尾：把记账位也收回去（⛔ 别留脏账）
                            errBan.Advance(2.3f);                    // 收尾：把它演完，别留在后面几节的截图里
                        }

                        // ⑩ 文案的两态（`Battle/Tips/*` 那族键本地**一个 value 都没有** ⇒ 今天走兜底句）
                        const string keyInTable = "Battle/HUD/TargetsAvailable";   // 表里确实有这条（`Loc.cs` 实读）
                        Check(Loc.HasEntry(keyInTable), $"★ 前提：词条 `{keyInTable}` 在语言表里");
                        string viaTerm = BattleDriver.DamageFatigueTextWithKey(keyInTable, true, 7);
                        Check(viaTerm != fat5 && viaTerm.Contains("7") && !viaTerm.Contains("{0}")
                              && !viaTerm.Contains("Battle/"),
                              $"★ 键**在表里** ⇒ 走**词条**（`{keyInTable}` → 「{viaTerm}」）：`{{0}}` 已填数、⛔ 不印键名");
                        string viaFallback = BattleDriver.DamageFatigueTextWithKey(
                                                 "Battle/Tips/__SelftestNotInTable__", true, 7);
                        Check(!Loc.HasEntry("Battle/Tips/__SelftestNotInTable__") && viaFallback != viaTerm
                              && viaFallback.Contains("7") && !viaFallback.Contains("{0}")
                              && !viaFallback.Contains("Battle/"),
                              $"★ 键**不在表里** ⇒ 走**兜底句**（「{viaFallback}」）：⛔ 既不印键名、也不留 `{{0}}`"
                            + "（`Battle/Tips/*` 本地无 value ⇒ 今天实际走的就是这一档）");

                        // ============================================================
                        //  🆕 2026-10-20（W57 · 战斗线 `T09` 步骤 A3-a）：错误横幅的「关闭」输入
                        //
                        //  🔴 **A3-a 的任务书假设「关闭行为在 `BattleDriver` 里，改成 `Button` 最简单」——
                        //  现核【不成立】**。原版这一棵**没有任何点击件**：
                        //    · 模板 `Error Mensage_Ref`（GO 632）= `RectTransform` + `CanvasGroup` + `UIErrorMessageItem`；
                        //      `Background`（GO 477）= RT + CanvasRenderer + Image + HorizontalLayoutGroup + ContentSizeFitter
                        //      ⇒ **没有 Button / EventTrigger / Pointer 接口**；
                        //    · `Background` 的 Image（`MB 5101`）与文字的 TMP（`MB 3740`）`m_RaycastTarget` **都是 0**；
                        //    · `UIErrorMessageItem` 的方法表只有 `Show / LayoutRefresh / Toggle(bool)`（`Toggle` = `SetActive(参数)`）；
                        //    · 运行时 dump（`runtime_ui_dump_Battle_Arena_1.tsv:1172-1191`）整棵树只有 `RT/IMG/TXT`。
                        //  ⇒ 唯一的「关」= 时间轴 `OnComplete → SetActive(false)`（我们的等价物 = `Advance`，
                        //     由 `BattleDriver.AdvanceTimeline` 泵推；`_errorBanner` 只有 Create / ShowError / Advance 三个调用点）。
                        //  ⇒ 给它补「点一下关掉」= **原版没有的新行为**（⛔ 不做；判据 → `ErrorMessageBanner.cs` 文件头 ⑫）。
                        //  本组钉的就是这条事实；⛔ 它**不是**「uGUI 点击关闭」，因为那条在原版不存在。
                        // ============================================================
                        Debug.Log(P + "   --- W57/T09-A3a：错误横幅的关闭输入（原版无点击）---");
                        {
                            // ① 前提：真的是 uGUI 件、父链就是 `PopUps`/1 那块子画布、而且画布有射线面。
                            Check(errBan.IsUgui && cvErr != null && errBan.transform.parent == cvErr.transform
                                  && cvErr.GetComponent<GraphicRaycaster>() != null,
                                  "★ T09-A3a①：横幅是 **uGUI 件**、父链 = `UI Error Message Controller Canvas`、"
                                + "那块画布有 `GraphicRaycaster`"
                                + $"（IsUgui={errBan.IsUgui} · 父={(errBan.transform.parent != null ? errBan.transform.parent.name : "<null>")}"
                                + $" · 射线器={(cvErr != null && cvErr.GetComponent<GraphicRaycaster>() != null)})"
                                + "｜🧨 `BuildErrorBanner` 退回世界档 / 子画布没建 ⇒ 红");

                            // ② 原版没有点击件：两层都不是射线靶、整棵层级没有点击处理器。
                            errBan.HideAll();
                            int idxA3 = errBan.CurrentIndex;
                            errBan.ShowError("T09-A3a 点击不关闭");
                            var tmplBgA3 = tmplRef != null ? tmplRef.Find("Background") : null;
                            var tmplBgImgA3 = tmplBgA3 != null ? tmplBgA3.GetComponent<Image>() : null;
                            var tmplTxtA3 = tmplRef != null ? tmplRef.Find("ErrorMesage Text") : null;
                            bool tmplTextRtA3 = false;
                            if (tmplTxtA3 != null)
                            {
                                var tgA3 = tmplTxtA3.GetComponentsInChildren<Graphic>(true);
                                for (int k = 0; k < tgA3.Length; k++)
                                    if (tgA3[k] != null && tgA3[k].raycastTarget) tmplTextRtA3 = true;
                            }
                            Check(tmplBgImgA3 != null && !tmplBgImgA3.raycastTarget && !tmplTextRtA3,
                                  "★ T09-A3a②：模板的**底条 `Image`** 与**文字 TMP** 都不是射线靶"
                                + "（原版 `MB 5101` / `MB 3740` 的 `m_RaycastTarget = 0`）"
                                + $"（Image.raycastTarget={(tmplBgImgA3 != null ? tmplBgImgA3.raycastTarget.ToString() : "<无>")}"
                                + $" · 文字={tmplTextRtA3}）"
                                + "｜🧨 把它置 true（= 挂 `BattleHudButton` 的第一步）⇒ 本条 + ③ + ④ 一起红");
                            Check(!errBan.BarRaycastTargetOf(idxA3) && !errBan.TextAnyRaycastTargetOf(idxA3),
                                  "★ T09-A3a②：**亮着的那一条**同样不是射线靶（底条 / 文字）"
                                + $"（底条={errBan.BarRaycastTargetOf(idxA3)} · 文字={errBan.TextAnyRaycastTargetOf(idxA3)}）");
                            Check(errBan.ClickHandlerCountInHierarchy() == 0,
                                  $"★ T09-A3a②：横幅层级里**没有任何点击处理器**（实得 {errBan.ClickHandlerCountInHierarchy()}）"
                                + " —— 原版这一棵一个都没有（`UIErrorMessageItem` 只有 Show / LayoutRefresh / Toggle(bool)）"
                                + "｜🧨 给横幅挂 `BattleHudButton` ⇒ 红");

                            // ③ 几何：在**那条的中心**打射线 ⇒ 一条都不许命中横幅（点击穿过去）。
                            BattleEventSystem.SyncRaycasters();      // 编辑模式补偿（Play 模式是空操作）
                            Canvas.ForceUpdateCanvases();            // `Graphic.depth == -1` 会被 GraphicRaycaster 跳过
                            var esA3 = EventSystem.current != null ? EventSystem.current : BattleEventSystem.Instance;
                            var canvasA3 = HudCanvas.Root;
                            var camA3 = canvasA3 != null ? canvasA3.worldCamera : null;
                            var itemA3 = (containT != null && containT.childCount > idxA3 + 1)
                                         ? containT.GetChild(idxA3 + 1) as RectTransform : null;
                            bool geomA3 = esA3 != null && camA3 != null && itemA3 != null;
                            Check(geomA3,
                                  "★ T09-A3a③（前提）：`EventSystem` / 相机 / 那一条的 `RectTransform` 都取得到"
                                + " —— 取不到就算不出屏幕点（⛔ 不写死 960/540）");
                            if (geomA3)
                            {
                                Vector3 worldC3 = itemA3.TransformPoint(itemA3.rect.center);
                                Vector2 screenC3 = RectTransformUtility.WorldToScreenPoint(camA3, worldC3);
                                var pedA3 = new PointerEventData(esA3) { position = screenC3 };
                                var hitsA3 = new List<RaycastResult>();
                                esA3.RaycastAll(pedA3, hitsA3);
                                bool hitBannerA3 = false;
                                for (int hi = 0; hi < hitsA3.Count; hi++)
                                {
                                    var hgA3 = hitsA3[hi].gameObject;
                                    if (hgA3 != null && hgA3.transform.IsChildOf(errBan.transform)) { hitBannerA3 = true; break; }
                                }
                                Check(!hitBannerA3,
                                      "★ T09-A3a③：在**横幅那条的中心**打射线 ⇒ **一条都不命中横幅**"
                                    + $"（screen=({screenC3.x:F1},{screenC3.y:F1}) · 命中 {hitsA3.Count} 条 · 首中="
                                    + $"{(hitsA3.Count > 0 && hitsA3[0].gameObject != null ? hitsA3[0].gameObject.name : "<无>")}）"
                                    + " —— 原版两层 `m_RaycastTarget = 0`（点击穿过去）"
                                    + "｜🧨 把底条或文字置成射线靶 ⇒ 红（与 ② 配对：无界/恒命中会让别的断言绿、本条红）");

                                // ④ 灭自证：uGUI 点一下（+ 按下/松开）⇒ 不关闭、不快进、不新弹。
                                int visA3 = errBan.VisibleCount, showA3 = errBan.ShowCount;
                                float tA3 = errBan.TimeOf(idxA3);
                                ExecuteEvents.Execute<IPointerClickHandler>(itemA3.gameObject, pedA3, ExecuteEvents.pointerClickHandler);
                                ExecuteEvents.Execute<IPointerDownHandler>(itemA3.gameObject, pedA3, ExecuteEvents.pointerDownHandler);
                                ExecuteEvents.Execute<IPointerUpHandler>(itemA3.gameObject, pedA3, ExecuteEvents.pointerUpHandler);
                                Check(errBan.ActiveOf(idxA3) && errBan.VisibleCount == visA3 && errBan.ShowCount == showA3
                                      && Mathf.Abs(errBan.TimeOf(idxA3) - tA3) < 1e-4f,
                                      "★ T09-A3a④（灭自证）：uGUI **点一下横幅** ⇒ 不关闭、不快进、不新弹"
                                    + $"（亮着 {errBan.VisibleCount} / 弹过 {errBan.ShowCount} / 那条 t {tA3:F4}→{errBan.TimeOf(idxA3):F4}）"
                                    + " —— 原版点了就是什么都不发生（两层 `m_RaycastTarget = 0`）");

                                // ⑤ 关闭只走时间轴，且**恰好一次**：2.24 s 还亮着；+0.02 s 关；继续推不会又关/又弹。
                                errBan.Advance(ErrorMessageBanner.Lifetime - 0.01f);
                                Check(errBan.ActiveOf(idxA3) && errBan.VisibleCount == 1,
                                      $"★ T09-A3a⑤：{ErrorMessageBanner.Lifetime - 0.01f:F2} s（差 0.01 s 到终点）**还亮着**"
                                    + " —— 提前关就红（关闭只由 `Advance` 的时刻表说了算）");
                                errBan.Advance(0.02f);
                                Check(!errBan.ActiveOf(idxA3) && errBan.VisibleCount == 0
                                      && itemA3.gameObject != null && !itemA3.gameObject.activeSelf,
                                      "★ T09-A3a⑤：再过 0.02 s（累计 ≥ 2.25 s）⇒ **关掉**（记账位与**节点**一起关）"
                                    + "（原版 `OnComplete → SetActive(false)`）"
                                    + $"（亮着 {errBan.VisibleCount} / 那条 {(errBan.ActiveOf(idxA3) ? "还亮" : "关了")}"
                                    + $" / 节点 activeSelf={itemA3.gameObject.activeSelf}）");
                                int showA3b = errBan.ShowCount;
                                errBan.Advance(1f);
                                Check(!errBan.ActiveOf(idxA3) && errBan.VisibleCount == 0 && errBan.ShowCount == showA3b,
                                      "★ T09-A3a⑤（灭自证）：关掉之后继续推 ⇒ **不会关了又关 / 又弹一次**"
                                    + $"（亮着 {errBan.VisibleCount} / 弹过 {errBan.ShowCount}，期望 0 / {showA3b}）"
                                    + " —— 「点一次只关一次」的忠实替代：这里根本没有「点」，关的是时间轴那一次");
                            }

                            // ⑥ 源级（结构）：生产代码里没有任何「点击 ⇒ 关」的路径。
                            //    · `BattleDriver.cs`：`_errorBanner` 的**代码行**里不许出现命中 / 沿 / 关闭调用；
                            //    · `ErrorMessageBanner.cs`：不许出现点击接线（`BattleHudButton` / `ExecuteEvents` /
                            //      `OnPointerClick` / `EventTrigger` / `Button`）。
                            {
                                string srcA3a = System.IO.Path.Combine(Application.dataPath,
                                                                       "CardPresentation/Battle/BattleDriver.cs");
                                string srcA3b = System.IO.Path.Combine(Application.dataPath,
                                                                       "CardPresentation/Battle/ErrorMessageBanner.cs");
                                if (!System.IO.File.Exists(srcA3a) || !System.IO.File.Exists(srcA3b))
                                    Check(false, "★ T09-A3a⑥：读得到 `BattleDriver.cs` / `ErrorMessageBanner.cs`"
                                               + "（读不到时下面两条源级断言**等于没验**，所以这里当场红）");
                                else
                                {
                                    var badA3a = new List<string>();
                                    var linesA3a = System.IO.File.ReadAllLines(srcA3a);
                                    for (int i = 0; i < linesA3a.Length; i++)
                                    {
                                        string L = linesA3a[i].TrimStart();
                                        if (L.StartsWith("//")) continue;                      // 注释不算（含 `///`）
                                        if (L.IndexOf("_errorBanner", System.StringComparison.Ordinal) < 0) continue;
                                        if (L.IndexOf("ClickedThisFrame", System.StringComparison.Ordinal) >= 0
                                            || L.IndexOf("ReleasedThisFrame", System.StringComparison.Ordinal) >= 0
                                            || L.IndexOf("HideAll", System.StringComparison.Ordinal) >= 0
                                            || L.IndexOf(".Contains", System.StringComparison.Ordinal) >= 0
                                            || L.IndexOf("Hit", System.StringComparison.Ordinal) >= 0)
                                            badA3a.Add("行" + (i + 1) + ":" + L.Substring(0, Mathf.Min(56, L.Length)));
                                    }
                                    Check(badA3a.Count == 0,
                                          "★ T09-A3a⑥：`BattleDriver.cs` 里 `_errorBanner` **没有任何命中 / 沿 / 关闭**的代码行"
                                        + $"（违规 {badA3a.Count} 处：{string.Join(" | ", badA3a.ToArray())}）"
                                        + " —— 关闭只由 `AdvanceTimeline` 的 `Advance(dt)` 推"
                                        + "｜🧨 给它补一条「点了就关」⇒ 红");
                                    var badA3b = new List<string>();
                                    var linesA3b = System.IO.File.ReadAllLines(srcA3b);
                                    for (int i = 0; i < linesA3b.Length; i++)
                                    {
                                        string L = linesA3b[i].TrimStart();
                                        if (L.StartsWith("//")) continue;
                                        if (L.IndexOf("BattleHudButton", System.StringComparison.Ordinal) >= 0
                                            || L.IndexOf("ExecuteEvents", System.StringComparison.Ordinal) >= 0
                                            || L.IndexOf("OnPointerClick", System.StringComparison.Ordinal) >= 0
                                            || L.IndexOf("EventTrigger", System.StringComparison.Ordinal) >= 0
                                            || L.IndexOf("Button", System.StringComparison.Ordinal) >= 0)
                                            badA3b.Add("行" + (i + 1) + ":" + L.Substring(0, Mathf.Min(56, L.Length)));
                                    }
                                    Check(badA3b.Count == 0,
                                          "★ T09-A3a⑥（灭自证）：`ErrorMessageBanner.cs` 里**没有任何点击接线**"
                                        + $"（违规 {badA3b.Count} 处：{string.Join(" | ", badA3b.ToArray())}）"
                                        + " —— 原版这一棵没有 Pointer 接口（判据 → 文件头 ⑫）");
                                }
                            }
                        }
                    }
                }
            }
        }

        // ---- 16·b. 🆕 2026-10-19（A1502②）：**名牌上那层头像立绘**（`Avatar Item Small/Image Container/Image`）----
        //  生产代码 = `Battle/BattleDriver.cs` 的 `HudAbsTex` / `AvatarTex` / `BotAvatarIndex` /
        //  `RefreshHudAvatars` ＋ `BuildHudExtras` 里建 `AvatarImage_Me` / `AvatarImage_Foe` 那两句。
        //
        //  🔴 **为什么单开这一批**：本仓刚查实一条**恒绿断言** —— `Core/CardView.cs:1017` 的
        //     `TextBgVisible` **只看 `activeSelf`**，而场景里 `m_IsActive` 恰好是 1
        //     ⇒ 16k+ 条断言全绿、**那一层一个像素都没画**。⚠️ 同族陷阱：`FindChild` /
        //     `GetComponentsInChildren(true)` **含 inactive** ⇒ 「找得到」推不出「画得出来」。
        //     ⇒ 本节每一条「该显示」都**同时**断三样：`active`（含父链）+ **真有图** + **真有尺寸**。
        //
        //  🔴 判据（原版三条，已查实，⛔ 别重复查）：
        //   · `PlayerProfileUIController__SetProfileAvatar.c` —— 传进来 null 会**回落**
        //     `DefaultAvatarItem()`；紧随其后的 `AvatarDisplay__ChangeAvatar.c` 是
        //     `set_enabled(avatarImage, sprite != null)` ⇒ 原版这一层**永远有图**
        //     （我们当初不建它的那条判据「场景态 `m_Enabled = 0`、`m_Sprite = null`」**只说了出厂态**）；
        //   · `MatchData__SetBotDeckRandomCosmetics.c` ⇒ **单机对局的 bot 也有**头像；
        //   · `Player Profile Border` 那张图的**中心是不透明黑** ⇒ 立绘的 z 必须**更小**（= 更靠前），
        //     否则画面上就是 A1502② 一开始看到的那两块「空黑框」。
        Debug.Log(P + "--- A1502②：名牌上的头像立绘（两层）---");
        {
            var drv = Object.FindObjectOfType<BattleDriver>();
            if (drv == null) Check(false, "找不到 BattleDriver");
            else
            {
                // 🔴🔴 **2026-10-16（`EW8` · `T09` 批 3 连带）：这四件已【迁到 uGUI 画布】，旧读法两条叠加、恒 `null`。**
                //   它们走 `HudAbs`/`HudAbsTex` → `HudImageTex` → `HudCanvas.MakeAnchored`：
                //   ① `HudImageTex` 对**裸 `Transform`** 的 `root`（= `hudRoot`）一律 `Ensure(cam)` ⇒ 建在**根画布**直下，
                //      而根画布**是根对象**（`HudCanvas.Ensure` 里 `new GameObject(…)` 没有 `SetParent`；
                //      文件头第 2 条明文「⛔ 根 canvas 不能挂在 HUD 根下」—— 那是反向补震用的）
                //      ⇒ `drv.hudRoot.Find(nm)`（`Transform.Find` **不递归**）找不到；
                //   ② 那份件是 `RectTransform + Image`（`HudPiece` 的新路），**GO 上根本没有 `ImageQuad` 组件**
                //      ⇒ `GetComponent<ImageQuad>()` 也恒 `null`。
                //   ⇒ 本节原来**整组 12 条恒红**（不是「可能红」）：`IsDrawn` 报「节点或 `ImageQuad` 不在」、
                //      `QH` 恒 `0`/`-1`、`QZ` 恒 `NaN`（NaN 比较恒假）、`kMe/kFo` 恒 `0`。
                //   ✅ 判据侧换把尺（与上面字族那半边**同一条口径**）：**在根画布上按名找 `RectTransform`**，
                //      尺寸读 **`sizeDelta`（设计 px）**、层序读 **`HudCanvas.OrderZOf`（z 档）**。
                //   ⛔ **别用 `HudPiece.WorldH * 108f` 反推 px** —— 那个在非 16:9 下只是设计 px 的 0.75 倍
                //      （`T09` §七·8；`HudPiece.SetWorldHeight` 的 doc 有完整判据），
                //      而本节的期望值**全是原版设计 px 字面量**（88.7274449 / 99.1251923 / 158.6003077）。
                //   🔴 **2026-10-21（`G1`）就地订正**：本行原文写「这四件都是**根画布的直接子件**（`root` 传的是
                //      `hudRoot`）⇒ 不递归正好够用」—— **已过期**：`root` 是裸 `Transform` 的那一档现在建进
                //      `BattleHudLayer`（整层换牌期收掉）⇒ 必须走 `FindHudNode` 的回退（先直接子件、再 `BattleHudLayer/`）。
                RectTransform Rt(string nm)
                {
                    return FindHudNode(nm) as RectTransform;
                }
                // 「这一层真的画出来了」—— **三样一起断**；返回 null = 没问题，否则是「为什么没画」。
                string IsDrawn(string nm)
                {
                    var rt = Rt(nm);
                    if (rt == null) return "节点不在（`FindHudNode` 在根画布直子 / `BattleHudLayer` 直子 / rig 子树三档里都找不到）";
                    if (!rt.gameObject.activeSelf || !rt.gameObject.activeInHierarchy) return "`active` 是关的";
                    var iv = rt.GetComponent<Image>();
                    if (iv == null || iv.sprite == null || iv.sprite.texture == null)
                        return "`Image`/`sprite`/`texture` 缺一（有壳没图 —— 正是那条恒绿断言的病）";
                    var sz = HudCanvas.SizePx(rt);
                    if (!(sz.x > 0.5f) || !(sz.y > 0.5f)) return $"尺寸退化（{sz.x:F3}×{sz.y:F3} 设计 px）";
                    return null;
                }
                // 这个件占的 **z 档**。⚠️ uGUI 下「谁压谁」由**兄弟序**定、⛔ 不是 Unity 的 `localPosition.z`
                //   （那份件在画布上，`localPosition.z` 恒 0）⇒ 走 `HudPiece.OrderZ` 的那条读法。
                float QZ(string nm) { var rt = Rt(nm); return rt != null ? HudCanvas.OrderZOf(rt) : float.NaN; }
                // 这个件画出来的**高（设计 px）** —— 读 `sizeDelta.y`（= `HudCanvas.MakeAnchored` 写进去的那个数，
                //   ⛔ 不是 `WorldH`；两把尺的关系见上面那段）。
                float QHpx(string nm) { var rt = Rt(nm); return rt != null ? HudCanvas.SizePx(rt).y : 0f; }

                // 🔴 摆回基线：本节每一格**开始前都先回到这一态**（上一格的残留会漏到下一格）。
                bool savedMullAv = drv.mulliganEnabled;
                bool savedOffAv = drv.offensivePhaseEnabled;
                int savedIdxAv = ProfileData.AvatarIndex;
                drv.mulliganEnabled = true;
                drv.offensivePhaseEnabled = false;
                drv.Begin("Ultramarines", "Goff", 20260916);
                drv.RefreshAll();

                // ---- ① 两层都在，而且**真的画出来了**（三样一起断）----
                //  🧨 改坏法：把那两句 `HudAbsTex` 整句删掉（= 回到「只有 Border」的旧写法）⇒ 两条红。
                foreach (string nm in new[] { "AvatarImage_Me", "AvatarImage_Foe" })
                {
                    string bad = IsDrawn(nm);
                    var rt = Rt(nm);
                    var iv = rt != null ? rt.GetComponent<Image>() : null;
                    var sz = rt != null ? HudCanvas.SizePx(rt) : Vector2.zero;
                    string tex = (iv != null && iv.sprite != null && iv.sprite.texture != null)
                               ? iv.sprite.texture.name : "<无图>";
                    string desc = rt == null ? "（节点不在）"
                                : $"图「{tex}」· "
                                + $"{sz.x:F3}×{sz.y:F3} 设计 px · z 档 {HudCanvas.OrderZOf(rt):F3} · "
                                + $"activeSelf={rt.gameObject.activeSelf}/inHierarchy={rt.gameObject.activeInHierarchy}";
                    Check(bad == null,
                          $"★ A1502② `{nm}` **真的画出来了**：{desc}"
                        + (bad != null ? $" —— **{bad}**" : ""));
                }

                // ---- ② 尺寸 = 那一面 `Border` 的 **1.6 倍**，且**两件的绝对尺寸 = 原版 px** ----
                //  换算（原版直读）：容器高 99.1251923 × `Image.m_LocalScale 2.0` = 198.2503846，**再 × 父链 0.8**
                //  = **158.6003077**（PA 内接后仍是正方）；而 `Border` = 99.1251923（自己 ×1.25、按 256/286 内接）
                //  ⇒ 158.6003077 / 99.1251923 = **1.6**。
                //  🔴 **2026-10-19（A1512）**：原来这里**只断比值**，理由是「绝对值会跟着那个还没乘的 0.8 一起变
                //     ⇒ 比值对它免疫」。**0.8 现在补上了，绝对值可以（也应该）钉死** ——
                //     只断比值的话：「两件一起改回未乘 0.8 的那一版」（198.25 / 123.906）比值**又回到 1.6 ⇒ 绿**。
                //     ⇒ 下面**逐件再钉一次原版绝对 px**（⛔ 期望值是原版字面量，**不由** `HudPlateScale` 推出来）。
                //  🧨 改坏法：`HudAvatarSize` 去掉 `× HudPlateScale`、或 `Border` 改回 110.909×123.906 ⇒ 红。
                foreach (var pr in new[] { new[] { "AvatarImage_Me", "AvatarItemSmall_Me" },
                                           new[] { "AvatarImage_Foe", "AvatarItemSmall_Foe" } })
                {
                    float ah = QHpx(pr[0]), bh = QHpx(pr[1]);              // 设计 px（见 `QHpx`）
                    Check(bh > 1e-3f && Mathf.Abs(ah / bh - 1.6f) < 1e-3f,
                          $"★ A1502② `{pr[0]}` 实绘高 = `{pr[1]}` 的 **1.6 倍**（原版 `m_LocalScale 2.0` ×"
                        + $" 容器高 99.1251923 = 198.2503846，再 × 父链 0.8 = 158.6003077；除以 `Border` 的"
                        + $" 99.1251923 ⇒ 1.6）—— 实测 {ah:F4} / {bh:F4} 设计 px = {(bh > 1e-3f ? ah / bh : 0f):F5}");
                }
                // 🔴 **2026-10-19（A1512）：这两对的【绝对尺寸】**（出处 = `menu_dump` 的 `视觉框` 列）
                //    · `Avatar Item Small/Image Container/Border`（自己 `m_LocalScale 1.25`）：
                //      布局框 124.512×79.30016 ⇒ 视觉 155.64×99.12519，再 PA 内接（256/286、**高受限**）⇒ **88.7274449×99.1251923**
                //    · `…/Image`（自己 `m_LocalScale 2.0`）：布局框 124.512×79.30016 ⇒ 视觉 249.024×158.60031，
                //      贴图 512×512（PA）⇒ **158.6003077**（高；宽 = 高 × 贴图比例）
                //  ⚠️ **金框**那张图是固定的 256×286 ⇒ 宽高**都**钉死；
                //  ⚠️ **立绘**只钉**高** —— 见下面那一段的说明（`Art/avatars/` 里有非正方图）。
                foreach (var (nm, wPx, hPx) in new[] { ("AvatarItemSmall_Me",  88.7274449f, 99.1251923f),
                                                       ("AvatarItemSmall_Foe", 88.7274449f, 99.1251923f) })
                {
                    var rt = Rt(nm);
                    var sz = rt != null ? HudCanvas.SizePx(rt) : new Vector2(-1f, -1f);
                    float gw = sz.x, gh = sz.y;                        // 设计 px（`sizeDelta`，见上面那段）
                    Check(Mathf.Abs(gw - wPx) < 0.05f && Mathf.Abs(gh - hPx) < 0.05f,
                          $"★ A1512 `{nm}` 实绘 = **原版 {wPx}×{hPx} px**（`menu_dump` 视觉框，父链 0.8 已含）"
                        + $" —— 实测 {gw:F4}×{gh:F4} px（改前是未乘 0.8 的那一版）");
                }
                // ⚠️ **立绘只钉高**：宽 = 高 × 贴图比例（`ImageQuad.WorldW = _worldH × 贴图宽高比`，PA 就是这么内接的），
                //    而 `Resources/Art/avatars/` 里 **472 张有 2 张不是正方**
                //    （`Avatar_SAU_Deathmark.png` / `Avatar_SAU_Vargard Obyron.png`，**437×441**）
                //    ⇒ 它们那两局的真值就是 **157.1615**，钉死 158.6003 会**冤枉**它。
                //    `HudAvatarSize`（= `HudPlateScale` 唯一的使用点）**整个落在「高」上** ⇒ 钉高就够挡「改回 1f」。
                foreach (string nm in new[] { "AvatarImage_Me", "AvatarImage_Foe" })
                {
                    var rt = Rt(nm);
                    float gh = rt != null ? HudCanvas.SizePx(rt).y : -1f;   // 设计 px（见 `QHpx`）
                    Check(Mathf.Abs(gh - 158.6003077f) < 0.05f,
                          $"★ A1512 `{nm}` 实绘**高** = **原版 158.6003077 px**（布局框 124.512×79.30016 × 自己 2.0"
                        + $" × 父链 0.8，见 `menu_dump` 的 `视觉框=×2 → 249.02×158.60`）—— 实测 {gh:F4} px"
                        + $"（宽由贴图比例定、**故意不钉**：非正方的头像有 2 张）");
                }

                // ---- ③ 中心 = 框中心 + 偏移（我 右 0.8 / 上 11.690 px · 敌 右 0 / 上 11.930 px）----
                //  出处：原版那几个 `m_AnchoredPosition`（我 (0, 2.70) / 敌 (0, 2.15) 那一对，见
                //  `BattleDriver` 里 `HudAvatarH` 上面那段注释）算出来是**容器局部单位**，再乘父链那一级
                //  0.8 ⇒ px 就是 14.6125×0.8 = 11.690（我）/ 14.9125×0.8 = 11.930（敌）；x 那一侧是 1.0×0.8 = 0.8 / 0。
                //  🔴 **2026-10-19（A1512）**：`SpecBorderHpx` 从 **123.90649041742475** 改成 **99.1251923339398**
                //     （= 原版 `Border` 的**真实绘高**，父链 0.8 已经含在里面）。理由：`k` 的口径是
                //     「**我们那面框 ÷ 原版框架**」，0.8 补上之后原版框架本来就该是 99.1251923 ⇒ `k == 1`
                //     ⇒ 下面那两个 `0.8 / 11.690` 就是**原版 px 绝对值**（⛔ 不是 `× HudPlateScale` 推出来的）。
                //     改前 `k = 0.8`、期望值被缩成 0.64 / 9.352 ⇒ 与真值差 0.16 / 2.34 px ⇒ **必红**。
                //  🧨 改坏法：把那两个 `x/y` 写成 `Border` 那两个（= 立绘与框完全重合）⇒ 偏移变 (0, 0) ⇒ 红。
                const float SpecBorderHpx = 99.1251923339398f;
                {
                    // 🔴 2026-10-16（`EW8`）：分子从「世界高」换成 **设计 px**（`sizeDelta.y`）⇒ 分母那个
                    //    `/ 108f`（世界单位↔设计 px 的桥，`QH` 那一路才需要）**同步去掉** ⇒ `k` 仍是
                    //    「我们那面框 ÷ 原版框架」、两条并存时仍应 ≈ **1.0000**（改前 = 88.7/99.1 = 0.895、
                    //    再叠旧读法恒 0 ⇒ 必红）。
                    float kMe = QHpx("AvatarItemSmall_Me") / SpecBorderHpx;
                    Vector2 pa = drv.HudExtraPosPx("AvatarImage_Me"), pb = drv.HudExtraPosPx("AvatarItemSmall_Me");
                    float tolMe = 0.05f * kMe;
                    Check(kMe > 0f
                       && Mathf.Abs((pa.x - pb.x) - 0.8f * kMe) < tolMe
                       && Mathf.Abs((pa.y - pb.y) + 11.6900153867151f * kMe) < tolMe,
                          $"★ A1502② 我方立绘中心 = 框中心 **右 0.8 / 上 11.690 px**"
                        + $"（原版绝对 px；`k` 只是哨兵，现在应为 1.0000，实得 {kMe:F4}）"
                        + $" —— 实得 (Δx, Δy) = ({pa.x - pb.x:F4}, {pa.y - pb.y:F4})（坐标 y 从上 ⇒ 上移是负）"
                        + $"；期望 ({0.8f * kMe:F4}, {-11.6900153867151f * kMe:F4})，容差 {tolMe:F4} px");

                    float kFo = QHpx("AvatarItemSmall_Foe") / SpecBorderHpx;      // 同 `kMe`：两边都是设计 px
                    Vector2 fa = drv.HudExtraPosPx("AvatarImage_Foe"), fb = drv.HudExtraPosPx("AvatarItemSmall_Foe");
                    float tolFo = 0.05f * kFo;
                    Check(kFo > 0f && Mathf.Abs(fa.x - fb.x) < tolFo
                       && Mathf.Abs((fa.y - fb.y) + 11.9300153867152f * kFo) < tolFo,
                          $"★ A1502② 敌方立绘中心 = 框中心 **右 0 / 上 11.930 px**"
                        + $"（原版绝对 px；`k` 只是哨兵，现在应为 1.0000，实得 {kFo:F4}）"
                        + $" —— 实得 (Δx, Δy) = ({fa.x - fb.x:F4}, {fa.y - fb.y:F4})"
                        + $"；期望 (0, {-11.9300153867152f * kFo:F4})，容差 {tolFo:F4} px");
                }

                // ---- ④ 灭自证：**一行同时钉住两件事** ----
                //  语义（本文件 `HudImageTex` 那句「相机看 +Z，z 越大越远」）：**z 越小越靠前**。
                //   · 立绘必须在它那面 `Border` **之前** —— 那张图中心是不透明黑，反了就是**一块黑**；
                //   · `ChatButton` 必须在立绘**之前** —— 这一笔把它的 z 从默认 `HudImageZ`(0.3) 挪到 0.235
                //     就是为了这个（判据 = 原版同级兄弟序 `[PlayerName(头像挂在里面), Milestones, ChatButton]`
                //     ⇒ 后出现的兄弟画在上面）。
                //  ⚠️ 简报里给的那条写成 `avatarZ < frameZ && avatarZ < chatZ`，**与实现/判据不符**
                //     （实现是 `chatZ(0.235) < avatarZ(0.245) < frameZ(0.25)`）—— 这里按**实现与判据**写。
                //  🧨 改坏法（一行里两件事各有一条坏法）：
                //     · `HudAvatarZ` 改回 `HudImageZ`（或改到 `HudImageZ - 0.05f` 之后）⇒ 前半假 ⇒ 红；
                //     · `ChatButton` 那句的 z 改回默认（`HudImageZ`）⇒ 后半假 ⇒ 红。
                {
                    float azMe = QZ("AvatarImage_Me"), bzMe = QZ("AvatarItemSmall_Me"), cz = QZ("ChatButton");
                    Check(azMe < bzMe && cz < azMe,
                          $"★ A1502② z 序：`ChatButton`({cz:F3}) < 立绘我({azMe:F3}) < `Border`我({bzMe:F3})"
                        + "（z 越小越靠前）—— 立绘反到 `Border` 后面就是**一块黑**；"
                        + "`ChatButton` 退回 0.3 就会被立绘盖掉一截");
                    float azFo = QZ("AvatarImage_Foe"), bzFo = QZ("AvatarItemSmall_Foe");
                    Check(azFo < bzFo,
                          $"★ A1502② ……敌方那一对同样（立绘 {azFo:F3} < 框 {bzFo:F3}）");
                }

                // ---- ⑤ 换牌阶段**提示条照样出**（原版没有「换牌期不显示提示」这条规则）----
                //  🔴 **2026-10-15 换件（`A2109` 第 1 条）**：本处原来断的是一条**我们自己加的抑制**
                //     （`SetHint` 开头 `if (InMulligan) { _hintLabel.SetText(""); return; }`，账 `A1502①`）——
                //     它存在的理由是「自建提示行钉在屏幕正中、被两张督军卡盖住」。换成**原版的提示条**
                //     （`AboveShader/TipText`：`ap.y = 91.78` 在屏幕中心**上方**、宽 2450）之后那条理由不再适用，
                //     而且**原版没有任何与 mulligan 相关的分支**（`BattleTipController.ShowHeadsUpMessage`
                //     与 `_DisplayTip_d__14__MoveNext` 逐句读过）⇒ **那道抑制整个删掉**。
                //  🧨 改坏法：谁再把 `if (InMulligan) return;` 加回 `SetHint` ⇒ 这一条当场红。
                {
                    drv.mulliganEnabled = true;
                    drv.offensivePhaseEnabled = false;      // ⛔ 不关的话换牌一完就停在「选进攻卡」那一步
                    drv.Begin("Ultramarines", "Goff", 20260920);
                    Check(drv.InMulligan, "★ A2109①（前提）这一局进了换牌阶段 —— 不成立时下面两条等于没验");
                    if (drv.InMulligan)
                    {
                        drv.NetSay("__A2109①_probe__");
                        Check(drv.TipPending("__A2109①_probe__"),
                              "★ A2109① **换牌阶段提示条照样出**（原版 `BattleTipController` 里没有 mulligan 这一支）"
                            + $" —— 实得「{drv.HintText ?? "(null)"}」");
                        Check(drv.SimulateMulliganToggle(0),
                              "★ A2109①（前提）点第 1 张牌的「换」被面板收下（下面要它真的换出 1 张）");
                        Check(drv.SimulateMulliganDone(), "★ A2109①（前提）点「完成换牌」");
                        Check(!drv.InMulligan, "★ A2109① ……换牌阶段真的结束了（`Ctx.MulliganOpen` 落了）");
                        drv.NetSay("__A2109①_after__");
                        Check(drv.TipPending("__A2109①_after__"),
                              "★ A2109① ……换牌结束之后同一条路**照旧**（前后两态一样，不再有那道闸）"
                            + $" —— 实得「{drv.HintText ?? "(null)"}」");
                    }
                }

                // ---- ⑥ bot 头像**跟 seed 走**（同 seed 相同 / 换 seed **不恒同**）----
                //  实现 = `BotAvatarIndex()`：拿本局 `_seed` 做一次位混合再 `% list.Count` —— **确定性**。
                //  🔴 **只有「同 seed 相同」这半条是没有判别力的**（返回常量也满足它）⇒ 必须配第二半。
                //  🧨 改坏法：把 `BotAvatarIndex()` 改成返回常量（或改读 `Ctx.Rng`）⇒ 第一半仍绿、**第二半红**。
                {
                    drv.mulliganEnabled = false;     // 这一格只关心头像 ⇒ 把换牌那条支路关掉，少一层噪声
                    var avSeeds = new[] { 20260911, 20260912, 1, 7, 1000, 999983, 123456789, 424242 };
                    var avArts = new List<string>();
                    foreach (int sd in avSeeds) { drv.Begin("Ultramarines", "Goff", sd); avArts.Add(drv.HudAvatarFoeArt); }
                    drv.Begin("Ultramarines", "Goff", avSeeds[0]);
                    string avAgain = drv.HudAvatarFoeArt;
                    Check(avArts[0] != null && avAgain == avArts[0],
                          $"★ A1502② **同一个 seed ⇒ 同一张 bot 头像**（seed {avSeeds[0]}：「{avArts[0]}」==「{avAgain}」）");
                    var avUniq = new HashSet<string>();
                    foreach (var a in avArts) avUniq.Add(a);
                    Check(avUniq.Count >= 2,
                          $"★ A1502② ……换 seed ⇒ **不是恒同一张**（{avSeeds.Length} 个 seed 出了 {avUniq.Count} 张不同头像）");
                    Check(avArts.TrueForAll(a => a != null && a.StartsWith("Avatar_")),
                          "★ A1502② bot 那层取到的都是 `Art/avatars/` 里的真图（都形如 `Avatar_*`）"
                        + $" —— 实得 {string.Join(" / ", avArts.ToArray())}");
                }

                // ---- ⑦ 玩家换头像 ⇒ 战斗里这一层跟着换 · ⑧ 头像**不扰动引擎随机流** ----
                int nAv = ProfileData.Avatars != null ? ProfileData.Avatars.Count : 0;
                Check(nAv > 1, $"★（前提）头像清单读进来了（`Resources/profile_cosmetics.json`，{nAv} 张）"
                             + " —— 不成立时下面这一组等于没验");
                if (nAv > 1)
                {
                    int idxA = 0, idxB = nAv / 2;

                    // ⑦ **两条一起断**：「跟着选的那张走」+「判别式：真的换了」。
                    //  🧨 改坏法：把 `AvatarTex(ProfileData.AvatarArt, …)` 换成写死某一张图 ⇒ 两条一起红。
                    ProfileData.AvatarIndex = idxA;
                    drv.Begin("Ultramarines", "Goff", 20260916);
                    string avArtA = drv.HudAvatarMeArt;
                    ProfileData.AvatarIndex = idxB;
                    drv.RefreshAll();          // `RefreshHudAvatars` 就在 `UpdateHud` 里（`Begin` 那次也会刷）
                    string avArtB = drv.HudAvatarMeArt;
                    Check(avArtA == ProfileData.Avatars[idxA].Art && avArtB == ProfileData.Avatars[idxB].Art,
                          $"★ A1502② 我方立绘 = **档案窗选的那张**（索引 {idxA} →「{avArtA}」· 索引 {idxB} →「{avArtB}」）");
                    Check(avArtA != null && avArtB != null && avArtA != avArtB,
                          $"★ A1502② ……**判别式**：换一个索引这一层**真的换了**（「{avArtA}」≠「{avArtB}」）");

                    // ⑧ **同 seed 的引擎输出逐字相同**，且 `Ctx.Rng` **一个数都没被花掉**。
                    //  A、B 两遍除了「头像输入」与「刷新次数」之外**完全一样**：
                    //   · A：`AvatarIndex = idxA`，`Begin` 之后刷 **1** 次；
                    //   · B：`AvatarIndex = idxB`，`Begin` 之后在**静置**状态下刷 **61** 次
                    //     （`RefreshAll` → `UpdateHud` → `RefreshHudAvatars`，每刷一次都走一遍立绘那条路）。
                    //  ⇒ 立绘那条路若动了 `Ctx.Rng`（例如把 `BotAvatarIndex` 改成从 Rng 里挑），B 那 60 次
                    //    多余的刷新会把随机流**挪位**，下面两条立刻红。
                    //  🔴 B 那一遍**全程静置**（不发任何引擎动作）⇒ 除了「每帧都跑的表现层」之外没有别的
                    //     消耗源，这正是这一条要量的东西（`CardPresentation/` 里 `Ctx.Rng` 的**代码**消费点
                    //     只有 `BattleDriver` 那两处自动挑牌，不在 `RefreshAll` 这条路上）。
                    //  🧨 改坏法：`BotAvatarIndex()` 里写 `return Ctx.Rng.Next(list.Count);` ⇒ 第二条红。
                    drv.mulliganEnabled = false;
                    const int seedRng = 20260921;
                    ProfileData.AvatarIndex = idxA;
                    drv.Begin("Ultramarines", "Goff", seedRng);
                    drv.RefreshAll();
                    int avHashA = NetProtocol.StateHash(drv.Ctx);
                    int avRngA1 = drv.Ctx.Rng.Next(), avRngA2 = drv.Ctx.Rng.Next(), avRngA3 = drv.Ctx.Rng.Next();
                    string avRngArtA = drv.HudAvatarMeArt;

                    ProfileData.AvatarIndex = idxB;
                    drv.Begin("Ultramarines", "Goff", seedRng);
                    for (int i = 0; i < 60; i++) drv.RefreshAll();
                    int avHashB = NetProtocol.StateHash(drv.Ctx);
                    int avRngB1 = drv.Ctx.Rng.Next(), avRngB2 = drv.Ctx.Rng.Next(), avRngB3 = drv.Ctx.Rng.Next();
                    string avRngArtB = drv.HudAvatarMeArt;

                    // 🔴 **见证**：两遍的**头像输入真的不同** —— 否则下面两条是拿同一个东西比自己，等于没验。
                    Check(avRngArtA != null && avRngArtB != null && avRngArtA != avRngArtB,
                          $"★ A1502②（见证）两遍的立绘输入**真的不同**（「{avRngArtA}」vs「{avRngArtB}」）");
                    Check(avHashA == avHashB,
                          $"★ A1502② 同 seed ⇒ **局面哈希逐字相同**（{avHashA} vs {avHashB}）"
                        + " —— 多刷 60 次立绘，一点引擎状态都没带进去");
                    Check(avRngA1 == avRngB1 && avRngA2 == avRngB2 && avRngA3 == avRngB3,
                          $"★ A1502② ……**而且 `Ctx.Rng` 的下一串数逐位相同**"
                        + $"（({avRngA1},{avRngA2},{avRngA3}) vs ({avRngB1},{avRngB2},{avRngB3})）"
                        + " ⇒ 立绘那条路**一个 `Ctx.Rng` 都没花**（它走 `BotAvatarIndex()` 那套自算位混合）");
                }

                // 🔴 **摆回基线**（本仓踩过：上一格的残留会漏到下一格）——
                //    `ProfileData` 是全局静态、那两个 `*Enabled` 是驱动级开关，都得还原。
                ProfileData.AvatarIndex = savedIdxAv;
                drv.mulliganEnabled = savedMullAv;
                drv.offensivePhaseEnabled = savedOffAv;
                drv.Begin("Ultramarines", "Goff", 20260916);
                Step(0.3f);
            }
        }

        // ---- 16·c 🔴 2026-10-22（E-C）：换牌期那 8 条原版 `BattleHud*` legacy clip 的接线 ----
        //  判据 → `资料/普查产出_1022/E-C_BattleHud8条.md` §三；实现/坑 → `Battle/BattleHudAnim.cs` 文件头。
        //  本节验四件事：① 表 + 时长（读**重建出来的 `clip.length`**）② rig 搬家零位移
        //  ③ 两个端点（Hidden 的 9 个 delta / Show 末帧全 0）④ 触发链（换牌进/出各播哪条）。
        //  🧨 各条都写清「改回 `alpha = 0` 硬切 / 把 delta 写成绝对值 ⇒ 红」。
        Debug.Log(P + "--- 换牌期 HUD 动画（8 条 BattleHud* legacy clip）---");
        {
            var drv = Object.FindObjectOfType<BattleDriver>();
            if (drv == null) Check(false, "★ E-C（前提）找不到 BattleDriver");
            else
            {
                Check(drv.HudAnimBuiltForTest,
                      "★ E-C（前提）换牌期 HUD 动画播放器 + 9 颗 rig 都建出来了"
                    + $"（实得 {(drv.HudAnimForTest != null ? drv.HudAnimForTest.RigCount.ToString() : "<无播放器>")} 颗）"
                    + "｜🧨 删掉 `BuildHudAnimRigs()` 那一句（或让它排在 `BuildHudExtras` 之前）⇒ 本条 + 下面全红");
                var ha = drv.HudAnimForTest;
                if (ha != null && ha.Built)
                {
                    // ---- ① 表：8 条 · 无载表错误 · 时长（**读重建出来的 `AnimationClip.length`**）----
                    //  🧨 改坏法：`Resources/battlehud_clips.json` 没带 / `SetCurve` 的绑定写错（曲线进不去）
                    //     ⇒ `clip.length` 变 0 ⇒ Show 那条当场红（⛔ 不是「读 JSON 字段」那种自证）。
                    Check(BattleHudAnim.Loaded && BattleHudAnim.ClipCount == 8,
                          $"★ E-C：表里有 8 条 clip（实得 {BattleHudAnim.ClipCount}；错误 = "
                        + $"{BattleHudAnim.LastError ?? "<无>"}）"
                        + "｜🧨 生成器没跑 / `Resources/battlehud_clips.json` 没拷 ⇒ 红");
                    Check(Mathf.Abs(BattleHudAnim.LengthOf("BattleHudShow") - 1f) < 1e-4f,
                          $"★ E-C：`BattleHudShow` 时长 = **1.000 s**（实得 {BattleHudAnim.LengthOf("BattleHudShow"):F4}）"
                        + "｜🧨 曲线没写进 clip（`SetCurve` 绑错）⇒ 长度变 0 ⇒ 红");
                    Check(Mathf.Abs(BattleHudAnim.LengthOf("BattleHudShowInstant") - 0f) < 1e-6f
                       && Mathf.Abs(BattleHudAnim.LengthOf("BattleHudHiddenNoHand") - 0f) < 1e-6f
                       && Mathf.Abs(BattleHudAnim.LengthOf("BattleHudHideNoHand") - 1f) < 1e-4f,
                          "★ E-C：Instant 那 4 条 = **0.000 s**、带补间那 4 条 = **1.000 s**"
                        + $"（实得 ShowInstant={BattleHudAnim.LengthOf("BattleHudShowInstant"):F4} / "
                        + $"HiddenNoHand={BattleHudAnim.LengthOf("BattleHudHiddenNoHand"):F4} / "
                        + $"HideNoHand={BattleHudAnim.LengthOf("BattleHudHideNoHand"):F4}）"
                        + "｜🧨 把时长写死成同一个数 ⇒ 红（原版就是 4+4）");
                    Check(BattleHudAnim.CurveCountOf("BattleHudHidden") == 16
                       && BattleHudAnim.CurveCountOf("BattleHudHiddenNoHand") == 14
                       && BattleHudAnim.CurveCountOf("BattleHudShowInstantNoHand") == 15,
                          "★ E-C：曲线条数照原版（Hidden 16 / HiddenNoHand 14 / ShowInstantNoHand 15）"
                        + $"（实得 {BattleHudAnim.CurveCountOf("BattleHudHidden")}/"
                        + $"{BattleHudAnim.CurveCountOf("BattleHudHiddenNoHand")}/"
                        + $"{BattleHudAnim.CurveCountOf("BattleHudShowInstantNoHand")}）");

                    // ---- ② rig：9 颗 + **搬家零位移**（全屏 + 单位变换）----
                    Check(ha.RigCount == 9,
                          $"★ E-C：9 个原版落点各一颗 rig（实得 {ha.RigCount}）—— 原版那 8 条 clip 动的就是这 9 个组节点");
                    Check(ha.MoveMaxDeltaWorld <= 1e-5f,
                          $"★ E-C：**搬家零位移** —— 把件搬进 rig 前后 `transform.position` 最大偏差 = "
                        + $"{ha.MoveMaxDeltaWorld:E2} 世界单位（阈值 1e-5 ≈ 1e-3 px）"
                        + "｜🧨 rig 不是「全屏 stretch + 单位变换」（例如给了 sizeDelta / 非零 anchoredPosition）⇒ 红");

                    // ---- ③ 端点：`t=0` 播 `BattleHudHidden` ⇒ 9 个 delta 就是原版隐藏位移 ----
                    //  期望值 = **原版末键之差**（`hidden − shown`，逐条从 clip 数据手核；见 E-C §一·2 表），
                    //  ⛔ 不是从被测实现读回来的。
                    ha.SnapTo("BattleHudHidden", 0f);
                    Vector2 P(string node) { return ha.RigAnchoredPosition(node); }
                    bool Near(Vector2 v, float x, float y) { return Mathf.Abs(v.x - x) < 1e-3f && Mathf.Abs(v.y - y) < 1e-3f; }
                    Check(Near(P("LeftArea/PlayerInfo"), -290f, -358f),
                          $"★ E-C：`t=0` 我方名牌 delta = (−290, −358)（实得 {P("LeftArea/PlayerInfo")}；"
                        + "= `BattleHudHidden` (−240,−330) − `BattleHudShow` 末键 (50,28)）"
                        + "｜🧨 把 delta 写成**绝对值**（−240,−330）⇒ 红；把 `shown` 换成场景 rest（31.7 / −48.1）⇒ 红");
                    Check(Near(P("LeftArea/EnemyInfo"), -290f, 358f),
                          $"★ E-C：`t=0` 敌方名牌 delta = (−290, +358)（实得 {P("LeftArea/EnemyInfo")}）");
                    Check(Near(P("RightArea/SettingsBtn"), 364f, 320.199951f),
                          $"★ E-C：`t=0` 设置钮 delta = (+364, +320.19995)（实得 {P("RightArea/SettingsBtn")}）"
                        + "—— y 那一格尤其能抓「把 shown 当成 0」：311 − (−9.19995) = 320.19995");
                    Check(Near(P("RightArea/PlayerDeck"), 0f, -461f)
                       && Near(P("RightArea/EnemyDeck"), 27.699951f, 461f),
                          $"★ E-C：`t=0` 两侧牌堆 delta = 我 (0,−461) / 敌 (+27.69995,+461)（实得 {P("RightArea/PlayerDeck")} / {P("RightArea/EnemyDeck")}）"
                        + "｜🧨 敌方牌堆 x 写成 0（漏掉 −190 vs −217.7 那一档）⇒ 红");
                    Check(Near(P("RightArea/Right Anchor"), 476f, 0f)
                       && Near(P("LeftArea/Left Anchor"), -449f, 0f),
                          $"★ E-C：`t=0` 右锚 +476 / 左锚 −449（实得 {P("RightArea/Right Anchor")} / {P("LeftArea/Left Anchor")}）"
                        + "｜🧨 把 `Right Anchor` 里那批（能量/结束回合）留在 rig 外 ⇒ 位置对但**件不跟着走** ⇒ 下面那条手牌/件的检查会红");
                    //  两处「不是 uGUI 件」的落点：位移走 `HandLayout.areaOffsetY`
                    drv.ApplyHudAnimHandOffsetsForTest();
                    Check(Mathf.Abs(drv.hand.areaOffsetY - (-479f / 1080f)) < 1e-6f,
                          $"★ E-C：`t=0` 我方手牌区下移 479 px（`areaOffsetY` = {drv.hand.areaOffsetY:F6}，"
                        + $"期望 {(-479f / 1080f):F6} = 原版 `HandArea.m_LocalPosition.y`）"
                        + "｜🧨 只搬 uGUI 件、不驱动 `HandLayout` ⇒ 红（真机上手牌不会跟着滑进滑出）");
                    if (drv.foeHand != null)
                        Check(Mathf.Abs(drv.foeHand.areaOffsetY - (402.82998657f / 1080f)) < 1e-4f,
                              $"★ E-C：`t=0` 敌方手牌区上移 402.83 px（`areaOffsetY` = {drv.foeHand.areaOffsetY:F6}）"
                            + "｜🧨 用错符号（−402.83）⇒ 敌手往屏幕里掉 ⇒ 红");
                    //  真·世界坐标：同一次 `SlotPosition` 在「有位移 / 无位移」两档之间必须差 479 px
                    if (drv.hand != null && drv.HandCount > 0)
                    {
                        drv.hand.areaOffsetY = 0f;
                        float y0 = drv.hand.SlotPosition(drv.HandCount - 1, drv.HandCount).y;
                        drv.ApplyHudAnimHandOffsetsForTest();      // 重新按动画值写回
                        float y1 = drv.hand.SlotPosition(drv.HandCount - 1, drv.HandCount).y;
                        float dyPx = (y1 - y0) / LayoutSpace.VisibleHeight * 1080f;
                        Check(Mathf.Abs(dyPx - (-479f)) < 0.01f,
                              $"★ E-C（灭自证）：手牌**世界坐标**真的跟着动了 —— 同一个槽位在「归零 / 换牌隐藏」两档之间差 "
                            + $"{dyPx:F3} px（期望 −479）"
                            + "｜🧨 只把 `areaOffsetY` 写进去、`SlotPosition` 不读它（或读了别的分量）⇒ 红");
                    }

                    // ---- ④ `t=1` 播 `BattleHudShow` ⇒ 9 个 delta **全 0**（回到我们自己的显示基准）----
                    ha.SnapTo("BattleHudShow", 1f);
                    drv.ApplyHudAnimHandOffsetsForTest();
                    int zero = 0, total = 0;
                    string worstNode = null; float worstMag = 0f;
                    for (int i = 0; i < ha.RigCount; i++)
                    {
                        var node = ha.RigNodeAt(i);
                        var v = ha.RigAnchoredPositionAt(i);
                        total++;
                        float mag = Mathf.Max(Mathf.Abs(v.x), Mathf.Abs(v.y));
                        if (mag < 1e-3f) zero++; else if (mag > worstMag) { worstMag = mag; worstNode = node; }
                    }
                    Check(zero == total,
                          $"★ E-C：`t=1`（显示态）**9 颗 rig 全部 delta = 0**（{zero}/{total}"
                        + (worstNode != null ? $"；最差 `{worstNode}` = {ha.RigAnchoredPosition(worstNode)}" : "") + "）"
                        + "｜🧨 `Apply` 里写成 `delta = key`（不减 `shown`）⇒ 整块 HUD 被搬到原版那棵树的位置 ⇒ 红");
                    Check(Mathf.Abs(drv.hand.areaOffsetY) < 1e-6f
                       && (drv.foeHand == null || Mathf.Abs(drv.foeHand.areaOffsetY) < 1e-6f),
                          "★ E-C：`t=1` 两处手牌区位移都回 0（换牌结束手牌回到原版那条基线）");

                    // ---- ⑤ 灭自证（结构上不可能与实现一起改绿）：**表里的原始绝对值** ----
                    //  这三条读的是**原版 clip 的末键**（绝对坐标），期望值手写在断言里（E-C §一·2 逐条核过）。
                    //  把 `Apply` 的 delta 口径改坏时上面几条会红；把**生成器**改坏时这三条红 —— 两条路都堵上。
                    Check(Mathf.Abs(BattleHudAnim.RawLastKey("BattleHudShow", "LeftArea/PlayerInfo", "m_AnchoredPosition.x") - 50f) < 1e-4f
                       && Mathf.Abs(BattleHudAnim.RawLastKey("BattleHudShow", "LeftArea/PlayerInfo", "m_AnchoredPosition.y") - 28f) < 1e-4f,
                          "★ E-C（灭自证·原始值）：表里 `BattleHudShow` 的末键 = 原版 **(50, 28)**"
                        + $"（实得 ({BattleHudAnim.RawLastKey("BattleHudShow", "LeftArea/PlayerInfo", "m_AnchoredPosition.x"):F4}, "
                        + $"{BattleHudAnim.RawLastKey("BattleHudShow", "LeftArea/PlayerInfo", "m_AnchoredPosition.y"):F4})）"
                        + "｜🧨 生成器按「场景 rest」重算 reference（31.7002）⇒ 红");
                    Check(Mathf.Abs(BattleHudAnim.RawLastKey("BattleHudHidden", "UpperAnchor/EnemyArea", "m_AnchoredPosition.y") - 402.82998657f) < 1e-3f,
                          "★ E-C（灭自证·原始值）：表里 `BattleHudHidden` 的 EnemyArea = 原版 **402.8299865722656**"
                        + $"（实得 {BattleHudAnim.RawLastKey("BattleHudHidden", "UpperAnchor/EnemyArea", "m_AnchoredPosition.y"):F4}）");
                    Check(Mathf.Abs(BattleHudAnim.RawLastKey("BattleHudHidden", "RightArea/SettingsBtn", "m_AnchoredPosition.x") - 310f) < 1e-4f
                       && Mathf.Abs(BattleHudAnim.RawLastKey("BattleHudHidden", "RightArea/Right Anchor", "m_AnchoredPosition.x") - 476f) < 1e-4f,
                          "★ E-C（灭自证·原始值）：`BattleHudHidden` 的 SettingsBtn.x = **310**、RightAnchor.x = **476**");
                    Check(Mathf.Abs(BattleHudAnim.RefShown("RightArea/SettingsBtn", "m_AnchoredPosition.x") - (-54f)) < 1e-4f
                       && Mathf.Abs(BattleHudAnim.RefShown("LeftArea/PlayerInfo", "m_AnchoredPosition.x") - 50f) < 1e-4f,
                          "★ E-C：`refs[].shown` 取的是 `BattleHudShow` 末键（SettingsBtn.x = −54 · PlayerInfo.x = 50）"
                        + "—— 这两格正是**场景 rest 与 clip 末键不同**的那两处（E-C §2·2，偏移由显示基准那一侧去修）");

                    // ---- ⑥ 触发链：换牌进 / 出各播哪条（原版两处调用点）----
                    //  ⚠️ 本节在**批处理**下跑：`Play` 直接落终态 ⇒ 这里只断「播的是哪一条」（几何已由 ③④ 单独验）。
                    bool savedMulE = drv.mulliganEnabled, savedOffE = drv.offensivePhaseEnabled;
                    drv.mulliganEnabled = true;
                    drv.offensivePhaseEnabled = false;
                    drv.Begin("Ultramarines", "Goff", 20260916);
                    Check(drv.InMulligan, "★ E-C⑥（前提）这一局进了换牌阶段 —— 不成立时下面两条等于没验");
                    if (drv.InMulligan)
                    {
                        Check(ha.CurrentClipName == BattleHudAnim.HiddenNoHandClip && !drv.HudLayerActiveForTest,
                              $"★ E-C⑥：进换牌期 ⇒ 播 `BattleHudHiddenNoHand`（原版 `m_PlayAutomatically` 的默认 clip）"
                            + $"（实得 `{ha.CurrentClipName ?? "<没播>"}` · HudLayerActive={drv.HudLayerActiveForTest}）"
                            + "｜🧨 退回 `CanvasGroup.alpha = 0` 硬切（不再起播）⇒ 本条红");
                        drv.SimulateMulliganDone();
                        Check(ha.CurrentClipName == BattleHudAnim.ShowClip && drv.HudLayerActiveForTest,
                              $"★ E-C⑥：换牌结束 ⇒ 播 `BattleHudShow`"
                            + "（判据 = `_FinishMulliganFinalPhase_d__351__MoveNext.c:113` = `(1,1,0)`）"
                            + $"（实得 `{ha.CurrentClipName ?? "<没播>"}`）"
                            + "｜🧨 只在状态翻转**之外**每帧 `Play`（会一直重置到 t=0）⇒ 真机上看不出滑入 ⇒ 红");
                    }
                    drv.mulliganEnabled = savedMulE;
                    drv.offensivePhaseEnabled = savedOffE;

                    // ---- 收工：把动画状态与这一局的局面都还原（后面的小节复用同一个 driver）----
                    ha.ResetAll();
                    drv.ApplyHudAnimHandOffsetsForTest();
                    drv.Begin("Ultramarines", "Goff", 20260916);
                    drv.RefreshAll();
                    Check(Mathf.Abs(ha.RigAnchoredPosition("LeftArea/PlayerInfo").x) < 1e-3f
                       && Mathf.Abs(ha.RigAnchoredPosition("LeftArea/PlayerInfo").y) < 1e-3f,
                          "★ E-C：`Begin()` 会把上一局残留的 HUD 位移**清干净**（`ResetAll`）"
                        + "｜🧨 删掉 `Begin` 里那两行复位 ⇒ 上一局「战斗结束收 HUD」的位移带进下一局 ⇒ 红");
                }
            }
        }

        // ---- 17. 开局换牌（原版 `Mulligan` 子树 / 规则书 :46）----
        // 引擎侧的规则账在 `RuleEngineTest.TestMulligan` 里（15 条）；这一节验的是**画面这一侧**：
        // 换牌在 BeginTurn **之前**、面板的件都在、点「换」真的标记、点「完成」真的换掉并开打。
        Debug.Log(P + "--- 开局换牌（Mulligan）---");
        {
            var drv = Object.FindObjectOfType<BattleDriver>();
            if (drv == null) Check(false, "找不到 BattleDriver");
            else
            {
                string Sig(BattleContext c)
                {
                    var l = new List<string>();
                    // ⚠️ **凭空生成的牌不算**（第三十四轮）：换牌结束时 `BeginTurn` 里的**天赋**
                    //    会从卡池现拿一张塞进手牌，而这张签名比的是「**卡组自己的牌有没有多/少**」。
                    // 🔴 2026-09-18 第 7 行第 3 步：标记住在**每一份**上 ⇒ 直接看这一份的
                    //    `EphemeralMarked`。那个「按份数扣、防同名被一起跳过」的绕法**删掉了** ——
                    //    它当年存在的唯一理由就是「卡模板共享、同名那两张分不开」，现在分得开了。
                    foreach (var x in c.Players[0].Hand)
                        if (!x.EphemeralMarked) l.Add(x.Card.Name);
                    foreach (var x in c.Players[0].Deck) l.Add(x.Card.Name);
                    foreach (var x in c.Players[0].Discard) l.Add(x.Card.Name);
                    l.Sort();
                    return string.Join(",", l.ToArray());
                }

                // ---- 17·0 🔴 **A1540**：换牌阶段的手牌必须**停在真牌位**上（发牌入场不许把牌留在父级原点）----
                // 🧨 **为什么单开一格、还要自己开关一次**：手牌那一档**只有存盘场景里 `animateRelayout == 1`**
                //    （`Scenes/Battle.unity`），批处理里出厂是 `false`；而 `animateFeel` 在批处理里默认也关
                //    ⇒ **老写法在这套自检里结构上复现不出来**（诊断 → `普查产出_第十八会话/D1_开局换牌与进攻卡.md`
                //    §问题 A 第 4 条明写）。夹具必须**显式**把这两个开关打开才走得到那条路 —— 这就是本格存在的理由。
                // 判据：原版换牌阶段**不动手牌位置**（`MulliganManager__ActivateMulligan.c` 只做 SetActive +
                //    改两条词条 + 遍历一个列表调 `SetupMulliganButton`），而那颗钮是**读那张卡当时的世界位**
                //    摆的（`MulliganManager__SetupMulliganButton.c:26-32`）⇒ 牌在牌位上、钮才贴着卡。
                // 🧨 改坏法：删掉 `BattleDriver.CommitDealtPoses()`（或把 `DealInPose` 退回 `DealIn`）⇒ 下面全红。
                {
                    var hl0 = drv.hand;
                    if (hl0 == null) Check(false, "★ A1540（前提）取得到 HandLayout");
                    else
                    {
                        bool savedAF = drv.animateFeel, savedAR = hl0.animateRelayout;
                        bool savedMul0 = drv.mulliganEnabled, savedOff0 = drv.offensivePhaseEnabled;
                        drv.animateFeel = true;
                        hl0.animateRelayout = true;      // 🔴 存盘场景里我方手牌那一份就是 1
                        drv.mulliganEnabled = true;      // 🔴 本格的前提：要有换牌阶段（下面第 17 节那段才置 true）
                        drv.offensivePhaseEnabled = false;   // ⛔ 不关的话换牌一完就停在「选进攻卡」那一步
                        drv.Begin("Ultramarines", "Goff", 20260917);
                        Check(drv.InMulligan, "★ A1540（前提）这一局进了换牌阶段 —— 不成立时下面几条等于没验");
                        if (drv.InMulligan)
                        {
                            var origin = drv.transform.position;   // 父级原点 = 老写法让牌停住的地方（画布正中）
                            int hn = drv.HandCount;
                            var preScale = new float[hn];
                            var prePos = new Vector3[hn];
                            for (int i = 0; i < hn; i++)
                            {
                                var v = drv.HandViewAt(i);
                                prePos[i] = v != null ? v.transform.position : origin;
                                preScale[i] = v != null ? v.transform.localScale.x : 0f;
                            }

                            // 🆕 2026-10-24（`A19` · `C1-A01`）**逐张错开的行为面**：推 0.05 s 之后，
                            //   第 0 张已经离开牌堆、第 1 张**还没起飞**（原版每放好一张才等 0.15 s）。
                            //   🧨 改坏法：把发牌改回「同帧全起」（`DealStaggerDelay` 恒 0）⇒ 两张都离开牌堆 ⇒ 红。
                            if (hn >= 2)
                            {
                                var s0 = drv.DealtView(0);
                                var s1 = drv.DealtView(1);
                                Check(s0 != null && s1 != null, "★ C1-A01（前提）前两张都在 `_dealt` 里");
                                if (s0 != null && s1 != null)
                                {
                                    CardTween.Advance(0.05f);
                                    float g0 = Vector3.Distance(s0.transform.position, drv.DeckWorld);
                                    float g1 = Vector3.Distance(s1.transform.position, drv.DeckWorld);
                                    Check(g0 > 0.01f && g1 < 1e-3f,
                                          $"★ 换牌**逐张错开**（行为面）：0.05 s 时第 0 张已离开牌堆（{g0:F3} 世界单位）、"
                                        + $"第 1 张**还压在牌堆上**（{g1:F4}）—— 判据 = 原版每放好一张就 "
                                        + "`WaitForSeconds(timeToDraw × 0.5)`（我方 0.15 s/张）"
                                        + "｜🧨 改回「同帧全起」⇒ 第 1 张 g₁ 也会 > 0.01 ⇒ 红");
                                }
                            }

                            // 把发牌补间推到底 —— 🔴 2026-10-24（`A19` · `C1-A01`）**时长要按张数算**：
                            //   逐张错开之后，第 i 张要到 `i × 0.15 + DealDuration` 才落位 ⇒ 整条链
                            //   = `hn × 0.15`（最后一张之后还等一次）+ 它自己那 0.3 s。
                            //   ⛔ 别再写死 0.4 s：那样第 3、4 张还在飞，下面那几条会假红（不是实现错）。
                            float pumpNeed = BattleDriver.DealChainSeconds(true, hn) + CardFeel.DealDuration + 0.1f;
                            for (float acc = 0f; acc < pumpNeed; acc += 1f / 60f) CardTween.Advance(1f / 60f);

                            int atPose = 0, atOrigin = 0, scaleOk = 0, onBtn = 0;
                            float worstGap = 0f;
                            for (int i = 0; i < hn; i++)
                            {
                                var v = drv.HandViewAt(i);
                                if (v == null) continue;
                                var p = v.transform.position;
                                if (Vector3.Distance(p, origin) > 0.1f) atPose++;
                                else atOrigin++;
                                // 发牌入场结束时它该**回到**「换」钮所在那一列（钮是**贴着卡**摆的）
                                var bp = drv.Mulligan != null ? drv.Mulligan.CardBtnWorldPos(i) : Vector3.zero;
                                float gap = Mathf.Abs(bp.x - p.x);
                                if (gap > worstGap) worstGap = gap;
                                if (gap < 1.5f) onBtn++;
                                // 落点那一套 rotZ / scale（⛔ 不是 `DealIn` 的「一律 0 / 1」）
                                if (Mathf.Abs(v.transform.localScale.x - preScale[i]) < 0.02f) scaleOk++;
                            }
                            Check(atOrigin == 0 && atPose == hn,
                                  $"★ A1540：{hn} 张起手牌发牌结束后**都在真牌位上**（在牌位 {atPose} · 停在父级原点 {atOrigin}）"
                                + "｜🧨 改坏法：退回 `CardFeel.DealIn`（它读当时位置，而 `Place` 只开了补间没落位）"
                                + " ⇒ 牌停在画布正中 (960,540)");
                            // 🔴 **灭自证**：上面那条只断「不在原点」，若把「父级原点」也算成牌位就一起绿了 ——
                            //    这条把牌位钉在**另一处独立读数**上（「换」钮的位置，它是**另一个类**按原版
                            //    `SetupMulliganButton` 的读法摆的）。
                            Check(onBtn == hn && worstGap < 1.5f,
                                  $"★ A1540（**灭自证**）：每张牌都回到它自己那颗「换」钮的列上（{onBtn}/{hn}，最大偏差 {worstGap:F2} 世界）"
                                + "｜🧨 改坏法：牌停在父级原点 ⇒ 与钮（在牌堆/牌位）差 ≈7 世界单位 ⇒ 红");
                            Check(scaleOk == hn,
                                  $"★ A1540：落点是**布局算出来的那一套 scale**、不是 `DealIn` 的 1（{scaleOk}/{hn}；首张 {preScale[0]:F3}）"
                                + "｜🧨 判据 = 实测实拍：按 scale 1 收尾时牌会停在**原尺寸**（226 设计 px，手牌档应 165）");
                        }
                        drv.animateFeel = savedAF;
                        hl0.animateRelayout = savedAR;
                        drv.mulliganEnabled = savedMul0;
                        drv.offensivePhaseEnabled = savedOff0;
                    }
                }

                // ---- 17·0b 🆕 2026-10-19（战斗线 T10）：换牌期命中规则合一（`A1668`）· 起拖两道阈值（`C3` #11）----
                //  判据：`资料/普查产出_1016战斗判据/T10_换牌阶段判据.md` §A1668 / §C3#11 ＋
                //        `d:/2/tools/decomp_full/CardScript__TryDraggingFromHand.c`（逐句）。
                //  ⚠️ 本格只验**判据与状态机**；「手机真机手感」验不了（`editor` 里没有触摸设备）。
                {
                    bool savedMulT = drv.mulliganEnabled, savedOffT = drv.offensivePhaseEnabled;
                    bool savedTouchT = SettingsWindow.GeneralFlags.TouchInput;
                    bool savedPersistT = SettingsWindow.GeneralFlags.PersistOverride;
                    SettingsWindow.GeneralFlags.PersistOverride = true;   // ⛔ 一个字节都不写玩家真设置
                    drv.mulliganEnabled = true;
                    drv.offensivePhaseEnabled = false;
                    drv.Begin("Ultramarines", "Goff", 20260917);
                    Check(drv.InMulligan, "★ T10（前提）这一局进了换牌阶段 —— 不成立时下面几条等于没验");
                    if (drv.InMulligan)
                    {
                        var mpT = drv.Mulligan;
                        int nT = drv.HandCount;
                        Check(mpT != null && nT >= 2, $"★ T10（前提）换牌面板在、起手牌 ≥ 2 张（{nT}）");
                        if (mpT != null && nT >= 2)
                        {
                            // —— `A1671`：起手牌真的在**换牌区那一行**里（`BuildCardButtons` 搬的）——
                            var c0T = drv.HandViewAt(0);
                            var c1T = drv.HandViewAt(1);
                            Check(mpT.HasCard(c0T) && mpT.HasCard(c1T),
                                  "★ A1671：起手牌在**换牌区那一行**里（不是屏幕底部的手牌位）"
                                + "｜🧨 改坏法：`BuildCardButtons` 只贴钮不搬牌 ⇒ 这里 `HasCard` 为假");

                            // —— `A1668`：叠两张、前排 = **下标大的**那张 ——
                            //  旧规则（按下标递增）= 必拿第 0 张；新规则（取最前 z 最小）= 必拿第 1 张
                            //  ⇒ 这条**结构上有判别力**（不是拿实现证明实现）。
                            var pT = mpT.RowWorldPosAt(0, nT);
                            c0T.transform.position = pT + new Vector3(0f, 0f, 0.5f);    // 后
                            c1T.transform.position = pT + new Vector3(0f, 0f, -0.5f);   // 前
                            var hitT = mpT.CardAt(pT);
                            Check(ReferenceEquals(hitT, c1T),
                                  "★ A1668：换牌期点到的是**最前那张**（z 最小），不是「下标最小」"
                                + "｜🧨 改坏法：`MulliganPanel.CardAt` 退回按下标递增扫 ⇒ 拿到第 0 张 ⇒ 红");
                            // 灭自证：手牌那条与换牌区那条**同一个静态判据** ⇒ 同一个点必须给同一张
                            var sharedT = CardInteraction.Frontmost(new List<CardView> { c0T, c1T }, pT);
                            Check(ReferenceEquals(sharedT, c1T) && ReferenceEquals(hitT, sharedT),
                                  "★ A1668（灭自证）：换牌区与手牌走**同一条判据**（`CardInteraction.Frontmost`）—— 两处算出同一张");
                            mpT.ReapplyRowPoses();      // 复位成换牌区那一行（幂等）
                        }
                        if (drv.InMulligan) drv.SimulateMulliganDone();   // 回到普通手牌态，验下面那条输入链
                    }

                    // —— `C3#11` ①–⑤：两道阈值的**纯判据**（原版常量 0.00015 / 65° / 70°）——
                    //  点用 `LayoutSpace.ToWorld` 摆成**视口归一**坐标（与原版 `ScreenToViewportPoint` 同口径）
                    {
                        Vector3 AtViewport(float dx, float dy) { return LayoutSpace.ToWorld(0.5f + dx, 0.5f + dy); }
                        var pressT = AtViewport(0f, 0f);
                        Check(!CardInteraction.HandDragPastThreshold(pressT, AtViewport(0.01f, 0f)),
                              "★ C3#11①：视口位移 0.01（平方 0.0001 ≤ 0.00015）⇒ **不起拖**（原版 `DAT_1834b3150`）");
                        Check(CardInteraction.HandDragPastThreshold(pressT, AtViewport(0f, 0.02f)),
                              "★ C3#11②：位移够了 + 朝正上（0°）⇒ 起拖（原版那条正路）");
                        Check(!CardInteraction.HandDragPastThreshold(pressT, AtViewport(0.02f, 0f)),
                              "★ C3#11③：横向 90° > 65° ⇒ **不起拖**（原版 `DAT_1834b316c`）"
                            + "｜🧨 改坏法：删掉角度闸 ⇒ 这条红");
                        Check(CardInteraction.HandDragPastThreshold(pressT, AtViewport(0.01732f, 0.01f)),
                              "★ C3#11④：60° ≤ 65° ⇒ 起拖（边界**内**那一档真的放行，不是「一律拦」）");
                        var p67T = AtViewport(0.0184f, 0.00784f);      // ≈ 67°
                        Check(!CardInteraction.HandDragPastThreshold(pressT, p67T)
                              && CardInteraction.HandDragPastThreshold(pressT, p67T, true),
                              "★ C3#11⑤：67° —— 默认档拦（65°）、`card+0x249` 档放行（70°）"
                            + "（⚠️ 那个字段的语义没查到 ⇒ 只留判据、生产恒走 65°）");
                    }

                    // —— `C3#11` ⑥：平台闸 = 设置窗 General 页那颗 `Touch input`
                    //   （原版 `GameStaticData.touchInput` static +0x11D，判据 `GeneralTab__TouchInputToggle.c`）——
                    SettingsWindow.GeneralFlags.TouchInput = true;
                    Check(CardInteraction.TouchInputGateForTest,
                          "★ C3#11⑥：平台闸认的就是 `GeneralFlags.TouchInput`（= 原版 `GameStaticData` +0x11D）");
                    SettingsWindow.GeneralFlags.TouchInput = false;
                    Check(!CardInteraction.TouchInputGateForTest,
                          "★ C3#11⑥（灭自证）：关掉那颗开关 ⇒ 闸真的关（不是恒真）");

                    // —— `C3#11` ⑦：候选态走**生产同一批方法**（`Begin/Tick/EndPressCandidate`）——
                    var itT = drv.interaction;
                    Check(itT != null && drv.HandCount > 0, "★ C3#11⑦（前提）手牌交互层在、手里有牌");
                    if (itT != null && drv.HandCount > 0)
                    {
                        var vT = drv.HandViewAt(0);
                        var homeT = vT.transform.position;
                        itT.SimulateHover(homeT);
                        itT.SimulatePressPendingForTest(homeT);
                        Check(itT.PressPendingForTest && !itT.IsDragging,
                              "★ C3#11⑦a：按下**只记候选**（touchInput 档不直接抓 —— 原版是拖拽事件里才试）");
                        bool gSmall = itT.SimulatePendingTickForTest(
                                          homeT + new Vector3(LayoutSpace.VisibleWidth * 0.01f, 0f, 0f));
                        Check(!gSmall && itT.PressPendingForTest && !itT.IsDragging,
                              "★ C3#11⑦b：视口位移 0.01 那一帧**还在候选态**（没抓）");
                        bool gSide = itT.SimulatePendingTickForTest(
                                          homeT + new Vector3(LayoutSpace.VisibleWidth * 0.05f, 0f, 0f));
                        Check(!gSide && itT.PressPendingForTest && !itT.IsDragging,
                              "★ C3#11⑦c：横向蹭 90° **也不抓**（65° 那道闸）");
                        bool gUp = itT.SimulatePendingTickForTest(
                                          homeT + new Vector3(0f, LayoutSpace.VisibleHeight * 0.05f, 0f));
                        Check(gUp && itT.IsDragging, "★ C3#11⑦d：朝上过阈值 ⇒ **才**抓起来");
                        itT.SimulateRelease(homeT);                  // 收工：不在格位上 ⇒ 回弹

                        // ⑦e 轻点那一档：候选态原地松手 = 原版 `OnPointerClick` ⇒ 开/关卡面展示窗
                        //   （⚠️ 这是「按下不再直接 PickUp」带来的**必经分支** —— 不验就会静默退化成「点了没反应」）
                        itT.SimulateHover(homeT);
                        bool dispBefore = drv.CardDisplay != null && drv.CardDisplay.Visible;
                        itT.SimulatePressPendingForTest(homeT);
                        itT.SimulatePendingReleaseForTest(homeT);
                        Check(!itT.PressPendingForTest && !itT.IsDragging,
                              "★ C3#11⑦e：候选态原地松手 ⇒ 回到干净态（不残留 `_pressPending`）");
                        Check(drv.CardDisplay != null && drv.CardDisplay.Visible != dispBefore,
                              "★ C3#11⑦f：这一下**仍然是轻点**（开关卡面展示窗）—— 不许因为加了起拖阈值就吞掉点击"
                            + "｜🧨 改坏法：`EndPressCandidate` 不转发 `OnTapped` ⇒ 手机上点卡没反应 ⇒ 红");

                        // —— 🆕 **2026-10-19（战斗线 `T16` · 命中区全仓普查）**：原版
                        //   `CardCollider.allowClick`（`+0x44`）——**按下后在卡外松手 ⇒ 不产生点击**。
                        //   判据 = `CardCollider__OnPointerDown.c`（置 1）· `CardCollider__OnPointerExit.c`
                        //   （**清 0**，且回到卡上**不会自己恢复**，只有下一次 `OnPointerDown` 才重新置 1）。
                        //   ⚠️ 判别式必须让**位移量**两态相同、只差「有没有出卡」——否则测的是 `_travel`。
                        {
                            int kT16 = -1; float zMinT16 = float.MaxValue;
                            for (int i = 0; i < itT.HandCardCountForTest; i++)
                            {
                                var cv = itT.HandCardForTest(i);
                                if (cv != null && cv.transform.position.z < zMinT16)
                                { zMinT16 = cv.transform.position.z; kT16 = i; }
                            }
                            var cvT16 = kT16 >= 0 ? itT.HandCardForTest(kT16) : null;
                            Check(cvT16 != null, "★ T16：（前提）取得到**最前面**那张手牌（z 最小）");
                            if (cvT16 != null)
                            {
                                // 卡局部系：边界点**按真 collider 的实测矩形**取，⛔ 不再写死 0.96/0.98/1.00。
                                // 🔴 **2026-10-20（W58 · P1-L）**：原来假定半宽 0.985、采样到 1.00（余量仅 1.5%），
                                //    而本仓已记录 `BoxCollider2D` **不跟 `AutoCardRotation` 的 X/Y ±10° 倾摆**、
                                //    最大差 **≈2.6% 卡高**（`CardView.cs:5944-5947`）⇒ 1.5% 余量小于已知偏差，
                                //    `1.00` 可能仍在框内（`cos 10° = 0.9848 < 0.985`）。
                                //    现在：内侧 = 半宽 × **0.90** / 外侧 = 半宽 × **1.10**（10% 余量，跨过 2.6%），
                                //    位移 = 0.04 × 半宽（≈0.039 卡单位 ≪ `TapThreshold` 0.3 世界单位）。
                                float halfWT16 = cvT16.ColliderForTest != null ? cvT16.ColliderSizeForTest.x * 0.5f : 0f;
                                Check(halfWT16 > 0f,
                                      $"★ T16：（前提）最前面那张手牌有真 `BoxCollider2D`（半宽 {halfWT16:F4} 卡单位）");
                                // 取不到 collider 时退回旧常量 —— 上面那条前提**已经红了**，这里不制造假绿。
                                float hwT16 = halfWT16 > 0f ? halfWT16 : 0.985f;
                                float dyT16 = cvT16.ColliderForTest != null ? cvT16.ColliderOffsetForTest.y : 0f;
                                // 🔴 **2026-10-20（W58 · BTFIX3）**：边界点必须在 `SimulateHover` **之后**取 ——
                                //   hover 会把这张卡放大 **1.3×** 并抬高 30 px（`HandLayout.Refresh`）⇒ 悬停前取的
                                //   「半宽 × 1.10」相对**新框**只有 1.10/1.3 = **0.846** 个半宽，**仍在卡内**
                                //   ⇒ `TickPressCandidate` 那句 `_pressInside = false` 不触发、`EndPressCandidate`
                                //   照旧转发点击（日志 63627/63640 两条红就是这个先后）。
                                //   先用卡心把 hover 打上（`HitLocalToWorldForTest` 读的是**当前** transform），
                                //   再按悬停后的 transform 重新取三个点。
                                //   ⛔ 别改 `TickPressCandidate` 的判据口（W57 B2a 有意换成真 collider）。
                                itT.SimulateHover(cvT16.HitLocalToWorldForTest(0f, dyT16));
                                Vector3 inA = cvT16.HitLocalToWorldForTest(hwT16 * 0.86f, dyT16);
                                Vector3 inB = cvT16.HitLocalToWorldForTest(hwT16 * 0.90f, dyT16);
                                Vector3 outB = cvT16.HitLocalToWorldForTest(hwT16 * 1.10f, dyT16);
                                // 前提①：真 collider 自己的判据（内侧在内 / 外侧在外）—— 不成立说明几何与假设不符。
                                Check(halfWT16 > 0f && cvT16.HitByCollider(inB) && !cvT16.HitByCollider(outB),
                                      $"★ T16：（前提）真 collider：`inB` 在内 / `outB` 在外"
                                    + $"（宽 {cvT16.ColliderSizeForTest.x:F4} · offset.y {dyT16:F4}）");
                                // 前提②：按下点命中的**就是 `cvT16`**（`Frontmost` 不许取到邻卡 ——
                                //   那会让锁存落在别人身上，下面测的就不是这张卡了）。
                                Check(itT.HitCardForTest(inB) == kT16,
                                      $"★ T16：（前提）`inB` 命中的就是 `cvT16`（手牌第 {kT16} 张），不是邻卡"
                                    + $"（`HitTest` 实得第 {itT.HitCardForTest(inB)} 张）");

                                // ① 出卡那一档 ⇒ `allowClick` 必须被清 0，且松手不许出点击
                                itT.SimulateHover(inB);
                                itT.SimulatePressPendingForTest(inB);
                                Check(itT.PressInsideForTest,
                                      "★ T16：按下点在卡的命中区内 ⇒ 锁存为 1（原版 `OnPointerDown` 置 `allowClick`）");
                                itT.SimulatePendingTickForTest(outB);
                                Check(!itT.PressInsideForTest,
                                      "★ T16：指针挪出卡的命中区 ⇒ 锁存清 0（原版 `OnPointerExit` 清 `allowClick`）");
                                bool dispT16 = drv.CardDisplay != null && drv.CardDisplay.Visible;
                                itT.SimulatePendingReleaseForTest(outB);
                                Check(drv.CardDisplay == null || drv.CardDisplay.Visible == dispT16,
                                      "★ T16：**按在卡缘、在卡外松手 ⇒ 不产生点击**（原版 `OnPointerClick` 看 `allowClick`）"
                                    + "｜🧨 改坏法：`EndPressCandidate` 去掉 `_pressInside` ⇒ 这条红");

                                // ② 灭自证：同样 0.02 位移、但整段留在卡内 ⇒ 必须仍然算轻点（开关展示窗）
                                bool dispT16b = drv.CardDisplay != null && drv.CardDisplay.Visible;
                                itT.SimulateHover(inA);
                                itT.SimulatePressPendingForTest(inA);
                                itT.SimulatePendingTickForTest(inB);
                                Check(itT.PressInsideForTest,
                                      "★ T16（灭自证）：同样的位移量但没出卡 ⇒ 锁存**仍为 1**"
                                    + "（证明上一条不是「什么位移都拦」）");
                                itT.SimulatePendingReleaseForTest(inB);
                                Check(drv.CardDisplay != null && drv.CardDisplay.Visible != dispT16b,
                                      "★ T16（灭自证）：卡内松手 ⇒ **仍然是轻点**（开关卡面展示窗）");
                                // 收工：再点一下把展示窗恢复回去（免得影响后面别的断言）
                                itT.SimulateHover(inA);
                                itT.SimulatePressPendingForTest(inA);
                                itT.SimulatePendingReleaseForTest(inA);
                            }
                        }
                    }

                    SettingsWindow.GeneralFlags.TouchInput = savedTouchT;
                    SettingsWindow.GeneralFlags.PersistOverride = savedPersistT;
                    drv.mulliganEnabled = savedMulT;
                    drv.offensivePhaseEnabled = savedOffT;
                }

                // ---- 17·1 🔴 **A1541**：选完进攻卡 / 防御卡之后，面板里那批**调用方现建**的卡必须被销毁 ----
                // 现场：`OnOffensiveDone` / `OnDefensiveDone` 只调 `_choosePanel.Close()`，而那 3~4 张卡视图
                //   原先是**局部变量 `views`**（出了作用域就没人引用）⇒ 面板关掉后卡**永远留在屏幕正中**，
                //   而且它们不在任何命中链里 ⇒ 点它、按 ESC 都没反应（用户 2026-10-11 真机点名的那一条）。
                // 判据（**原版两件都做**）：`ChooseCardMenu__ProcessChooseDone.c` 先
                //   `ShowChooseCardElements(this,false)`（内含 `ShowChooseCards(false)`，逐张 `SetActive(false)`），
                //   再遍历 `ChooseCardMenuAnchor` 的子节点 `UnityEngine.Object.Destroy(gameObject)`。
                // 🧨 改坏法：把 `OnOffensiveDone` / `OnDefensiveDone` 里的 `ClearEnvPickViews()` 删掉 ⇒ 本格两条红。
                // ⚠️ 判据**按树数**（`PanelCardViewsAlive`），⛔ 不是查我们那个列表 —— 病灶恰恰是
                //    「列表没人引用、卡还在树上」，查列表等于让被测实现自己证明自己。
                {
                    bool savedOff1 = drv.offensivePhaseEnabled, savedMul1 = drv.mulliganEnabled;
                    bool savedCard1 = drv.offensiveCardEnabled;
                    bool savedDef1 = drv.defensiveCardPanelEnabled;
                    drv.mulliganEnabled = true;
                    drv.offensivePhaseEnabled = true;    // 这一格**要**走「选进攻卡」那一段
                    drv.offensiveCardEnabled = true;     // 🔴 2026-10-11 用户只关进攻卡（`false` 是默认值）⇒
                                                         //    这一格验的是**备份里的那套代码**，必须显式打开
                    // 🔴 **2026-10-12（`A1664`）**：**防御卡那半也显式打开** —— 本格验的是
                    //   「`ClearEnvPickViews()` 被调了吗」（`OnOffensiveDone` / `OnDefensiveDone` 各一份），
                    //   **哪扇面板开都算**（本机是先手 ⇒ 进攻卡那扇；是后手 ⇒ 防御卡那扇）。
                    //   ⛔ 不开的话：本机若是后手，本格会**因为「防御卡面板不弹」而假红**
                    //   —— 那是 `A1664` 的**预期行为**，不是缺陷。
                    drv.defensiveCardPanelEnabled = true;
                    // 🔴 **2026-10-13（`A1088` / `A1743`）：这一行【必须锁先手方】—— 别把 `firstSeatOverride` 删掉。**
                    //   本格要的是**「换牌完成后有一扇进攻/防御面板停在那儿」**这个场景，它**自己没锁先手方**：
                    //   不锁 ⇒ 先手 = `ForceFirstSeat`，而默认是 **`0`（本机先手）** ⇒ 走**进攻**那扇
                    //   ⇒ 那个池子的阵营 = **后手方**（= `Begin` 的第 2 实参 `Goff`），而 `Goff` 的锻造等级是 3
                    //   ⇒ `OffensiveCards` 的三张最小档都是 **4** ⇒ 那道 `forgeLevel` 闸（`A1743`）把三张**全挡掉**
                    //   ⇒ `list.Count < 2` ⇒ `BattleDriver` 照原版**不弹菜单** ⇒ 下面那条前提当场红。
                    //   ⚠️ **那红不是缺陷**：原版同情境（池子阵营等级 < 4 且 `justOwnedCards = true`）**也不弹**
                    //     （`…MoveNext.c` 的 `列表<2` 那一支直接 `ClickChosenCardDone(list[0])`）。
                    //   ⇒ 锁成本机**后手**：走**防御**那扇、池子 = 本机阵营（`Ultramarines`，等级 50）⇒ 3 张 ⇒ 绿。
                    //   （写法与同族 `17·2(b)/(c)` **同一条**：`1 - drv.MyIndex`。）
                    //   📌 进攻那半的「面板关掉之后卡视图清干净了吗」由 **17·2(e)** 接着验（本笔新增）。
                    drv.Begin("Ultramarines", "Goff", 20260917, firstSeatOverride: 1 - drv.MyIndex);
                    if (drv.InMulligan) drv.SimulateMulliganDone();
                    var cp1 = drv.Choose;
                    Check(cp1 != null && cp1.Visible,
                          "★ A1541（前提）换牌完成后「选进攻卡/防御卡」面板开着（两个开关都显式打开）");
                    if (cp1 != null && cp1.Visible)
                    {
                        int cardsIn = drv.PanelCardViewsAlive();
                        Check(cardsIn > 0,
                              $"★ A1541（前提）面板里**真的摆了卡**（{cardsIn} 张）—— 一张都没有时下面那条等于没验");
                        drv.SimulateChoosePick(0);
                        drv.SimulateChooseDone();
                        Check(!cp1.Visible, "★ A1541：点「继续」之后面板关了");
                        int left = drv.PanelCardViewsAlive();
                        Check(left == 0,
                              $"★ A1541：面板里那批卡视图**一张都不剩**（现存活的 {left} 张）"
                            + "｜🧨 改坏法：删掉 `ClearEnvPickViews()` ⇒ 卡永远留在屏幕正中、点不动也关不掉");
                        int leftAll = drv.PanelCardViewsAlive(false);
                        Check(leftAll == 0,
                              $"★ A1541：连**藏起来的**也没有（含 inactive 共 {leftAll} 张）—— 原版是**销毁**、不是只隐藏");
                    }
                    drv.offensivePhaseEnabled = savedOff1;
                    drv.mulliganEnabled = savedMul1;
                    drv.offensiveCardEnabled = savedCard1;
                    drv.defensiveCardPanelEnabled = savedDef1;
                }

                // ---- 17·2 🔴 **2026-10-11 用户口径**：进攻卡暂时不要、**防御卡照旧要** ----
                // 用户两次原话（第二次是**纠正**）：「面板/功能都暂时不要了……先把场景复刻好」→
                //   我按「整段都关」做了一版 → 用户当场订正「**防御卡需要，不要的是进攻卡。**」
                // ⇒ 判据（**必须是两半都断**，只断一半就是本条要治的病）：
                //   · 本机**先手** ⇒ **不弹**「选择进攻卡」面板，也没人替我们选进攻卡
                //     ⇒ HUD 那颗进攻卡钮**不亮**、**战场停在默认环境**（用户要的「只用 13 个默认场景的默认环境」）；
                //   · 本机**后手** ⇒ 防御卡**直接进手牌、不经面板**。
                //     🔴 **2026-10-12（`A1664`）就地订正（铁律 5）**：这一行原来写「「选择防御卡」面板**照旧弹**」
                //        —— **已不成立**：原版 `ShouldUseEnviromentalEffects()` **恒 `false`**（反汇编实证）
                //        ⇒ 面板永不弹，后手那张卡由 `RuleCore.GrantDefenceCard` 直接发（判据 → (b)(c) 那两格）。
                //        ⚠️ 用户口径**没变**：防御卡照旧要（照旧发进手牌），被关掉的是「**选**」这一步。
                // 🧨 改坏法：把 `offensiveCardEnabled` 那两句判据删掉（退回「整段一起关」）⇒ 先手那半红；
                //   把 `offensivePhaseEnabled` 直接改成 `false` ⇒ 先手那半也红（面板会在那儿假弹）。
                {
                    bool savedOff2 = drv.offensivePhaseEnabled, savedCard2 = drv.offensiveCardEnabled;
                    bool savedMul2 = drv.mulliganEnabled;
                    drv.mulliganEnabled = true;
                    drv.offensivePhaseEnabled = true;      // 整段开着
                    drv.offensiveCardEnabled = false;      // 只关进攻卡（这也正是出厂默认值）

                    // (a) 本机是**先手** ⇒ 进攻卡那扇面板不弹
                    drv.Begin("Ultramarines", "Goff", 20260917, firstSeatOverride: drv.MyIndex);
                    Check(drv.Ctx.FirstSeat == drv.MyIndex, "★ 用户口径（前提）本局本机是先手");
                    if (drv.InMulligan) drv.SimulateMulliganDone();
                    Check(drv.Choose == null || !drv.Choose.Visible,
                          "★ 用户口径：本机**先手**时**不弹**「选择进攻卡」面板（进攻卡暂时不要）"
                        + "｜🧨 改坏法：删掉 `BeginOffensivePhaseIfAny` 里那句 `if (!offensiveCardEnabled) return false;` ⇒ 红");
                    Check(!drv.OffensiveButtonVisible,
                          "★ 用户口径：没人选进攻卡 ⇒ HUD 那颗进攻卡钮**不亮**（战场停在默认环境）"
                        + "｜🧨 判据 = 原版只在「选定卡 ≠ 空卡」时才 `SetActive(true)`");

                    // (b) 本机是**后手** ⇒ 防御卡**不经面板**、直接进手牌
                    //   🔴 **2026-10-12（`A1664`，用户真机点名「为什么可以选择防御卡，防御卡是放在卡组，
                    //     后手的时候直接在手卡，这个是给后手玩家的补偿」）**：原版那扇门
                    //     `BattleManager.ShouldUseEnviromentalEffects()` **恒 `false`**
                    //     （反汇编 `VA 0x1806FB110` 的字节 = `32 c0 c3` = `xor al,al; ret`；`dump.cs` /
                    //     `script.json` 的 RVA 都是 `0x6FB110`）⇒ 面板**永不弹**；后手那张卡由
                    //     `RuleCore.GrantDefenceCard`（`EndMulligan` 那条）**直接进手牌**（= 原版
                    //     `StartBattlePhase` → `AddGoesSecondCardToDeck` → `AddNewCardToHand`）。
                    //   ⚠️ 本格**同时把 `offensivePhaseEnabled` 开着**（`savedOff2` 那一对）—— 这样
                    //     「本机后手不弹防御面板」就**不是**因为「整段关了」而假绿。
                    //   🧨 改坏法：把 `defensiveCardPanelEnabled` 默认值改回 `true`（或删掉分支③那句闸）⇒ 第一条红；
                    //     把发卡那一步弄丢 ⇒ 第二条红（手里没那张卡）。
                    bool savedDef2 = drv.defensiveCardPanelEnabled;
                    drv.defensiveCardPanelEnabled = false;         // = 出厂默认值（这里显式写出来）
                    drv.Begin("Ultramarines", "Goff", 20260917, firstSeatOverride: 1 - drv.MyIndex);
                    Check(drv.Ctx.FirstSeat != drv.MyIndex, "★ A1664（前提）本局本机是后手");
                    if (drv.InMulligan) drv.SimulateMulliganDone();
                    int defsN2 = drv.DefensiveChoicesForTest(drv.MyFactionForTest).Count;
                    if (defsN2 == 0) Check(false, "★ A1664（前提）本阵营卡池里**有**防御卡 —— 没有的话下面那条验不了");
                    Check(drv.Choose == null || !drv.Choose.Visible,
                          "★ A1664：本机**后手**时**不弹**「选择防御卡」面板（原版那扇门恒 `false` ⇒ 没有这一步）"
                        + "｜🧨 改坏法：`defensiveCardPanelEnabled` 改回 `true` 或删掉分支③那句 `return false` ⇒ 红");
                    int defInHand2 = 0; CardDef lastDef2 = null;
                    foreach (var h in drv.Ctx.Players[drv.MyIndex].Hand)
                        if (h != null && h.Card != null && h.Card.Type == "defence") { defInHand2++; lastDef2 = h.Card; }
                    Check(defInHand2 == 1,
                          $"★ A1664：……后手那张防御卡**照旧发进手牌**（手里 {defInHand2} 张，"
                        + $"「{lastDef2?.Name ?? "<无>"}」）—— 关掉的只是「**选**」这一步"
                        + "｜判据 = `RuleCore.GrantDefenceCard`（`EndMulligan`）"
                        + "｜🧨 改坏法：把它当成「防御卡不要了」一起关掉 ⇒ 红");

                    // (c) 🗄 **备份路径不许烂**（铁律 11 例外②）：开关打开 ⇒ 那扇面板**照旧弹**、选完**换进手牌**
                    //   （`OnDefensiveDone` / `SetDefensiveCard` / `DefensiveChoices` 一行没删，得有人跑它）。
                    drv.defensiveCardPanelEnabled = true;
                    drv.Begin("Ultramarines", "Goff", 20260917, firstSeatOverride: 1 - drv.MyIndex);
                    if (drv.InMulligan) drv.SimulateMulliganDone();
                    Check(drv.Choose != null && drv.Choose.Visible,
                          "★ A1664（备份路径）：开关置 `true` ⇒ 「选择防御卡」面板**照旧弹**（代码一行没删）");
                    // 🔴 **2026-10-20（`W57` · 战斗线 `T09`-CONFIRM）：确认钮开局 `interactable = false`、
                    //   选中一张后才启用** ⇒ 这里必须先真选一张（⛔ 直接点「继续」会被面板吞掉、
                    //   面板不关、后面那条「换进手牌」必红）。判据 → `W57` · `T09-CONFIRM` 报告。
                    if (drv.Choose != null && drv.Choose.Visible)
                    {
                        drv.SimulateChoosePick(0);
                        drv.SimulateChooseDone();
                    }
                    int defInHand3 = 0;
                    foreach (var h in drv.Ctx.Players[drv.MyIndex].Hand)
                        if (h != null && h.Card != null && h.Card.Type == "defence") defInHand3++;
                    Check(defInHand3 == 1,
                          $"★ A1664（备份路径）：选完**换进手牌**、而且手里**只有 1 张**（实得 {defInHand3} 张）"
                        + " —— 判据 = `SetDefensiveCard` 会**先把原来那张摘掉**再加新的（否则手里两张）");

                    drv.defensiveCardPanelEnabled = savedDef2;
                    drv.offensivePhaseEnabled = savedOff2;
                    drv.offensiveCardEnabled = savedCard2;
                    drv.mulliganEnabled = savedMul2;
                }

                // ---- 🆕 2026-10-13（`A1088`）17·2(d)：**面板摆的是【闸过】的那一份**（生产路径接线） ----
                // 为什么单开一格：上面那几条断的是**纯函数**（`DefensiveChoicesOwnedAt`）——
                //   把闸写成一个**没人调**的辅助函数、面板照旧用未筛那份，上面全绿。
                //   🔴 判别的做法：把本阵营的锻造等级**临时压到 3**（原版 SO 的三个 `forgeLevel` = 1/20/40
                //   ⇒ 等级 3 **只够第 1 张**）—— 若面板用的是**未筛**那份，这里会数到 3 张 ⇒ 红。
                // ⚠️ `ForgeData` 是全局静态 ⇒ **无论走哪条分支都要还原**（这里用 `savedLv3` 原值还原）。
                // 🧨 改坏法：把面板那句 `DefensiveChoicesOwned` 换回 `DefensiveChoices`（或闸只写不用）⇒ 本格红。
                {
                    bool savedDef3 = drv.defensiveCardPanelEnabled;
                    bool savedOff3 = drv.offensivePhaseEnabled;
                    bool savedMul3 = drv.mulliganEnabled;
                    // ⚠️ 阵营名用**字面量**（= 下面 `Begin` 的第一个实参）—— 面板的池子就是「本机阵营」，
                    //   所以压等级的必须是**同一个**阵营；压错阵营 ⇒ 本格会假红。
                    //   `MyFactionForTest == myF3` 那条就是钉死这一点的。
                    string myF3 = "Ultramarines";
                    int savedLv3 = ForgeData.LevelOf(myF3);
                    drv.mulliganEnabled = true;
                    drv.offensivePhaseEnabled = true;      // 别让「整段关了」把面板不弹说成是对的
                    drv.defensiveCardPanelEnabled = true;
                    ForgeData.SetLevelForTest(myF3, 3);    // 原版 SO：槽 0 = 1 级 · 槽 1 = 20 · 槽 2 = 40
                    drv.Begin(myF3, "Goff", 20260917, firstSeatOverride: 1 - drv.MyIndex);
                    if (drv.InMulligan) drv.SimulateMulliganDone();
                    Check(drv.MyFactionForTest == myF3,
                          $"★ A1088（前提）本机的阵营 = 被压等级的那个（`{myF3}`；实得「{drv.MyFactionForTest}」）"
                        + " —— 不是同一个的话下面那条等于没验");
                    bool panelOpen3 = drv.Choose != null && drv.Choose.Visible;
                    Check(panelOpen3,
                          "★ A1088（前提）锻造等级压到 3 ⇒ 那扇「选择防御卡」面板**照旧弹**"
                        + "（闸只**少给卡**、不弹窗 —— 原版那道闸在 `GetEnvCardList` 里，不在弹窗判据里）");
                    if (panelOpen3)
                    {
                        int shown3 = drv.PanelCardViewsAlive();
                        Check(shown3 == 1,
                              $"★ A1088：面板上**只摆 1 张**（本阵营 {myF3} 锻造等级 3 · 原版 SO 槽 1/2 要 20/40 级"
                            + $" ⇒ 那两张被**丢掉**；实得 {shown3} 张）"
                            + "｜🧨 改坏法：面板那句 `DefensiveChoicesOwned` 换回未筛的 `DefensiveChoices` ⇒ 数到 3");
                        int defInHand3 = 0;
                        foreach (var h in drv.Ctx.Players[drv.MyIndex].Hand)
                            if (h != null && h.Card != null && h.Card.Type == "defence") defInHand3++;
                        // 🔴 **2026-10-20（`W57` · 战斗线 `T09`-CONFIRM）：原来这里只调 `SimulateChooseDone()`，
                        //   注释写「选下标 0」却**根本没选** —— 确认钮现在开局 `interactable = false`、
                        //   选中后才启用 ⇒ 不先选一张，这一下会被面板吞掉（面板不关、换牌不发生）。
                        //   ⛔ 补的是**真选**（走面板命中判定），不是直接写选中状态。
                        drv.SimulateChoosePick(0);
                        drv.SimulateChooseDone();          // ⚠️ 在**还压着等级**时走完（选下标 0 = 闸过那份的第 0 张）
                        var ownedAt3 = drv.DefensiveChoicesOwnedAtForTest(myF3, 3);
                        string want3 = (ownedAt3.Count > 0 && ownedAt3[0] != null) ? ownedAt3[0].Name : "<闸过那份是空的>";
                        int defAfter3 = 0; CardDef lastDef3 = null;
                        foreach (var h in drv.Ctx.Players[drv.MyIndex].Hand)
                            if (h != null && h.Card != null && h.Card.Type == "defence") { defAfter3++; lastDef3 = h.Card; }
                        Check(defAfter3 == 1 && lastDef3 != null && lastDef3.Name == want3,
                              $"★ A1088：选完**换进手牌的就是面板上那一张**（「{lastDef3?.Name ?? "<无>"}」"
                            + $" · 期望「{want3}」· 选前手里 {defInHand3} 张 → 选后 {defAfter3} 张）"
                            + " —— 这条挡「面板按闸过的取下标、发卡却按未筛那份取」的**静默错位**");
                    }
                    ForgeData.SetLevelForTest(myF3, savedLv3);
                    drv.defensiveCardPanelEnabled = savedDef3;
                    drv.offensivePhaseEnabled = savedOff3;
                    drv.mulliganEnabled = savedMul3;
                }

                // ---- 🆕 2026-10-13（`A1743`）17·2(e)：**进攻面板摆的也是【闸过】那份**（对称的那一半） ----
                // 与上面 17·2(d) 是**同一道闸的两个方向**：`MoveNext:63` 那**同一句**
                //   （`justOwnedCards = true`）在本机**先手**时落在**进攻池**上。
                // 🔴 判别的做法：把**池子那个阵营**（本机先手时 = 后手方 = 对手）的锻造等级压到 **4**
                //   （原版 SO：进攻侧最小档就是 4）⇒ 面板应摆 **2 张**（空卡 + SO 槽 0）；
                //   若面板用的还是**未筛**那份 ⇒ 数到 4 ⇒ 红。
                // ⚠️ 压的是**池子阵营**、不是本机阵营 —— 池子恒取后手那一方（§3.1 三处证据）。
                // 🧨 改坏法：把面板那句 `OffensiveChoicesOwned` 换回 `OffensiveCards.Choices` ⇒ 本格红。
                {
                    bool savedCardE = drv.offensiveCardEnabled, savedPhaseE = drv.offensivePhaseEnabled;
                    bool savedMulE = drv.mulliganEnabled, savedDefE = drv.defensiveCardPanelEnabled;
                    // 池子阵营：本自检里 `_me == 0`、`firstSeatOverride = 本机` ⇒ 后手方 = `Begin` 的第 2 个实参
                    //   ⇒ 就是 `"Goff"`。下面那条「池子 == Goff」的断言**钉住这个前提**（不是同一个就当场红）。
                    string poolE = "Goff";
                    int savedLvE = ForgeData.LevelOf(poolE);
                    drv.mulliganEnabled = true;
                    drv.offensivePhaseEnabled = true;
                    drv.offensiveCardEnabled = true;          // 出厂默认 `false`（用户 2026-10-11 拍板）⇒ 显式打开
                    drv.defensiveCardPanelEnabled = false;    // 别让防御那扇替它开
                    ForgeData.SetLevelForTest(poolE, 4);      // 原版 SO：进攻侧最小档 = 4 ⇒ 只够槽 0
                    drv.Begin("Ultramarines", poolE, 20260917, firstSeatOverride: drv.MyIndex);
                    if (drv.InMulligan) drv.SimulateMulliganDone();
                    Check(drv.Ctx.FirstSeat == drv.MyIndex, "★ A1743（前提）本局本机是**先手** ⇒ 走「选进攻卡」那扇");
                    Check(drv.OffensivePoolFaction == poolE,
                          $"★ A1743（前提）进攻池用的就是被压等级的那个阵营（期望 `{poolE}` · 实得 `{drv.OffensivePoolFaction}`）"
                        + " —— 不是同一个的话下面那条等于没验");
                    bool openE = drv.Choose != null && drv.Choose.Visible;
                    Check(openE,
                          $"★ A1743（前提）池子阵营（`{poolE}`）锻造等级 4 ⇒ 面板**照旧弹**（闸只**少给卡**、不弹窗）");
                    if (openE)
                    {
                        int shownE = drv.PanelCardViewsAlive();
                        Check(shownE == 2,
                              $"★ A1743：面板上**摆了 2 张**（「不使用进攻卡」+ SO 槽 0；原版 SO 槽 1/2 要 25/45 级"
                            + $" ⇒ 被**丢掉**；实得 {shownE} 张）"
                            + "｜🧨 改坏法：面板那句换回未筛的 `OffensiveCards.Choices` ⇒ 数到 4");
                        drv.SimulateChoosePick(1);            // 下标 1 = 闸过那份里的 SO 槽 0
                        drv.SimulateChooseDone();
                        Check(drv.Ctx.OffensiveSlotIdx == 0,
                              $"★ A1743：面板选中的**落进记录的是 SO 槽号 0**（实得 {drv.Ctx.OffensiveSlotIdx}）"
                            + " —— 面板下标 → `c.idx` 这条映射是通的（发出去的网络包/录像用的也是 `c.idx`）");
                        // 🔴 **补回 17·1 丢掉的那半覆盖**：17·1 现在锁了「本机后手」（走防御那扇）⇒
                        //   **`OnOffensiveDone` 那条 `ClearEnvPickViews()`** 不再被它跑到 ⇒ 这里接上
                        //   （判据与 17·1 同一条：原版 `ChooseCardMenu.ProcessChooseDone` 是**隐藏 + 销毁两件都做**）。
                        Check(!drv.Choose.Visible, "★ A1743：进攻面板点「继续」之后**关了**");
                        int leftE = drv.PanelCardViewsAlive();
                        Check(leftE == 0,
                              $"★ A1743：进攻面板那批卡视图**一张都不剩**（现存活的 {leftE} 张）"
                            + "｜🧨 改坏法：删掉 `OnOffensiveDone` 里的 `ClearEnvPickViews()` ⇒ 本格红"
                            + "（17·1 已改锁后手 ⇒ 它不再覆盖这半，本格是**唯一**守这条的）");
                        int leftAllE = drv.PanelCardViewsAlive(false);
                        Check(leftAllE == 0,
                              $"★ A1743：连**藏起来的**也没有（含 inactive 共 {leftAllE} 张）—— 原版是**销毁**、不是只隐藏");
                    }
                    ForgeData.SetLevelForTest(poolE, savedLvE);
                    drv.offensiveCardEnabled = savedCardE;
                    drv.offensivePhaseEnabled = savedPhaseE;
                    drv.mulliganEnabled = savedMulE;
                    drv.defensiveCardPanelEnabled = savedDefE;
                }

                bool saved = drv.mulliganEnabled;
                drv.mulliganEnabled = true;
                // 🆕 2026-09-29（§25）：**这一段也要把「选进攻卡」关掉** —— 换牌一完成，原版就会弹
                //   `SetupEnviromentalEffectPhase` 那个面板并**停住**（等玩家点「继续」）；
                //   这一节验的是换牌本身，不停住的话「这时才发能量 / 抽第 1 张」那些断言会假红
                //   （2026-09-29 实测：三条红都是这么来的）。
                bool savedOff = drv.offensivePhaseEnabled;
                drv.offensivePhaseEnabled = false;
                drv.Begin("Ultramarines", "Goff", 20260917);

                Check(drv.InMulligan, "Begin 之后**先进换牌阶段**");
                // 这两条是「换牌发生在 BeginTurn 之前」的硬证据
                Check(drv.Ctx.Players[0].Energy == 0, $"……这时**还没发能量**（{drv.Ctx.Players[0].Energy}）");
                Check(drv.Ctx.Players[0].Hand.Count == RuleCore.StartHand,
                      $"……也**还没抽第 1 张**（手牌 {drv.Ctx.Players[0].Hand.Count} = 起手 {RuleCore.StartHand}）");

                var mp = drv.Mulligan;
                Check(mp != null && mp.Visible, "换牌面板开着");
                Check(mp.BarHasArt && mp.PlayHasArt && mp.EyeHasArt,
                      $"面板的件都取到图了（底「{mp.BarTex}」/ 眼睛「{mp.EyeTex}」）");
                Check(mp.CardButtonCount == drv.HandCount,
                      $"每张起手牌上都贴了「换」按钮（{mp.CardButtonCount} 个 == 手牌 {drv.HandCount} 张）");
                // 🆕 **2026-10-18（W6）**：那颗钮上的字 = **原版词条** `Battle/Mulligan/Replace`
                //    （TMP 原文 `Replace`；原来写死中文 `"换"`）。
                Check(mp.CardButtonCount > 0 && mp.CardBtnWordAt(0) == Loc.T(MulliganPanel.ReplaceTerm),
                      $"★ 卡上那颗钮写的「{mp.CardBtnWordAt(0)}」= `Loc.T({MulliganPanel.ReplaceTerm})`"
                    + $"（当前语档 {Loc.Current}；原版 TMP 原文 `Replace`）");
                // 🆕 **2026-10-18（第十三轮 · G2b）**：**同一颗钮的第二档** —— 那张牌被标记要换之后，
                //    原版会把**同一个 `Localize` 的 term** 换成 `Battle/Mulligan/Undo`
                //    （`MulliganFrame.{ChangeCardButtonOnClick,SetupMulligan,UpdateButtonText}` 三处逐字相同）
                //    ⇒ 上面那条「一直写着 `Replace`」只覆盖了**未标记**那一档。
                //    ⚠️ 结尾**必须复原**（后面几节还要用这块面板，且不许留标记）。
                Check(Loc.HasEntry(MulliganPanel.UndoTerm),
                      $"★（坑表 #18）`Loc` 表里**真有** `{MulliganPanel.UndoTerm}` —— 原版有 ≠ 我们表里有");
                {
                    bool markedBeforeU = mp.IsMarked(0);
                    mp.ToggleMark(0);
                    Check(mp.CardBtnWordAt(0) == Loc.T(MulliganPanel.UndoTerm),
                          $"★ 标记后的那张牌，钮上写「{mp.CardBtnWordAt(0)}」= `Loc.T({MulliganPanel.UndoTerm})`"
                        + " —— 判据 = `MulliganFrame.UpdateButtonText`：`card+0x228 == 0xe ⇒ Undo`"
                        + $"（⛔ 原来只有一档、标记之后还写着「{Loc.T(MulliganPanel.ReplaceTerm)}」）");
                    Check(mp.CardBtnWordAt(0) != Loc.T(MulliganPanel.ReplaceTerm),
                          "★ 判别式：两档**必须不是同一串**（否则上面那条等于没查）");
                    if (mp.CardButtonCount > 1)
                        Check(mp.CardBtnWordAt(1) == Loc.T(MulliganPanel.ReplaceTerm),
                              $"★ 没标记的第 2 张仍是「{mp.CardBtnWordAt(1)}」= `Loc.T({MulliganPanel.ReplaceTerm})`"
                            + " —— 档是**逐张**的（判据：原版三处读的都是**那张卡自己**的 `+0x228`）");
                    mp.ToggleMark(0);      // 还原（来回一次 = 两档都走到过）
                    Check(mp.IsMarked(0) == markedBeforeU && mp.CardBtnWordAt(0) == Loc.T(MulliganPanel.ReplaceTerm),
                          $"★ 取消标记后复原（标记 {mp.IsMarked(0)}，钮上「{mp.CardBtnWordAt(0)}」）");
                }

                // ---- 17·3 🔴 **A1663**：点手牌本身 = **看牌**（不是标记）----
                // 用户 2026-10-12 真机点名：「战斗开始前替换手牌的阶段，你搞错了，**不是点击手卡替换**」。
                // 判据（原版，唯一一处）= `CardScript__OnTouchUpAsButton.c:52-58`：换牌期
                //   `cardState ∈ {0xD,0xE}` 这一段只做「置 `displayingCardFlag(+0x24a)` →
                //   `BattleManager.DisplayCard(bm, this, 1, 1)`」（第 4 参 = 强制展示）；指针移开由
                //   `OnTouchExit.c:15-16` 收。**标记只走每张卡上那颗「换」钮**（`ClickMulliganSelected`）。
                //   ⇒ 我们原来那条「点卡也能标记」是**自己加的**（`MulliganPanel.HandleClick` 里，
                //     注释自己招过「点卡这条路是我们加的」）—— 它把原版这条路整个盖住了，所以**一条断言都没有**、
                //     这个偏离一路活到今天。本轮删掉那条路、把 `OnCardSeen` 回调接回 `OnCardTapped`。
                // 🧨 改坏法：把 `HandleClick` 里那句 `OnCardSeen` 回调删掉（或把卡命中的分支写回
                //   `ToggleMark`）⇒ 下面**成对**的两条里**必有一条红**（这正是灭自证的用意）。
                {
                    var hvA = drv.HandViewAt(0);
                    Check(hvA != null, "★ A1663（前提）取得到第 1 张手牌的视图");
                    Check(mp.CardButtonCount > 1, "★ A1663（前提）起手至少 2 张（下面灭自证那条要点第 2 张）");
                    Check(drv.CardDisplay != null, "★ A1663（前提）卡牌展示窗那一套在位");
                    if (hvA != null && mp.CardButtonCount > 1 && drv.CardDisplay != null)
                    {
                        drv.CardDisplay.Hide();                     // 从「窗关着」这一档起（两态都走到）
                        int marksBefore = mp.Marked.Count;
                        string wordBefore = mp.CardBtnWordAt(0);
                        string title0 = hvA.Data.title;
                        bool tapTaken = drv.SimulateMulliganCardTap(0);
                        Check(tapTaken, "★ A1663（前提）这一下点**被面板收下**了（没收下就不能怪下面两条）");
                        Check(mp.Marked.Count == marksBefore && !mp.IsMarked(0) && mp.CardBtnWordAt(0) == wordBefore,
                              $"★ A1663：点手牌本身**不产生标记**（标记 {marksBefore} → {mp.Marked.Count}；"
                            + $"那颗钮上仍是「{mp.CardBtnWordAt(0)}」）"
                            + "｜🧨 改坏法：把点卡那条写回 `ToggleMark`（= 原来那条我们加的路）⇒ 红");
                        Check(drv.CardDisplay.Visible && drv.CardDisplay.ShownTitle == title0,
                              $"★ A1663：点手牌本身 = **把这张牌放大展示**（现展示「{drv.CardDisplay.ShownTitle}」，"
                            + $"手牌第 1 张是「{title0}」）｜判据 = `CardScript.OnTouchUpAsButton` → "
                            + "`BattleManager.DisplayCard(card,1,1)`｜🧨 改坏法：不接 `OnCardSeen` 回调 ⇒ 窗不开 ⇒ 红");
                        drv.CardDisplay.Hide();

                        // 🔴 **灭自证（这一对是结构上互斥的，必须两条都断）**：
                        //   点那张牌的「换」**钮** ⇒ 标记 + **不开**展示窗；
                        //   点**卡**（上面那条）⇒ 开窗 + **不标记**。
                        //   只断其中一条的话，「点卡 = 标记 + 不开窗」（改回旧写法）照样能全绿。
                        Check(drv.SimulateMulliganToggle(1) && mp.IsMarked(1) && !drv.CardDisplay.Visible,
                              "★ A1663（**灭自证**）：点那张牌的「换」**钮** ⇒ 标记上了，而展示窗**不开**"
                            + "（原版两条路是分开的：钮 = `ClickMulliganSelected`、卡 = `DisplayCard`）");
                        drv.SimulateMulliganToggle(1);          // 还原（后面几节还要用这块面板）
                        Check(!mp.IsMarked(1) && mp.Marked.Count == marksBefore,
                              $"★ A1663（收尾）标记复原（现在 {mp.Marked.Count} 个，进来时 {marksBefore} 个）");
                    }
                }

                // ---- 🆕 2026-10-19（`T03`）：**第 3 处调用点** = 换牌 `MulliganPanel.CardAt` ----
                //  判据 = 原版 `2DCard` 的 `BoxCollider2D` 主面 **in-hand 档 1.97 × 3.0502 @ y −0.0151**
                //  （换牌期那几张就是**同一批手牌对象** —— `MulliganPanel.BuildCardButtons` 只搬位置、
                //   不换 `CardFace`，所以走的是 in-hand 那一档，⛔ 不是常态档）。
                //  手法同前两组：卡局部系二分找边 → 比字面量 ≤ 1 px → 边界内/外 1 px 各问一次。
                {
                    var mvT03 = drv.HandViewAt(0);
                    Check(mvT03 != null && mp.HasCard(mvT03),
                          "★ T03：（前提）换牌区第 1 张就是手牌第 1 张（`MulliganPanel.HasCard`）");
                    if (mvT03 != null && mp.HasCard(mvT03))
                    {
                        Check(mvT03.IsHandFaceForTest,
                              "★ T03：（前提）换牌行那张卡的脸型 = `CardFace.Hand`（⇒ in-hand 档）");
                        const float halfW03m = 1.97f * 0.5f;                 // 0.985
                        const float halfH03m = 3.02f * 1.01f * 0.5f;         // 1.5251
                        const float dy03m    = -(halfH03m - 3.02f * 0.5f);    // −0.0151
                        // ⚠️ `PxPerUnit964` 那颗 const 在**别的方法**里（E2 段）⇒ 这里另起一颗同值常量
                        //    （世界单位 ↔ 画布 px；与 `BattleDriver.Px` / `PxPerUnit964` 同一个换算）。
                        const float PxPerUnit03m = 108f;
                        float pxU03m = Mathf.Abs(mvT03.transform.lossyScale.x) * PxPerUnit03m;
                        Check(pxU03m > 1f, $"★ T03：（前提）换牌卡的换算非退化（1 卡单位 = {pxU03m:F2} px）");
                        if (pxU03m > 1f)
                        {
                            float one03m = 1f / pxU03m;
                            System.Func<Vector3, bool> hitM03 = p => mp.CardAt(p) == mvT03;
                            // 🔴 **2026-10-20（W58 · P2-M）**：原签名**只回 x**（`ix + (ox-ix)*lo`）——
                            //   纵向两条传 `ix = ox = 0` ⇒ 无论 `lo` 多少都回 **0**（日志 `65211` 实得 0.0000，
                            //   而 `|0 − 1.51| <= 1px` 必红）。改成按 `vertical` 回**插值后的那个轴**；
                            //   命中判断本身没动（横向两条一直是绿的）。
                            System.Func<bool, float, float, float, float, float> edgeM03 =
                                (vertical, ix, iy, ox, oy) =>
                                {
                                    float lo = 0f, hi = 1f;
                                    for (int k = 0; k < 40; k++)
                                    {
                                        float t = (lo + hi) * 0.5f;
                                        if (hitM03(mvT03.HitLocalToWorldForTest(
                                                ix + (ox - ix) * t, iy + (oy - iy) * t))) lo = t;
                                        else hi = t;
                                    }
                                    float lx = ix + (ox - ix) * lo, ly = iy + (oy - iy) * lo;
                                    return vertical ? ly : lx;
                                };
                            float eL03m = edgeM03(false, -halfW03m + 0.05f, 0f, -halfW03m - 0.08f, 0f);
                            float eR03m = edgeM03(false,  halfW03m - 0.05f, 0f,  halfW03m + 0.08f, 0f);
                            float eT03m = edgeM03(true, 0f, dy03m + halfH03m - 0.05f, 0f, dy03m + halfH03m + 0.08f);
                            float eB03m = edgeM03(true, 0f, dy03m - halfH03m + 0.05f, 0f, dy03m - halfH03m - 0.08f);
                            bool okL03m = Mathf.Abs(eL03m - (-halfW03m)) <= one03m
                                       && hitM03(mvT03.HitLocalToWorldForTest(eL03m + one03m, 0f))
                                       && !hitM03(mvT03.HitLocalToWorldForTest(eL03m - one03m, 0f));
                            bool okR03m = Mathf.Abs(eR03m - halfW03m) <= one03m
                                       && hitM03(mvT03.HitLocalToWorldForTest(eR03m - one03m, 0f))
                                       && !hitM03(mvT03.HitLocalToWorldForTest(eR03m + one03m, 0f));
                            bool okT03m = Mathf.Abs(eT03m - (dy03m + halfH03m)) <= one03m
                                       && hitM03(mvT03.HitLocalToWorldForTest(0f, eT03m - one03m))
                                       && !hitM03(mvT03.HitLocalToWorldForTest(0f, eT03m + one03m));
                            bool okB03m = Mathf.Abs(eB03m - (dy03m - halfH03m)) <= one03m
                                       && hitM03(mvT03.HitLocalToWorldForTest(0f, eB03m + one03m))
                                       && !hitM03(mvT03.HitLocalToWorldForTest(0f, eB03m - one03m));
                            Check(okL03m && okR03m,
                                  $"★ T03：换牌行 x 两侧边界 = 原版 **±0.985** 卡单位（实得 {eL03m:F4} / {eR03m:F4}），"
                                + "且**边界内 1 px 必中 / 外 1 px 必不中**"
                                + "｜🧨 改坏法：`CardAt` 的 `Contains` 换成整卡矩形（多认 15.3 px）⇒ 红");
                            Check(okT03m && okB03m,
                                  $"★ T03：换牌行 y 上下边界 = 原版 in-hand **上沿 {dy03m + halfH03m:F4} / 下沿 {dy03m - halfH03m:F4}**"
                                + $"（实得 {eT03m:F4} / {eB03m:F4}），且**边界内 1 px 必中 / 外 1 px 必不中**"
                                + "｜🧨 改坏法：换成常态档（上沿 1.51 / 下沿 −1.51）⇒ 下沿差 5 px ⇒ 红");
                        }
                    }
                }
                // 🔴 **A245：这条原来没有判别力** —— `PromptText` 在 `_prompt == null` 时返 `"<无>"`
                //    （**非空串**）⇒ 「提示行压根没建出来」那一档**照样通过**（两态分不开 = 等于没查）。
                //    现在那个 getter 返 `null`（见 `Battle/MulliganPanel.cs` 的 `PromptText`）⇒ 两态可分了。
                //    ⚠️ 今天**不可达**（`Label.Create` 恒不返回 null）⇒ 这是**潜在**缺口、不是现患。
                //    改坏法：把 `MulliganPanel.Create` 里建 `_prompt` 那一句删掉（或让它为 null）⇒
                //    下面这条会印出 `(null …)` 并**当场红**。
                Check(!string.IsNullOrEmpty(mp.PromptText),
                      $"提示行写着「{mp.PromptText ?? "(null —— 这一行没建出来)"}」");
                // 🆕 **2026-10-18（W6）**：提示行现在是**原版词条** `Battle/Mulligan/Instructions`
                //    （TMP 原文 `Choose cards to replace in first hand`）—— 原来那串是写死的中文，
                //    而且带一个**只在中文档出现**的「（回车 = 完成）」半句（本轮按原版去掉了）。
                Check(mp.PromptText == Loc.T(MulliganPanel.PromptTerm),
                      $"★ 提示行 = `Loc.T({MulliganPanel.PromptTerm})`（当前语档 {Loc.Current}）「{mp.PromptText}」"
                    + " —— ⛔ 不再带「（回车 = 完成）」那种只在中文档出现的尾巴");
                Check(Loc.HasEntry(MulliganPanel.PromptTerm) && Loc.HasEntry(MulliganPanel.ReplaceTerm)
                   && Loc.HasEntry(MulliganPanel.DoneTerm) && Loc.HasEntry(MulliganPanel.TurnFirstTerm)
                   && Loc.HasEntry(MulliganPanel.TurnSecondTerm) && Loc.HasEntry(MulliganPanel.UndoTerm),
                      "★（坑表 #18）换牌面板用到的 **6 条键**在 `Loc` 表里全查得到"
                    + $"（`{MulliganPanel.PromptTerm}` / `{MulliganPanel.ReplaceTerm}` / `{MulliganPanel.UndoTerm}`"
                    + $" / `{MulliganPanel.DoneTerm}` / `{MulliganPanel.TurnFirstTerm}` / `{MulliganPanel.TurnSecondTerm}`）");
                // 🔴🆕 **2026-10-16（`A2102④` · `A1104` 同族）：换牌面板这几颗字【各自都有框与字号】。**
                //   判据 = 主对话现读原版那两颗 TMP 的字段（提示行：框 1307.064×69.44 / auto 18~65 / base 36；
                //   钮上「继续」：框 368.929×62.242 / auto 18~45 / base 36）。
                //   🔴 **断「渲染尺寸 ≤ 框」、不断字号** —— 字号对而溢出时自检照样全绿（`AutoFitBox` 教训）。
                //   🧨 **改坏法**：把 `MulliganPanel` 里那两句 `SetAutoFitBox` 删掉 ⇒ 落回「按框高 × 0.55/0.45 猜」
                //     那一档，**不再受这个框约束**（原来提示行实渲 43.67、原版 53.7）。
                // 🔴 **2026-10-16（`T09` 批 3）就地换量纲**：换牌面板已上 uGUI 画布 ⇒
                //   uGUI 档的 `Label.WorldW/H` **就是设计 px**（读 `TMP.textBounds`）⇒ 期望值**不再过** `LayoutSpace.Px`。
                if (mp.PromptLabel != null)
                    Check(mp.PromptLabel.WorldW <= 1307.064f + 1e-4f
                          && mp.PromptLabel.WorldH <= 69.44f + 1e-4f,
                          $"★ 提示行渲染尺寸 {mp.PromptLabel.WorldW:F4} × {mp.PromptLabel.WorldH:F4} px"
                        + $" ≤ 原版框 {1307.064f:F4} × {69.44f:F4} px（auto 18~65 · base 36）");
                if (mp.DoneLabelView != null)
                    Check(mp.DoneLabelView.WorldW <= 368.929f + 1e-4f
                          && mp.DoneLabelView.WorldH <= 62.242f + 1e-4f,
                          $"★ 「继续」那颗渲染尺寸 {mp.DoneLabelView.WorldW:F4} × {mp.DoneLabelView.WorldH:F4} px"
                        + $" ≤ 原版框 {368.929f:F4} × {62.242f:F4} px（auto 18~45 · base 36）");
                // 🆕 2026-09-26：**「你先手 / 你后手」那一行**（原版 `MulliganText/TurnText`）。
                //   🔴 **它是原版唯一一处「先手/后手」的表现** —— 原版没有硬币资产/动画/音效（判据 → §2.8）。
                Check(mp.TurnText == (drv.Ctx.FirstSeat == 0 ? MulliganPanel.TurnFirst : MulliganPanel.TurnSecond),
                      $"★ 换牌面板那行「你先手 / 你后手」跟**这一局谁先手**对得上：「{mp.TurnText}」"
                    + $"（先手 = {drv.Ctx.Players[drv.Ctx.FirstSeat].Name}）");
                // 🔴 **颜色：那两行【不是同一个颜色】—— 提示行【橙】、先后手行【白】。**
                //   **2026-10-13 就地订正（铁律 5 · `A1752`）**：本条原来断的是「两行都纯白」，判据只读了
                //   `MonoBehaviour_3731/3856` 的 `m_fontColor32`（两行都是 `0xFFFFFFFF`）——
                //   **那一半没读错，结论错了**：顶点色是**乘在材质 `_FaceColor` 上**的，而两行挂的**不是同一份材质**
                //   （`m_sharedMaterial` 是两个不同 PathID）：
                //   · 提示行 → **`Pragati-Regular Orange`**（`bundle_fonts_assets_all/Material/Material_-5772249770677823286.json`）
                //     `_FaceColor = (0.9960785, 0.5960785, 0.1176471, 1)` = **#FE981E**（材质名自己就叫 `Orange`）；
                //   · 先后手行 → `Pragati-Regular Atlas Material`（`…/Material_-5050103597772954521.json`）`_FaceColor` = 白。
                //   旁证 = 用户实拍 `C:/Users/qjh36/Desktop/warpforge参考图/战斗—替换手卡参考图（先手/后手）.png`
                //   （两行**一橙一白**，同一帧内两色不同 ⇒ 不是视频调色）。
                // ⚠️ **A195 核过：这个 `&&` 门是安全的**（没改）—— 它**不可能为假**：
                //    `Label.Create` **从不返回 null**（`Battle/Label.cs:64` 无条件 `return l`；TMP 不在时退**点阵**
                //    后端、`_tmp` 为 null 但 Label 对象照样在），而两行 label 是 `MulliganPanel.Create` 里无条件建的
                //    ⇒ 只有「整具面板没建出来」才会为空，那一档上面 `Check(mp != null && mp.Visible, "换牌面板开着")` 已经红了。
                if (mp.PromptLabel != null && mp.TurnLabel != null)
                {
                    var c1 = mp.PromptLabel.color; var c2 = mp.TurnLabel.color;
                    var wantPrompt = new Color(0.9960785f, 0.5960785f, 0.1176471f, 1f);
                    Check(Mathf.Abs(c1.r - wantPrompt.r) < 0.01f && Mathf.Abs(c1.g - wantPrompt.g) < 0.01f
                          && Mathf.Abs(c1.b - wantPrompt.b) < 0.01f,
                          $"★ 换牌提示行 = **原版 `Pragati-Regular Orange` 那个橙 `#FE981E`** —— 实测"
                        + $" ({c1.r:F3},{c1.g:F3},{c1.b:F3})，期望 ({wantPrompt.r:F3},{wantPrompt.g:F3},{wantPrompt.b:F3})"
                        + "（⛔ 别照 `m_fontColor32` 改回纯白 —— 那只是顶点色，乘在材质 `_FaceColor` 上）");
                    Check(c2.r > 0.999f && c2.g > 0.999f && c2.b > 0.999f,
                          $"★ 先后手行 = **纯白**（原版那颗挂的是 `Pragati-Regular Atlas Material`）—— 实测"
                        + $" ({c2.r:F3},{c2.g:F3},{c2.b:F3})"
                        + "（⚠️ 它与提示行**不是同一个颜色**，两行一并断「都白」是旧口径，已作废）");
                }
                // 🔴 **2026-09-29 新加**：这一行**照原版 rect 摆**（原来是我们自己放在其下方 21.5 px 处）。
                //   判据 = `bundle_scenes_scenes_battlearena1/RectTransform/RectTransform_3403.json`：
                //   原版 `MulliganText/TurnText` 左上 (312.50, 129.42) · 1307.06×54.17 ⇒ 中心 **(966.03, 156.50)**。
                //   ⚠️ 量的是**渲染出来那个 label 的实际位置**（不是拿常量跟自己比 —— 那是自证）。
                // ⚠️ **A195 核过：这个门是安全的**（没改）—— 上面刚断过 `mp.TurnLabel != null`；
                //    真为空时 `mp.TurnText` 返 `null`（**A245 起**；原来返 `"<无>"`）⇒ 两种取值都 ≠
                //    那两个字面量 ⇒ `Check(mp.TurnText == …)` 当场红（判别力不变）。
                if (mp.TurnLabel != null)
                {
                    // 🔴 **2026-10-16（`T09` 批 3）就地换读法**：换牌面板已上 uGUI 画布 ⇒
                    //   「件真正画在哪」的逆**不再是**世界帧那套（`LayoutSpace.PxX/PxY` —— 画布的 y 系数
                    //   随屏变，批处理下是 1/144）⇒ 改读**画布帧**的逆 `mp.PxOf(...)`（16:9 下逐位同值）。
                    var tc = mp.PxOf(mp.TurnLabel.transform.position);
                    float tcx = tc.x, tcy = tc.y;
                    Check(Mathf.Abs(tcx - 966.03f) < 1.5f && Mathf.Abs(tcy - 156.5f) < 1.5f,
                          $"★ 换牌那行的位置 = **原版 rect**（实得中心 ({tcx:F1}, {tcy:F1})，原版 (966.0, 156.5)）"
                        + " —— 原来我们自己放在 y=178（低 21.5 px、高多 5.8 px）");
                }
                // 🔴 **2026-10-22（用户口径「战斗里原版没有的设计不要」）**：原来这一条断的是
                //    「换牌阶段不显示回合行」（`drv.TurnLabelVisible`）—— 那一行**整颗删了**
                //    （原版 `BattleHud` 树里没有 `TurnLabel` 节点，判据 →
                //     `资料/普查产出_1022/W62_战斗非原版元素审计.md` C 表第 1 行）⇒
                //    改成**反向断言**：谁哪天把那行加回来，本条当场红。
                Check(FindHudNode("TurnLabel") == null,
                      "★ 中上那行「第 N 回合　你的回合」**不许再出现**（原版没有这个节点；"
                    + "2026-10-22 按用户口径删除）—— 🧨 谁把它加回来 ⇒ 本条红");
                // 🔴 **2026-09-27（PA 普查）**：原版 `MulliganContinueButton/Button` 是 **PA=0**（`m_Type=0` Simple）
                //   ⇒ `40k_bt_underbutton`（485×83）**拉满 577.5×63.84**；而 `ImageQuad` 默认按**贴图比例**定宽
                //   ⇒ 补 `SetAspect` 之前我们只画出 **372.8 宽（窄 204.7px）**。
                //   ⚠️ 量的是**渲染尺寸**、不是框 —— 框一直是对的，错的是往里画多大。
                // 🔴 **2026-10-16（`T09` 批 3）**：改读 **`mp.BarSizePx`**（= `sizeDelta`）——
                //   旧读法「世界尺寸 ×108」在批处理下 **y 偏 0.75 倍**（`T09` §五·补⑩ §七·8）。
                Check(Mathf.Abs(mp.BarSizePx.x - 577.5f) < 1.5f
                   && Mathf.Abs(mp.BarSizePx.y - 63.84f) < 1.5f,
                      $"★ 换牌底条渲染 = 原版 **577.5×63.84**（PA=0 拉满）—— 实测 "
                    + $"{mp.BarSizePx.x:F1}×{mp.BarSizePx.y:F1}");
                // 🔴 **2026-10-19（A1301③）**：「完成换牌」那颗钮的**命中框**
                //   = `Mulligan/ButtonsGroup/MulliganContinueButton/Button` 自己的 `rect` **577.5 × 63.84**
                //     按 `m_RaycastPadding (0,−40,0,−40)` 外扩 ⇒ **577.5 × 143.84**（中心不变 = (1611.45, 980.25)）。
                //   出处：`MB_5292`（pad，`m_RaycastTarget=1`）+ `RT_2659`（`m_SizeDelta` 577.5×63.84）+
                //   `工具/menu_dump.py bundle_scenes_scenes_battlearena1 "Mulligan"`（那颗钮与它两颗子件的绝对矩形）。
                //   期望值**字面量当场算** —— ⛔ 不读 `MulliganPanel.DoneHitPx`（那是被测实现自己算的，自证）；
                //   那个只读口只喂最后那条探测器。
                {
                    // 1 设计 px 的世界向量 —— 🔴 **2026-10-16（`T09` 批 3）**：改从**画布帧**那一侧差
                    //   （`mp.FrameRect.TransformVector(...)`：把画布局部向量映射到世界，含画布那一级缩放）。
                    //   ⛔ 旧的 `LayoutSpace.FromPixel` 那对**不再等于**「件真正画在哪」的逆 ——
                    //   画布的 y 系数随屏变（批处理下 1/144），16:9 下两者才逐位同值。
                    Vector3 perPxX = mp.FrameRect.TransformVector(new Vector3(1f, 0f, 0f));
                    Vector3 perPxY = mp.FrameRect.TransformVector(new Vector3(0f, -1f, 0f));   // 画布 y 向上 ⇒ 向下是 −y
                    Vector3 bc = mp.BarWorldPos;              // 那颗钮的**框中心**（⛔ 不是 `DoneWorldPos` = 文字中心）
                    // (a) 框内必中（四边各【内】1 px；中心那一点也算）
                    bool inM  = mp.HitDone(bc)
                             && mp.HitDone(bc + perPxY * (143.84f * 0.5f - 1f))
                             && mp.HitDone(bc - perPxY * (143.84f * 0.5f - 1f))
                             && mp.HitDone(bc + perPxX * (577.5f * 0.5f - 1f));
                    // (b) 框外 1 px 必不中（有界 —— 灭自证）
                    bool outM = !mp.HitDone(bc + perPxY * (143.84f * 0.5f + 1f))
                             && !mp.HitDone(bc - perPxY * (143.84f * 0.5f + 1f))
                             && !mp.HitDone(bc + perPxX * (577.5f * 0.5f + 1f));
                    // (c) 🔴 **判别式（灭自证）· 多认的那半**：旧实现那个「以文字中心为心、半径 184.45 px 的圆」
                    //     在**框下方** 119 px 处**必中**（到圆心 119 px < 184.45）；原版框到 1052.17 就结束
                    //     ⇒ 新口径在那一点**必不中**。
                    Vector3 oldCircle = bc - perPxX * 86.4f - perPxY * 119.75f;
                    // (d) 🔴 **判别式（灭自证）· 漏认的那半**：旧实现**完全没过**上下那 40 px ——
                    //     框的右上角内侧（x 距中心 278.75 px、y 距中心 61.92 px）在旧口径下
                    //     （底条 63.84 ∪ 圆）**必不中**（离圆心 370 px），新口径**必中**。
                    Vector3 corner = bc + perPxX * 278.75f + perPxY * 61.92f;
                    Debug.Log(P + $"   [A1301③] 换牌「完成」命中框：原版 577.5×143.84 px"
                                + $"（框内中={inM} · 框外不中={outM}）");
                    Check(inM, "★ A1301③：「完成换牌」命中框（原版 577.5×143.84）**四边各内 1 px 都中**"
                             + "｜🧨 改坏法：`HitDone` 写回 `_bar.Contains`（只有 63.84 高、不过那 40）⇒ 上下两点红");
                    Check(outM, "★ A1301③（**灭自证**）：框**外** 1 px 必不中（有界 —— 与上一条配对）");
                    Check(!mp.HitDone(oldCircle),
                          "★ A1301③（**判别式**）：旧实现那个「文字中心 ±184.45 px 的圆」在**框下 119 px** 处"
                        + "**必中** ⇒ 新口径在这一点**必不中**（那一圈原版没有可射线件）"
                        + "｜🧨 改坏法：`HitDone` 写回那个圆 ⇒ 红");
                    Check(mp.HitDone(corner),
                          "★ A1301③（**判别式**）：框的**右上角内侧**必中 —— 旧口径（底条 ∪ 圆）在那一点必不中"
                        + "（原来上下那 40 px 一点都没过）");
                    var dhp = MulliganPanel.DoneHitPx;
                    Check(Mathf.Abs(dhp.x - 577.5f) < 0.01f && Mathf.Abs(dhp.y - 143.84f) < 0.01f,
                          $"★ A1301③：`MulliganPanel.DoneHitPx` = {dhp.x:F2}×{dhp.y:F2} px"
                        + "（原版 577.5×143.84 = 577.5×63.84 上下各外扩 40）");
                }
                Debug.Log(P + "   " + mp.Describe());
                Shot(cam, "24_开局换牌");

                // ---- 17b. **A276**：换牌按钮那一层的 z 口径（**不许跟卡的世界 z 走**）----
                // 现场：`Battle/MulliganPanel.cs` 原来是 `c.transform.position + (0, −h, Z − c…z)` ——
                //   那个 `− c.transform.position.z` 项**自相消**（`+ c…z` 与 `− c…z` 恰好抵消）⇒
                //   这一处**改不改都一样**（恒等于 `Z`）。但它**形状上**很容易被后人「顺手化简」成
                //   `c.transform.position`（那一行里 x/y 本来就是拿卡的世界坐标当局部坐标用的）——
                //   那样按钮的 z 就会跟着卡走。现在 z 由本面板的 `Z` 单独给（与同父的 `_shade` 同口径）。
                // ⚖️ 调度台裁定 = 收口径（选项 (a)；判据全文 → `资料/普查产出_1010/V4b_三件口径.md` §Q2）；同一处
                //   两套口径并存（这一处的「另一套」= 卡的世界坐标）⇒ 收成面板的局部 z。
                // 判据（两态）：把第 1 张手牌的**世界 z** 挪 0.4 再重建按钮 ⇒ 局部 z **一动不动**。
                // 改坏法：把 z 写成 `c.transform.position.z`（或整个 `c.transform.position`）⇒ 下面这条红。
                {
                    var hv0 = drv.HandViewAt(0);
                    if (hv0 == null) Check(false, "（A276 前提）取得到第 1 张手牌的视图");
                    else
                    {
                        var handForZ = new List<CardView>();
                        for (int i = 0; i < drv.HandCount; i++)
                        { var v = drv.HandViewAt(i); if (v != null) handForZ.Add(v); }
                        mp.Open(handForZ);
                        float zc0 = mp.CardButtonLocalZ(0);
                        var cardP0 = hv0.transform.position;
                        hv0.transform.position = new Vector3(cardP0.x, cardP0.y, cardP0.z + 0.4f);
                        mp.Open(handForZ);                       // 用**同一份**手牌重建，只让卡的 z 不同
                        float zc1 = mp.CardButtonLocalZ(0);
                        hv0.transform.position = cardP0;         // 还原卡的位置…
                        mp.Open(handForZ);                       // …并把按钮重建回原位那一版
                        Check(!float.IsNaN(zc0) && Mathf.Abs(zc0 - zc1) < 1e-5f,
                              $"★ 「换」按钮那一层的 z 是**面板的局部 z**、不跟卡的世界 z 走 —— "
                            + $"卡 z {cardP0.z:F2} 时按钮 z = {zc0:F4}；卡挪到 {cardP0.z + 0.4f:F2} 时 = {zc1:F4}");
                    }
                }

                // 点「换」→ 标记；再点一次 → 取消（走的是面板的命中判定，不是直接改标记）
                Check(drv.SimulateMulliganToggle(0) && mp.IsMarked(0), "点第 1 张牌的「换」→ 标记上了");
                Check(mp.Marked.Count == 1, "……而且只标记了 1 张");
                Check(mp.CardBtnTex(0) == "UI_Button_Mulligan_Pressed",
                      $"……按钮换成按下态那张图（{mp.CardBtnTex(0)}）");
                Check(drv.SimulateMulliganToggle(0) && !mp.IsMarked(0), "再点一次 → 取消标记");
                Check(drv.SimulateMulliganToggle(0) && drv.SimulateMulliganToggle(2) && mp.Marked.Count == 2,
                      "标记第 1、3 张（`Marked` 应当是升序的 [0,2]）");
                Shot(cam, "25_换牌标记");

                // 🔴 「眼睛」那颗钮（原版 `HideMulliganButton` → `MulliganManager.ToggleMulliganVisibility`
                //    → `ShowMulliganElements`）。**2026-09-17 照反编译核实**：它是**开关**（按 activeInHierarchy
                //    取反），且一次收**四样** —— 两个 GameObject + 每张卡的换牌按钮 + **压暗层**
                //    （`Shade.SwitchShade`）。我们原来只收按钮、压暗还盖着 —— 那是**漏做**：玩家按眼睛
                //    就是为了看战场，原版那时屏幕是亮的。
                SettleShake();      // 点「眼睛」是**按世界坐标点的**，HUD 偏了就会点空（见 `SettleShake`）
                Check(drv.SimulateMulliganEye() && !mp.CardButtonsShown && !mp.ShadeActive,
                      "点「眼睛」→ 换牌按钮**和压暗层**一起收起（原版 `ShowMulliganElements(false)`）");
                // ⚠️ 图要拍在**两次点击之间** —— 拍在后面那一次之后，画面是「又都回来了」，
                //    和文件名对不上（第一次写的时候就是这么错的，图上按钮还在）。
                Shot(cam, "25b_换牌收起");
                Check(drv.SimulateMulliganEye() && mp.CardButtonsShown && mp.ShadeActive,
                      "再点一次 → 按钮和压暗都回来（**是开关，不是按住**）");

                // ══════════════════════════════════════════════════════════════════════════════
                //  🆕 2026-10-22（W62 · 战斗线 `D6`）：压暗层必须夹在「战场/战将」之上、「换牌卡」之下
                //  病灶（真机像素证据，2560×1440）：原版换牌卡那一区 mean/max = **56.5 / 255**，
                //    我们同一区 = **30.1 / 98**（背景 26.1 / 80）⇒ 压暗层画在了**卡上面**（卡和背景一样暗）。
                //  机制 / 为什么「只抬卡、不动压暗层」→ `Battle/MulliganPanel.cs` 的 `QMulliganCard` doc
                //    （战场几何也是队列 3000 ⇒ 压暗层只要 ≤2999 就压不住战场）。
                //  ⚠️ 批处理没有画面 ⇒ 把「亮度比」换算成**从层序推出来的**透射比（**线性光**）：
                //    在压暗层之上 ⇒ 透射 1.0；在它下面 ⇒ 1 − alpha。
                //    ⛔ 不是把 0.9 / 0.25 当两个常量写死 —— 它们是**下面这两条层序关系的推论**。
                // ══════════════════════════════════════════════════════════════════════════════
                {
                    const int QCanvasBand = CardView.QCard;          // 画布件所在那一档（3000）
                    int qCardMin = int.MaxValue, qCardMax = int.MinValue;
                    for (int i = 0; i < mp.RowCardCount; i++)
                    {
                        var rc = mp.RowCard(i);
                        if (rc == null) continue;
                        qCardMin = Mathf.Min(qCardMin, rc.Queue);
                        qCardMax = Mathf.Max(qCardMax, rc.Queue);
                    }
                    Debug.Log(P + $"   [D6] 压暗层画布层 {mp.ShadeCanvasLayer} · 换牌卡队列 {qCardMin}..{qCardMax}"
                                + $"（压暗层/画布那一档 = {QCanvasBand}，放大窗卡 = {CardFan.QCardBase}）"
                                + $" · alpha={mp.ShadeTintAlpha:F3}");
                    Check(mp.ShadeCanvasLayer == HudCanvas.SortingLayer.OverHand,
                          $"★ D6①：压暗层在 **`OverHand` 画布上**（排序层 {mp.ShadeCanvasLayer}）"
                        + " —— 战场几何是**队列 3000 + `Default` 层**（`ArenaBuilder.cs:5068`）⇒ 同队列时由**排序层**判胜负"
                        + "｜🧨 把它挪去世界空间 quad ⇒ 压不住战场（≤2999 就输给 3000 的战场）");
                    Check(mp.RowCardCount > 0 && qCardMin < int.MaxValue,
                          $"（前提·不静默）D6：换牌区有卡、且读得到它们的渲染队列（实得 {mp.RowCardCount} 张）");
                    Check(qCardMin > QCanvasBand,
                          $"★ D6②：换牌卡的队列**在画布那一档之上**（最低 {qCardMin} > {QCanvasBand}）"
                        + " ⇒ `renderQueue` 比较先于排序层 ⇒ 卡画在压暗层**之后**（= 在它上面、不被压暗）"
                        + "｜🧨 回到 `HandLayout` 那一段（2989..3000）⇒ 卡被压暗 ⇒ 本条红");
                    Check(qCardMax < CardFan.QCardBase,
                          $"★ D6③：换牌卡的队列**仍低于「点卡放大」那扇窗的卡**（最高 {qCardMax} < `CardFan.QCardBase` {CardFan.QCardBase}）"
                        + " ⇒ 点牌看大图那张照样压在换牌卡之上｜🧨 把 `QMulliganCard` 抬到 ≥3009 ⇒ 红");
                    Check(Mathf.Abs(mp.ShadeTintAlpha - 0.8f) < 0.002f,
                          $"★ D6④：压暗 alpha = 原版 `Shade.onAlphaLevel` **0.8**（`MB_4399`；实得 {mp.ShadeTintAlpha:F3}）"
                        + "｜🧨 写回我们原来的 0.88 ⇒ 红");
                    float bgRatio = 1f - mp.ShadeTintAlpha;       // 线性光：压暗下面透上来多少
                    float cardRatio = qCardMin > QCanvasBand ? 1f : bgRatio;
                    Check(cardRatio >= 0.9f && bgRatio <= 0.25f,
                          $"★ D6⑤（亮度比·线性光）：换牌卡 {cardRatio:F3}（判据 ≥0.9，卡不被压暗）"
                        + $" · 背景/战场 {bgRatio:F3}（判据 ≤0.25）"
                        + " —— ⚠️ 屏上是 sRGB：0.20 的线性透射在中灰底上量出来 ≈0.33"
                        + "（`ProjectSettings.asset:50` `m_ActiveColorSpace:1` ⇒ ⛔ 别拿 sRGB 比值当判据）");
                }

                string sigBefore = Sig(drv.Ctx);
                int handBefore = drv.Ctx.Players[0].Hand.Count;
                Check(drv.SimulateMulliganDone(), "点「完成换牌」");

                Check(!drv.InMulligan && !mp.Visible, "……换牌阶段结束、面板收起");
                Check(drv.Ctx.Players[0].Energy == 2, $"……这时才发能量（{drv.Ctx.Players[0].Energy} = 回合 1）");
                // ⚠️ 第三十四轮：换牌结束后 `BeginTurn` 里的**天赋**也会塞一张进来 ⇒ 单算。
                Check(drv.Ctx.Players[0].Hand.Count == handBefore + 1 + Conjured(drv.Ctx, 0),
                      $"……也才抽第 1 张（手牌 {handBefore} → {drv.Ctx.Players[0].Hand.Count}，"
                      + $"其中天赋生成的 {Conjured(drv.Ctx, 0)} 张）");
                // 换牌 + 抽牌的净效果：牌**一张不多一张不少**（换掉的回牌库、补抽回来）
                Check(Sig(drv.Ctx) == sigBefore, "牌一张不多一张不少（换掉 2 张 → 回牌库重洗 → 补抽 2 张）");
                Debug.Log(P + $"   换完手牌：{string.Join("/", HandNames(drv.Ctx, 0))}");
                Shot(cam, "26_换牌之后");

                // ---- 换牌倒计时（原版 `BattleManager._MulliganCountdown`）------------------
                // 原版：逐秒 -1 → **< 10 s** 把剩余秒数写到「完成换牌」那颗钮上（`SetMulliganTimer`）
                //       → **< 1 s** 自动完成（`ProcessMulliganDone` = 等价玩家点完成）。
                // 总秒数字段 = `VarsGlobal.mulliganTimeLimit`（**值拿不到，默认是我们挑的**，见字段注释）。
                // 上一段已经把换牌走完了 ⇒ 重开一局来验。
                drv.Begin("Ultramarines", "Goff", 20260919);
                Check(drv.InMulligan && mp.Visible, "重开一局 → 又进换牌阶段（下面验倒计时）");
                Check(Mathf.Abs(drv.MulliganSecondsLeft - drv.mulliganSeconds) < 0.01f,
                      $"倒计时从总秒数起（{drv.MulliganSecondsLeft:F1} = mulliganSeconds {drv.mulliganSeconds:F1}）");
                Check(mp.DoneText == MulliganPanel.DoneLabel,
                      $"开局时按钮上写的是「{MulliganPanel.DoneLabel}」（还没进最后 10 秒）");
                int toGo = Mathf.CeilToInt(drv.mulliganSeconds) - 9;
                for (int i = 0; i < toGo; i++) drv.TickMulliganForTest(1f);
                Check(mp.DoneText == "0:09", $"剩 9 s 时按钮上写着「0:09」（实得「{mp.DoneText}」）");
                Check(drv.InMulligan, "……这时**还没**自动完成（原版只在 <1 s 才自动完成）");
                Shot(cam, "25c_换牌倒计时");
                for (int i = 0; i < 12 && drv.InMulligan; i++) drv.TickMulliganForTest(1f);
                Check(!drv.InMulligan, "走到 0 → **自动完成换牌**（= 玩家点「完成换牌」同一条路）");
                Check(mp.DoneText == MulliganPanel.DoneLabel,
                      $"……收尾时按钮的字复原成「{MulliganPanel.DoneLabel}」（实得「{mp.DoneText}」）");

                // 关掉开关 → 回到默认路径（自检里那十几节用的就是这条）
                drv.mulliganEnabled = false;
                drv.Begin("Ultramarines", "Goff", 20260918);
                Check(!drv.InMulligan && drv.Ctx.Players[0].Energy == 2,
                      "不开换牌 → Begin 之后直接就是回合 1（老路径不变）");
                drv.mulliganEnabled = saved;
                drv.offensivePhaseEnabled = savedOff;
            }
        }


        // ---- 20. 选牌面板（原版 `ChooseCardMenu`）：引擎不再替玩家挑 ----
        //   引擎那半在 `RuleEngineTest.TestPlayerChoice`（含「不同下标 → 不同卡」那条硬判据）；
        //   这一节验的是**表现层那半**：面板真的弹出来、点得动、选完关得掉。
        //   ⚠️ 必须走 `SimulatePlayViaPanel` —— **不是** `SimulatePlay`（那个直接调引擎、绕过面板）。
        Debug.Log(P + "--- 选牌面板 ---");
        {
            var pool = CardDatabase.Load();
            var rd = CardDatabase.Find(pool, "Rapid Deployment");   // `Choose a troop in your hand. Lower its cost by 2`
            Check(rd != null, "卡池里有 `Rapid Deployment`（`Choose a troop in your hand`）");
            var panel = driver != null ? driver.Choose : null;
            Check(panel != null, "选牌面板建出来了");
            Check(panel != null && !panel.Visible, "平时是关着的");

            if (rd != null && panel != null)
            {
                ctx = driver.Ctx;                       // 上面那节重建过对局，这里重新取一次
                ctx.Players[0].Hand.Add(ctx.NewInstance(rd));
                ctx.Players[0].Energy = 9;              // 保证付得起（费 3）
                driver.RefreshAll();
                Step(0.05f);

                int idx = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, rd)) { idx = i; break; }   // 第 7 行第 3 步：手牌存实例
                Check(idx >= 0, "注入的那张牌在手牌里");

                Check(driver.SimulatePlayViaPanel(idx, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走**面板那条路**出牌（`BeginPlay` 返回成功）");
                Step(0.05f);

                Check(panel.Visible, "★ **面板真的弹出来了**（不用面板的话这一步直接就打出去了）");
                Check(driver.ChooseOptionCount >= 2,
                      $"★ 上面摆着 **{driver.ChooseOptionCount}** 张候选（应 ≥2 —— 手牌里的部队）");
                Check(panel.TitleText == Loc.T(ChoosePanel.TitleTerm),
                      $"★ 标题「{panel.TitleText}」= **原版词条** `{ChoosePanel.TitleTerm}` 在当前语档下的字"
                      + "（🔴 2026-10-18（W6）就地订正：这条原来断的是写死的中文「选择一张牌」，"
                      + " 并说它是「运行时实测那句」—— 那不是判据；判据 = 原版那颗 `ChooseText` 的 `mTerm`，"
                      + " 英文原文 `Choose one card` 也在本地。现在中文档 = `zh_CN` 值、英文档 = TMP 原文）");
                Check(panel.ConfirmText == Loc.T(MulliganPanel.DoneTerm),
                      $"★ 确认文案「{panel.ConfirmText}」= 原版词条 `{MulliganPanel.DoneTerm}` 在当前语档下的字"
                      + "（选牌**复用**换牌那条词条，原版如此）");
                Check(panel.BarHasArt && panel.PlayHasArt && panel.EyeHasArt,
                      "★ 底条 / 圆钮 / 眼睛三张图都在"
                      + $"（`{panel.BarTex}` · `40k_UI_bt_play` · `{panel.EyeTex}`）");
                Shot(cam, "20_选牌面板");

                // ---- 🆕 2026-10-19（`T03` · `A1327`）：选牌「确认」的命中区 = 原版**三条可射线 Image 的并集** ----
                //  判据 = arena2（arena1 逐值同）`ChooseCardMenu/ButtonsGroup/Continue Button` 子树逐节点现读：
                //    ① 父 `Continue Button`：548.015 × 75.905 @ (BarCx−65.196, BarCy−5.749)（**alpha=0 仍吃射线**，pad 0）
                //    ② `BG`：577.5 × 63.84 @ (BarCx, BarCy)（pad 0）
                //    ③ 圆钮 `ContinueButton`：80.469 × 79.636 @ (PlayCx, PlayCy)（**rt=1，onClick 直绑
                //       `ChooseCardMenu.ClickChooseDone`**，pad 0）
                //  ⛔ 期望值全是**原版字面量**，不读 `CardChoicePanel` 的常量/只读口（那是自证）。
                //  ⚠️ 旧口径 = `_bar ∪ _play ∪ 自加的 r=190 圆`：纵向多认 ~147/152 px、漏了父矩形左侧 50 px 那条。
                {
                    var rtA = panel.PanelRect;
                    Check(rtA != null, "★ T03/A1327：（前提）选牌面板的画布本体在（`PanelRect` 非空）");
                    if (rtA != null)
                    {
                        Vector3 perPxX = rtA.TransformVector(new Vector3(1f, 0f, 0f));
                        Vector3 perPxY = rtA.TransformVector(new Vector3(0f, -1f, 0f));  // 画布 y 向上 ⇒ 向下是 −y
                        Vector3 bc = panel.BarWorldPos;      // `BG` 框中心（画布帧）
                        // 设计 px（左上原点、y 向下）→ 世界；dx/dy 相对 `BG` 中心
                        System.Func<float, float, Vector3> PxA =
                            (dx, dy) => bc + perPxX * dx + perPxY * dy;
                        Vector3 pc = PxA(-65.196f, -5.749f);      // 父 `Continue Button` 中心
                        Vector3 cc = PxA(175.112f, -2.361f);      // 圆钮中心
                        // (a) 三块中心 + 驱动层点「确认」用的那个点都必中
                        bool ctrA = panel.HitDone(bc) && panel.HitDone(pc) && panel.HitDone(cc)
                                 && panel.HitDone(panel.DoneWorldPos);
                        // (b) 并集四条**外沿**：内侧 1 px 必中 / 外侧 1 px 必不中
                        //     左沿 = 父左（bc.x − 339.2035）· 右沿 = BG 右（bc.x + 288.75）
                        //     上沿 = 父上（bc.y − 43.7015）· 下沿 = 圆钮下（bc.y + 37.457）
                        bool inA = panel.HitDone(PxA(-339.2035f + 1f, 0f))
                                && panel.HitDone(PxA( 288.75f   - 1f, 0f))
                                && panel.HitDone(PxA(-65.196f, -43.7015f + 1f))
                                && panel.HitDone(PxA(175.112f,  37.457f  - 1f));
                        bool outA = !panel.HitDone(PxA(-339.2035f - 1f, 0f))
                                 && !panel.HitDone(PxA( 288.75f   + 1f, 0f))
                                 && !panel.HitDone(PxA(-65.196f, -43.7015f - 1f))
                                 && !panel.HitDone(PxA(175.112f,  37.457f  + 1f));
                        // (c) 🔴 **并集 ≠ 外接盒**（三个角必须不中；外接盒实现会全中）
                        bool cornersA = !panel.HitDone(PxA(286.75f, -41.70f))    // 右上角（BG 不够高、父不够宽）
                                      && !panel.HitDone(PxA(286.75f,  35.46f))    // 右下角
                                      && !panel.HitDone(PxA(-337.20f, 35.46f));  // 左下角
                        // (d) 🔴 **旧口径的两条判别式**（结构上互斥，必须一真一假）
                        //     多认：确认文字上方 63.75 px（旧 r=190 圆内）⇒ 新口径必不中
                        bool oldOverA = !panel.HitDone(PxA(-69.796f, -63.75f));
                        //     漏认：父矩形左侧那条（x≈1260，旧口径在圆外、BG 外）⇒ 新口径必中
                        bool oldMissA = panel.HitDone(PxA(-328.80f, 0f));
                        Debug.Log(P + "   [T03/A1327] 选牌「确认」命中区 = 原版并集"
                                + "（父 548.015×75.905 ∪ BG 577.5×63.84 ∪ 圆钮 80.469×79.636，pad 全 0）"
                                + $"：中心中={ctrA} · 外沿内 1px 中={inA} · 外沿外 1px 不中={outA}"
                                + $" · 三角不中={cornersA} · 旧多认点不中={oldOverA} · 旧漏认点中={oldMissA}");
                        Check(ctrA,
                              "★ T03/A1327：确认区**三块的中心 + 驱动层点确认用的那个点**全都判得中"
                            + "（父 `Continue Button` / `BG` / 圆钮 / `DoneWorldPos`）"
                            + "｜🧨 改坏法：只留 `_bar`（丢掉父矩形与圆钮的上/下凸出）⇒ 圆钮中心那条仍绿、"
                            + "但下面「外沿内 1 px」会红");
                        Check(inA,
                              "★ T03/A1327：并集四条外沿**内侧 1 px 全中**（父左 1249.60 / BG 右 1877.55 /"
                            + " 父上 937.05 / 圆钮下 1018.21 设计 px）"
                            + "｜🧨 改坏法：命中区退回 `_bar` 的 577.5×63.84 ⇒ 左右上三条红");
                        Check(outA,
                              "★ T03/A1327（**灭自证**）：并集四条外沿**外侧 1 px 全不中**（有界）"
                            + " —— 与上一条配对：「`HitDone` 恒 true」会让上一条绿、本条红");
                        Check(cornersA,
                              "★ T03/A1327（**并集 ≠ 外接盒**）：右上/右下/左下三个**角**必不中"
                            + "（外接盒 627.95×81.16 会把这三块白送出去）"
                            + "｜🧨 改坏法：把三条并集换成一个大矩形 ⇒ 本条红");
                        Check(oldOverA && oldMissA,
                              "★ T03/A1327（**旧口径判别式**，两条结构互斥）："
                            + "① 确认文字上方 63.75 px（旧 `r=190` 圆内）现在**不中**；"
                            + "② 父矩形左侧条（x≈1260，旧口径在圆外且 `_bar` 外）现在**中**"
                            + "—— 只改其中一处、另一处不改 ⇒ 必有一条红");
                    }
                }

                CheckPick(driver, 0, "点第 1 张候选（走面板的命中判定，真路径）");
                Check(driver.SimulateChooseDone(), "点「继续」");
                Check(!panel.Visible, "★ 选完**面板关掉了**");
                Check(ctx.LastChosenCard != null, "★ 引擎真的按面板选了一张（`LastChosenCard` 非空）");

                // 收尾：收尾：这一节是全自检**最后**跑的一节 —— 播出来的特效要清掉再交棒
                // （批处理下没有帧循环，`WarpforgeEffectPlayer` 不会自毁，见 `ClearEffects`）
                ClearEffects();
                Step(0.2f);
            }
        }

        // ---- 20-b. 🆕 2026-10-14（账 `A1964`）：候选上限是【逐卡数据】，不是一条常数 ----
        //   原版 `choicesDefinition.maxTargets` **逐卡不同**（🆕 2026-10-19 现读当前 build 的
        //   `allcards_export/cards_raw.json`：**全 1351 张** = `0` 1103 · `3` 224 · `2` 13 · `4` 11；
        //   **池内 1127 张** = `0` 979 · `3` 127 · `2` 12 · `4` 9。
        //   ⚠️ 本行原来写的是 2022 旧快照的 `= 3` 204 张 · `= 4` 10 张 · `= 2` 1 张 —— 已过期）
        //   ⇒「同一句 `Choose a …` 子句 ⇒ 同一个上限」是**错的**。两张卡就是那对反例：
        //     · `GSC65 Pilfered Supplies`（`type = defence`）—— 原版 `maxTargets = 4`
        //       `desc = "Choose a Sabotage card and add it to your opponent's hand"`
        //     · `GSC50 Clandestine Operation`（`type = tactic`）—— 原版 `maxTargets = 3`
        //       `desc` **前面那半句与 `GSC65` 逐字相同**，只多一句 `Draw a card`
        //       （⚠️ **不是「一字不差」** —— 别把这两张卡的 `desc` 写成同一条）
        //   两张卡的**候选域完全一样** —— 都是 `subtype == "Sabotage"` 的那 4 张
        //   （`GSC_Cult_Propaganda` / `GSC_Improvised_Barricade` / `GSC_Jammed_Communications` /
        //    `GSC_Poisoned_Supplies`；实测 4/4 全是 `type = tactic` · `faction = Genestealers`）。
        //   ⇒ **域相同、摆出来的张数必须不同** —— 这一节钉的就是这件事。
        //   判据链（`BattleDriver`）：`ChooseShowByCardId`（`{"GSC65", 4}`）→ `ChooseShowLimit`
        //   → 打开面板那一段（`cands.Count > showMax` 才抽）。本节**只断行为、不读那张表**
        //   （读表 = 拿我们自己的常量证明我们自己）。
        //   防御卡打得出去这件事的判据：`RuleEngine/Core/EffectResolver.cs:1373-1379`（防御卡走
        //   战术卡同一条链）+ `RuleEngine/Core/RuleCore.cs:2333-2335`（非单位卡一律分流 `PlayTactic`）。
        //
        //   🧨 **改坏法（灭自证）**：
        //     · 把 `ChooseShowLimit` 退回一条常数 `3` ⇒ **(a) 红**（4 变 3）、(b) 绿；
        //     · 把 `ChooseShowLimit` 改成「一律返回全部候选」 ⇒ (a) 绿、**(b) 红**（3 变 4）。
        //   **两条必须同时绿**才说明「逐卡数据」真的在起作用 —— 只绿一条 = 那两种退化写法之一还活着。
        Debug.Log(P + "--- 选牌面板：候选上限是逐卡数据（A1964）---");
        {
            // ⚠️ 面板是**一份对象四族共用**（`BattleDriver` 只有一个 `_choosePanel`）——
            //    这里先断一次「它是关着的」，免得拿别的族摆的东西当数。
            var showPanel = driver != null ? driver.Choose : null;
            Check(showPanel != null && !showPanel.Visible,
                  "★（前提）接着第 20 节 —— 面板是**关着的**（没被别的族占着）");

            var showPool = CardDatabase.Load();

            // 候选域的**分母**在测试侧独立数一遍（不靠驱动那张逐卡表）——
            // 它一变，(a) 那条 `== 4` 就会红，而且红得有据可查。
            int sabInPool = 0;
            foreach (var c in ctx.CardPool)
                if (c != null && c.Subtype == "Sabotage") sabInPool++;
            Check(sabInPool == 4,
                  $"（前提）卡池里 `subtype == \"Sabotage\"` 的正好 **{sabInPool}** 张"
                  + "（= 两张卡共用的那个候选域）");

            // 域里那 4 张的 `CardDef.Id`（判据 = `cards_engine.json`）——
            // 下面按**集合**比，不比顺序（面板怎么排是表现层的事）。
            string[] sabIds = { "7c666a04c1b9e8b4e9a96247e9fe115a", "334a32d196d46ed4387bf3740cce069b",
                                "68909cf02f472734ea391665e0d28e15", "a7bb23355a30d344e9d2decf976d91e1" };

            // ---- (a) `GSC65`（原版 `maxTargets = 4`）⇒ **4 张全摆** ----
            var g65 = CardDatabase.Find(showPool, "Pilfered Supplies");
            Check(g65 != null && g65.Id == "GSC65",
                  "卡池里有 `Pilfered Supplies`（`GSC65`，防御卡）");
            if (g65 != null && showPanel != null)
            {
                ctx = driver.Ctx;                       // 上一节动过对局，这里重新取一次（与 20/21 节同规矩）
                ctx.Players[0].Hand.Add(ctx.NewInstance(g65));
                ctx.Players[0].Energy = 9;              // 这张费 0，给足只是保险
                driver.RefreshAll();
                Step(0.05f);

                int i65 = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, g65)) { i65 = i; break; }
                Check(i65 >= 0, "注入的那张 `GSC65` 在手牌里");

                Check(driver.SimulatePlayViaPanel(i65, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走**面板那条路**打出 `GSC65`（防御卡走战术卡同一条链）");
                Step(0.05f);

                Check(showPanel.Visible, "★（a）**面板弹出来了**");
                Check(driver.ChooseOptionCount == 4,
                      $"★（a）原版 `maxTargets = 4` ⇒ 上面摆 **{driver.ChooseOptionCount}** 张候选"
                      + "（🔴 改坏法：把 `ChooseShowLimit` 退回常数 3 ⇒ 这里变 3、这条红）");

                var got4 = new List<string>();
                for (int i = 0; i < driver.ChooseOptionCount; i++)
                    got4.Add(driver.ChooseOptionStableId(i));
                bool sameSet = got4.Count == sabIds.Length;
                foreach (string w in sabIds)
                {
                    int n = 0;
                    foreach (string g in got4) if (g == w) n++;
                    if (n != 1) sameSet = false;
                }
                Check(sameSet,
                      "★（a）摆出来的 4 张**就是**那个域里的 4 张（各一张、一张不多一张不少）："
                      + $"`{string.Join("/", got4.ToArray())}`");

                // ---- (a2) 🆕 2026-10-19（`A1961`）：**面板顺序 = 原版比较函数排出来的** ----
                //   判据 = `BattleManager__SortByCostAndName.c`（`BattleManager__GetChoiceOptions.c:110-113`
                //   那次 `Sort`；玩家那一路 `ChoiceOfCardPlayer.c:27` 的 `param_4 = 0` ⇒ 一定排）：
                //   **`manaCost` 升序 → 本地化卡名（`ToLower()`、当前文化）→ `uniqueId`**。
                //   🔴 **判别力（灭自证）**：这 4 张在**卡池里的顺序**是
                //   `Cult Propaganda(2) / Improvised Barricade(3) / Jammed Communications(2) / Poisoned Supplies(2)`
                //   （`cards_engine.json` 的数组序）—— **费用不单调**（2,3,2,2）。
                //   不排序 ⇒ 面板照池序摆 ⇒ 下面「费用非降」这条**必红**；只有排序真跑了才绿。
                //   ⚠️ 只断**规则**、不写死这 4 张的期望顺序：第 2 键（卡名）是**文化相关**的
                //   （原版 `String.CompareTo` 走当前文化）⇒ 写死某台机器的顺序会变成假红。
                var costById = new Dictionary<string, int>();
                foreach (var cc in ctx.CardPool)
                    if (cc != null && cc.Id != null) costById[cc.Id] = cc.Cost;
                bool costAsc = true;
                var costSeq = new List<string>();
                for (int i = 0; i < driver.ChooseOptionCount; i++)
                {
                    int cv;
                    if (!costById.TryGetValue(driver.ChooseOptionStableId(i), out cv))
                    {
                        costAsc = false;
                        costSeq.Add("?");
                        continue;
                    }
                    costSeq.Add(cv.ToString());
                    if (i > 0)
                    {
                        int pv;
                        if (!costById.TryGetValue(driver.ChooseOptionStableId(i - 1), out pv)) pv = cv;
                        if (pv > cv) costAsc = false;
                    }
                }
                Check(costAsc,
                      "★（a2）面板顺序的第 1 键 = **费用升序**（原版 `SortByCostAndName`）："
                      + $"面板费用 [{string.Join(",", costSeq.ToArray())}]"
                      + "（🔴 改坏法：删掉 `cands.Sort(CompareChoiceOptions)` ⇒ 照池序 2,3,2,2 ⇒ 这条红）");
                bool nameAsc = true;
                for (int i = 1; i < driver.ChooseOptionCount; i++)
                {
                    int c0, c1;
                    if (!costById.TryGetValue(driver.ChooseOptionStableId(i - 1), out c0)) continue;
                    if (!costById.TryGetValue(driver.ChooseOptionStableId(i), out c1)) continue;
                    if (c0 != c1) continue;                 // 只对**同费用**的相邻两张比第 2 键
                    string n0 = (driver.ChooseOptionName(i - 1) ?? "").ToLower();
                    string n1 = (driver.ChooseOptionName(i) ?? "").ToLower();
                    if (string.Compare(n0, n1, System.StringComparison.CurrentCulture) > 0) nameAsc = false;
                }
                Check(nameAsc,
                      "★（a2）同费用的相邻两张按**本地化卡名**升序（原版第 2 键 = `GetLocalizedCardName().ToLower()`）");

                Check(driver.SimulateChoosePick(0), "（a）点第 1 张候选");
                // 这一条是「点到了卡、不是点到了『继续』」的判据：`TogglePick` 只做标记、
                // 不关面板；hit 到 Done 则会把它关掉（`HitDone` 在 `HandleClick` 里**排在**卡片之前）。
                Check(showPanel.IsPicked(0),
                      "★（a）第 1 张候选**真的被标记成选中**了（面板没被「继续」吃掉）");
                Check(driver.SimulateChooseDone(), "（a）点「继续」");
                Check(!showPanel.Visible, "★（a）选完**面板关掉了**");
                Check(ctx.LastChosenCard != null && ctx.LastChosenCard.Card != null
                      && ctx.LastChosenCard.Card.Subtype == "Sabotage",
                      "★（a）引擎真的按面板选了一张 `Sabotage`"
                      + $"（`{ctx.LastChosenCard.Card.Name}`）");
                ClearEffects();
                Step(0.15f);
            }

            // ---- (b) `GSC50`（**同一句 `Choose a Sabotage card`**、原版 `maxTargets = 3`）⇒ **只摆 3 张** ----
            var g50 = CardDatabase.Find(showPool, "Clandestine Operation");
            Check(g50 != null && g50.Id == "GSC50",
                  "卡池里有 `Clandestine Operation`（`GSC50`，计策卡）");
            if (g50 != null && showPanel != null)
            {
                ctx = driver.Ctx;
                ctx.Players[0].Hand.Add(ctx.NewInstance(g50));
                ctx.Players[0].Energy = 9;              // 这张费 2
                driver.RefreshAll();
                Step(0.05f);

                int i50 = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, g50)) { i50 = i; break; }
                Check(i50 >= 0, "注入的那张 `GSC50` 在手牌里");

                Check(driver.SimulatePlayViaPanel(i50, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走**面板那条路**打出 `GSC50`（与 `GSC65` 同一句 `Choose a Sabotage card`）");
                Step(0.05f);

                Check(showPanel.Visible, "★（b）**面板弹出来了**");
                Check(driver.ChooseOptionCount == 3,
                      $"★（b）原版 `maxTargets = 3` ⇒ 摆 **{driver.ChooseOptionCount}** 张"
                      + "（🔴 改坏法：把 `ChooseShowLimit` 改成「一律返回全部候选」⇒ 这里变 4、这条红）");

                // 这 3 张必须是**从 (a) 那个 4 张域里抽出来**的（都在域内、互不重复）——
                // 钉住「(b) 少了那一张是**抽掉的**，不是它换了个更小的域」；
                // 否则 (a)/(b) 的差可能来自「域不同」而不是「上限不同」，那就白断了。
                var got3 = new List<string>();
                for (int i = 0; i < driver.ChooseOptionCount; i++)
                    got3.Add(driver.ChooseOptionStableId(i));
                bool subOf4 = got3.Count == 3;
                foreach (string g in got3)
                {
                    bool inDom = false;
                    foreach (string w in sabIds) if (g == w) inDom = true;
                    if (!inDom) subOf4 = false;
                }
                for (int i = 0; i < got3.Count; i++)
                    for (int j = i + 1; j < got3.Count; j++)
                        if (got3[i] == got3[j]) subOf4 = false;
                Check(subOf4,
                      "★（b）这 3 张是**从 (a) 那个 4 张域里抽出来**的（都在域内、互不重复）："
                      + $"`{string.Join("/", got3.ToArray())}`");

                Check(driver.SimulateChoosePick(0), "（b）点第 1 张候选");
                Check(showPanel.IsPicked(0), "★（b）第 1 张候选真的被标记成选中了");
                Check(driver.SimulateChooseDone(), "（b）点「继续」");
                Check(!showPanel.Visible, "★（b）选完**面板关掉了**");
                ClearEffects();
                Step(0.15f);
            }
        }

        // ---- 21. 🆕 2026-09-14：三选一 / 选效果 / 变身 —— **同一个面板**，候选不是卡池里的卡 ----
        //   为什么是同一个面板：原版 `ChooseCardMenu` 全树**只有两个调用点**（`ChoiceOfCardPlayer`
        //   与 `_SetupEnviromentalEffectPhase`），**没有第三个** —— 「choose one」走的也是它
        //   （`CardScript.NeedsToChooseFromPool()` → `BattleManager.ChooseCardMethod`
        //     → `ChoiceOfCardPlayer` → `ChooseCardMenu.Setup`）。
        //   候选在数据侧是 `TargetCriteria.filterSpecificCards`（`List<RawCardScript>`）——**就是真卡**，
        //   而且面板**带 Done 钮**（`chooseButton` / `ClickChooseDone`）。
        //   ⇒ 我们复用同一个面板 + 同一个「选完点继续」；**不是卡**的那几项由
        //     `BattleDriver.MakeChoiceCard` **合成一张卡**（源卡的插图 + 选项文字当效果文字，
        //     `cost = -1` ⇒ 不画费用六边形）。
        Debug.Log(P + "--- 三选一 / 选效果 / 变身面板 ---");
        {
            var pool = CardDatabase.Load();
            var panel = driver != null ? driver.Choose : null;
            Check(panel != null, "面板还是那一个（三族共用，没另开第三份克隆）");

            // ---- 21-a 三选一：`The Fang` = `Choose one: Deploy a Grey Hunter; Heal 4 … or Draw 2 cards` ----
            var fang = CardDatabase.Find(pool, "The Fang");
            Check(fang != null, "卡池里有 `The Fang`（`chooseone`，费 2）");
            if (fang != null && panel != null)
            {
                ctx = driver.Ctx;
                ctx.Players[0].Hand.Add(ctx.NewInstance(fang));
                ctx.Players[0].Energy = 9;
                driver.RefreshAll();
                Step(0.05f);

                int idx = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, fang)) { idx = i; break; }
                Check(idx >= 0, "注入的那张牌在手牌里");

                int before = UnitsOnBoard(ctx, 0);
                Check(driver.SimulatePlayViaPanel(idx, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走**面板那条路**打出 `The Fang`");
                Step(0.05f);

                Check(panel.Visible, "★ **三选一面板弹出来了**（不用面板的话这一步直接就打出去了）");
                Check(panel.TitleText == ChoosePanel.DefaultTitle,
                      $"★ 标题「{panel.TitleText}」= 原版那唯一一个（原版只有一个 `ChooseText` 对象，"
                      + "运行时**换词条**而不是换标题；原来这里断言的是我们自造的「选择一项」，2026-09-18 删）");
                // 🆕 **2026-10-18（W6）**：选牌面板那**两颗**字也都走原版词条了 ——
                //    · 标题 = `Battle/ChooseCard/Instructions`（英文原文 `Choose one card`）
                //    · 每张牌那颗钮 = `Battle/Prebattle/SelectButton`（英文原文 `Select`）
                //    🔴 后者的键**上一轮被判成「本地查不到 ⇒ 留英文」**（错因：只扫了 `menus` 一个包）⇒ 本批接上。
                Check(panel.CardButtonCount > 0 && panel.CardBtnWordAt(0) == Loc.T(ChoosePanel.SelectTerm),
                      $"★ 每张候选下那颗钮写「{panel.CardBtnWordAt(0)}」= `Loc.T({ChoosePanel.SelectTerm})`"
                    + $"（原版 TMP 原文 `Select`；当前语档 {Loc.Current}）");
                Check(Loc.HasEntry(ChoosePanel.SelectTerm) && Loc.HasEntry(ChoosePanel.TitleTerm)
                   && Loc.HasEntry(MulliganPanel.DoneTerm),
                      "★（坑表 #18）选牌面板用到的三条键在 `Loc` 表里全查得到"
                    + $"（`{ChoosePanel.TitleTerm}` / `{ChoosePanel.SelectTerm}` / `{MulliganPanel.DoneTerm}`）");
                Check(driver.ChooseOptionCount == 3,
                      $"★ 上面摆着 **{driver.ChooseOptionCount}** 张候选（卡面就是三项）");
                Check(driver.ChooseOptionName(0) == "Deploy a Grey Hunter",
                      $"★ 第 1 张候选的卡名「{driver.ChooseOptionName(0)}」= 卡面原文"
                      + "（**不是**小写的 `deploy a grey hunter` —— 解析层 `TryChooseOne` 存的是原文大小写）");
                Check(driver.ChooseOptionName(2) == "Draw 2 cards",
                      $"★ 第 3 张候选「{driver.ChooseOptionName(2)}」");
                Shot(cam, "21a_三选一面板");

                CheckPick(driver, 0, "点第 1 张候选");
                Check(driver.SimulateChooseDone(), "点「继续」");
                Check(!panel.Visible, "★ 选完**面板关掉了**");
                Check(UnitsOnBoard(ctx, 0) > before,
                      $"★ 选第 1 项真的**部署了 `Grey Hunter`**（场上 {before} → {UnitsOnBoard(ctx, 0)} 个单位）");
                ClearEffects();
                Step(0.15f);

            }

            // ---- 21-b 选效果（池子是**真卡**）：`Exemplary Warrior` 的三项就是三张真卡 ----
            var ew = CardDatabase.Find(pool, "Exemplary Warrior");
            Check(ew != null, "卡池里有 `Exemplary Warrior`（`chooseeffect`，费 2）");
            if (ew != null && panel != null)
            {
                ctx = driver.Ctx;
                ctx.Players[0].Hand.Add(ctx.NewInstance(ew));
                ctx.Players[0].Energy = 9;
                driver.RefreshAll();
                Step(0.05f);

                int idx = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, ew)) { idx = i; break; }

                Check(driver.SimulatePlayViaPanel(idx, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走面板那条路打出 `Exemplary Warrior`");
                Step(0.05f);

                Check(panel.Visible, "★ **选效果面板弹出来了**");
                Check(panel.TitleText == ChoosePanel.DefaultTitle,
                      $"★ 标题「{panel.TitleText}」= 同上（原版**不分叉标题**）");
                Check(driver.ChooseOptionCount == 3, $"★ 摆着 {driver.ChooseOptionCount} 张候选");
                Check(driver.ChooseOptionId(0) == "Righteous Fury"
                      && driver.ChooseOptionId(2) == "Paragon of Ultramar",
                      $"★ 三项都是**真卡**（`{driver.ChooseOptionId(0)}` / "
                      + $"`{driver.ChooseOptionId(1)}` / `{driver.ChooseOptionId(2)}`；卡面标题是中文："
                      + $"`{driver.ChooseOptionName(0)}`）"
                      + " —— 池子里的条目本来就是卡名（`ChooseEffectPools`）");
                Shot(cam, "21b_选效果面板");

                CheckPick(driver, 0, "点第 1 张候选（`Righteous Fury`）");
                Check(driver.SimulateChooseDone(), "点「继续」");
                Check(!panel.Visible, "★ 选完**面板关掉了**");
                ClearEffects();
                Step(0.15f);
            }

            // ---- 21-c 选效果（池子是**载荷**）：合成卡 —— 源卡的插图 + 选项文字 ----
            var ha = CardDatabase.Find(pool, "Hyper-adaptation");
            Check(ha != null, "卡池里有 `Hyper-adaptation`（`Choose an effect and give it to a friendly troop`）");
            if (ha != null && panel != null)
            {
                ctx = driver.Ctx;
                ctx.Players[0].Hand.Add(ctx.NewInstance(ha));
                ctx.Players[0].Energy = 9;
                driver.RefreshAll();
                Step(0.05f);

                int idx = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, ha)) { idx = i; break; }

                Check(driver.SimulatePlayViaPanel(idx, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走面板那条路打出 `Hyper-adaptation`");
                Step(0.05f);

                Check(panel.Visible, "★ 面板弹出来了");
                Check(driver.ChooseOptionCount == 6,
                      $"★ 摆着 {driver.ChooseOptionCount} 张候选（`LeviathanEffectPool` = **6 项**，"
                    + "第五十五会话 E10 起按 SO 真值 `…_enchantment1..6` 定；⛔ 不是 3）");
                Check(driver.ChooseOptionName(0) == "+1 Armour"
                      && driver.ChooseOptionName(1) == "+2 Melee Attack"
                      && driver.ChooseOptionName(2) == "+2 Ranged Attack"
                      && driver.ChooseOptionName(3) == "+2 Health"
                      && driver.ChooseOptionName(4) == "Stealth and +1 Armour"
                      && driver.ChooseOptionName(5) == "Vanguard",
                      $"★ 六项是**载荷文字**（`{driver.ChooseOptionName(0)}` / "
                      + $"`{driver.ChooseOptionName(1)}` / `{driver.ChooseOptionName(2)}` / "
                      + $"`{driver.ChooseOptionName(3)}` / `{driver.ChooseOptionName(4)}` / "
                      + $"`{driver.ChooseOptionName(5)}`）"
                      + " —— 合成卡，插图用**这张卡自己的**（用户 2026-09-13 的界面线索）");
                Shot(cam, "21c_选效果_合成卡");

                CheckPick(driver, 0, "点第 1 张候选");
                Check(driver.SimulateChooseDone(), "点「继续」");
                Check(!panel.Visible, "★ 选完**面板关掉了**");
                ClearEffects();
                Step(0.15f);
            }

            // ---- 21-d 变身：`Hrolf the Ironhowl` 的 `become A or B` ----
            // 🔴 **2026-09-14 用户裁决翻了这条的口径**：卡面 `Stratagems in your hand become a
            //    Hunting Wolf or Fenrisian Wolf` **没有 `choose` 字样** ⇒ 按规则书英文版 `:475`
            //    的反面（只有写了 `choose` 才轮到玩家），**引擎随机挑、不开面板**。
            //    ⇒ 这条从「**面板弹出来、摆两只狼**」翻面成「**面板不弹、手牌里的战略卡直接变成一只**」。
            var hrolf = CardDatabase.Find(pool, "Hrolf the Ironhowl");
            Check(hrolf != null, "卡池里有 `Hrolf the Ironhowl`");
            if (hrolf != null && panel != null)
            {
                ctx = driver.Ctx;
                // 手牌里先塞一张**战略卡**（`become` 换的就是手牌里的战略卡）
                var strat = CardDatabase.Find(pool, "Fenrisian Wolfpack");
                Check(strat != null, "卡池里有 `Fenrisian Wolfpack`（拿它当手牌里的战略卡）");
                if (strat != null) ctx.Players[0].Hand.Add(ctx.NewInstance(strat));
                ctx.Players[0].Hand.Add(ctx.NewInstance(hrolf));
                ctx.Players[0].Energy = 9;
                driver.RefreshAll();
                Step(0.05f);

                int idx = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, hrolf)) { idx = i; break; }

                Check(driver.SimulatePlayViaPanel(idx, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走面板那条路部署 `Hrolf the Ironhowl`");
                Step(0.05f);

                Check(!panel.Visible,
                      "★ 变身**不再弹面板** —— 卡面没有 `choose`，按用户口径该**随机**"
                      + "（原来这里钉的是「面板弹出来了」，已推翻）");

                string becomeLog = null;
                foreach (string e in ctx.Events)
                    if (e != null && e.Contains("变身")) becomeLog = e;
                Check(becomeLog != null,
                      "★ 日志里留下了变身那一笔（**不静默**）—— " + (becomeLog ?? "<无>"));

                bool anyWolf = false;
                foreach (var c in ctx.Players[0].Hand)
                    if (c.Card != null && (c.Card.Name == "Hunting Wolf" || c.Card.Name == "Fenrisian Wolf")) anyWolf = true;
                Check(anyWolf, "★ 手牌里的战略卡真的变成了狼（`Fenrisian Wolfpack` 那只不在了）");
                ClearEffects();
                Step(0.15f);
            }

            // ================================================================
            // ---- 21-e. 🆕 2026-10-17（A904 / A905）：ask 点**归谁**、**什么时候问** ----
            // ================================================================
            //   账目 = `资料/普查产出_1017/W_B14_选牌一族.md` §③（触发链）与 §⑥（手牌那一支）；
            //   正本 = `d:/4/Unity/资料/普查产出_1017/W_B22_选牌ask时机.md`。
            //
            //   **原版判据**（反编译）：`BattleManager.ChooseCardMethod(BattleAction, Action<int>)`
            //   是个**迭代器**（`il2cpp_out/dump.cs:31768`），全工程**只有 4 个调用点**，
            //   而且**全在「结算到那一步」**——
            //   `_ResolvePlayCardFromHand_d__447__MoveNext.c:607`（非指向性出牌）· `:827`
            //   （小人落地之后，**外面套着 `CanUseSpiritStone` 那道闸**）· `:1248`（指向性法术之后）·
            //   `_ResolvePlayActiveAbility_d__479__MoveNext.c:367`（**主动技能**）。
            //   每个调用点后面紧跟 `StartCoroutine(...)` + `return 1` ⇒ **结算协程在此挂起**；
            //   玩家的答案由单槽字段 `ChooseCardMenu.selectedCard` → `BattleManager.cardChosenInSelection`
            //   经 `Action<int>` 回调写回 `battleAction.actionValueTens`，协程才继续。
            //   ⇒ **原版没有「出牌前一次问完 + 答案排队」这回事**（那一层根本不存在）。
            //   ⚠️ 我们的引擎是**同步**的（`ResolveOps` 一口气跑完）⇒ 只能在**动作边界**上对齐：
            //      **一次动作 = 一次引擎调用 = 一批 ask 点**。这是与原版**已知的、如实标着的**差距。
            //
            //   🔴 **本节 (a)(c)(d) 三条都是判别式**：把 ask 点挪回「出牌前一次性问完」，
            //      三条会**同时红**（而且 (c)(d) 那条红的样子正是账目里描述的**静默错位**）。
            Debug.Log(P + "--- A904/A905：ask 点的归属与时机 ---");

            // ---- 21-e-① 归属表本身（判据 = `AskOwners`，与面板实际用的是**同一份**）----
            if (driver != null)
            {
                // ⚠️ `B14` 那份普查把这族写成了 **4 张**（`Farseer` / `Farseer Skyrunner` /
                //    `Master Zacharial` / `Suppressor`）—— **漏了 `Azrael` 与 `Watcher in the Dark`**，
                //    两张都是 `Agenda` 那一档。全池实测（1126 张，离线真解析器）是 **6 张**。
                string[,] a904 = {
                    { "Farseer",                 "spirit=1"     },
                    { "Farseer Skyrunner",       "spirit=1"     },
                    { "Suppressor",              "oath=1"       },
                    { "Master Zacharial",        "alt:agenda=1" },
                    { "Azrael",                  "alt:agenda=1" },
                    { "Watcher in the Dark",     "alt:agenda=1" },
                    { "Rapid Deployment",        "play=1"       },
                    { "Chaplain",                "play=1"       },
                    { "Infinite Biomorphologies", "play=1"      },
                };
                for (int i = 0; i < a904.GetLength(0); i++)
                {
                    string got = driver.AskScopesForTest(a904[i, 0]);
                    Check(got == a904[i, 1],
                          $"★ A904 归属表：`{a904[i, 0]}` 的 ask 应归 `{a904[i, 1]}`（实得 `{got}`）");
                }
            }

            // ---- 21-e-② 出牌那一步：灵魂石能力**付得起才问**（原版 `_d__447:723` 那道 `CanUseSpiritStone` 闸）----
            var farseer = CardDatabase.Find(pool, "Farseer");
            Check(farseer != null, "卡池里有 `Farseer`（`1 [Spirit Stone]: Choose a card from your deck and draw it`）");
            if (driver != null && panel != null && farseer != null)
            {
                ctx = driver.Ctx;

                // (a) **0 灵魂石** ⇒ 这一处**不问**（旧写法在**出牌前**就弹了 ⇒ 判别式）
                ctx.Players[0].SpiritStones = 0;
                ctx.Players[0].Energy = 9;
                ctx.Players[0].Hand.Add(ctx.NewInstance(farseer));
                driver.RefreshAll();
                Step(0.05f);
                int f0 = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, farseer)) { f0 = i; break; }
                Check(f0 >= 0, "夹具：`Farseer` 在手牌里");

                int u0 = UnitsOnBoard(ctx, 0);
                Check(driver.SimulatePlayViaPanel(f0, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走**面板那条路**打出 `Farseer`（0 灵魂石）");
                Step(0.05f);
                Check(!panel.Visible,
                      "★ A904 **判别式 (a)**：灵魂石不够 ⇒ **那一处不问**（面板不弹）"
                      + " —— 旧写法在**出牌前**就弹出来了，这条必红");
                Check(UnitsOnBoard(ctx, 0) == u0 + 1,
                      "★ 牌**照样打出去了**（不问 ≠ 这一手不落地）");
                bool saidWhy = false;
                foreach (string e in ctx.Events)
                    if (e != null && e.Contains("这次不会发动")) saidWhy = true;
                Check(saidWhy, "★ 而且**说出了为什么**（战斗日志里有「这次不会发动」那一句"
                             + " —— 红线：不许静默）");
                Check(ctx.ChoosePicks.Count == 0 && ctx.ChooseCardIds.Count == 0,
                      $"★ A904 清队：出牌之后队列是空的（实得 {ctx.ChoosePicks.Count}+{ctx.ChooseCardIds.Count}）"
                      + " —— 旧写法这里是 1，而那 1 格会被**下一处**选择吃掉、此后全部错位**且不报错**");
                ClearEffects();
                Step(0.1f);

                // (b) **2 灵魂石** ⇒ 这一处**在出牌这一步问**（付得起就发动，原版同）——
                //     与 (a) 一起把「什么时候问」两头夹住
                ctx.Players[0].SpiritStones = 2;
                ctx.Players[0].Energy = 9;
                ctx.Players[0].Hand.Add(ctx.NewInstance(farseer));
                driver.RefreshAll();
                Step(0.05f);
                int f1 = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, farseer)) { f1 = i; break; }
                Check(driver.SimulatePlayViaPanel(f1, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走面板那条路打出第二张 `Farseer`（2 灵魂石）");
                Step(0.05f);
                Check(panel.Visible, "★ **付得起 ⇒ 面板弹出来了**（这一处属于「这一次出牌」）");
                Check(driver.ChooseOptionCount >= 1,
                      $"★ 候选 **{driver.ChooseOptionCount}** 张（牌库里的卡）");
                // 🔴 2026-10-17（F6 #5）：这一句原来取的是 `ChooseOptionId(0)`，而它返回的是
                //    **卡名**（本仓 `CardData.id` = 显示名，`ToCardData` 里写的就是 `id = c.Name`），
                //    下面却拿它跟 `CardDef.Id` 比 ⇒ **恒不相等**（这张红跟引擎无关）。
                //    引擎那侧是对的：`OnChooseDone` 入队的是 `_askCands[picks[0]].Id`。
                string wantId = driver.ChooseOptionStableId(0);
                CheckPick(driver, 0, "点第 1 张候选（走面板的命中判定）");
                Check(driver.SimulateChooseDone(), "点「继续」");
                Check(!panel.Visible, "★ 选完面板关掉了");
                bool drawn = false;
                foreach (var h in ctx.Players[0].Hand)
                    if (h.Card != null && h.Card.Id == wantId) drawn = true;
                Check(drawn, $"★ 引擎按面板选的把 `{wantId}` **从牌库抽上了手**（那一条真的结算了）");
                Check(ctx.ChoosePicks.Count == 0 && ctx.ChooseCardIds.Count == 0,
                      "★ A904 清队：答案被这一手用掉了，队列空");
                ClearEffects();
                Step(0.1f);
            }

            // ---- 21-e-③ 主动技能那一步：`Agenda` 的 ask **点下去那一刻才问** ----
            var watcher = CardDatabase.Find(pool, "Watcher in the Dark");
            Check(watcher != null,
                  "卡池里有 `Watcher in the Dark`（`Agenda:` 的正文里带 `Choose a non-Legendary Dark Angels card`）");
            if (driver != null && panel != null && watcher != null)
            {
                ctx = driver.Ctx;
                ctx.Players[0].Energy = 9;
                ctx.Players[0].Hand.Add(ctx.NewInstance(watcher));
                driver.RefreshAll();
                Step(0.05f);
                int w0 = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, watcher)) { w0 = i; break; }
                Check(w0 >= 0, "夹具：`Watcher in the Dark` 在手牌里");

                int u1 = UnitsOnBoard(ctx, 0);
                Check(driver.SimulatePlayViaPanel(w0, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走面板那条路打出 `Watcher in the Dark`");
                Step(0.05f);
                Check(!panel.Visible,
                      "★ A904 **判别式 (c)**：议程那一处**出牌时不问**"
                      + " —— 旧写法这里会弹，而那格答案会一直留在队里"
                      + "（技能整局不发动 ⇒ 永远没人取 ⇒ 被**下一处**选择吃掉）");
                Check(UnitsOnBoard(ctx, 0) == u1 + 1, "★ 单位照样落地");
                bool saidDefer = false;
                foreach (string e in ctx.Events)
                    if (e != null && e.Contains("等那格技能真的发动时再问")) saidDefer = true;
                Check(saidDefer, "★ 而且**说出了往后挪到哪一步**（日志里有「等那格技能真的发动时再问」"
                               + " —— 红线：不许静默）");
                Check(ctx.ChoosePicks.Count == 0 && ctx.ChooseCardIds.Count == 0,
                      $"★ A904 清队：出牌之后队列是空的（实得 {ctx.ChoosePicks.Count}+{ctx.ChooseCardIds.Count}；"
                      + "旧写法这里是 1）");
                ClearEffects();
                Step(0.1f);

                // 找到它落在哪一格；把本回合的行动解开（夹具：议程受「与攻击同限制」，
                // 部署当回合 `Exhausted` —— 同 §「议程那一条」既有的 `Ravenwing Bikes` 夹具写法）
                int ws = -1;
                for (int s = 0; s < BoardSpec.Size; s++)
                {
                    var u = ctx.Players[0].Board[s];
                    if (u != null && u.Card != null && u.Card.Id == watcher.Id) { ws = s; break; }
                }
                Check(ws >= 0, "夹具：`Watcher in the Dark` 在场上");
                if (ws >= 0)
                {
                    ctx.Players[0].Board[ws].Exhausted = false;
                    driver.RefreshAll();
                    Check(driver.SimulateOpenCommand(ws), "点它 → 攻击方式选择器弹出");
                    Check(driver.HasCommand(AttackKind.Ability),
                          "★ 带 `Agenda` 的单位给出了主动技能那一格");
                    driver.SimulateCommand(AttackKind.Ability);   // = 玩家在选择器里点「技能」
                    Step(0.05f);
                    Check(panel.Visible,
                          "★ A904 **判别式 (d)**：**面板在这里才弹**（技能真的发动那一刻）"
                          + " —— 原版同一处 = `_ResolvePlayActiveAbility_d__479__MoveNext.c:367`");
                    Check(driver.ChooseOptionCount >= 1,
                          $"★ 候选 **{driver.ChooseOptionCount}** 张"
                          + "（= 牌库里**非传说暗黑天使**卡，实测全池 69 张）");
                    int hand0 = ctx.Players[0].Hand.Count;
                    // 🔴 2026-10-17（F6 #6）：同 #5 —— 面板那几个 `CardData` 的 `id` 是**卡名**，
                    //    引擎记的却是 `CardDef.Id`；要比「引擎用的是面板给的那一张」得用**稳定卡号**。
                    string wid = driver.ChooseOptionStableId(0);
                    CheckPick(driver, 0, "点第 1 张候选");
                    Check(driver.SimulateChooseDone(), "点「继续」");
                    Check(!panel.Visible, "★ 选完面板关掉了");
                    bool landed = false;
                    foreach (var h in ctx.Players[0].Hand)
                        if (h.Card != null && h.Card.Id == wid) landed = true;
                    Check(landed, $"★ 议程真的结算了：`{wid}` 进了手牌"
                                + $"（手牌 {hand0} → {ctx.Players[0].Hand.Count}）");
                    Check(ctx.ChoosePicks.Count == 0 && ctx.ChooseCardIds.Count == 0,
                          "★ A904 清队：答案被这一手用掉了，队列空");
                    ClearEffects();
                    Step(0.15f);
                }
            }

            // ---- 21-e-④ A905：`Infinite Biomorphologies` 的「给手牌」那一支 —— 面板**照常开** ----
            //   引擎侧 2026-09-16 就做完了（`DoChooseEffect` 的 `handScope` → `RuleCore.AttachHandEffect`
            //   → **`CardInstance.HandEffects`** → `RuleCore.ApplyHandBuffs`），原来只有 `ShowAsk` 里那条
            //   ⚠️ **2026-10-18（`A886` ①）就地订正**：原来这句写的是「… → **`ctx.HandBuffs`** → …」——
            //      **那张对局级的表已经不在了**（`A885` 搬到 `CardInstance.HandEffects`，
            //      判据 `RuleEngine/Core/BattleContext.cs:501-511`）。
            //   「这一版没做，不问了」的短路把玩家挡在外面 ⇒ **引擎按 `ctx.Rng` 替他挑**
            //   （那正是「静默替玩家做决定」）。本条判断 = **面板必须开、三项照旧**。
            var bio = CardDatabase.Find(pool, "Infinite Biomorphologies");
            Check(bio != null, "卡池里有 `Infinite Biomorphologies`（`chooseeffect`，载荷 = `hand`）");
            if (driver != null && panel != null && bio != null)
            {
                ctx = driver.Ctx;
                ctx.Players[0].Energy = 9;
                ctx.Players[0].Hand.Add(ctx.NewInstance(bio));
                driver.RefreshAll();
                Step(0.05f);
                int b0 = -1;
                for (int i = 0; i < ctx.Players[0].Hand.Count; i++)
                    if (ReferenceEquals(ctx.Players[0].Hand[i].Card, bio)) { b0 = i; break; }
                Check(b0 >= 0, "夹具：`Infinite Biomorphologies` 在手牌里");

                // 🔴 2026-10-17（F6 #7）：**基线必须取在「打出之前」** —— A904 改成「先问后打」之后，
                //    面板还开着的时候那张牌**还在 `ps.Hand` 里**（`DoPlay` 挂在 ask 的续跑闭包里，
                //    真正 `ps.Hand.RemoveAt` 在 `EffectResolver.PlayTactic` 才发生）⇒ 原来那句基线
                //    读到的是「含打出的那一张」的张数，才显得「打完了张数没变」。
                int handBefore = ctx.Players[0].Hand.Count;
                Check(driver.SimulatePlayViaPanel(b0, SimpleAI.FirstFreeSlot(ctx.Players[0])),
                      "走面板那条路打出 `Infinite Biomorphologies`");
                Step(0.05f);
                Check(panel.Visible,
                      "★ A905 **判别式**：「给手牌里的全部部队」这一支**面板要照常弹**"
                      + " —— 旧那行短路写的是「这一版没做，不问了」，这条必红");
                Check(driver.ChooseOptionCount == 6,
                      $"★ **六项**照旧（实得 {driver.ChooseOptionCount} —— 池子是 `LeviathanEffectPool`，"
                    + "SO 真值 `…_enchantment1..6`；原来写 3 的那条已在第五十五会话 E10 过期）");
                Check(driver.ChooseOptionName(0) == "+1 Armour"
                      && driver.ChooseOptionName(2) == "+2 Ranged Attack"
                      && driver.ChooseOptionName(3) == "+2 Health"
                      && driver.ChooseOptionName(4) == "Stealth and +1 Armour"
                      && driver.ChooseOptionName(5) == "Vanguard",
                      $"★ 六项文字：`{driver.ChooseOptionName(0)}` / `{driver.ChooseOptionName(1)}` / "
                      + $"`{driver.ChooseOptionName(2)}` / `{driver.ChooseOptionName(3)}` / "
                      + $"`{driver.ChooseOptionName(4)}` / `{driver.ChooseOptionName(5)}`");
                int ans0 = ctx.ChooseAnswered;
                CheckPick(driver, 0, "点第 1 项（`+1 Armour`）");
                Check(driver.SimulateChooseDone(), "点「继续」");
                Check(!panel.Visible, "★ 选完面板关掉了");
                // 🔴 判据是「引擎用的是**面板给的**那一项」——`ChooseAnswered` 只在 `TakePick`
                //    出队成功时才 +1（`EffectResolver.cs:2020`）；引擎替玩家挑时**只加 `ChooseSites`**。
                Check(ctx.ChooseAnswered > ans0,
                      "★ 引擎用的是**面板给的**那一项（`ChooseAnswered` 涨了）"
                      + " —— 不是 `ctx.Rng` 替玩家挑的（旧写法就是那条路：玩家连面板都看不到）");
                string buffLog = null;
                foreach (string e in ctx.Events)
                    if (e != null && e.Contains("选效果")) buffLog = e;
                Check(buffLog != null,
                      "★ 日志里留下了这次选效果那一笔（**不静默**）—— " + (buffLog ?? "<无>"));
                // ⚠️ **落点**（`RuleCore.AttachHandEffect` → `CardInstance.HandEffects` → `ApplyHandBuffs`）由
                //    （2026-10-18 · `A886` ①：原来的 `ctx.HandBuffs` 那张对局级表已随 `A885` 搬走）
                //    `RuleEngineTest` ⑥/⑧ 断；这里只管**玩家选得到**这件事 + 张数那笔账 ——
                //    🔴 2026-10-17（F6 #7）：原来这里写「选完手牌张数**不变**是正常的」，**那是错的**
                //    （基线取在面板还开着的时候了，见上面那条注释）⇒ 现在断「只少打出的那一张」。
                Check(ctx.Players[0].Hand.Count == handBefore - 1,
                      $"★ 手牌只少打出的那一张（{handBefore} → {ctx.Players[0].Hand.Count}；给的是加成、不是换牌）"
                    + " —— ⛔ 别退化成「≥」：多退/少退都是错");
                Check(ctx.ChoosePicks.Count == 0 && ctx.ChooseCardIds.Count == 0,
                      "★ A905 清队：答案被这一手用掉了，队列空");
                ClearEffects();
                Step(0.15f);
            }
        }

        Application.logMessageReceived -= dwCounter;
        Check(dotween == 0, $"全程没有 DOTween 补间报错（实测 **{dotween}** 条；"
                          + "真包里这一族曾经有 22 条，成因与修法见 `资料/特效还原_进度与交接.md` §七）");

        // ==================================================================
        //  🆕 2026-10-11（A218）：「空节点工厂」那一族的 **`sizeDelta`**
        //
        //  为什么单开一段：A92 把那一族的**类型**补成了 `RectTransform`，但 `sizeDelta` 仍是默认值 ⇒
        //  「空节点 + 原版像素矩形」的**宽高验收不了**（判据原文 = `资料/待办判据_1007.md` §A218 的 ①）。
        //  判据 = **原版那一件自己的 `rect`**（2026-10-11 逐个现读 `bundle_scenes_scenes_battlearena1`，
        //  出处逐条写在断言里），⛔ 不读被测实现、也不拿我们的常量当期望值。
        //  验收口径 = `rect.width/height` == 原版那对 px（经**唯一那一份**换算 `LayoutSpace.Px`）。
        //  ⚠️ 这一段在 `logMessageReceived` 摘掉**之后** —— 探针建/毁不掺进上面那条 DOTween 计数。
        Debug.Log(P + "--- §A218 空节点工厂的 `sizeDelta`（`rect` 的宽高 = 原版矩形）---");
        {
            // 一具「断这个节点的 `rect` = 原版那对 px」的小尺子（只本段用）。
            // 🔴 断的是 **`rect`** 而不是 `sizeDelta` —— 那正是本件的验收口径（写 `sizeDelta` 只是手段）。
            // 🔴 **父链缩放核查**：`rect` 与「设计 px」同量纲**只在父链 `lossyScale == 1` 时成立** ⇒ 每条都先断这条前置
            //    （本工程今天全部成立：`WindowsManager.AttachToAnchor` 把窗根写成 `localScale = one`；战斗侧这些件挂在
            //     `HudRoot` 下、链上无缩放；⛔ 非 1 的档不能直接比设计 px，要按 `MenuDraw.SetPxSize` 的注释单独算）。
            System.Action<Transform, string, float, float, string> box = (t, what, wPx, hPx, src) =>
            {
                if (t == null) { Check(false, $"（前提）{what} 没建出来"); return; }
                var rt = t.GetComponent<RectTransform>();
                Check(rt != null, $"（前提）{what} 是 `RectTransform`（A92 那半）");
                if (rt == null) return;
                // 🔴🔴 **2026-10-16（`T09` 批 2）给【画布下的件】另开一支尺子** ——
                //   它们的 `lossyScale` 是**画布那一级**（16:9 = 1/108），而 `rect/sizeDelta`
                //   **单位就是设计 px** ⇒ 上面那两条老前提（`lossyScale == 1`、比 `LayoutSpace.Px(wPx)`）
                //   **对它一条都不成立**。⛔ 别把老那支硬套到画布件上（会红得莫名其妙）。
                //   ✅ 这一支：**直接拿 `rect` 比 px**（`wPx/hPx` 就是 px）—— 与断言的字面量同口径。
                if (t.GetComponentInParent<Canvas>() != null)
                {
                    float rw = rt.rect.width, rh = rt.rect.height;
                    bool stretched = Mathf.Abs(rt.anchorMin.x) < 1e-3f && Mathf.Abs(rt.anchorMax.x - 1f) < 1e-3f
                                  && Mathf.Abs(rt.anchorMin.y) < 1e-3f && Mathf.Abs(rt.anchorMax.y - 1f) < 1e-3f;
                    Check(Mathf.Abs(rw - wPx) < 0.05f && Mathf.Abs(rh - hPx) < 0.05f,
                          $"★ {what} 的 `rect` = **{rw:F2} × {rh:F2} px**（原版 {wPx:F2}×{hPx:F2} —— {src}）"
                        + $"｜（画布下的件：`anchor {(stretched ? "stretch" : "重合")}`、单位 = 设计 px）");
                    return;
                }
                var ls = t.lossyScale;
                Check(Mathf.Abs(ls.x - 1f) < 1e-3f && Mathf.Abs(ls.y - 1f) < 1e-3f,
                      $"（前提·父链缩放）{what} 的 `lossyScale` = ({ls.x:F3},{ls.y:F3})，应为 1（= 本件验收口径成立的那一档）");
                Check(rt.anchorMin == rt.anchorMax && rt.pivot == new Vector2(0.5f, 0.5f),
                      $"（前提）{what} 的锚点重合、pivot 居中（`rect` 只由 `sizeDelta` 决定的前提）");
                Check(Mathf.Abs(rt.rect.width - LayoutSpace.Px(wPx)) < 0.01f
                      && Mathf.Abs(rt.rect.height - LayoutSpace.Px(hPx)) < 0.01f,
                      $"★ {what} 的 `rect` = **{rt.rect.width * EndPanel.PxPerUnit:F1} × {rt.rect.height * EndPanel.PxPerUnit:F1} px**"
                      + $"（原版 {wPx:F2}×{hPx:F2} —— {src}）");
            };

            var a218root = new GameObject("A218ProbeRoot");
            // ① 整屏那几扇：原版 `anchor (0,0)-(1,1)` + `sizeDelta (0,0)` ⇒ 绝对矩形 **(0,0)-(1920,1080)**
            // 🔴 **2026-10-16（`T09` 批 2）**：画布下那几件的「整屏矩形」= **画布自己的 rect**，
            //   ⛔ 不是写死的 `1920×1080` —— `Expand` 档下**屏比画布高**时它会更大
            //   （批处理 `640×480` ⇒ `scaleFactor 0.3333` ⇒ 画布 **1920×1440 单位**）✓ 与原版一致。
            var a218Cv = HudCanvas.RootRect;
            float a218CvW = a218Cv != null ? a218Cv.rect.width : 1920f;
            float a218CvH = a218Cv != null ? a218Cv.rect.height : 1080f;
            var a218End = EndPanel.Create(a218root.transform);
            // 🔴 **2026-10-24（`B-26`）**：期望值换了 —— 面板现在挂在**原版那棵树**里
            //   （`BattleDoors`(1920.1199×1118.981) → `Canvas` → `EndBattlePanel`），
            //   而 `FillParent` 拿的是**父画布 rect** = 那颗 `BattleDoors` 的矩形 ⇒ **1920.1199 × 1118.981**
            //   （原来这里是 `a218CvW/H` = 根画布的 rect，因为当时面板直接铺在根画布下）。
            box(a218End.transform, "结算面板根 `EndBattlePanel`", 1920.1199f, 1118.981f,
                "原版 `EndBattlePanel`（`anchor (0,0)-(1,1)` + `sd (0,0)` ⇒ 铺满父画布 `BattleDoors/Canvas`，"
              + "而那块画布 stretch 到 `BattleDoors`(RT 1920.1199×1118.981)）");
            box(a218End.transform.Find("content"), "结算内容层 `content`", 1920.1199f, 1118.981f,
                "⚠️ **本层是我们自己的**（原版 `EndBattlePanel` 下没有这一级）⇒ 取它真正占的那块 = 父面板矩形");
            box(a218End.transform.Find("AllRewardsHolder/SkullsHolder"), "骷髅行 `SkullsHolder`", 648.1f, 52.4f,
                "原版 `SkullsHolder` 的 `m_SizeDelta (648.1, 52.38)`（末位 0.02px 取本文件一直在用的 52.4）"
              + "｜🔴 2026-10-24（`B-26`）：父件换成原版的 `AllRewardsHolder`（100×100 @ 面板中心 −259.5）");
            // 🔴 **2026-10-16（`T09` 批 3）**：这两扇已迁到 `OverHand` 子画布、且是 **stretch** ⇒ 矩形 = **画布矩形**
            //   （`Expand` 档下可能比 1920×1080 大）⇒ 期望值改用上面那对 `a218CvW/H`。
            //   ⚠️ ✅ **2026-10-16 就地订正（铁律 5 · 收口台账 `W45`）**：本行原文写「`UnitChatPanel` **还没迁**
            //      ⇒ 它那一条照旧」—— **已过期**：`A1`/`A12` 已把它迁完（宿主 `"Unit Chat Canvas"`、
            //      `OverHand`/order 0、原版子件序 **2/14**），下面那一条因此**一起换成画布矩形口径**。
            box(MulliganPanel.Create(a218root.transform).transform, "换牌面板根 `MulliganPanel`",
                a218CvW, a218CvH, "原版 `Mulligan`（stretch ⇒ **铺满父画布**）");
            var a218Cdw = CardDisplayWindow.Create(a218root.transform);
            box(a218Cdw.transform, "卡牌展示窗根",
                a218CvW, a218CvH, "原版 `Card Display Window`（stretch ⇒ **铺满父画布**）");
            // 🔴🔴 **灭自证（写手 A 建议、主对话采纳）**：迁完之后**这一扇里一件世界空间 `ImageQuad` 都不该剩** ——
            //   这是「没有一件还留在世界空间」的**机械证明**，比逐件断矩形强得多、也更早抓到漏迁。
            //   ⚠️ **有意留在世界空间**的那一件（`Menu Dark Background` 压暗层：它必须画在**卡体下面**，
            //     而卡体还是 `Default` 层的世界件 ⇒ 上画布反而会盖住卡）挂在**世界壳**上，
            //     ⛔ **不在** `a218Cdw.transform` 之下 ⇒ 本条仍应为 **0**。判据与裁定 → `T09` §八·5。
            Check(a218Cdw != null && a218Cdw.transform.GetComponentsInChildren<ImageQuad>(true).Length == 0,
                  "★ `T09` 批 3（**机械证明**）：卡牌展示窗里**一件世界空间 `ImageQuad` 都不剩**"
                + "｜🧨 漏迁一件 ⇒ 本条红");
            // 🔴 **2026-10-16（`T09` 批 3 补正 · 台账 `W45`）**：这扇探针**改成传宿主** ——
            //   ① `UnitChatPanel` 的画布档只有「有人把子画布喂进来」才成立（`Create(parent, uguiHost)`）；
            //   ② 期望值换 **画布矩形**（`Unit Chat` 原版是 `stretch` ⇒ 铺满父画布，`Expand` 档下比 1080 高）；
            //   ⚠️ `HudCanvas.EnsureSubCanvas` **按名字幂等**（先例 `Mulligan Canvas`）⇒ 这里「建/取」同一块。
            var a218UcCv = HudCanvas.EnsureSubCanvas(null, UnitChatPanel.SubCanvasName,
                                                    UnitChatPanel.SortingLayerId, UnitChatPanel.SortingOrder);
            var a218Uc = UnitChatPanel.Create(a218root.transform, a218UcCv);
            box(a218Uc != null ? a218Uc.transform : null, "单位语音条根", a218CvW, a218CvH,
                "原版 `Unit Chat`（stretch ⇒ **铺满父画布**）");
            var a218Choose = ChoosePanel.Create(a218root.transform);
            box(a218Choose.transform, "选牌面板**世界壳**", 1920f, 1080f,
                "原版 `ChooseCardMenu`（stretch ⇒ 整屏）；⚠️ 该节点已降级成世界壳（压暗层仍世界空间）");
            // 🔴 **2026-10-16（`T09` 批 3）**：**本体**现在在画布上（`FillParent` = 原版 `(0,0)-(1,1)+sd 0`）——
            //   ⛔ 期望值跟**画布矩形**走（`Expand` 档下屏比画布高时它不是 1080）。
            box(a218Choose.PanelRect, "选牌面板**本体**（画布上）", a218CvW, a218CvH,
                "原版 `ChooseCardMenu`（stretch ⇒ **铺满父画布**）");
            var a218Log = BattleLogPanel.Create(a218root.transform);
            // 🔴🔴 **2026-10-16（`T09` 批 2）：这一扇已迁到子画布** ⇒
            //   ① 两个节点都换**画布矩形**口径（上面那个 `a218CvW/H`）；
            //   ② ⛔ **别再用 `a218root.transform.Find("CemeteryLogPanel")`** —— 它现在挂在子画布下，找不到。
            //   ⚠️ **如实记一处与原版不符（铁律 11 要做的账）**：原版 `CemeteryLogPanel` 自己那一级的 rect 是
            //     **794.07 × 653.80**（`m_SizeDelta (794.06897, **0**)` + 竖直 stretch、高 = 0.60537014×1080），
            //     而我们**没有节点承载它**（那块宽度只当布局判据 `PanelW`）⇒ **本条的期望值因此不再是原版那个矩形**、
            //     只能断「铺满画布」。⇒ **新账**（`T09` §五·补⑩ §七），⛔ 不是「已经复刻」。
            box(a218Log.PanelRect, "日志面板根", a218CvW, a218CvH,
                "⚠️ **本层是我们自己的**（原版那一级是 `Safe area BackCanvas/LeftArea`，实读 RT · `sizeDelta (0,0)` ⇒ 铺满）"
              + "；原版 `CemeteryLogPanel` **自己那一级**是 794.07×653.80 —— 见上面那段如实记的差异");
            // ② 非整屏那几扇（原版那对数值逐条现读）
            var a218Mcd = MultiCardDisplay.Create(a218root.transform);
            box(a218Mcd.transform, "多卡展示窗**世界壳**", 1920f, 818f,
                "原版 `Generic Multi Card Display Combat`（横向 stretch + `sizeDelta (0, 818.04)`）"
              + "；⚠️ 该节点已降级成世界壳（压暗层与卡体仍在世界空间）");
            // 🔴 **2026-10-16（`T09` 批 3）**：**本体**在画布上 —— 原版那条是**横向 stretch + `sd.y = 818.04`**
            //   ⇒ `rect` = (**画布宽**, 818)（⛔ 宽别写死 1920，见 `T09` §五·补⑩ §七·8）。
            box(a218Mcd.PanelRect, "多卡窗**本体**（画布上）", a218CvW, 818f,
                "原版 `Generic Multi Card Display Combat`（横向 stretch + `sd.y 818.04`）");
            // 🔴 **2026-10-16（`T09` 批 2）**：这扇迁到画布后**分成了两个节点** ——
            //   原先那个根降级成「**世界壳**」；
            //   🔴 **2026-10-17（`EW13` · `T09` 块 6）就地订正（铁律 5）**：本行原文写「只装那 3 根
            //   还没迁的 `WfSlider`」—— **已过期**：那三根在本批**也迁到 `_panel` 上了**
            //   ⇒ 这个壳现在**一个件都不装**（只剩 `sizeDelta` 给 `A218` 读，⛔ 别顺手删它）。
            //   面板本体（原版那颗 `BattleSettingsPanel`）现在在**画布上**的新节点里。
            //   ⇒ 原来只有一条，量的是世界壳；现在**两条都要**（壳那条的数字照旧、本体那条才是原版判据）。
            var a218Set = SettingsPanel.Create(a218root.transform, null);   // 2026-10-22：`onCycleDifficulty` 已删
            box(a218Set.transform, "对局内设置面板**世界壳**（**已空**，只留 `sizeDelta`）", 743.2f, 758.6f,
                "⚠️ 本节点已降级成世界壳 —— 它的矩形仍照原版写；原版的**面板本体**在下面那条");
            box(a218Set.PanelRect, "对局内设置面板**本体**（画布上）", 743.202f, 758.6345f,
                "原版 `BattleSettingsPanel` 的 `m_SizeDelta (743.202, 758.6345)`");
            // 🔴 **2026-10-16（收口 · 台账 `W45`）**：同样**改成传宿主**（`"ChatPopup Canvas"`）——
            //   期望值 **`815.04 × 475.47` 不用改**：画布档那对数是写进 `sizeDelta` 的真 px，
            //   而 `box()` 认得出画布子件、会自动走「直接比 `rect`」那一支（两档同值 ⇒ 这一条是干净的判别式）。
            var a218PopCv = HudCanvas.EnsureSubCanvas(null, ChatPopupPanel.SubCanvasName,
                                                     ChatPopupPanel.SortingLayerId, ChatPopupPanel.SortingOrder);
            var a218Pop = ChatPopupPanel.Create(a218root.transform, a218PopCv);
            box(a218Pop != null ? a218Pop.transform : null, "聊天弹幕根 `ChatPopup`", 815.04f, 475.47f,
                "原版 `ChatPopup` 的 `m_SizeDelta (815.044, 475.470)`");
            // 🔴 **2026-10-16（收口 · 台账 `W45` + `W11` 同一族）：子画布结构 + `OnCanvas` 灭自证。**
            //   判据（期望值一律取【判据侧】，⛔ 不读 `HudCanvas.SubCanvas(name)` 自己的值 ⇒ 那是拿实现证明实现）：
            //     · 层 = `OverHand` / order = 0 / `overrideSorting = true` —— 出处 `T09c` §一 那两行
            //       （原版 `Unit Chat` 子件序 **2/14** · `ChatPopup` **4/7**，两块都落 `OverHand`/0）；
            //     · **子画布不许带 `CanvasScaler`**：原版**全场景只有一个**、在根上（`T09` §五·补⑨ 一）⇒ 带了会**二次缩放**。
            //   🧨 改坏法：把 `HudCanvas.EnsureSubCanvas` 里那三行赋值删掉 ⇒ 层/order 那一对红；
            //      给子画布 `AddComponent<CanvasScaler>()` ⇒ 第四条红。
            System.Action<string, string> subCv = (name, who) =>
            {
                var cv = HudCanvas.SubCanvas(name);
                Check(cv != null && cv.overrideSorting,
                      $"★ `T09`/{who}：子画布 `{name}` 的 `overrideSorting = true`（原版子 canvas 都另立排序组）");
                Check(cv != null && cv.sortingLayerID == HudCanvas.SortingLayer.OverHand,
                      $"★ `T09`/{who}：`{name}` 的排序层 = `OverHand`（判据 = `T09c` §一；实得 {cv?.sortingLayerID}）");
                Check(cv != null && cv.sortingOrder == 0,
                      $"★ `T09`/{who}：`{name}` 的 order = 0（原版那一行；实得 {cv?.sortingOrder}）");
                Check(cv != null && cv.GetComponent<CanvasScaler>() == null,
                      $"★ `T09`/{who}：`{name}` **不带** `CanvasScaler`（原版全场景只有一个、在根上；带了 = 二次缩放）");
            };
            subCv(UnitChatPanel.SubCanvasName, "Unit Chat");
            subCv(ChatPopupPanel.SubCanvasName, "ChatPopup");
            // 🔑 **`OnCanvas` 灭自证（正面那一半）**：图与字**全在 uGUI 画布父链下**。
            //   它防的是本批最坏的那一档：**一半件在画布、一半还在世界** —— 16:9 下逐位相同、全绿，
            //   只有别的宽高比才露（`T09` §五·补⑦）。⛔ 别用「`HudPiece != null`」替它（那个两档都真 = 同义反复）；
            //   ⛔ 也别用「`IsUgui`」替它（那个只看**宿主登记了没**，不看**件建在哪**）。
            //   （反面那一半 —— 「世界档下 `OnCanvas` 必须为假」—— 写在上面世界档那两节里，两半配对才挡得住「写成恒真」。）
            Check(a218Uc != null && a218Uc.OnCanvas,
                  "★ `T09`（灭自证）`UnitChatPanel` 三颗气泡的图与字**都在 uGUI 画布上**｜🧨 漏迁一件 ⇒ 红");
            Check(a218Pop != null && a218Pop.OnCanvas,
                  "★ `T09`（灭自证）`ChatPopupPanel` 7 张图 + 6 颗钮的字**都在 uGUI 画布上**｜🧨 漏迁一件 ⇒ 红");
            var a218Replay = ReplayBar.Create(a218root.transform);
            box(a218Replay.transform, "回放条根", 293.6f, 57.41f,
                "原版 `ReplayButtons` 的 `m_SizeDelta (293.6, 57.406)`");
            box(a218Replay.transform.Find("Holder"), "回放条 `Holder`", 258.54f, 59.43f,
                "原版 `Holder`（= 字段 `objHolder`）绝对 rect `x[416.3,674.8] y[36.3,95.7]`");
            var a218Doors = BattleDoors.Create(a218root.transform);
            box(a218Doors.transform, "开门视频根 `BattleDoors`", 1920.1199f, 1118.981f,
                "原版 `BattleDoors` 的 `m_SizeDelta`"
              + "｜⚠️ **2026-10-16 就地订正（铁律 5）**：本条文案原来写「缩放**不复刻**」—— **已过期**，"
              + "`A2105②` 早就把 `localScale 1.06647` 补上了（所以这里的 `rect` = `m_SizeDelta`、**视觉**再 ×1.0665）"
              + "｜🔴 2026-10-24（`B-26`）：它是**外骨架**（`BattleDoors → Canvas → EndBattlePanel`），"
              + "自己不再装视频节点");
            // 🔴 **2026-10-24（`B-26`）**：视频那一颗挂在**面板根**下、名字是原版的 **`Video Image`**
            //   （原来叫 `video_player`、挂在 `BattleDoors` 下 —— 那是父子颠倒时的形状）。
            //   探针这里没有真面板 ⇒ `BattleDoors.Create(裸节点)` 会把它建在**共用子画布**下
            //   （见 `Create` 里那段「裸节点 ⇒ 退到子画布」的口径）⇒ 从 `CanvasTransform` 找它。
            var a218Video = a218Doors != null && a218Doors.CanvasTransform != null
                          ? a218Doors.CanvasTransform.Find("Video Image")
                          : a218root.transform.Find("Video Image");
            box(a218Video, "视频组件宿主 `Video Image`", 1920f, 1080f,
                "原版 `Video Image`（`VideoPlayer` 组件的宿主就是它；`EndBattlePanel/Video Image`）");
            // ---- 🔴 2026-10-24（`B-26`）：整棵树的**形状**必须与原版一致 ----
            //   出处 `资料/说明书/01_战斗_对战/2D层_battlearena2全树.md:1195-1200`：
            //     `BattleDoors (inactive)` → `Canvas` → `EndBattlePanel` → { `Background` · `Video Image` ·
            //     `AllRewardsHolder`（→ `SkullsHolder` / `RewardsHolder`）}
            //   ⚠️ 我们**多一层** `content`（自建的内容层，原版没有；判据见 `EndPanel` 文件头）——
            //      这里把它**列出来**而不是假装它不存在（`多的报`）。
            //   🧨 改坏法：把面板再挂回根画布（或把 `BattleDoors` 挂回面板下面 = 改之前那棵倒置树）⇒ 前两条红。
            {
                var b26Panel = a218End != null ? a218End.transform : null;
                Check(b26Panel != null && b26Panel.name == "EndBattlePanel",
                      $"★ B-26：结算面板那一级叫 **`EndBattlePanel`**（原版名；实得「{(b26Panel != null ? b26Panel.name : "<没有面板>")}」）");
                var b26Cv = b26Panel != null ? b26Panel.parent : null;
                Check(b26Cv != null && b26Cv.name == "BattleDoors Canvas" && b26Cv.GetComponent<Canvas>() != null,
                      "★ B-26：面板的父级 = **`BattleDoors/Canvas`** 那块子画布（原版那一级就叫 `Canvas`；"
                    + $"我们沿用 `CanvasName`。实得「{(b26Cv != null ? b26Cv.name : "<无父级>")}」"
                    + $"，带 `Canvas` = {(b26Cv != null && b26Cv.GetComponent<Canvas>() != null)}）");
                var b26Doors = b26Cv != null ? b26Cv.parent : null;
                Check(b26Doors != null && b26Doors.name == "BattleDoors",
                      "★ B-26：子画布的父级 = **`BattleDoors`**（外骨架，带 `localScale 1.06647`）"
                    + $"（实得「{(b26Doors != null ? b26Doors.name : "<无父级>")}」）"
                    + "｜🧨 父子颠倒（我们改之前：`EndPanel → BattleDoors`）⇒ 本条与前一条都红");
                // 原版那三颗子件（`B-26` 的「缺的补」）
                foreach (var want26 in new[] { "Background", "Video Image", "AllRewardsHolder" })
                    Check(b26Panel != null && b26Panel.Find(want26) != null,
                          $"★ B-26：`EndBattlePanel/{want26}` 在（原版三颗子件之一）"
                        + "｜🧨 少一颗 ⇒ 红（`Background` 原来叫 `dim`、`Video Image` 原来叫 `video_player`）");
                // …以及**多出来的那一颗**（如实列名，⛔ 不许静默多出第二个）
                if (b26Panel != null)
                {
                    var extras26 = new System.Collections.Generic.List<string>();
                    for (int i = 0; i < b26Panel.childCount; i++)
                    {
                        var nm = b26Panel.GetChild(i).name;
                        if (nm == "Background" || nm == "Video Image" || nm == "AllRewardsHolder") continue;
                        extras26.Add(nm);
                    }
                    Check(extras26.Count == 1 && extras26[0] == "content",
                          "★ B-26：`EndBattlePanel` 下**只多一颗我们自建的 `content`**"
                        + $"（原版那三颗之外的：{(extras26.Count == 0 ? "<无>" : string.Join(",", extras26.ToArray()))}）"
                        + "｜🧨 又长出别的节点 ⇒ 先判它是不是原版有的，再改本条（别把断言改宽）");
                }

                // ---- 🔴 2026-10-24（`A28`）：`BattleDoors` 自己的 `anchoredPosition` ----
                //   判据 = 原版 `bundle_scenes_scenes_battlearena1/RectTransform/RectTransform_2717.json`
                //   （m_GameObject = GO 60 = «BattleDoors»，与 `m_SizeDelta (1920.1199, 1118.981)` 同一份）：
                //   `m_AnchoredPosition = (−0.0640869140625, −5.276123046875)` · `m_AnchorMin/Max = m_Pivot = (0.5,0.5)`。
                //   🧨 只写 `sizeDelta` 不写位置（= 我们改之前的 (0,0)）⇒ 整块面板 / 视频 / 骷髅比原版**高 5.28 px**。
                var a28DoorsRt = b26Doors as RectTransform;
                var a28DoorsAp = a28DoorsRt != null ? a28DoorsRt.anchoredPosition
                                                    : new Vector2(float.NaN, float.NaN);
                Check(a28DoorsRt != null
                      && Mathf.Abs(a28DoorsAp.x - (-0.0640869f)) < 0.01f
                      && Mathf.Abs(a28DoorsAp.y - (-5.276123f)) < 0.01f,
                      "★ A28：`BattleDoors` 的 `anchoredPosition` = 原版 **(−0.0640869, −5.276123)**"
                    + $"（`RT_2717`；实测 ({a28DoorsAp.x:F4}, {a28DoorsAp.y:F4})）"
                    + "｜🧨 漏抄（0,0）⇒ 红");

                // ---- 🔴 2026-10-24（`A28`）：骷髅行的【布局后】绝对位置 ----
                //   判据 = **解包字段 + 本工程 uGUI 布局组源码**（⛔ 不是本件常量）：
                //    · `AllRewardsHolder`（`RT_2854`）：`ap (0, −260)` · `sd 100×100` · 中心锚
                //      （场景与运行时 dump `:1152` 两处同值）；
                //    · 它身上挂 **`VerticalLayoutGroup`**（`MB_4902`：spacing 30 · childAlignment 7 (LowerCenter) ·
                //      padding 0 · ChildControl / ForceExpand 全 0 · Enabled 1）；子件高 52.38 + 49
                //      ⇒ 内容 131.38 > 容器 100 ⇒ **溢出** ⇒ `pos` 停在 `padding.top = 0`
                //      （`HorizontalOrVerticalLayoutGroup.cs:182-192`）⇒ 第一颗子件（`SkullsHolder`）
                //      **顶边贴容器顶边** · `ap.y = −52.38/2 = −26.19`（`LayoutGroup.cs:249-267`）；
                //      横向按 `7 % 3 = 1`（居中）⇒ x = 0。
                //    · ⇒ **行心 = 面板中心 (0, −260 + 50 − 26.19) = (0, −236.19)**。
                //   ⚠️ **状态 → 值**（铁律 5·c）：上面的推导按「`RewardsHolder` **激活**」算（= 正常对局有奖励）。
                //      那一行被 `EndBattleDoors__ShowRewards` 按「有没有奖励」`SetActive`，而布局组**只排 active 子件**
                //      ⇒ **无奖励**时内容只剩 52.38 ⇒ LowerCenter 下推 ⇒ 行心 **−283.81**。
                //      我们取**画满那一档 −236.19**（奖励行只是按用户口径没做、位置仍按原版占着）。
                //   🧨 用旧值 −250 / 用静态全树表算出的 −309.5 / 直接拿容器中心 −260 / 无奖励档 −283.81 ⇒ 都红。
                var a28Row = a218End != null && a218End.SkullRow != null
                           ? a218End.SkullRow as RectTransform : null;
                float a28RowX = float.NaN, a28RowY = float.NaN;
                if (a28Row != null && b26Panel != null)
                {
                    var a28RowLocal = b26Panel.InverseTransformPoint(a28Row.position);
                    a28RowX = a28RowLocal.x;
                    a28RowY = a28RowLocal.y;
                }
                Check(a28Row != null && Mathf.Abs(a28RowX - 0f) < 0.05f
                      && Mathf.Abs(a28RowY - (-236.19f)) < 0.05f,
                      "★ A28：骷髅行 `SkullsHolder` 的行心 = **面板中心 (0, −236.19) px**"
                    + "（= 布局组重算后的结果：容器 ap −260 + 半高 50 − 52.38/2；"
                    + $"实测 ({a28RowX:F2}, {a28RowY:F2})）"
                    + "｜🧨 旧值 −250 / 静态表的 −309.5 / 容器中心 −260 ⇒ 都红");

                // ---- 🔴 2026-10-24（`A32`）：`RewardsHolder` 的布局后真值（同族第二条账） ----
                //   我们**不建**奖励行（用户 2026-09-17 口径），但真值已经落成 `EndPanel` 的两个常量
                //   （`RewardRowAnchorY` / `RewardRowPanelY`）—— 这一格把它们**按 uGUI 算法从原版字段现算**一遍再对。
                //   判据（解包现读，⛔ 不是本件常量、⛔ 不是序列化 `(0,0)` / 全树表 −309.5，那两个是**布局前**的）：
                //    · `AllRewardsHolder`（`RT_2854`）：`sd 100×100` · `ap (0, −260)` · 中心锚/枢轴；
                //    · 子件高：`SkullsHolder` 52.38（`RT_2616`）· `RewardsHolder` 49（`RT_3458`）· spacing 30（`MB_4902`）；
                //    · 内容高 131.38 > 100 ⇒ **溢出** ⇒ `pos` 停在 `padding.top = 0`
                //      （`HorizontalOrVerticalLayoutGroup.cs:182-192`）⇒ 第二颗 `ap.y = −(52.38+30) − 49×0.5`；
                //    · 锚点在容器**顶边**（`LayoutGroup.cs:261` 写 `anchorMin/Max = Vector2.up`）⇒ 面板坐标 = −260 + 50 + ap.y。
                //   🧨 把常量改回序列化那一档（0/0）、或改成全树表的 −309.5、或把 spacing 抄成 0 ⇒ 红。
                {
                    const float a32ContH = 100f;      // `RT_2854` m_SizeDelta.y
                    const float a32ContApY = -260f;   // `RT_2854` m_AnchoredPosition.y
                    const float a32SkullH = 52.38f;   // `RT_2616` m_SizeDelta.y
                    const float a32RewardH = 49f;     // `RT_3458` m_SizeDelta.y
                    const float a32Spacing = 30f;     // `MB_4902` m_Spacing
                    float a32Content = a32SkullH + a32Spacing + a32RewardH;                 // 131.38
                    float a32RowApY = -a32SkullH * 0.5f;                                    // −26.19（溢出 ⇒ pos = 0）
                    float a32RowLocalY = a32ContH * 0.5f + a32RowApY;                       // +23.81
                    float a32RewardApY = -(a32SkullH + a32Spacing) - a32RewardH * 0.5f;      // −106.88
                    float a32RewardLocalY = a32ContH * 0.5f + a32RewardApY;                 // −56.88
                    float a32RewardPanelY = a32ContApY + a32RewardLocalY;                   // −316.88
                    Check(a32Content > a32ContH,
                          $"★ A32（前提）：原版这两行**溢出**容器（{a32Content:F2} > {a32ContH:F0}）"
                        + " —— 只有这一档起点才停在 `padding.top`（不溢出的档见 `EndPanel` 的「状态 → 值」表）");
                    Check(Mathf.Abs(a32RowLocalY - EndPanel.SkullRowLocalY) < 0.01f
                          && Mathf.Abs(a32ContApY + a32RowLocalY - EndPanel.SkullRowPanelY) < 0.01f,
                          "★ A32：`SkullsHolder` 的布局后行心与 `EndPanel.SkullRowLocalY` 一致"
                        + $"（按 uGUI 公式算 +{a32RowLocalY:F2} / 面板 {a32ContApY + a32RowLocalY:F2}；"
                        + $"常量 +{EndPanel.SkullRowLocalY:F2} / {EndPanel.SkullRowPanelY:F2}）");
                    Check(Mathf.Abs(a32RewardApY - EndPanel.RewardRowAnchorY) < 0.01f
                          && Mathf.Abs(a32RewardPanelY - EndPanel.RewardRowPanelY) < 0.01f,
                          "★ A32：`RewardsHolder` 的布局后位置 = **ap.y −106.88 / 面板中心 −316.88**"
                        + $"（按 uGUI 公式算 {a32RewardApY:F2} / {a32RewardPanelY:F2}；"
                        + $"常量 {EndPanel.RewardRowAnchorY:F2} / {EndPanel.RewardRowPanelY:F2}）"
                        + "｜🧨 改成序列化的 (0,0) / 全树表的 −309.5 / spacing 抄成 0 ⇒ 红");
                    // 我们**真建了**的那一行读真几何 —— ⛔ 不拿被测常量当证据（上面那条才是常量对账）
                    Check(a28Row != null && Mathf.Abs(a28Row.anchoredPosition.y - a32RowLocalY) < 0.01f,
                          "★ A32：骷髅行的 `anchoredPosition.y` = 推导值 "
                        + $"+{a32RowLocalY:F2}（实测 {(a28Row != null ? a28Row.anchoredPosition.y : float.NaN):F2}）");
                }
            }
            // ③ 等待提示（原版 `WaitText` 与它下面那两级，矩形**各不相同**）
            var a218Wait = WaitBanner.CreateWithArt(a218root.transform, CardArt.DeckUi("40k_popup"),
                                                    CardArt.Ui("40k_popup_texture"));
            box(a218Wait.transform, "等待提示根（原版 `WaitText`）", 1344f, 79.44f,
                "原版 `WaitText` 的 `m_SizeDelta (1344.0, 79.44)`");
            box(a218Wait.transform.Find("wait_popup/wait_fillRoot"), "等待提示填充层根", 1323f, 90f,
                "原版 `Mask`（stretch ⇒ 矩形 = 父件 `Generic Popup Background` 的 1323×90）");
            // ④ 滑块根：战斗那三根原版实读 **561.08 × 12.00**（见 `WfSlider` 文件头那段）
            // ⚠️ **2026-10-21（`A1365`）一条用法的告诫**：这颗探针按 `value: 0.5f` 建 ⇒ `A1359` 之后
            //   它的填条**真的只画半宽**（两端端帽仍 15px —— 填条已改成原版的「改锚点」）。
            //   🔴 它下面那条 `box(...)` 只量滑块**根**的 rect（561.08 × 12），**不会因此红** ——
            //   ⛔ 但**别拿它当「填条没变」的证据** —— 本文件这一侧**下面那一段**已经补上填条的几何断言
            //   （`FillWorldW` / `FillCapWorldW` / 对填条子树取并集；设置窗那三根见 `Editor/SettingsScene.cs`）。
            var a218Slider = WfSlider.Create(a218root.transform, "A218Probe", Vector3.zero, 0.5f, null,
                            queue: 3000, handlePx: 34.406f, handleOffset: WfSlider.HandleOffsetPx, capScale: 1f);
            box(a218root.transform.Find("slider_A218Probe"), "音量滑块根", 561.08f, 12f,
                "原版战斗那三根 `Slider`：`Container sizeDelta (0,100)` + 锚 y `0.33→0.45` ⇒ 高 12 · 宽 561.08");

            // ---- 🆕 2026-10-21（`A1359` / `A1351`② 的**断言**那一半）：**填条那三块的几何** ----
            //  判据 = `资料/普查产出_第十三会话/W6c_A1350A1351A1359.md` §三「该补什么断言」。
            //  🔴 期望值一律写**字面量**、⛔ **不引用 `WfSlider.*` 的任何常量**（那是被测实参 ⇒ 自证）。
            //  战斗档：`trackW 561.08` · `trackH 12` · `capScale 1` ⇒ 端帽 = 原版 `m_Border 30 ÷ ppuMul 2` × 1 = **15**。
            //  ⚠️ 设置窗那三根**不是同一个数**（615.771 / 13.5）⇒ 那边另有三条（`Editor/SettingsScene.cs` 的 `A1359` 一节）。
            if (a218Slider == null)
                Check(false, "（前提）滑块探针 `A218Probe` 建出来了（下面几条填条几何要靠它）");
            else
            {
                // (a) 共用件报的是**建件矩形**、⛔ 不乘回子件缩放（`MenuDraw.QuadRectPx` 的规范句②）：
                //     填条三块里**中段那一块**建件时是**满宽**（九宫格的角块固定像素、中段拉伸 ⇒
                //     它的建件宽 = 561.08 − 15 − 15）⇒ 对整棵子树取并集 = **531.08**，
                //     与「屏幕上那一块」（= 值 × 561.08）**不是一回事**。
                // 🔴 这一格与下面 (b) 是**成对**的：谁哪天把 `MenuDraw` 改成「自动乘回子件缩放」，
                //    它们就会**相等** ⇒ 红 —— 而那正是会打翻既有 40+ 个调用点的改动。
                var fillN = a218root.transform.Find("slider_A218Probe/slider_fill");
                float ux1 = 0f, uy1 = 0f, ux2 = 0f, uy2 = 0f;
                bool hasUnion = fillN != null && MenuDraw.UnionQuadRectPx(
                    fillN, MenuDraw.QuadGate.InHierarchy, true, out ux1, out uy1, out ux2, out uy2);
                Check(hasUnion, "（前提）填条那棵子树（`slider_fill` 下的三块）量得到 quad");
                float[] sVals = { 1f, 0.5f, 0.2f };
                string[] sTags = { "值 1", "值 0.5", "值 0.2" };
                float sCapFirst = -1f;
                for (int k = 0; k < sVals.Length; k++)
                {
                    float v = sVals[k];
                    a218Slider.SetValue(v, false);      // ⚠️ `fire: false` —— 自检**只摆值**（不碰总线 / 存档）
                    float fw  = a218Slider.FillWorldW * 108f;
                    float flx = a218Slider.FillWorldLeftX * 108f;
                    float fcap = a218Slider.FillCapWorldW * 108f;
                    Check(Mathf.Abs(flx + 280.54f) <= 0.05f,
                          $"★ {sTags[k]}：填条**左沿** = 轨道宽 ÷ 2 ⇒ **−280.54**（实得 {flx:F3}）"
                        + " —— 原版 `Slider` 把 `Fill` 锚在**左边**的锚点上（`anchorMin.x = 0`），值怎么变它都不动");
                    Check(Mathf.Abs(fw - v * 561.08f) <= 0.05f,
                          $"★ {sTags[k]}：填条**画出来的宽** = 值 × 原版轨道宽 561.08 = **{v * 561.08f:F3}**（实得 {fw:F3}）");
                    Check(Mathf.Abs(fcap - 15f) <= 0.05f,
                          $"★ {sTags[k]}：端帽**恒宽** 15 画布 px（原版 `m_Border 30 ÷ ppuMul 2 × capScale 1`；实得 {fcap:F3}）");
                    if (k == 0) sCapFirst = fcap;
                    else
                        // 🧨 **灭自证那一半**：「整体横向缩放」那条旧实现**结构上做不到**这一条
                        //    （值 0.5 时端帽必掉到 7.5）—— 要让一个**随值变化**的量变成常量，只能真改实现；
                        //    而「把被测实现与它的读口一起改回去」也救不了：这条断的是**跨两个值相等**。
                        Check(Mathf.Abs(fcap - sCapFirst) <= 0.02f,
                              $"★★ {sTags[k]} 的端帽宽与「值 1」**逐值相等**（{fcap:F3} vs {sCapFirst:F3}）"
                            + " —— 旧的整体缩放路在值 0.5 时给的是 7.5 ⇒ 红");
                }
                // (b) 「屏幕上那一块」（本件读口）—— 与 (a) 的期望值**必须不相等**：
                //     两者量的是**两份不同的实现**（共用件的并集 vs 本件的读口），喂进去的期望都是字面量。
                a218Slider.SetValue(0.5f, false);           // ⚠️ 并集要在**这个值**上现量（上面那次是取前置）
                hasUnion = fillN != null && MenuDraw.UnionQuadRectPx(
                    fillN, MenuDraw.QuadGate.InHierarchy, true, out ux1, out uy1, out ux2, out uy2);
                if (hasUnion)
                {
                    float uniW = ux2 - ux1;
                    float fillW05 = a218Slider.FillWorldW * 108f;
                    Check(Mathf.Abs(uniW - 531.08f) <= 1f,
                          $"★ 对填条子树取**并集** = **531.08**（= 轨道 561.08 − 两端端帽 30：中段那块**建件时满宽**）"
                        + $" —— 实得 {uniW:F3}；共用件报的是**建件矩形**、⛔ 不乘回子件缩放（`QuadRectPx` 规范句②）");
                    Check(Mathf.Abs((uniW - fillW05) - 250.54f) <= 1.2f,
                          $"★★（灭自证那一半）并集 {uniW:F3} 与「屏幕上那一块」{fillW05:F3} **必须差 250.54**"
                        + $"（实得 {uniW - fillW05:F3}）—— 两者一旦相等，就是有人把 `MenuDraw` 改成「自动乘回子件缩放」了");
                }
                a218Slider.SetValue(0.5f, false);       // （还原）探针建件时那个值
            }

            // ------------------------------------------------------------------
            //  🔴 **反向那一半**：原版**本来就是裸 `Transform`** 的几处**不许被顺手补齐**
            //     （弱断言分不出两态 ⇒ 必须成对断：上面那批**有** `RectTransform`、这几处**没有**）
            // ------------------------------------------------------------------
            if (driver != null && driver.hudRoot != null)
            {
                Check(driver.hudRoot.GetComponent<RectTransform>() == null,
                      "🔴 `HudRoot` **没有** `RectTransform`（判据 = 原版 `BattleHud` 本尊就是裸 `Transform`"
                      + " —— `bundle_scenes_scenes_battlearena1` 实读 go_pid 239；它的**孙辈**才是 uGUI 的 `Canvas`）");
                // 🔴 **2026-10-16（`T09` 批 3）**：这一件已挂到 `AboveShader` 子画布下 ⇒ ⛔ `hudRoot.Find` 找不到了；
                //   而且它是 **stretch** ⇒ 矩形 = **画布矩形**（`Expand` 档下可能比 1920×1080 大，见 §五·补⑩ §七·8）。
                var aboveCvT = HudCanvas.SubCanvas("AboveShader Canvas");
                box(aboveCvT != null ? aboveCvT.transform.Find("OvertimeSplashText") : null, "加时 splash 根",
                    a218CvW, a218CvH,
                    "原版 `OvertimeSplashText`（stretch + `sizeDelta (0,0)` ⇒ **铺满父画布**）");
            }
            else Check(false, "（前提）拿得到 `driver.hudRoot`（`HudRoot` / 加时 splash 那两条要靠它）");

            // 这几处**原版就是裸 `Transform`**（判据逐条写在 `Battle/*.cs` 的注释里），但它们的创建是**惰性**的
            // ⇒ 拿不到就**出声跳过**（不是静默门）：`Particle colliders` 只在第一次粒子碰撞时要、`Slots` 只在棋盘铺标记时建。
            var a218Pc = driver != null ? driver.transform.Find("Particle colliders") : null;
            if (a218Pc != null)
                Check(a218Pc.GetComponent<RectTransform>() == null && a218Pc.childCount > 0
                      && a218Pc.GetChild(0).GetComponent<RectTransform>() == null,
                      "🔴 粒子碰撞平面 `Particle colliders` 及它的 `Generic Target` 子件**都没有** `RectTransform`"
                      + "（判据 = 原版 go_pid 575 / 138 实读就是裸 `Transform`）");
            else Debug.Log(P + "   （A218：`Particle colliders` 这一轮**没建出来**（惰性）⇒ 那两条不判；"
                             + "判据在 `Battle/BattleDriver.cs` 的注释里）");
            var a218Slots = driver != null && driver.playerBoard != null
                          ? driver.playerBoard.transform.Find("Slots") : null;
            if (a218Slots != null)
                Check(a218Slots.GetComponent<RectTransform>() == null,
                      "🔴 落点标记根 `Slots` **没有** `RectTransform`（判据 = 原版 `Board Center` / `MinionArea` /"
                      + " `HandArea` 那一族实读全是裸 `Transform`）");
            else Debug.Log(P + "   （A218：`Slots` 这一轮**没建出来**（惰性）⇒ 那一条不判；判据在 `Board/BoardLayout.cs` 的注释里）");
            var a218Line = driver != null && driver.reticle != null
                         ? driver.reticle.transform.Find("CrosshairLine") : null;
            if (a218Line != null)
                Check(a218Line.GetComponent<RectTransform>() == null,
                      "🔴 准星弧线 `CrosshairLine` **没有** `RectTransform`（判据 = 原版 `CrosshairLine 3D`"
                      + " go_pid 848 实读裸 `Transform`，同一批 7 个 `LineRenderer` 宿主全是）");
            else Debug.Log(P + "   （A218：`CrosshairLine` 这一轮**没建出来** ⇒ 那一条不判；判据在 `Battle/TargetReticle.cs` 的注释里）");

            Object.DestroyImmediate(a218root);      // 批处理下 `Destroy` 不生效
        }

        // ==================================================================
        //  🆕 2026-09-26（N4）：**联机客机的视图方向**（`_me = 1`）
        //
        //  为什么单开一段：联机对局两端跑的是**同一套绝对座位**（主机 0 / 客机 1），
        //  客机那边靠 `SetMySeat(1)` 把视图翻过来 —— 而这一路**批处理里只能这样验**
        //  （同一工程不能同时跑两个 Unity 实例，两台机器真连一次是「真 Play」的事）。
        //  验的是：**自己那侧的东西必须画在屏幕下半**（手牌 / 上场单位），对面那侧在上半。
        // ==================================================================
        // ⚠️ **A195 核过：这个门是安全的**（没改）—— 它查的是 `Run` 里那两个**局部**（不是 `FindObjectOfType` 重查）：
        //    `driver` 由 `BuildScene` 直接给出、紧接着就被解引用（`driver.selector` / `driver.Begin`）；
        //    `ctx` 取自 `driver.Ctx`，之后每次重取（§20/§21 那几处）**紧接着**就是 `ctx.Players[0]…`
        //    ⇒ 任一为 null 的话**前面早就 NRE 了**（大声，不是静默），根本走不到这一行。
        if (driver != null && ctx != null)
        {
            // 🔴 **联机局：对面那一侧不许跑 AI**（否则 AI 和网络会给对面同时出招 ⇒ 立刻打岔）。
            //    挂上联机层再问那个判据 —— 单机那一路必须原样不变。
            Debug.Log(P + "--- 联机：对面那一侧该由网络驱动，不许跑 AI ---");
            Check(driver.AiShouldDriveOpponent, "单机：**AI 照旧驱动对面**（联机没把单机改坏）");
            var nbProbe = CardPresentation.Net.NetBattle.Attach((CardPresentation.Net.INetBattleHost)driver,
                                                                null, isHost: true);
            driver.AttachNet(nbProbe);
            Check(!driver.AiShouldDriveOpponent,
                  "★ 挂上联机层之后：**AI 不再驱动对面那一侧**（对面由 `NetTick()` 落地网络动作）");
            driver.AttachNet(null);
            Check(driver.AiShouldDriveOpponent, "拆掉联机层 ⇒ 又回到单机那一路（幂等，不留后遗症）");

            Debug.Log(P + "--- 联机客机视图（`_me = 1`）：自己那侧该在屏幕下半 ---");
            // 🆕 2026-10-21（`T04`）：这是**局已开始之后**翻座位（前面几节已经在场上摆过东西了）
            //   ⇒ 传 `rebuildViews: true`，让视图侧按新座位整套重建（`BattleDriver.SetMySeat` 的 doc）。
            driver.SetMySeat(1, rebuildViews: true);
            Check(driver.MyIndex == 1, "`SetMySeat(1)` ⇒ `MyIndex = 1`（引擎那边一切照旧，只是视图翻过来）");
            // 引擎侧不变：`Ctx.Players[1]` 就是「我」那一方
            Check(driver.Ctx == ctx, "换座位**不动引擎**（同一个 `Ctx`，只是「哪一侧画在下面」变了）");
            driver.RefreshAll();
            var myHand1 = driver.HandViewAt(0);
            var foeHand1 = driver.FoeHandViewAt(0);
            if (myHand1 != null && foeHand1 != null)
            {
                Check(myHand1.transform.position.y < 0f,
                      $"客机视角：**我的手牌在下半屏**（y={myHand1.transform.position.y:F2} < 0）");
                Check(foeHand1.transform.position.y > 0f,
                      $"客机视角：**对面手牌在上半屏**（y={foeHand1.transform.position.y:F2} > 0）");
            }
            else Check(false, "客机视角：两边的手牌视图都在（拿到 `HandViewAt(0)` / `FoeHandViewAt(0)`）");

            // 场上单位同理：两边各摆一个，看谁在下半屏。
            // ⚠️ **单位的位置是「竞技场世界坐标」**（3D 落点，`ArenaSlots.RootPosition`），
            //    **不是 UI 的屏幕坐标** ⇒ 不能假设「y < 0 就是下面」。改成 **A/B 比**：
            //    先记下座位 0 那副占的是哪一行，再把座位翻成 1，看两副牌是不是**换了行**。
            int mineSlot = -1, foeSlot = -1;
            var card1 = FirstUnit(driver.Ctx, 1);
            var card0 = FirstUnit(driver.Ctx, 0);
            if (driver.Ctx.IsOver || card1 == null || card0 == null)
            {
                // 如实说「这一段没验」，不装作验过（本项目红线：不许静默）
                Debug.LogWarning(P + "  ⚠️ **场上单位那一层没验**（这一局已经打完 / 手牌里没有单位卡）—— "
                                 + "「客机视角下 `MyUnits` 认的是不是座位 1 那一方」留给"
                                 + "**两台机器真连一次**那次（`资料/真Play待验清单.md`）");
            }
            else if (RuleCore.DeployFree(driver.Ctx, 1, card1, out mineSlot)
                  && RuleCore.DeployFree(driver.Ctx, 0, card0, out foeSlot))
            {
                // 🔴 **量「映射」而不是量「坐标」**：单位落在哪一行是竞技场 3D 的事
                //    （`ArenaSlots.RootPosition` 是**竞技场世界坐标**，不是屏幕坐标，别拿 y 的正负判上下）。
                //    这里要钉的是：**`MyUnits` 认的必须是 `_me` 那一方的棋子、`FoeUnits` 认另一方**。
                //
                // 🆕 2026-10-20（W58 · P1-B/13）：`DeployFree` → `RefreshAll` 时 `Deploy` 事件排在**队尾**
                //   ⇒ `SyncBoard` 被 `IsPendingDeploy` 压着**不建视图**（`BattleDriver.cs:17652`）⇒ 翻座位后
                //   两边都读到 null（日志 `70192/70218`）。**先把旧队排空**，让两条 `Deploy` 在这一步演到。
                //   ⚠️ 若排空后仍为 null：下面那条红会把 `DeployPendingForTest` 和两边字典的实际内容一起打出来。
                // 🔴 **2026-10-21（`T04`）就地订正（铁律 5）**：这一行原来写「`SetMySeat` 中途翻座位
                //   **生产侧未支持**，本夹具只负责把原因打出来」—— **已不成立**：`SetMySeat` 现在有
                //   `rebuildViews: true`（真翻座位时按新座位把视图侧整套重建）⇒ 「翻座位之后建不出件」
                //   不再是已知缺口，而是本节**断言 A / B** 钉住的行为。
                // ⚠️ **2026-10-21（`T04` 审查）再订正**：上面「`DrainQueue` 让两条 `Deploy` 在这一步演到」
                //   **位置不对** —— `DeployFree` 只是把事件写进 `Ctx.Signals`（`RuleCore.DeployFree` 里那句
                //   `ctx.Emit(EvtKind.Deploy, …)`）；它们是在 **`RefreshAll → PlaySignals`** 里才记账、排期的。
                // 🔴 **2026-10-21（`T04` 实跑订正，铁律 5）**：这两条 `Deploy` 排在同一批里，但**只有排在
                //   前面那条是「当刻到期」的** —— 实跑（`BattleScene.Run` 4071/2）读到
                //   `seat1/5=False · seat0/1=True`：第二条还在队尾、`IsPendingDeploy`（`BattleDriver.cs:17652`）
                //   把 `FoeUnits[1]` 继续压住（**这条断言当场就是红在这**，不是「两边都没建」）。
                //   ⇒ 修法 = **排两次队**：先排空**更早几节遗留**的队尾（否则下面新摆的卡会被旧事件打掉，
                //   同 `:6858` 那条教训），`RefreshAll` 之后再排一次，让这两条 `Deploy` **真的演到**
                //   （演到 = `CompletePendingDeploy` 销账 + `_syncAfterDeploy` 那次 `SyncBoard` 建件）。
                DrainQueue(driver);                        // ① 先清「更早几节遗留」的队尾
                driver.SetMySeat(1); driver.RefreshAll();  // ② 记账 + 排期（两条 Deploy 进时间线，尚未演到）
                DrainQueue(driver);                        // ③ 再排一次：让两条 Deploy 演到（销账 + 建件）
                var vm = Lookup(driver.MyUnits, mineSlot);
                var vf = Lookup(driver.FoeUnits, foeSlot);
                CardView vm0 = null, vf0 = null;
                if (vm != null && vf != null)
                {
                    Check(vm.Data.id == card1.Name,
                          $"★ 客机视角（`_me = 1`）：`MyUnits` 里那个**是座位 1 的「{card1.Name}」**（本机的棋子）");
                    Check(vf.Data.id == card0.Name,
                          $"★ 客机视角（`_me = 1`）：`FoeUnits` 里那个**是座位 0 的「{card0.Name}」**（对面的棋子）");
                }
                else Check(false,
                    $"客机视角：两边的场上视图都建出来了（`_me=1`：MyUnits[{mineSlot}]="
                  + $"{(vm == null ? "null" : vm.Data.id)} / FoeUnits[{foeSlot}]={(vf == null ? "null" : vf.Data.id)}；"
                  + $"DeployPending：seat1/{mineSlot}={driver.DeployPendingForTest(1, mineSlot)} · "
                  + $"seat0/{foeSlot}={driver.DeployPendingForTest(0, foeSlot)}；期望 {card1.Name} / {card0.Name}）");

                // 反向对照：座位 0 视角下**两个字典要认另一边**
                // 🆕 2026-10-21（`T04`）：这是**局已开始之后**翻座位（`_me` 1 → 0）——
                //   必须 `rebuildViews: true`：否则身份表（`UnitViewMap` 按 `owner == _me` 挑表，
                //   `BattleDriver.cs:994`）与登场账（键 = 绝对座位 `HpKey`，`:14281`）都停在旧座位
                //   那一边 ⇒ `SyncBoard` 被 `IsPendingDeploy` 闸住（`:17652`）、两边的坑位都建不出件。
                Check(card0.Name != card1.Name,
                      "夹具前提：两边摆的是**不同名**单位（否则下面两条不辨方向）");
                // 前提：`_me = 1` 时视图侧的「我方阵营」必须是**座位 1** 的（`FactionOf` 那条）。
                Check(driver.MyFactionForTest == card1.Faction,
                      $"（前提）`_me = 1` 时视图侧「我方阵营」= 座位 1 的阵营"
                    + $"（实得 `{driver.MyFactionForTest}`，应为 `{card1.Faction}`）");
                int seatRebuildsBefore = driver.SeatRebuildCountForTest;
                driver.SetMySeat(0, rebuildViews: true); driver.RefreshAll();
                vm0 = Lookup(driver.MyUnits, foeSlot);
                vf0 = Lookup(driver.FoeUnits, mineSlot);
                if (vm0 != null && vf0 != null)
                {
                    Check(vm0.Data.id == card0.Name,
                          $"★ 主机视角（`_me = 0`）：`MyUnits` 里那个是座位 0 的「{card0.Name}」（同一批棋子，认的方反过来了）");
                    Check(vf0.Data.id == card1.Name,
                          $"★ 主机视角（`_me = 0`）：`FoeUnits` 里那个是座位 1 的「{card1.Name}」");
                }
                else Check(false,
                    $"主机视角：两边的场上视图都建出来了（`_me=0`：MyUnits[{foeSlot}]="
                  + $"{(vm0 == null ? "null" : vm0.Data.id)} / FoeUnits[{mineSlot}]={(vf0 == null ? "null" : vf0.Data.id)}；"
                  + $"DeployPending：seat0/{foeSlot}={driver.DeployPendingForTest(0, foeSlot)} · "
                  + $"seat1/{mineSlot}={driver.DeployPendingForTest(1, mineSlot)}；期望 {card0.Name} / {card1.Name}）");

                // 🆕 2026-10-21（`T04`）**断言 A / B**：翻座位（1 → 0）之后视图侧要**整套按新座位重建**。
                //   直接读当前两张表，不复用上面那两个变量（它们可能落在失败分支里、本来就是 null）。
                var aMine = Lookup(driver.MyUnits, foeSlot);     // `_me = 0` ⇒ 座位 0 的兵在「我方」表里
                var aFoe = Lookup(driver.FoeUnits, mineSlot);    // 座位 1 的兵在「敌方」表里
                // 🔴 **灭自证（2026-10-21 审查后加强）**：只断「两个不同 id」**不够** —— **不重建**时
                //   `SyncBoard` 还会走「认领旧视图」那条退路（`BattleDriver.cs:17671-17679`），把**另一侧**
                //   槽位上的旧视图认过来、再 `SetData` 改掉 id ⇒ id 断言照样全过。⇒ 三条一起断：
                //   ① 重建计数**真的** +1（`SeatRebuildCountForTest`，生产口径、只增）；
                //   ② 那两件**不是翻之前的那两件**（`vm`/`vf` 是旧对象；批处理里 `Kill` = `DestroyImmediate`
                //      ⇒ 它们已变「假 null」，而 `ReferenceEquals` 仍认得出「同一个对象被认领过来」）；
                //   ③ 两件不是同一对象、id 各自等于**绝对座位**那一方的卡。
                Check(driver.SeatRebuildCountForTest == seatRebuildsBefore + 1,
                      "★ 这次翻座位走的是**重建**那条路（`SeatRebuildCountForTest` "
                    + $"{seatRebuildsBefore} → {driver.SeatRebuildCountForTest}，应 +1）");
                // 🔴 第二条判别式：**翻之前那两件必须已经被销毁**（批处理里 `Kill` = `DestroyImmediate`
                //   ⇒ Unity 的 `== null` 对已销毁对象为真）。不重建的话它们还活着 ⇒ 本条红。
                Check(vm == null && vf == null,
                      "★ 翻座位重建时**旧的那两件视图被销毁了**（`vm`/`vf` 应成 Unity 假 null；"
                    + $"实得 vm={(vm == null ? "null" : "还在")} / vf={(vf == null ? "null" : "还在")}）"
                    + " —— 🧨 不重建 ⇒ 旧视图留着（两张表各多一条脏账）⇒ 本条红");
                Check(aMine != null && aFoe != null,
                      "★ `_me` 1→0 翻座位之后：**两边的场上视图都重建出来了**"
                    + $"（MyUnits[{foeSlot}]={(aMine == null ? "null" : aMine.Data.id)} / "
                    + $"FoeUnits[{mineSlot}]={(aFoe == null ? "null" : aFoe.Data.id)}）");
                Check(aMine != null && aFoe != null
                      && !ReferenceEquals(aMine, aFoe)
                      && !ReferenceEquals(aMine, vf) && !ReferenceEquals(aFoe, vm)
                      && aMine.Data.id != aFoe.Data.id
                      && aMine.Data.id == card0.Name && aFoe.Data.id == card1.Name,
                      "★ 翻座位之后那两件是**新建的、不同的对象、不同的卡**，且各自认的是**绝对座位**那一方"
                    + $"（我方「{(aMine == null ? "null" : aMine.Data.id)}」应为「{card0.Name}」/ "
                    + $"对面「{(aFoe == null ? "null" : aFoe.Data.id)}」应为「{card1.Name}」）"
                    + "｜🧨 没重建 / 只清一张表 / 把另一侧的旧视图认领过来（`SetData` 会改 id）⇒ 本条红");
                // 阵营那两格也是**视图侧**（`FactionOf(seat)`）—— 翻回 0 之后「我方阵营」必须是座位 0 的，
                // 否则重建出来的视图描边色 / 卡背停在旧座位（翻过去了、颜色没翻）。
                Check(driver.MyFactionForTest == card0.Faction,
                      "★ 翻回 `_me = 0` 之后视图侧「我方阵营」= 座位 0 的阵营"
                    + $"（实得 `{driver.MyFactionForTest}`，应为 `{card0.Faction}`）");

                // ---- 断言 B（2026-10-21 审查后**重做**）----
                //  原来那版断「翻座位之后那两笔登场账都作废」：③ 把两条 `Deploy` 都演到之后，走到翻转
                //  这一步时两本账**本来就是空的** ⇒ 那条断言恒绿（不辨真假）。⇒ 改成**自己造一笔
                //  「还没演到」的登场**：
                //  往 `Ctx.Signals` 塞一条 `Deploy`（那一格本来就站着人 ⇒ `NotePendingDeploy` 会记账，
                //  `InstanceId` 取那一份自己的号，判据 = `BattleDriver.NotePendingDeploy`：14944 起），`RefreshAll` 之后
                //  ① 先确认账上**真的**压着一笔（否则下面那条不辨真假 —— 如实说没验，不装作验过）；
                //  ② 再翻座位 ⇒ 那一笔必须被作废。
                var bUnit = ctx.Players[0].Board[foeSlot];
                if (bUnit != null)
                {
                    ctx.Signals.Add(new BattleEvent
                    {
                        Kind = EvtKind.Deploy, Player = 0, Slot = foeSlot,
                        CardId = card0.Name, InstanceId = bUnit.InstanceId,
                    });
                    driver.RefreshAll();                      // 记账 + 排期（还没演到 ⇒ 账上压着）
                    if (driver.DeployPendingForTest(0, foeSlot))
                    {
                        int bBefore = driver.SeatRebuildCountForTest;
                        driver.SetMySeat(1, rebuildViews: true);
                        Check(driver.SeatRebuildCountForTest == bBefore + 1,
                              "（B 的前提）这一次翻座位**真的重建**了（`SeatRebuildCountForTest` 应 +1）");
                        Check(!driver.DeployPendingForTest(0, foeSlot)
                              && driver.DeployPendingInstanceForTest(0, foeSlot) == 0,
                              "★ 翻座位重建之后，那笔**还没演到**的登场账被作废了"
                            + $"（`DeployPending`(0,{foeSlot}) = {driver.DeployPendingForTest(0, foeSlot)}，"
                            + $"实例号 {driver.DeployPendingInstanceForTest(0, foeSlot)}）"
                            + " —— 🧨 不清的话它会把重建后的视图继续闸住（`SyncBoard` 的 `continue`）");
                        driver.SetMySeat(0, rebuildViews: true);   // 还原（下面 19b 按 `_me = 0` 写）
                    }
                    else
                        Debug.LogWarning(P + "  ⚠️ **登场账作废那一条没验**：塞进去的 `Deploy` 在 `RefreshAll`"
                                         + " 里当场就演完了（账上已经是空的）—— 如实说没验，不装作验过");
                }
                else Check(false, $"（B 的前提）槽 {foeSlot} 上还站着座位 0 那个单位（拿不到就造不出「还没演到的登场」）");

                // ---- 19b. 客机视角：**其余 HUD 认的是不是 `_me` 那一方** ----
                //  判据：`BattleDriver.UpdateHud` 里 `me = Ctx.Players[_me]` / `foe = Ctx.Players[1 - _me]`
                //  ⇒ 翻座位之后，**能量 / 牌堆 / 名牌**三处的两侧内容要整体对调。
                //  ⚠️ 为了让「对调」看得出来，先把两边能量**改成不一样的**（改完还原 —— 后面几节还要用这个局面）。
                {
                    int e0 = ctx.Players[0].Energy, e1 = ctx.Players[1].Energy;
                    ctx.Players[0].Energy = 3; ctx.Players[1].Energy = 5;
                    //  🔴 **2026-10-22**：名牌那一行**只印名字**了（不再拼阵营/生命）⇒ 下面那两句
                    //    「让两边生命不一样」对名牌已经没有意义；**保留**是因为本节后面几条还在用这两个值。
                    //    （历史：它当年是 `阵营 + 生命/HP + 数值`，靠血量判翻座位。）
                    int h0 = ctx.Players[0].Warlord.Health, h1 = ctx.Players[1].Warlord.Health;
                    ctx.Players[0].Warlord.Health = 12; ctx.Players[1].Warlord.Health = 27;
                    string WantE(int seat) { return ctx.Players[seat].Energy + "/" + ctx.Players[seat].MaxEnergy; }
                    // 🔴 **2026-10-18（W6）改**：牌堆那格现在是**原版拼法** `<词条>: <张数>`
                    //    （`Battle/HUD/CardsLeft`；弃牌数已不在这一格上）。期望值走 `BattleDriver.CountText`
                    //    —— 那是**唯一一处**拼法实现（⛔ 别在这儿再抄一遍 `Loc.T(...) + ": " + n`）。
                    string WantP(int seat)
                    {
                        return BattleDriver.CountText(BattleDriver.DeckCountTerm, ctx.Players[seat].Deck.Count);
                    }
                    // 🆕 2026-10-21（`T04`）：本节所有翻座位调用都带 `rebuildViews: true`
                    //   （同值再调 = 幂等，只打日志；真翻的时候才拆表重建）。
                    driver.SetMySeat(0, rebuildViews: true); driver.RefreshAll();
                    Check(driver.MyEnergyText == WantE(0) && driver.FoeEnergyText == WantE(1),
                          $"（对照）主机视角：能量条两侧各认自己的（{driver.MyEnergyText} / {driver.FoeEnergyText}）");
                    driver.SetMySeat(1, rebuildViews: true); driver.RefreshAll();
                    Check(driver.MyEnergyText == WantE(1),
                          $"★ 客机视角：**我方能量 = 座位 1 的**（实得 {driver.MyEnergyText}，应为 {WantE(1)}）");
                    Check(driver.FoeEnergyText == WantE(0),
                          $"★ 客机视角：**对面能量 = 座位 0 的**（实得 {driver.FoeEnergyText}，应为 {WantE(0)}）");
                    Check(driver.MyPileText == WantP(1) && driver.FoePileText == WantP(0),
                          $"★ 客机视角：**牌堆/弃牌计数也跟着翻**（我 {driver.MyPileText} / 敌 {driver.FoePileText}）");
                    // 🔴 **2026-09-28 改**：这块名牌原来印「阵营 + 生命」，靠 12/27 两个血量判方向；
                    //    现在**照原版印名字**（那个节点就叫 `EnemyNameText`）⇒ 名字**不随座位变**
                    //    （我就是我、对手就是对手）⇒ 它**不再能判「翻座位」**（那是它原本的用途要说清的事）。
                    //    座位方向由上面**能量 / 牌堆**两条盯（判据本来就更硬、也更直接）。
                    // 🔴 **2026-10-22（用户口径「战斗里原版没有的设计不要」）**：原来这里断的是
                    //    「以玩家名开头」/「不含玩家名」—— 那时**阵营名被拼在名字后面**（我们自己加的），
                    //    现在**只印名字**（原版 `PlayerProfileUIController.SetProfileName` 原样 `SetText`）⇒
                    //    期望值改成**逐字相等**；单机局对面没有名字数据源 ⇒ 原版对空串的兜底
                    //    `GetTranslation("MenuLogin/Guest")` = `New player` / `新玩家`（⛔ 不再是阵营名）。
                    Check(driver.MyPlateText == ProfileData.PlayerName,
                          $"★ 名牌 = **只有玩家名**（原版那格是名字节点、不拼阵营；实得「{driver.MyPlateText}」）");
                    string foeWant = "New player";
                    Check(driver.FoePlateText != null
                          && !driver.FoePlateText.Contains(ProfileData.PlayerName)
                          && !driver.FoePlateText.Contains(CardText.Faction(driver.MyFaction)),
                          "★ 对面那块名牌**不印玩家名、也不拼阵营名**（单机局没有名字数据源 ⇒ "
                        + "走原版空串兜底 `MenuLogin/Guest`；实得「" + driver.FoePlateText + "」）");
                    Check(driver.FoePlateText == foeWant || driver.FoePlateText == "新玩家",
                          $"★ 单机对面那块 = 原版空串兜底 `MenuLogin/Guest`（两列官方值 = "
                        + $"「{foeWant}」/「新玩家」；实得「{driver.FoePlateText}」）");
                    // ⚠️ **必须把座位还原成 0** —— 原来这行夹在那两条断言中间，改断言时**差点丢掉**
                    //    （丢了后面那批「同一局面」的用例就全在客机视角下跑，会静默改变语义）。
                    driver.SetMySeat(0, rebuildViews: true); driver.RefreshAll();
                    ctx.Players[0].Energy = e0; ctx.Players[1].Energy = e1;
                    ctx.Players[0].Warlord.Health = h0; ctx.Players[1].Warlord.Health = h1;

                    // ---- 攻击选择器：**同一个槽号在两侧指向不同棋子** ----
                    //  判据：`BattleDriver.OpenCommand(slot)` 首行读的是 `Ctx.Players[_me].Board[slot]`。
                    //  最硬的证法是**拿一个「座位 0 有兵、座位 1 空着」的槽**：
                    //  座位 1 视角下点它**必须点不开**（那边是空的），座位 0 视角下点得开。
                    //  ⚠️ **刚部署的单位是 `Exhausted = true`**（`UnitState` 那条：部署当回合不能动）
                    //     ⇒ 对照那一半会「点不开」而**理由不是座位**，所以先把行动权还给它。
                    if (ctx.Players[0].Board[foeSlot] != null) ctx.Players[0].Board[foeSlot].Exhausted = false;
                    bool foeSlotEmptyForSeat1 = ctx.Players[1].Board[foeSlot] == null;
                    if (foeSlotEmptyForSeat1)
                    {
                        driver.SetMySeat(1, rebuildViews: true); driver.RefreshAll();
                        Check(!driver.SimulateOpenCommand(foeSlot),
                              $"★ 客机视角：点槽 {foeSlot}（**座位 1 那边是空的**）⇒ **弹不出选择器**"
                              + "（`OpenCommand` 读的是 `Players[_me]` ⇒ 对面那个兵不算我的）");
                        driver.SetMySeat(0, rebuildViews: true); driver.RefreshAll();
                        Check(driver.SimulateOpenCommand(foeSlot),
                              $"（对照）主机视角：同一个槽 {foeSlot} 是**我自己的兵**（且已解行动） ⇒ 弹得出选择器");
                        if (driver.SelectorOpen) driver.SimulateCommand(AttackKind.Melee);   // 收起，别留给下一节
                    }
                    else
                        Debug.LogWarning(P + "  ⚠️ **选择器那一层没验**：两个座位在同一个槽上都有兵"
                                         + "（拿不到「一侧空着」的槽）—— 如实说没验，不装作验过");
                }

                driver.SetMySeat(0, rebuildViews: true); driver.RefreshAll();
            }
            else Check(false, "客机视角：能给两边各摆一个单位（`DeployFree`）");

            driver.SetMySeat(0, rebuildViews: true);   // 🔴 **还原**（后面 `CheckSavedScene` 那一节还要用）
            driver.RefreshAll();
        }

        // ---- 20. 本地录像：录了一局 → 量它多大 → 放一遍 → 指纹对得上吗 🆕 2026-09-27 ----
        // 判据全文 → `Battle/ReplayStore.cs` 文件头 · `BattleDriver.RecFinish` / `PlayReplay`。
        // 🔴 用户 2026-09-27 拍板「做，我们需要录像」，并问了两件事：**专门的文件夹**（= `ReplayStore.Dir`）
        //    与 **「留最近 50 局、占多大」** ⇒ 这一节把「一局多大」**量出来**，50 局的占用就是它 ×50。
        Debug.Log(P + "--- 本地录像（录 → 量大小 → 放 → 对指纹）---");
        {
            // 🔴 自检里那一局是**用 `SimulateAiTurn` 走的**（`SimpleAI.PlayTurn` + 回合推进）——
            //    它**现在也走同一条录制路**（`SimpleAI.Executed` 挂在引擎边界上；
            //    回合推进收口在 `EndTurnAndAdvance`）⇒ **自检这一局是完整录下来的**。
            //    ⚠️ 若哪天这里变成「指纹对不上」，先查那两个钩子还在不在（别急着改判据）。
            // 先**真打一局完整的**（两边都由 AI 代走），再拿它量大小 —— 别拿前面那种一两步就结束的局当样本。
            // 🆕 2026-10-12（A381）：这一句只为**下面那条骷髅断言**留一个「不是在断空气」的凭据
            //   （本节这局自己拿了多少颗 —— 0 颗时那条骷髅断言就没在断东西，日志里要说出来）。
            int skullBeforeSampleA381 = DailyData.SkullsCountValue();
            driver.Begin("Ultramarines", "Goff", 20260927);
            if (driver.InMulligan) driver.SimulateMulliganDone();
            int rg = 0;
            while (driver.Ctx != null && !driver.Ctx.IsOver && rg++ < 400) driver.SimulateAiTurn();
            Debug.Log(P + $"   录了一局完整的：{driver.Ctx.Turn} 回合 · 循环 {rg} 次");

            int n = ReplayStore.Count;
            Check(n > 0, $"★ 打过的局**都自动录了**（夹里现在 {n} 份）");
            // 取**动作最多的那一份**来量（最新那份可能是一两步就结束的局，不代表性）
            ReplayRecord rec = null; string newest = null;
            foreach (var f in ReplayStore.List())
            {
                var r = ReplayStore.Load(f);
                if (r == null) continue;
                if (rec == null || r.actions.Count > rec.actions.Count) { rec = r; newest = f; }
            }
            Check(rec != null, $"读得回来（动作最多的那份 `{newest}`）");

            // 🔴🔴 **2026-09-27 更正：要放的是「刚打完的这局」，不是「动作最多的那一份」。**
            //
            // 原来拿「最多的那一份」去放 ⇒ **必红**（2026-09-27 实测：分叉点**当时**在第 6 条）。
            // 🔴 **2026-10-19 就地订正（铁律 5 · `A1998`）**：本行原来写「分叉点**稳稳**在第 6 条」——
            //   **不成立**：这一份是「当轮录像里动作最多、且 ≠ 刚打完那份」的那一份，**分叉点随卡池与动作流变**
            //   （2026-10-14 的复跑实测首处分叉在**第 0 条**，`P2 手牌 5 vs 4`）。
            //   ⇒ 负例里**只断「发生了分叉」，不钉第几条**（见下面那条 `ReplayDivergenceForTest` 断言）。
            // 而根因**不是回放坏了**，是**那一局根本不可回放**：
            //   录像的契约是「起始条件 + 动作流」 —— 只有**由动作流产生**的局面才复现得出来。
            //   而自检前面那些「靶场」小节会**直接手写引擎状态**，例如
            //   本文件 `Run` 里那几处手写 `Board[…] = new UnitState(…)` `cAlt.Players[0].Board[2] = new UnitState(bikes, false)`
            //   （验完议程再在本文件还原）⇒ 那一步**永远不可能**由动作流复现。
            //   ⚠️ **2026-10-19（`A1971`）就地补注**：那一行现在已改成 `FreeSlot(cAlt, 0)`（不再写死 2 号格）；
            //      本段说的是**当时那份录像**的成因，⛔ 别拿现在的代码去否定这条历史结论。
            //   实测就是它：录的那一条 `kind=5 slot=2 alt=agenda` 打的是**手放上去的
            //   `Ravenwing Bikes`**，回放时那一格是空的 ⇒ `UseAlternative` 返回 `ErrNotUnit`
            //   （日志：「第 6 条……被拒：该格没有单位」）⇒ 从此整局错开、终局指纹不等。
            //   ⚠️ 判据是 `rec.traceState` 那两行（★ 新加的局面速写），不是猜的。
            // ⇒ **放本节刚打的那一局**（`Begin` + 换牌 + `SimulateAiTurn`，全程只有动作流）。
            //   它的路径就在 `LastReplayFile` 上（`RecFinish` 落盘时记的）。
            string playable = driver.LastReplayFile;

            // ⚠️ **A195 核过：这个门是安全的**（没改）—— 上面 `Check(rec != null, "读得回来（…）")` 就是这条前提。
            if (rec != null)
            {
                long bytes = new System.IO.FileInfo(System.IO.Path.Combine(ReplayStore.Dir, newest)).Length;
                // 黑匣子关掉之后是多大（= **真打时一局的大小**）——直接把那两份速写清空再序列化一次
                var t1 = rec.traceLogTail; var t2 = rec.traceState;
                rec.traceLogTail = new System.Collections.Generic.List<string>();
                rec.traceState = new System.Collections.Generic.List<string>();
                long plain = System.Text.Encoding.UTF8.GetByteCount(UnityEngine.JsonUtility.ToJson(rec));
                rec.traceLogTail = t1; rec.traceState = t2;
                long per = rec.actions.Count > 0 ? (plain - 500) / rec.actions.Count : 0;
                Debug.Log(P + $"   【量】刚打完那一局：**{rec.actions.Count} 条动作** ——"
                            + $" **开黑匣子 {bytes} 字节（{bytes / 1024f:F1} KB）** ／ **关黑匣子 {plain} 字节（{plain / 1024f:F1} KB）**"
                            + $" ⇒ 每条动作约 {per} 字节（净荷；头部约 500 字节）");
                Debug.Log(P + $"   【算】按 `ReplayStore.MaxKept = {ReplayStore.MaxKept}` 局："
                            + $"**真打（关黑匣子）满仓 ≈ {plain * ReplayStore.MaxKept / 1024f / 1024f:F2} MB**"
                            + $"（= {plain / 1024f:F1} KB × {ReplayStore.MaxKept}；带黑匣子约 {bytes * ReplayStore.MaxKept / 1024f / 1024f:F2} MB）");
                Check(bytes > 0 && plain > 0 && plain <= bytes, $"两个尺寸都量得出来（开 {bytes} / 关 {plain} 字节）");
                Check(rec.actions.Count > 0, $"动作流非空（{rec.actions.Count} 条）");
                Check(rec.finalHash != 0, "记下了终局指纹（放的时候拿它对账）");

                // 诊断：把**录的那一局**的最后几条引擎事件与动作表打出来（回放侧会在分叉点打它自己的）
                var alog = driver.Ctx != null ? driver.Ctx.ActionLog : null;
                if (alog != null)
                    for (int i = Mathf.Max(0, alog.Count - 4); i < alog.Count; i++)
                        Debug.Log(P + $"   【录】事件{i}: {alog[i].Kind}#p{alog[i].Player}s{alog[i].Slot}<-p{alog[i].TargetPlayer}s{alog[i].TargetSlot}:{alog[i].CardId}");
                for (int i = 0; i < Mathf.Min(8, rec.actions.Count); i++)
                {
                    var mm2 = rec.actions[i];
                    string pk = mm2.picks == null ? "null" : mm2.picks.Length.ToString();
                    Debug.Log(P + $"   【录】动作{i}: kind={mm2.kind} actor={mm2.actor} handIdx={mm2.handIdx} slot={mm2.slot} "
                                + $"tgtP={mm2.targetP} tgtSlot={mm2.targetSlot} alt={mm2.altKeyword} picks={pk}");
                }

                // ③ ★ **反面用例**（先做 —— 下面那次正面重建会把它覆盖掉）：
                //    靶场手改过局面那一局**放不出来**，而且必须**当场报出来**（红线：不许静默失败）。
                //    没有这一条的话，「回放悄悄演成另一局」这种事就没人管了。
                //    ⚠️ 只在「最多的那一份 ≠ 刚打完那份」时跑 —— 相等时说明这局也是干净的，跳过。
                if (newest != playable)
                {
                    Debug.Log(P + "   ★ 反面用例：下面这几行**红字是预期的**（靶场局放不出来 ⇒ 必须出声）");
                    bool bad = driver.PlayReplay(rec);
                    Check(!bad, "★★ **靶场手改过局面的那局放不出来，而且【报出来了】**"
                              + "（不是静默演成另一局 —— 「不许静默失败」的落地）");
                    // 🔴 **`A1998`（2026-10-19 · 第五十五会话 S3）：上面那条只断「失败」、不断【为什么】失败。**
                    //   `PlayReplay` 的 `false` 至少覆盖三种原因：① 开局头解不出 / 录像读不出来（提前 return）；
                    //   ② 全放完了但终局指纹不等；③ **轨迹分叉**。只有 ③ 是这一条负例要验的
                    //   （「局面的来路没记全 ⇒ 回放必然错开」）。不分开断 ⇒ 它可能因为**别的原因**变绿，
                    //   而没人看得出来（写手 `A1969` 当初查出「实际分叉点与注释写的不一样」正是这么漏的）。
                    //   判据 = `BattleDriver.ReplayDivergenceForTest`（回放侧第一次对不上轨迹时置位；
                    //   `PlayReplay` 开头会清成 -1）⇒ **≥ 0 才证明「是因为分叉而失败」**。
                    //   ⚠️ **不钉具体条数**（见上面那段订正：第 6 条 / 第 0 条都出现过）。
                    Check(driver.ReplayDivergenceForTest >= 0,
                          $"★★ ……而且失败的原因是**轨迹分叉**（首处分叉 = 第 {driver.ReplayDivergenceForTest} 条），"
                        + "不是「开局头解不出 / 录像读不出来」那一类 —— 后者会让这条负例**因为错的原因**变绿");
                }
                // 🔴 **A195**：原来这一支**连出声都没有** —— 两份相等时那条 ★★ 就静默不跑。
                //    这里**不加断言**：相等是**合法情形**（说明「动作最多那一份」就是刚打完的干净局），
                //    真红了反而是假警报 ⇒ 按红线取「出声」那一半（同 §1f 那句「没建 3D 战场 ⇒ 跳过」的做法）。
                else Debug.Log(P + "   （「动作最多那一份」就是刚打完那份 ⇒ 上面那条反面用例**跳过**"
                                  + " —— 不是失败，但这一档下那条 ★★ 等于没验；A195）");
            }

            // ② ★★ **正面：放刚打完的那一局**（`BeginFromPendingCore` 重建 + 全量灌动作，最后比指纹）
            var playRec = string.IsNullOrEmpty(playable) ? null : ReplayStore.Load(playable);
            Check(playRec != null, $"刚打完那一局的录像读得回来（`{playable}`）");
            if (playRec != null)
            {
                // 🔴 **A381**（2026-10-12）：放一局录像 **一笔记账都不许有** —— 判据 = 原版
                //   `ChallengeLogMgr.LogMatchEnd` **只在真打完时叫**（回放不是「真打完」）。
                //   闸在驱动侧（`BattleDriver.UpdateHud` 那个结算块，字段 `_replaySession`），这里读它的自检口。
                //   ⚠️ 三个基线**必须在 `PlayReplay` 之前**记：那一趟会把动作**一口气**灌完、`Ctx.IsOver`
                //   在那趟结束时就为真，而画面靠 `_timeline` 慢慢演 ⇒ 闸要是只在那一趟为真，
                //   下一帧 `Update()` 就复发（所以它必须**整场回放期间**都留着）。
                //   🧨 **改坏法**：删掉 `PlayReplay` 里置 `_replaySession` 那一句、或删掉结算块里那个分支
                //   ⇒ 下面四条**同时红**（结算账 +1 / 对局记录 +1 / 日常骷髅 +N / 结算面板弹出来）。
                int logBeforeA381   = BattleLogData.Count;
                int skullBeforeA381 = DailyData.SkullsCountValue();
                int settleBefore381 = driver.SettleCount;
                Debug.Log(P + $"   【放】刚打完那局：{playRec.actions.Count} 条动作 · 座位 {playRec.mySeat}");
                // 🆕 **2026-10-13（A410）**：这一趟顺手把日志抓下来 —— 回放走的就是 `BeginFromPendingCore`
                //   （`PlayReplay` 传的是 `attachNet: false`），而那里面那句开局日志原来**写死**「联机开局」
                //   ⇒ 回放局在日志里也自称联机局。抓法 = 本仓现成的那一套（`Application.logMessageReceived`，
                //   同 `Editor/SettingsScene.cs` 的 `CaptureErrors`）。
                var log410 = new List<string>();
                Application.LogCallback h410 = (string m, string st, LogType ty) => log410.Add(m);
                Application.logMessageReceived += h410;
                bool same;
                try { same = driver.PlayReplay(playRec); }
                finally { Application.logMessageReceived -= h410; }
                Check(same, "★★ **回放演完，指纹与录制时【相等】⇒ 演的是同一局**"
                          + "（这是「录全了没有」唯一的尺子 —— 不等就说明有动作没录到）");

                // ---- 🆕 2026-10-24（执行代理 `A2` · `F2` 顺手发现 3）：`mulliganEnabled` 进录像头 ----
                //   判据 / 哨兵纪律 → `ReplayStore.mulliganPlus1` 的 doc（存**值 + 1**：0=没记·1=false·2=true）。
                //   ⛔ 它**不进 `MsgStart`**（那是联机协议结构，加字段 = 把码送上网；`Net/**` 不属本批白名单）。
                {
                    var rrUnit = new ReplayRecord();
                    Check(rrUnit.MulliganEnabledForReplay == null,
                          "★ A2·F2-3（哨兵）：**没记**那一档（`mulliganPlus1 = 0`）读口回 `null`、**不是 `false`**"
                        + " —— 老录像的 JSON 里没有这个键 ⇒ 必须退回「driver 当时的字段值」");
                    rrUnit.mulliganPlus1 = 1;
                    Check(rrUnit.MulliganEnabledForReplay == false, "★ A2·F2-3：存 `1` ⇒ 读回 `false`");
                    rrUnit.mulliganPlus1 = 2;
                    Check(rrUnit.MulliganEnabledForReplay == true, "★ A2·F2-3：存 `2` ⇒ 读回 `true`"
                        + " —— 🧨 把字段改成 `bool`（默认 `false`）⇒ 「没记」与「真的 false」会混 ⇒ 上面第一条红");
                    Check(playRec.mulliganPlus1 == 1 || playRec.mulliganPlus1 == 2,
                          "★ A2·F2-3：**这一局真打出来的录像头记了这一格**"
                        + $"（实得 `mulliganPlus1 = {playRec.mulliganPlus1}`，期望 1 或 2）"
                        + " —— 🧨 删掉 `RecBegin` 里那句 ⇒ 0 ⇒ 红");
                    Check(driver.ReplayMulliganPlus1AppliedForTest == playRec.mulliganPlus1,
                          "★ A2·F2-3：刚才那次 `PlayReplay` **用的是录像头那一格**"
                        + $"（头 = {playRec.mulliganPlus1} · 实际应用 = {driver.ReplayMulliganPlus1AppliedForTest}）"
                        + " —— 🧨 `PlayReplay` 里不读这一格、只靠 driver 当时的字段值 ⇒ 红（夹具默认 false）");
                    Check(driver.MulliganSeenByBeginForTest == playRec.mulliganPlus1,
                          "★ A2·F2-3：而且它**真的传到了 `RuleCore.NewBattle(openMulligan:)`**"
                        + $"（`Begin` 收到 {driver.MulliganSeenByBeginForTest}）"
                        + " —— 🧨 只在驱动字段上写一下、没在 `BeginFromPendingCore` **之前**恢复 ⇒ 红");
                }
                // 🆕 **2026-10-11（A985⑬ / A1295）**：录像的**头 / 尾**两条【只落盘】结果记录。
                //   ⛔ 它们不进 `MsgAction`、**不上网**（那个结构同时是**网络上**那个结构
                //      ⇒ 往里加字段 = 把理由码送上网，与原版相反）。
                //   🔑 **这几条为什么不自证**：
                //     (a) 「头」比的是**设计常量**（开局那一刻还没有结果 ⇒ `Undefined`、`seat` 不写）；
                //     (b) **判别式（灭自证）**：把「尾」那格**抹掉**后读口必须**退回 `Undefined`**
                //         ⇒ 证明它读的确实是那两条记录本身，而不是从别处推出来的；
                //     (c) 与**引擎事件表**独立对账 —— 两个数据源（一个在磁盘录像里、一个在 `ctx.Events` 里），
                //         两边过**同一个解析器**（共用一份 = 铁律「两处写同一条规则迟早不一致」的反面）。
                Check(ReplayStore.HasResultHead(playRec) && ReplayStore.HasResultTail(playRec),
                      $"★ A985⑬：录像的**头 / 尾**两条只落盘记录都在"
                    + $"（head={ReplayStore.HasResultHead(playRec)} · tail={ReplayStore.HasResultTail(playRec)}）");
                Check(ReplayStore.ReadResultHead(playRec) == BattleResult.Undefined,
                      $"★ ……「头」是设计上的 `Undefined`（实得 `{ReplayStore.ReadResultHead(playRec)}`）"
                    + " —— 开局那一刻还没有结果");
                // 🧨 **改坏法**：把 `RecFinish` 里那两条 `WriteResult*` 删掉 ⇒ 上面两条同时红；
                //   把 `ReadResultCode` 改成「不看那两格、恒返回 `Undefined`」⇒ 下面那条判别式红。
                var stripTail = ReplayStore.Load(playable);
                if (stripTail != null) stripTail.resultTail = "";
                Check(stripTail != null && ReplayStore.ReadResultCode(stripTail) == BattleResult.Undefined,
                      "★ ……**抹掉「尾」之后读口退回 `Undefined`**（证明它读的是那两条记录本身）");
                // (c) 与引擎事件表对账 —— ⚠️ **如实分两档**：**有**那条 `[BattleResult]` 行才硬断；
                //    **没有**（例如这一局的结束不走记码那条路）就**出声说没验**，⛔ 不假装验过。
                string evResultLine = driver.Ctx != null
                    ? driver.Ctx.Events.Find(sv => sv != null && sv.Contains("[BattleResult]")) : null;
                if (evResultLine == null)
                    Debug.Log(P + "   ⚠️ 这一局的 `ctx.Events` 里没有 `[BattleResult]` 行 ⇒ 「尾那格与事件表对账」"
                              + $"这一档**没验**（尾实得 `{ReplayStore.ReadResultTail(playRec)}`）—— 如实记，A985⑬");
                else
                {
                    Check(ReplayStore.TryParseResultLine(evResultLine, out var evCode, out var evSeat),
                          $"★ ……事件表里那条 `[BattleResult]` 行解析得出来（`{Short(evResultLine, 60)}`）");
                    Check(ReplayStore.ReadResultTail(playRec) == evCode,
                          $"★ ……**录像文件里的码 == 引擎事件表里的码**（文件 `{ReplayStore.ReadResultTail(playRec)}`"
                        + $" vs 事件 `{evCode}`，座位 {evSeat}）—— 两个数据源各读一遍");
                }
                // 🆕 **2026-10-13（A410）**：两句一起才咬得住「**照实情说**」——
                //   ① 不许再自称「联机开局」（判据 = 原版 `MatchType.Replay = 160` 是**独立的一档**，同 A387）；
                //   ② 也不许干脆不出声（红线：不许静默失败）⇒ 它得说清自己是「回放开局」。
                // 🧨 **改坏法**：把 `BeginFromPendingCore` 那句日志改回写死的「联机开局」⇒ 第 1 条红；
                //   把整句删掉（或只说状态、不再说这是哪一种局）⇒ 第 2 条红。
                //   ⚠️ 这一趟是**单机放录像**（上面 `driver.AttachNet(null)` 已经摘掉联机）⇒ 驱动侧判据落到
                //      `attachNet == false && _net == null` 那一档；联机 / 重连那两档的措辞这里**不验**。
                string log410txt = string.Join("\n", log410.ToArray());
                Check(!log410txt.Contains("联机开局"),
                      $"★ A410：回放局的日志**不再自称「联机开局」**（这一趟抓了 {log410.Count} 行日志）"
                    + " —— 回放与联机走的是同一个 `BeginFromPendingCore`，可**回放不是联机局**"
                    + "（原版 `MatchType.Replay = 160` 是独立的一档；同 A387）");
                Check(log410txt.Contains("回放开局"),
                      $"★ A410：那一趟**说清了自己是哪一档**（日志里有「回放开局」；共抓 {log410.Count} 行）"
                    + " —— 只把「联机开局」删掉、什么也不说同样是错（红线：不许静默失败）");
                // 🆕 **2026-10-12（A387，W4 备好的原文照贴）**：回放局**不再借「联机局」那张标签**。
                //   账的落点先订正：`deckNote` **根本不进「对局记录」**（`RecordBattleLog` 不收它、
                //   `BattleLogData.Match` 也没这一格）—— 它唯一去处是**提示行**（`Begin` → `_deckNotice` → `SetHint`）。
                //   而原版**没有我们这条提示行**（`SetHint` 文件头自己写着）⇒ 「回放该写哪句话」**没有判据**
                //   ⇒ 按「不发明文案」把它传 `null`。原版能给到的判据只到「**回放是独立的一档**」
                //   （`MatchType.Replay = 160`）。
                //   🧨 **改坏法**：把 `PlayReplay` 的 `deckNote: null` 换回 `"联机局"`（或任何非 null）⇒
                //   下面第 1 条**必红**（它比的是**传进去的原样值**，与「录的那局有没有带卡组」**无关**
                //   —— 这正是为什么不比成品句子 `DeckNotice`）。
                Check(driver.RawDeckNoteForTest == null,
                      "★ A387：回放局**不再借「联机局」那张标签**（`deckNote` 实得 "
                    + (driver.RawDeckNoteForTest == null ? "`null`" : "「" + driver.RawDeckNoteForTest + "」")
                    + "）—— 回放不是联机局（原版 `MatchType.Replay = 160` 是独立的一档）");
                // ⚠️ 第 2 条是**哨兵、不是主力**（如实标）：只有「录的那一局本来就没带卡组」时，旧实现才会
                //   拼出这两句 ⇒ 那一档下它红；别的档它**恒绿**，**单独不构成判据**。要两条都硬，
                //   就得让自检里那局录像本身不带卡组 —— 那是录像节的写法问题，不在 A387 这一笔账里。
                Check(!driver.DeckNotice.Contains("联机局") && !driver.DeckNotice.Contains("读不出来"),
                      $"★ ……提示行也不再说这两句（实得「{Short(driver.DeckNotice, 44)}」）");
                Check(driver.Ctx != null && driver.Ctx.IsOver, "回放演到终局（这一局演完了）");
                // ① 驱动侧那笔账（**自检口**）。
                Check(driver.SettleCount == settleBefore381,
                      $"★ A381：放一局录像 ⇒ 结算账**一笔都没多**（{settleBefore381} → {driver.SettleCount}）"
                    + " —— 原版 `LogMatchEnd` 只在真打完时叫");
                // ② 三个**独立于驱动**的可观测（这三条才是「真的没记」的判据，别只信驱动那个计数器）。
                Check(BattleLogData.Count == logBeforeA381,
                      $"★ ……对局记录**没多**（{logBeforeA381} → {BattleLogData.Count}）");
                Check(DailyData.SkullsCountValue() == skullBeforeA381,
                      $"★ ……日常骷髅**没多**（{skullBeforeA381} → {DailyData.SkullsCountValue()}；"
                    + $"本节那局自己拿了 {skullBeforeA381 - skullBeforeSampleA381} 颗 ⇒ 这条"
                    + (skullBeforeA381 - skullBeforeSampleA381 > 0 ? "**真的在断东西**）" : "**是恒真的**（如实说））"));
                Check(driver.End == null || !driver.End.Visible, "★ ……结算面板与开门视频**没弹**");
                // ③ 闸的前提（机制那一格）：它是「整场回放期间」为真、不是「灌动作那一瞬」。
                //    ⚠️ 与上面几条**分开断**：这一条红了是「闸的形态变了」，上面几条红了才是「账记多了」。
                Check(driver.ReplaySession,
                      "★ A381：回放局标记**整场都在**（`ReplaySession`；清掉的唯一入口是 `Begin()` = 新开一局）");
                Check(playRec.trace != null && playRec.trace.Count == playRec.actions.Count,
                      $"逐条轨迹与动作**一一对应**（{playRec.trace.Count} 条）—— 少一条就少对一个分叉点");

                // ---- 🆕 2026-10-20（战斗线 `W58-REPLAYINTRO`）：**回放开场也播独白** ----
                //   原版判据（逐句，`d:/2/tools/decomp_full/`）：
                //    · `BattleManager._StartBattlePhase_d__334__MoveNext.c:36-47` —— 回放局先
                //      `ClickPlayReplay`（开始演动作流），随后**照样落到下面那道闸**；
                //    · 同文件 `:141-148` —— `IsTutorialOrCampaignMatch() == 0` 才 `ShowHeroesIntroMessage`
                //      （真值集 matchType {100,130,140,190}）；原版回放 = `Replay(160)`、**不在**排除集。
                //   🧨 **灭自证**：删掉 `BattleDriver.PlayReplay` 里 `_replayDivergence = -1;` 之后那句
                //      `StartIntroMonologue();` ⇒ 起播次数恒 0，第 2 条必红（第 1 条已钉住「有换牌模式」
                //      ⇒ `Begin` 的无换牌支不会替它起播）。
                {
                    Check(driver.Ctx != null && driver.Ctx.Vars.showMulligan,
                          "（前提）录的那一局是**有换牌的模式**（`Vars.showMulligan = true`）"
                        + " —— 否则 `Begin` 的无换牌支会先起播一次，下面那条就分不清是不是回放路径起的播");
                    Check(driver.IntroStartCountForTest == 1,
                          $"★ W58：**回放开局也播开场独白**（`PlayReplay` 在动作流之前过了闸；"
                        + "原版 `_StartBattlePhase:36-47` 先 `ClickPlayReplay`、`:141-148` 再过同一道闸，"
                        + "`Replay(160)` 不在 {100,130,140,190}）"
                        + $"—— 起播次数 = {driver.IntroStartCountForTest}，期望 1");
                    Check(driver.IntroStage >= 0,
                          $"★ ……状态机确实在推（`IntroStage = {driver.IntroStage}`，≥0；-1 = 一句都没起）"
                        + " —— 回放那趟里 `RefreshAll → PlaySignals → AdvanceTimeline(0)` 已经推起它");
                    int firstRP = driver.IntroFirstForTest;
                    Check(firstRP == 0 || firstRP == 1,
                          $"★ ……先手侧照原版 `IsPlayerFirstIntro` 定下来了（实得 {firstRP}）");
                    // 🔴 **一局只播一次**（`_introStarted` 闩）：判别式 = 再叫一次，过闸次数必须**还是 1**。
                    //    🧨 删掉 `StartIntroMonologue` 里 `if (_introStarted) return;` 那一句 ⇒ 这里变 2，本条红。
                    driver.StartIntroMonologue();
                    Check(driver.IntroStartCountForTest == 1,
                          $"★ ……而且**一局只播一次**（再叫 `StartIntroMonologue()` 后起播次数仍是 "
                        + $"{driver.IntroStartCountForTest}，期望 1）");
                    // ⚠️ **回放契约的判据不在这里重复**：上面既有的 `Check(same, …)` 与
                    //    `ReplayDivergenceForTest < 0` 就是契约的尺子 —— 独白若动了引擎状态 / RNG，
                    //    动作流会逐条错开，那两条会先红（铁律：两处写同一条规则迟早不一致）。
                }
            }

            // ------------------------------------------------------------
            //  🆕 2026-10-19（`A1087`）：**录像头那一格「哪一个座位是电脑」必须被回放采纳**。
            //    背景：那一格在引擎里**有后果** —— `RuleCore.GoesSecondCard` 拿它判「后手那张防御卡
            //    从哪来」（**电脑** ⇒ 后手方阵营防御池**随机**取、**吃 `ctx.Rng`**；**真人** ⇒ 用卡组自带那张）。
            //    而它原来的判据是 `BattleDriver.AiShouldDriveOpponent`（`= _net == null`）——
            //    🔴 **放录像时 `_net` 恒 null** ⇒ 一份记着「-1（对手是真人）」的录像放出来会被当成
            //    「1（座位 1 是电脑）」⇒ 后手那张卡不同 + 随机流错位 ⇒ 轨迹分叉。
            //    🔴 本节的判据**不是**「回放时不许算 `_net == null`」这种实现细节，而是**可观测的行为**：
            //      **同一份录像、只拨头部那一格 ⇒ 重建出来的 `ctx.BotSeat` 必须跟着变**（一正一反）。
            //    🧨 **改坏法**：把 `Begin` 里 `botSeat: botSeatOverride ?? (AiShouldDriveOpponent ? 1 : -1)`
            //      退回写死的 `AiShouldDriveOpponent ? 1 : -1` ⇒ 下面第 2 条红（两趟都会是 `1`）。
            // ------------------------------------------------------------
            if (playRec != null)
            {
                // ① 老录像（JSON 里**没有这个键**）⇒ 不许被当成任何一档，必须落到「没记」上
                //    （哨兵取 `0` = `int` 默认值 ⇒ 初始化器跑不跑都安全；同 `tutorialStage` 那条纪律）
                var noKeyRec = JsonUtility.FromJson<CardPresentation.ReplayRecord>("{\"version\":2}");
                var noKeyVal = noKeyRec == null ? "?"
                             : (noKeyRec.BotSeatForNewBattle.HasValue
                                ? noKeyRec.BotSeatForNewBattle.Value.ToString() : "`null`");
                Check(noKeyRec != null && noKeyRec.BotSeatForNewBattle == null,
                      $"★ A1087：老录像（缺这一格）⇒ `BotSeatForNewBattle` = {noKeyVal}（期望 `null` = 「没记」）"
                    + " —— 哨兵是 `0`（= `int` 默认值），所以「初始化器跑不跑」都给 `0`"
                    + "｜🧨 把哨兵换成 `-1`/任何非 0 值 ⇒ 每一份老录像都被当成某一档电脑局（静默错）");

                int savedCode = playRec.botSeatPlus2;
                var savedActions = playRec.actions;
                try
                {
                    // 只拨头、不灌动作 —— 这一趟问的就是**开局那一格**（灌动作只会在分叉处刷屏，
                    // 而「分叉」在这个**人为**的头下是预期的，不是被测行为）
                    playRec.actions = new List<MsgAction>();
                    playRec.botSeatPlus2 = 1;                     // = `-1`：**这一局没有电脑**（联机局录下来就是这个值）
                    driver.PlayReplay(playRec);
                    Check(driver.Ctx != null && driver.Ctx.BotSeat == -1,
                          "★ A1087：录像头写「这一局没有电脑」（联机局的实情）⇒ 重建出来的对局**照它**建"
                        + $"（`ctx.BotSeat` 实得 {(driver.Ctx == null ? "?" : driver.Ctx.BotSeat.ToString())}，期望 **-1**）"
                        + "｜🧨 回放时现算 `AiShouldDriveOpponent`（恒真）⇒ 这里实得 `1` ⇒ 本条红");
                    playRec.botSeatPlus2 = 3;                     // = `1`：**座位 1 是电脑**（单机局录下来就是这个值）
                    driver.PlayReplay(playRec);
                    Check(driver.Ctx != null && driver.Ctx.BotSeat == 1,
                          "★ A1087 **判别式（灭自证）**：同一份录像，把头部那一格换成「座位 1 是电脑」⇒ "
                        + $"`ctx.BotSeat` = {(driver.Ctx == null ? "?" : driver.Ctx.BotSeat.ToString())}（期望 **1**）"
                        + " —— 一正一反 ⇒ 这一格既不可能是「恒 -1」也不可能是「头部根本不生效」");
                }
                finally { playRec.botSeatPlus2 = savedCode; playRec.actions = savedActions; }
            }

            // ------------------------------------------------------------
            //  🆕 2026-10-19（`A1100`）：**先手那一格【产品不许写字段】**（跨局泄漏的修复）。
            //    病（`资料/普查产出_第六会话/W_联机录像补记_A1099_A1100.md`）：`ForceFirstSeat` 只在
            //    `BeginFromPendingCore` 被写、**无处清** ⇒ 打一局**联机** / 放一局**录像**之后，
            //    **下一局单机**（`Restart()` 或任何 `Begin`）沿用上一局的**绝对座位** ⇒ **先手不掷硬币**。
            //    ✅ 修法：产品改走 `Begin(firstSeatOverride:)`（联机开局 / 重连重建 / 放录像三档都走它），
            //       `A1111` 起那个存储已**私有**（只留 `SetFirstSeatForTest` / `FirstSeatPinForTest`）。
            //    判据全是**可观测的行为**（`ctx.FirstSeat`），⛔ 不是「看哪个字段被写过」：
            //      ① 正：联机那条路（`BeginFromPendingCore`，`pb.FirstSeat = 1`）⇒ `ctx.FirstSeat == 1`；
            //      ② 反（灭自证）：紧接着开一局**普通单机**（种子钉成「硬币 = 0」）⇒ `ctx.FirstSeat`
            //         必须是**掷硬币的结果** —— 若 `BeginFromPendingCore` 不再传 `firstSeatOverride`、
            //         又有谁把开局包那个绝对座位写进钉子（`A1111` 起已私有，产品写不进去）⇒ 这里实得 `1` ⇒ 红；
            //      ③ 钉子那一格仍然有后果：`SetFirstSeatForTest(1)` ⇒ `ctx.FirstSeat == 1`
            //         （不然 ② 可能是「这一格根本没人看」的恒真）。
            //    ⚠️ 全程**还原**：跑完把钉子装回原值（与 9c / A383 两节的收尾同一个手法）。
            //    ⚠️ 如实标注：这一节**只验「产品不再写那个字段 + 形参生效」**，不验「先手该是谁」那条规则
            //       （那条的覆盖在 9b / 9c 与教程那一节）。
            // ------------------------------------------------------------
            {
                int? savedFsPin = driver.FirstSeatPinForTest;   // 🆕 A1111：读口（私有字段只在 `BattleDriver` 里）
                int fsSeed = SeedForFirstSeat(0);   // 找一颗「掷硬币 = 座位 0」的种子（判据 = `FirstSeatForSeed`）
                int fsCoin = BattleDriver.FirstSeatForSeed(fsSeed);
                try
                {
                    Check(fsCoin == 0, $"（A1100 夹具）种子 {fsSeed} 掷出来是座位 {fsCoin}（这一节要 **0** 才能分辨泄漏）");

                    PinFirstSeat(driver, null);     // 拔掉自检的钉子（产品侧本来就不该有钉子）· 🆕 A1111 唯一写口
                    var pbFs = NetPendingBattle.FromStart(new MsgStart
                    {
                        seed = 20260920, mode = "Classic", arena = "Battle",
                        hostFirst = 1,               // 🔴 被测那一格（开局包说：绝对座位 1 先手）
                        hostFaction = "Ultramarines", clientFaction = "Goff",
                        hostDeckJson = "", clientDeckJson = "",
                    }, isHost: true);
                    Check(pbFs != null, "（A1100 夹具）开局包造出来了（`FromStart` 非 null）");
                    driver.BeginFromPendingCore(pbFs, attachNet: false, deckNote: null);
                    int fsGot1 = driver.Ctx == null ? -1 : driver.Ctx.FirstSeat;
                    Check(driver.Ctx != null && fsGot1 == 1,
                          $"★ A1100：先手走**显式形参** —— 联机 / 重连 / 放录像那条路（`BeginFromPendingCore`）"
                        + $"照着开局包建（实得 {fsGot1}，期望 **1**）"
                        + "｜🧨 把 `firstSeatOverride: pb.FirstSeat` 那一位删掉（先手会落到自检钉子 0）⇒ 本条红");

                    PinFirstSeat(driver, null);     // 产品那条路**不许**给这一格留下任何东西
                    driver.Begin(BattleDriver.DefaultFactionA, BattleDriver.DefaultFactionB, fsSeed);
                    int fsGot2 = driver.Ctx == null ? -1 : driver.Ctx.FirstSeat;
                    Check(driver.Ctx != null && fsGot2 == fsCoin,
                          $"★ A1100 判别式（灭自证）：紧接着开一局**普通单机** ⇒ 先手**掷硬币**"
                        + $"（实得 {fsGot2}，期望 {fsCoin}）—— 若上一局那个「绝对座位 1」留在产品状态里 ⇒ "
                        + "这里实得 1 ⇒ 红（那正是本笔要修的跨局泄漏：打完联机 / 放完录像，下一局不掷硬币）");

                    PinFirstSeat(driver, 1);        // ③ 自检的钉子仍然照旧生效（否则上面那条分不出「没人看这一格」）
                    driver.Begin(BattleDriver.DefaultFactionA, BattleDriver.DefaultFactionB, fsSeed);
                    int fsGot3 = driver.Ctx == null ? -1 : driver.Ctx.FirstSeat;
                    Check(driver.Ctx != null && fsGot3 == 1,
                          $"★ A1100：自检的钉子（`SetFirstSeatForTest(1)`）**照旧生效**（实得 {fsGot3}，期望 **1**）");
                }
                finally { PinFirstSeat(driver, savedFsPin); }
            }

            // ------------------------------------------------------------
            //  🆕 2026-10-19（`A1099`）：**联机局的【对手那一半】也必须进录像**。
            //    病（`资料/普查产出_第六会话/W_联机录像补记_A1099_A1100.md` §五·1）：`ApplyLoggedAction`
            //    是**联机局里对面那一侧唯一的落地口**（`NetBattle.cs` 三处：主机收客机动作 /
            //    客机收主机广播 / `AppendLogAndApply` 的换牌定序那三条伪动作），而它原来
            //    **一个记账口都没有** ⇒ 联机录像 = **本机自己那一半**（对手的动作、双方换牌一条都不进）
            //    ⇒ 灌到第一条就「不是你的回合」⇒ **今天本来就放不出来**。
            //    修法 = 在它的**末尾**（`return code;` 之前）补一次 `RecMsg(m)`。
            //
            //    🔴 本节的期望值**全部来自下面写死的那几条字面动作**（`kind` / `actor` / `seq` / 条数），
            //      ⛔ 没有一处从被测代码里算出来 —— 否则就是自证（`CLAUDE.md` §三「灭自证」那一条）。
            //      唯一的例外是第 ③ 格那次**自洽**比对（终局局面哈希），下面那一格自己如实标着。
            //
            //    四格判据（编号 = 下面代码里的编号）：
            //      ① 正：重连那一趟（`NetReplay` = 产品上真实的那条路）灌进去的**每一条**都要在录像里，
            //         字段逐条对得上 —— 其中 `actor == 0` 那两条，对 `_me == 1` 的本机来说
            //         **就是「对手那一半」**（`NetReplay` 里 `_net == null` ⇒ `host = false` ⇒ `MySeat = 1`）；
            //      ② 🧨 **灭自证**：再拿一条**从没经过 `NetReplay`** 的对手动作，走
            //         `NetBattle` 收对手动作时那个调用形状（**直接调 `driver.ApplyLoggedAction(...)`**）
            //         —— 它也必须进**同一份**录像。⇒ 结构上不可能靠「`NetReplay` 顺手记一下自己的入参」
            //         蒙混过去：那条路在这一格上**根本用不上**（这正是本笔要修的那个洞的形状）。
            //      ③ 自洽：这份录像**放得回来、而且演的是同一局** —— 那才是 `A1099` 要的那个结果
            //         （「对手那一半进了录像」的直接后果）。⚠️ 这一格的期望值来自被测代码自己的
            //         `NetProtocol.StateHash`（与既有 ⑨ 节 `recW.finalHash` 那一处**同一个手法**）
            //         ⇒ 它**不满足**「期望值不许从被测代码算」那条纪律，**那条由 ①② 两格满足**。
            //      ④ 位置 · 反面控制：被引擎**拒**的那一条**不进**录像 ——
            //         `RecMsg` 排在 `code != RuleCodes.OK` 那道早退**之后**；记账口若被挪到方法开头，
            //         录像里就会出现「回放时必然被拒」的条目（回放侧会把它报成分叉）。
            //
            //    ⚠️ 本节**只验记账口的位置与覆盖面**，⛔ 不验「重连重建出来的那一局对不对」
            //      （那条的覆盖在 `NetSelfTest` / `NetBattleTest`）；也**不验**「对面那个人在界面上是谁」。
            //    🔴 **座位必须还原**：`NetReplay` 那条路上 `_net == null` ⇒ `host = false`
            //      ⇒ `pb.MySeat = 1` ⇒ 它会把本机座位**改成 1**（这条路上本机就是客机）。
            //      本节末尾还原（与本文件里那句 `SetMySeat(0)` 同一条纪律 —— 后面每一节都按座位 0 写）。
            //    ⚠️ 收尾：最后一次 `Begin` 会**清掉 `_replaySession`**（与 A1087 / A1100 两节同一个收尾手法），
            //      后面 A382 那一节量的是「一局只记一笔结算」⇒ 这里必须把局面交回「一局普通的单机」。
            // ------------------------------------------------------------
            {
                int rpSeatSaved = driver.MyIndex;      // 进本节之前的座位（收尾还原用）
                // 🔴 **2026-10-24（`F2`）· 本节夹具的前提：这一局必须【真的开着换牌阶段】。**
                //   判据（产品形状）：`rpActs` 那三条伪动作 = `NetBattle.HostResolveMulligan` 发的那三条，
                //   而它的两个调用点都挂在**换牌提交**上 —— `Net/NetBattle.cs:1028`（主机自己也交了）
                //   / `:1222`（主机收到客机的换牌）⇒ **产品录像里出现 `MulliganDone`，必然意味着那一局
                //   真的进过换牌阶段**（`Ctx.MulliganOpen == true`）。反过来，「没换牌的一局 + 一条
                //   `MulliganDone`」**不是产品会录出来的形状**。
                //   🧨 原来本节没打开它（`driver.mulliganEnabled` 在 `RunCore` 里是默认 `false`）⇒
                //   `RuleCore.NewBattle` 的 `MulliganOpen` 从头就是 false、`Begin` 直接 `RuleCore.BeginTurn`
                //   （`BattleDriver.cs:4630`，回合 1）⇒ 重放里第一、二条 `Mulligan` 返回 -1（不在换牌阶段）、
                //   第三条 `MulliganDone` 落地时 `ctx.Turn` 已是 1 ⇒ `A32` 接的 `A29` 结构断言**如实报红**
                //   （实得第 2 条）。⇒ **要修的是夹具前提，不是那条断言**。
                //   ⚠️ 录（`NetReplay`）与放（`PlayReplay`）**整段都要带着它**：重建出来的必须与
                //   「录的那一刻」是同一局（`ReplayRecord` 头里没有这一格 ⇒ 靠 driver 这一段保持一致）。
                //   ⛔ 这**不是放宽断言**：`NetApply.Apply` / `PlayReplay` 一个字没动；把钉子关掉，
                //   这三条伪动作就不再是产品会录出来的形状（见上面那句判据）。
                bool rpMulSaved = driver.mulliganEnabled;
                driver.mulliganEnabled = true;
                var rpStart = new MsgStart
                {
                    seed = 20260921, mode = "Classic", arena = "Battle",
                    hostFirst = 0,                      // 绝对座位 0 先手（本节不关心先手，只要一个确定值）
                    hostFaction = "Ultramarines", clientFaction = "Goff",
                    hostDeckJson = "", clientDeckJson = "",   // 两副牌都空 ⇒ `ResolveDeck` 按种子自动凑（可复现）
                };
                // 🔴 三条**字面**动作 —— 形状照 `NetBattle.HostResolveMulligan` 发的那三条伪动作
                //   （换牌定序：座位 0 换、座位 1 换、换牌阶段结束）。它们**都不走 `LocalAct`**
                //   ⇒ 补记账口之前，这一趟一条都进不了录像。
                var rpActs = new List<MsgAction>();
                rpActs.Add(new MsgAction { kind = NetActionKind.Mulligan, actor = 0, marks = new int[0] });
                rpActs.Add(new MsgAction { kind = NetActionKind.Mulligan, actor = 1, marks = new int[0] });
                rpActs.Add(new MsgAction { kind = NetActionKind.MulliganDone, actor = 0 });

                driver.NetReplay(rpStart, rpActs);
                var rpRec = driver.Recording;
                Check(rpRec != null,
                      "★ A1099（前提）：重连重建那一趟**开了**一份新录像 —— `RecBegin` 的语义"
                    + "**从「开局」扩成「开局 / 重连重建」**（这一句在 `NetReplay` 的说明里显式写着）"
                    + "｜🧨 若这里为 `null`：`RecordReplays` 在重连那趟被关掉了（那是回放那趟的做法）"
                    + " —— 那正是候选 B，也是本件**没**走的那条");
                if (rpRec != null)
                {
                    int rpN = rpRec.actions.Count;
                    bool rpSame = rpN == rpActs.Count;
                    if (rpSame)
                        for (int i = 0; i < rpN; i++)
                        {
                            var gotA = rpRec.actions[i]; var wantA = rpActs[i];
                            if (gotA == null || gotA.kind != wantA.kind || gotA.actor != wantA.actor || gotA.seq != i)
                            { rpSame = false; break; }
                        }
                    var rpDigest = new System.Text.StringBuilder();
                    for (int i = 0; i < rpN; i++)
                    {
                        var a = rpRec.actions[i];
                        rpDigest.Append(i).Append(a == null ? ":null " : $":k{a.kind}/a{a.actor}/s{a.seq} ");
                    }
                    Check(rpSame,
                          $"★ A1099：重连那一趟灌进去的**每一条**都进了录像，`kind`/`actor`/`seq` 逐条对得上"
                        + $"（实得 {rpN} 条：{rpDigest}｜期望 3 条：k100/a0/s0 · k100/a1/s1 · k101/a0/s2）"
                        + "｜🧨 把 `ApplyLoggedAction` 末尾那句 `RecMsg(m)` 删掉 ⇒ 这里实得 **0 条** ⇒ 红"
                        + "（`_rec` 照旧被 `RecBegin` 建出来、只是**一条都没进去**）；"
                        + "其中 `a0` 那两条（本机 `_me == 1`）**就是「对手那一半」**");
                    Check(rpRec.trace != null && rpRec.trace.Count == rpN,
                          $"★ ……`trace` 与 `actions` **一一对应**（{rpRec.trace.Count} / {rpN}）"
                        + " —— 少记一次 ⇒ `PlayReplay` 之后每一条都比错位置（分叉点定位跟着错）");

                    // ② 🧨 灭自证：一条**从没经过 `NetReplay`** 的对手动作，直接走
                    //    `NetBattle` 收对手动作时那个调用形状（`_d.ApplyLoggedAction(m)`）。
                    int rpBefore = rpRec.actions.Count;
                    var rpDirect = new MsgAction
                    { kind = NetActionKind.Mulligan, actor = 0, marks = new int[0] };
                    int rpDirectCode = driver.ApplyLoggedAction(rpDirect);
                    int rpAfter = rpRec.actions.Count;
                    var rpDirectGot = (rpAfter > rpBefore && rpAfter - 1 < rpRec.actions.Count)
                                    ? rpRec.actions[rpAfter - 1] : null;
                    bool rpDirectOk = rpDirectCode == RuleCodes.OK && rpAfter == rpBefore + 1
                                   && rpDirectGot != null
                                   && rpDirectGot.kind == NetActionKind.Mulligan
                                   && rpDirectGot.actor == 0
                                   && rpDirectGot.seq == rpAfter - 1;
                    Check(rpDirectOk,
                          "★ A1099 **判别式（灭自证）**：一条**没经过 `NetReplay`** 的对手动作，"
                        + "直接走 `ApplyLoggedAction`（= `NetBattle.cs` 收对手动作的那个调用形状）"
                        + $"⇒ 也进**同一份**录像（{rpBefore} → {rpAfter} 条，"
                        + $"实得 kind={(rpDirectGot == null ? "?" : rpDirectGot.kind.ToString())}"
                        + $"/actor={(rpDirectGot == null ? "?" : rpDirectGot.actor.ToString())}"
                        + $"/seq={(rpDirectGot == null ? "?" : rpDirectGot.seq.ToString())}，期望 100/0/{rpAfter - 1}）"
                        + "｜🧨 记账口若只挂在 `NetReplay` 的重放循环里（而不是挂在**共用**的 "
                        + "`ApplyLoggedAction` 上）⇒ 这一格实得条数不变 ⇒ 红 —— 那条路在这一格上"
                        + "**根本用不上**（`NetBattle` 那三个调用点没有一个经过 `NetReplay`）");

                    // 🔴 **2026-10-24（`F8`）· 灭自证（录制侧）**：这份录像里 **第 2 条（`MulliganDone`）与
                    //   第 3 条之间真的开了一回合** —— 判据 = 这两格的 `DeepHash` **不等**。
                    //   为什么单开一条：下面 ③ 只断「回放侧逐条不分叉」。**把录制端那次 `BeginTurn` 也拿掉**
                    //   （`NetReplay` 收尾那句 `CompleteReplayBeginTurn()` —— 内部仍走 `NetApply.BeginTurnAfterSetup`；
                    //   ⚠️ **2026-10-24（执行代理 `A13`）就地订正（铁律 5）**：这里原来直接写「收尾那句
                    //   `NetApply.BeginTurnAfterSetup`」，`B1`（A1 第 4 件）已把它收口成 `CompleteReplayBeginTurn()`，
                    //   语义一字未变、只是多了一层「被 `IsOver` 挡成空操作时补开」）⇒ 两边都不开回合、③ 照样全绿 ——
                    //   那就把「回合开始真的发生过」这件事从判据里抹掉了（`CLAUDE.md` §三「灭自证断言」）。
                    //   ⚠️ 前提（可查日志）：第 3 条是 kind=100 的换牌残条，换牌阶段已关 ⇒ `RuleCore.Mulligan`
                    //      返回 -1 **不改局面**（日志 `[Net] 换牌落地：座位 0 换了 -1 张`）
                    //      ⇒ 这两格之间**唯一**的差别就是那次回合开始。
                    Check(rpRec.trace != null && rpRec.trace.Count >= 4 && rpRec.trace[2] != rpRec.trace[3],
                          "★ A1099（灭自证 · 录制侧）：这份录像里 **`MulliganDone` 与第 3 条之间真的开了一回合**"
                        + $"（第 2 条轨迹 {(rpRec.trace != null && rpRec.trace.Count > 2 ? rpRec.trace[2].ToString() : "?")}"
                        + $"，第 3 条 {(rpRec.trace != null && rpRec.trace.Count > 3 ? rpRec.trace[3].ToString() : "?")}"
                        + "；相等 = 两边都没开回合）"
                        + "｜🧨 把 `NetReplay` 收尾那句 `CompleteReplayBeginTurn()`（内部 = `NetApply.BeginTurnAfterSetup`）删掉"
                        + " ⇒ 这两格相等 ⇒ 红"
                        + "（⚠️ 2026-10-24 `A13` 订正文案：原来写的是「收尾那句 `BeginTurnAfterSetup`」，入口已收口）");

                    // ③ 自洽：这份录像**放得回来、而且演的是同一局**。
                    //    `finalHash` 照生产那个口算（`RecFinish` 用的就是它）—— ⚠️ 这一格的期望值
                    //    来自被测代码自己（如实标着，见本节头部那条 §附注）。
                    rpRec.finalHash = NetProtocol.StateHash(driver.Ctx);
                    bool rpRoundTrip = driver.PlayReplay(rpRec);
                    Check(rpRoundTrip && driver.ReplayDivergenceForTest < 0,
                          "★ A1099：这份**含对手那一半**的录像**放得回来、而且是同一局**"
                        + $"（`PlayReplay` 返回 {rpRoundTrip}，逐条轨迹首处分叉 = "
                        + $"{driver.ReplayDivergenceForTest}，期望 -1 = 没分叉）"
                        + " —— 这就是「补上记账口之后，重连过的那一局得到一份从头到尾完整的录像」那件事"
                        + "｜🧨 对手那一半没进录像（或只进了一半）⇒ 分叉点会落在第一条"
                        + "（换牌那三条伪动作没人记账 ⇒ 重建出来还是换牌阶段）⇒ 本条红");

                    // 🔴 **2026-10-24（`F8`）**：回放结束**不许留下「回合还没开」的待办** ——
                    //   留着它说明那条被推迟的 `BeginTurn` 只是**被跳过**（终局 `StateHash` 只数张数，
                    //   恰好相等也会全绿），而不是被兑现。这是「真兑现了」的独立读数（不是哈希）。
                    Check(!NetApply.SetupTurnPending(driver.Ctx),
                          "★ A1099（F8）：回放结束**没有留下「回合还没开」的待办**"
                        + $"（`NetApply.SetupTurnPending` = {NetApply.SetupTurnPending(driver.Ctx)}，期望 False）"
                        + "｜🧨 把 `PlayReplay` 收尾那句 `CompleteReplayBeginTurn()`（内部 = `NetApply.BeginTurnAfterSetup`）删掉"
                        + " ⇒ 待办还在 ⇒ 红"
                        + "（⚠️ 2026-10-24 `A13` 订正文案：原来写的是「收尾那句 `BeginTurnAfterSetup`」，入口已收口；"
                        + "`CompleteReplayBeginTurn` 先走 `NetApply.BeginTurnAfterSetup`（**消费待办标记**），"
                        + "再只对「被 `IsOver` 挡成空操作」那一档用强制入口补 ⇒ 删掉它，标记仍然留在表里）"
                        + "（那时终局指纹也可能恰好相等 —— 所以这一格不能只靠哈希）");

                    // 🔴 **2026-10-24（`A32`）：给 `A29` 的结构断言接线。**
                    //   `BattleDriver.cs:873-895` 在 `PlayReplay` 的逐条循环里加了一条**灭自证**的结构判据
                    //   （原版次序 = `C2/R-03`：`MulliganDone` / 环境卡落地那一刻 `ctx.Turn` 必须还是 0），
                    //   但它只置失败位 + `LogError`、**没有任何读者** ⇒ 等于没有硬断言（`A29` §四·2 明确留的活）。
                    //   ⚠️ 这一格正好是**含 `MulliganDone` 的那份录像**（上面手造的三条伪动作）⇒ 它就是最该读它的地方。
                    //   🧨 把 `NetApply` 的 `MulliganDone` 支改回「`EndMulligan` + `BeginTurn` 一拍做完」⇒ 红；
                    //      而且**同时**把录制端 `RecRaw(MulliganDone)` 挪到 `BeginTurn` 之后（哈希两边一起错、又都相等，
                    //      上面那条 `rpRoundTrip && ReplayDivergenceForTest < 0` 会全绿）⇒ 仍然红 ——
                    //      这一条与原版那一步的**位置**绑定，与哈希取在哪一点无关（`CLAUDE.md` §三「灭自证断言」）。
                    Check(driver.SetupOrderViolationForTest < 0,
                          "★ A29：开局次序 —— `MulliganDone`/环境卡落地时**回合还没开始**"
                        + $"（实得第 {driver.SetupOrderViolationForTest} 条，-1 = 没有）"
                        + "｜🧨 回放端把 `EndMulligan` 与 `BeginTurn` 合成一拍（或不给环境卡让路）⇒ 红");

                    // 🔴 **2026-10-24（`F2`）**：换牌钉子还原（= 本节进场的口径）。
                    //   必须在下面 ④ 那次 `Begin` **之前**：那一局是「普通的单机局」（它的注释这么写着），
                    //   带着换牌阶段开局会变成另一档前提（还会把换牌面板留在场上给后面的小节）。
                    driver.mulliganEnabled = rpMulSaved;

                    // 🔴 座位还原（`NetReplay` / `PlayReplay` 两条路都把本机座位改成了 1）——
                    //    必须在最后一次 `Begin` **之前**做：`Begin` 之后的 `_myFaction/_foeFaction`
                    //    是**视图侧**的（`owner == _me ? _my : _foe`），带着座位 1 开局会让
                    //    「我方 / 敌方」的名字与颜色**对调**，而这一节之后的每一节都按座位 0 写。
                    driver.SetMySeat(rpSeatSaved);
                    driver.RefreshAll();
                    Check(driver.MyIndex == rpSeatSaved,
                          $"（本节收尾）座位还原成 {rpSeatSaved}（实得 {driver.MyIndex}）"
                        + " —— 后面每一节都按座位 0 写");

                    // ④ 位置 · 反面控制：先把一盘普通的单机局开起来（既清掉 `_replaySession`，
                    //    又让 `_rec` 重新挂上），再喂一条**必然被拒**的动作。
                    driver.Begin(BattleDriver.DefaultFactionA, BattleDriver.DefaultFactionB, 20260922);
                    var rpRejRec = driver.Recording;
                    Check(rpRejRec != null,
                          "★ A1099（夹具）：新开一局之后录像**又挂上了**（`RecordReplays` 默认开）"
                        + " —— 不然下面那条「没记」是**恒真**的（没在录当然没记）");
                    if (rpRejRec != null)
                    {
                        int rpRejBefore = rpRejRec.actions.Count;
                        // `kind = 999` 不在 `AiActionKind` 里 ⇒ `NetApply.Apply` 走 `default:`
                        // 直接 `return ErrUnimplemented`（与局面无关 ⇒ 恒被拒，不靠运气）。
                        var rpBad = new MsgAction { kind = 999, actor = 0 };
                        int rpBadCode = driver.ApplyLoggedAction(rpBad);
                        Check(rpBadCode != RuleCodes.OK,
                              $"★ A1099（夹具）：那条坏动作**真的被拒了**（`{RuleCodes.Describe(rpBadCode)}`）");
                        Check(rpRejRec.actions.Count == rpRejBefore,
                              $"★ A1099（位置 · 反面控制）：**被引擎拒的那一条不进录像**"
                            + $"（{rpRejBefore} → {rpRejRec.actions.Count} 条）"
                            + "｜🧨 把 `RecMsg(m)` 挪到 `code != RuleCodes.OK` 那道早退**之前**（方法开头）"
                            + "⇒ 这里实得条数 +1 ⇒ 红（录像里多出一条回放时必然被拒的条目）");
                    }
                }
                // 🔴 **2026-10-24（`F2`）兜底还原**：`rpRec == null` 那条路上上面那次还原走不到
                //   （它在 `if (rpRec != null)` 里面）—— 同值重复赋值无害，但不能让钉子漏出去。
                driver.mulliganEnabled = rpMulSaved;
            }

            // ---- 🆕 2026-10-12（A382）：结算那一块的**闩**是 `_settled`（一局一张账），⛔ 不是面板可见性 ----
            //   旧实现 `if (_endPanel != null && !_endPanel.Visible)` 有两层病：
            //     ① 面板为 `null` ⇒ 四件事（面板 / 日常 / 对局记录 / 录像收尾）**全静默跳过**、没人出声；
            //     ② 那个「可见性」本来也不是闩 —— 它靠的是「新一局一开局，`UpdateHud` 的 `else` 支顺手
            //        `Hide()`」这个**副作用**。
            //   ⚠️ **「面板为 `null`」那一半自检里造不出来**（`EndPanel.Create` 恒建、不返回 `null`，
            //      见 `S2` §二.6）⇒ 「出声且账照记」那一半**只能靠代码审查** —— **如实记，不假称验过**。
            //      🔴 **2026-10-16 就地订正（铁律 5）**：上面那句「恒建、不返回 `null`」**本批起不再恒真** ——
            //        `EndPanel.Create` 现在要拿 `BattleDoors Canvas` 子画布，**拿不到时会出声并给 `null`**
            //        （`T09` 批 2）。⇒ 那句话**只对「画布建得起来」的档成立**，⛔ 别当无条件前提用。
            //   能验的那一半 = **闩不依赖面板可见性**：把面板 `Hide()` 掉再刷一帧。
            //   🧨 **改坏法**：把驱动侧 `if (!_settled) { _settled = true; … }` 换回
            //   `if (_endPanel != null && !_endPanel.Visible)` ⇒ 本段第二条红（面板被 `Hide()` 过 ⇒ 又记一笔）。
            {
                int settleBefore382 = driver.SettleCount;
                int logBefore382    = BattleLogData.Count;
                driver.Begin("Ultramarines", "Goff", 20260913);
                if (driver.InMulligan) driver.SimulateMulliganDone();
                driver.Forfeit();                      // 走真入口（与 §12 投降那一节同一条路）
                Check(driver.Settled && driver.SettleCount == settleBefore382 + 1
                      && BattleLogData.Count == logBefore382 + 1,
                      $"★ A382：一局**恰好**记一笔账（结算账 {settleBefore382} → {driver.SettleCount}；"
                    + $"对局记录 {logBefore382} → {BattleLogData.Count}）");
                if (driver.End != null) driver.End.Hide();   // 闩若是「面板可见性」，这一句之后就会**再记一笔**
                driver.RefreshAll();                        // 再刷一帧（`RefreshAll` 末尾就是 `UpdateHud`）
                Check(driver.SettleCount == settleBefore382 + 1 && BattleLogData.Count == logBefore382 + 1,
                      $"★ A382：把面板 `Hide()` 掉再刷一帧也**不会**再记一笔"
                    + $"（结算账 {driver.SettleCount}、记录 {BattleLogData.Count}）"
                    + " —— 闩是 `_settled`、不是面板可见性");
            }

            // ============================================================
            //  21. 🆕 2026-10-23（引擎线「新账-88」· 深审 B 的 `D1`/`D2`/`E1`）：**回放自证那三条**
            //  ------------------------------------------------------------
            //  判据 → `资料/普查产出_1023c/引擎深审B_可用性.md` §1·2（D1 / D2）、§4·2（E1）；
            //         执行报告 → `资料/普查产出_1023d/引擎_新账88_回放自证_执行报告.md`。
            //  三格各一条：
            //    21·1 `DeepHash` 的卡 id 必须走**跨进程稳定**的哈希（⛔ `string.GetHashCode()`）；
            //    21·2 `StateHash` 必须**演错了就判得出不同**（每一维一条「只改那一格 ⇒ 哈希必须变」）；
            //    21·3 AI 替先手/后手选环境卡**不许挪动 `ctx.Rng`**（开关打开时整条随机流不错位）。
            //  ⚠️ 期望值纪律：21·1 用**字面量**（⛔ 不从被测代码算）；21·2 / 21·3 断的是
            //     「两次读数**不相等**」这个**结构**（每一维同时就是它自己那条的灭自证）。
            // ============================================================
            {
                // ---- 21·1：`DeepHash` 的**跨进程锚点** ----
                // 两个数都只由字符内容决定 —— 换任何运行时 / 换一个进程都该复现；
                // `string.GetHashCode()` 给不出它们（.NET 的字符串哈希**按进程随机化**）。
                Check(NetProtocol.Hash("A") == 778 && NetProtocol.Hash("AB") == 24184,
                      $"★ 新账-88①：稳定哈希的字面量锚点（`Hash(\"A\")` = {NetProtocol.Hash("A")}、"
                    + $"`Hash(\"AB\")` = {NetProtocol.Hash("AB")}；期望 **778 / 24184** = 23*31+65 / 778*31+66）"
                    + "｜🧨 实现退回 `string.GetHashCode()` ⇒ 这两个数随进程变 ⇒ 红");
                {
                    // 一个**完全由字面量拼出来**的局面（空棋盘 · 一张手牌 `Id = "A"` · 实例号 7 · 能量 3）。
                    // 期望数 = 按 `DeepHash` 的算式**逐字节**手算出来的（不是跑被测代码得到的读数）。
                    var dhCtx = new RuleEngine.BattleContext(1);
                    dhCtx.Players[0] = new RuleEngine.PlayerState();
                    dhCtx.Players[1] = new RuleEngine.PlayerState();
                    dhCtx.Players[0].Energy = 3;
                    dhCtx.Players[0].Hand.Add(new RuleEngine.CardInstance(
                        new RuleEngine.CardDef("A", "Alpha", "unit", "", "common", "Ultramarines",
                                               1, 1, 1, 0), 7));
                    int dhGot = BattleDriver.DeepHashForTest(dhCtx);
                    Check(dhGot == -96317188,
                          $"★ 新账-88①：**跨进程锚点** —— 全字面量的局面 `DeepHash` = {dhGot}（期望 **-96317188**）"
                        + " —— 这个数只有「与运行时无关」的哈希算得出来；"
                        + "今天 Unity Mono 下 `GetHashCode()` 恰好稳定，所以**同进程自检本来是绿的**"
                        + "｜🧨 卡 id 那一格退回 `string.GetHashCode()` ⇒ 随进程变 ⇒ 红"
                        + "（换 CoreCLR / 换运行时的那一天，这条是唯一先红的东西）");
                }

                // ---- 21·2：`StateHash` 的**每一维都要能判出不同** ----
                // 手法：同一局面 → **只改一格** ⇒ 哈希必须变；改回来 ⇒ 必须变回去。
                // ⛔ 期望值不是从被测代码算的：判据是「两次读数不相等 / 相等」这个结构。
                // 🧨 每一维都是它自己的灭自证：把那一维从 `NetProtocol.PlayerHash` 删掉 ⇒ 那一条红。
                {
                    bool svPhase2 = driver.offensivePhaseEnabled, svMul2 = driver.mulliganEnabled;
                    driver.offensivePhaseEnabled = false;   // 这一格不验环境卡那一段（21·3 才验）
                    driver.mulliganEnabled = false;
                    driver.Begin(BattleDriver.DefaultFactionA, BattleDriver.DefaultFactionB, 20260923);
                    driver.offensivePhaseEnabled = svPhase2;
                    driver.mulliganEnabled = svMul2;
                    var hc = driver.Ctx;
                    Check(hc != null && hc.Players[0].Deck.Count >= 8,
                          $"（21·2 夹具）局面够用（牌库 {hc?.Players[0].Deck.Count ?? -1} 张，至少要 8 张）");
                    if (hc != null && hc.Players[0].Deck.Count >= 8)
                    {
                        // 找一对**不同名、且下标都不是 7 的倍数**的牌 —— 后半个条件是要**正对**
                        // 「牌库每 7 张取 1」那个旧口径的洞（换成任意一对也能红，但不精确）。
                        int di = -1, dj = -1;
                        var deck2 = hc.Players[0].Deck;
                        for (int i = 1; i < deck2.Count && di < 0; i++)
                            for (int j = i + 1; j < deck2.Count; j++)
                            {
                                if (i % 7 == 0 || j % 7 == 0) continue;
                                if (deck2[i]?.Card?.Id != deck2[j]?.Card?.Id) { di = i; dj = j; break; }
                            }
                        Check(di >= 0, "（21·2 夹具）牌库里找得到一对「不同名、下标都不是 7 的倍数」的牌");

                        System.Func<int> H2 = () => NetProtocol.StateHash(driver.Ctx);
                        int hb = 0, ha = 0, hr = 0;
                        System.Func<System.Action, System.Action, bool> mut = (apply, undo) =>
                        {
                            hb = H2(); apply(); ha = H2(); undo(); hr = H2();
                            return ha != hb && hr == hb;
                        };
                        var p0 = hc.Players[0];
                        var p1 = hc.Players[1];
                        int f0;

                        f0 = p1.Faith;  Check(mut(() => p1.Faith = f0 + 3, () => p1.Faith = f0),
                            $"★ 新账-88②：**信仰 `Faith`** 进了 `StateHash`（{hb} → {ha} → 复原 {hr}）"
                          + "｜🧨 删掉 `ps.Faith` 那一维 ⇒ 两次读数相等 ⇒ 红");
                        f0 = p1.SpiritStones; Check(mut(() => p1.SpiritStones = f0 + 2, () => p1.SpiritStones = f0),
                            $"★ 新账-88②：**灵魂石 `SpiritStones`**（{hb} → {ha} → 复原 {hr}）"
                          + "｜🧨 删掉那一维 ⇒ 红");
                        f0 = p1.QuestPoints; Check(mut(() => p1.QuestPoints = f0 + 1, () => p1.QuestPoints = f0),
                            $"★ 新账-88②：**任务点 `QuestPoints`**（{hb} → {ha} → 复原 {hr}）"
                          + "｜🧨 删掉那一维 ⇒ 红");
                        f0 = p1.Fatigue; Check(mut(() => p1.Fatigue = f0 + 1, () => p1.Fatigue = f0),
                            $"★ 新账-88②：**疲劳 `Fatigue`**（{hb} → {ha} → 复原 {hr}）"
                          + "｜🧨 删掉那一维 ⇒ 红");
                        f0 = p0.SecretsPlayed; Check(mut(() => p0.SecretsPlayed = f0 + 1, () => p0.SecretsPlayed = f0),
                            $"★ 新账-88②：**本局隐秘张数 `SecretsPlayed`**（{hb} → {ha} → 复原 {hr}）"
                          + "｜🧨 删掉那一维 ⇒ 红");
                        // 牌库：**中间那两张对调**（张数与首尾都不变；旧口径「每 7 张取 1」看不见）
                        if (di >= 0)
                        {
                            var ci = deck2[di]; var cj = deck2[dj];
                            Check(mut(() => { deck2[di] = cj; deck2[dj] = ci; },
                                      () => { deck2[di] = ci; deck2[dj] = cj; }),
                                  $"★ 新账-88②：**牌库全量**（把第 {di} 张与第 {dj} 张对调、张数不变；"
                                + $"{hb} → {ha} → 复原 {hr}）"
                                + "｜🧨 换回「每 7 张取 1」⇒ 这两个下标都不是 7 的倍数 ⇒ 两次读数相等 ⇒ 红");
                        }
                        // 弃牌堆：**张数不变、内容换一张**（旧口径只数张数 ⇒ 看不见）
                        {
                            var dc = p0.Discard;
                            int nDc = dc.Count;
                            int hBeforeDc = H2();
                            var addC = deck2[di >= 0 ? di : 0];
                            var otherC = deck2[dj >= 0 ? dj : 1];
                            bool diffC = addC != null && otherC != null
                                      && addC.Card != null && otherC.Card != null
                                      && addC.Card.Id != otherC.Card.Id;
                            Check(diffC, "（21·2 夹具）弃牌堆那两档用的确实是**两张不同名**的牌");
                            if (diffC)
                            {
                                dc.Add(addC);
                                int hA = H2();
                                dc[dc.Count - 1] = otherC;          // 仍张数 +1，**只换内容**
                                int hB = H2();
                                dc.RemoveAt(dc.Count - 1);
                                int hR = H2();
                                Check(hA != hB && hR == hBeforeDc && dc.Count == nDc,
                                      $"★ 新账-88②：**弃牌堆内容**（同张数、换一张 ⇒ {hA} → {hB}；清掉 ⇒ {hR}，"
                                    + $"期望回到 {hBeforeDc}）"
                                    + "｜🧨 删掉 `Discard` 那一段（旧口径只数张数）⇒ 两次读数相等 ⇒ 红");
                            }
                        }
                        Check(mut(() => p0.HandEffectRecords.Add(new RuleEngine.CardInstance.HandEffect
                                      { RecordId = 987654, Source = "probe", ExpireTurn = 3 }),
                                  () => p0.HandEffectRecords.RemoveAt(p0.HandEffectRecords.Count - 1)),
                              $"★ 新账-88②：**手牌效果记录表 `HandEffectRecords`**（{hb} → {ha} → 复原 {hr}）"
                            + "｜🧨 删掉那一段 ⇒ 红");
                        Check(mut(() => hc.CostMods.Add(new RuleEngine.CostMod
                                      { Player = 1, Key = "*", Delta = -2, HandOf = 0 }),
                                  () => hc.CostMods.RemoveAt(hc.CostMods.Count - 1)),
                              $"★ 新账-88②：**费用修正 `CostMods`**（{hb} → {ha} → 复原 {hr}）"
                            + "｜🧨 删掉那一段 ⇒ 红");
                        Check(mut(() => hc.TempControls.Add(new RuleEngine.BattleContext.TempControl
                                      { Owner = 1, Turn = hc.Turn, Slot = 0 }),
                                  () => hc.TempControls.RemoveAt(hc.TempControls.Count - 1)),
                              $"★ 新账-88②：**抢来的单位 `TempControls`**（{hb} → {ha} → 复原 {hr}）"
                            + "｜🧨 删掉那一段 ⇒ 红");
                        f0 = hc.EnchantmentsUsed;
                        Check(mut(() => hc.EnchantmentsUsed = f0 + 1, () => hc.EnchantmentsUsed = f0),
                              $"★ 新账-88②：**附魔计数 `EnchantmentsUsed`**（{hb} → {ha} → 复原 {hr}）"
                            + "｜🧨 删掉 `StateHash` 里那一格 ⇒ 红");
                        // 附魔（挂在单位身上那一条）—— 用督军这一份当载体（它一定在场、一定有 `Instance`）
                        var wu = p0.Warlord;
                        Check(wu != null && wu.Instance != null,
                              "（21·2 夹具）督军那一份有 `CardInstance`（附魔挂载点）");
                        if (wu != null && wu.Instance != null)
                        {
                            Check(mut(() => wu.Instance.ActiveEnchantments.Add(
                                              new RuleEngine.ActiveEnchantment
                                              { Card = wu.Card, EnchantmentCardId = 424242 }),
                                      () => wu.Instance.ActiveEnchantments.RemoveAt(
                                              wu.Instance.ActiveEnchantments.Count - 1)),
                                  $"★ 新账-88②：**附魔 `ActiveEnchantments`**（{hb} → {ha} → 复原 {hr}）"
                                + "｜🧨 删掉棋盘那一格里的附魔循环 ⇒ 红");
                        }
                        // 环境卡（进攻卡）那一次选择 —— 只在 `StateHash` 里
                        Check(mut(() => hc.OffensiveChosen = true, () => hc.OffensiveChosen = false),
                              $"★ 新账-88②：**进攻卡选择 `OffensiveChosen`**（{hb} → {ha} → 复原 {hr}）"
                            + "｜🧨 删掉 `StateHash` 里那三格 ⇒ 红");
                    }
                }

                // ---- 21·3：AI 选环境卡**不许挪动 `ctx.Rng`** ----
                // 判据（为什么选「方案 A」、为什么不是「回放端补掷」）→ `BattleDriver.PickOffensiveForAi` 的 doc。
                // 做法：同一颗种子跑两趟，唯一差别是「AI 要不要挑环境卡」；
                //      挑完之后从 `ctx.Rng` **连取 8 个数**，两趟必须**逐位相同**。
                //      （8 个数同时相同的偶然概率 ~1e-48 ⇒ 结构上不可能靠撞上。）
                // 🧨 改坏法：`PickOffensiveForAi` / `PickDefensiveForAi` 里 `Ctx.AiRng` 改回 `Ctx.Rng`
                //    ⇒ 挑卡那一趟多掷一次 ⇒ 8 个数整体错位 ⇒ 红。
                {
                    bool svP3 = driver.offensivePhaseEnabled, svC3 = driver.offensiveCardEnabled;
                    bool svD3 = driver.defensiveCardPanelEnabled, svM3 = driver.mulliganEnabled;
                    try
                    {
                        System.Func<bool, bool, int?, int[]> probe = (offOn, defOn, firstSeat) =>
                        {
                            driver.offensivePhaseEnabled = true;
                            driver.offensiveCardEnabled = offOn;
                            driver.defensiveCardPanelEnabled = defOn;
                            driver.mulliganEnabled = true;
                            driver.Begin("Ultramarines", "Goff", 20261024, firstSeatOverride: firstSeat);
                            if (driver.InMulligan) driver.SimulateMulliganDone();
                            var a = new int[8];
                            for (int i = 0; i < a.Length; i++) a[i] = driver.Ctx.Rng.Next(1000000);
                            return a;
                        };
                        string Join8(int[] a) { return string.Join(",", a); }

                        // ① 进攻卡：AI 是**先手** ⇒ 它替先手方挑
                        int[] offCtl = probe(false, false, 1 - driver.MyIndex);
                        int[] offRun = probe(true, false, 1 - driver.MyIndex);
                        bool offPicked = driver.Ctx.OffensiveChosen
                                      && driver.Ctx.OffensiveSeat == driver.Ctx.FirstSeat;
                        Check(offPicked,
                              "★ 新账-88③（前提）：AI **真的**替先手选了进攻卡"
                            + $"（`OffensiveChosen` = {driver.Ctx.OffensiveChosen}、`OffensiveSeat` = {driver.Ctx.OffensiveSeat}、"
                            + $"`FirstSeat` = {driver.Ctx.FirstSeat}）—— 没挑的话下面那条是**恒真**");
                        Check(Join8(offCtl) == Join8(offRun),
                              "★ 新账-88③：AI 挑**进攻卡**之后，`ctx.Rng` 的下 8 个数**逐位相同**"
                            + $"（关：{Join8(offCtl)}｜开：{Join8(offRun)}）—— 挑卡不挪动对局随机流"
                            + "｜🧨 `PickOffensiveForAi` 里改回 `Ctx.Rng.Next` ⇒ 开的那趟整体错一位 ⇒ 红");

                        // ② 防御卡：本机先手 ⇒ AI 是**后手**，替后手方挑
                        int[] defCtl = probe(false, false, driver.MyIndex);
                        int[] defRun = probe(false, true, driver.MyIndex);
                        bool defPicked = driver.Ctx.DefensiveSlotIdx >= 0;
                        Check(defPicked,
                              $"★ 新账-88③（前提）：AI **真的**替后手挑了防御卡（`DefensiveSlotIdx` = {driver.Ctx.DefensiveSlotIdx}，"
                            + "期望 ≥ 0）—— -1 = 走了「卡池里没有这一阵营防御卡」那一支，那下面那条等于没验");
                        Check(Join8(defCtl) == Join8(defRun),
                              "★ 新账-88③：AI 挑**防御卡**之后，`ctx.Rng` 的下 8 个数**逐位相同**"
                            + $"（关：{Join8(defCtl)}｜开：{Join8(defRun)}）"
                            + "｜🧨 `PickDefensiveForAi` 里改回 `Ctx.Rng.Next` ⇒ 红");

                        // ③ 端到端：**开关打开**录一整局 → 原样放一遍 → 终局指纹必须相等，
                        //    **而且逐条轨迹一条都不许分叉**（见下面新加的那条 `Check`）。
                        //    🔴 **2026-10-24（`A32`）就地订正（铁律 5）**：这里原来有一句
                        //    `recPlayE.trace = new List<int>();`，注释写着「`MulliganDone` / 环境卡那几格的轨迹
                        //    录制侧取在 `BeginTurn` **之前**、回放侧（`NetApply` 把 `EndMulligan`+`BeginTurn`
                        //    合成一拍）取在**之后** ⇒ 带 trace 会在那里**假报分叉**（那是**另一条账**）」。
                        //    **那条账已由 `A29` 修掉**（`NetApply.Apply(MulliganDone)` 只 `EndMulligan`，
                        //    `BeginTurn` 改到第一条真动作之前补；活局在 `RecMsg` 之后补；
                        //    结构断言在 `BattleDriver.cs:873-895`）⇒ **这句清 `trace` 的变通可以删**。
                        //    删掉之后，本格才真正**逐条**盯住随机流（RNG 一错位，通常从第 k 条起轨迹就不等），
                        //    「新账-88③」的端到端覆盖才算补全。
                        driver.offensivePhaseEnabled = true;
                        driver.offensiveCardEnabled = true;
                        driver.defensiveCardPanelEnabled = false;
                        driver.mulliganEnabled = true;
                        driver.Begin("Ultramarines", "Goff", 20260927, firstSeatOverride: 1 - driver.MyIndex);
                        if (driver.InMulligan) driver.SimulateMulliganDone();
                        var recE = driver.Recording;
                        bool hasPickE = false;
                        if (recE != null)
                            for (int i = 0; i < recE.actions.Count; i++)
                                if (recE.actions[i] != null && recE.actions[i].kind == NetActionKind.OffensivePick)
                                    hasPickE = true;
                        Check(hasPickE,
                              "★ 新账-88③（前提）：这一局的动作流里**真的**有一条 AI 进攻卡（kind=102）"
                            + " —— 否则下面那条端到端是恒真的");
                        int rgE = 0;
                        while (driver.Ctx != null && !driver.Ctx.IsOver && rgE++ < 400) driver.SimulateAiTurn();
                        Check(driver.Ctx != null && driver.Ctx.IsOver,
                              $"★ 新账-88③（夹具）这一局在 {rgE} 次推进内打完了（不然没有录像可放）");
                        string fE = driver.LastReplayFile;
                        var recPlayE = string.IsNullOrEmpty(fE) ? null : ReplayStore.Load(fE);
                        Check(recPlayE != null, $"★ 新账-88③（夹具）这一局的录像读得回来（`{fE}`）");
                        if (recPlayE != null)
                        {
                            // ⚠️ **前提**：`trace` 与 `actions` 一样长，下面那条「逐条不分叉」才不是恒真
                            //    （`RecRaw`/`RecAct` 在同一个方法里成对 `Add`；`ReplayRecord.trace` 是 public 字段
                            //     ⇒ `JsonUtility` 会写盘。少一条就说明存档/录制链路漏了，⛔ 别当「通过」）。
                            Check(recPlayE.trace != null && recPlayE.trace.Count == recPlayE.actions.Count,
                                  "★ 新账-88③（前提）：录像里**逐条轨迹齐全**"
                                + $"（trace {(recPlayE.trace == null ? -1 : recPlayE.trace.Count)} / actions {recPlayE.actions.Count}）");
                            bool sameE = driver.PlayReplay(recPlayE);
                            Check(sameE,
                                  "★ 新账-88③：**开关打开**（AI 替先手挑进攻卡、吃 `AiRng`）录的一整局，"
                                + "放回来**终局指纹与录制时相等**（= 整条 `ctx.Rng` 流没有错位）"
                                + "｜🧨 `PickOffensiveForAi` 改回 `Ctx.Rng.Next` ⇒ 录制端多掷一次、回放端不掷"
                                + " ⇒ 后面的抽牌/洗牌/AI 决策全部错位 ⇒ `finalHash` 不等 ⇒ 红");
                            // 🔴 **2026-10-24（`A32`）**：删掉「清 `trace`」之后这条才成立 ——
                            //   `PlayReplay` 的返回值只比**终局** `StateHash`（它只数张数），中途错位可能被抹平
                            //   （同一条理由见本文件 ⑨ 节那条与 `A29` §七·1）。
                            Check(driver.ReplayDivergenceForTest < 0,
                                  "★ 新账-88③：这一局的**逐条轨迹一条都没分叉**"
                                + $"（首处分叉 = {driver.ReplayDivergenceForTest}，-1 = 没有）"
                                + "｜🧨 回放侧 `MulliganDone` 的次序改回去 ⇒ 换牌那一格的轨迹必不等 ⇒ 红");
                        }
                    }
                    finally
                    {
                        driver.offensivePhaseEnabled = svP3;
                        driver.offensiveCardEnabled = svC3;
                        driver.defensiveCardPanelEnabled = svD3;
                        driver.mulliganEnabled = svM3;
                    }
                }
            }

            // 上限修剪：多存几份 ⇒ 只留最新的，旧的自动删
            int before = ReplayStore.Count;
            for (int i = 0; i < 3; i++)
                ReplayStore.Save(new ReplayRecord { savedAt = "2000-01-0" + (i + 1) + " 00:00:00", myHero = "Old" + i, foeHero = "X" });
            Check(ReplayStore.Count == before + 3, $"又塞了 3 份 ⇒ 一共 {before + 3} 份");
            int removed = ReplayStore.TrimToLast(before);
            Check(removed == 3, "按上限修剪 ⇒ **删掉 3 份最旧的**（不是删新的）");
            Check(ReplayStore.Count == before, $"修完剩 {before} 份");
            ReplayStore.ResetForTest();
            Check(ReplayStore.Count == 0, "自检收尾：清空临时目录");
        }

        // ---------------- 🆕 2026-10-12（A175）：`Auto Zoom` 的消费者（原版 `CombatAutoZoom`）----------------
        // 判据（全部实读，全文 → `Battle/CombatAutoZoom.cs` 文件头）：
        //  · 方法体 = `d:/2/tools/decomp_full/CombatAutoZoom__{ctor,Initialize,OnEnable,OnDisable,
        //    OnMinionNumberChanged,SetZoomLevel,ResetCameraZoomUIAction,ForceRefresh}.c`（`ForceRefresh` 与
        //    `ResetCameraZoomUIAction` **同一个 RVA 0x60CA80** = 逐字节同体）；
        //  · `SetZoomLevel` 里被反编译器吃掉的那两个操作数 = **指令流实读**（`工具/disasm_va.py … 0x18060ce40`）：
        //    开关真 ⇒ `Evaluate(人数)`、假 ⇒ 常量 `DAT_1834b2bb8` = **1.0**；上夹取也是这个 1.0；
        //  · 曲线 `unitsZoomCurve` = `MonoBehaviour_5231.json` 等 **13 份逐字节相同**（md5 `ca085afd`）；
        //  · 触发 = `MinionManager__RefreshOccupationSlots.c`（全反编译里 `OnMinionAddedOrRemoved` 的**唯一 Invoke 点**）。
        //  · 期望的 `lensShift.y` 两个数（−0.210542 / −0.250836）= 拿**原版那几条曲线**逐段 Hermite 手算出来的
        //    （`zoom = 1` / `zoom = 0`；算式就写在下面 `OffFrameA175` 那几行），⛔ **不是**从
        //    `CombatAutoZoom.LensShiftY` 读的 —— 从被测实现里读期望值 = 自证（本仓红线）。
        //    🔴 **2026-10-12（A444）改过一次**：原来那对是 **−0.207943 / −0.250551**，是照 `CombatAutoZoom.cs` 里
        //    **抄错的**三条取景曲线（`ViewShift` 的四段切线 + `PadModByAspect` 的 `+0.0517`）算出来的
        //    —— 形式上像「手算自原版」、实际**钉的是实现里那一份错值**。曲线订正后重算见下面那几行。
        // ⚠️ **放在这里（整轮最靠后）的理由**：这一块会真的改那台战场相机的取景，而 13d 那组
        //    「卡在屏内 / 卡底边压在手牌之上」的断言量的是**同一台相机** ⇒ 必须在它们全跑完之后。
        // 🧨 **主改坏法**：① 把 `SetZoomLevel` 里「开关假 ⇒ 1.0」那一支删掉（关着也套曲线）⇒ 第 3 条红；
        //    ② 把 `if (!manualCamera)` 那道闸删掉 ⇒ 第 7 条红；③ 把 `TargetZoomLevel` 的 setter 里
        //    `ApplyFraming()` 删掉（只算不落）⇒ 第 4/6 条红（`FramingApplyCount` 也钉着这件事）。
        {
            var az = driver.AutoZoom;
            Check(az != null && az.boardCamera == driver.boardCam && driver.boardCam != null,
                  "★ A175：3D 战场这一档下**消费者建出来了**，而且拿着的是**那台战场相机**"
                + $"（`BattleDriver.AutoZoom`；原版 `combatCameraZoom.targetCamera` = 场景里的 `BoardCamera`）"
                + $" —— 实得 {(az == null ? "`null`" : (az.boardCamera == null ? "相机为 null" : "对上了"))}");

            if (az != null && driver.boardCam != null)
            {
                // ① 曲线 = 原版那 5 个键（期望值是**原版字面量**，⛔ 不读 `az` 里那份）。
                Check(Mathf.Abs(CombatAutoZoom.EvaluateUnitsZoom(0f)) < 1e-6f
                   && Mathf.Abs(CombatAutoZoom.EvaluateUnitsZoom(2f)) < 1e-6f
                   && Mathf.Abs(CombatAutoZoom.EvaluateUnitsZoom(3f) - 0.105257757f) < 1e-5f
                   && Mathf.Abs(CombatAutoZoom.EvaluateUnitsZoom(4f) - 1f) < 1e-6f
                   && Mathf.Abs(CombatAutoZoom.EvaluateUnitsZoom(9f) - 1f) < 1e-6f,
                      "★ A175：人数→zoom 的曲线就是原版那 5 个键（**≤2 ⇒ 0 · 3 ⇒ 0.1052578 · ≥4 ⇒ 1**；"
                    + "判据 = `MonoBehaviour_5231.json`，13/13 场逐字节相同）");

                // ② 前提：宽高比就是 **16:9**（批处理里 `Shot()` 定死 `cam.aspect = (float)1920 / 1080`）——
                //    下面两个期望值就是按**这个**宽高比算出来的。
                //    🔴 **2026-10-12（A444）订正**：这里原来断的是「宽高比在 [1.333, 1.77]（只有这一档
                //    `PadMod ≡ 1`）」，而**实况是 16:9 = 1.7777778，比 1.77 高** ⇒ 那条前提**当场就是红的**；
                //    而且 `verticalPaddingModifierByAspectRatio(16:9) = 0.9951903 ≠ 1`（它在第 3 键 1.77
                //    之后才开始掉，16:9 已经进了下降段）⇒ 两个期望值必须把这一项带上。
                //    ⚠️ 本工程踩过同款坑（13d 那条「判据要在判据成立的条件下量」），所以把前提也断出来。
                float aspect = driver.boardCam.aspect;
                Check(Mathf.Abs(aspect - 16f / 9f) < 1e-4f,
                      $"（前提）战场相机宽高比（期望 **16:9**；实得 {aspect:F6}；`Shot()` 里 `cam.aspect = (float)1920 / 1080`）"
                    + " —— 下面两个 `lensShift.y` 期望值就是按这个宽高比算的"
                    + "（`verticalPaddingModifierByAspectRatio(16:9) = 0.9951903`，**不是** 1.0）");

                // 这一局重开一把干净的（前面那些段落把棋盘/对局都折腾过）。
                driver.Begin("Ultramarines", "Goff", 20260914);
                if (driver.InMulligan) driver.SimulateMulliganDone();
                driver.RefreshAll();

                // 两个期望值 = 拿**原版那三条曲线**逐段 Hermite **手算**出来的（⛔ 不是从被测实现里读的 —— 那是自证）：
                //   曲线逐值照抄 `MonoBehaviour_4697.json`（判据资产，13/13 场逐字节相同）；
                //   ★ **2026-10-12（A444）：曲线订正后重算过**（旧值 −0.207943 / −0.250551 是照**抄错的**那三条算的）。
                //   `minY = 249.9 / 1080 = 0.2313889`；
                //   `maxY(zoom) = (1080 − 96.7) / 1080 + PadMod(aspect) × PadByZoom(zoom)`
                //                = `0.9104630 + 0.9951903 × PadByZoom(zoom)`（宽高比 = 16:9 ⇒ `PadMod = 0.9951903`，见上面的前提）
                //   `arg = (maxY + minY) × 0.5`；`lensShift.y = ViewShift(arg)`
                //   · `zoom = 1`：`PadByZoom(1) = −0.1710815` ⇒ `arg = 0.4857966` ⇒ **−0.210542**
                //   · `zoom = 0`：`PadByZoom(0) = −0.0320131`（曲线左端**取端点值**）⇒ `arg = 0.5549963` ⇒ **−0.250836**
                //   ⚠️ 宽高比 ≤ 1.77 时（`PadMod ≡ 1`）这两个数是 **−0.210265 / −0.250793** —— A444 报告 §5·1 给的
                //      就是这一对（它把 `PadMod ≡ 1` 当成了前提）；**实况是 16:9，必须用上面那一对**。
                //   ⚠️ 订正前后差 **0.0026 / 0.00029**（前者 > 容差 0.001）⇒ 曲线被改回旧值这条会红。
                const float OffFrameA175 = -0.210542f;   // zoom = 1（= 烘进场景那一档，也是「关着」那一档）
                const float OnFrameA175  = -0.250836f;   // zoom = 0（= 原版曲线在人少那一档给的取景）
                float offFrame = OffFrameA175, onFrame = OnFrameA175;
                int evBefore   = az.ZoomEventCount;
                int applyBefore = az.FramingApplyCount;

                // ③ **关着 ⇒ 不缩放**。触发条件走**真那条路**（棋盘变 → 消费者收到人数事件）。
                AutoZoom.RestoreForTest(false, false);                        // 开关关（内存态，⛔ 不落盘）
                driver.Ctx.Players[0].Board[BoardSlots.SlotOf(BoardSlots.Left, 0)] =
                    new UnitState(CardByName(StarterCards.Ember(), "Veteran"), false);
                driver.RefreshAll();                                         // 棋盘一变 ⇒ `TickAutoZoom` 抬事件
                Check(az.ZoomEventCount > evBefore,
                      "★ A175：棋盘一变 ⇒ 消费者**真的收到人数事件**（原版 `MinionManager.OnMinionAddedOrRemoved` →"
                    + $" `OnMinionNumberChanged`；累计 {evBefore} → {az.ZoomEventCount}）");
                Check(Mathf.Abs(az.ZoomLevel - 1f) < 1e-6f,
                      $"★ A175：**开关关着 ⇒ zoom = 1（不缩放）**（实得 {az.ZoomLevel:F6}；"
                    + "原版 `SetZoomLevel` 那一支取常量 1.0，读指令流实得）");
                Check(Mathf.Abs(driver.boardCam.lensShift.y - offFrame) < 0.001f,
                      $"★ ……取景**一字不差**停在烘出来那一档（`lensShift.y` 实得 {driver.boardCam.lensShift.y:F6}，"
                    + $"本局零点 {offFrame:F6}）—— 关着的时候这一格**什么都不该改**");

                // ④ **开着 + 人少 ⇒ zoom = 0**，而且取景真的动了。触发走**菜单那颗开关同一条路**
                //    （`FindObjectByType<CombatAutoZoom>().ForceRefresh()` = 原版 `BattleSettingsWindow__OnAutoZoomChanged`）。
                AutoZoom.Set(true);
                az.ForceRefresh();
                Check(Mathf.Abs(az.ZoomLevel) < 1e-6f,
                      $"★ A175：**开着 + 较忙那侧 1 人（≤2）⇒ zoom = 0**（实得 {az.ZoomLevel:F6}，"
                    + "原版曲线第一档就是 0）");
                Check(Mathf.Abs(driver.boardCam.lensShift.y - onFrame) < 0.001f
                   && Mathf.Abs(onFrame - offFrame) > 0.02f,
                      $"★ ……取景**真的动了**：`lensShift.y` {offFrame:F6} → {driver.boardCam.lensShift.y:F6}"
                    + $"（期望 {onFrame:F6}；两档差 {Mathf.Abs(onFrame - offFrame):F4} ⇒ 这条分得开开/关两种状态）");
                Check(az.FramingApplyCount > applyBefore,
                      $"★ ……而且是**真写进相机**的，不只是算了个数（写入次数 {applyBefore} → {az.FramingApplyCount}）");

                // ⑤ **开着 + 人多 ⇒ zoom = 1**（曲线给满）⇒ 取景回到不缩放那一档。**两态真的翻得动**。
                for (int i = 0; i < BoardSpec.SlotsPerSide; i++)
                    driver.Ctx.Players[0].Board[BoardSlots.SlotOf(BoardSlots.Left, i)] =
                        new UnitState(CardByName(StarterCards.Ember(), "Veteran"), false);
                driver.RefreshAll();
                Check(Mathf.Abs(az.ZoomLevel - 1f) < 1e-6f
                   && Mathf.Abs(driver.boardCam.lensShift.y - offFrame) < 0.001f,
                      $"★ A175：**开着 + 较忙那侧 4 人（≥4）⇒ zoom = 1** ⇒ 取景回到不缩放那一档"
                    + $"（zoom {az.ZoomLevel:F6} · `lensShift.y` {driver.boardCam.lensShift.y:F6} vs {offFrame:F6}）");

                // ⑥ `manualCamera` 那道闸（原版 `if (!combatCameraZoom.manualCamera) set_TargetZoomLevel(…)`）
                //    —— **能分辨的那一半**：先置真，再把棋盘改成「该给 zoom 0」的样子（人少），
                //    走**非 force** 的事件那条路 ⇒ **不该动**。
                az.manualCamera = true;
                for (int i = 0; i < BoardSpec.SlotsPerSide; i++)
                    driver.Ctx.Players[0].Board[BoardSlots.SlotOf(BoardSlots.Left, i)] = null;
                driver.Ctx.Players[0].Board[BoardSlots.SlotOf(BoardSlots.Left, 0)] =
                    new UnitState(CardByName(StarterCards.Ember(), "Veteran"), false);
                driver.RefreshAll();
                Check(az.manualCamera && Mathf.Abs(az.ZoomLevel - 1f) < 1e-6f
                   && Mathf.Abs(driver.boardCam.lensShift.y - offFrame) < 0.001f,
                      "★ A175：`manualCamera` 为真时**人数事件不动取景**（现在较忙那侧只有 1 人 ⇒ 本该给 0，"
                    + $"实得 zoom {az.ZoomLevel:F6} · `lensShift.y` {driver.boardCam.lensShift.y:F6}）"
                    + " —— 原版那一道 `if (!manualCamera)` 就是它");

                // ⑦ **`force` 那条路会把手动档清掉**（原版 `if (force) { … *(combatCameraZoom + 0x30) = 0; }`）。
                az.ForceRefresh();
                Check(!az.manualCamera && Mathf.Abs(az.ZoomLevel) < 1e-6f
                   && Mathf.Abs(driver.boardCam.lensShift.y - onFrame) < 0.001f,
                      $"★ A175：**`ForceRefresh()`（force 那条路）清掉手动档并重算**"
                    + $"（`manualCamera` {az.manualCamera} · zoom {az.ZoomLevel:F6} · "
                    + $"`lensShift.y` {driver.boardCam.lensShift.y:F6} vs {onFrame:F6}）");

                // ⑧ 🆕 **2026-10-12（A421）**：`sensorSize.x` 那一半（原版 `CameraVerticalFramer.cameraSizeXTable`）。
                //   判据（全是实读）：曲线 6 键 = `bundle_scenes_scenes_battlearena1` 的 `MonoBehaviour_4697.json`
                //   （13/13 场逐字节相同）· `maxVerticalSizeInViewPort`（`framer+0x78`）= **7.0** ·
                //   那一段的指令流 = `CameraVerticalFramer$$CalculateFraming` VA 0x1806085D0 的
                //   `0x180608B4F`(abs 掩码) → `0x180608B69`(Math.Min) → `0x180608BB0`(取 `+0x38` 求值)
                //   → `0x180608C02-C0E`(`(origX − curve) × clamp01(zoom) + curve`)。
                //   **期望值全是原版字面量**，插值在本文件里**自己算一遍 Hermite**（⛔ 不读被测实现的静态口）。
                //   🧨 改坏法：① 曲线抄错一个键 ⇒ ①/③ 红；② 把 `Mathf.Min(…, 7)` 那个上夹去掉 ⇒ ②/④ 红；
                //   ③ `zoom = 1` 那支不恒等（比如忘了夹 zoom）⇒ ③ 红；④ `ApplyFraming` 里不写 `sensorSize.x`
                //   （只写 lensShift）⇒ ⑤ 红。
                {
                    // 原版 `cameraSizeXTable` 的 6 个键 / 值 / 段切线（原版字面量，抄自 `MonoBehaviour_4697.json`；
                    // 原版这 6 键满足 `outSlope[i] == inSlope[i+1]` ⇒ 一段只有一个切线）
                    float[] kt = { 4.930829048156738f, 5.591578006744385f, 5.856215000152588f,
                                   7.6655964851379395f, 8.940309524536133f, 11.45475959777832f };
                    float[] kv = { 41.084930419921875f, 35.6795539855957f, 33.34006881713867f,
                                   25.721040725708008f, 22.336490631103516f, 17.468660354614258f };
                    float[] km = { -8.180681228637695f, -8.84035587310791f, -4.210846900939941f,
                                   -2.655146598815918f, -1.93594229221344f, -2.3610286712646484f };
                    // Unity `AnimationCurve.Evaluate`（`m_PreInfinity/m_PostInfinity = 2` = Clamp ⇒ 两端取端点值）
                    // 在这几条键上的**逐段三次 Hermite**（`weightedMode = 0` ⇒ 权重不参与，切线就是上面那些）。
                    float wantCamX(float t)
                    {
                        if (t <= kt[0]) return kv[0];
                        if (t >= kt[5]) return kv[5];
                        for (int i = 0; i < 5; i++)
                            if (t >= kt[i] && t <= kt[i + 1])
                            {
                                float h = kt[i + 1] - kt[i], s = (t - kt[i]) / h, s2 = s * s, s3 = s2 * s;
                                return (2f * s3 - 3f * s2 + 1f) * kv[i] + (s3 - 2f * s2 + s) * h * km[i]
                                     + (-2f * s3 + 3f * s2) * kv[i + 1] + (s3 - s2) * h * km[i];
                            }
                        return kv[5];
                    }

                    // ① 曲线 = 原版那 6 个键（逐键比原版字面量）+ 两端 Clamp。
                    bool keysOk = true;
                    for (int i = 0; i < 6; i++)
                        if (Mathf.Abs(CombatAutoZoom.EvaluateCameraSizeX(kt[i]) - kv[i]) > 1e-3f) keysOk = false;
                    Check(keysOk
                       && Mathf.Abs(CombatAutoZoom.EvaluateCameraSizeX(0f) - 41.084930419921875f) < 1e-3f
                       && Mathf.Abs(CombatAutoZoom.EvaluateCameraSizeX(20f) - 17.468660354614258f) < 1e-3f
                       && Mathf.Abs(CombatAutoZoom.MaxVerticalSizeInViewPort - 7f) < 1e-6f,
                          "★ A421：`cameraSizeXTable` 就是原版那 **6 个键**、两端 Clamp，"
                        + "`maxVerticalSizeInViewPort` = **7.0**（判据 = `MonoBehaviour_4697.json`，13/13 场逐字节相同）");

                    // ② `Mathf.Min(|Δ世界 Y|, maxVerticalSizeInViewPort)` 那一段（**上夹真的在**）。
                    Check(Mathf.Abs(CombatAutoZoom.BoundsVerticalSizeInViewport(7.6837f) - 7f) < 1e-5f
                       && Mathf.Abs(CombatAutoZoom.BoundsVerticalSizeInViewport(-3.2f) - 3.2f) < 1e-5f
                       && Mathf.Abs(CombatAutoZoom.BoundsVerticalSizeInViewport(7f) - 7f) < 1e-5f,
                          "★ A421：`bounds` = `Mathf.Min(Mathf.Abs(Δ世界 Y), 7.0)`（上夹 + 取绝对值两半都在）");

                    // ③ `sensorSize.x = (origX − curve) × clamp01(zoom) + curve`：`zoom = 1` **恒等**、`zoom = 0` 取曲线值、
                    //    zoom 超出 [0,1] 被夹（原版那两条 `comiss`）。期望值 = 上面那个**独立 Hermite**。
                    float wantC7 = wantCamX(7f);          // = 28.523765f（手算：原版第 3–4 键之间）
                    Check(Mathf.Abs(CombatAutoZoom.FrameSensorSizeX(41.5f, 7f, 1f) - 41.5f) < 1e-4f
                       && Mathf.Abs(CombatAutoZoom.FrameSensorSizeX(41.5f, 7f, 0f) - wantC7) < 1e-3f
                       && Mathf.Abs(wantC7 - 28.523765f) < 1e-3f
                       && Mathf.Abs(CombatAutoZoom.FrameSensorSizeX(41.5f, 7f, 2f)
                                  - CombatAutoZoom.FrameSensorSizeX(41.5f, 7f, 1f)) < 1e-4f
                       && Mathf.Abs(CombatAutoZoom.FrameSensorSizeX(41.5f, 7f, -1f)
                                  - CombatAutoZoom.FrameSensorSizeX(41.5f, 7f, 0f)) < 1e-4f,
                          $"★ A421：`sensorSize.x` 的 lerp —— `zoom = 1` **恒等**（41.5 → "
                        + $"{CombatAutoZoom.FrameSensorSizeX(41.5f, 7f, 1f):F4}）· `zoom = 0` = 曲线值 "
                        + $"{wantC7:F6}（手算自原版那 6 个键 = 28.523765）· zoom 被 `Clamp01`");

                    // ④ **现量**：`bounds` 的自变量 = 「敌方区下沿 ↔ 我方手牌区上沿」在战场相机世界系里的高差。
                    //    期望值 = 原版那一条链在本文件里**独立写一遍**（⛔ 不读 `CombatAutoZoom` 任何静态口）：
                    //      z  = `boardCamera.transform.InverseTransformPoint(场地根).z`（原版那一格字面量 = 100.0
                    //           = 原版场地根 x；我们整体平移 −100 ⇒ 等价点 = `Vector3.zero`，z 恒等）
                    //      Δvp.y = (敌方下沿 − 手牌上沿) 的**视口** y 差（`LayoutSpace` 可见高 = 10 世界单位）
                    //      K  = `2 · z · tan(vFOV/2)`，`tan(vFOV/2) = (sensorSize.x / aspect) / 2 / focal`
                    //           （原版 `gateFit = Horizontal`：竖直画幅由 `sensorSize.x / aspect` 定）
                    {
                        var bcam4 = driver.boardCam;
                        // `sensorSize.x` **逐场两个取值**（41.5 / 37.2）—— 从**清单**读原版值（⛔ 不从相机现读，
                        // 那时相机上可能正挂着上一次算出来的曲线值），同 §存档检查那条的取法。
                        var camMf4 = ArenaBuilder.LoadManifest(BoardArena);
                        float sx4 = (camMf4 != null && camMf4.camera != null && camMf4.camera.sensorSizeX > 0f)
                                  ? camMf4.camera.sensorSizeX : 41.5f;
                        float zz = bcam4.transform.InverseTransformPoint(Vector3.zero).z;
                        float halfPx = LayoutSpace.DesignPxH * 0.5f;                       // 540
                        float enemyY4 = ((1080f - 96.7f) - halfPx) / 108f;                // 原版敌方 helper 下沿（从屏底 983.3 px）
                        float playerY4 = (249.9f - halfPx) / 108f;                        // 原版手牌 helper 上沿（249.9 px · M = 1）
                        float tanHalf = (sx4 / bcam4.aspect) * 0.5f / 28f;                // focal 28（原版 `Camera_1461.json`）
                        float wantDelta = 2f * zz * tanHalf * (enemyY4 - playerY4) / LayoutSpace.DesignHeight;
                        // ⚠️ 上面用的是 `sx4`（原版那个 sensorSize.x）—— **量的时候相机上必须是它**
                        //    （原版那一句 `set_sensorSize(+0x98)` 就是把相机换成它再量；不还原会自激）。
                        // ⚠️ **不许断「它一定 > 7」**：`sensorSize.x` 逐场两个取值（41.5 / 37.2）而 `z` 也随场，
                        //    16:9 下窄的那三场算出来是 **6.888**（< 7，上夹**不**咬）⇒ 断死了会把那三场判红。
                        Check(Mathf.Abs(Mathf.Abs(az.MeasuredWorldDeltaY) - wantDelta) < 0.02f
                           && Mathf.Abs(az.BoundsVerticalSize - Mathf.Min(Mathf.Abs(az.MeasuredWorldDeltaY), 7f)) < 1e-5f
                           && az.BoundsVerticalSize <= 7f + 1e-5f,
                              $"★ A421：现量的「敌我卡区高差」= {az.MeasuredWorldDeltaY:F4} 世界单位"
                            + $"（本文件独立算一遍 = {wantDelta:F4}；`z` {zz:F4} · 宽高比 {bcam4.aspect:F4}"
                            + $" · 原版 `sensorSize.x` {sx4:F3}）"
                            + $" ⇒ `bounds` = {az.BoundsVerticalSize:F4} = `Min(|高差|, 7.0)`"
                            + $"（{(Mathf.Abs(az.MeasuredWorldDeltaY) > 7f ? "上夹咬住了" : "上夹没咬、取的就是它")}）"
                            + "；⚠️ 实现返回的是 `y(手牌上沿) − y(敌方下沿)`（原版那个相减次序，**负**数）"
                            + " —— 所以左边先取一次绝对值");
                    }

                    // ⑤ **两态**：开关开着 + 人少（此刻 zoom = 0）⇒ 相机 `sensorSize.x` **真的被写成曲线值**；
                    //    关掉 ⇒ **回到原样**。原样那两个数从**这一局真相机**上取（关着的时候写的就是它），
                    //    不是从被测实现里读的。
                    {
                        var bcam5 = driver.boardCam;
                        // 先把开关关掉、重算一次 ⇒ 相机上就是「原版那一档」
                        AutoZoom.RestoreForTest(false, false);
                        az.ForceRefresh();
                        float origSx = bcam5.sensorSize.x;
                        float wantOff = az.BoundsVerticalSize;                 // 与开关无关（只跟几何/相机走）
                        float wantOn = wantCamX(wantOff);                      // ⛔ 不被测实现，自己算的那一份
                        Check(Mathf.Abs(origSx - 41.5f) < 0.05f || Mathf.Abs(origSx - 37.2f) < 0.05f,
                              $"（前提）关着的时候相机 `sensorSize.x` 取原版那一档（期望 **41.5 或 37.2**"
                            + $"—— 原版 13 台里两个取值；实得 {origSx:F3}）");
                        Check(Mathf.Abs(bcam5.sensorSize.y - 24f) < 0.05f,
                              $"（前提）`sensorSize.y` **没被我们碰过**（期望 **24** = 原版序列化值；"
                            + $"实得 {bcam5.sensorSize.y:F3}）");

                        AutoZoom.Set(true);                                   // 内存态（`PersistOverride` 已开，⛔ 不落盘）
                        az.ForceRefresh();                                    // = 战斗内那颗开关那条路
                        Check(Mathf.Abs(bcam5.sensorSize.x - wantOn) < 1e-3f
                           && Mathf.Abs(bcam5.sensorSize.x - origSx) > 0.5f,
                              $"★ A421：**开关开着 + 人少 ⇒ `sensorSize.x` 真的被写成曲线值**"
                            + $"（{origSx:F3} → {bcam5.sensorSize.x:F3}，期望 {wantOn:F3} = "
                            + $"`(origX − cameraSizeXTable({wantOff:F3})) × 0 + 曲线值`）"
                            + " —— 只算不落（`ApplyFraming` 里不写这一格）就会红");

                        AutoZoom.RestoreForTest(false, false);
                        az.ForceRefresh();
                        Check(Mathf.Abs(bcam5.sensorSize.x - origSx) < 1e-3f,
                              $"★ A421：**关掉 ⇒ `sensorSize.x` 回到原版那一档**（{bcam5.sensorSize.x:F3} vs {origSx:F3}）"
                            + " —— 两态真的翻得动（`zoom = 1` 时那个 lerp 恒等）");
                    }

                }

                // 收尾：把取景放回**不缩放**那一档（后面只剩 A388 那一段，别再让相机停在歪的地方）。
                AutoZoom.RestoreForTest(false, false);
                az.ForceRefresh();
                Check(Mathf.Abs(driver.boardCam.lensShift.y - offFrame) < 0.001f,
                      $"★ A175 收尾：开关放回**关** ⇒ 取景回到不缩放那一档（{driver.boardCam.lensShift.y:F6}）"
                    + " —— 玩家的真设置在整轮末尾由 `AutoZoom.RestoreForTest` 放回（见下面那段）");
            }
        }

        // ---------------- ★ A422（2026-10-12）：原版 `CombatCameraZoom` 那一件（手动缩放 / 拖拽 / 世界边界 / 平滑）----------------
        // 判据（全部实读，全文 → `Battle/CombatCameraZoom.cs` 文件头）：
        //  · 26 个方法体 = `d:/2/tools/decomp_full/CombatCameraZoom__*.c`（+ 逐 VA 复核了 6 处**反编译器认错的操作数**）；
        //  · 常量 = `.rdata` 直读（`工具/read_literal.py`）；序列化值 = `MonoBehaviour_4404.json`（13/13 场逐字节相同）；
        //  · 期望值**一律在本文件里另行推/算**（⛔ 不读被测实现的静态口 —— 那是自证）。
        // ⚠️ **三个前提**（不设的话下面几条恒真或恒假；判据 → H20 报告 §三·A）：
        //   ① `PointerOverUi = () => false`（原版 = `IsPointerOverUIObject(fingerId)`；本仓没有 UGUI `EventSystem`）
        //      —— 不接的话第一次出声一次、之后按「不在 UI 上」放行（结果一样，但会多一行日志）；
        //   ② 🔴 **`FocusedOverride = true`** —— **批处理里 `Application.isFocused` 恒 `false`**，
        //      而那道门（原版 `EventSystem.current.m_HasFocus`）会把手动那一路**整条挡掉**；
        //   ③ `PointerViewportOverride` —— 不钉住的话 `GetWorldPositionUnderMouse` 跟着一个假鼠标坐标走。
        // ⚠️ **③、⑤～⑫ 跑在一个临时 rig 上**（自建相机 + 自建 `CombatAutoZoom`）：几何由本段钉死 ⇒
        //   世界边界那一档**可算**，而且**不碰真战场相机**（后面还有别的段落量那一台）。
        //   **这不是「换一条实现」** —— rig 上跑的是同一个 `CombatCameraZoom` / `CombatAutoZoom` 类。
        // 🧨 主改坏法：① `DragSign` 改回 `+1` ⇒ 第 9 条红；② 序列化值抄成 ctor 默认（`zoomSpeed 0.1` /
        //   `invertMouseScrollWheel false` / `dragSensitivity 0.005`）⇒ 第 2 条红；③ `SmoothDamp` 换成直接赋值 ⇒ 第 10 条红；
        //   ④ `ClampShiftLimits` 两条 `if` 改成 `else if` ⇒ 第 7 条（后者覆盖前者那一半）红；
        //   ⑤ 删掉 `if (manualCamera) return false;` ⇒ 第 11 条红；⑥ 删掉 `manualCamera = false` ⇒ 第 12 条红。
        {
            var az422 = driver.AutoZoom;
            var cz422 = az422 != null ? az422.CameraZoomForTest : null;
            if (az422 == null || cz422 == null)
            {
                // 不许静默：下面十几条全依赖它（`SetupAutoZoom` 只在有 3D 战场相机时才建它）
                Check(false, "★ A422：原版 `CombatCameraZoom` 那一件**没建出来** ⇒ 十几条一条都验不了"
                           + "（HUD 建了但没有 3D 战场相机那一档；原因见 `SetupAutoZoom` 的日志）");
            }
            else
            {
                Check(cz422.targetCamera == driver.boardCam && cz422.framer == az422,
                      "（前提）★ A422：那一件拿着的是**这台**战场相机 + **这个**取景器"
                    + "（原版 `CombatCameraZoom.targetCamera`(+0x20) = 场景里的 `BoardCamera`；`cameraVerticalFramer`(+0x50)）");
                Check(!SmallScreenUI.Enabled,
                      "（前提）★ A422：`smallScreenUI` **关着** —— 开着时 `CombatCameraZoom.TargetZoomLevel` 的 setter"
                    + " 会把上界压到 ~0.305（16:9），下面几条期望值按「上界 = 1」算的");

                // ① 常量 = 原版字面量（`.rdata` 直读：`0x1834b2bb8`/`0x1834b2bb4`/`0x1834b2bc8`/`0x1834b2da8`/
                //    `0x1834b3174`/`0x1834b2ba8`/`0x1834b2db8`）。
                //    ⚠️ 只有 `ScrollUnitsPerNotch` **不是** `.rdata` 里的原版字面量 —— 它是我们挑的等价物
                //    （转发 `TouchInputManager.ScrollUnitsPerNotch`）。**2026-10-22 量纲 120→1**：
                //    真机 `[SCROLLPROBE] raw=1.0000`（一格本来就是 ±1）⇒ 原来那个 `/120` 是错的等价物。
                Check(Mathf.Abs(CombatCameraZoom.OffZoom - 1f) < 1e-9f
                   && Mathf.Abs(CombatCameraZoom.DragSign - (-1f)) < 1e-9f
                   && Mathf.Abs(CombatCameraZoom.ScrollUnitsPerNotch - 1f) < 1e-9f
                   && Mathf.Abs(CombatCameraZoom.OriginalLensShiftSpeed - 10f) < 1e-9f
                   && Mathf.Abs(CombatCameraZoom.LensShiftSnapEpsilon - 1e-7f) < 1e-16f
                   && Mathf.Abs(CombatCameraZoom.ShiftCorrectionEpsilon - 1e-10f) < 1e-19f
                   && Mathf.Abs(CombatCameraZoom.CameraForwardEpsilon - 1e-6f) < 1e-13f,
                      "★ A422：七个常量逐个对得上（六个 = 原版 `.rdata` 字面量；`ScrollUnitsPerNotch` = 我们挑的等价物）"
                    + "（`OffZoom 1` · `DragSign −1` · `ScrollUnitsPerNotch 1`（我们挑的等价物，2026-10-22 量纲 120→1）"
                    + " · `OriginalLensShiftSpeed 10` ·"
                    + " `LensShiftSnapEpsilon 1e-7` · `ShiftCorrectionEpsilon 1e-10` · `CameraForwardEpsilon 1e-6`）"
                    + " —— `DragSign` 写回 `+1` 这一条就红（拖拽方向会反）");

                // ② 序列化值 = **场景那一档**（判据 = `MonoBehaviour_4404.json`，13/13 场逐字节相同）。
                //    🔴 这条专门盯那**三个「ctor 默认 ≠ 场景值」**：`zoomSpeed`(0.1/12.5) ·
                //       `invertMouseScrollWheel`(false/true) · `dragSensitivity`(0.005/0.01)。
                Check(Mathf.Abs(cz422.ZoomSpeedTest - 12.5f) < 1e-6f
                   && Mathf.Abs(cz422.DragSensitivityTest - 0.01f) < 1e-8f
                   && Mathf.Abs(cz422.SnapBackSpeedTest - 5f) < 1e-6f
                   && Mathf.Abs(cz422.ZoomSensitivityTest - 0.1f) < 1e-8f
                   && Mathf.Abs(cz422.ZoomSensitivityMobileTest - 0.005f) < 1e-9f
                   && cz422.InvertMouseScrollWheelTest,
                      $"★ A422：六个参数取的是**场景那一档**（`zoomSpeed 12.5` · `dragSensitivity 0.01` ·"
                    + $" `snapBackSpeed 5` · `zoomSensitivity 0.1` · `zoomSensitivityMobile 0.005` ·"
                    + $" `invertMouseScrollWheel true`）—— 实得 {cz422.ZoomSpeedTest} / {cz422.DragSensitivityTest} /"
                    + $" {cz422.SnapBackSpeedTest} / {cz422.ZoomSensitivityTest} / {cz422.ZoomSensitivityMobileTest} /"
                    + $" {cz422.InvertMouseScrollWheelTest}；**照 ctor 默认抄（0.1 / 0.005 / false）这一条就红**");
                var wb422 = cz422.WorldBoundsTest;
                Check(Mathf.Abs(wb422.x - (-10.05f)) < 1e-4f && Mathf.Abs(wb422.y - (-8f)) < 1e-4f
                   && Mathf.Abs(wb422.width - 20.115f) < 1e-4f && Mathf.Abs(wb422.height - 15.75f) < 1e-4f,
                      $"★ A422：`worldBounds` = 原版 `(89.95, −8.0, 20.115, 15.75)` 经**我们那次 −100 平移**之后那一档"
                    + $"（实得 ({wb422.x:F3}, {wb422.y:F3}, {wb422.width:F3}, {wb422.height:F3})；"
                    + "平移的判据 = `Editor/BattleScene.cs` 的 `ArenaOriginX = 100` + 场地根 `localPosition.x = −100`）");

                // ---- 临时 rig：几何由本段钉死。用完 `DestroyImmediate`。----
                // ⚠️ 必须在 `try/finally` 外面先把引用拿齐（`UnityEngine.Object` 的「假 null」那一套）
                GameObject rigGo = new GameObject("A422Probe_rig");
                try
                {
                    var rigCamGo = new GameObject("A422Probe_cam");
                    rigCamGo.transform.SetParent(rigGo.transform, false);
                    rigCamGo.transform.localPosition = new Vector3(0f, 0f, -5f);   // t = 5 ⇒ 视野宽 = 41.5×5/28 = 7.411
                    rigCamGo.transform.localRotation = Quaternion.identity;
                    var rigCam = rigCamGo.AddComponent<Camera>();
                    // 光学参数照 `Battle/ArenaSceneState.cs:111-117` 那一组（原版 `BoardCamera` 的那一档）
                    rigCam.orthographic = false;
                    rigCam.usePhysicalProperties = true;
                    rigCam.focalLength = 28f;
                    rigCam.sensorSize = new Vector2(41.5f, 24f);
                    rigCam.gateFit = Camera.GateFitMode.Horizontal;
                    rigCam.aspect = 16f / 9f;

                    var rigAz = rigGo.AddComponent<CombatAutoZoom>();
                    rigAz.boardCamera = rigCam;
                    rigAz.ResetForBattle();          // 出厂档（zoom 回 1、manualCamera 清、vcam 位移放回不缩放那一档）
                    var rigCz = rigAz.CameraZoomForTest;
                    if (rigCz == null)
                    {
                        Check(false, "★ A422：临时 rig 上那件组件**没建出来** ⇒ ③、⑤～⑫ 全验不了");
                    }
                    else
                    {
                        rigAz.Initialize();          // 那三句前提没写进去的那一句：让 `CombatCameraZoom.Initialize` 真的跑一次
                        rigCz.PointerOverUi = () => false;                 // 前提 ①
                        rigCz.FocusedOverride = true;                      // 前提 ②（批处理里必须钉）
                        rigCz.PointerViewportOverride = new Vector2(0.5f, 0.5f);   // 前提 ③

                        // ③ `Initialize` 的**反解**：相机当前那个 `sensorSize.x` 应当反解回 zoom = 1
                        //    （判据 = `CombatCameraZoom__Initialize.c`：`t = Clamp01((camSS.x − ss0.x)/(ss1.x − ss0.x))`，
                        //     而 `FrameSensorSizeX(…, zoom:1)` **恒等** ⇒ `ss1.x == camSS.x` ⇒ `t = 1`）。
                        //    🧨 改坏法：`ss0`/`ss1` 对调 ⇒ `t = 0`（分母变成 `ss0.x − camSS.x`）⇒ 红。
                        Check(Mathf.Abs(rigCz.TargetZoomLevel - 1f) < 1e-6f
                           && Mathf.Abs(rigCz.CurrentZoomLevel - 1f) < 1e-6f
                           && !rigCz.ManualCamera,
                              $"★ A422：`Initialize()` 把开局那个 zoom **反解回 1**（= 我们烘进场景那一档）"
                            + $"（实得 target {rigCz.TargetZoomLevel:F6} · current {rigCz.CurrentZoomLevel:F6} ·"
                            + $" manualCamera {rigCz.ManualCamera}）—— 反解公式里 `ss0`/`ss1` 对调就红");

                        // ④ `CorrectLensShift` **纯函数**（期望值在本文件里自己算：`1 / ((ss × |z|) / focal)`）
                        {
                            float kx = (rigCam.sensorSize.x * Mathf.Abs(rigCamGo.transform.position.z)) / rigCam.focalLength;
                            float ky = (rigCam.sensorSize.y * Mathf.Abs(rigCamGo.transform.position.z)) / rigCam.focalLength;
                            var cs = rigCz.CorrectLensShift(Vector2.zero, new Vector2(1f, 0f));
                            Check(Mathf.Abs(cs.x - 1f / kx) < 1e-7f && Mathf.Abs(cs.y) < 1e-12f
                               && Mathf.Abs(kx - 7.4107143f) < 1e-4f,
                                  $"★ A422：`CorrectLensShift((0,0),(1,0))` = `(1 / ((sensorSize.x × |pos.z|) / focal), 0)`"
                                + $"（本文件独立算：kx = 41.5×5/28 = {kx:F6} ⇒ 期望 {1f / kx:F6}，实得 ({cs.x:F6}, {cs.y:F6})）"
                                + " —— 把 x/y 两个分母对调 ⇒ 红");
                        }

                        // ⑤ `GetCameraFrustumWorldBoundsWithShift(zero)` = 「相机在 `z = 0` 平面上的视野」
                        //    期望矩形在本文件里由**公开的 Unity 相机属性**独立算：
                        //      t = (0 − pos.z)/forward.z · 宽 = sensorSize.x × t / focal ·
                        //      高 = 那个宽 / aspect · 中心 = (pos.x + forward.x·t, pos.y + forward.y·t)
                        //    （本 rig 的 forward = (0,0,1)、right = (1,0,0)、up = (0,1,0) ⇒ 轴对齐矩形）
                        {
                            var ct = rigCamGo.transform;
                            float t5 = (0f - ct.position.z) / ct.forward.z;
                            float w5 = rigCam.sensorSize.x * t5 / rigCam.focalLength;
                            float h5 = w5 / rigCam.aspect;
                            var r5 = rigCz.GetCameraFrustumWorldBoundsWithShift(Vector2.zero);
                            var wantC5 = new Vector2(ct.position.x + ct.forward.x * t5,
                                                     ct.position.y + ct.forward.y * t5);
                            Check(Mathf.Abs(r5.width - w5) < 1e-4f && Mathf.Abs(r5.height - h5) < 1e-4f
                               && Mathf.Abs(r5.center.x - wantC5.x) < 1e-4f && Mathf.Abs(r5.center.y - wantC5.y) < 1e-4f,
                                  $"★ A422：`GetCameraFrustumWorldBoundsWithShift(0)` = 相机在 `z = 0` 平面上的视野矩形"
                                + $"（实得 {r5.width:F4}×{r5.height:F4} @中心 ({r5.center.x:F4},{r5.center.y:F4})；"
                                + $" 独立算 {w5:F4}×{h5:F4} @({wantC5.x:F4},{wantC5.y:F4})）"
                                + " —— 半宽少乘/多乘那个 0.5、或把 `Vector3.forward` 换成别的静态（如 `up`）⇒ 红");
                        }

                        // ⑥ `ClampShiftLimits` 的**早退**：视野已在 `worldBounds` 内 ⇒ **原样返回**。
                        //    🧨 改坏法：把两条判断的**方向**写反（`r.xMin > bounds.xMin` 这种）⇒ 界内时 nx 会被算成
                        //       非零 ⇒ 返回值不再等于入参 ⇒ 红。
                        //    ⚠️ **如实记**：把那个 `1e-10` 的早退**整个删掉**，这一条**不会红**
                        //       （`CorrectLensShift(desired, (0,0))` 恒等于 `desired`，0/kx 就是 0）
                        //       ⇒ `1e-10` 只能靠第 ⑦ 条间接盯（那一档 nx 是真非零）。
                        {
                            var want6 = new Vector2(0.001f, -0.002f);
                            var got6 = rigCz.ClampShiftLimits(want6);
                            var r6 = rigCz.GetCameraFrustumWorldBoundsWithShift(want6);
                            var wb6 = cz422.WorldBoundsTest;
                            bool inside6 = r6.xMin > wb6.xMin && r6.xMax < wb6.xMax
                                        && r6.yMin > wb6.yMin && r6.yMax < wb6.yMax;
                            Check(inside6 && Mathf.Abs(got6.x - want6.x) < 1e-7f && Mathf.Abs(got6.y - want6.y) < 1e-7f,
                                  $"★ A422：`ClampShiftLimits` 的**早退** —— 视野完全在界内时**一个字节都不动**"
                                + $"（入参 ({want6.x},{want6.y}) ⇒ 实得 ({got6.x:F8},{got6.y:F8})；"
                                + $" 视野 x[{r6.xMin:F3},{r6.xMax:F3}] ⊂ 界 x[{wb6.xMin:F3},{wb6.xMax:F3}]）");
                        }

                        // ⑦a `worldBounds` **真夹**（视野比界窄 ⇒ 只一侧出界）：把 `desired.x` 喂大
                        //    ⇒ 返回值的 `.x` **小于**它，且新视野矩形的 **xMax 落回 `worldBounds.xMax`**（1e-4）。
                        {
                            var want7 = new Vector2(1.0f, 0f);
                            var got7 = rigCz.ClampShiftLimits(want7);
                            var r7 = rigCz.GetCameraFrustumWorldBoundsWithShift(got7);
                            var wb7 = cz422.WorldBoundsTest;
                            Check(got7.x < want7.x - 1e-3f && Mathf.Abs(got7.y) < 1e-9f
                               && Mathf.Abs(r7.xMax - wb7.xMax) < 1e-3f
                               && r7.xMin > wb7.xMin && r7.xMax < wb7.xMax + 1e-4f,
                                  $"★ A422：`ClampShiftLimits` **真的在夹** —— `desired.x = {want7.x}` ⇒ 实得 {got7.x:F6}（变小），"
                                + $" 夹完的视野 x[{r7.xMin:F3},{r7.xMax:F3}] 落回界 x[{wb7.xMin:F3},{wb7.xMax:F3}] 内"
                                + " —— 删掉那两条 `if`（不夹）这一条就红；`x/y` 分母对调也红");
                        }

                        // ⑦b 🔴 **那两条 `if` 不是 `else if`**（后者可以覆盖前者）：把视野拉**宽过界**（相机挪到 t = 20
                        //     ⇒ 视野宽 29.64 > 界宽 20.115）⇒ 正负两侧**同时**出界 ⇒ `nx` 最终取的是**后一条**
                        //     （`bounds.xMax − r.xMax`，负）⇒ 修正方向 = **左移**、夹完的 `xMax` 贴回界右沿而 `xMin` 仍在外。
                        //    🧨 改坏法：两条 `if` 改成 `else if` ⇒ 取的是**前一条**（正）⇒ 修正方向反过来 ⇒ 红。
                        {
                            rigCamGo.transform.localPosition = new Vector3(0f, 0f, -20f);   // t = 20 ⇒ 视野宽 29.643
                            var want7b = Vector2.zero;
                            var got7b = rigCz.ClampShiftLimits(want7b);
                            var r7b = rigCz.GetCameraFrustumWorldBoundsWithShift(got7b);
                            var wb7b = cz422.WorldBoundsTest;
                            Check(Mathf.Abs(r7b.width - 29.6429f) < 1e-3f          // 前提：这一档确实是「宽过界」
                               && got7b.x < want7b.x - 1e-3f                        // 修正 = 左移（后一条 if 赢了）
                               && Mathf.Abs(r7b.xMax - wb7b.xMax) < 1e-4f           // 右沿贴回界
                               && r7b.xMin < wb7b.xMin,                             // 左沿仍在外（宽过界的必然）
                                  $"★ A422：`ClampShiftLimits` 两条 `if` **不是 `else if`**（后者覆盖前者）—— "
                                + $"视野宽 {r7b.width:F3} > 界宽 {wb7b.width:F3} ⇒ 两侧同时出界 ⇒ 修正取**后一条**（左移），"
                                + $" 实得 `desired.x` {want7b.x} → {got7b.x:F6}，夹完 xMax = {r7b.xMax:F4} 贴回界右沿 {wb7b.xMax:F4}"
                                + $"、xMin {r7b.xMin:F3} 仍在外 —— **改成 `else if` 这一条就红**（方向会反过来）");
                            rigCamGo.transform.localPosition = new Vector3(0f, 0f, -5f);    // 挪回去
                        }

                        // ⑧ **滚轮改 zoom**（手动档）：`invertMouseScrollWheel = true` ⇒ 符号翻转 ⇒ **减**
                        //    期望：`TargetZoomLevel` 从 1 减到 `1 − zoomSensitivity × 1`（`zoomSensitivity` = 0.1）
                        //    🧨 改坏法：删掉 `invertMouseScrollWheel` 那一跳 ⇒ 方向反 ⇒ 值被上夹在 1 ⇒ 红
                        {
                            rigAz.ResetForBattle();                      // zoom 回 1、manual 回 false
                            rigCz.ManualCamera = true;
                            float z0 = rigCz.TargetZoomLevel;
                            rigCz.InjectPointerSource(+1f, false, Vector2.zero);   // 一格滚轮（原版 legacy 刻度 = ±1）
                            rigCz.TickInjected(0.02f);
                            float z1 = rigCz.TargetZoomLevel;
                            Check(Mathf.Abs(z0 - 1f) < 1e-6f && Mathf.Abs(z1 - (1f - 0.1f)) < 1e-4f
                               && z1 < z0 - 1e-3f,
                                  $"★ A422：滚轮一格 ⇒ zoom **减** `zoomSensitivity × 1 = 0.1`"
                                + $"（{z0:F6} → {z1:F6}；`invertMouseScrollWheel = true` ⇒ 原版那一句 `xorps` 求负）"
                                + " —— 把求负那一跳删掉 ⇒ 方向反、上夹在 1 ⇒ 红");
                        }

                        // ⑨ **右键拖拽平移**：`HandleDrag() = TouchDragDelta × dragSensitivity × (−1)`
                        //    ⇒ 向左拖 10 px ⇒ `(+0.1, 0)`；整帧之后 `virtualCameraLensShift.x` **变大**。
                        //    ⚠️ **量级别想当然**：拖那一帧里 `targetLensShift = vcam + drag = (0.1, …)`，而
                        //    `Vector2.SmoothDamp` 的 `smoothTime = dt × zoomSpeed = 0.02 × 12.5 = 0.25` ⇒
                        //    **一帧只走约 1.1%**（≈ +0.0011，本文件按 Unity 那条公式手算过）⇒ 阈值取 1e-4。
                        //    🧨 改坏法：`DragSign` 改 `+1` ⇒ 两条都红。
                        {
                            rigCz.ManualCamera = true;
                            rigCz.InjectPointerSource(0f, true, new Vector2(-10f, 0f));
                            var drag9 = rigCz.HandleDrag();
                            Check(rigCz.TouchPressedSecondary
                               && Mathf.Abs(drag9.x - 0.1f) < 1e-6f && Mathf.Abs(drag9.y) < 1e-9f,
                                  $"★ A422：右键按着时 `HandleDrag()` = `TouchDragDelta × dragSensitivity × (−1)`"
                                + $"（拖 (−10,0) ⇒ 期望 (0.1, 0)，实得 ({drag9.x:F6}, {drag9.y:F6})）"
                                + " —— 那个 `−1` 是 `.rdata` 直读（`0x1834B2BC8`），改成 `+1` 就红");
                            float x9 = rigCz.virtualCameraLensShift.x;
                            rigCz.TickInjected(0.02f);                   // 整帧：`ApplyZoom` 的手动档那条
                            float x9b = rigCz.virtualCameraLensShift.x;
                            Check(x9b > x9 + 1e-4f,
                                  $"★ A422：整帧之后镜头**真的往正走**（`virtualCameraLensShift.x` {x9:F6} → {x9b:F6}；"
                                + "方向 = 「向左拖 ⇒ 镜头右移」，同 `HandleDrag` 的 `−1`；量级 ≈ +0.0011 = 0.1 × 一帧平滑系数）"
                                + " —— 这一档几何在界内（视野宽 7.41 ≪ 界宽 20.115）⇒ **世界边界不会把结果吃掉**");
                        }

                        // ⑩ **平滑真的在追**（不是一步到位）：先让 target ≠ current（`SetZoomLevel(instant:false)`
                        //    那一档**只写 target**），再连跑两帧 ⇒ current 既不等于 target、又逐帧靠近。
                        //    🧨 改坏法：把 `Mathf.SmoothDamp` 换成直接赋值 ⇒ 第一帧就到位 ⇒ 红。
                        {
                            rigAz.ResetForBattle();       // ⚠️ **先把 current 也放回 1**（`SetZoomLevel(instant:false)` 只写 target，
                                                          //    而上面两帧已经让 current 动过了 —— 不重置的话「前提」那条会红）
                            rigCz.ManualCamera = false;
                            rigCz.SetZoomLevel(0.5f, false, false);
                            bool prem10 = Mathf.Abs(rigCz.TargetZoomLevel - 0.5f) < 1e-6f
                                       && Mathf.Abs(rigCz.CurrentZoomLevel - 1f) < 1e-5f;
                            rigCz.InjectPointerSource(0f, false, Vector2.zero);
                            rigCz.TickInjected(0.016f);
                            float c1 = rigCz.CurrentZoomLevel;
                            rigCz.TickInjected(0.016f);
                            float c2 = rigCz.CurrentZoomLevel;
                            Check(prem10 && Mathf.Abs(c1 - 0.5f) > 1e-3f && Mathf.Abs(c2 - 0.5f) > 1e-3f
                               && Mathf.Abs(c2 - 0.5f) < Mathf.Abs(c1 - 0.5f),
                                  $"（前提）目标 0.5 / 当前还是 1（`instant:false` 只写目标）—— 期望 **真**；实得 {prem10}；"
                                + $"★ A422：`SmoothDamp` **真的在追** —— 第一帧 {c1:F6}、第二帧 {c2:F6}（都在朝 0.5 走，"
                                + "两帧都没到位）—— 换成直接赋值 ⇒ 第一帧就 0.5 ⇒ 红");
                        }

                        // ⑪ **手动档 `SettleFraming()` 什么都不写**（原版那一道 `if (manualCamera) return false;`）
                        //    🧨 改坏法：删掉那一句 ⇒ 返回 true 且写相机 ⇒ 红。
                        {
                            rigCz.ManualCamera = true;
                            var ls11 = rigCam.lensShift; var ss11 = rigCam.sensorSize;
                            int ap11 = rigCz.FramingApplyCount;
                            bool wrote11 = rigCz.SettleFraming();
                            Check(!wrote11
                               && Mathf.Abs(rigCam.lensShift.x - ls11.x) < 1e-9f
                               && Mathf.Abs(rigCam.lensShift.y - ls11.y) < 1e-9f
                               && Mathf.Abs(rigCam.sensorSize.x - ss11.x) < 1e-9f
                               && Mathf.Abs(rigCam.sensorSize.y - ss11.y) < 1e-9f
                               && rigCz.FramingApplyCount == ap11,
                                  $"★ A422：手动档下 `SettleFraming()` 返回 {wrote11}、相机 `lensShift`/`sensorSize` **一个字节都没变**、"
                                + $" `FramingApplyCount` 也没涨（{ap11}）—— 原版那道 `if (manualCamera) return false;`"
                                + " —— 删掉它这一条就红");
                        }

                        // ⑫ `SetZoomLevel(force:true)` **清手动档**（原版 `manualCamera = false`），
                        //    而且清完之后 `SettleFraming()` 会真的写（两件叠起来的落点）。
                        //    🧨 改坏法：删掉 `manualCamera = false` ⇒ 两条都红。
                        {
                            rigCz.ManualCamera = true;
                            rigCz.SetZoomLevel(0.25f, false, true);
                            Check(!rigCz.ManualCamera && Mathf.Abs(rigCz.TargetZoomLevel - 0.25f) < 1e-6f,
                                  $"★ A422：`SetZoomLevel(force:true)` 清掉手动档并写新的目标"
                                + $"（manualCamera {rigCz.ManualCamera} · zoom {rigCz.TargetZoomLevel:F6}）");
                            int ap12 = rigCz.FramingApplyCount;
                            Check(rigCz.SettleFraming() && rigCz.FramingApplyCount > ap12,
                                  $"★ A422：……清完之后 `SettleFraming()` **真的会写**（`FramingApplyCount` {ap12} → "
                                + $"{rigCz.FramingApplyCount}）—— 手动档那道闸 + 落点那一路**两件叠起来**才对得上原版");
                        }
                    }
                }
                finally
                {
                    // ⚠️ 先把静默事件摘掉（`OnEnable` 在批处理里跑不跑本工程没定论，摘一次是幂等的），再销毁
                    var rigAzRef = rigGo.GetComponent<CombatAutoZoom>();
                    if (rigAzRef != null) rigAzRef.DetachMinionEvent();
                    // 🔴 2026-10-14（#8 顺手堵住 = **A809**）：**那条静态分辨率信号也必须摘**。
                    //   `CombatAutoZoom.Initialize()` 会建出 `BattleCameraSreenSize` **并**注册那条静态信号
                    //   （调用点 `Battle/CombatCameraZoom.cs:360` → 方法 `Battle/BattleCameraSreenSize.cs:172`）
                    //   —— 这里不摘
                    //   ⇒ 静态事件上留一个**指向已销毁组件**的委托：抬一次信号就冒一条
                    //   `[BattleCameraSreenSize] \`Initialize\` 的 combatCameraZoom 与 cameraVerticalFramer
                    //   两个都 没接上…`（`battle.log:40233` 就是这么来的），而且 `_refsMissingNoted` 把它闩住
                    //   ⇒ 之后再也看不见（**静默污染**，`D1013` §五·1 与本段 A463 各自独立查到）。
                    var rigCzRef = rigAzRef != null ? rigAzRef.CameraZoomForTest : null;
                    if (rigCzRef != null && rigCzRef.battleCameraScreenSize != null)
                        rigCzRef.battleCameraScreenSize.UnregisterResolutionSignal();
                    UnityEngine.Object.DestroyImmediate(rigGo);
                }

                // 收尾：把真那一件放回**不缩放**那一档（后面只剩 A388/A423，别再让相机停在歪的地方）。
                AutoZoom.RestoreForTest(false, false);
                az422.ForceRefresh();
            }
        }

        // ---------------- ★ A423（2026-10-12）：HUD 那颗「重置自动镜头」钮 ----------------
        // 判据（全是实读）→ `BattleDriver.ToggleCameraResetButton` 的注释（节点 `CenterCameraButton` ·
        //   `BattleHud.resetCameraZoomButton`(+0xa8) · 显隐三处调用点 · 点击链 · `.rdata` 三个 punch 常量）。
        // 🧨 改坏法：① 图名/尺寸写错 ⇒ 第 1/2/3 条红；② 建完不 `SetActive(false)` ⇒ 第 4 条红；
        //   ③ `SetupAutoZoom` 里不接 `ToggleResetCameraZoomUi` ⇒ 第 5/6 条红（钮永不出现）；
        //   ④ 命中区拿 `ImageQuad.Contains`（画出来的 61.846）顶替原版那个**外扩后的 80.443×77.846** ⇒ 第 7 条红；
        //      🔴 **2026-10-18（A964 前置）订正**：本行原来写的是「……顶替原版那个 48.443×45.846」—— 那是**错值**
        //      （`m_RaycastPadding` 的负值 = **外扩**，不是「往里缩」；判据见 `BattleDriver.CameraResetHitPxW` 上面那段）。
        //   ⑤ 点击不 Invoke 那条 `Action`（自己另写一次重算）⇒ 第 8 条红。
        {
            Check(driver.CameraResetButtonBuilt && driver.CameraResetButtonArt == "40k_UI_bt_center_camera",
                  $"★ A423：HUD 上那颗「重置自动镜头」钮建出来了，而且就是原版那张图"
                + $"（原版 `BattleHud.resetCameraZoomButton`(+0xa8) / 节点 `CenterCameraButton` / sprite `40k_UI_bt_center_camera`；"
                + $" 实得 `{driver.CameraResetButtonArt}`）");
            var bd423 = driver.CameraResetButtonDrawnPx;
            // 🔴 **2026-10-19（`T09` A2）就地订正**：`sizeDelta` 已按原版改回**节点 rect 64.443×61.846**
            //   （A2 要照抄 `m_RaycastPadding`，基准是节点 rect ⇒ 见 `T09` 计划 §1·6 / R2）。
            //   `CameraResetButtonDrawnPx` 读的是 `sizeDelta` ⇒ 现在回的是**节点 rect**；
            //   「画出来多大」由 `Image.preserveAspect` 决定（原版 `m_PreserveAspect = 1` ⇒ 内接 61.846²）。
            var img423 = driver.HudButtonPieceForTest("cameraReset") != null
                       ? driver.HudButtonPieceForTest("cameraReset").gameObject.GetComponent<Image>() : null;
            Check(Mathf.Abs(bd423.x - 64.4429931640625f) < 0.01f
               && Mathf.Abs(bd423.y - 61.84600830078125f) < 0.01f
               && img423 != null && img423.preserveAspect,
                  $"★ A423：那颗钮的 `sizeDelta` = **原版节点 rect 64.443×61.846**、且 `preserveAspect = true`"
                + $"（实得 {bd423.x:F4}×{bd423.y:F4} · PA={(img423 != null ? img423.preserveAspect.ToString() : "<无 Image>")}）"
                + " —— 原版 `m_PreserveAspect = 1` ⇒ 画出来是**内接**的 61.846×61.846（由 `Image` 自己算）"
                + "；🧨 改坏法：把 `preserveAspect` 关掉 ⇒ 按 64.443×61.846 拉伸（横向 +4.2%）");

            // 几何：px 原值（判据 = `RectTransform_3487` 的 `anchoredPosition (0.150757, −59.097)`
            //   + 父 `Left Anchor` 那宽 100 的整列 ⇒ 中心在 1920×1080 画布上的 **(50.1508, 599.097)** 处
            //   —— y **从上往下**数（即 `HudAbs` 的口径），换算成 `HudAbs` 的左上角口径 = **(17.9293, 568.174)**）。
            //   🔴 **2026-10-12 订正（A423 收红那轮）**：这句原来把画布中心写成 `(50.1508, 480.903)` ——
            //     **值对、标签错**：`480.903 = 1080 − 599.097` 是**翻转后**的那个数，而 `LayoutSpace.ToWorld`
            //     的 `y01`（相对可见区、y 从**下**）收的恰好就是它（`BattleDriver.HudAbs` 里
            //     `cy = 1 − (y + h/2)/1080`）⇒ 下面 `480.903f / 1080f` **一个字都不能改**，
            //     改了文案就够（照 480.903 去「修」代码会把方向改反）。
            //   期望值 = 原版字面量换算出来的（⛔ 不读 `BuildHud` 传的那几个数）。
            //   ⚠️ 过 `hudRoot.TransformPoint` 与建它那一路**逐字同一条换算**（`ImageQuad.Create` 写的也是
            //     `root` 下的 `localPosition`）⇒ 不假设 `HudRoot` 自己在原点。
            {
                Vector3 want423 = driver.hudRoot != null
                    ? driver.hudRoot.TransformPoint(LayoutSpace.ToWorld(50.1508f / 1920f, 480.903f / 1080f))
                    : LayoutSpace.ToWorld(50.1508f / 1920f, 480.903f / 1080f);
                var d423 = driver.CameraResetButtonWorldPos - want423;
                Check(Mathf.Abs(d423.x) < 1e-4f && Mathf.Abs(d423.y) < 1e-4f,
                      $"★ A423：那颗钮落在**原版那个位置**上（中心 = `LeftAnchor` 中心 + (0.150757, −59.097) px"
                    + $" ⇒ 画布 (50.1508, 599.097)，y 从上往下数）—— 实得偏 ({d423.x:F4}, {d423.y:F4}) 世界单位"
                    + "（阈值 1e-4 世界单位 ≈ 0.011 px；同一件在 16 那一节还有一条「中心 ≈ (50.15, 599.1)」的粗口径）"
                    + " —— 🧨 改坏法：`BattleDriver.BuildHudExtras` 里那四个 px 写成取整值"
                    + "（`17.9 / 568.2 / 64.44 / 61.85`）⇒ 中心偏 0.0308 / 0.028 px = 2.9e-4 / 2.6e-4 世界单位"
                    + " ⇒ 本条红（2026-10-12 之前就是这个状态）");
            }

            Check(!driver.CameraResetButtonVisible,
                  "★ A423：**开局它是关着的**（原版 `BattleHud.Initialize` 里那句 `SetActive(false)`）"
                + " —— 建完不关（让它一直亮着）这一条就红");
            Check(driver.CameraResetHookWired,
                  "★ A423：显隐钩子接上了（原版 `BattleHud.ToggleResetAutoCameraZoom` 那一条 = "
                + "`BattleDriver.SetupAutoZoom` 里接的 `ToggleCameraResetZoomUi`）—— 不接的话那三处只会出声、钮永不出现");
            Check(!driver.CameraResetButtonHit(driver.CameraResetButtonWorldPos),
                  "★ A423：**关着的时候点不着**（原版 `SetActive(false)` 的节点收不到射线）");

            // 走**真那条路**让它出现：原版 `CombatCameraZoom.LateUpdate` 里
            //   `if (ScrollDelta != 0 || TouchPressedSecondary) BattleHud.Instance.ToggleResetAutoCameraZoom(allowManualControl);`
            var cz423 = driver.AutoZoom != null ? driver.AutoZoom.CameraZoomForTest : null;
            if (cz423 == null)
            {
                Check(false, "★ A423：拿不到 `CombatCameraZoom` ⇒ 「玩家一动镜头 ⇒ 钮出现」那两条验不了");
            }
            else
            {
                cz423.ToggleAllowManualControl(true);
                cz423.ManualCamera = false;
                cz423.PointerOverUi = () => false;
                cz423.FocusedOverride = true;
                cz423.PointerViewportOverride = new Vector2(0.5f, 0.5f);
                int punch423 = driver.CameraResetPunchCount;
                cz423.InjectPointerSource(+1f, false, Vector2.zero);      // 滚一格
                cz423.TickInjected(0.02f);
                Check(driver.CameraResetButtonVisible && cz423.ManualCamera,
                      "★ A423：**玩家一滚轮 ⇒ 那颗钮就出现**，而且镜头进了手动档"
                    + $"（原版同一条 `if` 里两句挨着：`ToggleResetAutoCameraZoom(allowManualControl)` + `manualCamera = allowManualControl`；"
                    + $" 实得 显示 {driver.CameraResetButtonVisible} · manualCamera {cz423.ManualCamera}）");
                Check(driver.CameraResetPunchCount == punch423 + 1,
                      $"★ A423：出现那一下**弹了一次**（原版 `DOPunchScale(Vector3.one × 0.2, 0.5s, vibrato 10, elasticity 1.0)`；"
                    + $" 计数 {punch423} → {driver.CameraResetPunchCount}）");

                // 命中区 = 原版那个**带 `m_RaycastPadding` 的**矩形，⛔ 不是画出来的 61.846 正方形。
                // 🔴 **2026-10-18（A964 前置）就地订正（铁律 5）**：UGUI 里 **负 padding = 外扩**，不是「往里缩」
                //   ⇒ 真值 = rect(64.443×61.846) 四边各向外 +8 = **80.443 × 77.846**
                //   （`BattleDriver.CameraResetHitPxW/H` 同源、现算不写死）。本段原来钉的是**错的 48.443×45.846**，
                //   判别式取「偏中心 25 px ⇒ 打不中」（25 > 错半宽 24.2215，所以它当时是绿的）—— **那条钉的是错值**，一起重写。
                //   符号判据（两点独立出处：官方单测 `GraphicRaycasterTests.cs:82-101` + 官方 editor gizmo `GraphicEditor.DrawRect`）
                //   → `BattleDriver.CameraResetHitPxW` 上面那段。
                var c423 = driver.CameraResetButtonWorldPos;
                Check(driver.CameraResetButtonHit(c423),
                      "★ A423：钮中心那一击**打得中**（真实输入与自检走同一条判定）");
                // ---- 判别式（两态 · 半边 A：命中区比 rect 本身**宽**）----
                // 现算：rect 半宽 = 64.4429931640625 / 2 = **32.22150**；
                //      外扩后半宽 = (64.4429931640625 + 8 + 8) / 2 = **40.22150**；
                //      y 向同带 = [30.92300, 38.92300]（61.84600830078125 / 2 · +16 / 2）。
                // 取 **36 px**：在 rect **外** 3.78 px、在命中区**内** 4.22 px —— 两轴都在同一个带里（36 < 38.923）
                // ⇒ 一条断言同时管 x、y 两向。**只有「外扩」这一种读法会绿**（错符号 24.2215、无 padding 32.2215、
                // 画出来的 30.923，三个都 < 36）。
                float in423 = 36f / 108f;               // px → 世界（本件 scale 1，与 `Px()` 同一条换算）
                Check(driver.CameraResetButtonHit(c423 + new Vector3(in423, 0f, 0f))
                   && driver.CameraResetButtonHit(c423 + new Vector3(0f, in423, 0f)),
                      "★ A423：偏中心 **36 px**（x、y 各一次）那一点**打得中** —— 原版 `Image.m_RaycastPadding = (−8,−8,−8,−8)`"
                    + " 的**负值 = 往外扩** ⇒ 命中矩形 = rect 四边各 **+8** = **80.443×77.846**（半宽 40.2215 · 半高 38.9230）"
                    + " ⇒ 36 px 那一点落在**矩形之外（半宽只有 32.2215）、命中区之内**"
                    + "｜🧨 改坏法：① `CameraResetHitPxW/H` 写回旧口径「往里缩」（`Rect − 16`）⇒ 半宽 24.2215 < 36 ⇒ 红；"
                    + "② 干脆不外加 padding（= rect 本身）⇒ 半宽 32.2215 < 36 ⇒ 红；"
                    + "③ 拿画出来的 `ImageQuad.Contains`（61.846² ⇒ 半宽 30.923）顶替 ⇒ 同样红");
                // ---- 判别式（两态 · 半边 B：命中区**有界**）· 与 A 配对即【灭自证】----
                // A 要求半宽 ≥ 36、B 要求半宽 < 44 —— 这两条**结构上不可能被同一个错实现同时满足**：
                //   · 错符号给 24.2215 ⇒ A 红；
                //   · 「不设界 / 拿画出来的矩形硬撑」给不出「≥36 且 <44」这个窗口 ⇒ 必有一条红。
                // ⛔ 而且这两条用的 36 / 44 是**从原版字段现算的**（rect 64.443 + padding 8×2），
                //    ⛔ 不读 `BattleDriver` 那两个常量 ⇒ 把实现与判别式「一起改回旧写法」不会全绿。
                float out423 = 44f / 108f;              // 44 > 半宽 40.2215、也 > 半高 38.9230 ⇒ 两轴都该落空
                Check(!driver.CameraResetButtonHit(c423 + new Vector3(out423, 0f, 0f))
                   && !driver.CameraResetButtonHit(c423 + new Vector3(0f, out423, 0f)),
                      "★ A423：偏中心 **44 px**（x、y 各一次）那一点**打不中** —— 命中区是**有界**的"
                    + "（外扩后半宽 40.2215 · 半高 38.9230，44 px 两边都超）"
                    + "｜🧨 改坏法：把 `CameraResetButtonHit` 的界去掉（恒 `return true`，或 padding 取成 ≥ 44 px）⇒ 本条红");

                // 点它 ⇒ 原版那条链：`BattleHud.DoResetCameraZoom()` → Invoke `ResetCameraZoom`(+0xc0)
                //   → `CombatAutoZoom.ResetCameraZoomUIAction()` → `SetZoomLevel(Max(敌,我), force:true)`
                //   ⇒ 清手动档 + 重算取景 + **把本钮自己收起来**。
                int apply423 = driver.AutoZoom.FramingApplyCount;
                bool ok423 = driver.ResetCameraZoomClick();
                Check(ok423 && !cz423.ManualCamera && !driver.CameraResetButtonVisible
                   && driver.AutoZoom.FramingApplyCount > apply423,
                      $"★ A423：点它 ⇒ 镜头**被重置**（手动档清掉 {cz423.ManualCamera} · 钮收回 {driver.CameraResetButtonVisible} ·"
                    + $" 取景重算了 {apply423} → {driver.AutoZoom.FramingApplyCount}）"
                    + " —— `force:true` 那一支不调 `RaiseToggleResetCameraZoomUi(false)` 钮就收不回去 ⇒ 红");

                // ---- 🆕 2026-10-18（A964 前置）：`HudButton*ForTest` 那一族补上 `"cameraReset"` 档 ----
                //   那颗钮是**全 HUD 唯一出厂就 `SetActive(false)`** 的（`BuildHudExtras` 建完立刻关）
                //   ⇒ A964 的探针只能走这张键表拿它（「等它可见了再取坐标」那条路走不通）。
                //   ⚠️ 本段之前**零断言** —— `HudButtonWorldPosForTest("cameraReset")` 原来**根本没有这一档**。
                var wp423 = driver.HudButtonWorldPosForTest("cameraReset");
                Check(wp423 == driver.CameraResetButtonWorldPos,
                      $"★ A964 前置：`HudButtonWorldPosForTest(\"cameraReset\")` 指的就是那颗钮"
                    + $"（与 `CameraResetButtonWorldPos` 同一点 —— 实得 ({wp423.x:F5}, {wp423.y:F5}, {wp423.z:F5})）"
                    + "｜🧨 改坏法：把那一档从 switch 里删掉 / 键名写错 ⇒ `q` 留 null ⇒ 返回 `Vector3.zero` ⇒ 本条红"
                    + "（注意此刻那颗钮**是关着的**，所以这一条同时证明「关着的钮也取得到坐标」）");
                // 灭自证：键表必须**真在分派** —— 给一个不存在的键必须回 `Vector3.zero`。
                Check(driver.HudButtonWorldPosForTest("__no_such_button__") == Vector3.zero,
                      "★ A964 前置（灭自证）：给一个**不存在的键**返回 `Vector3.zero` —— "
                    + "🧨 若把函数写成「无视 `which`、恒返回 `_cameraResetBtn`」，上一条与本条会**一起绿** ⇒ 本条专门挡那一手"
                    + "（2026-10-18 实测：本函数**没有 `default` 分支**，未知键天然落 `q == null`）");
                // 显隐那一档：`SetHudButtonActiveForTest` **只 `SetActive`、不起 tween**。
                int punchBefore423 = driver.CameraResetPunchCount;
                Check(!driver.CameraResetButtonVisible && driver.SetHudButtonActiveForTest("cameraReset", true)
                   && driver.HudButtonActiveForTest("cameraReset") && driver.CameraResetButtonVisible,
                      "★ A964 前置：`SetHudButtonActiveForTest(\"cameraReset\", true)` ⇒ 它真的亮了（**两态**：之前是关着的）"
                    + " —— `HudButtonActiveForTest` 与 `CameraResetButtonVisible` 同时翻过来");
                Check(driver.CameraResetPunchCount == punchBefore423,
                      $"★ A964 前置：摆状态**不起 tween**（`DOPunchScale` 计数 {punchBefore423} 不动）"
                    + "｜🧨 改坏法：把 `SetHudButtonActiveForTest` 改成走 `ToggleCameraResetButton` ⇒ 计数 +1 ⇒ 本条红"
                    + "（那还会 `DOTween.Kill` 掉生产里正在播的那一下）");
                Check(driver.SetHudButtonActiveForTest("cameraReset", false) && !driver.HudButtonActiveForTest("cameraReset"),
                      "★ A964 前置：再 `false` ⇒ 它收回去（收尾时留下的就是这一步，与本段开头同一个状态）");
                Check(!driver.SetHudButtonActiveForTest("__no_such_button__", true),
                      "★ A964 前置（灭自证）：未知键**什么都不做**、返回 false（⛔ 不静默造一颗钮出来；"
                    + "若写成「找不到就兜 `_cameraResetBtn`」⇒ 本条红）");

                // 收尾：开关放回关、取景回到不缩放那一档（同 A175 那一段的收尾口径），
                //   并把那三个自检口放开（不让它们留在生产语义上）
                AutoZoom.RestoreForTest(false, false);
                driver.AutoZoom.ForceRefresh();
                cz423.FocusedOverride = null;
                cz423.PointerViewportOverride = null;
                cz423.PointerOverUi = null;
            }
        }

        // ---------------- 🆕 2026-10-12（A388，W4 备好的原文照贴）：离场把静态钩子摘干净 ----------------
        // ⚠️ **本段测的是「摘」这个方法本身**（`DetachStaticHooks` + `StaticHookCount` 两个自检口）。
        //    🔴 **把 `OnDestroy` 里那句 `DetachStaticHooks();` 删掉，本段(a)照样全绿** ⇒ 「`OnDestroy` 有没有调它」
        //    这半**只能靠代码审查**（`BattleDriver.OnDestroy` 里就一句，`Editor` 侧看一眼即可）——
        //    **如实记，不假称验过**；下面 (b) 那半（真 `DestroyImmediate`）能盖住「生命周期没走到」那一类。
        // 🆕 **2026-10-13（A515）**：这个基线提到块外 —— 下面 (b) 段要拿它当**同一次运行的基线**
        //   （断言 = 「二次 `Begin()` 接回的条数 == 首次 `Begin()` 之后的条数」）。
        //   🔴 **为什么不能写死 19**：那 19 槽里 `WFModulePostProcess.OnPostFx` 只在「载进来的战场
        //   prefab 里有 `Volume`」时挂得上（`AttachPostFx` 取不到 Volume 就**出声并保持 null**）
        //   ⇒ 换个环境它可能少一条，写死数会把那种环境误报成红。用同一次运行的实测基线就没有这个问题。
        int hookedBefore388 = BattleDriver.StaticHookCount;
        {
            // 🔴 **2026-10-14（A532）给下面那个 `16` 补出处**：`Begin()` 之后 **现读是 19 条**
            //   （`Unity/_tmp_view/battle.log:39110` 逐字：「A388：开局后静态钩子挂着 19 条」——
            //    与上面 A515 那段注释里说的「那 19 槽」一致）。这里写 **16 只是下限**、**故意不写 19**，
            //   理由见上一段：`AttachPostFx` 取不到 `Volume` 时 `OnPostFx` 会**保持 null**
            //   ⇒「钩子数」是**环境相关**的，写死真值会把「换了个战场 / 换了个环境」误报成红。
            //   （原来那个 16 离真值更远，读起来更像「实测值」，所以补这一句把它标成下限。）
            // 🔑 **通则（以后写这类断言一律照它）**：先问「这一组数是**谁挂的**、有没有哪个挂点**带条件**」——
            //   只要有一个带条件（这里是 `Volume`），就 ⛔ **别写死数**：要么用**同一次运行的基线**
            //   （如 A515 的 `hookedBeforeB == hookedBefore388`），要么用**下限 + 点名那几条环境无关的**
            //   （如紧下面那条「账上点名的三条在」）。出处 = `资料/普查产出_1013/批次计划_1013.md` §六·B（A532）。
            Check(hookedBefore388 >= 16,
                  $"A388：开局后静态钩子挂着 {hookedBefore388} 条"
                + "（挂点 = `HookAnimFxShake/Cards` · `BuildHud` 的两个补间口 · 后期 · 录像）");
            Check(WarpforgeVFX.WFEffectCards.Resolver != null
                  && WarpforgeVFX.WFModuleCollisions.ColliderLookup != null
                  && WarpforgeVFX.WFModuleScaleByTarget.MinionLines != null,
                  "A388：账上点名的那三条在（`WFEffectCards.Resolver` / `Collisions.ColliderLookup` / `ScaleByTarget.MinionLines`）");
            int removed388 = driver.DetachStaticHooks();
            Check(removed388 == hookedBefore388 && BattleDriver.StaticHookCount == 0,
                  $"★ A388：离场把静态钩子**摘干净**（摘前 {hookedBefore388} → 摘掉 {removed388} → "
                + $"现存 {BattleDriver.StaticHookCount}）—— 旧代码一条都不摘（现存 ≥ 3，场景重载后还指着已销毁的 driver）");
            Check(WarpforgeVFX.WFEffectCards.Resolver == null
                  && WarpforgeVFX.WFModuleCollisions.ColliderLookup == null
                  && WarpforgeVFX.WFModuleScaleByTarget.MinionLines == null,
                  "★ A388：账上点名的那三条也在其中（都成 null 了）");
            // ⚠️ 这一段**会把钩子摘光**（上面 A175 那一段已经用完 VFX 了，所以放在它之后没问题）；
            //    若将来还要在这之后用 VFX，得先 `driver.Begin(...)` 把这一场接回来。
        }

        // ---------------- 🆕 2026-10-12（A388 的 b 半）：**真卸载**那一路（更硬）----------------
        // 🔴 为什么在 `CheckSavedScene` **之前**（W4 原文说「放整轮自检的最后」—— 这里必须把它读准）：
        //    `CheckSavedScene` 里第一句就是 `EditorSceneManager.OpenScene(...)`，那会把**当场建的**这份场景
        //    整个卸掉 ⇒ 之后 `driver` 已经没了（本条要的 `driver.Begin(...)` 与 `DestroyImmediate(driver)`
        //    两件都做不到）。所以「整轮的最后」= **打开存档场景之前**。
        //    ⚠️ **2026-10-12 订正**：这里原来还写着「⇒ `driver` 的 `OnDestroy` **已经跑过了**
        //    （`StaticHookCount` 早就是 0）⇒ 再断一次就是**恒真的假断言**」—— **那个前提是错的**
        //    （编辑模式不派 `OnDestroy`，判据见下面 (b) 段）：放它之后**不会**恒真，而会**红**。
        //    结论不变，理由是上面那句。
        {
            // 🔴 **先把这一场接回来，否则这一条是恒真的假断言**：上面 (a) 已经把计数清成 0
            //    ⇒ 不接回来就是「0 → 销毁 → 还是 0」，什么都没验。`Begin()` 里会重新挂
            //    `HookAnimFxShake/HookAnimFxCards` 那一串（W4 §三 的注脚也是这么写的）。
            driver.Begin("Ultramarines", "Goff", 20260915);
            if (driver.InMulligan) driver.SimulateMulliganDone();
            // 🆕 2026-10-19（战斗线 W）：**先把开局/换牌那一批演出排空**。
            //   批处理没有帧循环 ⇒ 那批事件不会自己演完；而 W 段新加的
            //   `WaitingForBlockingAction` 闸会让 `DrivePlayerTurnForTest`（走玩家那条 `fromUi` 路）
            //   在下面 A462 的「悬停即选中」处被挡下。这不是 A462 要验的东西 ⇒ 这里显式推完。
            //   ⚠️ 后面 A462 全程只做白盒摆盘 + `RefreshAll`（不产生新事件），所以推这一次就够。
            StepThrough(driver);
            { int wgA462 = 0; while (driver.WaitingForBlockingAction && wgA462++ < 400) Step(1f / 30f); }
            // ⬇⬇ 2026-10-14（#9 · A462 搬家）：这一段原来在整轮末尾（`DestroyImmediate(driver)` **之后**）
            //    ⇒ 进段时 `Object.FindObjectOfType<BattleDriver>()` 恒为 null（**前提不成立**）⇒ 整段一条都验不了。
            //    搬到这儿（`driver.Begin(...)` + `SimulateMulliganDone()` 之后）：driver 活着、HUD 已建、开局已走完。
            //    ⚠️ 本段自己 try/finally 收尾、**一处 `Hook*` 调用都没有**（只用 `FindObjectOfType` 与 `RefreshAll()`；
            //    挂/摘静态钩子的口只在 `BattleDriver.Begin()` / `DetachStaticHooks()` 里）⇒ 下面 `hookedBeforeB` 不受影响。

            // ---------------- 🆕 2026-10-13（A462 + A658）：输入的【两条沿】· 选择器的入场驱动量 ----------------
            // 逐处判据（15 处代码调用，一处一档）→ `资料/普查产出_1013/WA462_输入入口分类.md` §三 / §四。
            // 组件级判据（悬停那三格状态机）→ `d:/2/tools/decomp_full/`：
            //   `CardDisplayAttackTypeButton__{Update,Toggle,MoveButton}.c` +
            //   `...__UnityEngine.EventSystems.IPointerEnter/ExitHandler.{OnPointerEnter,OnPointerExit}.c` +
            //   `..._<StartSafeTouch>d__37__MoveNext.c` · `AttackTypesButtonsController__{MoveButtons,OnEnable}.c`
            // uGUI 那一侧的**根判据**（本机自带源码 `com.unity.ugui`）：
            //   `UI/Core/Button.cs:110-116`（`OnPointerClick` → `m_OnClick`）·
            //   `UI/Core/Selectable.cs:1201-1212`（`OnPointerDown` **不**触发 `onClick`）·
            //   `EventSystem/InputModules/StandaloneInputModule.cs:208-217`（`IPointerClickHandler` 在
            //   `ReleaseMouse()` = 松手那一帧里执行）· `EventSystem/EventTriggerType.cs:24`（`PointerDown = 2`）
            // 🧨 主改坏法（逐条附在断言上）：① 两条沿合并回一个「按下沿」latch；
            //   ② 悬停那条去掉 0.1s 安全窗；③ `_pressCaptured` / `_swallowNextRelease` 删掉
            //   （滑块拖完 / 模态被按下关掉之后会**穿透**）；④ 入场动画改回按时间驱动。
            {
                var wb4 = Object.FindObjectOfType<BattleDriver>();
                Check(wb4 != null, "★ A462：（前提）场上有一台 `BattleDriver` —— 两条沿的判据全挂在它身上");
                if (wb4 != null)
                {
                    // 收尾状态（本段动过的东西一律放回去）
                    var sp4 = wb4.Settings;
                    bool spWasOpen4 = sp4 != null && sp4.Visible;
                    bool azWas4 = AutoZoom.Enabled, azChosen4 = AutoZoom.ChosenManually;
                    try
                    {
                        // ============================================================
                        //  一、两条沿本身（12 处「改抬起」共用的那**一个**机制）
                        // ============================================================
                        // 手法：`PointerHeldForTest` 钉死「按住 / 松手」，`PollInputEdgesForTest()`
                        //       走一次「一帧」。⚠️ 批处理里 `Mouse.current == null` ⇒ 不钉死的话
                        //       `PointerHeld()` 恒 false、**两条沿一条都验不了**。
                        BattleDriver.PointerHeldForTest = true;
                        wb4.PollInputEdgesForTest();                      // 第 1 帧：按下
                        Check(!wb4.ReleasedThisFrameForTest(),
                              "★ A462：（按下那一帧）**不给松手沿** —— 12 处改抬起之后，按住那一下不许触发"
                            + "（改坏法：把 `_upEdge` 换成「按住」⇒ 这条红）");
                        Check(wb4.ClickedThisFrameForTest(),
                              "★ A462：（同一帧）按下沿照旧给 —— `ClickedThisFrame` 的语义一个字没改");
                        Check(!wb4.ClickedThisFrameForTest(),
                              "★ A462：按下沿**一次按住只给一次**（原来的 latch 语义；改坏法：去掉 `_downEdge = false`）");

                        wb4.PollInputEdgesForTest();                      // 第 2 帧：还按着
                        Check(!wb4.ClickedThisFrameForTest() && !wb4.ReleasedThisFrameForTest(),
                              "★ A462：（按住不放的第 2 帧）**两条沿都不给** —— 按住不放不会每帧触发");

                        BattleDriver.PointerHeldForTest = false;
                        wb4.PollInputEdgesForTest();                      // 第 3 帧：松手
                        Check(!wb4.ClickedThisFrameForTest(),
                              "★ A462：（松手那一帧）**不给按下沿** ← 这就是「按下 vs 抬起」两态的分界线");
                        Check(wb4.ReleasedThisFrameForTest(),
                              "★ A462：（松手那一帧）**给松手沿** ← 12 处改的就是它");
                        Check(!wb4.ReleasedThisFrameForTest(),
                              "★ A462：松手沿**一次按住只给一次**（改坏法：去掉 `_upEdge = false`）");
                        wb4.PollInputEdgesForTest();                      // 第 4 帧：还松着
                        Check(!wb4.ReleasedThisFrameForTest(),
                              "★ A462：松手之后**不会补出第二次松手沿**（边沿是帧的状态、不滞留）");

                        // ============================================================
                        //  一·b、`ClickLog`：**两条沿各记一次**（用户 2026-09-24 要的「真实点击记录」）
                        //     判据 = 纪律 1：`ClickedThisFrame` 原来兼着 `ClickLog.Begin/Hit`，
                        //     改沿时**两支都要记**，否则改到抬起的 12 处**一条记录都不会有**。
                        //     ⚠️ 探针写 `_tmp_view/battle/` 下的临时文件（⛔ 不碰玩家那份真日志），
                        //        做法同 `Editor/ShellScene.cs` 的 `Run` 里那处 `DeckStore.OverridePath` → `_tmp_view` 的写法。
                        // ============================================================
                        {
                            var probePath4 = Path.Combine(OutDir, "_wb4_click_probe.txt");
                            if (File.Exists(probePath4)) File.Delete(probePath4);
                            ClickLog.OverridePath = probePath4;
                            BattleDriver.PointerWorldForTest = Vector3.zero;
                            BattleDriver.PointerHeldForTest = true;
                            wb4.PollInputEdgesForTest();
                            wb4.ClickedThisFrameForTest();
                            ClickLog.End();
                            string blkDown4 = ClickLog.LastBlock ?? "";
                            BattleDriver.PointerHeldForTest = false;
                            wb4.PollInputEdgesForTest();
                            wb4.ReleasedThisFrameForTest();
                            ClickLog.End();
                            string blkUp4 = ClickLog.LastBlock ?? "";
                            ClickLog.OverridePath = null;
                            Check(blkDown4.Contains("来源 BattleDriver"),
                                  "★ A462：**按下沿**那一下进了「真实点击记录」（`ClickLog.Begin/Hit` 还在）");
                            Check(blkUp4.Contains("来源 BattleDriver"),
                                  "★ A462：**松手沿**那一下**也**进了同一份记录"
                                + "（改坏法：只在按下那一支调 `ClickLog` ⇒ 改到抬起的 12 处全都查不到记录，"
                                + "而画面看上去一切正常 = 典型静默）");
                        }

                        // ============================================================
                        //  二、`_pressCaptured`：被滑块接住的这一次按住，松手那一帧**不算点击**
                        //     （原版 uGUI 靠 `StandaloneInputModule.ProcessDrag` 把 `eligibleForClick`
                        //      清掉来做同一件事 —— 拖完滑块不许顺带按到别的钮）
                        // ============================================================
                        if (sp4 != null)
                        {
                            sp4.Show();
                            var ms4 = sp4.SliderAt(0);
                            Check(ms4 != null, "★ A462：（前提）设置面板上第 1 根滑块在（不然下面这条等于没验）");
                            if (ms4 != null)
                            {
                                // 探针取**手柄当前的位置**（一定是命中区里的一点）；值可能被这一按挪动，
                                // 收尾用 `SetValue(..., fire:false)` 放回去（同 14c 那组的做法）。
                                // 🔴 **2026-10-20（W57 · `T09` A3-b2 收口）就地订正（铁律 5）**：本段原来写
                                //   「**滑块**接住了这一按」—— A3-b2 之后 `SettingsPanel.PointerFrame` 是
                                //   **整扇面板的模态接管**（面板开着 ⇒ 任何按下都返回 true；滑块自己的输入已归
                                //   `WfSlider` 的 uGUI 事件），不再按「点在不在滑块上」分档。
                                //   `_pressCaptured` 要挡的那件事**不变**：面板开着时按下、松手不许算成一次点击。
                                float mv0 = ms4.Value;
                                BattleDriver.PointerWorldForTest = ms4.HandleWorldPos;
                                BattleDriver.PointerHeldForTest = true;
                                wb4.PollInputEdgesForTest();
                                wb4.TickSettingsInputForTest();            // 按下：被面板的模态接管
                                Check(wb4.PressCapturedForTest,
                                      "★ A462：（前提）面板开着 ⇒ 这一次按住被**模态接管**（`PressCapturedForTest`）"
                                    + " —— `T09` A3-b2 起 `PointerFrame` 对**任何**按下都返回 true，不再只认滑块");
                                BattleDriver.PointerHeldForTest = false;
                                wb4.PollInputEdgesForTest();
                                wb4.TickSettingsInputForTest();            // 松手
                                Check(!wb4.ReleasedThisFrameForTest(),
                                      "★ A462：被面板接管的这一次按住 —— **松手那一帧不算点击**"
                                    + "（改坏法：删掉 `_pressCaptured` ⇒ 关窗途中/拖完音量条会在松手那一下顺带点掉别的钮）");
                                ms4.SetValue(mv0, false);                  // 还原（不 fire）
                            }
                            sp4.Hide();
                        }

                        // ============================================================
                        //  三、设置钮 / 设置面板里那颗 Auto Zoom：#5 #6（按下不动、松手才动）
                        // ============================================================
                        if (sp4 != null)
                        {
                            sp4.Hide();
                            BattleDriver.PointerWorldForTest = wb4.HudButtonWorldPosForTest("settings");
                            Check(wb4.HudButtonWorldPosForTest("settings") != Vector3.zero,
                                  "★ A462：（前提）拿得到设置钮的世界坐标（拿不到 `WorldPointer()` 就压不着它）");
                            BattleDriver.PointerHeldForTest = true;
                            wb4.PollInputEdgesForTest();
                            wb4.TickSettingsInputForTest();
                            Check(!sp4.Visible,
                                  "★ A462：设置钮**按下那一帧不弹面板**"
                                + "（原版 `BattleHud.settingsButton` = `EverguildButton`，`BattleHud__Awake.c:48-55` 绑 `m_OnClick`）"
                                + " —— 🔴 2026-10-19（`T09` A2）起那颗钮走 uGUI：按下帧本来就没有任何派发");
                            BattleDriver.PointerHeldForTest = false;
                            wb4.PollInputEdgesForTest();
                            // 🔴 **2026-10-19（`T09` A2）**：设置钮已走 uGUI ⇒ 松手那一帧的「点击」
                            //   由 `BattleHudButton` 派发（与 `EventSystem` 的 `IPointerClickHandler` 同一跳）；
                            //   手搓的 `TickSettingsInputForTest` 现在**只剩面板开着那条模态支**、关着恒 false。
                            wb4.ClickHudButtonForTest("settings");
                            Check(sp4.Visible,
                                  "★ A462：……**松手那一帧才弹**（uGUI `IPointerClickHandler` = 抬起；"
                                + "改坏法：把 `ClickSettingsHud` 挪到 `OnPointerDown` / 手搓回按下沿 ⇒ 前一条红）");

                            // 面板里那颗 `Auto Zoom`（原版 `EverguildToggle` ⇒ `IPointerClickHandler`）
                            Check(sp4.AutoZoomRowBuilt, "★ A462：（前提）`Auto Zoom` 那一行建出来了（不然下面两条等于没验）");
                            bool az0 = AutoZoom.Enabled;
                            sp4.ResetClickCountForTest("Auto Zoom Toggle");
                            int az4a = sp4.ClickCountForTest("Auto Zoom Toggle");
                            BattleDriver.PointerWorldForTest = sp4.AutoZoomBoxWorldPos;
                            BattleDriver.PointerHeldForTest = true;
                            wb4.PollInputEdgesForTest();
                            wb4.TickSettingsInputForTest();
                            Check(AutoZoom.Enabled == az0 && sp4.ClickCountForTest("Auto Zoom Toggle") == az4a,
                                  $"★ A462：面板里那颗 `Auto Zoom` —— **按下那一帧不翻**（实得 {AutoZoom.Enabled}，期望还是 {az0}；"
                                + $"uGUI 计数仍 {az4a}）");
                            BattleDriver.PointerHeldForTest = false;
                            wb4.PollInputEdgesForTest();
                            wb4.TickSettingsInputForTest();
                            // 🔴 **2026-10-20（W57 · `T09` A3-b2 收口）就地订正（铁律 5）**：本行原来断
                            //   「**松手那一帧才翻**」—— 那走的是 `SettingsClickAt` 手搓链；A3-b2 之后它在
                            //   **产线上不可达**（按下被 `PointerFrame` 的模态接管吃掉 ⇒ 松手沿恒不成立）。
                            //   现在拆成两条（判别力更强，且各指一种改坏法）：
                            //   ① 手搓的松手那一帧**不翻**（挡住「把那颗钮的动作接回手搓链」）；
                            //   ② uGUI 的**点击那一跳**才翻（`IPointerClickHandler` = 抬起，与真鼠标同一条链）。
                            Check(AutoZoom.Enabled == az0 && sp4.ClickCountForTest("Auto Zoom Toggle") == az4a,
                                  $"★ A462：……**松手那一帧手搓链也不翻**（实得 {AutoZoom.Enabled}；"
                                + "`SettingsClickAt` 在 `T09` A3-b2 之后产线上不可达）");
                            sp4.ClickForTest("Auto Zoom Toggle");        // = EventSystem 在抬起那帧派发的 IPointerClick
                            Check(AutoZoom.Enabled != az0 && sp4.ClickCountForTest("Auto Zoom Toggle") == az4a + 1,
                                  $"★ A462：……**uGUI 的点击那一跳才翻**（实得 {AutoZoom.Enabled}；"
                                + $"计数 {az4a} → {sp4.ClickCountForTest("Auto Zoom Toggle")}）"
                                + " —— 与 Resign/Close 同一条 `BattleHudButton` 链（Difficulty 那颗 2026-10-22 已删）");
                            AutoZoom.RestoreForTest(azWas4, azChosen4);         // 内存态放回去（本段全程 PersistOverride）
                            sp4.Hide();
                        }

                        // ============================================================
                        //  四、`#11` 与 `#12`：**同一次实验里两条沿并存**（日志面板 / 日志钮）
                        //     · 关面板 = 按下沿（原版 `shade` 的 `EventTrigger`，`eventID 2 = PointerDown`）
                        //     · 开面板 = 松手沿（原版 `ShowCemeteryBtn` = `EverguildButton`）
                        // ============================================================
                        var log4 = wb4.BattleLog;
                        Check(log4 != null, "★ A462：（前提）战斗日志面板建出来了");
                        if (log4 != null)
                        {
                            if (log4.Visible) log4.Hide();
                            var cemeteryW = wb4.HudButtonWorldPosForTest("cemetery");
                            BattleDriver.PointerWorldForTest = cemeteryW;
                            Check(cemeteryW != Vector3.zero, "★ A462：（前提）拿得到日志钮的世界坐标");
                            BattleDriver.PointerHeldForTest = true;
                            wb4.PollInputEdgesForTest();
                            wb4.TickLogInputForTest();
                            Check(!log4.Visible,
                                  "★ A462：日志钮**按下那一帧不开**（原版 `ShowCemeteryBtn` 的 `m_OnClick → ShowCemeteryLogBtn`）");
                            BattleDriver.PointerHeldForTest = false;
                            wb4.PollInputEdgesForTest();
                            // 🔴 **2026-10-19（`T09` A2）**：日志（墓地）钮已走 uGUI ⇒ 松手那一帧由
                            //   `BattleHudButton` 派发（与 `EventSystem` 的 `IPointerClickHandler` 同一跳）；
                            //   手搓的 `TickLogInputForTest` 现在只剩「面板开着」那条模态支。
                            wb4.ClickHudButtonForTest("cemetery");
                            Check(log4.Visible,
                                  "★ A462：……**松手那一帧才开**（uGUI `IPointerClickHandler` = 抬起；"
                                + "改坏法：把 `ClickCemeteryHud` 挪到 `OnPointerDown` / 手搓回按下沿 ⇒ 前一条红）");
                            // 面板开着 ⇒ 同一处（`shade` 盖满全屏）那一下**仍然按按下沿关**
                            BattleDriver.PointerHeldForTest = true;
                            wb4.PollInputEdgesForTest();
                            wb4.TickLogInputForTest();
                            Check(!log4.Visible,
                                  "★ A462：日志面板**按下那一帧就收**（原版 `shade` = `EventTrigger`，"
                                + "`eventID 2 = PointerDown`；判据 `EventTriggerType.cs:24`）"
                                + " —— ⚠️ 换成松手沿 = 与原版不符，也**红**");
                            // 吞并自证：**同一次按住**的松手沿不许把它又打开（指针就在日志钮上）
                            BattleDriver.PointerHeldForTest = false;
                            wb4.PollInputEdgesForTest();
                            wb4.TickLogInputForTest();
                            Check(!log4.Visible,
                                  "★ A462：……同一次按住的**松手沿不会把它又打开**（改坏法：删掉 `_swallowNextRelease`"
                                + " ⇒ 画面闪一下、看着像「点了没反应」）");
                        }

                        // ============================================================
                        //  五、`#10`：`ChatPopup` 那一处的**两半**（条外关闭按「按下」/ 选台词按「松手」）
                        // ============================================================
                        var pop4 = wb4.ChatPopup;
                        Check(pop4 != null && pop4.Ready, "★ A462：（前提）`ChatPopup` 建起来了");
                        if (pop4 != null && pop4.Ready)
                        {
                            // ① 条外关闭：**uGUI `CloseChatPopup` 的 `EventTrigger` + `PointerDown`** ——
                            //    🔴 **2026-10-21（战斗线 `T09` A4 · 步骤 S1）就地改口径（铁律 5）**：驱动那条手搓支
                            //    （`ClickedThisFrame()` + `PointerDownAt`）已整段退场 ⇒ 这条断言不再喂手搓指针，
                            //    改为「**uGUI 入口点一次 ⇒ 动作 1 次 + `TickChatInputForTest()` 只做模态吞掉**」。
                            pop4.Show();
                            Check(pop4.UguiInputReadyForTest,
                                  "★ A462：（前提）`ChatPopup` 的 uGUI 输入层整组装好（6 条命中条 + 关闭区触发器）");
                            var pd4 = new UnityEngine.EventSystems.PointerEventData(
                                           UnityEngine.EventSystems.EventSystem.current);
                            // 按下那一帧（世界侧）：先喂一次按下沿，好让下面那条「松手沿被吞」有东西可吞
                            BattleDriver.PointerWorldForTest = wb4.HudButtonWorldPosForTest("chat");
                            BattleDriver.PointerHeldForTest = true;
                            wb4.PollInputEdgesForTest();
                            int close4 = pop4.UguiCloseCountForTest;
                            var closeTrig4 = pop4.CloseTriggerForTest;
                            Check(closeTrig4 != null,
                                  "★ A462：（前提）关闭区那颗 `EventTrigger` 在（原版 `CloseChatPopup` 的 `PointerDown`）");
                            if (closeTrig4 != null) closeTrig4.OnPointerDown(pd4);   // uGUI：原版那颗 `EventTrigger`
                            Check(pop4.Visible && pop4.ClosePendingForTest && pop4.UguiCloseCountForTest == close4,
                                  "★ A462：条外**按下** ⇒ 面板只记「待关」、**不当场 `Hide()`**"
                                + "（`T09-FIX3` P1-3：当场关会让驱动这一帧看不到模态 ⇒ 同一按落到棋盘/手牌）");
                            Check(wb4.TickChatInputForTest(),
                                  "★ A462：气泡开着 ⇒ 驱动**只做模态吞掉**（`HandleChatPopup` 恒 true、不做事）");
                            // 🔴 `ClickLog`：uGUI 入口那一下**仍记一笔**（判据 → `T09` 迁移计划 §四 R8）——
                            //   驱动退掉手搓沿之后，这条记录必须由订阅方（`OnChatCloseRequested`）补上，
                            //   否则真机点一下「日志里一条都没有」，而画面一切正常 = 典型静默。
                            var chatProbe4 = Path.Combine(OutDir, "_wb4_chat_close_probe.txt");
                            if (File.Exists(chatProbe4)) File.Delete(chatProbe4);
                            ClickLog.OverridePath = chatProbe4;
                            bool chatApplied4 = pop4.ApplyPendingClose();
                            ClickLog.End();
                            string chatBlk4 = ClickLog.LastBlock ?? "";
                            ClickLog.OverridePath = null;
                            Check(chatApplied4 && !pop4.Visible && pop4.UguiCloseCountForTest == close4 + 1,
                                  "★ A462：……**面板自己的 `LateUpdate` 落账** ⇒ 关掉"
                                + "（原版 `CloseChatPopup` = `EventTrigger` `eventID 2 = PointerDown`）");
                            Check(chatBlk4.Contains("来源 BattleDriver") && File.Exists(chatProbe4),
                                  "★ A462：……uGUI 那一下**进了「真实点击记录」**（`CloseRequested` → `LogClickBeat`）"
                                + "｜🧨 把驱动那半边订阅摘掉 ⇒ 手搓沿退了、记录也没了 ⇒ 本条红（`wf_click.py` 验收口会少一大片）"
                                + $"（探针文件 {(File.Exists(chatProbe4) ? "有" : "**没有**")}："
                                + "`ClickLog.End()` 在没有新记录时会早退、`LastBlock` 停在上一笔 ⇒ "
                                + "所以这里**同时看文件**，别只信那串文本）");
                            // 同一次按住的**松手沿不许把聊天钮又点开**（`CloseRequested` → `_swallowNextRelease`）
                            BattleDriver.PointerHeldForTest = false;
                            wb4.PollInputEdgesForTest();
                            Check(!wb4.ReleasedThisFrameForTest(),
                                  "★ A462：……同一次按住的**松手沿被吞掉**（`OnChatCloseRequested` 里置 `_swallowNextRelease`）"
                                + "｜🧨 删掉那一句 ⇒ 真机上松手会把聊天钮又点开（画面闪一下、看着像「点了没反应」）");

                            // ② 选台词：**按下那一帧不说**（uGUI `IPointerClickHandler` = 松手才派发），
                            //    说哪一句由面板的 `BattleHudButton` → `ButtonClicked` → 驱动 `LateUpdate` 落账。
                            pop4.Show();
                            var hit4 = pop4.ButtonClickComponentForTest(0);
                            Check(hit4 != null,
                                  "★ A462：（前提）台词钮的 uGUI 点击适配器在（不在 ⇒ 这颗钮点不动）");
                            if (hit4 != null)
                            {
                                int uc4 = pop4.UguiButtonClickCountForTest;
                                BattleDriver.PointerWorldForTest = pop4.ButtonWorldPos(0);
                                BattleDriver.PointerHeldForTest = true;
                                wb4.PollInputEdgesForTest();
                                Check(wb4.TickChatInputForTest() && pop4.Visible
                                   && pop4.UguiButtonClickCountForTest == uc4,
                                      "★ A462：台词钮**按下那一帧不说话**（窗还开着、uGUI 点击计数不动）"
                                    + "（原版 6 颗 = `ChatPopupButton : EverguildButton` ⇒ `onClick` 在松手那一帧）");
                                BattleDriver.PointerHeldForTest = false;
                                wb4.PollInputEdgesForTest();
                                Check(wb4.TickChatInputForTest(),
                                      "★ A462：……松手那一帧仍由驱动**吞掉**（模态；动作归面板的 uGUI）");
                                hit4.ClickForTest();                     // uGUI：`IPointerClickHandler` 那一跳
                                Check(pop4.UguiButtonClickCountForTest == uc4 + 1 && pop4.Visible,
                                      "★ A462：uGUI **点一次 = 动作 1 次**，而且**窗还开着**"
                                    + "（`Hide()` + 说话挂起到 `LateUpdate`，⛔ 不在 `EventSystem` 回调里当场做）");
                                Check(wb4.ApplyPendingChatForTest() && !pop4.Visible,
                                      "★ A462：……**落账之后才说那句 + 关气泡**"
                                    + "（原版 `ClickChat`：先 `Hide` 再 `OnVoiceLinePressed`）"
                                    + "｜🧨 把 `ReleasedThisFrame()` + `PointerUpAt` 那条手搓支加回 `HandleChatPopup` ⇒ "
                                    + "上面「点一次 = 1」与「窗还开着」两条结构上不可能同时满足");
                            }
                            if (pop4.Visible) pop4.Hide();
                        }

                        // ============================================================
                        //  六、`#1` 多卡摊开窗：关闭的**唯一入口** = 面板自己的 uGUI（`T09` A4 · S1）
                        //    🔴 **2026-10-21 就地改口径（铁律 5）**：驱动那条手搓支
                        //    （`ReleasedThisFrame()` + `_multiCards.Hide()`）已整段删除 ⇒ 这里不再断
                        //    「松手那一帧才关」，改断「**驱动一条沿都不耗、一颗都不关**」（= 手搓路确实退了），
                        //    关闭改由 uGUI 入口点一次 ⇒ 挂起 → 落账。
                        // ============================================================
                        Check(wb4.Ctx != null, "★ A462：（前提）这一局还有 `Ctx`（多卡窗靠牌库内容才开得起来）");
                        if (wb4.Ctx != null)
                        {
                            var mcd4 = wb4.MultiCards;
                            Check(mcd4 != null && mcd4.ContinueButtonForTest != null
                               && mcd4.BackgroundCloseButtonForTest != null,
                                  "★ A462：（前提）多卡摊开窗开得起来，且两颗 uGUI 关闭件（「继续」条 / 全屏背景）都在");
                            if (mcd4 != null && mcd4.ContinueButtonForTest != null
                                && mcd4.BackgroundCloseButtonForTest != null)
                            {
                                // ① 手搓那条路**已经退场**：按下 / 松手都不关窗
                                wb4.ShowMyDeck(true);
                                Check(wb4.MultiCardsVisibleForTest, "★ A462：（前提）多卡摊开窗开得起来");
                                BattleDriver.PointerWorldForTest = LayoutSpace.ToWorld(0.5f, 0.5f);   // 随便一点（不是牌堆）
                                BattleDriver.PointerHeldForTest = true;
                                wb4.PollInputEdgesForTest();
                                Check(wb4.TickMultiCardsForTest(),
                                      "★ A462：窗开着 ⇒ 这一帧**被吞掉**（全屏模态，`TickMultiCards` 恒 true）");
                                Check(wb4.MultiCardsVisibleForTest,
                                      "★ A462：多卡窗**按下那一帧不关**");
                                BattleDriver.PointerHeldForTest = false;
                                wb4.PollInputEdgesForTest();
                                Check(wb4.TickMultiCardsForTest() && wb4.MultiCardsVisibleForTest,
                                      "★ A462：**松手那一帧也不关** —— 关闭只走面板自己的 uGUI 入口"
                                    + "（原版 `BackgroundCloseButton` / `Close` 钮都是 uGUI 点击）"
                                    + "｜🧨 把 `if (tapped) _multiCards.Hide();` 加回 `TickMultiCards` ⇒ 本条红"
                                    + "（那正是「两条关闭路并存」= 一次点击走两遍）");

                                // ② 点牌堆本身：同样只走 uGUI（全屏背景关闭件），驱动这一侧不关也不重开
                                Vector3 deckW4 = wb4.MyDeckPlateWorldPos;
                                Check(deckW4 != Vector3.zero && BattleDriver.HitMyDeckPile(deckW4),
                                      "★ A462：（前提）牌堆底板的世界坐标落在 `HitMyDeckPile` 的命中区里");
                                BattleDriver.PointerWorldForTest = deckW4;
                                BattleDriver.PointerHeldForTest = true;
                                wb4.PollInputEdgesForTest();
                                wb4.TickMultiCardsForTest();
                                Check(wb4.MultiCardsVisibleForTest,
                                      "★ A462：指在牌堆上 —— **按下那一帧不关**");
                                BattleDriver.PointerHeldForTest = false;
                                wb4.PollInputEdgesForTest();
                                Check(wb4.TickMultiCardsForTest() && wb4.MultiCardsVisibleForTest,
                                      "★ A462：指在牌堆上 —— **松手那一帧也不再靠手搓关**（那条已退场；"
                                    + "关这一下由全屏背景关闭件收）"
                                    + "｜🧨 把「`if (tapped) Hide()` + `if (tapped && onDeck) ShowMyDeck(true);`」"
                                    + "加回去 ⇒ 本条红（窗会被 hide 完立刻 show，永远关不掉）");

                                // ③ uGUI：点「继续」⇒ 只挂起 → 面板 `LateUpdate` 落账（批处理手动落）
                                int mcdClick4 = mcd4.UguiCloseClickCountForTest;
                                // 🔴 `ClickLog`：uGUI 入口那一下仍记一笔（判据 → `T09` 迁移计划 §四 R8）
                                var mcdProbe4 = Path.Combine(OutDir, "_wb4_multicard_close_probe.txt");
                                if (File.Exists(mcdProbe4)) File.Delete(mcdProbe4);
                                ClickLog.OverridePath = mcdProbe4;
                                mcd4.ContinueButtonForTest.ClickForTest();
                                ClickLog.End();
                                string mcdBlk4 = ClickLog.LastBlock ?? "";
                                ClickLog.OverridePath = null;
                                Check(mcd4.Visible && mcd4.ClosePendingForTest
                                   && mcd4.UguiCloseClickCountForTest == mcdClick4 + 1,
                                      "★ A462：uGUI 点「继续」⇒ **只记「待关」**（窗还开着、不当场 `Hide`）");
                                Check(mcdBlk4.Contains("来源 BattleDriver") && File.Exists(mcdProbe4),
                                      "★ A462：……uGUI 那一下**进了「真实点击记录」**（`CloseRequested` → `LogClickBeat`）"
                                    + "｜🧨 摘掉 `_multiCards.CloseRequested += LogClickBeat;` ⇒ 手搓沿退了、记录也没了 ⇒ 红"
                                    + $"（探针文件 {(File.Exists(mcdProbe4) ? "有" : "**没有**")}；"
                                    + "没记录时 `ClickLog.End()` 会早退、`LastBlock` 是上一笔 ⇒ 所以同时看文件）");
                                Check(mcd4.ApplyPendingCloseForTest() && !mcd4.Visible,
                                      "★ A462：……落账 ⇒ 关掉一次，而且**同一按不会被 `ShowMyDeck(true)` 开回来**"
                                    + "｜🧨 改回手搓那两句 ⇒ 本条与上面那条**结构上不可能同时满足**");
                            }
                            wb4.ShowMyDeck(false);      // 收尾：别让窗挂着影响后面几段
                        }

                        // ============================================================
                        //  七、`#3` 攻击选择器【悬停即选中】+ 0.1s 安全窗（原版根本不是点击）
                        //     `CardDisplayAttackTypeButton` 只实现 `IPointerEnter/ExitHandler`；
                        //     `__Update.c:20-30` 要 `inputOverButton(+0x92) && sendInput(+0x90)
                        //     && !isInputOverSent(+0x91)` 三格一齐才发。
                        // ============================================================
                        // ⚠️ **只验触发沿，不碰拖拽流程**（WA462 §五·2 明说时序没验全）。
                        var sel4 = wb4.Selector;
                        Check(sel4 != null, "★ A462：（前提）攻击选择器在");
                        if (sel4 != null && wb4.Ctx != null)
                        {
                            // 摆一个**新鲜的**探针单位（`Ballista`：近战 0 / 远程 4 ⇒ 只有「远程」那一格。
                            // 同 5b 那段的做法，收尾要把它清掉）。
                            int side4 = wb4.MySideForTest;
                            int probe4 = FreeSlot(wb4.Ctx, side4);
                            Check(probe4 >= 0, "★ A462：（前提）我方棋盘上有一个空格能摆探针单位");
                            if (probe4 >= 0)
                            {
                                ClearEffects();
                                wb4.Ctx.Players[side4].Board[probe4] =
                                    new UnitState(CardByName(StarterCards.Tide(), "Ballista"), false) { Exhausted = false };
                                wb4.RefreshAll();
                                Check(wb4.SimulateOpenCommand(probe4) && wb4.HasCommand(AttackKind.Ranged),
                                      "★ A462：（前提）探针 `Ballista` 的选择器开起来了、且有「远程」那一格");
                                var bw4 = sel4.ButtonWorld(AttackKind.Ranged);
                                Check(bw4.HasValue, "★ A462：（前提）拿得到「远程」那格的世界坐标");
                                if (bw4.HasValue)
                                {
                                    BattleDriver.PointerWorldForTest = bw4.Value;
                                    // 安全窗还在（刚弹出，`Show()` 打了 0.1s）⇒ **悬停上去也不发**
                                    // 🔴 2026-10-20（W57 · `T09` WIRE · A3-e4 收口）：画布档的 `Hovered`
                                    //   已改由 uGUI 送达（`UpdatePointer` 只推进画/回读）⇒ 喂 `Highlight` 圈的
                                    //   `PointerEnter`（下标 2 = `Order` 的 `Ranged`，同 5b 那条）。
                                    var ring4 = sel4.HighlightTriggerForTest(2);
                                    Check(ring4 != null,
                                          "★ A462：（前提）「远程」那一格的 `Highlight` 挂了 `EventTrigger`");
                                    ring4?.OnPointerEnter(NewPointerEventData());
                                    Check(sel4.Hovered == AttackKind.Ranged && !sel4.HoverPickReady,
                                          $"★ A462：刚弹出时指针就压在上面 —— **安全窗没走完 ⇒ 不发**"
                                        + $"（`sendInput(+0x90)` 那一格；实得 safeLeft={sel4.HoverSafeLeft:F3}s、"
                                        + $"ready={sel4.HoverPickReady}）");
                                    wb4.DrivePlayerTurnForTest();
                                    Check(wb4.SelectedSlot >= 0 && wb4.SelectorOpen,
                                          "★ A462：……这一帧**没有选中任何打法**（指针压着也不动 —— 安全窗之内）");
                                    // 「换格 ⇒ 重开安全窗」那一格（原版 `OnPointerExit` → `DisableTemporary(其它钮)`）：
                                    // 指针**刚进入**这一格 ⇒ 安全窗从头算（0.1s 是「进入之后」才起算的）
                                    sel4.TickForTest(0f, Vector2.zero);
                                    Check(!sel4.HoverPickReady,
                                          $"★ A462：指针**刚进入**那一格 ⇒ 安全窗重开（原版 `OnPointerExit` 会给别的钮"
                                        + $" `DisableTemporary`），实得 safeLeft={sel4.HoverSafeLeft:F3}s");
                                    // 安全窗走完（喂 0.11s）⇒ 同一格**发**
                                    sel4.TickForTest(0.11f, Vector2.zero);
                                    Check(sel4.HoverPickReady,
                                          "★ A462：安全窗走完（0.1s，原版 `disableTimeAfterPointerExit` 三颗都是这个数）"
                                        + $" ⇒ 可以发（实得 {sel4.HoverSafeLeft:F3}s）");
                                    wb4.DrivePlayerTurnForTest();
                                    Check(!wb4.SelectorOpen && wb4.Command == AttackKind.Ranged,
                                          $"★ A462：**悬停即选中** —— 指针一直压着「远程」就定下来了"
                                        + $"（选择器收起 {!wb4.SelectorOpen} / 打法 {wb4.Command}）"
                                        + "（改坏法：改回 `if (ClickedThisFrame())` ⇒ 这两条红）");
                                    wb4.SimulateDeselect();
                                }
                                wb4.Ctx.Players[side4].Board[probe4] = null;      // 探针清掉（同 5b 那段）
                                wb4.RefreshAll();
                            }
                        }

                        // ============================================================
                        //  八、`#4` 的 ④ 支：**按下不是选目标，松手才是**（③ 与 ④ 同一行，判据逐字相同）
                        //     ⚠️ 另一半（⑤ 记 `_pressSlot`）必须留在按下那一帧 —— 见 `DrivePlayerTurn`
                        //     里那条注释；这里验的是「按下那一帧**没有**把目标打掉」。
                        // ============================================================
                        if (wb4.Ctx != null && wb4.FoeUnits.Count > 0)
                        {
                            int mySide4 = wb4.MySideForTest;
                            int mySlot4 = FreeSlot(wb4.Ctx, mySide4);
                            int foeSlot4 = -1;
                            CardView foeV4 = null;
                            foreach (var kv in wb4.FoeUnits)
                                if (kv.Value != null) { foeSlot4 = kv.Key; foeV4 = kv.Value; break; }
                            Check(mySlot4 >= 0 && foeSlot4 >= 0,
                                  "★ A462：（前提）我方有空格摆探针、对面场上也有一个单位（④ 那组要这两样）");
                            if (mySlot4 >= 0 && foeSlot4 >= 0)
                            {
                                ClearEffects();
                                wb4.Ctx.Players[mySide4].Board[mySlot4] =
                                    new UnitState(CardByName(StarterCards.Tide(), "Ballista"), false) { Exhausted = false };
                                wb4.RefreshAll();
                                // ⚠️ `Ballista` 只有远程 ⇒ 用 `Ranged` 起手（近战 0 开不出「近战」那一格）
                                Check(wb4.SimulateOpenCommand(mySlot4) && wb4.HasCommand(AttackKind.Ranged),
                                      "★ A462：（前提）探针的选择器开起来了、有「远程」那一格");
                                wb4.SimulateCommand(AttackKind.Ranged);          // 定好打法 ⇒ 进「选目标」
                                Check(wb4.SelectedSlot == mySlot4, "★ A462：（前提）已经进「选目标」状态");
                                if (wb4.SelectedSlot == mySlot4)
                                {
                                    BattleDriver.PointerWorldForTest = foeV4.transform.position;
                                    BattleDriver.PointerHeldForTest = true;
                                    wb4.PollInputEdgesForTest();
                                    wb4.DrivePlayerTurnForTest();
                                    Check(wb4.SelectedSlot >= 0,
                                          "★ A462：选目标时**按下那一帧不结算**（原版点棋盘单位 = `CardCollider.IPointerClickHandler`）"
                                        + " —— 改坏法：把 ④ 那一支挪回按下沿 ⇒ 这条红");
                                    BattleDriver.PointerHeldForTest = false;
                                    wb4.PollInputEdgesForTest();
                                    wb4.DrivePlayerTurnForTest();
                                    Check(wb4.SelectedSlot < 0,
                                          "★ A462：……**松手那一帧才结算**（`Resolve` 自己会 `ClearSelection`；"
                                        + "改坏法：换回 `ClickedThisFrame()` ⇒ 前一条红）");
                                }
                                wb4.Ctx.Players[mySide4].Board[mySlot4] = null;   // 探针清掉
                                wb4.RefreshAll();
                            }
                        }
                        else Debug.Log(P + "   （A462：对面场上没有单位 ⇒ ④ 那一组没验 —— 出声）");

                        // ============================================================
                        //  九、A658：三钮入场动画的**驱动量 = 累计的视口拖拽位移**（不是时间）
                        //     `AttackTypesButtonsController__MoveButtons.c`：
                        //     `accumulatedDrag += TouchInputManager.TouchDragDeltaViewport` →
                        //     `t = clamp01(−accumulatedDrag.y ÷ accumulatedDragForMinDistance(+0x30))`
                        //     `OnEnable` 把累计量清零（`__OnEnable.c`）。
                        // ============================================================
                        if (wb4.Ctx != null)
                        {
                            // 再摆一个**新鲜**探针（上面那组可能已经把上一个用掉了 —— `OpenCommand` 对
                            // `Exhausted` 的单位直接返回）
                            int side5 = wb4.MySideForTest;
                            int probe5 = FreeSlot(wb4.Ctx, side5);
                            Check(probe5 >= 0, "★ A658：（前提）我方棋盘上还有空格能摆第二个探针单位");
                            if (probe5 >= 0)
                            {
                                ClearEffects();
                                wb4.Ctx.Players[side5].Board[probe5] =
                                    new UnitState(CardByName(StarterCards.Tide(), "Ballista"), false) { Exhausted = false };
                                wb4.RefreshAll();
                                Check(wb4.SimulateOpenCommand(probe5), "★ A658：（前提）探针的选择器开起来了");
                                var s5 = wb4.Selector;
                                Check(s5 != null && s5.Visible, "★ A658：（前提）选择器可见（下面量的是它的入场进度）");
                                if (s5 != null && s5.Visible)
                                {
                                    Check(s5.EnterProgress <= 1e-3f && s5.AccumulatedDrag == Vector2.zero,
                                          "★ A658：弹出时累计量清零（原版 `OnEnable` 从静态零向量写 `+0x50/+0x54`）");
                                    // 停住不拖 ⇒ **冻住**（原来那个按时间推进的版本会自己走完）
                                    bool moved5 = s5.TickForTest(0.5f, Vector2.zero);
                                    Check(!moved5 && s5.EnterProgress <= 1e-3f,
                                          $"★ A658：**停住不拖 ⇒ 动画冻在原地**（喂 0.5s 时间 + 零位移，进度实得 {s5.EnterProgress:F3}）"
                                        + " —— 改坏法：换回 `_enterT += dt / 0.085f` ⇒ 这条红");
                                    // 往下拖（视口 y 正向）⇒ 进度不涨（原版取的是 −accumulatedDrag.y）
                                    s5.TickForTest(0f, new Vector2(0f, 0.05f));
                                    Check(s5.EnterProgress <= 1e-3f,
                                          $"★ A658：**往下拖不推进**（原版 `t = −accumulatedDrag.y ÷ …`；实得 {s5.EnterProgress:F3}）");
                                    // 往上拖 0.0425 = 半程
                                    // 🔴 **2026-10-14 就地订正**：累计量是**从开窗起一直在加**的
                                    //   （`PushDrag`：`_accumulatedDrag += delta`，只有 `OnEnable` 那一下清零）
                                    //   ⇒ 上一步那 +0.05 还挂着 ⇒ 要净 −0.0425 就得喂 **−0.0925**
                                    //   （原来写 −0.0425 ⇒ 净 +0.0075 ⇒ 进度 0，本条**从未被执行过**所以一直没露）。
                                    //   ⛔ 别改成「反过来把上一步的 0.05 删掉」—— 那一步是「往下拖不推进」的判据。
                                    s5.TickForTest(0f, new Vector2(0f, -0.0925f));
                                    Check(Mathf.Abs(s5.EnterProgress - 0.5f) < 0.02f,
                                          $"★ A658：往上拖半个阈值（净 −0.0425 屏高 = `DragThreshold01` 的一半）⇒ 进度 ≈ 0.5（实得 {s5.EnterProgress:F3}）");
                                    s5.TickForTest(0f, new Vector2(0f, -0.5f));
                                    Check(s5.EnterProgress >= 1f,
                                          $"★ A658：拖够 ⇒ 夹在 1（实得 {s5.EnterProgress:F3}）");
                                    wb4.SimulateDeselect();
                                }
                                wb4.Ctx.Players[side5].Board[probe5] = null;      // 探针清掉
                                wb4.RefreshAll();
                            }
                        }

                        // ============================================================
                        //  十、**源级**（结构）断言：`BattleDriver.cs` 里还剩哪几处用**按下沿**
                        //     15 处代码调用一处不能漏 —— 这一条把「哪一行换成了哪条沿」整体钉死，
                        //     补上「面板开不起来 ⇒ 那一处验不了」的那几处（#2 放大窗 / #13 回放条 /
                        //     #14 换牌 / #15 选牌）。⛔ 它不是行为断言，别拿它顶替上面那几条。
                        // ============================================================
                        {
                            string src4 = System.IO.Path.Combine(Application.dataPath,
                                                                 "CardPresentation/Battle/BattleDriver.cs");
                            if (!System.IO.File.Exists(src4))
                            {
                                Check(false, $"★ A462：读得到 `BattleDriver.cs`（路径 {src4}）—— 读不到时"
                                           + "下面那条源级断言**等于没验**，所以这里当场红");
                            }
                            else
                            {
                                var lines4 = System.IO.File.ReadAllLines(src4);
                                var downCallSites = new List<string>();
                                for (int i = 0; i < lines4.Length; i++)
                                {
                                    string L = lines4[i].TrimStart();
                                    if (L.StartsWith("//")) continue;                 // 注释不算（含 `///`）
                                    if (L.IndexOf("ClickedThisFrame()") < 0) continue;
                                    if (L.StartsWith("bool ClickedThisFrame")
                                        || L.StartsWith("public bool ClickedThisFrameForTest")) continue;   // 定义 / 自检口
                                    downCallSites.Add("行" + (i + 1) + ":" + L.Substring(0, Mathf.Min(52, L.Length)));
                                }
                                // **按下沿**允许留下的调用点（逐处判据 → WA462 §三 / §四；**2026-10-21 现读**）：
                                //  ① 日志面板背板 `shade`（原版 `EventTrigger` `eventID 2 = PointerDown`）
                                //  ② 攻击选择器的**槽外取消**（原版没有对应物 —— 保持现状，WA462 §四·3）
                                //  ③ 记 `_pressSlot`（我们自己的中间态，纪律 3）
                                //  ④ 结算后的出口（`HandleEndBattleExit` 里那句 `bool clicked = ClickedThisFrame();`）——
                                //     原版那句就是 `UnityEngine_Input__GetMouseButtonDown(0)`
                                //     （`BattleManager__Update.c:116`），**本来就是按下沿**、而且**无坐标判定**
                                //     （点屏幕任意处）⇒ 这一处**不该**改成抬起。
                                //     判据全文 → `资料/普查产出_1016/判据_结算后出口.md` §2.1 / §3。
                                //  🔴 **2026-10-21（战斗线 `T09` A4 · 步骤 S1）：数从 5 改成 4** ——
                                //     原来那条「`ChatPopup` 条外关闭 `CloseChatPopup`」**已退场**：
                                //     气泡的条外关闭现在完全归面板自己的 uGUI（`EventTrigger.PointerDown` →
                                //     `OnClosePointerDown`），驱动 `HandleChatPopup` 只做模态吞掉、**一条沿都不耗**。
                                //     ⚠️ 旧注里列的「`DrivePlayerTurn`」那一处**早已不在这个函数上**（它直接读 `_downEdge`，
                                //     见 `Update` 里那条注释）—— 那是旧注的残留，别再按它去核。
                                //     🧨 判据：把 `ClickedThisFrame()` 加回 `HandleChatPopup` ⇒ 本条红（两条关闭路并存）。
                                string joined4 = string.Join(" | ", downCallSites.ToArray());
                                Check(downCallSites.Count == 4,
                                      $"★ A462：`BattleDriver.cs` 里用**按下沿**的代码行**只剩 4 处**"
                                    + $"（实得 {downCallSites.Count} 处：{joined4}）"
                                    + " —— 多一处 = 有一条该改抬起的没改（或有一条已退场的手搓路被加回来了）；少一处 = 把一个本来就该按下的改掉了"
                                    + "（②~④ 那几处：`Update` 里两条沿的行为断言覆盖不到 ⇒ 这里补"
                                    + "「那一行到底调的是哪条沿」）");
                            }
                        }
                    }
                    finally
                    {
                        BattleDriver.PointerHeldForTest = null;
                        BattleDriver.PointerWorldForTest = null;
                        AutoZoom.RestoreForTest(azWas4, azChosen4);
                        if (sp4 != null) { if (spWasOpen4) sp4.Show(); else sp4.Hide(); }
                    }
                }
            }
            Debug.Log(P + "--- A462 / A658 段结束 ---");

            int hookedBeforeB = BattleDriver.StaticHookCount;
            Check(hookedBeforeB > 0,
                  $"（前提）新开一局把静态钩子**接回来**了（期望 **> 0**；实得 {hookedBeforeB} 条）"
                + " —— 有这个前提，(b) 才不是恒真");

            // ---------------- 🆕 2026-10-13（A515）：**二次 `Begin()` 也要把钩子一条不少地接回来** ----------------
            // 🔴 上面那次 `driver.Begin(...)` 是**同一个 driver 的第 N 次**（`_hudBuilt` 早就闩住了 ——
            //    `HudExtraCount` 那 10 件补摆件就是证据）⇒ 正好在这儿钉「静态钩子**每次 `Begin` 都重挂**」。
            //    基线 = `hookedBefore388`（**同一次运行**里「一次 `Begin` 之后」的实测条数，见它上面那段注；
            //    清单槽数 `StaticHookSlots` 只打印出来当参照，⛔ 不拿它当期望值 —— 理由同那段注）。
            //    毛病原来是：`UnitTweenRuntime.HeroBySeat` / `SeatOf` 那两个补间解析口**只在 `BuildHud()` 里赋值**，
            //    而 `BuildHud` 被 `_hudBuilt` 闩住 ⇒ 二次 `Begin` 时它们**不跑**（可 `DetachStaticHooks()`
            //    已经把这两格置 null 了 ⇒ 静默少两条，下游只表现为「补间定位不到督军」）。
            // 🧨 **改坏法**：把那两句挪回 `BuildHud()` ⇒ 二次 `Begin` 只接回 **17/19** ⇒ 第 1 条红
            //    （2026-10-13 之前就是这个状态，实测日志 `d:/4/_tmp_view/battle.log` 卸前 17）；
            //    把 `Begin()` 里那句 `HookUnitTweenResolvers()` 删掉 ⇒ 两条一起红。
            // ⚠️ 它与上面 (a)/(b) 两段**不冲突**：(b) 用的是动态量 `hookedBeforeB`（⛔ 没有写死 17），
            //    所以这条修完不会把 (b) 弄红。
            {
                int slots515 = BattleDriver.StaticHookSlots;
                Check(slots515 > 0 && driver.HudExtraCount > 0 && hookedBeforeB == hookedBefore388,
                      $"★ A515：**二次 `Begin()` 之后静态钩子一条不少**（首次 `Begin` 后 {hookedBefore388} 条 → "
                    + $"二次 `Begin` 后 {hookedBeforeB} 条；清单共 {slots515} 槽）"
                    + $"，且 HUD 早建过了（`HudExtraCount = {driver.HudExtraCount}` ⇒ `_hudBuilt` 为真）"
                    + " —— 钩子绑的是**这个 driver 实例**，所以 `Begin` 每走一次都要重挂；少两条就是"
                    + "`UnitTweenRuntime.HeroBySeat` / `SeatOf` 又挂回 `BuildHud()` 里去了");
                Check(UnitTweenRuntime.HeroBySeat != null && UnitTweenRuntime.SeatOf != null,
                      "★ A515：那两个**补间解析口**在二次 `Begin()` 之后仍挂着"
                    + $"（`HeroBySeat` = {(UnitTweenRuntime.HeroBySeat != null ? "非 null" : "**null**")} · "
                    + $"`SeatOf` = {(UnitTweenRuntime.SeatOf != null ? "非 null" : "**null**")}）"
                    + " —— 它们为 null 时 `UnitTweenRuntime.ResolveHero` **直接返回 null**（补间定位不到督军，静默）");
            }

            // ---------------- 🆕 2026-10-15（W19）：「让位」预览（拖拽中把场上单位推开）----------------
            // 🔴 **2026-10-17 搬家**：本段原来落在整轮末尾（`DestroyImmediate(driver)` **之后**）——
            //    进段时驱动已被卸 ⇒ `StepThrough`/`Step` 用 `FindObjectOfType` 现找 **恒 null** ⇒
            //    `AdvanceTimeline` 一次都不推、时钟冻结、时间线永远排不空（收口跑 2 条红）。
            //    搬到 `DestroyImmediate(driver)` **之前**（与 2026-10-14「A462/A658 搬家」同一个处置）。
            // 🔴 **为什么单开这一节**：这条链 2026-10-01 落码之后**一次都没被自检走过** ——
            //    `BattleDriver.TickShufflePreview` 的调用点**全仓只有 `Update` 一处**（`BattleDriver.cs` 的 `Update` 里那句 `TickShufflePreview`），
            //    而批处理**没有帧循环** ⇒ 那条路一次都不跑（`项目任务.md` §三 8b 把它记成「已完成」，
            //    实际零覆盖；2026-10-15 可玩性普查查出的）。
            // 判据（原版）= `MinionManager__ReassembleMinionsWhilePlayingUnit.c`（由 `BattleManager__Update.c:575`
            //    **逐帧**调）：① 求「这张牌会插到该侧哪个下标」② 🔴 **下标 ≥ 插入点的单位整体 +1**
            //    —— ⚠️ 它**不改数据**，只是把它们补间到「插进去之后」的位置。
            //    我们这边 = `PreviewSlotFor`（三条守卫）+ `TickShufflePreview`（指数趋近 18/s）。
            // ⚠️ 测试口在 `BattleDriver`（形状照 `SimulateAiTurn` 那一族）：`SimulateDropPreview` /
            //    `SimulateTickShufflePreview` / `SimulateEndShufflePreview` / `ShufflePreviewArmed`。
            Debug.Log(P + "--- 「让位」预览（拖拽中把场上单位推开）---");
            {
                // 夹具前置：**先把事件时间线排空**（下面要白盒改棋盘；若还压着别的段的阵亡/触发事件，
                //    下一次 `RefreshAll` 会把它们当场播出来 —— 那会把刚摆好的探针视图搅掉）。
                StepThrough(driver);
                Check(driver.TimelinePending == 0,
                      $"夹具前提：进本节时事件时间线已经排空（待播 {driver.TimelinePending} 条）"
                    + " —— 不清空的话下面摆的探针会被上一段的事件播掉");

                // 🔴 **必须先打开 `animateFeel`** —— `TickShufflePreview` 头一句就是
                //    `if (!animateFeel …) return;`，而它**默认 false**（批处理自检为「当场精确的坐标」关掉的）。
                //    不打开的话这三个口**静默什么都不做**，下面每一条都会走空（同 `PlayDeathFeel` 那节的坑）。
                bool feelWas19 = driver.animateFeel;
                driver.animateFeel = true;

                int me19 = driver.MySeat;
                var bak19 = new UnitState[BoardSpec.Size];
                // 🔴 必须**当场重取**：`Begin()` 每走一次就 `Ctx = RuleCore.NewBattle(...)`（`BattleDriver.cs`），
                //    而本函数开头那个 `ctx` 的最后一次赋值远在本文件、此后至少又跑过 4 次 `Begin` ⇒ 早已是**孤儿**。
                //    写到孤儿上 = 白盒改了没人看的那一局（收口跑 1 条红：v3/v5/v6/v7 全 null）。
                ctx = driver.Ctx;
                for (int s = 0; s < BoardSpec.Size; s++) bak19[s] = ctx.Players[me19].Board[s];
                // 夹具：我方**左半场贴督军那格放 1 张**、**右半场贴督军连排 3 张** —— 两侧都「从贴督军那格起连续」，
                //    是 `BoardSlots` 认的合法局面（有洞的棋盘语义不唯一，那个模块会直接报错）。
                //    左半场那张是 ③ 的反例「另一侧不动」用的。
                for (int s = 0; s < BoardSpec.Size; s++)
                    if (s != BoardSpec.WarlordSlot) ctx.Players[me19].Board[s] = null;
                var probe19 = CardByName(StarterCards.Ember(), "Veteran");
                foreach (int s in new[] { 3, 5, 6, 7 })
                    ctx.Players[me19].Board[s] = new UnitState(probe19, false) { Exhausted = false };
                driver.RefreshAll();            // 白盒改棋盘不发事件 ⇒ 得自己刷一次（本文件夹具的惯例）

                var v3 = driver.MyUnits.ContainsKey(3) ? driver.MyUnits[3] : null;
                var v5 = driver.MyUnits.ContainsKey(5) ? driver.MyUnits[5] : null;
                var v6 = driver.MyUnits.ContainsKey(6) ? driver.MyUnits[6] : null;
                var v7 = driver.MyUnits.ContainsKey(7) ? driver.MyUnits[7] : null;
                if (v3 == null || v5 == null || v6 == null || v7 == null)
                {
                    Check(false, "（夹具）四张探针视图都建出来了 —— 建不出来下面全是空跑（⛔ 不静默跳过）");
                }
                else
                {
                    // 位姿全部**量出来**当期望值（⛔ 不用我们的常量 —— 那些常量正是被测实现自己读的）
                    Vector3 p3 = v3.transform.localPosition, p5 = v5.transform.localPosition;
                    Vector3 p6 = v6.transform.localPosition, p7 = v7.transform.localPosition;
                    float pitch19 = Vector3.Distance(p6, p5);           // 相邻格距
                    Vector3 out19 = (p7 - p6).normalized;               // 右外侧方向
                    Check(pitch19 > 0.01f,
                          $"★ 夹具前提：相邻两格**不是同一个点**（实测格距 {pitch19:F4}）—— "
                        + "它要是 0，「被推了一格」这条断言就退化成同义反复");

                    // ① 让位：请求落在**右半场贴督军那格（5 号）** ⇒ 该侧下标 ≥ 0 的三张整体 +1
                    driver.SimulateDropPreview(true, 5);
                    Check(driver.ShufflePreviewArmed,
                          "★ 预览态摆上了（`_previewRequested ≥ 0`）—— 它是 `TickShufflePreview` 的第一道门");
                    driver.SimulateTickShufflePreview(1f);   // 指数趋近：dt = 1 s ⇒ k ≈ 1，**一步到位**（不依赖 Update）

                    float d5 = Vector3.Distance(v5.transform.localPosition, p5);
                    Check(d5 > 0.5f * pitch19,
                          $"★ 「让位」**真的把单位推开了**：5 号那张挪了 {d5:F4}（判据 = 半个格距 "
                        + $"{0.5f * pitch19:F4}）—— ⛔ 这一条**不是**「调了不报错」"
                        + "；🧨 改坏法：删掉 `TickShufflePreview` 里那句 `tr.localPosition = Vector3.Lerp(…)`"
                        + "（或整个 `for` 循环）⇒ 红");
                    Check(Vector3.Distance(v5.transform.localPosition, p6) < 1e-3f,
                          "★ 而且推的是**正好一格**：5 号那张落在 **6 号原来那个位姿**上"
                        + "（期望值是**量出来的另一张视图的位姿**，不是我们自己的常量 ⇒ 与实现不同源）");
                    Check(Vector3.Distance(v6.transform.localPosition, p7) < 1e-3f,
                          "★ …6 号那张落在 7 号原来那一位（**整段一起 +1**，不是只推最外那一张）");
                    float d7 = Vector3.Dot(v7.transform.localPosition - p7, out19);
                    Check(d7 > 0.9f * pitch19 && d7 < 1.1f * pitch19,
                          $"★ 最外那张（7 号）也沿格线**往外挪了一格**（实测 {d7:F4}，一格 {pitch19:F4}）"
                        + " —— 用**量的方向**判，别处抄不到这个数");

                    // ② 收工（取消）：被推开的要**送回真格位**（原版那句 `DOLocalMove` 的回头路）
                    if (driver.interaction != null) driver.interaction.DropAccepted = false;   // 夹具：这一档 = 取消
                    bool moved19 = driver.SimulateEndShufflePreview();
                    Check(moved19,
                          "★ 收工时它知道「刚才确实推过人」（`_previewMoved` 非空）—— 这一条同时是下面那条的**前提**"
                        + "（一张都没记上 ⇒ 下面那条会静默走空）");
                    Check(!driver.ShufflePreviewArmed, "★ 收工之后预览态清干净（`_previewRequested` 回到 −1）");
                    CardTween.Advance(CardFeel.ReassembleTime + 0.05f);   // 送回是**补间** ⇒ 批处理得手动推到头
                    Check(Vector3.Distance(v5.transform.localPosition, p5) < 1e-3f
                       && Vector3.Distance(v6.transform.localPosition, p6) < 1e-3f
                       && Vector3.Distance(v7.transform.localPosition, p7) < 1e-3f,
                          "★ 取消（没松手打出去）⇒ 被推开的单位**各自送回真格位**"
                        + " —— 🧨 改坏法：删掉 `EndPreviewReturn` 里那句 `CardFeel.Reassemble(v, pos)` ⇒ 红");

                    // ③ 反例：**另一侧** / **插入点以前**的单位都不许动（`PreviewSlotFor` 前两条守卫）
                    driver.SimulateDropPreview(true, 6);      // 请求 6 号 = 该侧下标 1 ⇒ 插入点在它自己那一格
                    driver.SimulateTickShufflePreview(1f);
                    Check(Vector3.Distance(v5.transform.localPosition, p5) < 1e-3f,
                          "★ 反例：**插入点以前**那张不动（请求第 6 格 ⇒ 5 号那张该待在原地）"
                        + " —— 🧨 改坏法：删掉 `PreviewSlotFor` 里 `if (BoardSlots.IndexOf(slot) < insertAt) "
                        + "return slot;` ⇒ 红");
                    Check(Vector3.Distance(v3.transform.localPosition, p3) < 1e-3f,
                          "★ 反例：**另一侧**那张不动（插的是右半场，左半场那张连 1e-3 都没挪）"
                        + " —— 🧨 改坏法：删掉 `PreviewSlotFor` 里 `if (BoardSlots.SideOf(slot) != side) "
                        + "return slot;` ⇒ 红（它会被按**右侧的下标**推到一个跟自己无关的位子上）");
                    Check(Vector3.Distance(v6.transform.localPosition, p7) < 1e-3f,
                          "★ …而 6 号那张照样往外挪了一格（推的是**插入点之后**那些人）");
                    if (driver.interaction != null) driver.interaction.DropAccepted = false;
                    driver.SimulateEndShufflePreview();
                    CardTween.Advance(CardFeel.ReassembleTime + 0.05f);

                    // ④ 反例：**这一次松手是要打出去的** ⇒ 收工**不送回**（`DropAccepted` 那半条）
                    driver.SimulateDropPreview(true, 5);
                    driver.SimulateTickShufflePreview(1f);
                    if (driver.interaction != null) driver.interaction.DropAccepted = true;    // 夹具：松手 = 打出去
                    driver.SimulateEndShufflePreview();
                    CardTween.Advance(CardFeel.ReassembleTime + 0.05f);
                    Check(Vector3.Distance(v5.transform.localPosition, p6) < 1e-3f,
                          "★ 反例：**这一次松手是要打出去的** ⇒ 收工**不送回原位**（它们本来就该站在预览位上；"
                        + "送回去会先弹回原位、再被引擎插出去 = 抖两下）"
                        + " —— 🧨 改坏法：删掉 `EndPreviewReturn` 开头那句 `if (interaction != null "
                        + "&& interaction.DropAccepted) { _previewMoved.Clear(); return; }` ⇒ 红");

                    // ⑤ 顺带把**「关掉 3D 棋盘」那一档**（`use3DBoard == false`）也钉住 —— 本节是全仓
                    //    **唯一**真的把它翻过来的地方。它管着两处：`PoseFor` 的 `else` 支（`BattleDriver.cs` 的 `PoseFor`，
                    //    退回烘图那套正交行线）与 `SetLayer` 的门（`BattleDriver.cs` 的 `SyncBoard`，改由透视相机画）。
                    //    ⚠️ **两个落点必须一起设**：`driver.use3DBoard` 与 `BoardLayout.use3D` 是
                    //       同一个开关的两面（`BoardLayout.cs:419-423`、`BuildScene` 末尾那两行），
                    //       只设一个就是自相矛盾的状态。
                    driver.use3DBoard = false;
                    pBoard.use3D = eBoard.use3D = false;
                    driver.RefreshAll();
                    float back2D = Vector3.Distance(v5.transform.localPosition, pBoard.SlotPosition(5));
                    Check(back2D < 1e-3f,
                          $"★ 关掉 3D 棋盘 ⇒ 场上卡退回**正交行线**那一套落点（`PoseFor` 的 `else` 支）"
                        + $"（与 `BoardLayout.SlotPosition(5)` 的偏差 {back2D:E2}）"
                        + " —— 🧨 改坏法：把 `PoseFor` 的 `if (use3DBoard)` 去掉、恒走 3D 那套 ⇒ 红"
                        + "（那台透视相机不在时，卡会站到**没有相机画**的地方 = 静默消失）");
                    Check(Vector3.Distance(v5.transform.localPosition, p5) > 0.5f,
                          "★ 而且它与 3D 那一套落点**真不是同一个点**（挪了 "
                        + $"{Vector3.Distance(v5.transform.localPosition, p5):F3}）—— 有这一条，上面那条才分辨得出两态");

                    // 🆕 2026-10-17（B8/A849）：**3D 关着时「新建」的卡视图不许挂 `ArenaLayer`**。
                    // 为什么单列一条：`SyncBoard` 里那句带着 `if (use3DBoard)` 这道门，**门一摘掉**，
                    //   在「没有 3D 战场相机」那一档（`boardCam == null` ⇒ `use3DBoard` 恒 false，
                    //   `BuildScene` 末尾那句）**所有场上卡都会落到 `ArenaLayer`** —— 那一层
                    //   **没有任何相机画**（HUD 相机把它剔出 `cullingMask`）⇒ **整个棋盘静默消失**
                    //   （`BattleDriver.use3DBoard` 自己的 doc 就写着「最坏的一种失败」）。
                    //   而上面第 ④ 条只钉了「3D 开着 ⇒ 层是 `ArenaLayer`」—— **摘掉这道门它照样绿**
                    //   （两条路给的是同一个层数）⇒ 必须有这一条**反档**，两种坏法才分辨得出。
                    // ⚠️ 夹具：往**空槽 2** 塞一个新 `UnitState`（左半场 {3} → {2,3}，仍是「连续无洞」）——
                    //   `SyncBoard` **先按身份找视图**（`byUnit`），新单位找不到 ⇒ 真走 `CardView.Create` 那一支；
                    //   复用旧视图是验不到这一条的。收尾那句 `bak19` 还原会把它带走。
                    {
                        const int probeSlot849 = 2;
                        ctx.Players[me19].Board[probeSlot849] = new UnitState(probe19, false) { Exhausted = false };
                        driver.RefreshAll();
                        var vNew = driver.MyUnits.ContainsKey(probeSlot849) ? driver.MyUnits[probeSlot849] : null;
                        Check(vNew != null,
                              "（夹具）3D 关着时新上场的那个单位**真建了一张新视图** —— 建不出来下面那条等于没验");
                        Check(vNew != null && vNew.gameObject.layer != ArenaSlots.ArenaLayer,
                              $"★ A849：**3D 棋盘关着时，新建的卡视图不许挂 `ArenaLayer`**"
                            + $"（实得 layer {vNew?.gameObject.layer}）—— 那一档 `boardCam` 是 null ⇒ "
                            + "`ArenaLayer` 上**没有任何相机**，挂过去就是整盘卡**静默消失**"
                            + " —— 🧨 改坏法：把 `SyncBoard` 里那句的 `if (use3DBoard)` 去掉、"
                            + "恒 `SetLayer(ArenaLayer)` ⇒ **只有这一条红**（上面 ④ 那条照样绿 = 它的判别式）");
                        // 收尾：把这一格还回去（下面还有「翻回真 3D」那两条，别让探针留在盘上）
                        ctx.Players[me19].Board[probeSlot849] = null;
                        driver.RefreshAll();
                    }
                    driver.use3DBoard = true;
                    pBoard.use3D = eBoard.use3D = true;
                    driver.RefreshAll();
                    Check(v5.gameObject.layer == ArenaSlots.ArenaLayer,
                          $"★ 3D 棋盘那一档：场上卡被搬到 `ArenaLayer`（{ArenaSlots.ArenaLayer}）改由透视相机画"
                        + $"（实得 {v5.gameObject.layer}）—— 🧨 改坏法：删掉 `SyncBoard` 里那句 "
                        + "`if (use3DBoard) v.SetLayer(ArenaSlots.ArenaLayer);` ⇒ 红");
                    Check(Vector3.Distance(v5.transform.localPosition, p5) < 1e-3f,
                          "★ 开关关回去 ⇒ 位姿回到 3D 那一套（本段这次翻转是**可逆的**，不污染后面）");
                    // 🔴 **2026-10-17（B8）结掉 A849**（原来这里记的是「没查清：`SetLayer` 那句单向、
                    //    是不是隐患留给协调者」——**结论 = 不是隐患**，判据如下，别再当悬念）：
                    //    · 「层被改走之后有没有别的路径改回来」—— `SyncBoard` 每次都会给**已经存在的**视图
                    //      重新 `SetLayer(ArenaLayer)`（`RefreshAll` 每次跑都走一遍，幂等）；
                    //      而**关掉 3D 时确实没有任何路径把它改回 `Default`**。
                    //    · **但那半条不可达**：`driver.use3DBoard` 的写点全仓只有三处 ——
                    //      `BuildScene` 里那句（本文件，**在建任何卡视图之前**按 `boardCam != null`
                    //      定死，一次成型）+ 本节的 `driver.use3DBoard = false` / `= true` 两处（自检翻转，且**翻回来了**）。
                    //      运行期没有任何东西会翻它 ⇒ 「留下已经建好的卡在 `ArenaLayer` 上」这一档走不到。
                    //    · ⛔ **也别顺手「补另一半」**（写成 `SetLayer(use3DBoard ? ArenaLayer : 0)`）：
                    //      `CardView.SetLayer` 是**递归**的，`RefreshAll` 每次都会跑 ⇒ 会把模块自己挂在
                    //      卡视图子物体上的层**逐次抹平**（那是一个**新的**静默缺陷，比这条隐患更糟）。
                    //    · 真正该防的是**这道门被摘掉**：那一档在「没有 3D 相机」的兜底构建里**可达** ⇒
                    //      上面那条 `★ A849` 就是钉它的（判别式：摘门 ⇒ 只有它红）。

                    // ---------------- 🆕 2026-10-23（战斗线 · 新账-71）：近战**逐帧按战场深度重算缩放** ----------------
                    // 【判据】原版近战序列的 `OnUpdate`（`decomp_full/CardScript.__c__DisplayClass357_0___AttackMeleeAnim_b__0.c`）
                    //   每帧 `minionScaleByPositionSO.GetScale(isPlayer, localPosition, defaultScale)` → `set_localScale`；
                    //   `MinionScaleByPositionSO__GetScale.c`：`x = isPlayer ? localZ : lastKey.time + localZ`、
                    //   `v = curve.Evaluate(x)`（两端 Clamp）、`scale = 1 × v × (defaultScale.x ÷ 末端键值)`，
                    //   末端 = isPlayer 取 keys[0]、敌方取 keys[last] ⇒ **自家那行系数 1、对面那行 = 两端之比**。
                    //   曲线真件 `MinionScaleByPosition.json` = (0.00281143, 0.36) → (7.6999998, 0.70)。
                    // 【为什么在这里验】本节是全仓**唯一**把 `use3DBoard` 真的翻成 true 的地方，而这条规则**只在**
                    //   3D 战场上有意义（2D 兜底的卡都在 z = 0 的 HUD 正交平面上，套曲线恒得 1.75× = 纯错）。
                    // 【症状】我们原来一次都不算 ⇒ 卡冲到对面那行时**视觉只剩约 55%**、0.1 s 缩下去 0.2 s 涨回来，
                    //   读起来就是用户 2026-10-23 真机点名的「速度很快 / 细节不对 / 不是原版的样子」。
                    {
                        // 曲线两端（**判据本身**，原版那份 SO 实读）—— 下面所有期望值都从这里推，⛔ 不调被测的 helper。
                        const float t3CurveLo = 0.36000001430511475f;      // keys[0].value
                        const float t3CurveHi = 0.699999988079071f;        // keys[1].value
                        const float t3Key0Time = 0.002811431884765625f;
                        const float t3Key1Time = 7.699999809265137f;

                        // ① 纯函数那一档：两侧「自家行 = 1」+「对面行 = 曲线两端之比」
                        float t3OwnMy  = CardFeel.DepthScaleFactor(ArenaSlots.PlayerZ, true);
                        float t3OwnFoe = CardFeel.DepthScaleFactor(ArenaSlots.EnemyZ, false);
                        float t3FoeRow = CardFeel.DepthScaleFactor(ArenaSlots.EnemyZ, true);
                        float t3MyRow  = CardFeel.DepthScaleFactor(ArenaSlots.PlayerZ, false);
                        Check(Mathf.Abs(t3OwnMy - 1f) < 1e-4f && Mathf.Abs(t3OwnFoe - 1f) < 1e-4f,
                              $"★ 新账-71：**在自家那一行上，深度缩放系数恒 = 1**（我方 {t3OwnMy:F5} · 敌方 {t3OwnFoe:F5}）"
                            + " —— 原版 `GetScale` 归一化除的是「末端键值」，而两端键值**各自**对应一行"
                            + "｜🧨 归一化除错了键（两侧都除 keys[0] = 0.36）⇒ 敌方那半条红（会得 0.514/0.36 = 1.43）");
                        Check(Mathf.Abs(t3FoeRow - t3CurveHi / t3CurveLo) < 5e-3f
                           && Mathf.Abs(t3MyRow - t3CurveLo / t3CurveHi) < 5e-3f,
                              $"★ ……而**到了对面那一行**系数就是曲线两端之比：我方冲过去 {t3FoeRow:F4}"
                            + $"（期望 {t3CurveHi / t3CurveLo:F4} = 0.70/0.36）、敌方冲过来 {t3MyRow:F4}"
                            + $"（期望 {t3CurveLo / t3CurveHi:F4}）"
                            + "｜🧨 丢了 `isPlayer` 分支（两侧都按 `x = localZ`）⇒ 敌方那半条红（会得 1.0）");
                        // ★ 灭自证：把上面两条**都写成常数 1** 也能过前一半 —— 这一条要求两侧**真的不对称**
                        //   （我方冲出去是放大 1.94×、敌方冲过来是缩小 0.51×，原版 `GetScale` 的符号就是这么反的）。
                        Check(t3FoeRow > t3MyRow + 1f,
                              $"★ ……而且两侧**不对称**（我方冲 {t3FoeRow:F3} vs 敌方冲 {t3MyRow:F3}，差 {t3FoeRow - t3MyRow:F3}）"
                            + " —— 这一条是**灭自证**：「系数恒 1」或「两侧同式」都满足不了它");

                        // ---- 🆕 2026-10-23（账 `新账-76②`）：**第三处 / 第四处调用点已接线** ----
                        //   原版 `MinionScaleByPositionSO.GetScale` 全仓 5 个调用点，我们原先只接了 2 处
                        //   （`CardFeel.MeleeAttack` / `AttackRecover`）。本节钉剩下两处：
                        //     · 第三处 = 技能动画位移（`CardScript…MoveAndDisappearAnim_b__1/b__4`）
                        //       → 我们这一侧 `Card3DAnimationController` 的逐帧 tick；
                        //     · 第四处 = AnimFX 模块（`AnimFXModuleTransformModifier__Update.c` 第 2 支）
                        //       → `WFModuleTransformModifier.updateScaleByBoardPosition`。
                        //   ⛔ 别把断言写成「字段在」—— 两条都要求**缩放值真的变了**。
                        {
                            // ---- 第四处：AnimFX 模块 ----
                            var t3ModGo = new GameObject("新账76_模块探针");
                            t3ModGo.layer = ArenaSlots.ArenaLayer;     // 只有 3D 战场上的卡才吃这条
                            t3ModGo.transform.position = new Vector3(0f, 0f, ArenaSlots.EnemyZ);
                            var t3Mod = t3ModGo.AddComponent<WarpforgeVFX.WFModuleTransformModifier>();
                            t3Mod.updateScaleByBoardPosition = true;
                            t3Mod.cardTarget = t3ModGo.transform;     // 没有 `CardView` ⇒ 走直写 `localScale` 那一支
                            t3Mod.cardIsPlayer = true;                // 我方卡**站在对面那一行** ⇒ 系数 = 0.70/0.36
                            t3Mod.originalScale = Vector3.one * t3CurveLo;
                            t3Mod.boardScaleBase = t3CurveLo;
                            WarpforgeVFX.WFModuleTransformModifier.ResetDiagnostics();
                            t3Mod.ModuleTick(1f / 60f);
                            float t3ModWant = t3CurveLo * (t3CurveHi / t3CurveLo);
                            Check(WarpforgeVFX.WFModuleTransformModifier.BoardScaleApplied == 1
                                  && WarpforgeVFX.WFModuleTransformModifier.SkippedBoardScale == 0
                                  && Mathf.Abs(t3ModGo.transform.localScale.x - t3ModWant) < 1e-3f,
                                  $"★ 新账-76②（第四处 · AnimFX 模块）：`updateScaleByBoardPosition` **真的算了** —— "
                                + $"探针在对面那一行、`isPlayer=true` ⇒ localScale {t3ModGo.transform.localScale.x:F4}"
                                + $"（期望 {t3ModWant:F4}）；Applied {WarpforgeVFX.WFModuleTransformModifier.BoardScaleApplied}"
                                + $"/ Skipped {WarpforgeVFX.WFModuleTransformModifier.SkippedBoardScale}"
                                + "｜🧨 退回 `SkippedBoardScale++`（不接线）⇒ Applied 变 0、Skipped 变 1，本条红");
                            // 灭自证：把探针搬回**自家那一行** ⇒ 系数必须回到 1（证明用的是 `isPlayer`+行 z，不是常数乘）
                            t3ModGo.transform.position = new Vector3(0f, 0f, ArenaSlots.PlayerZ);
                            t3Mod.ModuleTick(1f / 60f);
                            Check(Mathf.Abs(t3ModGo.transform.localScale.x - t3CurveLo) < 1e-4f
                                  && WarpforgeVFX.WFModuleTransformModifier.SkippedBoardScale2D == 0,
                                  $"★ ……而搬回**自家那一行**后缩放回到静止值 {t3ModGo.transform.localScale.x:F5}"
                                + $"（期望 {t3CurveLo:F5}）｜🧨 拿常数系数乘（不传 `isPlayer` / 不减本行 z）⇒ 本条红");
                            // 灭自证 · 适用范围：**2D 兜底布局**（不在 Arena 层）的卡一个字节都不许改
                            //   （套曲线恒得 1.75× = 纯错；判据 = `CardFeel` 那节的门）。
                            t3ModGo.layer = 0;
                            t3ModGo.transform.position = new Vector3(0f, 0f, ArenaSlots.EnemyZ);
                            int t3Before2D = WarpforgeVFX.WFModuleTransformModifier.BoardScaleApplied;
                            t3Mod.ModuleTick(1f / 60f);
                            Check(WarpforgeVFX.WFModuleTransformModifier.BoardScaleApplied == t3Before2D
                                  && WarpforgeVFX.WFModuleTransformModifier.SkippedBoardScale2D == 1
                                  && Mathf.Abs(t3ModGo.transform.localScale.x - t3CurveLo) < 1e-4f,
                                  "★ ……而**不在 3D 战场**（层 0）的卡**一次都不写** —— "
                                + $"Applied {WarpforgeVFX.WFModuleTransformModifier.BoardScaleApplied}（应停在 {t3Before2D}）· "
                                + $"Skipped2D {WarpforgeVFX.WFModuleTransformModifier.SkippedBoardScale2D}（应 1）· "
                                + $"缩放 {t3ModGo.transform.localScale.x:F5}｜🧨 删掉 `IsArenaCard` 那道门 ⇒ "
                                + "2D 兜底布局的卡会被套上恒 1.75× 的曲线（原版没有的事）");
                            Object.DestroyImmediate(t3ModGo);

                            // ---- 第三处：技能动画位移（`Card3DAnimationController` 逐帧 tick） ----
                            var t3CtlGo = new GameObject("新账76_技能动画探针");
                            t3CtlGo.layer = ArenaSlots.ArenaLayer;
                            t3CtlGo.transform.position = new Vector3(0f, 0f, ArenaSlots.EnemyZ);
                            var t3Ctl = new Card3DAnimationController(t3CtlGo.transform);
                            bool t3Stated = t3Ctl.DoAnim(new CardAnimPlayback
                            {
                                Prefab = "新账76_探针",
                                Duration = 0.5f,
                                Label = "probe/新账76",
                                DepthScaleByBoardPosition = true,      // 原版 `MoveAndDisappearAnim` 那一拍
                                DepthScaleIsPlayer = true,
                            }, disableFlying: false, onAnimationEnd: null, safeResetOnEnd: false);
                            Check(t3Stated && t3Ctl.Enabled,
                                  "（前提）技能动画探针起播了（`DoAnim` 返回 true、`Enabled`）");
                            t3Ctl.Update(1f / 60f);
                            float t3CtlWant = 1f * (t3CurveHi / t3CurveLo);   // 底数 = 起播时的 localScale.x = 1
                            Check(t3Ctl.DepthScaleWrites == 1
                                  && Mathf.Abs(t3CtlGo.transform.localScale.x - t3CtlWant) < 1e-3f,
                                  $"★ 新账-76②（第三处 · 技能动画位移）：演的那一拍**逐帧按深度重算卡自己的缩放** —— "
                                + $"localScale {t3CtlGo.transform.localScale.x:F4}（期望 {t3CtlWant:F4}）、"
                                + $"写过 {t3Ctl.DepthScaleWrites} 次｜🧨 把 `Card3DAnimationController.Update` 里"
                                + "那句 `if (_depthScale) ApplyDepthScaleTick();` 删掉 ⇒ 0 次、缩放停在 1，本条红");
                            t3Ctl.Update(1f);      // 推到收尾 ⇒ 复位
                            Check(Mathf.Abs(t3CtlGo.transform.localScale.x - 1f) < 1e-4f && !t3Ctl.Enabled,
                                  $"★ ……演完把缩放**写回静止值**（现在 {t3CtlGo.transform.localScale.x:F4}，"
                                + $"期望 1；`Enabled` = {t3Ctl.Enabled}）｜🧨 不在 `AnimFinished` 复位 ⇒ 卡会停在放大态");
                            Object.DestroyImmediate(t3CtlGo);
                        }

                        // ② 端到端：拿这张**真站在 3D 我方行上**的卡跑完整条近战序列，逐帧看缩放
                        var cardT3 = v5;
                        float t3Base = cardT3.BaseScale;                     // 静止缩放（量出来的，⛔ 不写死 0.36）
                        Vector3 t3Home = cardT3.transform.localPosition;
                        Check(Mathf.Abs(cardT3.transform.position.z - ArenaSlots.PlayerZ) < 1e-3f,
                              $"（夹具）这张卡站在**我方那一行**上（世界 z {cardT3.transform.position.z:F3} vs "
                            + $"`ArenaSlots.PlayerZ` {ArenaSlots.PlayerZ:F3}）—— 不在这一行，「深度」就没有基准可言");
                        // 目标点 = 对面督军位那一格（同一套生产函数算，⛔ 不手搓坐标）
                        Vector3 t3TargetPos = ArenaSlots.RootPosition(ArenaSlots.WarlordSlot, true,
                                                                     ArenaSlots.CardScale(true));
                        Vector3 t3End = CardFeel.MeleeEndPos(t3Home, t3TargetPos, true);
                        float t3EndZ = t3End.z;                              // boardRoot 恒等 ⇒ local == world
                        // 期望值：**独立照原版 `GetScale` 重写一遍**（曲线两键 + 除 keys[0]），⛔ 不调 CardFeel 的 helper
                        float t3X = t3EndZ - ArenaSlots.PlayerZ;
                        float t3V = t3CurveLo + (t3CurveHi - t3CurveLo)
                                  * Mathf.Clamp01((t3X - t3Key0Time) / (t3Key1Time - t3Key0Time));
                        float t3Want = t3Base * (t3V / t3CurveLo);
                        var twT3 = CardFeel.MeleeAttack(cardT3.transform, t3End, t3Home);
                        Check(twT3 != null, "（夹具）近战序列建出来了 —— 建不出来下面全是空跑（⛔ 不静默跳过）");
                        Check(Mathf.Abs(cardT3.transform.localScale.x - t3Base) < 1e-3f,
                              $"★ 出手**那一帧**缩放还是静止值 {t3Base:F4}（实测 {cardT3.transform.localScale.x:F4}）"
                            + " —— 原版 `OnUpdate` 在自家那行上给的就是 defaultScale（系数 1）"
                            + "｜🧨 把系数写成「恒 1.94」（只算对面那一端的常数）⇒ 本条当场红");
                        CardTween.Advance(CardFeel.AttackStepTime * 0.5f);    // 段1 走到一半（分两步推，见下）
                        CardTween.Advance(CardFeel.AttackStepTime * 0.5f);    // → t = 0.1：段1 结束、撞到目标点
                        float t3S1 = cardT3.transform.localScale.x;
                        // 采样点刻意取**段1 末尾**：位置已经恒为 `t3End`（段3 整整 0.1 s 不动它），
                        // ⚠️ 但上界留 1.001% 余量 —— 「DOTween 是先落位再回调」这件事不该由断言来赌：
                        //    若哪天真反了，这里读到的是半途值（仍然 > 1.05×），③ 那条会照旧精确验终值。
                        Check(t3S1 > t3Base * 1.05f && t3S1 < t3Want * 1.001f,
                              $"★ 新账-71：**段1 就已经在按深度放大**（t=0.1 时 {t3S1:F4} = {t3S1 / t3Base:F3}× 静止值，"
                            + $"终值 {t3Want:F4}）—— 原版是**逐帧**按当前位置重算，不是到最后一下再跳"
                            + "｜🧨 只在 OnComplete 里改一次缩放 ⇒ 这里恒 1.00× ⇒ 红");
                        CardTween.Advance(CardFeel.AttackHoldTime);           // → t = 0.2：段3（停在目标身上）结束
                        float t3HoldZ = cardT3.transform.position.z;
                        float t3HoldS = cardT3.transform.localScale.x;
                        Check(Mathf.Abs(t3HoldZ - t3EndZ) < 1e-2f,
                              $"（夹具）段1 走完之后卡已停在目标点（z {t3HoldZ:F3} vs 期望 {t3EndZ:F3}）"
                            + " —— 这一条不成立，下面的期望值就无从谈起");
                        Check(t3HoldS > t3Base * 1.5f && t3HoldS < t3Base * 1.95f,
                              $"★ ……而撞到对面那一行时，局部缩放**放大到静止值的 1.5～1.95 倍**"
                            + $"（静止 {t3Base:F4} → 实测 {t3HoldS:F4} = {t3HoldS / t3Base:F3}×）"
                            + " —— 原版靠这一下**抵消透视**（敌方那一行 86.2 px/单位 vs 我方 182.14）"
                            + "｜🧨 一次都不算（恒 `desiredScale`）⇒ 读数 1.00× ⇒ 红");
                        Check(Mathf.Abs(t3HoldS - t3Want) < 2e-3f,
                              $"★ ……而且**就是照那条曲线算出来的那个数**（实测 {t3HoldS:F5} vs 判据 {t3Want:F5}，"
                            + $"差 {Mathf.Abs(t3HoldS - t3Want):E2}）"
                            + " —— 期望值在测试里**独立重写了一遍** `MinionScaleByPosition.GetScale`"
                            + "｜🧨 曲线端点 / 分母（除 keys[0] 还是 keys[1]）/ 方向任一处写错 ⇒ 这里红");
                        // ★ 成对判别式（把上面三条合成一句）：常数**取哪一端都过不了** ——
                        //   取 1.0 ⇒ 「出手那一帧」那条绿、「段1/停住」两条红；取 1.94 ⇒ 反过来。

                        // ③ 必须**经 `CardView` 的口**写：`_baseScale` 要跟着变（不是只写 transform.localScale）
                        Check(Mathf.Abs(cardT3.transform.localScale.x - cardT3.BaseScale * cardT3.HighlightMul) < 1e-3f
                           && cardT3.BaseScale > t3Base * 1.4f,
                              $"★ ……而且写的是 **`CardView` 的基础缩放**（`BaseScale` {cardT3.BaseScale:F4} × "
                            + $"高亮 {cardT3.HighlightMul:F3} = `localScale` {cardT3.transform.localScale.x:F4}）"
                            + " —— 直接写 `transform.localScale` 的话 `_baseScale` 会停在旧值上，"
                            + "之后任何一次 `SetPose` / `SetHighlightScale` 都会把卡**弹回旧尺寸**（静默）"
                            + "｜🧨 绕过 `CardView.SetBaseScale` 直接写 `transform.localScale` ⇒ 本条红");

                        // ④ 收招归位 ⇒ 回到静止缩放
                        CardTween.Advance(CardFeel.AttackReturnTime + 0.05f);  // → t = 0.45：段4/段5 归位
                        Check(Vector3.Distance(cardT3.transform.localPosition, t3Home) < 1e-3f,
                              $"（夹具）整条序列回到了静止位（偏差 {Vector3.Distance(cardT3.transform.localPosition, t3Home):E2}）");
                        Check(Mathf.Abs(cardT3.transform.localScale.x - t3Base) < 1e-3f
                           && Mathf.Abs(cardT3.BaseScale - t3Base) < 1e-3f,
                              $"★ 收招回到自家那行 ⇒ 缩放**回到静止值** {t3Base:F4}"
                            + $"（实测 localScale {cardT3.transform.localScale.x:F4} / BaseScale {cardT3.BaseScale:F4}）"
                            + " —— 系数在自家行上恒 1；回不去 = 基准算错、或收尾没复位"
                            + "｜🧨 记错了 baseScale（拿每帧被改写后的值当基准）⇒ 复利放大 ⇒ 这里红");

                        // ⑤ 反档：**不在 3D 战场上的卡**（HUD 层）不许按深度改缩放
                        //   判据 = 挂没挂 `ArenaSlots.ArenaLayer`（`SyncBoard` 按 `use3DBoard` 决定，同族 A849 那条钉着）
                        cardT3.SetLayer(0);                                    // 只翻这张卡（棋盘与相机不动）
                        cardT3.SetPose(t3Home, 0f, t3Base);
                        var twT3b = CardFeel.MeleeAttack(cardT3.transform, t3End, t3Home);
                        Check(twT3b != null, "（夹具）反档那条序列也建出来了");
                        CardTween.Advance(CardFeel.AttackStepTime);
                        CardTween.Advance(CardFeel.AttackHoldTime);
                        Check(Mathf.Abs(cardT3.transform.localScale.x - t3Base) < 1e-3f,
                              $"★ 反档：**HUD 层（不在 3D 战场）的卡不按深度改缩放**"
                            + $"（实测 {cardT3.transform.localScale.x:F4} vs 静止 {t3Base:F4}）"
                            + " —— 那一档的卡都躺在 z = 0 的正交平面上，套曲线恒得 1.75× = 纯错"
                            + "｜🧨 把 `IsArenaCard` 这道门摘掉 ⇒ 本条红，而上面 ②③ 照样绿（= 它的判别式）");
                        CardTween.Advance(CardFeel.AttackReturnTime + 0.05f);
                        cardT3.SetLayer(ArenaSlots.ArenaLayer);                 // 还原层
                        cardT3.SetPose(t3Home, 0f, t3Base);

                        // ⑥ 共用同一份曲线：`Reassemble`（让位/补位）也得吃它
                        //   ⚠️ 同行让位 z 不变 ⇒ 系数恒 1，验不出东西；所以这里给一个**跨行**的目标位
                        //      （横向让位不会跨行，这一条是**直接测 API**，不是模拟真实让位）。
                        Vector3 t3Cross = new Vector3(t3Home.x, t3Home.y, ArenaSlots.EnemyZ);
                        var twT3r = CardFeel.Reassemble(cardT3, t3Cross);
                        Check(twT3r != null, "（夹具）让位补间建出来了");
                        CardTween.Advance(CardFeel.ReassembleTime * 0.25f);   // 分两步推，理由同 ② 的上界
                        CardTween.Advance(CardFeel.ReassembleTime * 0.25f);
                        Check(cardT3.transform.localScale.x > t3Base * 1.15f,
                              $"★ 新账-71：`CardFeel.Reassemble` **共用同一条深度曲线**（跨行补间走到一半时"
                            + $" 缩放到 {cardT3.transform.localScale.x:F4} = {cardT3.transform.localScale.x / t3Base:F2}× 静止值）"
                            + " —— 原版那条 `DOLocalMove` 也挂在**同一个** `Sequence.OnUpdate` 上"
                            + "｜🧨 只给 `MeleeAttack` 挂、`Reassemble` 不挂 ⇒ 这里恒 1.00× ⇒ 红");
                        CardTween.Advance(CardFeel.ReassembleTime + 0.05f);
                        Check(Mathf.Abs(cardT3.transform.localScale.x - t3Base) < 1e-3f,
                              $"★ ……收尾回到静止缩放 {t3Base:F4}（实测 {cardT3.transform.localScale.x:F4}）");
                        cardT3.SetPose(t3Home, 0f, t3Base);                    // 探针收尾：位姿/缩放还原

                        // ---------------- 🆕 2026-10-23（`新账-82①`）：`isPlayer` 必须**显式传**（源码普查）----------------
                        // 【判据】`CardFeel.MeleeAttack` / `AttackRecover` 的 `isPlayer` 形参 doc 原话：
                        //   「不传 ⇒ 按静止位离哪一行近来判（`IsPlayerRow`）…… 调用点**知道得准**就显式传
                        //     （⛔ 别在别处再写第二份推断）」；而 `CardFeel.IsPlayerRow` 自己的 doc 也写着
                        //   「给**没有 `isPlayer` 可传的**调用点兜底」。
                        //   `BattleDriver` 那三个生产调用点**明明知道** `e.Player == _me` —— 原来三处都只传三个实参。
                        // 【为什么用源码普查】这一位**不改变任何返回值**（今天 `IsPlayerRow` 判得对：
                        //   两行 z 差 7.698、督军偏移只占 6%）⇒ 行为断言抓不到它，只有「调用点有没有传」能判。
                        //   ⛔ 别用行号当判据（行号会漂）。
                        {
                            string drvPath82 = System.IO.Path.Combine(Application.dataPath,
                                                                      "CardPresentation/Battle/BattleDriver.cs");
                            Check(System.IO.File.Exists(drvPath82),
                                  $"★ 新账-82①（前提）：读得到 `{drvPath82}` —— 读不到下面这条就是空跑");
                            if (System.IO.File.Exists(drvPath82))
                            {
                                string src82 = System.IO.File.ReadAllText(drvPath82);
                                string[] heads82 = { "CardFeel.MeleeAttack(", "CardFeel.AttackRecover(" };
                                int calls82 = 0, with82 = 0;
                                var bad82 = new List<string>();
                                for (int h82 = 0; h82 < heads82.Length; h82++)
                                {
                                    int idx82 = 0;
                                    while (true)
                                    {
                                        idx82 = src82.IndexOf(heads82[h82], idx82, System.StringComparison.Ordinal);
                                        if (idx82 < 0) break;
                                        // 注释里的提法不算调用点（那一行 `//` 之前只有空白）
                                        int ls82 = src82.LastIndexOf('\n', idx82) + 1;
                                        string lead82 = src82.Substring(ls82, idx82 - ls82).TrimStart();
                                        if (lead82.StartsWith("//", System.StringComparison.Ordinal))
                                        { idx82 += heads82[h82].Length; continue; }
                                        int st82 = idx82 + heads82[h82].Length;
                                        int depth82 = 1, j82 = st82;
                                        while (j82 < src82.Length && depth82 > 0)
                                        {
                                            char c82 = src82[j82];
                                            if (c82 == '(') depth82++;
                                            else if (c82 == ')') depth82--;
                                            j82++;
                                        }
                                        string args82 = src82.Substring(st82, Mathf.Max(0, j82 - 1 - st82));
                                        calls82++;
                                        if (args82.IndexOf("isPlayer:", System.StringComparison.Ordinal) >= 0) with82++;
                                        else
                                        {
                                            int ln82 = 1;
                                            for (int q82 = 0; q82 < idx82; q82++) if (src82[q82] == '\n') ln82++;
                                            bad82.Add(ln82 + ": " + args82.Replace("\r", " ").Replace("\n", " ").Trim());
                                        }
                                        idx82 = j82;
                                    }
                                }
                                Check(calls82 == 3,
                                      $"★ 新账-82①：`BattleDriver` 里 `CardFeel.MeleeAttack` / `CardFeel.AttackRecover` 的"
                                    + $"生产调用点**恰好 3 处**（远程 `AttackRecover` · 近战 `MeleeAttack` · "
                                    + $"反击 `AttackRecover`；实得 {calls82}）—— 这条是下一条的**非空前提**"
                                    + "｜🧨 换了方法名 / 挪了文件 ⇒ 这里先红（⛔ 别让普查静默扫到 0 处就绿）");
                                Check(calls82 > 0 && with82 == calls82,
                                      $"★ 新账-82①：这 {calls82} 处**都显式传了 `isPlayer:`**（传了 {with82} 处）"
                                    + (bad82.Count == 0 ? "" : " —— 没传的：" + string.Join(" | ", bad82.ToArray()))
                                    + "｜🧨 任一处改回三实参 ⇒ 本条红；而且**运行时静默**"
                                    + "（`IsPlayerRow` 今天判得对，任何行为断言都抓不到）");
                            }
                        }
                    }
                }
                        
                        // ---------------- 🆕 2026-10-23（`新账-82⑤`）：`bloodThirstFrame` 那一层**判据为空**（源码普查 · 灭自证）----------------
                        // 【判据】`CardScript__FinishAfterAttack.c:85-104` 的嗜血高亮 → `CardScript.HighlightBloodThirst`
                        //   → `BattleCardUI.HighlightBloodThirst`（`BattleCardUI__HighlightBloodThirst.c:15-31`）= 拿 `ui+0x268`
                        //   （= `bloodThirstFrame`）的 `GetComponentInChildren<SpriteRenderer>()` 做
                        //   `DOFade(0, 0.3).SetLoops(6, Yoyo).SetEase(22)`（0.3 实读 `0x1834b2dc8`）。
                        //   而那个字段：`il2cpp_out/dump.cs:26221` **没有 `[SerializeField]`**、`BattleCardUI` 的全部方法（`BattleCardUI__*.c` 81 个 + 嵌套迭代器）里
                        //   **写点 0 处**（同族 `ShowOath:62` / `ShowCodex:62` / `ShowEphemeral:65` / `ShowStealth:65` /
                        //   `SetAsMulliganSelected:76` 都**有**写点，可作对照）、`CardPrefab.prefab` 里也**没有那个子节点**
                        //   ⇒ 原版这一支**恒早退、不产生任何画面**（铁律 11 例外①）。
                        // 【为什么断言这两条】① 卡上**不许**出现 `bloodThirstFrame` —— 加了就是**自造美术**（贴图 / 尺寸 /
                        //   颜色 / 队列全无判据）；② `BattleDriver` 里那段判据注释**必须在** —— 它没了，下一个人会照旧账再开一轮。
                        //   🧨 两条互为判别式：**旧状态**（没层也没注释）红第 ② 条 · **自造状态**（有层）红第 ① 条。
                        {
                            string cvPath82e = System.IO.Path.Combine(Application.dataPath, "CardPresentation/Core/CardView.cs");
                            string drvPath82e = System.IO.Path.Combine(Application.dataPath, "CardPresentation/Battle/BattleDriver.cs");
                            Check(System.IO.File.Exists(cvPath82e) && System.IO.File.Exists(drvPath82e),
                                  "★ 新账-82⑤（前提）：读得到 `Core/CardView.cs` 与 `Battle/BattleDriver.cs` —— 读不到下面两条就是空跑");
                            if (System.IO.File.Exists(cvPath82e) && System.IO.File.Exists(drvPath82e))
                            {
                                string cvSrc82e = System.IO.File.ReadAllText(cvPath82e);
                                string drvSrc82e = System.IO.File.ReadAllText(drvPath82e);
                                Check(cvSrc82e.IndexOf("bloodThirstFrame", System.StringComparison.Ordinal) < 0,
                                      "★ 新账-82⑤：`CardView` 上**没有** `bloodThirstFrame` 那一层（原版那个字段从没人赋值 ⇒ 判据为空）"
                                    + "｜🧨 谁给卡面自造这一层 ⇒ 本条红 —— 先拿反编译把「谁给它赋值」查出来再动");
                                Check(drvSrc82e.IndexOf("bloodThirstFrame", System.StringComparison.Ordinal) >= 0
                                   && drvSrc82e.IndexOf("0x268", System.StringComparison.Ordinal) >= 0
                                   && drvSrc82e.IndexOf("判据为空", System.StringComparison.Ordinal) >= 0,
                                      "★ 新账-82⑤：`BattleDriver` 里那段判据（`bloodThirstFrame` / `+0x268` / 判据为空）在位"
                                    + "｜🧨 删掉那段注释 ⇒ 本条红（否则下一个人会照旧账再开一轮「补那一层」）");
                            }
                        }

                // 收尾：棋盘还原 + `animateFeel` / `DropAccepted` 关回去（后面还有收尾与 `CheckSavedScene`）
                for (int s = 0; s < BoardSpec.Size; s++) ctx.Players[me19].Board[s] = bak19[s];
                if (driver.interaction != null) driver.interaction.DropAccepted = false;
                driver.animateFeel = feelWas19;
                driver.RefreshAll();
            }

        // ============================================================
        //  🆕 2026-10-17（B29）：**教程局**（`MatchType.Tutorial = 100`）—— 引擎侧那六条开关 + 白名单闸门
        // ============================================================
        //  判据全文（原版逐跳时序 + 字段偏移交叉验证）→ `资料/普查产出_1017/W_B29_教程执行器.md`
        //  与 `资料/普查产出_1017/W_B9_教程关卡数据.md`：
        //   · **不洗牌** = `MatchData.ShouldShuffleDeck(100) == false`（`PlayerHand` 那一路另有 `param_3 != 0` 覆盖）
        //   · **先手** = `BattleManager.GetPlayerGoesFirst` 的 `matchType == 100` 那一支 → `TutorialStage.playerStarts`（`+0x28`）
        //   · **起手卡** = `BattleManager.CreatePlayerDeck`（InHand 插牌库顶 → 抽 N 张）
        //   · **起始单位** = `BattleManager.SetupStartingTroops`；**初始法力/伤害** = `SetupInitialMana`（6 关四值全 0）
        //   · **白名单闸门** = `CheckIfPlayerActionPermittedInTutorial` + `ScriptedActionData.CheckIfMatchesActionData`
        //   · **`playerAlwaysWins`** = `GetWinnerAfterBattleEnd`（**战斗结束那一刻**覆盖赢家）
        //  ⚠️ 期望值一律朝**原版事实**（关卡数据 / 反编译那两条算式）取，⛔ 不朝我们自己的常量取。
        //  ⚠️ 这一段会**多次 `driver.BeginTutorial(...)`**（重开一局在本文件里是常规操作，见上面那一串 `driver.Begin`），
        //     收工时 driver 停在「第 5 关」那一局上 —— 它后面只剩收尾那两格设置的复位，不读对局状态。
        {
            Debug.Log(P + "--- 教程局（`MatchType.Tutorial 100`，B29）---");

            // ⚠️ `tutDecks` 必须在本地函数**声明之前**落地（C# 局部变量不能被「先用后声明」捕获）
            BattleDriver.TutorialDecksFileDto tutDecks = null;

            string TutDeckIds(PlayerState ps)
            {
                var sb = new List<string>();
                for (int i = 0; i < ps.Deck.Count; i++) sb.Add(ps.Deck[i].Card.Id);
                return string.Join("/", sb);
            }
            string TutHandIds(PlayerState ps)
            {
                var sb = new List<string>();
                for (int i = 0; i < ps.Hand.Count; i++) sb.Add(ps.Hand[i].Card.Id);
                return string.Join("/", sb);
            }
            int TutBoardUnits(PlayerState ps)
            {
                int n = 0;
                for (int i = 0; i < ps.Board.Length; i++) if (ps.Board[i] != null && !ps.Board[i].IsWarlord) n++;
                return n;
            }
            BattleDriver.TutorialDeckStageDto TutStageDeck(int stageNumber)
            {
                if (tutDecks == null || tutDecks.stages == null) return null;
                for (int i = 0; i < tutDecks.stages.Length; i++)
                    if (tutDecks.stages[i] != null && tutDecks.stages[i].stage == stageNumber) return tutDecks.stages[i];
                return null;
            }

            /// <summary>🆕 2026-10-18（`Z6` 收口 · 修「教程脚本推进 21 红」· R1）：**「推一步」= 驱动执行器
            /// + 替玩家把 `waitForTip` 那条提示点掉**。
            ///
            /// 🔴 **为什么必须成对**：本批 `Z6` 让 `DriveTutorialScript` 在提示挂着时
            /// `if (_tutTipUp) return TutorialStep.Advanced;`（`BattleDriver.cs` 的 `if (_tutTipUp) return TutorialStep.Advanced;`（🔴 **按内容找，别按行号** —— 2026-10-18 实测在 `:8656`，本批加日志后从 8649 漂过来的（独立审查 `REV_W_四写手.md` F1）；**逐字照原版**
            /// `_ExecuteScriptedTurn_d__597:252-264` 那个 `+0x430` 自旋 ⇒ ⛔ 那一句**不许动**），
            /// 而批处理**没有帧循环**（`TickTutorialView` 只由 `Update` 喂 dt）**也没有真鼠标**
            /// ⇒ `_tutTipUp` 一旦为真**再也不会变假** ⇒ 脚本**原地不动**，后面每一条断言都在读
            /// 一个「指针停在原地」的局面（诊断 → `资料/普查产出_1018/DC_教程推进21红.md` R1，20/21 条）。
            /// 提示消掉的那一下 = 原版 `TutorialTipScript.Update` 里那一下左键；
            /// `force = true` 跳过 `minTimeBeforeSkip`（自检不喂真时钟）。
            ///
            /// ⚠️ ⛔ **别拿它换掉「就是要看提示挂着」那两条**（⑭⑥ 里读 `ov.TipVisible` / `ov.TipText` 的
            /// `Check(ov.TipVisible, …)`）—— 那里要留一个**没被点掉**的提示；那一处用裸驱动 + 看完再显式点掉。</summary>
            BattleDriver.TutorialStep DriveStep()
            {
                var s = driver.DriveTutorialScriptForTest();
                if (driver.TutorialWaitingForTip) driver.DismissTutorialTipForTest(true);
                return s;
            }

            // ---- 0. 数据装上了吗（装不上 ⇒ 下面每一条都会是假红，先说清）----
            var tutStages = TutorialData.Stages;
            Check(tutStages.Length == 6, $"（前提）教程关卡数据 **6 关**装上了（实得 {tutStages.Length}）"
                + " —— 判据 = `Resources/tutorial_stages.json`（`gen_tutorial_stages.py` 生成）");
            var tutDecksAsset = Resources.Load<TextAsset>(BattleDriver.TutorialDecksAssetPath);
            Check(tutDecksAsset != null, $"（前提）`Resources/{BattleDriver.TutorialDecksAssetPath}.json` 装上了"
                + "（那 12 副关卡牌在那儿 —— `prebuilt_decks.json` 是 103 副 `isPractice==1` 的池子，**不含教程**）");
            tutDecks = tutDecksAsset == null ? null
                     : JsonUtility.FromJson<BattleDriver.TutorialDecksFileDto>(tutDecksAsset.text);

            if (tutStages.Length == 6)
            {
                bool orderOk = true;
                for (int i = 0; i < 6; i++) if (tutStages[i] == null || tutStages[i].stage != i + 1) orderOk = false;
                Check(orderOk, "（前提）`tutorialIndex` 0..5 ↔ 关号 1..6 **一一对应**（`TutorialData.ByIndex` 的契约）");

                // ------------------------------------------------------------
                //  ① **不洗牌** + ② **先手照关卡**（S1 `playerStarts = true`）
                // ------------------------------------------------------------
                driver.BeginTutorial(0);
                var cT1 = driver.Ctx;
                Check(cT1 != null && cT1.Tutorial != null && cT1.Tutorial.Stage.stage == 1,
                      "`BeginTutorial(0)` ⇒ 第 1 关的关卡数据进了 `ctx.Tutorial`（一局一个执行器实例）");
                Check(cT1.PlayMode == GameMode.Tutorial && cT1.MatchType == RuleEngine.MatchType.Tutorial,
                      "★ 模式号 = `Tutorial(4)`（原版 `PlayModes.Tutorial`）⇒ 派生出 `MatchType.Tutorial(100)`"
                    + "（`MatchTypes.For` 那张 14 项表；原版 `MatchData..ctor` 就是拿 `playMode` 查表）");
                Check(cT1.FirstSeat == 0, "★ 第 1 关 `playerStarts = true` ⇒ **玩家先手**"
                    + "（原版 `GetPlayerGoesFirst` 的 `matchType == 100` 那一支；⛔ 教程**不掷硬币**）");

                // 牌库顺序 == `tutorial_decks.json` 里那份（**没洗**）。
                // 🔴 判据选 **S1**：它的 `playerStartingTroopsInHand` 是**空的** ⇒ 起手那一段一张都不动牌库，
                //    「牌库 == 关卡给的那份顺序」这句话才没有别的解释。🧨 把 `NewBattle` 里那句
                //    `shuffle = false` 删掉 ⇒ 本条红（30 张以内洗一次，顺序几乎不可能照旧）。
                //   🔴 **2026-10-19（G-3）再订正**：`dontDrawCard` 闸接上后，**S1 第 1 回合按关卡数据一张都不抽**
                //      （原版 `TurnStartCardDraw.c:13-15`）⇒ 下面「抽 1 张」的旧口径作废；断言改成
                //      「抽过 **或**（第一回合脚本 `dontDrawCard` 且实抽 0 张）」。
                //   🔴 **2026-10-17（F6 #8）更正期望值**：原来断的是「牌库 == `cardIds` **全表、逐字相等**」——
                //    **漏算了「先手第 1 回合抽 1 张」**：`BattleDriver.Begin` 在教程这一支
                //    （`showMulligan = false`）直接 `RuleCore.BeginTurn`，而它开头就是 `Draw`
                //    （`Core/RuleCore.cs:759-761`）；`Draw` 从**末尾**抽（`int last = ps.Deck.Count - 1`，
                //    `RuleCore.cs:1051`）⇒ **牌库顶 = 数组末尾**，牌库 = `cardIds` 去掉末尾若干项。
                //    ⇒ 改成「**牌库 == `cardIds` 的前缀**（逐项同序）」+「少掉的那几项**在手牌里**」：
                //      两条合起来仍然钉死「没洗过」（洗过牌 ⇒ 前缀关系必破 ⇒ 照样红），
                //      而且**不写死「少 1 张」**（抽几张是引擎的事）。
                //    ⚠️ 本条**不能**当「原版牌库顺序」的证据 —— 那份 `PrebuiltSortedDeck` 的 `List`
                //       顺序没逐项核过（`资料/普查产出_1017/W_B29_教程执行器.md:110-111`）。
                var d1 = TutStageDeck(1);
                Check(d1 != null && d1.player != null && d1.player.cardIds != null && d1.player.cardIds.Length > 0,
                      "（前提）`tutorial_decks.json` 里有第 1 关的两副牌");
                if (d1 != null && d1.player != null && d1.player.cardIds != null)
                {
                    var deckNow = new List<string>();
                    for (int i = 0; i < cT1.Players[0].Deck.Count; i++)
                        deckNow.Add(cT1.Players[0].Deck[i].Card.Id);
                    int drawn = d1.player.cardIds.Length - deckNow.Count;    // 已被抽走的张数
                    bool prefix = drawn >= 0;
                    for (int i = 0; i < deckNow.Count && prefix; i++)
                        if (deckNow[i] != d1.player.cardIds[i]) prefix = false;
                    Check(prefix,
                          $"★ **不洗牌**：第 1 关我方牌库 == `tutorial_decks.json` 的 `player.cardIds`"
                        + $"（{d1.player.cardIds.Length} 张）的**前缀**、逐项同序 —— 现 {deckNow.Count} 张，"
                        + $"实得 `{string.Join("/", deckNow)}`（洗过牌的话前缀关系必破）");

                    // 少掉的那几项 = `cardIds` 的**后缀** ⇒ 应当在**手牌**里（先手第 1 回合抽走的）
                    var handNow = new List<string>();
                    for (int i = 0; i < cT1.Players[0].Hand.Count; i++)
                        handNow.Add(cT1.Players[0].Hand[i].Card.Id);
                    // S1 第 1 回合的脚本写着 `dontDrawCard = true`（原版 `TurnStartCardDraw.c:13-15`）⇒ 这一抽本来就不发生
                    bool firstTurnNoDraw = tutStages[0] != null && tutStages[0].turns != null
                                           && tutStages[0].turns.Length > 0 && tutStages[0].turns[0].dontDrawCard;
                    bool drewThem = drawn > 0 || (firstTurnNoDraw && drawn == 0);
                    for (int k = deckNow.Count; drewThem && k < d1.player.cardIds.Length; k++)
                    {
                        int at = handNow.IndexOf(d1.player.cardIds[k]);       // 按**张**核（同卡多份也对）
                        if (at < 0) drewThem = false; else handNow.RemoveAt(at);
                    }
                    Check(drewThem,
                          $"★ ……而少掉的那 {drawn} 张**已经被先手第 1 回合抽上手**了（牌库顶 = 数组末尾）"
                        + $" —— 手牌 = `{TutHandIds(cT1.Players[0])}`");
                }

                // ------------------------------------------------------------
                //  ②' S3 = **AI 先手**（关卡 `playerStarts = false`）
                // ------------------------------------------------------------
                driver.BeginTutorial(2);
                var cT3 = driver.Ctx;
                Check(cT3.Tutorial != null && cT3.Tutorial.Stage.stage == 3, "`BeginTutorial(2)` ⇒ 第 3 关");
                Check(cT3.FirstSeat == 1, "★ 第 3 关 `playerStarts = false` ⇒ **AI 先手**（座位 1）"
                    + " —— 这条正是「先手照关卡、不掷硬币」的判别式（掷硬币会随机落在 0 或 1）");
                Check(cT3.Active == 1, "开局当前行动方 = AI（`ctx.Active == FirstSeat`）");

                // ------------------------------------------------------------
                //  ③ **起始单位**（`SetupStartingTroops`）：S5 的**敌方**列表有 2 只 ⇒ 直接落场
                // ------------------------------------------------------------
                driver.BeginTutorial(4);
                var cT5 = driver.Ctx;
                var s5 = TutorialData.ByIndex(4);
                int wantFoe = 0;
                if (s5 != null && s5.enemyStartingTroops != null)
                    for (int i = 0; i < s5.enemyStartingTroops.Length; i++)
                    {
                        var r = s5.enemyStartingTroops[i];
                        if (r != null && !string.IsNullOrEmpty(r.ourId)) wantFoe++;   // 认不出的**不摆**（也不猜）
                    }
                Check(cT5.Tutorial != null && cT5.Tutorial.Stage.stage == 5, "`BeginTutorial(4)` ⇒ 第 5 关");
                Check(wantFoe == 2, $"（前提）第 5 关敌方起始单位表里有 **2** 张能认出来的（实得 {wantFoe}）"
                    + " —— 那是 6 关里**唯一**非空的 `startingTroops`（其余全是 `InHand` 那一支）");
                Check(TutBoardUnits(cT5.Players[1]) == wantFoe,
                      $"★ **起始单位**直接落场：AI 场上部队 **{wantFoe}** 只（实得 {TutBoardUnits(cT5.Players[1])}）"
                    + " —— 原版 `SetupStartingTroops`（教程/战役那一支才跑）");
                Check(TutBoardUnits(cT5.Players[0]) == 0, "我方这一关没有起始单位（4 个列表里只有敌方那个非空）");

                // ------------------------------------------------------------
                //  ③' **起手 = 关卡指定那一批**（`CreatePlayerDeck`：InHand 插牌库顶 → 抽 N 张）
                //     取 S3：它的 `playerStartingTroopsInHand` 有 4 条，其中**第 1 条 `ourId` 是空的**
                //     （产物 `unresolvedNoName` 那一档 ⇒ 认不出是卡池里哪一张）⇒ 我们**只插 3 张**。
                //     ⚠️ 抽的顺序：那几张是**按原序追加到牌库末尾**（= 我们的「牌库顶」，我们的 `Draw` 从末尾抽）
                //        ⇒ 抽出来是**逆序**；原版 `Insert(deck, 0, …)` + 从顶抽**同样是逆序**，两边一致。
                //        （换算见 `RuleEngine/Core/TutorialScript.cs` 的 `SetupInitialHand` 那段长注。）
                // ------------------------------------------------------------
                var s3 = TutorialData.ByIndex(2);
                var wantHand = new List<string>();
                if (s3 != null && s3.playerStartingTroopsInHand != null)
                    for (int i = s3.playerStartingTroopsInHand.Length - 1; i >= 0; i--)
                    {
                        var r = s3.playerStartingTroopsInHand[i];
                        if (r != null && !string.IsNullOrEmpty(r.ourId)) wantHand.Add(r.ourId);
                    }
                Check(wantHand.Count == 3, $"（前提）第 3 关我方起手表 4 条里有 **3** 条能认出我们的卡 id"
                    + $"（实得 {wantHand.Count}；第 1 条 `ourId` 空 = 产物 `unresolvedNoName`）");
                Check(TutHandIds(cT3.Players[0]) == string.Join("/", wantHand),
                      $"★ **起手 = 关卡那一批**：第 3 关我方手牌 = `[{string.Join("/", wantHand)}]`，"
                    + $"实得 `[{TutHandIds(cT3.Players[0])}]`（逆序 —— 见本条上面那段换算）"
                    + "｜🧨 把 `NewBattle` 里那段教程起手换回「各抽 `startingHand` 张」⇒ 本条红");
                Check(TutHandIds(cT3.Players[1]).Length > 0, "AI 那一侧的起手也照同一支走过（3 张）");

                // ------------------------------------------------------------
                //  ④ **白名单闸门**（`CheckIfPlayerActionPermittedInTutorial` + `CheckIfMatchesActionData`）
                //     纯引擎侧验 —— 不碰 driver 的状态。
                // ------------------------------------------------------------
                var gate = new TutorialScript(TutorialData.ByIndex(0));    // 第 1 关
                gate.UpdateTurn(1);
                Check(gate.Turn == 1 && gate.ActionCounter == 0, "（前提）执行器指针落到第 1 关第 1 回合第 0 条");

                // 第 1 关第 1 回合那 5 条（数据实读）：[0] `SmallTip`(非玩家动作) · [1] `AttackFreeMode`(玩家动作,
                //   acting=PlayerWarlord target=AiWarlord) · [2][3] `SmallTip` · [4] `EndTurn`(玩家动作)
                var attAttackWarlord = new TutorialAttempt
                {
                    Action = BattleActionType.attack, ActingIsHero = true, ActingIsPlayerSide = true,
                    TargetIsHero = true, TargetIsPlayerSide = false,
                };
                Check(!gate.PermitsPlayerAction(attAttackWarlord),
                      "★ **闸**：当前那条是 `SmallTip`（`playerAction = false` 且不是 `ActivateHandCards`）"
                    + " ⇒ **任何动作都不许做**（原版那一条 `IsActivateHandCards` 之外的 `playerAction == 0` 直接 return 0）"
                    + "｜🧨 把闸门删成 `return true` ⇒ 本条红");

                // 走一条 ⇒ 指针 ++（`PlayScriptedTurn`）—— 第 1 条是 `SmallTip`，引擎侧无事可做
                gate.PlayScriptedTurn(cT1);
                Check(gate.ActionCounter == 1, "`PlayScriptedTurn` 执行完当前那条 ⇒ 指针 ++（原版 `AiScripted +0x10 += 1`）");

                var attPlayCard = new TutorialAttempt
                {
                    Action = BattleActionType.playCardFromHand, ActingIsHero = true, ActingIsPlayerSide = true,
                    TargetIsHero = true, TargetIsPlayerSide = false,
                };
                Check(gate.PermitsPlayerAction(attAttackWarlord),
                      "★ 当前那条是 `AttackFreeMode(31)`（`playerAction = true`）·acting=`PlayerWarlord`·target=`AiWarlord`"
                    + " ⇒ 「**玩家督军打 AI 督军**」放行（`CheckIfMatchesActionData` 的动作档 + 发起者 + 目标三关全过）");
                Check(!gate.PermitsPlayerAction(attPlayCard),
                      "★ **判别式**：**同一个指针位置**、把动作换成 `playCardFromHand` ⇒ **不许放行**"
                    + "（`AttackFreeMode` 那一档只认 `attack(1)` / `changeAttack(19)` / `attackContinuation(53)`，"
                    + " 5 不在那张位掩码里）—— 一准一不准 ⇒ 闸门既不可能是「恒真」也不可能是「恒假」");

                // 目标换成一个「不是督军」的 ⇒ 同一条动作也该被挡（目标那一关独立生效）
                var attWrongTarget = new TutorialAttempt
                {
                    Action = BattleActionType.attack, ActingIsHero = true, ActingIsPlayerSide = true,
                    TargetIsHero = false, TargetIsPlayerSide = false,
                };
                Check(!gate.PermitsPlayerAction(attWrongTarget),
                      "★ 目标那一关独立生效：同一条动作、目标**不是督军** ⇒ 挡下"
                    + "（原版 target unitType 20 = `AiWarlord` 要求 `get_cardType(target) == 10` 且不是玩家侧）");

                // 🔴 **2026-10-18（审查 K1）**：指针现在停在 `AttackFreeMode`（第 1 条，`playerAction = true`）
                //   ⇒ 脚本**推不动它**（`PlayScriptedTurn` 里那句守卫）；要往下走得靠「玩家做完了」
                //   （`AdvancePlayerAction` = 原版 `PlayerChoiceAction`）。
                //   ⚠️ 原来的写法（连推两道 `PlayScriptedTurn` 指望它走到 2/3）在 K1 之后**不成立**。
                gate.PlayScriptedTurn(cT1);      // K1：玩家动作 ⇒ 推不动
                gate.PlayScriptedTurn(cT1);      // K1：同上
                Check(gate.ActionCounter == 1,
                      "★ **K1**：连推两次**指针纹丝不动**（这一条要玩家自己做）"
                    + "｜🧨 把守卫删掉 ⇒ 本条红（而真机上表现为「脚本替玩家攻击了一次」）");
                Check(!gate.PermitsPlayerAction(new TutorialAttempt { Action = BattleActionType.endTurn }),
                      "★ 指针停在 `AttackFreeMode` ⇒ **连 `endTurn` 也不许**（那一档只认 `attack/changeAttack/attackContinuation`）");
                gate.AdvancePlayerAction();      // 玩家做完了 ⇒ 指针 +1（原版 `PlayerChoiceAction`）⇒ 指针 2
                gate.PlayScriptedTurn(cT1);      // → 指针 3（`SmallTip`，`playerAction = false` ⇒ 执行 + ++）
                gate.PlayScriptedTurn(cT1);      // → 指针 4（`SmallTip`）
                // ⚠️ **2026-10-18 更正（铁律 5，只读诊断 D2 的结论）**：这里原来断 `== 3` —— 那是**本批 K1 之前**的旧值
                //   （旧流程里上面两个 PST 吃的是 `[1]`/`[2]`，当时确实停在 3）。**`AdvancePlayerAction()` 那句是本批新加的**
                //   （`+1`），但后面两个期望值没跟着 +1 ⇒ 抄漏。判据 = 紧邻的本文件那一条（断 `== 4`，绿）+ 本文件另一条（放行 `endTurn`，
                //   若指针真是 3 它必红 ⇒ 落 4 才是本块要的局面）。⛔ 别反过来把实现改成落 3。
                Check(gate.ActionCounter == 4,
                      $"（前提）两条 `SmallTip` 推完 ⇒ 指针 = **4**（期望 4 / 实得 {gate.ActionCounter}）"
                    + "｜🧨 把 `AdvancePlayerAction()` 那句删掉 ⇒ 本条红");
                gate.PlayScriptedTurn(cT1);      // → 指针 4（`EndTurn`，`playerAction = true`）
                Check(gate.PermitsPlayerAction(new TutorialAttempt { Action = BattleActionType.endTurn }),
                      "★ 指针落到 `EndTurn` 那一档 ⇒ 放行 `endTurn`（`data[0]` 的 acting/target 都是 `None` ⇒ 不约束）");
                Check(!gate.PermitsPlayerAction(new TutorialAttempt { Action = BattleActionType.attack }),
                      "★ **判别式**（同一个指针位置、`attack` 不许）—— 只放行清单里写的那一种动作");
                // 🔴 **2026-10-18（审查 K1）**：第 1 回合那 5 条里，**最后一条 `EndTurn` 是 `playerAction = true`**
                //   ⇒ **脚本推它不动**（原版 `0x180944129 jne 0x180944171` ⇒ `ret`：不执行、不 ++）。
                //   原来这里断的是「推完 ⇒ 指针 == 5」，那在 K1 之后**不成立**（也从来不对）——
                //   指针停在 4，回合推进时由 `UpdateTurn` 归零（**照原版**）。
                gate.PlayScriptedTurn(cT1);
                Check(gate.ActionCounter == 4,
                      "★ **K1**：`EndTurn`（`playerAction = true`）那一条 **`PlayScriptedTurn` 推不动**"
                    + $"（指针停在 {gate.ActionCounter}，不是 5）—— 守卫在函数里"
                    + "｜🧨 把 `if (a == null || a.playerAction) return false;` 删掉 ⇒ 本条红");

                // 「本回合脚本跑完（`actionCounter >= 动作数`）⇒ 闸门放行」那一档，**换个实例**证（不扰动 `gate`）：
                // S1 第 2 回合那 4 条**全是脚本自己执行的** ⇒ 4 条推完，指针 == 动作数。
                var gate2 = new TutorialScript(TutorialData.ByIndex(0));
                gate2.UpdateTurn(2);
                for (int k = 0; k < 4; k++) gate2.PlayScriptedTurn(cT1);
                Check(gate2.ActionCounter == 4,
                      $"（前提）第 2 回合那 4 条**全是脚本自己执行的** ⇒ 4 条推完、指针 = 动作数（实得 {gate2.ActionCounter}）");
                Check(gate2.PermitsPlayerAction(new TutorialAttempt { Action = BattleActionType.attack }),
                      "★ 本回合脚本跑完（`actionCounter >= 动作数`）⇒ 闸门**放行**"
                    + "（原版第 ③ 条：那一回合的引导结束了，玩家自由行动）");

                // ---- ④' `DrawCard` **抽哪一边**：判据是**发起者**（`scriptedActionData[0].actingUnitType`），
                //      ⛔ **不是「当前行动方」** —— 原版 `ExecuteAction.c:730` 把 `iVar8` 重赋成 `actingUnitType`
                //      之后才调 `AddDrawCard(bm, iVar8 == 10, …)`，而那个 bool 是「是不是玩家侧」
                //      （`AddDrawCard.c:31-37`：真 ⇒ `playerShuffledDeck`，假 ⇒ `enemyShuffledDeck`）。
                //      数据实测：9 条 `DrawCard` 里 8 条 `acting = PlayerWarlord`、**1 条 `None`**（S2 第 8 回合）
                //      ⇒ 那一条抽的是 AI；按「当前行动方」写就会在那一条上错（本轮**真的先写错了**，见报告 §④·1）。
                {
                    var dSt1 = TutorialData.ByIndex(0);      // S1
                    var dSt2 = TutorialData.ByIndex(1);      // S2
                    bool haveA = dSt1 != null && dSt1.turns != null && dSt1.turns.Length > 6
                              && dSt1.turns[6].actions != null && dSt1.turns[6].actions.Length > 1;
                    bool haveB = dSt2 != null && dSt2.turns != null && dSt2.turns.Length > 7
                              && dSt2.turns[7].actions != null && dSt2.turns[7].actions.Length > 0;
                    Check(haveA && haveB, "（前提）两条 `DrawCard` 用例在数据里都取得到（S1 第 7 回合 · S2 第 8 回合）");
                    if (haveA)
                        Check(TutorialScript.DrawSide(dSt1.turns[6].actions[1]) == 0,
                              "★ `DrawCard` 抽**发起者**那一侧：S1 第 7 回合那条 `acting = PlayerWarlord` ⇒ 抽**玩家**");
                    if (haveB)
                        Check(TutorialScript.DrawSide(dSt2.turns[7].actions[0]) == 1,
                              "★ …而 S2 第 8 回合那条 `acting = None` ⇒ 抽 **AI**"
                            + "｜🧨 把 `DrawSide` 改成返回 `ctx.Active` ⇒ 本条红");
                }

                // 换回合 ⇒ 指针归零（原版 `AiScripted.UpdateTurn`）
                gate.UpdateTurn(2);
                Check(gate.Turn == 2 && gate.ActionCounter == 0, "`UpdateTurn(2)` ⇒ 回合数变大时指指针**归零**");
                gate.UpdateTurn(1);
                Check(gate.Turn == 2, "`UpdateTurn(1)` ⇒ 回合数**变小不写**（原版那条 `if (当前 < param)`）");

                // ------------------------------------------------------------
                //  ⑤ `playerAlwaysWins` —— 🔴 **2026-10-15 就地订正：教程关这一档【按原版不改胜负】**
                //     ⛔ 关键是**守卫**：原版那两处（`GetWinnerAfterBattleEnd` / `DeadHero`）的守卫是
                //        **`IsCampaignLike()`（`matchType == 130 || 190`）**，**教程档(100/140)永不触发**；
                //        它「看着像教程机制」是因为下一步调的 `GetCurrentTutorialStage` **名字骗人** ——
                //        130/190 上它回的是 `currentCampaignStage`（同型 `TutorialStage`）。
                //        我们原来判 `ctx.Tutorial != null`（= 教程档）⇒ 两边触发集合**互不相交**。
                //     ⇒ 本段现在测的是**订正后的行为**：教程关置这个 flag = **原版的死数据**，
                //        但**必须出声一次**（红线：不许静默失败）。
                // ------------------------------------------------------------
                var emptyA = new List<CardDef>();
                var emptyB = new List<CardDef>();
                var pwOn = new TutorialScript(new TutorialStageData
                { stage = 99, so = "<自检合成·playerAlwaysWins>", playerStarts = true, playerAlwaysWins = true });
                var ctxPw = RuleCore.NewBattle(emptyA, emptyB, 7, tutorial: pwOn);
                Check(ctxPw.Winner == 0, "（前提）刚开完的教程局**还没分胜负**（这个开关不会让对局当场结束）");
                ctxPw.Players[0].Warlord.Health = 0;
                RuleCore.CheckWinner(ctxPw);
                Check(ctxPw.Winner == 2, "★ **订正后**：教程关把 `playerAlwaysWins` 置真 ⇒ **按原版【不生效】**"
                    + "（原版守卫 = `IsCampaignLike`，即 `matchType 130/190`；教程档永不触发）"
                    + "⇒ 玩家督军倒下就是**判 AI 胜**（`Winner = 2`）"
                    + "｜🧨 改回「教程档也判玩家胜」⇒ 本条红");
                Check(ctxPw.Events.Exists(e => e != null && e.Contains("按原版不生效")),
                      "★ 而它**不是静默的**：日志里有一句 ⚠️ 说明「教程关置这个 flag 在原版是死数据」"
                    + "｜🧨 把那支出声删掉 ⇒ 本条红（下一个会话会以为「我们忘了做」）");

                var pwOff = new TutorialScript(new TutorialStageData
                { stage = 98, so = "<自检合成·对照>", playerStarts = true, playerAlwaysWins = false });
                var ctxPw2 = RuleCore.NewBattle(emptyA, emptyB, 7, tutorial: pwOff);
                ctxPw2.Players[0].Warlord.Health = 0;
                RuleCore.CheckWinner(ctxPw2);
                Check(ctxPw2.Winner == 2, "★ **判别式**：同一个局面、那个开关关着 ⇒ **同样判 AI 胜**"
                    + "（⇒ 在本档它**确实不再影响胜负** —— 两条一致正是「订正后」的形状）");
                Check(!ctxPw2.Events.Exists(e => e != null && e.Contains("按原版不生效")),
                      "★ **判别式**：开关关着 ⇒ **没有**那句出声"
                    + "（⇒ 那句既不是「恒有」也不是「恒无」，是被这个 flag 驱动的）");

                // ------------------------------------------------------------
                //  ⑤' `preventPlayerResign`（6 关全 false，机制照做）
                // ------------------------------------------------------------
                var prOn = new TutorialScript(new TutorialStageData
                { stage = 97, so = "<自检合成·preventPlayerResign>", playerStarts = true, preventPlayerResign = true });
                var ctxPr = RuleCore.NewBattle(emptyA, emptyB, 7, tutorial: prOn);
                // 场景 = 玩家点那颗「投降」钮 ⇒ 理由码 `Forfeit`(2)（原版 `ClickExitBattle.c:59`
                // 那一跳就是 `DeadHero(我, 2)`；这里被 `preventPlayerResign` 挡下、**没走到**那一跳）
                RuleCore.Forfeit(ctxPr, 0, BattleResult.Forfeit);
                Check(ctxPr.Winner == 0, "★ `preventPlayerResign = true` ⇒ **投降被挡下**（`Winner` 仍是 0，对局继续）");
                var prOff = new TutorialScript(new TutorialStageData
                { stage = 96, so = "<自检合成·对照>", playerStarts = true, preventPlayerResign = false });
                var ctxPr2 = RuleCore.NewBattle(emptyA, emptyB, 7, tutorial: prOff);
                RuleCore.Forfeit(ctxPr2, 0, BattleResult.Forfeit);
                Check(ctxPr2.Winner == 2, "★ **判别式**：开关关着 ⇒ 投降照常生效（玩家投降 ⇒ AI 胜）");

                // ------------------------------------------------------------
                //  ⑥ **单机普通对局零影响**（投影：`tutorial == null` 时那一整条分支一次都不走）
                // ------------------------------------------------------------
                var nA = StarterCards.Of(StarterCards.EmberFaction);
                var nB = StarterCards.Of(StarterCards.TideFaction);
                var n1 = RuleCore.NewBattle(nA, nB, 20260911, shuffle: true);
                Check(n1.Tutorial == null, "★ 普通局：`ctx.Tutorial` 是 `null` ⇒ 教程那六条开关**一条都不生效**");
                Check(!n1.Vars.IsSkirmish && n1.Vars.startingHand == 3 && n1.Vars.secondExtraCards == 1,
                      "★ 普通局的参数仍是**经典那套**（起手 3 · 后手补偿 1）"
                    + " —— `GameplayVariables.For` 只对 `Tutorial 4` / `TutorialReplay 9` 改道，其余 13 档照旧");
                Check(n1.Players[0].Hand.Count == 3, $"★ 普通局起手仍是 **3** 张（实得 {n1.Players[0].Hand.Count}）");
                Check(n1.FirstSeat == BattleDriver.FirstSeatForSeed(20260911),
                      "★ 普通局的先手**仍按种子掷硬币**（教程那条覆盖只对 `tutorial != null` 生效）");
                var n1b = RuleCore.NewBattle(nA, nB, 20260911, shuffle: true);
                Check(TutDeckIds(n1.Players[0]) == TutDeckIds(n1b.Players[0]),
                      "（自证）同一个种子 ⇒ 同一副洗牌结果（对局可复现仍然是红线）");
                var n2 = RuleCore.NewBattle(nA, nB, 20260911, shuffle: false);
                Check(TutDeckIds(n2.Players[0]) != TutDeckIds(n1.Players[0]),
                      "★ 普通局**照旧洗牌**（`shuffle: true` 时牌库 != 传入顺序；`shuffle: false` 时 == 传入顺序）"
                    + "｜🧨 把那句 `shuffle = false` 写进教程分支之外（比如无条件覆盖）⇒ 本条红");

                // ------------------------------------------------------------
                //  ⑦ 「未接的动作要出声」—— 这一条**2026-10-18（A938）翻面了**：
                //     B29 那一批只接了 `DrawCard`，`PlayCard`/`Attack`/`ChangeToX`/`ActiveAbility` 四族没接，
                //     所以当时断的是「`AttackFreeMode` 进 `Unhandled`」。现在那四族**接完了**。
                //     🔴 **2026-10-18（审查 R5）更正**：原来这里断「`!probe.Unhandled.ContainsKey(AttackFreeMode)`」
                //        并标「🧨 删掉那两个 `case` ⇒ 本条红」—— **那句是错的**：删掉 `case` 之后它会落
                //        `default: Note` ⇒ 进 **`StageActions`**（`Unhandled` 的唯一写点是 `Stub`）⇒ **照样绿**。
                //        ⇒ 现在改成**两格都不许有它**（既不是「没接」也不是「原版无分支」），
                //        删掉 `case` ⇒ 进 `StageActions` ⇒ **真红**。
                //     🔑 三条合起来才有鉴别力：①」`AttackFreeMode` 两格都不在（= 真被处理了）·
                //        ②」`PlayScriptedTurn` 自己就挡住玩家那一档（K1）· ③」`ActiveAbility` **仍在** `Unhandled`（桩）。
                var probe = new TutorialScript(TutorialData.ByIndex(0));
                probe.UpdateTurn(1);

                // ⑦-a **K1：守卫在 `PlayScriptedTurn` 函数【里】**（照原版 VA `0x180944125-0x180944176`）
                Check(probe.PlayScriptedTurn(cT1) == true && probe.ActionCounter == 1,
                      "★ `[0] SmallTip`（`playerAction = false`）⇒ **执行 + 指针 ++**（脚本自己做的那一档）");
                Check(probe.PlayScriptedTurn(cT1) == false && probe.ActionCounter == 1,
                      "★ **`[1] AttackFreeMode`（`playerAction = true`）⇒ 不执行、指针也不动**"
                    + "（守卫**在函数里** —— 反汇编 `180944125 cmp [rax+0x40],r9b` → `jne 180944171` → `ret`）"
                    + "｜🧨 把 `PlayScriptedTurn` 里那句 `if (a == null || a.playerAction) return false;` 删掉"
                    + " ⇒ 本条红（`BattleScene` 自己就是那个反例：审查前这一句**真的替玩家打了一刀**）");

                // ⑦-b **它真的被 `ExecuteCore` 处理了**（绕过 K1 那道守卫，直接问这一档落到哪一格）
                var fmAct = TutorialData.ByIndex(0).turns[0].actions[1];    // `AttackFreeMode`
                var probe2 = new TutorialScript(TutorialData.ByIndex(0));
                probe2.UpdateTurn(1);
                probe2.ExecuteAction(cT1, fmAct);
                Check(!probe2.Unhandled.ContainsKey(ScriptedActionType.AttackFreeMode)
                      && !probe2.StageActions.ContainsKey(ScriptedActionType.AttackFreeMode),
                      "★ `AttackFreeMode` **两格都不在** ⇒ 它既不是「引擎侧没接」（`Unhandled`）"
                    + "、也不是「原版本来就没分支」（`StageActions`），而是**真被 `ExecuteCore` 处理了**"
                    + "｜🧨 把 `ExecuteCore` 里 `case Attack/AttackFreeMode` 删掉 ⇒ 落 `default: Note`"
                    + " ⇒ 进 `StageActions` ⇒ **本条红**");
                Check(probe2.Unhandled.Count == 0,
                      $"★ 而 `Unhandled` 整格是空的（实得 {probe2.Unhandled.Count} 档）—— 它的语义只有一条"
                    + "：「**引擎侧还没实现**」，⛔ 不是「这条动作改了局面没有」");

                var aaScript = new TutorialScript(new TutorialStageData { stage = 95, so = "<自检合成·ActiveAbility 桩>" });
                var aaAct = new TutorialAction
                {
                    type = "ActiveAbility",
                    data = new[] { new TutorialActionData { type = (int)ScriptedActionType.ActiveAbility } },
                };
                Check(!aaScript.ExecuteAction(cT1, aaAct)
                      && aaScript.Unhandled.ContainsKey(ScriptedActionType.ActiveAbility),
                      "★ **判别式**：`ActiveAbility`（**6 关数据里 0 条**）**仍然是桩** ⇒ 返回 false + 进 `Unhandled` + 出声"
                    + "（⛔ 没有数据可验的档**不凭空造** —— 原版那一支走 `AddAutoActionToQueue(playActiveAbility)`）"
                    + "｜🧨 把 `ActiveAbility` 也「顺手实现」了 ⇒ 本条红（那是猜的，不是复刻）");

                // ⑦-c **K12**：空动作不许静默（原来是「指针照 ++、什么都不记、不出声」）
                var naScript = new TutorialScript(new TutorialStageData { stage = 94, so = "<自检合成·空动作>" });
                Check(!naScript.ExecuteAction(cT1, null) && naScript.NullActions == 1,
                      "★ **空动作不再静默**（审查 K12）：`ExecuteAction(null)` ⇒ 返回 false + 记 `NullActions` + 出声"
                    + "｜🧨 把那一段 `if (a == null)` 写回 `return false;` ⇒ 本条红");

                // ------------------------------------------------------------
                //  ⑧ 🆕 2026-10-18（A938）：**把执行器真正挂进回合循环**（这一条才是本件的要害）
                //
                //  🔴 A938 的**真根因**不是「六档没接」，是「**执行器在真局里一次都没被驱动**」
                //     （`PlayScriptedTurn`/`UpdateTurn`/`PermitsPlayerAction` 在生产代码里**零调用点**）。
                //     所以这一节断的不是「函数返回什么」，而是「**它有没有被叫到**」。
                //
                //  判据（原版那几份协程，逐句读过）：
                //   · 脚本推一条 = `AiScripted.PlayScriptedTurn`（**教程**那份重载，VA `0x180944060`）——
                //     ⚠️ **2026-10-18 更正（铁律 5）**：原来这里写「执行 + `*(+0x14) += 1`」，
                //     实际是「**只有 `playerAction == false` 那一支**才 `ExecuteAction` + `inc [rbx+0x10]`；
                //     玩家那一支只调 `ShowPlayerActionAnim` 然后 `ret`（返回 false、不执行不 ++）」
                //     （落盘 `.c` 是**战役**那份，用 `+0x14`；教程那份的 `.c` 本地缺 —— 已按 VA 反汇编取到）；
                //   · 等玩家的那条**原地停住** = `_ExecuteScriptedTurn_d__597:236-246`；
                //   · 玩家做完 ⇒ 指针 +1 = `BattleManager__FinishResolvingAction.c:168-182`；
                //   · 回合变了 ⇒ 指针归零 = `AiScripted__UpdateTurn.c`（调用点 = 四个 `RuleCore.BeginTurn`）。
                // ------------------------------------------------------------
                driver.BeginTutorial(0);                 // S1：玩家先手，第 1 回合 5 条
                var cW = driver.Ctx;
                var tW = cW != null ? cW.Tutorial : null;
                Check(tW != null && tW.Stage.stage == 1, "（前提）第 1 关的执行器落位了");

                // ② **四个 `BeginTurn` 各跟一次 `UpdateTurn`** —— 开局那句 `BeginTurn` 就该把指针推到第 1 回合
                Check(cW.Turn == 1 && tW.Turn == 1 && tW.ActionCounter == 0,
                      $"★ 开局那句 `RuleCore.BeginTurn` 之后**指针已就位**（`Turn`={tW.Turn}，指针 {tW.ActionCounter}）"
                    + "｜🧨 把 `Begin` 里那句 `SyncTutorialTurn()` 删掉 ⇒ 本条红（`Turn` 会停在 0）");

                // ① 每驱动一帧 ⇒ 脚本推一条（第 1 回合第 0 条 = `SmallTip`，非玩家动作）
                var st0 = DriveStep();
                Check(st0 == BattleDriver.TutorialStep.Advanced && tW.ActionCounter == 1
                      && !driver.TutorialWaitingForTip,
                      $"★ **执行器真的被驱动了**：驱动一帧 ⇒ 推掉 1 条（指针 0 → {tW.ActionCounter}）"
                    + " —— 这正是 A938 原来缺的那一环（生产代码里零调用点）"
                    + "｜🧨 第三项（`!TutorialWaitingForTip`）是**两态判别式**：被 `_tutTipUp` 挡住时"
                    + " 驱动同样返回 `Advanced`（`DC_教程推进21红.md` §6·3 那条弱断言）——"
                    + " 靠 `ActionCounter` 与这一项合起来才分得出「真推了一条」");
                // ② 下一条是 `AttackFreeMode(playerAction = true)` ⇒ **原地停住、指针不动**
                var st1 = DriveStep();
                Check(st1 == BattleDriver.TutorialStep.WaitingForActor && tW.ActionCounter == 1,
                      "★ **等玩家的那一条不执行**：`AttackFreeMode(playerAction=true)` ⇒ 脚本停住、指针不动"
                    + "（原版 `_ExecuteScriptedTurn_d__597:236-246`：`IsNextActionScriptedPlayerAction` 真 ⇒ 协程结束）"
                    + "｜🧨 把 `IsNextActionScriptedPlayerAction` 那个判据删掉 ⇒ 本条红（脚本会把玩家该做的那步自己做了）");

                // ③ **闸门**：同一个指针位置一准一不准（判别式）
                var wMine = cW.Players[0].Board[BoardSpec.WarlordSlot];
                var wFoe = cW.Players[1].Board[BoardSpec.WarlordSlot];
                Check(wMine != null && wFoe != null, "（前提）两边督军都在场上");
                var attOk = new TutorialAttempt
                {
                    Action = BattleActionType.attack,
                    ActingId = wMine.Card.Id, ActingIsHero = true, ActingIsPlayerSide = true,
                    TargetId = wFoe.Card.Id, TargetIsHero = true, TargetIsPlayerSide = false,
                };
                Check(driver.TutorialPermitsForTest(attOk),
                      "★ **教程闸门**放行脚本写着的那一步（玩家督军打 AI 督军 —— 数据里就是 `AttackFreeMode` 那一条）");
                Check(!driver.TutorialPermitsForTest(new TutorialAttempt
                      { Action = BattleActionType.playCardFromHand, ActingIsHero = true, ActingIsPlayerSide = true }),
                      "★ **判别式**：同一个指针位置、换成 `playCardFromHand` ⇒ **拒**"
                    + "（一准一不准 ⇒ 闸门既不可能是「恒真」也不可能是「恒假」）");

                // ③″ 🔴 **原版那句 `param_4 == null ⇒ 目标那一关整段不判`**（`CheckIfMatchesActionData.c`：
                //     `UnityEngine_Object.op_Inequality(param_4, 0)` 为假就 `return 1`）。
                //     「**这一格能不能动手**」这种查询发生在**玩家还没点目标**的时候（原版那几处传的
                //     `targetCard` 就是 null）⇒ ⛔ 拿「目标那一关」去挡它 = **那一步永远做不出来**（自锁）。
                //     一正一反两条：
                Check(driver.TutorialPermitsForTest(new TutorialAttempt
                      { Action = BattleActionType.attack, ActingIsHero = true, ActingIsPlayerSide = true,
                        NoTargetYet = true }),
                      "★ **还没有目标的查询照样放行**（原版 `targetCard == null ⇒ return 1`）"
                    + "｜🧨 把那句 `if (a.NoTargetYet) return true;` 删掉 ⇒ 本条红 ——"
                    + " 而真机上它的表现是**玩家拖自己的督军打不出去**（选择器根本不开），整关卡死");
                Check(!driver.TutorialPermitsForTest(new TutorialAttempt
                      { Action = BattleActionType.attack, ActingIsHero = true, ActingIsPlayerSide = true,
                        TargetIsHero = true, TargetIsPlayerSide = true }),
                      "★ **判别式（灭自证）**：同一条动作、**把目标补上**并写成「打自己家的督军」⇒ **拒**"
                    + "（脚本那一条写的是 `AiWarlord` ⇒ 玩家侧督军不在目标清单里）");

                // ③′ **普通局恒放行**（闸门作用域 = 「教程局 + 人类座位」）
                var nOne = RuleCore.NewBattle(StarterCards.Of(StarterCards.EmberFaction),
                                              StarterCards.Of(StarterCards.TideFaction), 20260911);
                Check(nOne.Tutorial == null, "★ 普通局 `ctx.Tutorial == null` ⇒ 闸门那一整条链一次都不走"
                    + "（`TutorialPermits` 第一句就是 `tut == null ⇒ return true`）");

                // ④ **玩家做完那一步 ⇒ 指针 +1**（原版 `FinishResolvingAction.c:168-182`）
                int ptrBefore = tW.ActionCounter;
                driver.ContinueTutorialScriptForTest();
                Check(tW.ActionCounter == ptrBefore + 1,
                      $"★ 玩家做完脚本等着的那一步 ⇒ **指针 +1**（{ptrBefore} → {tW.ActionCounter}）");
                // ④′ **判别式**：指针落在「不等玩家」的那一条上 ⇒ 再叫一次**不许**动
                int ptrNow = tW.ActionCounter;                 // 现在是 `SmallTip`（playerAction=false）
                driver.ContinueTutorialScriptForTest();
                Check(tW.ActionCounter == ptrNow,
                      $"★ **判别式**：指针落在**不等玩家**的那一条上（`ActionCounter`={ptrNow}）⇒ 再叫一次**不许 +1**"
                    + "（原版那里先过 `CheckIfWaitingForPlayerAction`）"
                    + "｜🧨 把那道守卫删成「无条件 +1」⇒ 本条红");

                // ⑤ 把这一回合剩下的推完：`SmallTip` ×2 → 落在 `EndTurn(playerAction=true)`
                DriveStep();
                DriveStep();
                var st2 = DriveStep();
                Check(tW.ActionCounter == 4 && st2 == BattleDriver.TutorialStep.WaitingForActor,
                      $"★ 第 1 回合推到第 4 条（`EndTurn`，等玩家）—— 指针 {tW.ActionCounter}");
                Check(!driver.TutorialPermitsForTest(attOk),
                      "★ **越权动作被拒**：指针落在 `EndTurn` 那一条 ⇒ 连「打督军」也不许做");
                Check(driver.TutorialPermitsForTest(new TutorialAttempt { Action = BattleActionType.endTurn }),
                      "★ 而 `endTurn` 放行（脚本写的就是它）");

                // ⑤′ 🔴 **两条同时成立才是本轮的判据**：**引擎判定说「行」，教程闸门说「不行」**
                //     ⇒ 闸门是**叠在引擎判定之上的一层**，⛔ **不是引擎里的一条规则**。
                //     🧨 反过来做（把闸门塞进 `RuleCore.CanAttackNow` / `CanPlayCard`）会**把 AI 一起闸死** ——
                //        `SimpleAI.GetAvailableActions` 走的就是那几个 `Can*`，而脚本驱动的那些动作本来就不该被闸。
                Check(RuleCore.CanAttackNow(cW, 0, BoardSpec.WarlordSlot, false) == RuleCodes.OK,
                      "★ **引擎判定说「可以」**：玩家督军这一手在引擎里合法（攻击力 2 · 没疲劳 · 配额没满）");
                // 同一刻、**AI 那一侧**的同一个引擎判定也照旧给 OK（闸门只挂人类座位那条链）
                // ⚠️ **2026-10-18（审查 · 丙组）**：这一段要**临时解疲劳 + 临时改 `ctx.Active`**
                //    （`CanAttackNow` 的第一道闸就是「是不是你的回合」）⇒ **必须 try/finally 还原**：
                //    批处理里若这句之后抛异常，夹具会带着**被改过的局面**继续往下跑（后面每一条都会假红）。
                {
                    var aiW0 = cW.Players[1].Board[BoardSpec.WarlordSlot];
                    bool savedEx = aiW0.Exhausted;
                    int savedAct = cW.Active;
                    int aiCode;
                    try
                    {
                        aiW0.Exhausted = false;      // 只为了问这一句引擎判定
                        cW.Active = 1;
                        aiCode = RuleCore.CanAttackNow(cW, 1, BoardSpec.WarlordSlot, false);
                    }
                    finally
                    {
                        cW.Active = savedAct;
                        aiW0.Exhausted = savedEx;
                    }
                    Check(aiCode == RuleCodes.OK,
                          "★ **判别式：AI 的动作不受影响** —— 同一个教程局、同一刻，AI 那一侧的引擎判定"
                        + "**照旧给 OK**（⛔ 闸门没往 `RuleCore.Can*` 里塞 —— 那条路 `SimpleAI` 也在走，"
                        + "塞进去会把 AI 一起闸死）｜🧨 把闸门搬进 `RuleCore.CanAttackNow` ⇒ 本条红");
                }

                // ⑥ 玩家结束回合 ⇒ 回合推进 + **指针归零** + 进第 2 回合（AI 那一回合的脚本）
                int evtBefore = 0;
                for (int i = 0; i < cW.ActionLog.Count; i++)
                    if (cW.ActionLog[i] != null && cW.ActionLog[i].Kind == EvtKind.Attack) evtBefore++;
                var recW = driver.Recording;
                Check(recW != null, "（前提）这一局在录像（`RecordReplays` 默认开）");

                driver.SimulateEndTurn();      // 走产品那条 `EndPlayerTurn`（含闸门）
                Check(cW.Turn == 2, $"★ 玩家结束回合 ⇒ 第 2 回合（实得 {cW.Turn}）");
                Check(tW.Turn == 2 && tW.ActionCounter == 0,
                      $"★ **回合变了 ⇒ 脚本指针归零**（原版 `AiScripted.UpdateTurn`）—— 指针 {tW.ActionCounter}");
                Check(tW.CurrentTurn != null && tW.CurrentTurn.actions != null && tW.CurrentTurn.actions.Length == 4,
                      "（前提）第 2 回合是 AI 的脚本回合（数据：`Attack`/`AiChat`/`PlayerChat`/`EndTurn` 四条）");
                // ⚠️ 基线要取在**这一步之前**：`SimulateEndTurn` 自己会记一条「玩家结束回合」（清单 ⑥）
                int recBefore = recW.actions.Count;

                // ⑦ **六档里的 `Attack`**：脚本接管 AI 回合，第一条真的打了一记
                var st3 = DriveStep();
                Check(st3 == BattleDriver.TutorialStep.Advanced && tW.ActionCounter == 1
                      && !driver.TutorialWaitingForTip,
                      "★ 第 2 回合第 1 条（AI 的 `Attack`）由**脚本**执行"
                    + "｜🧨 末尾那一项是**两态判别式**：被 `_tutTipUp` 挡住时驱动同样返回 `Advanced`");
                int evtAfter = 0;
                for (int i = 0; i < cW.ActionLog.Count; i++)
                    if (cW.ActionLog[i] != null && cW.ActionLog[i].Kind == EvtKind.Attack) evtAfter++;
                Check(evtAfter > evtBefore,
                      $"★ 而且**真的打出去了**（引擎事件 `EvtKind.Attack` 计数 {evtBefore} → {evtAfter}）"
                    + " —— 不是「消费掉这条动作但局面没动」"
                    + "。⚠️ **这里判的是「至少多了一次」而不是「恰好多一次」**（有意放宽：上面那条 `EndTurn`"
                    + " 的结算是会连带触发别的攻击的，把玩家那一记也算进去就会假红）");

                // ⑧ **第三条记账口**：脚本动作进了录像；**纯演出档一条都不许记**
                int recAfter = recW.actions.Count;
                Check(recAfter == recBefore + 1,
                      $"★ **第三条记账口**（`TutorialScript.Executed`）把脚本那一条记进了录像"
                    + $"（{recBefore} → {recAfter}）"
                    + " —— 不记的话**教程局录像回放会从那里开始演成另一局**");
                DriveStep();      // 第 2 条 = `AiChat`（纯演出）
                Check(recW.actions.Count == recAfter,
                      $"★ **判别式**：`AiChat` 是纯演出（不改引擎状态）⇒ **一条都不许记**（仍是 {recW.actions.Count}）"
                    + "｜🧨 把记账口改成「凡动作都记」⇒ 本条红（回放会被空动作污染）");

                // ⑨ **回放**：比**终局局面哈希**（工程里既有那套自检法）
                //    ⚠️ `NetProtocol.StateHash` 只数**张数**（牌库/手牌几张）⇒ 单独用它挡不住「张数一样、牌不一样」。
                //       所以另配一份**局面速写**（哪一格站着哪一张、各多少血）一起比 —— 两份都过才算「同一局」。
                string SnapshotNow()
                {
                    var sb = new System.Text.StringBuilder();
                    for (int p = 0; p < 2; p++)
                    {
                        var ps = driver.Ctx.Players[p];
                        sb.Append('|').Append(p).Append(':').Append(ps.Energy)
                          .Append('/').Append(ps.Deck.Count).Append('/').Append(ps.Hand.Count).Append('/');
                        for (int i = 0; i < ps.Hand.Count; i++)
                            sb.Append(ps.Hand[i] != null && ps.Hand[i].Card != null ? ps.Hand[i].Card.Id : "-").Append(',');
                        sb.Append('/');
                        for (int i = 0; i < ps.Deck.Count; i++)
                            sb.Append(ps.Deck[i] != null && ps.Deck[i].Card != null ? ps.Deck[i].Card.Id : "-").Append(',');
                        sb.Append('/');
                        for (int s = 0; s < BoardSpec.Size; s++)
                        {
                            var u = ps.Board[s];
                            if (u == null) { sb.Append('-'); continue; }
                            sb.Append(u.Card.Id).Append('@').Append(u.Health).Append(u.Exhausted ? "!" : "");
                            sb.Append(' ');
                        }
                    }
                    return sb.ToString();
                }
                recW.finalHash = NetProtocol.StateHash(cW);
                string snapBefore = SnapshotNow();
                int recTotal = recW.actions.Count;
                bool replaySame = driver.PlayReplay(recW);
                Check(replaySame,
                      $"★ **回放完的终局局面哈希 == 录制时的**（`PlayReplay` 自己比 `NetProtocol.StateHash`）"
                    + $" —— 录了 {recTotal} 条动作，其中含脚本自己执行的那些"
                    + "｜🧨 把「脚本动作不进录像」改回去（删掉 `TutorialScript.Executed` 那一跳）⇒ 本条红");
                string snapAfter = SnapshotNow();
                Check(snapAfter == snapBefore,
                      "★ **判别式（灭自证）**：终局**局面速写**也逐字相同（哪一格站着哪一张、各多少血、手牌与牌库逐张）"
                    + " —— 单看 `StateHash` 挡不住「张数一样、牌不一样」，这一条补上那一刀");
                if (snapAfter != snapBefore)
                    Debug.LogError("[教程局] 回放分叉：\n  录的 " + snapBefore + "\n  放的 " + snapAfter);
                // 🆕 2026-10-18（审查 · 交件 §9·3）：**逐条轨迹也断一下** —— 原来 `PlayReplay` 里那一跳
                //   只 `LogError`，于是「轨迹中途分叉、终局 `StateHash` 恰好相等」时上面两条**仍会全绿**
                //   ⇒ 自检口径不闭合。现在它是一个**失败位**（`ReplayDivergenceForTest`）。
                Check(driver.ReplayDivergenceForTest < 0,
                      $"★ **回放的逐条轨迹一条都没分叉**（首处分叉 = {driver.ReplayDivergenceForTest}，-1 = 没有）"
                    + " —— 这是**比终局哈希更硬**的那一条（终局只数张数，中途错位可能被抹平）");
                // 🔴 **2026-10-24（`A32`）：同一族第二个失败位（`A29` 的结构断言）的读者。**
                //   教程局**没有换牌阶段**（`mulliganEnabled = false`）⇒ 这一格是**对照档**：
                //   它证明「结构断言不是靠『所有流都会踩』变绿」—— 换牌/环境卡一条都没有时它必须是 -1。
                //   🧨 把 `PlayReplay` 里 `_setupOrderViolationForTest` 的初值改成 ≥ 0（或漏清）⇒ 这一格立刻红。
                Check(driver.SetupOrderViolationForTest < 0,
                      "★ A29：开局次序（教程回放对照档）—— 没有换牌/环境卡 ⇒ 失败位必须是 -1"
                    + $"（实得 {driver.SetupOrderViolationForTest}）");
                Check(driver.Ctx != null && driver.Ctx.Tutorial != null && driver.Ctx.Tutorial.Stage.stage == 1,
                      "★ 回放局**重建的是教程那一局**（录像头里记着关号）—— 否则一开局就不在同一局上"
                    + "（教程少洗一次牌、起始单位与起手都由关卡摆）");

                // ---- 🆕 2026-10-20（战斗线 `W58-REPLAYINTRO`）：**教程回放不播独白** ----
                //   教程回放走 `BeginTutorial` ⇒ `Ctx.MatchType = Tutorial(100)`；原版
                //   `IsTutorialOrCampaignMatch`（真值集 {100,130,140,190}）在同一道闸上挡住
                //   （原版教程回放那一档 `TutorialReplay = 140` 也在排除集）。
                {
                    Check(driver.Ctx != null && driver.Ctx.MatchType == RuleEngine.MatchType.Tutorial,
                          $"（前提）教程回放的这一局是教程档（实得 "
                        + $"{(driver.Ctx != null ? (int)driver.Ctx.MatchType : -1)}；`BeginTutorial` 重建）");
                    Check(driver.IntroStartCountForTest == 0 && driver.IntroStage < 0,
                          $"★ W58：**教程回放不播开场独白**（原版 `IsTutorialOrCampaignMatch`）"
                        + $" —— 起播次数 = {driver.IntroStartCountForTest}、状态机 = {driver.IntroStage}，"
                        + "期望 0 / -1｜🧨 把 `StartIntroMonologue` 那道 "
                        + "`IsTutorialOrCampaignMatch(Ctx.MatchType)` 闸删成恒假 ⇒ 教程回放会起播，本条红");
                }

                // ------------------------------------------------------------
                //  ⑩ 🆕 2026-10-18（审查 K7/R10）：**老录像的兼容要有判据，不能只有注释背书**
                //     `ReplayRecord.tutorialStage` 是新加的字段，老录像 JSON 里**没有这个键** ——
                //     🔴 **2026-10-24（`A8`）就地订正**：本行原写「`JsonUtility` 跑不跑初始化器**本地无判据**」，
                //     **已结案 = 跑**（缺键字段留着初始化器值，⛔ 不是 `default(T)`；证据与封印断言见下面 §A8 那一段）。
                //     ⇒ 哨兵取 **`0`（= `int` 的默认值）** 这条**照旧正确**，理由更清楚了：
                //        `0` **既是默认值、也是本字段初始化器写的值** ⇒ 不管引擎走哪一档都给 `0`。
                // ------------------------------------------------------------
                {
                    var oldRec = JsonUtility.FromJson<CardPresentation.ReplayRecord>(
                        "{\"version\":2,\"mySeat\":0,\"actions\":[]}");     // ← 一个没有 `tutorialStage` 键的老录像
                    Check(oldRec != null && oldRec.TutorialStageIndex == -1,
                          $"★ **老录像不许被当成教程局**（缺键 ⇒ `tutorialStage = {oldRec?.tutorialStage}` ⇒ 关号 "
                        + $"{oldRec?.TutorialStageIndex}）—— **这是哨兵取 `0`（而不是 `-1`）的理由**："
                        + "初始化器跑不跑都给 0"
                        + "｜🧨 把哨兵改回 `-1`（或任何非 0 值）⇒ 本条红，而且真机上的表现是"
                        + "**每一份老录像都被当「教程第 1 关」放**（静默错、不报错）");
                    var tutRec = JsonUtility.FromJson<CardPresentation.ReplayRecord>(
                        "{\"version\":2,\"mySeat\":0,\"tutorialStage\":3,\"actions\":[]}");
                    Check(tutRec != null && tutRec.TutorialStageIndex == 2,
                          $"★ **判别式（灭自证）**：同一段 JSON 把 `tutorialStage` 换成 3 ⇒ 关号 **2**（0..5 换算）"
                        + " —— 一正一反 ⇒ 这一格既不可能是「恒 -1」也不可能是「恒等于 stage」");
                }

                // ------------------------------------------------------------
                //  🆕 2026-10-24（`A8`）：**`JsonUtility.FromJson` 跑不跑字段初始化器** —— 把
                //    `ReplayStore` 三份「新增字段哨兵」（`tutorialStage` / `botSeatPlus2` / `mulliganPlus1`）
                //    注释里那句「**本地没有判据**」一次消掉，并把结论**钉住**（Unity 换版本改了行为会红）。
                //  结论（外部证据，见 `ReplayStore.tutorialStage` 那段注）：**跑** —— `FromJson` 会调目标类型的
                //    **无参构造**（因而跑字段初始化器）⇒ **缺键字段留着初始化器写的值**，⛔ 不是 `default(T)`。
                //    判据 = `Unity 6000.3.4f1` 实跑（`kan-kikuchi.hatenablog.com/entry/JsonUtility_Ctor`，2026-03-05，
                //    与本工程同一个 6000.3 小版本线）+ `Unity 6000.6 / 7000` 官方 ScriptReference 把旧版
                //    「构造函数不执行」那句**更正**了。⚠️ 那是**引擎行为**、不是本工程数据判据 ⇒ 这里立**自己的封印**。
                //  ⚠️ **本会话（A8）没跑 Unity（红线）** ⇒ 下面第一条是它的**第一次实跑**；它若红，
                //     说明 6000.3.23f1 与 6000.3.4f1 不同 ⇒ 按日志里的实得值改期望，并回头订正 `ReplayStore` 三处注释。
                // ------------------------------------------------------------
                {
                    // 缺键 JSON：三个探针字段**一个都不给**。`intWithInit` / `strWithInit` 的初始化器
                    // **故意 ≠ 默认值**（`4242` vs `0`、`"INIT"` vs `null`）—— 否则「跑不跑初始化器」读出同一个值 = 结构上分不出（自证）。
                    var jp = JsonUtility.FromJson<JsonInitProbeForTest>("{\"plainInt\":7}");
                    Check(jp != null && jp.intWithInit == 4242 && jp.strWithInit == "INIT",
                          "★ A8 JsonUtility 初始化器：**缺键字段留着初始化器值**"
                        + $"（intWithInit = {(jp == null ? "?" : jp.intWithInit.ToString())} 期望 **4242** · "
                        + $"strWithInit = {(jp == null ? "?" : (jp.strWithInit == null ? "null" : "`" + jp.strWithInit + "`"))} 期望 **`INIT`**）"
                        + "｜🧨 Unity 换版本后若不跑初始化器 ⇒ 读到 `0` / `null` ⇒ 本条红"
                        + "（那时 `ReplayStore` 那三处哨兵注释要跟着改）");
                    Check(jp != null && jp.plainInt == 7,
                          "★ A8 **判别式（灭自证）**：同一段 JSON 里**给了键**的字段照常被覆盖"
                        + $"（plainInt = {(jp == null ? "?" : jp.plainInt.ToString())}，期望 **7**）"
                        + " —— 证明上面那条不是「整个对象压根没解析」的假绿");
                    // 真对象上的落点：三份哨兵（它们初始化器都 `= 0` ⇒ 两种引擎行为给出**同一个值**）
                    var sentinelRec = JsonUtility.FromJson<CardPresentation.ReplayRecord>("{\"version\":2}");
                    Check(sentinelRec != null && sentinelRec.tutorialStage == 0
                          && sentinelRec.botSeatPlus2 == 0 && sentinelRec.mulliganPlus1 == 0,
                          "★ A8：三份**新增字段哨兵**在缺键 JSON 上全读 `0` ⇒ `TutorialStageIndex` / "
                        + "`BotSeatForNewBattle` / `MulliganEnabledForReplay` 三处「没记」判定成立"
                        + $"（实得 {sentinelRec?.tutorialStage}/{sentinelRec?.botSeatPlus2}/{sentinelRec?.mulliganPlus1}；"
                        + "哨兵取 `0` 的理由 = `0` **既是 `int` 默认值、也是初始化器值**）"
                        + "｜🧨 把任一哨兵改成 `-1` / 别的非 0 值 ⇒ 本条红，真机上 = 每一份老录像都被当成某一档");
                }

                // ------------------------------------------------------------
                //  ⑪ 🆕 2026-10-18（审查 K8 后半·回放那一格）：**回放局里 AI 那一支不许自己吞掉回合**。
                //     此刻正好是回放局（`_replaySession` 还是 true、`Ctx.Tutorial` 也在）——
                //     这是**白拿的一次**真环境，不用再搭一个假回放局。
                // ------------------------------------------------------------
                {
                    int turnInReplay = driver.Ctx.Turn;
                    int ptrInReplay = driver.Ctx.Tutorial.ActionCounter;
                    driver.DriveAiTurnForTest();
                    Check(driver.Ctx.Turn == turnInReplay && driver.Ctx.Tutorial.ActionCounter == ptrInReplay,
                          $"★ **回放局：`DriveAiTurn` 一帧不动**（回合仍 {driver.Ctx.Turn}、指针仍 "
                        + $"{driver.Ctx.Tutorial.ActionCounter}）—— 执行器自驱被 `_replaySession` 关掉了，"
                        + "而那一支对 `NotOwned` 是**显式 return**（⛔ 不是「当成脚本跑完」去收回合）"
                        + "｜🧨 把 `if (step == TutorialStep.NotOwned) return;` 删掉 ⇒ 本条红"
                        + "（真机上 = 回放被推到下一回合、整条动作流错位）");
                }

                // 收尾：把 driver 留在**一个正常的教程局**上（回放局那道 `_replaySession` 闸要关掉）
                driver.BeginTutorial(0);
                Check(driver.Ctx != null && driver.Ctx.Tutorial != null && !driver.ReplaySessionForTest,
                      "收尾：重新开一局 ⇒ 不再是回放局（`_replaySession` 已清）");

                // ------------------------------------------------------------
                //  ⑫ 🆕 2026-10-18（审查 K4/R6）：**「玩家选了这一档打法」就是脚本等的「换打法」那一步**
                //     原版两半：`Update.c:1066` 的 `CheckIfWaitingToChangeAttack` 把这一刀**拦下来**
                //     + `AttackButtonClick` → `ChangeAttackType` → `FinishResolvingAction`（指针 +1）。
                //     我们：选打法 = `CommitCommand` ⇒ 在这里做那一步。
                // ------------------------------------------------------------
                {
                    var cK = driver.Ctx;
                    var tK = cK.Tutorial;
                    tK.UpdateTurn(5);                 // S1 第 5 回合 = [SmallTip, ChangeToMelee, ChangeToRanged(P), …]
                    tK.PlayScriptedTurn(cK);          // [0] SmallTip（脚本自己执行）
                    tK.PlayScriptedTurn(cK);          // [1] ChangeToMelee（脚本自己执行 —— 连带把督军拨成近战）
                    Check(tK.ActionCounter == 2 && tK.IsNextActionScriptedPlayerAction,
                          "（前提）指针落在 `ChangeToRanged(playerAction = true)` 那一条上");
                    RuleCore.SetCurrentAttackType(cK, 0, BoardSpec.WarlordSlot, UnitState.AttackTypeMelee);
                    Check(cK.Players[0].Board[BoardSpec.WarlordSlot].CurrentAttackType == UnitState.AttackTypeMelee,
                          "（前提）先把玩家督军摆成**近战**（这样下面「被改成远程」才是可观测的变化）");

                    Check(driver.SimulateOpenCommand(BoardSpec.WarlordSlot), "（前提）攻击方式选择器弹出来了");
                    // ⚠️ **照原版的口径**：`ChangeTo*` 那一条的闸门**接受 `attack`**
                    //    （`ScriptedActionData.CheckIfMatchesActionData` 的 `case 5/6`：`changeAttack(19)` 与
                    //     `attack(1)` 都收）⇒ **「不许越过这一步直接打」不是靠闸门挡的**，
                    //     而是靠「**选打法那一刻就把这一步做了**」（K4 把原版那两半合成一处的落点）。
                    Check(tK.PermitsPlayerAction(new TutorialAttempt
                          {
                              Action = BattleActionType.attack, ActingIsHero = true, ActingIsPlayerSide = true,
                              NoTargetYet = true,
                          }),
                          "（前提·照原版）`ChangeTo*` 那一条**接受 `attack`** ⇒ 闸门本身不挡「直接打」"
                        + "（原版靠 `BattleManager.Update` 那条 `CheckIfWaitingToChangeAttack` 挡；"
                        + "我们靠「选打法 = 做那一步」这条**结构性**的顺序 —— 见 K4 的注释）");
                    driver.SimulateCommand(AttackKind.Ranged);
                    Check(tK.ActionCounter == 3,
                          $"★ **K4**：玩家选「远程」那一刻 ⇒ 就是脚本等的「换打法」那一步 ⇒ **指针 +1**（2 → {tK.ActionCounter}）"
                        + "｜🧨 把 `TutorialCompleteChangeAttack(kind);` 那一句删掉 ⇒ 本条红");
                    Check(cK.Players[0].Board[BoardSpec.WarlordSlot].CurrentAttackType == UnitState.AttackTypeRanged,
                          "★ 而且**卡上那一格真的被改了**（`SetCurrentAttackType` = 原版 `CardScript.ChangeAttackType`；"
                        + $"近战 → {(cK.Players[0].Board[BoardSpec.WarlordSlot].CurrentAttackType == UnitState.AttackTypeRanged ? "远程" : "?")}）"
                        + " —— 原版那颗按钮那一下就干这个");
                }

                // ------------------------------------------------------------
                //  ⑬ 🆕 2026-10-18（审查 K8）：**「脚本接管 AI 回合」那一支的断言**（原来零覆盖）。
                //     走产品那条 `DriveAiTurn`（不是 `DriveTutorialScriptForTest`）——
                //     它才是真机上 AI 回合真正走的那条路。
                // ------------------------------------------------------------
                {
                    driver.BeginTutorial(0);
                    var cA = driver.Ctx;
                    var tA = cA.Tutorial;
                    // 把第 1 回合推到 `EndTurn(P)`（与主流程同一套动作），再收回合 ⇒ 进 AI 的第 2 回合
                    DriveStep();                                         // 0 → 1（`SmallTip`；`waitForTip` ⇒ 顺手点掉）
                    driver.ContinueTutorialScriptForTest();              // 玩家做掉 `AttackFreeMode` ⇒ 1 → 2
                    DriveStep();                                         // 2 → 3
                    DriveStep();                                         // 3 → 4
                    Check(DriveStep() == BattleDriver.TutorialStep.WaitingForActor
                          && tA.ActionCounter == 4 && !driver.TutorialWaitingForTip,
                          "（前提）指针落在第 1 回合最后那条 `EndTurn(P)`"
                        + "｜🧨 两态判别式：被 `_tutTipUp` 挡住时驱动返回的是 `Advanced`（不是 `WaitingForActor`）"
                        + " ⇒ 本条当场红 —— 批处理没有帧循环，提示不会自己消（`DC_教程推进21红.md` R1）");
                    driver.SimulateEndTurn();
                    Check(cA.Turn == 2 && tA.ActionCounter == 0, "（前提）进第 2 回合（AI 的脚本回合），指针归零");

                    // 第 2 回合 4 条**全是脚本自己执行的** ⇒ 每调一次 `DriveAiTurn` 推一条；
                    // 推完（`Exhausted`）⇒ 那一支自己**交回合**（原版 `_PlayAi` 的 `case 8`）
                    // 🆕 2026-10-19（战斗线 W 复跑红 #10–12）：**每步之前先把上一批演出推到放行**。
                    //   生产里这一步是 `Update` 每帧做的（`AdvanceTimeline` 在 `DriveAiTurn` 之前）；
                    //   批处理没有帧循环 ⇒ 不补的话 W 段的闸会让 `DriveAiTurn` 一条脚本都不推（假红）。
                    void AiStep()
                    {
                        StepThrough(driver);
                        int wgAI = 0;
                        while (driver.WaitingForBlockingAction && wgAI++ < 400) Step(1f / 30f);
                        driver.DriveAiTurnForTest();
                    }
                    AiStep();                         // Attack
                    Check(tA.ActionCounter == 1 && cA.Turn == 2, "★ **脚本接管 AI 回合**：`DriveAiTurn` 推的是脚本，不是 `SimpleAI`");
                    AiStep();                         // AiChat（纯演出）
                    AiStep();                         // PlayerChat（纯演出）
                    Check(tA.ActionCounter == 3 && cA.Turn == 2, "（前提）推到第 3 条，回合还没变");
                    AiStep();                         // EndTurn（脚本里是 no-op）
                    Check(tA.ActionCounter == 4 && cA.Turn == 2, "（前提）4 条跑完，仍在 AI 回合");
                    AiStep();                         // Exhausted ⇒ 收尾交回合
                    Check(cA.Turn == 3 && tA.Turn == 3 && tA.ActionCounter == 0,
                          $"★ **脚本跑完 ⇒ 那一支自己交回合并推进**（回合 {cA.Turn}、指针 {tA.ActionCounter} 归零）"
                        + "｜🧨 把 `DriveAiTurn` 里那段 `if (TutorialOwnsThisTurn) { … }` 删掉 ⇒ 本条红"
                        + "（AI 会改走 `SimpleAI`，与脚本抢着动）");
                }

                // ============================================================
                //  ⑭ 🆕 2026-10-18（A940）：**教程表现层**（原版那棵 `Tutorial` 子树）
                //     判据表 = `资料/普查产出_1018/R2_教程族现核.md` §4（逐元素 `文件:行号`）。
                //     🔴 这一节的断言一律**断「该显时显 / 该藏时藏」两态**（只断「建起来了」不算 —— 铁律里踩过）。
                // ============================================================
                {
                    // ---- ① 前提：表现层建出来了 ----
                    driver.BeginTutorial(0);
                    Check(driver.TutorialView != null,
                          "★ 教程表现层挂出来了（`TutorialOverlay` 建在 `HudRoot` 下 —— 原版那棵树在 `battlearena1` 的 `Tutorial` 根）");
                    // ---- ①·b 🆕 2026-10-17（`N49①`）：四颗教学标注的**细黑描边** ----
                    // 判据 = 原版材质 `bundle_fonts_assets_all/Material/Material_751232751962157263.json`
                    //   「`Asar-Regular Light Grey w outline thin`」：`_OutlineWidth 0.10` · `_FaceDilate 0.10` ·
                    //   `_OutlineSoftness 0` · `_OutlineColor (0,0,0,1)`；落点 `Battle/TutorialOverlay.ApplyThinOutline`。
                    if (driver.TutorialView != null)
                    {
                        int outlined = 0;
                        bool sharedDirty = false;
                        for (int ai = 0; ai < 4; ai++)
                        {
                            var al = driver.TutorialView.AnnoLabel(ai);
                            // 🔴 **2026-10-17（R1 现核）**：TMP 是 `Label` 的**子节点** ⇒
                            //   `GetComponent` 恒 null（原来这一口 + 实现那一口同错，4 条全静默跳过）。
                            var at = al != null ? al.GetComponentInChildren<TMPro.TMP_Text>(true) : null;
                            var am = at != null ? at.fontMaterial : null;
                            if (am == null) continue;
                            bool okW = Mathf.Abs(am.GetFloat(TMPro.ShaderUtilities.ID_OutlineWidth) - 0.10f) < 1e-4f;
                            bool okD = Mathf.Abs(am.GetFloat(TMPro.ShaderUtilities.ID_FaceDilate) - 0.10f) < 1e-4f;
                            bool okS = Mathf.Abs(am.GetFloat(TMPro.ShaderUtilities.ID_OutlineSoftness)) < 1e-4f;
                            var oc = am.GetColor(TMPro.ShaderUtilities.ID_OutlineColor);
                            bool okC = oc.r < 1e-3f && oc.g < 1e-3f && oc.b < 1e-3f;
                            if (okW && okD && okS && okC) outlined++;
                            // 🔴 **2026-10-17 订正（末轮红）**：原判据读 `at.fontSharedMaterial` —— 但 TMP 的
                            //   `fontMaterial` getter（上面 `am`）内部会把 `m_sharedMaterial` 指向**这一颗的实例**
                            //   ⇒ 再读 `fontSharedMaterial` 读到的是**实例**、描边当然在 ⇒ 假红。
                            //   真正要证明的是「**字体资产自己那份**没被写脏」= `at.font.material`。
                            var sm = at.font != null ? at.font.material : null;
                            if (sm != null && Mathf.Abs(sm.GetFloat(TMPro.ShaderUtilities.ID_OutlineWidth) - 0.10f) < 1e-4f)
                                sharedDirty = true;
                        }
                        Check(outlined == 4,
                              $"★ 四颗教学标注都上了原版那圈**细黑描边**（`_OutlineWidth 0.10` / `_FaceDilate 0.10` / "
                            + $"`_OutlineSoftness 0` / 黑；四颗里对得上的 = {outlined}）"
                            + "｜🧨 删掉 `TutorialOverlay.Build` 里那句 `ApplyThinOutline(_annoLabels[i])` ⇒ 本条红");
                        // 🔴 **灭自证（不许碰共享材质）**：原版值必须只落在**实例材质**上 —— 谁把
                        //    `fontMaterial` 换成 `fontSharedMaterial`，字体资产那份就会被永久写脏（`Resources/` 里
                        //    那份 `.asset` 是 git 跟踪的）⇒ 这一条抓的是「共享材质的 `_OutlineWidth` 仍是 0」。
                        Check(!sharedDirty,
                              "★ **灭自证（实例材质）**：字体资产那份**共享材质**的 `_OutlineWidth` 没被改成 0.10"
                            + "（原版 `NotoSerifCJK-Regular SDF Material` 的 `_OutlineWidth = 0`）"
                            + "｜🧨 把 `ApplyThinOutline` 里的 `t.fontMaterial` 改成 `t.fontSharedMaterial` ⇒ 本条红");

                        // ══ 🆕 **2026-10-17（`A1024`③ 批 2–4）：教程覆盖层八颗字的面** ══
                        //    判据 = 原版 TMP 的 `m_fontAsset`（现读 `battle1_tmp.tsv`；普查表 §二附录
                        //    「战斗教程覆盖」那一行写明的**唯一判据**）：
                        //      `TutorialTip/Generic Popup Background/TipText` = **Pragati**（fs36）
                        //      `TutorialTip/ContinueText`                    = **Asar**（fs4.5）
                        //      `InitTutorialTip/TipText` · `TipText (1)`     = **Asar**（fs5.2，两颗）
                        //      `TutorialObjs/{Melee,Ranged,Health,Energy}Text` = **Asar**（fs30，四颗）
                        //    ⚠️ 标注四颗的材质判据（`Asar-Regular Light Grey w outline thin`，见上面 `N49①`）
                        //    与这一行**互相印证**；⛔ 别按「提示条都是 Pragati」一刀切（`ContinueText` 是 Asar 例外）。
                        {
                            var tv = driver.TutorialView;
                            string[] tvName = { "TipText", "ContinueText", "InitTipText", "InitTipText (1)",
                                                "MeleeText", "RangedText", "HealthText", "EnergyText" };
                            TmpFont.Face[] tvFace = { TmpFont.Face.LatinCardBody, TmpFont.Face.LatinUi,
                                                      TmpFont.Face.LatinUi, TmpFont.Face.LatinUi,
                                                      TmpFont.Face.LatinUi, TmpFont.Face.LatinUi,
                                                      TmpFont.Face.LatinUi, TmpFont.Face.LatinUi };
                            string[] tvAsset = { "Pragati-Regular SDF", "Asar-Regular SDF",
                                                 "Asar-Regular SDF", "Asar-Regular SDF",
                                                 "Asar-Regular SDF", "Asar-Regular SDF",
                                                 "Asar-Regular SDF", "Asar-Regular SDF" };
                            for (int ti = 0; ti < 8; ti++)
                            {
                                var tl = ti < 2 ? tv.TipLabel(ti) : (ti < 4 ? tv.InitLabel(ti - 2) : tv.AnnoLabel(ti - 4));
                                var tt = tl != null ? tl.GetComponentInChildren<TMPro.TMP_Text>(true) : null;
                                string tGot = tt != null && tt.font != null ? tt.font.name : null;
                                string tTxt = tl != null ? tl.Text : null;
                                bool tCjk = tTxt != null && Loc.HasCjk(tTxt);
                                string tWant = tCjk ? "NotoSerifCJK-Regular SDF" : tvAsset[ti];
                                Check(tl != null && tl.Face == tvFace[ti],
                                      $"★ A1024③/批2–4：教程覆盖 `{tvName[ti]}` 被点名 = **{tvFace[ti]}**"
                                    + $"（原版同节点 `m_fontAsset` = {tvAsset[ti]}），"
                                    + $"实得 `{(tl != null ? tl.Face : TmpFont.Face.Cjk)}`"
                                    + (ti == 0 ? " —— 🧨 把提示条整族当成 Asar ⇒ 本条红" : ""));
                                Check(tGot == tWant,
                                      $"★ A1024③/批2–4：教程覆盖 `{tvName[ti]}` 的实际字体 = `{tWant}`"
                                    + $"（文本「{Short(tTxt, 18)}」{(tCjk ? "含汉字 ⇒ 汉字闸回 CJK" : "纯拉丁")}），实得 `{tGot}`");
                            }
                        }
                    }
                    // 🔴 **2026-10-18（A991）**：这一句原来断的是 `TutorialView.SkipVisible` —— 那时那颗钮
                    //   建在 `TutorialOverlay` 那棵 **HUD 子树**上（**落点错**）。原版那颗钮的父链是
                    //   `SkipTutorial Button → Bottom buttons → **BattleSettingsPanel**`（13/13 场景同构、
                    //   每包恰 1 份）⇒ 现在「钮亮不亮」就是**设置面板开着没有**（原版那颗在场景里是
                    //   `(inactive)`，运行期由齿轮打开面板才见）⇒ 改读 `driver.Settings.SkipTutorialShown`。
                    //   ⚠️ 面板此刻是关的（前文 13 节点完「投降」之后它自己收起来了，见上面那条 `!sp.Visible`）。
                    Check(!driver.Settings.SkipTutorialShown,
                          "★ **判别式（一半）**：教程局刚开、设置面板**没开** ⇒ 跳过钮**不画**"
                        + "（钮是设置面板的子件 ⇒ 跟着面板开关走；原版那颗本来就是 `BattleSettingsPanel` 下的）");
                    driver.Settings.Show();
                    Check(driver.Settings.SkipTutorialShown,
                          "★ **判别式（另一半）**：打开设置面板 ⇒ 那颗钮**画出来了**"
                        + "｜🧨 改坏法：把 `SettingsPanel.SetActive` 里那句 `_skipBtn.SetActive(on)` 删掉"
                        + " ⇒ 开面板时那颗钮不跟着亮 ⇒ 两态同值 ⇒ 本条红");
                    Check(driver.Settings.SkipTutorialBuilt
                          && driver.Settings.SkipTutorialText == Loc.T(SettingsPanel.SkipTutorialTerm),
                          "★ 而且那颗钮**真建出来了**、字 = 词条 `Battle/Settings/SkipTutorial`"
                        + $"（实测「{driver.Settings.SkipTutorialText}」；原版 TMP 原文 `Skip tutorial`、fs38、同 `Resign`）");
                    // 🔴 **灭自证（结构）**：那颗钮**必须长在设置面板那棵树下**。
                    //    ⛔ 只断「`SkipTutorialShown` 跟着面板开关走」**不够** —— 把钮建回 `TutorialOverlay`
                    //    的 HUD 子树、再把 `SkipTutorialShown` 改成读 HUD 那一颗，**两边一起改照样全绿**。
                    //    这一条钉的是**树里的位置**：教程 HUD 子树下**不许再有** `SkipTutorial Button`
                    //    （原版那颗不在 HUD 上），而设置面板下**按名字找得到** `settings_skip_tutorial`。
                    var straySkip = driver.TutorialView != null
                                  ? driver.TutorialView.transform.Find("SkipTutorial Button") : null;
                    // 🔴 **2026-10-17（`BSC62` · W4）：找错根 —— 改走 `PanelRect`（= `_panel`）。**
                    //   那颗钮建在 `_panel`（画布下的面板帧）上（`SettingsPanel.cs:872`
                    //   `MakeSlicedPiece(_panel, …)`），而 `Settings.transform` 是 "SettingsPanel" **壳**，
                    //   `Transform.Find` **不递归** ⇒ 壳下直接子件里找不到它。`PanelRect` = 那个 `_panel`。
                    var inPanelSkip = driver.Settings != null && driver.Settings.PanelRect != null
                                    ? driver.Settings.PanelRect.Find("settings_skip_tutorial") : null;
                    Check(straySkip == null && inPanelSkip != null,
                          $"★ **灭自证（结构）**：教程 HUD 子树下 {(straySkip == null ? "没有" : "**还有**")} "
                        + $"`SkipTutorial Button` · 设置面板下 {(inPanelSkip == null ? "**找不到**" : "找得到")} "
                        + "`settings_skip_tutorial`"
                        + "｜🧨 改坏法：把钮建回 `TutorialOverlay`（或只把 `SkipTutorialShown` 改读 HUD 那一颗）⇒ 本条红");
                    driver.Settings.Hide();
                    Check(!driver.Settings.SkipTutorialShown,
                          "★ **判别式（收尾）**：关掉面板 ⇒ 那颗钮收回去（一开一关、一画一收 —— 两态真的分得开）");
                    Check(!driver.TutorialView.InitTipVisible,
                          "★ **`InitTutorialTip` 那一层建了但【不亮】** —— 🔴 原版**谁启用它查不到**（R2 §6·7）"
                        + " ⇒ 我们不发明触发条件（⛔ 不是「忘了做」，是「判据没有」）");

                    // ---- ①-b 🆕 2026-10-18（`G9`）：提示横向偏移量的**两态**（原版那个 `×1.3`）----
                    //   判据 = `AiScripted.GetHorizontalOffset` / `GetTipPosition`（两份方法体都读过）：
                    //   `fVar9` 算完之后，`if (*(char *)(*(longlong *)(DAT_18427be00 + 0xb8) + 0x11c) != 0)
                    //   fVar9 = fVar9 * DAT_1834b33f0;` —— 常量 `1.29999995f`（常量池实读），
                    //   那个布尔 = **`GameStaticData.smallScreenUI`**（`dump.cs` 字段表 `+0x11C`，逐格对得上）
                    //   ⇔ 我们的 `CardPresentation.SmallScreenUI.Enabled`。
                    //   ⚠️ 本场自检一开头就把这一格**压成关**（A175 那条纪律：不许随玩家偏好变红变绿）
                    //   ⇒ 这里显式翻两态、翻完**立刻放回关**（后面那些摆位断言都按「关」这一档量）。
                    {
                        Check(!SmallScreenUI.Enabled, "（前提）本场自检跑在 `smallScreenUI = 关` 那一档");
                        float baseSub  = BattleDriver.TutorialTipOffsetForTest(11);   // 督军那三档 ⇒ +0x38
                        float baseNorm = BattleDriver.TutorialTipOffsetForTest(0);    // 其余 ⇒ +0x34
                        Check(baseSub > 0f && baseNorm > 0f && Mathf.Abs(baseSub - baseNorm) > 1e-4f,
                              $"★ G9 关档：偏移量取的是**两个不同的值**（督军档 {baseSub:F4} / 普通档 {baseNorm:F4}）"
                            + " —— 「按锚点档二选一」这一条钉住（⛔ 不是同一个数）");
                        SmallScreenUI.Set(true);
                        float onSub = BattleDriver.TutorialTipOffsetForTest(11);
                        SmallScreenUI.Set(false);       // ⛔ 立刻放回：本节后面那些摆位断言都按「关」这一档量
                        Check(Mathf.Abs(onSub - baseSub * BattleDriver.TutSmallScreenFactor) < 1e-3f,
                              $"★ G9 **开档**：`smallScreenUI` 为真 ⇒ 偏移量 **×1.3**（{baseSub:F4} → {onSub:F4}）"
                            + "｜🧨 把 `TutorialTipOffset` 里那句 `if (SmallScreenUI.Enabled) v *= …` 删掉 ⇒ 两档同值 ⇒ 红"
                            + "（原来记的是「那个全局开关没定位 ⇒ 不乘」；`G9` 定位到了 = `GameStaticData.smallScreenUI`，`+0x11C`）");
                        Check(!SmallScreenUI.Enabled, "（收尾）开关放回**关**（本场自检的口径不变）");
                    }

                    // ---- ② `hide*` 那一族 · 第 1 关（`hideCardsLeftInDeck=1 · hideChat=1 · hideCemetery=0 · hideLargeCardDisplay=0`）----
                    Check(!driver.DeckSizeVisibleForTest,
                          "★ `hideCardsLeftInDeck = 1`（6 关**全 1**，判据 = `BattleManager__CanDisplayDeckSize.c:43-46`）"
                        + " ⇒ **牌库数**（两边文字 + 两块底板）**藏住了**");
                    Check(!driver.HandSizeVisibleForTest,
                          "★ **同一个开关的第二个消费者**（`PlayerHand__ShowHandSize.c:29-48`）⇒ **手牌数也藏住了**"
                        + "｜🧨 只做牌库那一半（审查点名的坑）⇒ 本条红");
                    Check(!driver.ChatButtonVisibleForTest,
                          "★ `hideChat = 1`（6 关**全 1**）⇒ **聊天那颗按钮**藏住了"
                        + "（判据 `BattleManager__TutorialSetup.c:52-60`；🔴 控的是那**颗按钮**，不是气泡面板）");
                    Check(!driver.CemeteryButtonVisibleForTest,
                          "★ 教程局里 `cemeteryButton` **无条件藏**（`TutorialSetup.c:~64`，与 `hideCemetery` 无关）"
                        + " —— 尽管第 1 关 `hideCemetery = 0`");
                    Check(driver.AllowsCardDisplayForTest,
                          "★ `hideLargeCardDisplay = 0`（6 关全 0）⇒ 大卡窗那一档**照常开着**（机制接上、本轮零效果）");

                    // ---- ③ **判别式：同一批元素、只换关卡开关 ⇒ 另一种状态** ----
                    var synth = new TutorialScript(new TutorialStageData
                    {
                        stage = 91, so = "<自检合成·hide* 反向>", playerStarts = true,
                        hideCardsLeftInDeck = false, hideChat = false, hideLargeCardDisplay = true,
                    });
                    driver.SetCardHoldForTest(true);      // 🆕 T13：「按住一张牌才亮张数」那一格（批处理里没有真指针）
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261018, tutorial: synth);
                    Check(driver.DeckSizeVisibleForTest && driver.HandSizeVisibleForTest,
                          "★ **判别式**：同一个合成关卡把 `hideCardsLeftInDeck` 设成 `false` ⇒ **牌库数与手牌数都显出来**"
                        + "（一藏一显 ⇒ 这一族断言既不可能是「恒藏」也不可能是「恒显」）"
                        + "｜⚠️ 前提是**按住了一张牌**（`SetCardHoldForTest(true)`）—— 原版这一件还要「按住」才亮，见下一条");
                    Check(driver.ChatButtonVisibleForTest, "★ **判别式**：`hideChat = false` ⇒ 聊天那颗按钮**显出来**");
                    // 🆕 2026-10-16（`A1239`）：手牌数那颗字**自己有框与三档**（判据含那条「单位桥」→
                    //   `BattleDriver.HandLabelBoxW` 的 doc：那颗活在缩放假里、**1 局域单位 = 100 px**）。
                    //   🔴 断「**渲染尺寸 ≤ 框**」、不断字号 —— 字号对而溢出时自检照样全绿（`AutoFitBox` 教训）。
                    //   ⚠️ 必须在这一格**显出来之后**量（TMP 在对象没激活时量不出尺寸 —— 本仓已知的坑）。
                    //   🧨 **改坏法**：把 `BuildHud` 里那句 `SetAutoFitBox` 删掉 ⇒ 落 `Label` 默认档、不再受框约束。
                    //   🔴 **2026-10-16（`T09` 字族迁 uGUI · `EW6` 接线）—— 两把尺改成【同尺 = 设计 px】**：
                    //     `HandLabelWorldW/H` 现在是 **设计 px**（判据 → `BattleDriver.HandLabelWorldW` 的 doc），
                    //     而框那两个数 `HandLabelBoxW/H` = **234 / 64**（原版 2.34/0.64 局域 × **100** 那条单位桥，
                    //     判据 → `HandLabelBoxW` 的 doc）⇒ 右项**原样写字面量**、⛔ 不再 `LayoutSpace.Px(...)`
                    //     （那个 ÷108 是**世界档**的换算；混进去右边只剩 2.17 ⇒ 恒红）。
                    //   🔴 **2026-10-23（已知 γ 收口）：字号四格从 ×100 订正成 ×10** —— 原版那颗是 **3D TMP**
                    //     （`m_isOrthographic = 0` ⇒ `orthographicMultiplier 0.1`）⇒ `m_fontSize 3.0` 只渲成 30 px em；
                    //     按 ×100 传 min = 50 px 时**自适应永远缩不进框**（Noto 行盒 1.516 × 50 = 75.8 高过 64）
                    //     ⇒ 本条长期红（164.75 × 75.81）。判据全文 → `BattleDriver.HandLabelBoxW` 的 doc。
                    //   🧨 **灭自证**：把 `HandLabelFsMin/Max/Base` 改回 50/300/300（= ×100 那一版）
                    //     ⇒ 高度回到 75.8 ⇒ 本条**必红**。上下两条闸各管一头：`≤ 64` 管「塞不进框」，
                    //     `≥ 15` 管「为了塞进框把字缩到看不见」（最大档 30 px em 时行盒约 45.5 px，离 15 很远）。
                    Check(driver.HandLabelWorldW > 0f
                          && driver.HandLabelWorldW <= 234f + 1e-4f
                          && driver.HandLabelWorldH <= 64f + 1e-4f
                          && driver.HandLabelWorldH >= 15f,
                          $"★ 手牌数那颗渲染尺寸 {driver.HandLabelWorldW:F4} × {driver.HandLabelWorldH:F4} **设计 px**"
                        + " 落在原版框 234 × 64 **px** 之内、且没有被缩成看不见（高 ≥ 15 px）"
                        + "（原版 `CardsInHandText`：框 2.34×0.64 局域 **×100** = 234×64 px；"
                        + "字号 auto 0.5~3.0 局域 **×10** = **5~30 px** —— 那颗是 3D TMP（`m_isOrthographic=0`）⇒ ×0.1）");
                    Check(!driver.CemeteryButtonVisibleForTest,
                          "★ 而 `cemeteryButton` **仍然是藏的** —— 它那条是「教程局无条件藏」，与 `hideCemetery` **无关**"
                        + "（这一对正好把两条判据分开）");
                    Check(!driver.AllowsCardDisplayForTest,
                          "★ **判别式**：`hideLargeCardDisplay = true` ⇒ `AllowsCardDisplay` 翻成 **false**"
                        + "（原版 `DisplayCard.c:44-50` 那一支；6 关全 0 ⇒ 真关卡上永远走不到）");

                    // ---- ④ 第三条腿：**非教程局，那两颗钮都得显出来** ----
                    driver.Begin(BattleDriver.DefaultFactionA, BattleDriver.DefaultFactionB, 20261019);
                    Check(driver.CemeteryButtonVisibleForTest && driver.ChatButtonVisibleForTest,
                          "★ **非教程局**：墓园钮与聊天钮**都显出来**（`Ctx.Tutorial == null` ⇒ 那一整段恒空转）"
                        + "｜🧨 把 `ApplyTutorialVisibility` 写成「只在教程局跑」而不还原 ⇒ 本条红"
                        + "（普通对局会**永久少两颗钮**，而且不报错）");
                    Check(driver.DeckSizeVisibleForTest && driver.HandSizeVisibleForTest,
                          "★ 非教程局 + **按住一张牌** ⇒ 牌库数/手牌数照旧显示（非教程=逐条还原）");
                    // 🆕 **2026-10-15（`T13` 普查 · 「该藏的时候藏住了吗」那一类）**：
                    //   **同一局、只翻「按住」这一个输入位** ⇒ 那一族必须跟着藏。
                    //   原版判据 = `CardScript.OnTouchDown` 按下才 `ShowDeckSize()`、松手在
                    //   `BattleManager__Update.c:140-150` 收起 ⇒ **常显是错的**（我们原来常显）。
                    driver.SetCardHoldForTest(false);
                    driver.ApplyTutorialVisibilityForTest();
                    Check(!driver.DeckSizeVisibleForTest && !driver.HandSizeVisibleForTest,
                          "★ **判别式**：松手（`SetCardHoldForTest(false)`）⇒ 牌库数/手牌数**都收起来**"
                        + "｜🧨 改回「常显」（或把 `CardHoldPeek` 短路成 `true`）⇒ 本条红");
                    driver.SetCardHoldForTest(true);
                    driver.ApplyTutorialVisibilityForTest();
                    Check(driver.DeckSizeVisibleForTest && driver.HandSizeVisibleForTest,
                          "★ 再按回去 ⇒ **又亮**（一藏一显 ⇒ 这一条既不可能是「恒藏」也不可能是「恒显」）");
                    driver.SetCardHoldForTest(null);        // 还原成看真指针，别影响后面的段
                    driver.ApplyTutorialVisibilityForTest();

                    // ---- ⑤ 督军两拍（原版 `BattleManager.TutorialStartSequence`，**不是动作档**）----
                    driver.BeginTutorial(0);
                    var fw = driver.BoardViewAt(BoardSpec.WarlordSlot, false);
                    Check(fw != null, "（前提）敌方督军的视图在场上");
                    Check(!fw.gameObject.activeSelf,
                          "★ **第一拍**：敌方督军的视图**先藏着**（原版：玩家督军 → `WaitForSeconds` → 敌方督军）");
                    driver.TickTutorialViewForTest(0.1f);
                    Check(fw.gameObject.activeSelf == false, "★ 第一拍还没到 ⇒ **仍然藏着**（判别式的一半）");
                    driver.TickTutorialViewForTest(1.0f);
                    Check(fw.gameObject.activeSelf,
                          "★ **第二拍**：过了节拍 ⇒ 敌方督军**显出来**（一藏一显 ⇒ 这一条真有鉴别力）"
                        + "｜🧨 把 `TickTutorialView` 里那两行删掉 ⇒ 上面三态对不上");

                    // ---- ⑥ 小提示（`SmallTip 61` 条；判据 = `TutorialTipScript` 那一套参数）----
                    var ov = driver.TutorialView;
                    Check(!ov.TipVisible, "★ 还没走到 `SmallTip` ⇒ 提示**不亮**（判别式的一半）");
                    // 🔴 这一处**故意不用 `DriveStep()`**：紧接着那几条断言（`ov.TipVisible` / `ov.TipText` /
                    //    `ov.TipContinueText`）要读的正是「提示正挂着」这一刻，而助手会**当场把它点掉**。
                    //    这里 = **裸驱动 + 两态判别式**；提示改由 ⑦ 那一段开头显式点掉。
                    //    原有写法只断 `== Advanced` —— 那是 `DC_教程推进21红.md` §6·3 点名的**弱断言**：
                    //    被 `_tutTipUp` 挡住时**也**是 `Advanced`（分不出「真推了一条」与「什么都没干」）。
                    Check(driver.DriveTutorialScriptForTest() == BattleDriver.TutorialStep.Advanced
                          && driver.Ctx.Tutorial.ActionCounter == 1 && driver.TutorialWaitingForTip,
                          "（前提）第 1 关第 1 回合第 0 条是 `SmallTip`（脚本自己执行）"
                        + "｜🧨 **两态判别式**：真推了一条 ⇒ `ActionCounter` 走到 1 **且**提示挂起来；"
                        + " 若被 `_tutTipUp` 挡住 ⇒ 驱动同样返回 `Advanced`，但 `ActionCounter` 仍停在 0 ⇒ 本条红");
                    var tipAct = driver.Ctx.Tutorial.CurrentTurn.actions[0];
                    Check(ov.TipVisible, "★ 走到 `SmallTip` ⇒ **提示亮起来**（原版 `BattleManager.ShowTutorialTip`）");
                    // 🔴 **2026-10-20（W58 · BTFIX3）**：这条判据写于「本地没有 I2 词条表」之前 —— 官方本地化
                    //   已于 **2026-10-18 并入**（`官方本地化_en+zh-CN.json`；判据 → `CLAUDE.md` 铁律 2 的
                    //   2026-10-18 就地补注）。生产链 = `BattleDriver.cs` 的 `SmallTip` 那一支：
                    //   `TutorialData/` + `textReference` ⇒ `Loc.OfficialCurrent`（取不到才回落 SO 的 `arg`），
                    //   记号再走 `CardIcons.RewriteMarks` ⇒ 期望值按**同一条链**算（⛔ 不是放宽：仍逐字比）。
                    string tipExpect = tipAct.arg ?? "";
                    if (!string.IsNullOrEmpty(tipAct.textReference))
                    {
                        string tipKey = "TutorialData/" + tipAct.textReference;
                        string tipVal = Loc.OfficialCurrent(tipKey);
                        if (!string.IsNullOrEmpty(tipVal) && tipVal != tipKey)
                            tipExpect = CardIcons.HasOfficialMarks(tipVal)
                                      ? CardIcons.RewriteMarks(tipVal, Loc.Current == AvailableLanguages.Chinese)
                                      : tipVal;
                    }
                    Check(ov.TipText == tipExpect,
                          "★ 提示正文 = **官方本地化表**（`TutorialData/` + `textReference`）那一份，"
                        + "取不到才回落 SO 的 `arg`（原版 `ScriptedAction.GetLocalizedText` 那条链；"
                        + "官方表 2026-10-18 已并入 ⇒ 中文档印中文）。"
                        + $"实测「{(ov.TipText ?? "").Substring(0, System.Math.Min(24, (ov.TipText ?? "").Length))}…」"
                        + $" · 期望「{tipExpect.Substring(0, System.Math.Min(24, tipExpect.Length))}…」");
                    Check(ov.TipContinueText == "",
                          "★ `tipWithContinue = false`（6 关 61 条**全是 false**）⇒ Continue 那一行**不显示**"
                        + "（机制照做）");
                    // ---- ⑥′ 🔴 **2026-10-18（`A1031⑤`）补强：上面那条只覆盖了【`false` 这一态】** ----
                    //   出厂 6 关 **61 条 `SmallTip` 全是 `tipWithContinue = false`** ⇒ 真数据
                    //   **永远走不到** `true` 那一支；而**词条那半句**（`TutorialOverlay.ContinueTerm`
                    //   → `Loc.T(…)`）**恰恰只在 `true` 那一支才印得出来**。
                    //   ⇒ 只断「`TipContinueText == ""`」时：把 `SetTip` 里那半句写死成常量、
                    //     或让它印**空串**/**键名**，今天**照样全绿** —— 这是**弱断言**（分不出两态）。
                    //   ⇒ 这里显式驱动一次 `withContinue = true`，**两语档各断一次**，
                    //     然后**原样还原**成 `false` 那一态（⑦ 起还要它挂着，⛔ 别把提示弄掉）。
                    {
                        var ovLangWas = Loc.Current;
                        string ovTextWas = ov.TipText;
                        var ovPosWas = ov.TipWorldPos;
                        // `_tipContinue` 那个 `Label` 的 GO（`TutorialOverlay.Build` 里叫
                        // `ContinueText`，挂 `TutorialTip` 下）—— 只读它的开关态，⛔ 不改任何东西。
                        var ovCont = ov.transform.Find("TutorialTip/ContinueText");

                        // （前提）词条在表里 —— ⛔ 不在 ⇒ `Loc.T` 回的是**键名本身**，
                        //   实现印键名、期望也是键名 ⇒ **假绿**（看不出「词条丢了」）。
                        Check(Loc.HasEntry(TutorialOverlay.ContinueTerm),
                              $"（前提）词条 `{TutorialOverlay.ContinueTerm}` 在表里"
                            + "（⛔ 不在 ⇒ 下面两条两边一起退化成键名 = 假绿）");
                        // 期望值的**独立出处**（⛔ 不从被测实现、也不从 `Loc.T` 现算）：
                        // 原版那颗 `ContinueText` TMP 的 `m_text` 原文就是 `Continue`。
                        Check(Loc.EnOf(TutorialOverlay.ContinueTerm) == "Continue",
                              "★ 那一行的**原版印刷值** = `Continue`（出处：原版 `ContinueText` 那颗 TMP 的 "
                            + "`m_text`；`Core/Loc.cs` 那条的英文列照它逐字）");

                        Loc.RestoreForTest(AvailableLanguages.Chinese);
                        string ovZhWant = Loc.T(TutorialOverlay.ContinueTerm);
                        ov.SetTip(true, ovTextWas, true, ovPosWas, 0f, TutRelation.Above);
                        string ovZhGot = ov.TipContinueText;
                        bool ovZhShown = ovCont != null && ovCont.gameObject.activeSelf;

                        Loc.RestoreForTest(AvailableLanguages.English);
                        string ovEnWant = Loc.T(TutorialOverlay.ContinueTerm);
                        ov.SetTip(true, ovTextWas, true, ovPosWas, 0f, TutRelation.Above);
                        string ovEnGot = ov.TipContinueText;
                        bool ovEnShown = ovCont != null && ovCont.gameObject.activeSelf;

                        Loc.RestoreForTest(ovLangWas);                       // 收尾：还给本节的语档
                        // 🔴 **还原**：后面 ⑦ 起读的是「`tipWithContinue = false`」那一态
                        //   （`DismissTutorialTip` 要提示还挂着）。`Above` + `dx = 0` ⇒ 位置不动。
                        ov.SetTip(true, ovTextWas, false, ovPosWas, 0f, TutRelation.Above);

                        Check(ovZhGot == ovZhWant,
                              "★ **中文档 · `withContinue = true`** ⇒ 那一行 = "
                            + $"`Loc.T(\"{TutorialOverlay.ContinueTerm}\")`（实得「{ovZhGot}」）"
                            + "｜🧨 改前只断 `false` 那一态 ⇒ 把这一行写死成 `\"Continue\"`/空串/键名"
                            + "都照样绿（`false` 那一支印的本来就是空串）");
                        Check(ovEnGot == ovEnWant,
                              $"★ **英文档 · 同一态** ⇒ 那一行 = 同一条词条的**英文列**"
                            + $"（期望「{ovEnWant}」／实得「{ovEnGot}」）"
                            + "｜🧨 只断一条语档的话，「写死中文那一版」在另一档下会照样绿");
                        // 🔴 **灭自证（结构）**：两档读数**必须不一样**、**都不许是键名**、**都不许空**
                        //   —— 三条一起挡「期望值也从实现那个口来」：实现被改坏成写死常量/空串/键名时，
                        //   这三条里至少一条红。而「把实现改回去」与「把这三条也一起改回去」
                        //   在结构上不可能同时满足（改回来就变成看不出两态的那一版）。
                        Check(ovZhGot != ovEnGot
                              && !string.IsNullOrEmpty(ovZhGot) && !string.IsNullOrEmpty(ovEnGot)
                              && ovZhGot != TutorialOverlay.ContinueTerm
                              && ovEnGot != TutorialOverlay.ContinueTerm,
                                  $"★ **灭自证**：两档读数**各是各的**（中「{ovZhGot}」／英「{ovEnGot}」）、"
                                + "**都不是键名**、**都不空**"
                                + "｜🧨 `SetTip` 那半句改回写死 `\"Continue\"` ⇒ 中文档那条红；"
                                + " 改成空串 ⇒ 上面两条都红；改成键名 ⇒ 本条红");
                        Check(ovZhShown && ovEnShown,
                              "★ …而且那一行**真的亮着**（`ContinueText` 那个 GameObject 被 "
                            + "`SetActive(true)`）—— 只改字不亮层 = 玩家什么都看不见，"
                            + "而只读 `TipContinueText` **看不出来**（它读的是 Label 存的串，不看开关）");
                    }
                    Check(!driver.TutorialView.HighlightVisible,
                          "★ 这一条**没有** `shouldHighlightElement` ⇒ 高亮**不亮**（判别式的另一半）");

                    // ---- ⑦ 高亮 + `K2`（玩家动作出场）----
                    // 🔴 上一条提示**看完了** ⇒ 这里替玩家点掉它。⛔ **不点的话脚本推不动** ——
                    //    `DriveTutorialScript` 开头的 `if (_tutTipUp) return Advanced;`（`BattleDriver.cs` **按内容找**，
                    //    逐字照原版）会让下面每一句驱动都变成空转（`DC_教程推进21红.md` R1）。
                    //    那一下 = 原版 `TutorialTipScript.Update` 里的左键抬起；`force=true` 跳过 `minTimeBeforeSkip`。
                    Check(driver.DismissTutorialTipForTest(true) && !driver.TutorialWaitingForTip,
                          "（前提）提示**真的被点掉了**（`DismissTutorialTip` 返回真 · 标志位归假）"
                        + "｜🧨 把 `DismissTutorialTip` 里清 `_tutTipUp` 那一句删掉 ⇒ 本条红，"
                        + " 而且下面每一条驱动都会空转（这就是 R1 那 20 条红的形状）");
                    Check(DriveStep() == BattleDriver.TutorialStep.WaitingForActor
                          && !driver.TutorialWaitingForTip,
                          "（前提）第 1 条是 `AttackFreeMode(playerAction = true)` ⇒ 脚本停住"
                        + "｜🧨 两态判别式：被 `_tutTipUp` 挡住时驱动返回的是 `Advanced` ⇒ 本条红");
                    Check(driver.TutorialEventsContain("玩家动作出场"),
                          "★ **K2**：脚本停住那一刻**调了一次 `ShowPlayerActionAnim`**"
                        + "（原版 RVA `0x180944290`，调用点本来在 `PlayScriptedTurn` 那一支里；"
                        + "`RuleEngine/Core/*` 本批冻结 ⇒ 挂到调用方，语义相同，已如实标）");
                    Check(ov.PointerVisible,
                          "★ **指点光标**亮着（原版 `CheckForTutorialPointer` 只在 `playerAction == 1` 时走）");
                    // 推到第 1 回合第 4 条 `EndTurn`（数据里 `shouldHighlightElement = true`、`positionReference = 90`）
                    driver.ContinueTutorialScriptForTest();
                    DriveStep();
                    DriveStep();
                    Check(!ov.HighlightVisible, "（前提）推到第 3 条（`SmallTip`）时高亮仍**不亮**");
                    Check(DriveStep() == BattleDriver.TutorialStep.WaitingForActor
                          && driver.Ctx.Tutorial.ActionCounter == 4 && !driver.TutorialWaitingForTip,
                          "（前提）指针落在第 4 条 `EndTurn`（等玩家）"
                        + "｜🧨 两态判别式：上面那两条 `SmallTip` 的提示没点掉 ⇒ 这里驱动返回 `Advanced`"
                        + "（不是 `WaitingForActor`）⇒ 本条红（`DC_教程推进21红.md` R1）");
                    Check(ov.HighlightVisible,
                          "★ **高亮**：`EndTurn` 那一条 `shouldHighlightElement = true`、`positionReference = 90`"
                        + "（= 结束回合那颗钮，`dump.cs` TypeDefIndex 478）⇒ **高亮亮起来**"
                        + "｜🧨 这一前一后两条（`:1360x` 那一对）就是它的判别式");

                    // ---- ⑧ 教学标注四块（`ActivateHandCards 170`）----
                    Check(!ov.AnnotationsVisible, "（前提）别的档上四块标注**不显示**");
                    var ahAct = new TutorialAction
                    {
                        type = "ActivateHandCards",
                        data = new[] { new TutorialActionData { type = (int)ScriptedActionType.ActivateHandCards } },
                    };
                    driver.ApplyTutorialActionViewForTest(ahAct);
                    Check(ov.AnnotationsVisible,
                          "★ `ActivateHandCards` ⇒ **教学标注四块**亮（原版 `TutorialObjs/UnitObjs` + `EnergyText`；"
                        + "⚠️ 那四句文案与四根箭头的位置**是我们挑的** —— 原版是 TMP + 远端 I2 词条）");
                    driver.ApplyTutorialActionViewForTest(
                        new TutorialAction { type = "SmallTip", data = new[] { new TutorialActionData { type = 80 } } });
                    Check(!ov.AnnotationsVisible || ov.TipVisible,
                          "★ **判别式**：换成别的档 ⇒ 四块标注收掉（原版有对应的 `Hide…` 那一支）");

                    // ---- ⑨ 跳过钮：点的命中 + 语义（原版 `BattleManager.ClickSkip`）----
                    // 🔴 **2026-10-18（A991）**：命中判定搬到了**设置面板**那颗钮上（`HitSkipTutorial`）——
                    //    断言照旧读**真身**（走与真实输入同一条判定）。命中算法与 `HitResign`
                    //    逐字同形：同一个 `RectContains`、同一套 300×90（两颗互为镜像位）。
                    // ✅ **2026-10-18（第三会话）订正（铁律 5）**：本行原来写「钮搬走了，`TutorialOverlay` 上
                    //    那几个口（`ClickSkipAt` / `SkipWorldPos`）**只是转发**（零像素）」—— **过时**：
                    //    那四个口（`SkipPanel` / `SkipVisible` / `SkipWorldPos` / `ClickSkipAt`）**已删**
                    //    （`Battle/TutorialOverlay.cs` 里只剩「【已删】」留痕）。**本批断言一个字都没依赖它们**，
                    //    所以只是注释过时、没有行为问题。
                    var spSkip = driver.Settings;      // 与 14 节点那颗 `sp` 同一个对象（`SettingsPanel.Create` 只建一次）
                    spSkip.Show();
                    Check(spSkip.HitSkipTutorial(spSkip.SkipTutorialWorldPos), "★ 点在跳过钮上 ⇒ **命中**");
                    Check(!spSkip.HitSkipTutorial(spSkip.SkipTutorialWorldPos + new Vector3(3f, 0f, 0f)),
                          "★ **判别式**：偏出 3 个世界单位（≈324 px）⇒ **不命中**");
                    spSkip.Hide();
                    Check(!spSkip.HitSkipTutorial(spSkip.SkipTutorialWorldPos),
                          "★ **判别式**：面板关着 ⇒ **同一个坐标也不命中**（判据里 `!Visible` 那道闸 —— 与 `HitResign` 同形）"
                        + "｜🧨 改坏法：把 `HitSkipTutorial` 里的 `if (!Visible …) return false;` 删掉 ⇒ 本条红"
                        + "（面板关着也认账 = 点在那儿会平白跳过）");
                    // ⚠️ 这一条**显式把计时归零**再断：上面那两拍 `Tick` 已经把秒数走掉了
                    //    （`Tick` 是自检显式喂的；产品里由 `Update` 喂）。
                    ov.SetShownForTest(0f);
                    Check(!ov.SkipAllowed && !driver.TutorialTrySkipForTest(),
                          "★ **还没到跳过的时候**（原版 `minTimeBeforeSkip = 1.0s`）⇒ `TrySkip` 返回 false"
                        + "（且**出声** —— 不静默吞掉这一下）｜🧨 把那个闸删掉 ⇒ 本条红");
                    ov.SetShownForTest(2f);
                    Check(driver.TutorialTrySkipForTest(), "★ 过了 1 秒 ⇒ 这一下**算**（`TrySkip` 返回 true）");
                    Check(driver.TutorialView.SkipClickedByPlayer, "★ 而且记下来了（`SkipClickedByPlayer`）");

                    // ---- ⑩ 跳过的**语义**：把我方督军判死 ⇒ 对局当场结束（原版 `DeadHero(bm, 0, 4)`）----
                    driver.BeginTutorial(0);
                    Check(!driver.Ctx.IsOver, "（前提）刚开的教程局还没分胜负");
                    driver.ApplyTutorialSkipForTest();
                    Check(driver.Ctx.IsOver && driver.Ctx.Players[0].Warlord.Health == 0,
                          "★ **「跳过教程」= 把我方督军判死**（原版 `BattleManager__ClickSkip.c`："
                        + "`playMode == 100 ⇒ DeadHero(bm, 0, 4)`）⇒ 对局当场结束"
                        + "｜🧨 把它写成「什么都不做」⇒ 本条红");
                    Check(driver.Ctx.Winner == 1 - driver.MySideForTest + 1,
                          $"★ 而且判的是**对方胜**（6 关 `playerAlwaysWins` 全 false ⇒ 死了就是输；"
                        + $"实测 `Winner = {driver.Ctx.Winner}`）—— 与 B29 那条 `playerAlwaysWins` 的机制自洽");

                    // ---- ⑩-b 🆕 2026-10-18（A991）：**真实那条链** —— 开设置窗 → 点那颗钮 ----
                    //   原版 `BattleSettingsWindow__SkipTutorialButtonOnClick.c`（方法体亲读）是**两行、这个先后**：
                    //   `WindowsManager.CloseWindow(<设置窗>)` **然后** `BattleManager.ClickSkip(bm, 0)`。
                    //   我们照抄 ⇒ 走**产品那条 uGUI 链**：`BattleHudButton` 的点击 →
                    //   `SettingsPanel.OnSkipTutorialClicked`（先 `Hide()`）→ `OnSkipTutorial` 回调
                    //   （🔴 **2026-10-20（`T09` WIRE）：本段顺带验 D 半的接线** —— 那条回调没接时
                    //    `OnSkipTutorialClicked` 只 `LogWarning` ⇒ 下面第二档「判死」必红）。
                    //   ⚠️ 旧写法用 `driver.SettingsClickAt(...)`（手搓链，`T09` A3-b2 之后产线上不可达，
                    //   而且**绕过**回调口 ⇒ 断不出接线）。
                    //   🔴 **两态判别式**：同一颗钮、同一个坐标，只翻「`minTimeBeforeSkip` 那道闸过没过」
                    //      ⇒ 一档**只关窗**、另一档关窗**并且判死**。
                    var spChain = driver.Settings;
                    driver.BeginTutorial(0);
                    driver.TutorialView.SetShownForTest(0f);       // 闸门之内（`BeginTutorial` 会把 `_shownFor` 归零）
                    spChain.Show();
                    Check(spChain.Visible && spChain.HitSkipTutorial(spChain.SkipTutorialWorldPos),
                          "（前提）设置窗开着、指针落在那颗钮上");
                    spChain.ResetClickCountForTest("SkipTutorial Button");
                    spChain.ClickForTest("SkipTutorial Button");
                    Check(spChain.ClickCountForTest("SkipTutorial Button") == 1,
                          "（前提）这一下走的是那颗钮的 **uGUI 点击**（`BattleHudButton` 计数 = 1）");
                    Check(!spChain.Visible,
                          "★ **先关设置窗**（原版那两行的第一行 `CloseWindow`；⛔ 别把这个先后倒过来）");
                    Check(!driver.Ctx.IsOver,
                          "★ **闸门之内 ⇒ 只关窗、不判死**（`minTimeBeforeSkip` 挡住了语义那一半）"
                        + "｜🧨 改坏法：把 `SkipTutorialFromSettings` 里那句 `if (ov != null && !ov.TrySkip()) return;` 删掉 ⇒ 本条红");

                    driver.BeginTutorial(0);
                    driver.TutorialView.SetShownForTest(2f);       // 过了 1 秒
                    spChain.Show();
                    spChain.ResetClickCountForTest("SkipTutorial Button");
                    spChain.ClickForTest("SkipTutorial Button");
                    Check(spChain.ClickCountForTest("SkipTutorial Button") == 1,
                          "（前提）第二局、同一颗钮再点一次（uGUI 计数 = 1）");
                    Check(!spChain.Visible, "★ 还是**先关设置窗**（两档都一样 —— 这一半与闸门无关）");
                    Check(driver.Ctx.IsOver && driver.Ctx.Players[0].Warlord.Health == 0,
                          "★ **判别式（另一半）**：过了 1 秒 ⇒ 关窗**之外**还把我方督军判死 ⇒ 对局当场结束"
                        + "（原版 `BattleManager__ClickSkip.c`：`playMode == 100 ⇒ DeadHero(bm, 0, 4)`）");
                    Check(driver.Ctx.Winner == 1 - driver.MySideForTest + 1,
                          $"★ 而且判的是**对方胜**（同 ⑩；实测 `Winner = {driver.Ctx.Winner}`）");

                    // 🔴 **如实标注（一处真偏离 · ⛔ 别为了「对齐原版」把它删掉）**：
                    //   上面**第一档**（只关窗、不判死）**原版没有** —— `minTimeBeforeSkip` 是
                    //   `TutorialTipScript` 的字段（管的是**提示自己**什么时候能被消），**原版那颗钮没有这道闸**。
                    //   我们把它接在 `TrySkip` 上、于是顺带管住了这颗钮 = **一处真偏离**；
                    //   实际影响 ≈ 0（设置窗得玩家先点齿轮才开得出来，那时 `_shownFor` 早过 1 秒）。
                    //   要删得**两处一起改**（`TutorialOverlay.TrySkip` + 这里这两条 §⑨/⑩-b 的断言）。
                    //   判据与出处 → `BattleDriver.SkipTutorialFromSettings` 的 doc 末段。
                }

                // ============================================================
                //  ⑮ 🆕 2026-10-18（A940 收尾）：`skipNormalBattleEndOnVictory/Defeat`
                //     （`TutorialStage +0x60/+0x70`；6 关**全 false** ⇒ 今天零可见影响，机制照接 —— 铁律 11）
                //     🔴 **两态判别式**：同一个合成关卡，只改「赢/输」与那两个开关 ⇒ 结算面板的
                //        **出口闸门**一个关着、一个立刻开。⛔ 不是「建起来了」那种断言。
                // ============================================================
                {
                    var synthEnd = new TutorialScript(new TutorialStageData
                    {
                        stage = 92, so = "<自检合成·skipNormalBattleEnd>", playerStarts = true,
                        skipNormalBattleEndOnVictory = true, skipNormalBattleEndOnDefeat = false,
                    });
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261020, tutorial: synthEnd);

                    driver.Ctx.Winner = driver.MySideForTest + 1;      // 假装**我方赢**
                    Check(driver.TutorialSkipsNormalEndForTest,
                          "★ 我方赢 + `skipNormalBattleEndOnVictory = true` ⇒ **该跳**"
                        + "（判据 `dump.cs:42066` 的 `TutorialStage +0x60`）");
                    driver.Ctx.Winner = 1 - driver.MySideForTest + 1;  // 假装**对方赢**
                    Check(!driver.TutorialSkipsNormalEndForTest,
                          "★ **判别式**：同一个关卡、改成对方赢 ⇒ 那一格是 `onDefeat = false` ⇒ **不跳**"
                        + "（一真一假 ⇒ 这一条既不可能是「恒跳」也不可能是「恒不跳」）");
                    driver.Ctx.Winner = 3;                             // 平局
                    Check(!driver.TutorialSkipsNormalEndForTest,
                          "★ 平局（`Winner == 3`）⇒ **两个开关都不适用**（⛔ 别拿 `== 3` 去套输的那一格）");

                    // ---- 结算面板那两态：一个「演出还在走」、一个「一帧推完」----
                    var ep = driver.End;
                    Check(ep != null, "（前提）结算面板在（`BattleDriver.End`）");
                    if (ep != null)
                    {
                        ep.Hide();
                        ep.Show(driver.MySideForTest + 1, driver.MySideForTest, 0, 3,
                                -1, -1, skipSequence: false);                  // ← 正常那条路
                        bool normalExitable = ep.ExitReady;
                        float len = ep.Doors != null ? ep.Doors.Length : 0f;
                        bool playing = ep.Doors != null && ep.Doors.Playing && !ep.Doors.Finished;
                        ep.Hide();
                        ep.Show(driver.MySideForTest + 1, driver.MySideForTest, 0, 3,
                                -1, -1, skipSequence: true);                   // ← 跳的那条路
                        bool skipExitable = ep.ExitReady;
                        float el = ep.Doors != null ? ep.Doors.Elapsed : 0f;

                        if (len > 0f)
                        {
                            Check(!normalExitable && playing,
                                  $"★ **没跳**：`Show(skipSequence: false)` ⇒ 开门视频**还在走**（片长 {len:F2}s）"
                                + " ⇒ **出口闸门关着**（`ExitReady = Visible && Doors.Finished`）");
                            Check(skipExitable && el >= len - 1e-4f,
                                  $"★ **跳了**：`Show(skipSequence: true)` ⇒ 一帧推完（`Elapsed {el:F2}` / 片长 {len:F2}）"
                                + " ⇒ **出口闸门立刻开**"
                                + "｜🧨 把 `EndPanel.Show` 里那句 `_doors.Advance(_doors.Length)` 删掉 ⇒ 本条红"
                                + "（而真机上的表现是「跳过之后出不去」—— 那正是我们**不**用「根本不 SetupDoor」的原因）");
                        }
                        else
                        {
                            // 这一台下**没有**对应结局的开门视频 ⇒ 两条路本就等价（如实说，⛔ 不当成判别式成立）
                            Check(normalExitable && skipExitable,
                                  "（如实）这一台上**没有**胜利结局的开门视频（片长 0）⇒ 两条路**本来就等价**，"
                                + "这一对两态断言**在这一台上分辨不出来** —— 不是「跳了」，是「没有可跳的演出」");
                        }
                        ep.Hide();
                        Debug.Log($"[自检] `skipNormalBattleEnd*` 两态：片长 {len:F3} · 正常可出 {normalExitable}"
                                + " · 跳过可出 {skipExitable} · 推完 {el:F3}");
                    }
                }

                // ============================================================
                //  ⑯ 🆕 2026-10-18（`A940` 尾账 `Z1′`/`Z3` + `Z6` + `A939` + `A915`）
                //    四件各自的判据都写在对应方法的注释里；这里只断**可观测的两态**。
                //    ⛔ 没有一条是「建起来了」那种弱断言。
                // ============================================================

                // ---- ⑯-① `Z1′`：跳过结算演出时**不留视频最后一帧** ----
                {
                    var ep = driver.End;
                    Check(ep != null && ep.Doors != null, "（前提）结算面板 + 开门那一层都在");
                    if (ep != null && ep.Doors != null)
                    {
                        ep.Hide();
                        ep.Show(driver.MySideForTest + 1, driver.MySideForTest, 0, 3, -1, -1,
                                skipSequence: false);
                        bool normalDropped = ep.Doors.FrameDropped;
                        bool normalScreen = ep.Doors.ScreenVisible;
                        ep.Hide();
                        ep.Show(driver.MySideForTest + 1, driver.MySideForTest, 0, 3, -1, -1,
                                skipSequence: true);
                        bool skipDropped = ep.Doors.FrameDropped;
                        bool skipScreen = ep.Doors.ScreenVisible;
                        bool skipExitable = ep.ExitReady;

                        if (ep.Doors.Length > 0f)
                        {
                            Check(!normalDropped && normalScreen,
                                  "★ **没跳**那一档：视频照播、**最后一帧照留**（`FrameDropped = false`）"
                                + "—— 原版行为就是这样，⛔ 别顺手把两条路一起改");
                            Check(skipDropped && !skipScreen,
                                  "★ **跳了**那一档：`DropFrame()` 之后**那一帧不再留**（视频层也收掉了）"
                                + "｜🧨 删掉 `EndPanel.Show` 里那句 `_doors.DropFrame()` ⇒ 本条红");
                            Check(skipExitable,
                                  "★ 而且**闸门照样是开的**（`DropFrame` 只丢帧、不碰 `Finished`）"
                                + "—— 丢帧与开闸是两件事，⛔ 别把出不去当副作用");
                        }
                        else
                        {
                            Check(!normalDropped && !skipDropped,
                                  "（如实）这一台上没有对应结局的开门视频 ⇒ 两条路本来就等价，"
                                + "本条**在这一台上分辨不出来**（不是「跳了」）");
                        }
                        ep.Hide();
                    }
                }

                // ---- ⑯-② `Z3`：`hideCemetery` 那条闸（`CanShowCemetery`）真的挡得住 ----
                {
                    // 合成关卡：`hideCemetery = 0`（= 数据里 6 关的真实值）⇒ 放行
                    var allowStage = new TutorialScript(new TutorialStageData
                    {
                        stage = 93, so = "<自检合成·hideCemetery=0>", playerStarts = true, hideCemetery = false,
                    });
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261021, tutorial: allowStage);
                    driver.ShowBattleLog();
                    Check(driver.CemeteryClickAllowedForTest,
                          "★ `hideCemetery = 0` ⇒ 闸门**放行**（原版 `CanShowCemetery` 读 `stage+0x29`）");
                    bool ateA = driver.ClickLogRowForTest(0);
                    Check(ateA && driver.LogSelectedRow == 0,
                          "★ 点第 1 行 ⇒ 被吃掉、且**记下了选中的行**"
                        + "（⚠️ 本局日志**不是空的** —— `A985⑥` 之后 `RuleCore.Draw` 会 `Emit(EvtKind.Draw)` ⇒ "
                        + "`RefreshBattleLog` 的 `default:` 会给它印一行 ⇒ `RowCardKey(0)` 非空、**这一下会真弹卡**；"
                        + "「点行」这一步照做）");
                    driver.BattleLog.Hide();
                    // 🔴 **2026-10-18（第三会话 · `A985⑥` 之后）：把【弹出来的那张卡】摆回基线。**
                    //    `A985⑥` 给 `RuleCore.Draw` 加了 `Emit(EvtKind.Draw)` ⇒ 日志**不再空** ⇒ 上面那一格
                    //    `ClickLogRowForTest(0)` 会**真弹一张卡**；而 `_logCard` 是 `_logPanel.transform` 的子件、
                    //    面板**只在 `BuildHud()` 建一次**（跨子用例同生共死），`BattleLog.Hide()` 又**不收卡**
                    //    （产品那条路是配对的，自检这一格不是）⇒ **残留会漏到下一个子用例**。
                    //    ⇒ 摆基线走**产品语义**：**面板此刻是关的** ⇒ `TickLogCard` 第一句就 `HideLogCard()`。
                    //    ⛔ **必须摆在这一段**（面板已关）；摆到下一格的 `ShowBattleLog()` **之后**，会被
                    //    当成「面板不可见 ⇒ 这一下不算点击」而**把下一格那条点击断言弄红**（本会话踩过一次）。
                    driver.SimulateLogHover(Vector3.zero);

                    // 合成关卡：`hideCemetery = 1` ⇒ **整下点击早退**（原版 `:76 return`）
                    var hideStage = new TutorialScript(new TutorialStageData
                    {
                        stage = 94, so = "<自检合成·hideCemetery=1>", playerStarts = true, hideCemetery = true,
                    });
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261022, tutorial: hideStage);
                    driver.ShowBattleLog();
                    Check(!driver.CemeteryClickAllowedForTest,
                          "★ **判别式**：同一个面板、只把关卡换成 `hideCemetery = 1` ⇒ 闸门**关上**"
                        + "（一开一关 ⇒ 这一条既不可能是「恒放行」也不可能是「恒拦」）");
                    // 🔴 摆正基线：日志面板只在 `BuildHud()` 里建**一次**（`BattleDriver.cs:11117`，`Begin()` 不重建），
                    //    而 `Show()/Hide()/ApplyEntries()` **都不碰** `SelectedRow`
                    //    （全仓只有构造 `BattleLogPanel.cs:606` 与 `SelectRow` 会写它）
                    //    ⇒ 上一个子用例（闸门**开**的那一格）点过第 0 行 ⇒ 此刻它是 **0**、不是 -1
                    //    （诊断 → `DC_教程推进21红.md` R2）。
                    //
                    // 🔴 **2026-10-18（第三会话 · `A985⑥` 之后）：还要把【弹出来的那张卡】也摆回基线。**
                    //    `A985⑥` 给 `RuleCore.Draw` 加了 `Emit(EvtKind.Draw)` ⇒ 日志**不再空** ⇒ 上面那一格
                    //    `ClickLogRowForTest(0)` 会**真弹一张卡**；而 `_logCard` 是 `_logPanel.transform` 的子件、
                    //    面板**只在 `BuildHud()` 建一次**（跨子用例同生共死），`BattleLog.Hide()` 又**不收卡**
                    //    （产品那条路是配对的，自检这一格不是）⇒ **残留会漏到这一格**。
                    //    ⇒ 摆基线走**产品语义**（面板已关 ⇒ `TickLogCard` 第一句就 `HideLogCard()`），⛔ 不开测试后门。
                    //    （诊断 → `普查产出_1018第三会话/DIAG_战斗日志行一红.md`；分类 = **δ 夹具前提不成立**）
                    Check(driver.LogHoverCardKey == null,
                          "（前提）闸门这一档开始前：**一张悬停卡都没弹着**"
                        + "｜🧨 若删掉上一格那句 `SimulateLogHover(Vector3.zero)` ⇒ 上次点行弹的卡残留 ⇒ 红"
                        + "（⚠️ 本条**只覆盖「之前没弹过卡」这一态**，如实标着 —— 铁律 5·c）");
                    driver.BattleLog.SelectRow(-1);
                    Check(driver.LogSelectedRow == -1, "（前提）闸门这一档开始前「还没点过任何一行」");
                    int selBefore = driver.LogSelectedRow;
                    bool ateB = driver.ClickLogRowForTest(0);
                    Check(ateB && driver.LogSelectedRow == selBefore,
                          "★ 闸门关着时：这一下**仍然被吃掉**（原版就在这颗按钮的处理函数里 return，"
                        + "点击传不到压暗层）—— 但**没有记下选中的行**"
                        + "（原版 `CemeteryLogManager__ClickCemeterySlider.c:76-77`：`CanShowCemetery` 为假就 `return`，"
                        + "而那个 `return` 在**行处理整段之前** —— 最近的赋值在 `:83`）"
                        + "｜🧨 把闸门删掉 ⇒ 这两条一起红（闸门若写错成「放行」⇒ 会调 `SelectRow(0)` ⇒ 值被改掉）");
                    Check(driver.LogHoverCardKey == null, "…而且没有弹任何卡");
                    driver.BattleLog.Hide();
                }

                // ---- ⑯-③ `Z6`：`waitForTip` 那条「等」真的在等 ----
                {
                    var tipStage = new TutorialScript(new TutorialStageData
                    {
                        stage = 95, so = "<自检合成·waitForTip>", playerStarts = true,
                        turns = new[]
                        {
                            new TutorialTurn
                            {
                                turnName = "Turn1", scriptedTurn = true, actionCount = 2,
                                actions = new[]
                                {
                                    new TutorialAction
                                    {
                                        index = 0, type = "SmallTip", arg = "等着这条提示",
                                        playerAction = false,
                                        smallTipParams = new TutorialSmallTip
                                        {
                                            positionReference = 0, positionRelation = 0,
                                            tipDuration = 5f, waitForTip = true,
                                        },
                                        data = new[] { new TutorialActionData { type = 80 } },
                                    },
                                    new TutorialAction
                                    {
                                        index = 1, type = "PlayCard", arg = "", playerAction = false,
                                        data = new[] { new TutorialActionData { type = 20 } },   // 认不出卡 ⇒ 不执行、但**指针会 ++**
                                    },
                                },
                            },
                        },
                    });
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261023, tutorial: tipStage);
                    driver.SyncTutorialTurnForTest();

                    var step1 = driver.DriveTutorialScriptForTest();
                    Check(step1 == BattleDriver.TutorialStep.Advanced && driver.TutorialWaitingForTip,
                          $"★ 第一条 `SmallTip(waitForTip=true)` 演完 ⇒ **脚本挂住了**"
                        + $"（`TutorialWaitingForTip = {driver.TutorialWaitingForTip}`）");
                    int after1 = tipStage.ActionCounter;
                    var step2 = driver.DriveTutorialScriptForTest();
                    Check(step2 == BattleDriver.TutorialStep.Advanced && tipStage.ActionCounter == after1,
                          $"★ **判别式**：再推一帧 ⇒ **指针一动不动**（还是 {tipStage.ActionCounter}）"
                        + "｜🧨 删掉 `DriveTutorialScript` 里那句 `if (_tutTipUp) return Advanced;` ⇒ 指针会跳到 2 ⇒ 红");

                    // 太早按（`minTimeBeforeSkip = 1.0s` 之内）⇒ 不算
                    Check(!driver.DismissTutorialTipForTest(false) && driver.TutorialWaitingForTip,
                          "★ 提示刚出来那一下按 ⇒ **不算**（原版 `TutorialTipScript.minTimeBeforeSkip = 1.0s`）");
                    Check(driver.TutorialTipLimit == 5f,
                          $"★ 自动消的上限 = **数据里的 `tipDuration`**（{driver.TutorialTipLimit}s，"
                        + "合成关卡里是 5 ⇒ 不是写死的）");

                    // 过 1 秒之后按 ⇒ 算，脚本接着走
                    driver.TickTutorialViewForTest(1.2f);
                    Check(driver.DismissTutorialTipForTest(false) && !driver.TutorialWaitingForTip,
                          "★ 过了 `minTimeBeforeSkip` 再按 ⇒ **消掉了**");
                    var step3 = driver.DriveTutorialScriptForTest();
                    Check(step3 == BattleDriver.TutorialStep.Advanced && tipStage.ActionCounter == after1 + 1,
                          $"★ 提示消掉之后脚本**接着走**（指针 {after1} → {tipStage.ActionCounter}）");

                    // 另一条腿：**到点自动消**（不等玩家按）——
                    //   ⚠️ 换一个**新的** `TutorialScript`：`UpdateTurn` 只在「回合号变大」时才写、
                    //      复用同一个实例的话指针不会归零（第二腿起点就被上一腿污染了）。
                    var tipStage2 = new TutorialScript(tipStage.Stage);
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261024, tutorial: tipStage2);
                    driver.SyncTutorialTurnForTest();
                    driver.DriveTutorialScriptForTest();
                    Check(driver.TutorialWaitingForTip, "（前提）第二条腿也是先挂住");
                    driver.TickTutorialViewForTest(5.5f);            // > tipDuration
                    Check(!driver.TutorialWaitingForTip,
                          "★ **自动消**：把时间推过 `tipDuration`（5s）⇒ 不用玩家按也放行"
                        + "｜🧨 删掉 `TickTutorialView` 里那句自动消 ⇒ 本条红（而另一条腿仍绿 ⇒ 两条腿分得开）");
                }

                // ---- ⑯-④ `A939`：战后脚本（`onVictory` 那 13 条） ----
                {
                    var winStage = new TutorialScript(new TutorialStageData
                    {
                        stage = 96, so = "<自检合成·onVictory>", playerStarts = true,
                        onVictory = new TutorialTurn
                        {
                            turnName = "Victory", scriptedTurn = true, actionCount = 2,
                            actions = new[]
                            {
                                new TutorialAction { index = 0, type = "AiChat", arg = "打得不错。", playerAction = false,
                                                     waitBefore = 0f, waitAfter = 1f,
                                                     data = new[] { new TutorialActionData { type = 60 } } },
                                new TutorialAction { index = 1, type = "RadioMessage", arg = "请到前线报到。", playerAction = false,
                                                     waitBefore = 0.5f, waitAfter = 0f,
                                                     data = new[] { new TutorialActionData { type = 90 } } },
                            },
                        },
                        onDefeat = new TutorialTurn { turnName = "Defeat", scriptedTurn = false, actions = new TutorialAction[0] },
                    });
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261025, tutorial: winStage);
                    driver.Ctx.Winner = driver.MySideForTest + 1;         // 我方赢（`IsOver` 是派生属性，不用手动置）
                    Check(driver.PostBattleScriptAvailableForTest,
                          "★ 门开着：`onVictory.scriptedTurn = true` 且 actions 非空"
                        + "（判据 `BattleManager__IsPostBattleScriptAvailable.c`，"
                        + "6 关实测全开、共 **13 条**）");
                    driver.Ctx.Winner = 1 - driver.MySideForTest + 1;      // 对方赢
                    Check(!driver.PostBattleScriptAvailableForTest,
                          "★ **判别式**：同一个关卡改成对方赢 ⇒ 走 `onDefeat`（`scriptedTurn = false`）⇒ **门关上**");
                    driver.Ctx.Winner = driver.MySideForTest + 1;
                    Check(driver.StartPostBattleScriptForTest() && driver.PostBattleScriptStarted,
                          "★ 起来了，而且**一共 2 条**（`PostBattleScriptCount == "
                        + driver.PostBattleScriptCount + "`）");
                    Check(!driver.StartPostBattleScriptForTest(),
                          "★ **幂等**：再叫一次不会重起（一局一次）");

                    // 一拍一条（间隔 = 上一条 `waitAfter` + 下一条 `waitBefore`）
                    Check(driver.PostBattleScriptStep == 0, "（前提）起来时还没演第一条");
                    driver.TickPostBattleScriptForTest(0.01f);            // 首条 `waitBefore = 0` ⇒ 立刻演
                    Check(driver.PostBattleScriptStep == 1,
                          $"★ 推第一拍 ⇒ 演掉第 1 条（步进 {driver.PostBattleScriptStep}）");
                    Check(driver.UnitChat.ShownSide == 1,
                          $"★ 第 1 条是 `AiChat` ⇒ 走**第 2 颗**气泡（`EnemyChatDisplay`，"
                        + $"实得 {driver.UnitChat.ShownSide}）");
                    Check(driver.UnitChat.ShownText == "打得不错。",
                          $"★ **台词就是数据里的 `arg`**（实得「{driver.UnitChat.ShownText}」）"
                        + "—— 原版走远端 I2 表按 `textReference` 取词条，本地没有那张表");
                    driver.TickPostBattleScriptForTest(1.6f);             // 1(上一条 waitAfter) + 0.5(下一条 waitBefore)
                    Check(driver.PostBattleScriptStep == 2,
                          $"★ 第二拍 ⇒ 第 2 条（步进 {driver.PostBattleScriptStep}）");
                    Check(driver.UnitChat.ShownSide == 2,
                          $"★ 第 2 条是 `RadioMessage` ⇒ 走**第 3 颗**气泡 `RadioChat`（实得 {driver.UnitChat.ShownSide}）"
                        + "｜🧨 把 `SpeakTutorialChat` 里那句 `if (RadioMessage) side = 2;` 删掉 ⇒ 本条红"
                        + "（原版判据 = `ShowRadioMessage → ShowChatBox(panel, 2, …)`）");
                    Check(driver.UnitChat.HasRadio,
                          "★ 而且 `RadioChat` 那一颗**真的建出来了**（原版场景里它是 `(inactive)`，别的两档够不着它）");
                    driver.TickPostBattleScriptForTest(0.01f);
                    Check(driver.PostBattleScriptDone,
                          $"★ 推完 ⇒ `PostBattleScriptDone`（步进 {driver.PostBattleScriptStep}/"
                        + $"{driver.PostBattleScriptCount}）");
                }

                // ---- ⑯-④′ `A939`：**真数据**（6 关 / 13 条）—— 上一格是合成夹具，这一格盯产物本身 ----
                //
                //  为什么必须单列一格：合成夹具能验「机制」，**验不了「产物里真有 13 条」**。
                //  `JsonUtility` 遇到类型不符**只留 null、不报错**（B29 已经在 `preMulligan` 上栽过一次）⇒
                //  「`onVictory` 读出来是 null」会伪装成「这一关本来就没有战后脚本」，而上一格照样全绿。
                //  判据 = `Resources/tutorial_stages.json`（2026-10-19 现读：S1..S6 = 2/2/2/2/3/2，共 13）。
                {
                    var stages = TutorialData.Stages;
                    Check(stages.Length == 6, $"（前提）6 关数据在（实得 {stages.Length}）");
                    if (stages.Length == 6)
                    {
                        var counts = new int[6];
                        int total = 0, ai = 0, pc = 0, radio = 0, badKind = 0, badText = 0, playerActions = 0;
                        bool allVictoryTrue = true, allDefeatOff = true;
                        for (int i = 0; i < 6; i++)
                        {
                            var st = stages[i];
                            var ov = st != null ? st.onVictory : null;
                            var od = st != null ? st.onDefeat : null;
                            if (ov == null || !ov.scriptedTurn || ov.actions == null) { allVictoryTrue = false; continue; }
                            if (od == null || od.scriptedTurn) allDefeatOff = false;
                            counts[i] = ov.actions.Length; total += ov.actions.Length;
                            for (int k = 0; k < ov.actions.Length; k++)
                            {
                                var a = ov.actions[k];
                                if (a == null) { badKind++; continue; }
                                if (a.playerAction) playerActions++;
                                if (string.IsNullOrEmpty(a.arg)) badText++;
                                switch (a.Kind)
                                {
                                    case ScriptedActionType.AiChat: ai++; break;
                                    case ScriptedActionType.PlayerChat: pc++; break;
                                    case ScriptedActionType.RadioMessage: radio++; break;
                                    default: badKind++; break;
                                }
                            }
                        }
                        Check(allVictoryTrue && allDefeatOff,
                              "★ `A939` **前提成立**：6 关 `onVictory` 全在且 `scriptedTurn = true`；"
                            + "`onDefeat` 全在但 `scriptedTurn = false`（原版门 `IsPostBattleScriptAvailable.c` 的两半）"
                            + "｜🧨 DTO 把 `onVictory` 写成 `TutorialAction[]`（类型不符）⇒ `JsonUtility` 静默留 null ⇒ 本条红");
                        Check(total == 13 && string.Join(",", counts) == "2,2,2,2,3,2",
                              $"★ **13 条**、逐关 = {string.Join(",", counts)}（判据 = `tutorial_stages.json` 现读）");
                        Check(badKind == 0 && badText == 0 && playerActions == 0,
                              $"★ 13 条**逐条**都认得出（`AiChat {ai}` / `PlayerChat {pc}` / `RadioMessage {radio}`）"
                            + $" · 都带台词（缺 {badText}）· 都不是玩家动作（`playerAction=true` 有 {playerActions} 条）"
                            + " —— 所以它们**一条都不改局面**，只演聊天/电台");

                        // ---- 真驱动第 1 关（2 条：AiChat → RadioMessage）：**演的就是数据里那一句** ----
                        var s1 = TutorialData.ByIndex(0);
                        driver.BeginTutorial(0);
                        Check(driver.Ctx != null && driver.Ctx.Tutorial != null
                              && driver.Ctx.Tutorial.Stage == s1,
                              "（前提）第 1 关真开起来了（不是普通局冒充）");
                        driver.Ctx.Winner = driver.MySideForTest + 1;
                        Check(driver.PostBattleScriptAvailableForTest && driver.StartPostBattleScriptForTest()
                              && driver.PostBattleScriptCount == 2,
                              "★ **真数据**的门也开着（第 1 关 = 2 条）"
                            + "（判据 `IsPostBattleScriptAvailable.c`：`scriptedTurn` 真 + actions 非空）");
                        driver.TickPostBattleScriptForTest(0.01f);
                        Check(driver.PostBattleScriptExecuted == 1 && driver.UnitChat.ShownSide == 1
                              && driver.UnitChat.ShownText == s1.onVictory.actions[0].arg,
                              "★ 第 1 条 `AiChat` **真的交给执行器了**：第 2 颗气泡 + 台词 = 数据里的 `arg`"
                            + "｜🧨 把 `TickPostBattleScript` 里那句 `TutorialScript.ExecuteAction` 删掉"
                            + "（只推指针、不执行）⇒ 气泡不更新 ⇒ 本条红");
                        driver.TickPostBattleScriptForTest(5.6f);       // 上一条 `waitAfter = 5.5` + 下一条 `waitBefore = 0`
                        Check(driver.PostBattleScriptExecuted == 2 && driver.UnitChat.ShownSide == 2
                              && driver.UnitChat.ShownText == s1.onVictory.actions[1].arg,
                              "★ 第 2 条 `RadioMessage` 也真的演了（第 3 颗气泡 + 数据里那句话）");

                        // ---- 6 关**逐条消费**：每一关都推到底，合计必须 = 13 ----
                        int ran = 0;
                        for (int i = 0; i < 6; i++)
                        {
                            var st = TutorialData.ByIndex(i);
                            int expect = (st != null && st.onVictory != null && st.onVictory.actions != null)
                                       ? st.onVictory.actions.Length : -1;
                            driver.BeginTutorial(i);
                            if (driver.Ctx == null || driver.Ctx.Tutorial == null)
                            { Check(false, $"（前提）第 {i + 1} 关开不起来 —— 本关那一条**判不了**，如实红"); continue; }
                            driver.Ctx.Winner = driver.MySideForTest + 1;
                            bool started = driver.StartPostBattleScriptForTest();
                            for (int guard = 0; guard < 100 && !driver.PostBattleScriptDone; guard++)
                                driver.TickPostBattleScriptForTest(1f);      // 一拍一条；最大 `waitBefore+waitAfter` < 9s
                            Check(started && driver.PostBattleScriptDone
                                  && driver.PostBattleScriptExecuted == expect
                                  && driver.PostBattleScriptCount == expect,
                                  $"★ 第 {i + 1} 关：**{expect} 条逐条交给执行器**、全部消费完"
                                + $"（实得 {driver.PostBattleScriptExecuted}/{driver.PostBattleScriptCount}，"
                                + $"步进 {driver.PostBattleScriptStep}）");
                            ran += driver.PostBattleScriptExecuted;
                        }
                        Check(ran == 13, $"★ 6 关合计 **{ran} 条**全部被消费（判据 = 13）"
                            + "｜🧨 把 `TickPostBattleScript` 写成「只演第一条」⇒ 本条红");
                    }

                    // ---- 判别式：**认不出的动作类型** ⇒ `Unhandled` + 出声、指针照 ++、后面那条照跑 ----
                    //  判据 = B29 的口径（未识别不许静默吞掉；`A938` 之前 `default` 一律进 `Note`）。
                    var unk = new TutorialScript(new TutorialStageData
                    {
                        stage = 98, so = "<自检合成·A939 未知动作>", playerStarts = true,
                        onVictory = new TutorialTurn
                        {
                            turnName = "Victory", scriptedTurn = true, actionCount = 2,
                            actions = new[]
                            {
                                new TutorialAction { index = 0, type = "<未知>", waitBefore = 0f, waitAfter = 0f,
                                                     data = new[] { new TutorialActionData { type = 9999 } } },
                                new TutorialAction { index = 1, type = "AiChat", arg = "后面那条照跑",
                                                     waitBefore = 0f, waitAfter = 0f,
                                                     data = new[] { new TutorialActionData { type = 60 } } },
                            },
                        },
                    });
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261027, tutorial: unk);
                    driver.Ctx.Winner = driver.MySideForTest + 1;
                    // 「会出声」要**真抓日志**才算断（不许只看 `Unhandled` 字典 —— 那只是记账的一半）。
                    //  抓法照本仓现成范式（`Application.logMessageReceived`，同 `WaitBanner` 那一族）。
                    int unkWarns = 0; string unkLast = "";
                    Application.LogCallback hUnk = (cond, st, type) =>
                    {
                        if (type == LogType.Warning && cond != null && cond.Contains("认不出的动作类型"))
                        { unkWarns++; unkLast = cond; }
                    };
                    bool unkStarted = false;
                    Application.logMessageReceived += hUnk;
                    try
                    {
                        unkStarted = driver.StartPostBattleScriptForTest();
                        driver.TickPostBattleScriptForTest(0.01f);
                    }
                    finally { Application.logMessageReceived -= hUnk; }
                    Check(unkStarted, "（前提）合成关卡的战后脚本起来了");
                    Check(driver.PostBattleScriptStep == 1
                          && unk.Unhandled.ContainsKey((ScriptedActionType)9999),
                          "★ **认不出的动作类型** ⇒ 进 `Unhandled`，**指针照 ++**（不卡死）"
                        + "｜🧨 把 `ExecuteCore` 的 `default` 改回一律 `Note` ⇒ 本条红");
                    Check(unkWarns == 1,
                          $"★ 而且**真的出声了**：一条 `LogWarning`（实测 {unkWarns} 条"
                        + (unkLast.Length > 0 ? "，末条：" + unkLast : "") + "）"
                        + "｜🧨 删掉 `Unknown()` 里那句 `LogWarning` ⇒ 本条红（`Unhandled` 那条仍绿 ⇒ 两条分得开）");
                    driver.TickPostBattleScriptForTest(0.01f);
                    Check(driver.PostBattleScriptDone && driver.PostBattleScriptExecuted == 2
                          && driver.UnitChat.ShownText == "后面那条照跑",
                          "★ 后面那一条照常演（链没被未知动作卡住）");
                }

                // ---- ⑯-⑤ `A915`：掉线期间玩家禁操作（两道闸同源） ----
                {
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261026);
                    // 🔴 **2026-10-20（W58 · BTFIX3）**：`Begin()` 之后**先把开局的闸排空**再读 ——
                    //   `FrozenNow = _frozenForTest || (Frozen != null && Frozen())`（`CardInteraction.cs:200`），
                    //   而 `Frozen = () => PlayerInputFrozen || WaitingForBlockingAction`（`BattleDriver.cs:3726`）
                    //   ⇒ 换牌 / 开局那一段阻塞窗口还挂着时 `FrozenNow` 恒真（日志 87835/87887）。
                    //   本文件别的段落一律是 `SimulateMulliganDone → StepThrough → while(WaitingForBlockingAction) Step`。
                    if (driver.InMulligan) driver.SimulateMulliganDone();
                    StepThrough(driver);
                    { int g = 0; while (driver.WaitingForBlockingAction && g++ < 400) Step(1f / 30f); }
                    Check(!driver.PlayerInputFrozenForTest,
                          "★ 单机局（`_net == null`）⇒ **不冻结**"
                        + "（`NetClockPaused` 恒 false ⇒ 与加这一条之前逐字节等价）");
                    Check(!driver.interaction.FrozenNow,
                          "★ 而且手牌那一层也没被冻（同一个来源）");

                    driver.SetPlayerInputFrozenForTest(true);
                    Check(driver.PlayerInputFrozenForTest,
                          "★ 拨到「掉线」那一档 ⇒ `PlayerInputFrozen` 为真"
                        + "（原版 `BattleManager__Update.c:104-115`：`ConnectionStatus ∉ {0,3} ⇒ return`）");
                    Check(driver.interaction.FrozenNow,
                          "★ **手牌那一层也冻上了** —— 它**不走 `BattleDriver`**（自带 `Update`），"
                        + "所以另有一道；这一条钉的就是「那道接到没有」"
                        + "｜🧨 删掉 `Begin` 里那句 `interaction.Frozen = () => PlayerInputFrozen;` ⇒ 本条红");
                    // 判别式：**只掰手牌那一层自己的开关**（关掉）**冻不住** —— 说明它读的是驱动那一份，
                    // 不是自己那块 `_frozenForTest`（否则两条腿会各说各话）
                    driver.interaction.SetFrozenForTest(false);
                    Check(driver.interaction.FrozenNow,
                          "★ **判别式**：把手牌层自己的自检开关关掉 ⇒ 它**仍然冻着**"
                        + "（因为它读的是驱动那一份委托）⇒ 两处**同源**，不是各写一条判断");

                    driver.SetPlayerInputFrozenForTest(false);
                    Check(!driver.PlayerInputFrozenForTest && !driver.interaction.FrozenNow,
                          "★ **判别式（另一半）**：解开 ⇒ 两处**同时**恢复"
                        + "｜🧨 只把 `Update` 那句删掉、留着委托 ⇒ 这一条仍绿而上面那条红（分得开）");
                }

                // ------------------------------------------------------------
                //  ⑯-⑥ 🆕 2026-10-19（战斗线 `T11`）：7 条缺口的落地断言
                //     `G-1 actionOnPlayerResign` / `G-2 点空白跳过聊天` / `G-5 提示左右箭头`
                //     `G-6 preventSkipTip` / `G-7 ResetActionCounter（战后脚本那个入口）`
                //     ⚠️ `G-3` / `G-4` **没有断言** —— 它们要改 `RuleEngine/**`（本批冻结），见报告。
                // ------------------------------------------------------------
                {
                    // ---------- G-1：原版 `ClickExitBattle.c:50-74` 的「改演」那一半 ----------
                    // 真数据现核（`tutorial_stages.json`）：6 关 `preventPlayerResign` **全 0**、
                    // `actionOnPlayerResign` **全是空动作**（SO 里就是 `actionType` 空串、0 条 data）
                    // ⇒ 这一支在真数据上一次都走不到 ⇒ 用**合成关卡**钉机制。
                    TutorialAction MkResignChat()
                    {
                        return new TutorialAction
                        {
                            index = -1, type = "PlayerChat", arg = "我不会投降。", playerAction = false,
                            data = new[] { new TutorialActionData { type = (int)ScriptedActionType.PlayerChat } },
                        };
                    }
                    var resignStage = new TutorialScript(new TutorialStageData
                    {
                        stage = 91, so = "<自检合成·actionOnPlayerResign>", playerStarts = true,
                        preventPlayerResign = true, actionOnPlayerResign = MkResignChat(),
                    });
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261101, tutorial: resignStage);
                    Check(driver.Ctx != null && driver.Ctx.Winner == 0, "（前提）G-1 局面还没分胜负");
                    driver.Forfeit();
                    Check(driver.Ctx.Winner == 0 && !driver.Ctx.IsOver,
                          "★ **G-1**：`preventPlayerResign = true` ⇒ 投降被挡下、**不判负**（`Winner` 仍是 0）");
                    Check(driver.TutorialEventsContain("改演 `actionOnPlayerResign`"),
                          "★ **G-1**：而且**改演了 `actionOnPlayerResign`**（原版 `ClickExitBattle.c:71` → "
                        + "`AiScripted.ExecuteAction`）—— 我们的日志里有那一句"
                        + "｜🧨 只「挡下」不改演 ⇒ 本条红（原来那一支只喊一句「还没做」）");
                    Check(driver.UnitChat != null && driver.UnitChat.ShownSide == 0,
                          $"★ **G-1**：那个动作**真的演出去了**（合成关卡里是一条 `PlayerChat` ⇒ 第 1 颗气泡亮；"
                        + $"实得 `ShownSide = {(driver.UnitChat != null ? driver.UnitChat.ShownSide : -99)}`）"
                        + "｜🧨 只记日志不执行 ⇒ 本条红");

                    // 对照腿：同一个动作、`preventPlayerResign = false` ⇒ 投降照常判负、**不演**
                    var resignOff = new TutorialScript(new TutorialStageData
                    {
                        stage = 90, so = "<自检合成·对照>", playerStarts = true,
                        preventPlayerResign = false, actionOnPlayerResign = MkResignChat(),
                    });
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261102, tutorial: resignOff);
                    if (driver.UnitChat != null) driver.UnitChat.HideAll();     // 把上一条腿的气泡清干净
                    driver.Forfeit();
                    Check(driver.Ctx.Winner == 2 - driver.MySideForTest,
                          $"★ **判别式**：开关关着 ⇒ 投降照常判负（`Winner` = {driver.Ctx.Winner}）"
                        + "—— 与上一条合起来 ⇒ 「改演」只被 `preventPlayerResign` 驱动，不是恒有");
                    Check(!driver.TutorialEventsContain("改演 `actionOnPlayerResign`"),
                          "★ **判别式（灭自证）**：那一句日志**只在被挡下时才有**（正常投降那条链没有它）"
                        + "｜🧨 把 `PlayTutorialResignAction` 挪到无条件分支 ⇒ 本条红");

                    // ---------- G-2：`SkippableActionWait` + `skipNextAction` + `CloseChatBoxes` ----------
                    // 判据：`AiScripted._SkippableActionWait_d__15__MoveNext.c`（time=0 立刻收；
                    // `CanSkipAction` 假 ⇒ WaitForSeconds；真 ⇒ 逐帧看 `+0x29`）+ 协程 case 5（`skipNextAction`
                    // 一置位 ⇒ `CloseChatBoxes(currentAction)`，随后无条件清零）。
                    var chatStageData = new TutorialStageData
                    {
                        stage = 93, so = "<自检合成·点空白跳过聊天>", playerStarts = true,
                        turns = new[]
                        {
                            new TutorialTurn
                            {
                                turnName = "Turn1", scriptedTurn = true, actionCount = 1,
                                actions = new[]
                                {
                                    new TutorialAction
                                    {
                                        index = 0, type = "PlayerChat", arg = "这句话可以跳过。", playerAction = false,
                                        waitAfter = 2f,
                                        data = new[] { new TutorialActionData { type = (int)ScriptedActionType.PlayerChat } },
                                    },
                                },
                            },
                        },
                    };
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261103, tutorial: new TutorialScript(chatStageData));
                    driver.SyncTutorialTurnForTest();
                    var chatT = driver.Ctx.Tutorial;
                    Check(driver.Ctx.Active == driver.MySideForTest, "（前提）G-2 这一局是**玩家的回合**（窗口只在玩家回合起）");
                    var cStep = driver.DriveTutorialScriptForTest();
                    Check(cStep == BattleDriver.TutorialStep.Advanced && chatT.ActionCounter == 1
                          && driver.TutorialScriptWaitArmed && driver.TutorialScriptWaitLeft > 0f,
                          $"★ **G-2**：可跳过的聊天动作执行完 ⇒ 起 `SkippableActionWait` 窗口"
                        + $"（`waitAfter = 2s`，实得 {driver.TutorialScriptWaitLeft:F2}s）"
                        + "｜🧨 不接窗口 ⇒ `TutorialScriptWaitArmed` 恒 false ⇒ 本条红");
                    Check(driver.UnitChat != null && driver.UnitChat.ShownSide == 0,
                          $"（前提）聊天气泡亮着（`ShownSide = {(driver.UnitChat != null ? driver.UnitChat.ShownSide : -99)}`）");
                    // 判别式一：点在**单位上** ⇒ 不算跳过（原版要求「指针下什么都没有」）
                    // 🔴 **2026-10-20（W58 · BTFIX3）**：原来拿**敌方**督军视图当靶 —— 教程开局它被藏着
                    //   （`ApplyTutorialVisibility`；本文件 ⑤ 段就验过 `!fw.gameObject.activeSelf`），
                    //   而 `HitSlot` 走 `Physics2D.OverlapPoint`（`CardView.HitByCollider`）⇒ **停用对象的
                    //   collider 不在物理世界里** ⇒ 这一下被判成「空处」⇒ 跳过被收下（连带下一条红：窗口已收工）。
                    //   ⇒ 改拿**确定激活**的场上单位视图（优先我方督军；拿不到就取任意一张
                    //   **在激活层级里**的场上视图），并把 `activeInHierarchy` 当场钉成前提。
                    CardView g2Self = null;
                    var g2MineWarlord = driver.BoardViewAt(BoardSpec.WarlordSlot, true);
                    if (g2MineWarlord != null && g2MineWarlord.gameObject.activeInHierarchy) g2Self = g2MineWarlord;
                    for (int g2Pass = 0; g2Pass < 2 && g2Self == null; g2Pass++)
                    {
                        var g2Dict = g2Pass == 0 ? driver.MyUnits : driver.FoeUnits;
                        foreach (var kv in g2Dict)
                            if (kv.Value != null && kv.Value.gameObject.activeInHierarchy) { g2Self = kv.Value; break; }
                    }
                    Check(g2Self != null && g2Self.gameObject.activeInHierarchy,
                          "（前提）场上有一张**在激活层级里**的单位视图（拿它的位置当「点到东西」）"
                        + $"（我方督军 view={(g2MineWarlord != null)} · 选中={(g2Self != null ? g2Self.name : "<无>")}）"
                        + " —— 停用的 collider 不参与 `Physics2D` 查询 ⇒ 会被误判成「空处」");
                    if (g2Self != null)
                        // 🔴 **2026-10-21（`新账-64`）**：喂进去的必须是 `WorldPointer()` 那个**正交指针平面**的点；
                        //   `g2Self.transform.position` 是**战场世界坐标**（真 3D 战场上两者差 1.49–1.56 单位）⇒
                        //   先过 `PointerAtWorldForTest`（= 「点在这张卡画出来的屏幕位置」）。
                        Check(!driver.RequestTutorialSkipForTest(driver.PointerAtWorldForTest(g2Self.transform.position))
                              && driver.TutorialScriptWaitArmed,
                              "★ **G-2 判别式**：点在**单位上** ⇒ **不算跳过**（窗口仍开着）"
                            + "（原版 `DetectClickToSkip.c` 要求 `Physics.RaycastNonAlloc == 0`；"
                            + "我们的等价物 = `TutorialClickHitsSomething`）");
                    // 判别式二：点在空处 ⇒ 置 `skipNextAction` ⇒ 窗口当场收工 + 关气泡
                    //   ⚠️ 这个空点取 `(-6.0, +4.4)`：4:3（批处理 640×480）下仍在屏内（`VisibleWidth = 13.33`）、
                    //      且避开棋盘/手牌/那三颗钮的命中框。
                    Check(driver.RequestTutorialSkipForTest(new Vector3(-6.0f, 4.4f, 0f)),
                          "★ **G-2**：点在**空处** ⇒ `skipNextAction` 置起来（返回 true）"
                        + "｜🧨 把 `RequestTutorialSkip` 里那句 `_tutSkipNext = true` 删掉 ⇒ 本条红");
                    Check(!driver.TutorialScriptWaitArmed && driver.UnitChat != null && driver.UnitChat.ShownSide == -1,
                          "★ **G-2**：跳过 ⇒ 窗口**当场收工** + 聊天气泡**关掉**"
                        + "（原版 `skipNextAction` → `CloseChatBoxes`）"
                        + "｜🧨 只收窗口不关气泡 ⇒ 本条红");
                    // 第二腿：**不点** ⇒ 窗口走满 `waitAfter` 收工，但气泡**不会**被关（原版只有跳过才关）
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261104, tutorial: new TutorialScript(chatStageData));
                    driver.SyncTutorialTurnForTest();
                    driver.DriveTutorialScriptForTest();
                    Check(driver.TutorialScriptWaitArmed, "（前提）第二腿窗口也在");
                    driver.TickTutorialViewForTest(2.1f);
                    Check(!driver.TutorialScriptWaitArmed,
                          "★ **G-2（另一条腿）**：不点、把时间喂过 `waitAfter` ⇒ 窗口**照样收工**"
                        + "（原版 `SkippableActionWait` 的 `WaitForSeconds` 那半）");
                    Check(driver.UnitChat != null && driver.UnitChat.ShownSide == 0,
                          "★ **判别式**：但**气泡还在**（原版只有 `skipNextAction` 置过才 `CloseChatBoxes`；"
                        + "自然等满不关）—— 两腿一开一关 ⇒ 上面那条不是「恒关」");

                    // ---------- G-5：小提示的左右箭头（原版 `TutorialTipScript.SetupArrows`）----------
                    TutorialAction MkTip(bool left, bool right)
                    {
                        return new TutorialAction
                        {
                            index = 0, type = "SmallTip", arg = "看这里", playerAction = false,
                            smallTipParams = new TutorialSmallTip
                            {
                                positionReference = 0, positionRelation = 0, tipDuration = 5f, waitForTip = false,
                                showLeftArrow = left, showRightArrow = right,
                            },
                            data = new[] { new TutorialActionData { type = (int)ScriptedActionType.SmallTip } },
                        };
                    }
                    var arrowStageData = new TutorialStageData
                    {
                        stage = 88, so = "<自检合成·提示箭头>", playerStarts = true,
                        turns = new[]
                        {
                            new TutorialTurn
                            {
                                turnName = "Turn1", scriptedTurn = true, actionCount = 2,
                                actions = new[] { MkTip(true, false), MkTip(false, false) },
                            },
                        },
                    };
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261105, tutorial: new TutorialScript(arrowStageData));
                    driver.SyncTutorialTurnForTest();
                    var arrowOv = driver.TutorialView;
                    Check(arrowOv != null && !arrowOv.ArrowLeftVisible && !arrowOv.ArrowRightVisible,
