                                },
                            },
                        },
                    };
                    driver.Begin(myFaction: BattleDriver.DefaultFactionA, foeFaction: BattleDriver.DefaultFactionB,
                                 seed: 20261108, tutorial: new TutorialScript(g7StageData));
                    driver.SyncTutorialTurnForTest();
                    driver.DriveTutorialScriptForTest();
                    Check(driver.Ctx.Tutorial.ActionCounter == 1,
                          $"（前提）G-7：指针先推到 1（实得 {driver.Ctx.Tutorial.ActionCounter}）");
                    driver.Ctx.Winner = driver.MySideForTest + 1;          // 我方赢 ⇒ 走 `onVictory`
                    Check(driver.PostBattleScriptAvailableForTest, "（前提）战后脚本的门开着");
                    Check(driver.StartPostBattleScriptForTest(), "（前提）战后脚本起来了");
                    Check(driver.Ctx.Tutorial.ActionCounter == 0,
                          $"★ **G-7**：起战后脚本时**做了 `ResetActionCounter()`**（原版第三个实参 "
                        + "`resetActionCounter: 1`；指针应回到 0，实得 " + driver.Ctx.Tutorial.ActionCounter + "）"
                        + "｜🧨 删掉 `StartPostBattleScript` 里那一句 ⇒ 本条红（指针停在 1）"
                        + "。⚠️ 原版同一条链上还有一句 `UpdateTurn(turnCounter)` —— 我们的回合号在结算是**不 ++ 的**"
                        + "（`Ctx.Turn` 只在 `RuleCore.BeginTurn` 里涨）⇒ 那一半**做不到**，如实记（报告 §没查清）");
                }

                // ---- 🧨 G3 回归（2026-10-21 · 第六十一会话）：教程局藏起来的敌方战将视图**不许跨局复用** ----
                //  病灶与修法 → `BattleDriver.Begin` 里 `ReviveBoardViews` 那一段注释。
                //  判据链（缺任一步这条就没有鉴别力）：
                //   ① `BeginTutorial` 之后敌督军视图**确实被藏了**（前提 —— 不然下面那条恒绿）；
                //   ② 紧接着开一局**普通局**（`tutorial: null`，= 真机「打完教程回主菜单再来一局」的形状）；
                //   ③ 那张视图**还是同一张**（`_myUnits/_foeUnits` 跨局复用那条路；不是重建的）；
                //   ④ 它回到**激活层级**里；
                //   ⑤ 而且 `CardHit` 真能点到它（真机那条「敌督军点不动」的行为那一半）。
                {
                    driver.BeginTutorial(0);
                    var g3Foe = driver.BoardViewAt(BoardSpec.WarlordSlot, false);
                    Check(g3Foe != null && !g3Foe.gameObject.activeSelf,
                          "🧨 G3 回归（前提）：教程局一开，敌方战将的视图**先藏起来**"
                        + "（原版两拍的第一拍，判据 = `BattleDriver.BeginTutorial` 的 `foeW.SetActive(false)`）");
                    driver.Begin(BattleDriver.DefaultFactionA, BattleDriver.DefaultFactionB, 20261021);
                    var g3Foe2 = driver.BoardViewAt(BoardSpec.WarlordSlot, false);
                    Check(g3Foe2 != null && g3Foe2 == g3Foe,
                          "🧨 G3 回归（前提）：新一局**复用的还是同一张**敌方战将视图"
                        + "（`_myUnits/_foeUnits` 跨局复用 —— 这条不成立 ⇒ 下面验的不是那条复用路径）");
                    Check(g3Foe2 != null && g3Foe2.gameObject.activeInHierarchy,
                          "🧨 G3 回归：**教程局 → 普通局**之后，敌方战将的视图必须**回到激活态**"
                        + $"（实得 activeSelf={((g3Foe2 != null) ? g3Foe2.gameObject.activeSelf.ToString() : "<无视图>")}"
                        + $" / inHierarchy={((g3Foe2 != null) ? g3Foe2.gameObject.activeInHierarchy.ToString() : "<无视图>")}）"
                        + "｜🧨 **修复前此条必红** —— `Begin` 只清身份表、不复位激活态 ⇒ `SyncBoard` 认领这张 "
                        + "inactive 视图 ⇒ 不画、`CardHit` 对 `!activeInHierarchy` 恒 false（真机 = 敌督军点不动）");
                    if (g3Foe2 != null && g3Foe2.gameObject.activeInHierarchy)
                    {
                        int g3Hit = driver.HitSlotForTest(1 - driver.MySideForTest,
                                                          driver.PointerAtWorldForTest(g3Foe2.transform.position));
                        Check(g3Hit == BoardSpec.WarlordSlot,
                              $"🧨 G3 回归（行为那一半）：点**敌方战将画出来的位置**必须命中槽 {BoardSpec.WarlordSlot}"
                            + $"（实得 {g3Hit}）—— 只把节点点亮、命中那条没恢复 ⇒ 本条红");
                    }
                }

                // 收尾：把 driver 留在**一个正常的教程局**上
                driver.BeginTutorial(0);
            }
        }

            // ================================================================
            //  🆕 2026-10-18（A964 · 战斗侧）：「命中区覆盖 / 藏起来还响应」普查探针
            // ------------------------------------------------------------------
            //  判据（一句话）→ `资料/待办判据_1018.md` §A964：
            //    🔴 **凡参与点击命中的节点，它的【命中区矩形】必须覆盖它【画出来的矩形】。**
            //  侦察（必读）→ `资料/普查产出_1018第三会话/RECON_A964前置.md` +
            //    `资料/普查产出_1018/P-HIT_命中区探针侦察.md`。
            //
            //  🔴 **落点就地订正（写手现读，铁律 5）**：侦察 §4·0 把本段定在「A463 段收口之后、
            //     收尾 `Auto Zoom` 之前」—— **那里 `driver` 已经被 `DestroyImmediate` 卸掉了**
            //     （销毁就是紧下面那一句；同段还有一条 `Check(driver == null …)` 作证）。
            //     ⇒ 本段**只能**落在那一句**之前**（= 整轮里 `driver` 还活着的最后一处）。
            //     ⛔ 这不是「随便换个地方」：本段要调的就是 `driver` 上那套输入闸 / HUD 钮。
            //
            //  ⛔ 本段**不写 `资料/`**（那是正本区）、**不建任何常驻对象**（没有夹具要销毁）。
            //     产物只落 `d:/4/_tmp_view/hitprobe/`。
            //  ⛔ **缺陷判定一律走「报告式」**（§A964 续 ② 的裁定）：纯几何「谁盖住谁」会假红
            //     （装饰件会叠在**同一个矩形**上）⇒ 只有「生产函数自己就必须成立」的那几条才 `Check`。
            //  ⛔ 命中**一律调生产函数**（⛔ 探针不重算一份算式 —— 那是「实现与检测器一起改回去还全绿」的自证）。
            // ================================================================
            {
                var drv964 = driver;
                var hits964 = new List<string>();
                hits964.Add("kind\ttarget\t判据/命中函数\t读数\t结论\t备注");
                bool chatDependsOnCooldown964 = false;      // chat 的「副作用」那一格如实降级（见下）

                // ---- 夹具：**换一局干净的非教程局** ----
                // 🔴 为什么必须换：本段上面几步里最后一句是 `driver.BeginTutorial(0)`，而教程局
                //    `BattleDriver.ApplyTutorialHudVisibility` **无条件藏掉墓园钮**、并按 `hideChat`
                //    藏掉聊天钮（判据 = 原版 `BattleManager__TutorialSetup.c:52-60`）⇒ 不换局的话
                //    E4 的「亮着 ⇒ 必须响应」那半会**全假红**。种子与 A462 段同一个（20260915）。
                drv964.Begin("Ultramarines", "Goff", 20260915);
                if (drv964.InMulligan) drv964.SimulateMulliganDone();

                // ================================================================
                // 🔴 2026-10-16（修波 `FA` · 补 `R1` §②-7 点名的**零覆盖**缺口）：**子画布之间的兄弟序**。
                //   `HudCanvas.ApplySubCanvasRank()` 是「同层同 `sortingOrder` 的那几块子画布谁压谁」的
                //   **唯一实现**，而它按**名字**找（`RootRect.Find(name)`）—— 名字写坏 ⇒ **静默不排**
                //   （不报错、不警告，`HudCanvas.cs` 表尾那段自查注释写的就是这个）⇒ 这一格此前
                //   **没有任何机械证明**（`R1` §项 1 末 + §②-7）。放在这里是因为：① 上面那句 `Begin`
                //   刚跑过 `BuildHud()`（五扇面板的子画布都在里面建）⇒ 排次刚被重排过一次；
                //   ② 本段**不带面板可见性那种闸**（换个位置就成了「面板不开 ⇒ 这组断言静默消失」）。
                //   🔑 **读的是场景里真实的** `GetSiblingIndex()` —— ⛔ 不是把那张字符串数组按顺序念一遍
                //     （那是「数组按顺序写着」的同义反复，`R1` §②-7 要的「灭自证」就在这一点上）。
                //   🔑 判据（期望值来源）= **原版 `Safe area FrontCanvas` 的 `m_Children` 下标** ——
                //     `bundle_scenes_scenes_battlearena2/RectTransform/RectTransform_3055.json` 的 `m_Children`
                //     （**本波自己现读**：14 个 pathID 逐格解成 GO 名），全序为
                //       [0] Drag Attack Selector · [1] ActiveSkillDesc · [2] Unit Chat · [3] Mulligan ·
                //       [4] Generic Multi Card Display Combat · [5] ChooseCardMenu · [6] Card Display Window ·
                //       [7] DebugButtons · [8] AboveShader · [9] PopupAnchor · [10] BattleSettingsPanel ·
                //       [11] Tutorial · [12] LoadingMenu · [13] Alliance Panel
                //     ⛔ **不抄 `HudCanvas.SubCanvasRank`**（那是被测实现那一侧，抄它 = 拿实现证明实现）。
                //     · `ChatPopup` **不在那 14 格里**：它是 `Unit Chat` 的**子件**（原版 `RT_3280.m_Children`
                //       的 4/7）⇒ 复刻口径 = 「子件画在父件之上」⇒ 排在 `Unit Chat` **之后**、`Mulligan`(3) **之前**。
                //   🧨 两条改坏法（都会红，不是「理论上」）：
                //     ① 删掉 `ApplySubCanvasRank()` 里那句 `t.SetSiblingIndex(idx)` ⇒ 兄弟序退回**建序**
                //        （= `BuildHud` 的调用序：技能面板 → 单聊 → 选择器 → 联盟 → 聊天弹窗）
                //        ⇒ 第 1 对 `Drag Attack Selector Canvas` vs `ActiveSkillDesc Canvas` 当场反了；
                //     ② 把 `SubCanvasRank` 里任一项的名字写错一个字符 ⇒ 那一项拿不到最小位次 ⇒ 它前后那一对红。
                //   ⚠️ **只断「已建出来的那些」之间的相对次序**（原版那 14 格今天只迁了一部分；缺席的格子
                //     既不断它自己的位次、也不当红的理由 —— 逐格比会拿「还没迁」当缺陷 = **假红**）。
                // ================================================================
                {
                    var hudRtA2 = HudCanvas.RootRect;
                    Check(hudRtA2 != null,
                          "★ T09b/次序：（前提）HUD 根画布在（`HudCanvas.Ensure` 跑过 ⇒ 子画布有地方挂）");
                    if (hudRtA2 != null)
                    {
                        // 按**原版子件序**升序列好（数组顺序本身就是期望值；判据见上，⛔ 不是抄 `SubCanvasRank`）
                        // ⚠️ 名字一律取**面板自己的公开常量**（⛔ 别在这里再写一遍字面量 —— 那正是「同一条规则
                        //    两处拼写」）；`AttackSelector` / `MultiCardDisplay` 那几个还没开常量 ⇒ 现写字面量
                        //    （📌 接线清单：`AttackSelector.SubCanvasName` 见 `G1-1`）。
                        var cvRankA2 = new string[]
                        {
                            "Drag Attack Selector Canvas",                    // 原版 0/14
                            SkillPanel.SubCanvasName,                         // 原版 1/14
                            UnitChatPanel.SubCanvasName,                      // 原版 2/14
                            ChatPopupPanel.SubCanvasName,                     // `Unit Chat` 的子件（原版 4/7）⇒ 紧跟其父之后
                            "Mulligan Canvas",                                // 原版 3/14
                            "Generic Multi Card Display Combat Canvas",       // 原版 4/14
                            "ChooseCardMenu Canvas",                          // 原版 5/14
                            "Card Display Window Canvas",                     // 原版 6/14
                            "AboveShader Canvas",                             // 原版 8/14
                            AlliancePanelWindow.SubCanvasName,                // 原版 13/14（**这一组里最后一名**）
                        };
                        // 真实位次：根画布下的**直接子件**（子画布都这么挂 —— `EnsureSubCanvas` 的
                        //   `SetParent(RootRect)`），取「带 `Canvas` 组件」的那些 = 子画布本尊
                        var siA2 = new Dictionary<string, int>();
                        for (int iA2 = 0; iA2 < hudRtA2.childCount; iA2++)
                        {
                            var kidA2 = hudRtA2.GetChild(iA2);
                            if (kidA2.GetComponent<Canvas>() != null) siA2[kidA2.name] = iA2;
                        }
                        var seenA2 = new System.Text.StringBuilder();
                        int nRankA2 = 0, badA2 = 0, offTableA2 = 0, prevSiA2 = int.MinValue;
                        foreach (var nmA2 in cvRankA2)                       // 已按原版子件序升序
                        {
                            if (!siA2.TryGetValue(nmA2, out int siCurA2)) continue;
                            nRankA2++;
                            // 名字与 `SubCanvasRank` 里那条对不上 ⇒ 它**永远不参与排次**（静默失效）
                            if (!HudCanvas.IsRanked(nmA2)) offTableA2++;
                            if (siCurA2 <= prevSiA2) badA2++;
                            if (seenA2.Length > 0) seenA2.Append(" < ");
                            seenA2.Append(nmA2).Append('#').Append(siCurA2);
                            prevSiA2 = siCurA2;
                        }
                        Check(nRankA2 >= 5,
                              $"★ T09b/次序：（前提）本批迁的 5 块子画布都在根画布下（实得 {nRankA2} 块）"
                            + $"：{seenA2}｜🧨 少一块 = 那扇面板没登记宿主（`BattleDriver.BuildHud` 那几句 `UseHost`）");
                        Check(offTableA2 == 0,
                              "★ T09b/次序（**灭自证·名字**）：上面那几块的名字**都在** `HudCanvas.SubCanvasRank` 表里"
                            + "（⛔ 对不上的项 `RootRect.Find` 永远 `null`、**静默不排次序** —— 表自己写着这是它"
                            + $"最容易坏的方式；实得**不在表里**的 {offTableA2} 块）");
                        Check(nRankA2 >= 2 && badA2 == 0,
                              "★ T09b 次序：子画布按**原版 `Safe area FrontCanvas` 的 14 子件序**排"
                            + "（读的是**真实的** `GetSiblingIndex()`，⛔ 不是那张字符串数组）"
                            + "\n        实得（兄弟序升序）：" + seenA2
                            + $"\n        反序/并列 {badA2} 处"
                            + "｜🧨 删掉 `ApplySubCanvasRank` 那句 `SetSiblingIndex` ⇒ 退回建序 ⇒ 红"
                            + "；表里任一项的名字写错一个字符 ⇒ 它前后那一对红");
                    }
                }

                // 收尾要放回去的三样（指针钉子 / 进攻卡选择 —— 本段都写过）
                bool?   heldWas964  = BattleDriver.PointerHeldForTest;
                Vector3? worldWas964 = BattleDriver.PointerWorldForTest;
                int    offSlotWas964   = drv964.Ctx != null ? drv964.Ctx.OffensiveSlotIdx : -1;
                string offSoWas964     = drv964.Ctx != null ? drv964.Ctx.OffensiveEnvSO : null;
                bool   offChosenWas964 = drv964.Ctx != null && drv964.Ctx.OffensiveChosen;

                // ---- 三个小工具（全部只**转发**生产函数；⛔ 不另写一份命中判定）----

                // 五颗钮各自的路由（= `Update` 里那几条链）。⛔ 别自己算「点没点到」。
                // 🔴 **2026-10-19（`T09` A1）：进攻卡钮改走 uGUI** —— 这里走 `BattleHudButton` 的点击动作，
                //   与 `EventSystem` 派发的是同一个回调。
                // 🔴 **2026-10-19（`T09` A2）：其余四颗（settings / chat / cemetery / cameraReset）也改走 uGUI** ——
                //   手搓 handler 只剩「面板/气泡/日志面板开着」那条**模态支**（A3 才迁面板自己的钮）。
                bool Route964(string which)
                {
                    bool modal = false;
                    switch (which)
                    {
                        case "settings":    modal = drv964.TickSettingsInputForTest(); break;
                        case "chat":        modal = drv964.TickChatInputForTest(); break;
                        case "cemetery":    modal = drv964.TickLogInputForTest(); break;
                        case "cameraReset": modal = drv964.TickHudButtonsForTest(); break;
                        case "alliance":    modal = drv964.TickAllianceInputForTest(); break;
                        default:            break;                      // offensive / endTurn：没有模态支
                    }
                    // uGUI 那一跳（`IPointerClickHandler` 的等价物）—— 关着的钮由它自己的
                    // `activeInHierarchy` 闸挡掉（原版 uGUI 关着收不到射线）。
                    return drv964.ClickHudButtonForTest(which) || modal;
                }

                // 喂一整个「按下 → 松手」，返回**松手那一帧**的结果。
                // 🔴 **2026-10-19（`T09` A1/A2）**：这五颗都已走 uGUI，**只在松手那一帧派发**
                //   （`IPointerClickHandler` = 抬起；按下那一帧不该做事）⇒ 按下帧不再调 `Route964`。
                bool Click964(string which)
                {
                    BattleDriver.PointerWorldForTest = drv964.HudButtonWorldPosForTest(which);
                    BattleDriver.PointerHeldForTest = true;
                    drv964.PollInputEdgesForTest();          // 第 1 帧：按下沿
                    BattleDriver.PointerHeldForTest = false;
                    drv964.PollInputEdgesForTest();          // 第 2 帧：松手沿
                    return Route964(which);
                }

                // 这一颗被点之后**看得见的副作用**（比「返回 true」硬一档）。
                bool Side964(string which)
                {
                    switch (which)
                    {
                        case "settings":  return drv964.Settings != null && drv964.Settings.Visible;
                        case "chat":      return drv964.ChatPopup != null && drv964.ChatPopup.Visible;
                        case "cemetery":  return drv964.BattleLog != null && drv964.BattleLog.Visible;
                        case "offensive": return drv964.CardDisplay != null && drv964.CardDisplay.Visible;
                        default:          return false;      // cameraReset 看「取景重算计数」，另算
                    }
                }

                void CloseAll964()
                {
                    if (drv964.Settings   != null && drv964.Settings.Visible)   drv964.Settings.Hide();
                    // 🔴 **2026-10-20（W58 · BTFIX4）**：`Hide()` 是**淡出**（0.5 s），批处理没有帧循环 ⇒
                    //   淡出永远走不完 ⇒ `CloseChatPopup` 那块全屏关闭区**隐形但仍然是射线靶**
                    //   （`ChatPopupPanel.Hide` 的 doc：照原版**不撤射线靶**，`HideImmediate` 才是批处理那一档）。
                    //   实测代价（`battle5.log` 97977/98190/98403/98615）：A964 之后 A985 的「空白点首中 = 压暗层」
                    //   和 A2 后四颗钮的「边内 1 px 必中」全部**首中 = `CloseChatPopup`**。
                    //   ⇒ 夹具收尾一律走 `HideImmediate`（⛔ 不改生产 `Hide`：那是原版手感判据）。
                    //   ⚠️ 不按 `Visible` 判——淡出中 `_open` 已经是 false，但对象还开着、还在吃射线。
                    if (drv964.ChatPopup  != null)                              drv964.ChatPopup.HideImmediate();
                    if (drv964.BattleLog  != null && drv964.BattleLog.Visible)  drv964.BattleLog.Hide();
                    if (drv964.CardDisplay != null && drv964.CardDisplay.Visible) drv964.CardDisplay.Hide();
                    // 🔴 **2026-10-20（W57 · 战斗线 `T09` 步骤 WIRE · 来源 A3-e3 §三·2-A）：收掉 `ChoosePanel`。**
                    //   解的是 A2 报告 §三·5 的「`ChoosePanel` 收不掉」—— A3-e3 已给它补了公开 `Hide()`
                    //   （= 基类 `Close()` 的别名）。⛔ 别改用 `Close()` 让两处各写一份口径。
                    if (drv964.Choose     != null && drv964.Choose.Visible)     drv964.Choose.Hide();
                    // 🔴 **2026-10-19（`T09` A2）**：uGUI 点击外面那道模态闸（`HudClickBlocked`）看的就是
                    //   `HudButtonsBlocked`（含多卡窗 / 联盟窗）⇒ 这里也要收，否则 E4 的「亮着必须响应」会假红。
                    if (drv964.MultiCards != null && drv964.MultiCardsVisibleForTest) drv964.MultiCards.Hide();
                    if (drv964.AlliancePanelRef != null && drv964.AlliancePanelRef.Visible) drv964.AlliancePanelRef.Close();
                    if (drv964.Mulligan != null && drv964.Mulligan.Visible) drv964.Mulligan.Close();
                }

                /// <summary>本局 `Ctx.ActionLog` 里有没有**非 `Draw`** 的记录 ——
                /// `RefreshBattleLog` 只给这一类产出行（`case EvtKind.Draw:` ⇒ `skipRow = true`）。
                /// `BT-4` 那一步靠它驱动回合，见那里的注释。</summary>
                bool HasNonDrawEvt964(BattleContext c964)
                {
                    if (c964 == null) return false;
                    foreach (var e964 in c964.ActionLog) if (e964.Kind != EvtKind.Draw) return true;
                    return false;
                }

                // ================================================================
                //  一、`E4` —— **藏起来还响应** · 5 档 × 两态（战斗侧独有；外壳侧是 `E1`，两者别合并）
                // ================================================================
                //  🔴 三条前提（不写清就会假红/假绿）：
                //   ① `_settingsPanel.Visible` / `_chatPopup.Visible` / `_logPanel.Visible` **必须先为假** ——
                //      这三处 handler 的**第一句**就是「面板开着 ⇒ 无条件接管并 return true」，
                //      面板开着的话「藏起来的钮」根本走不到它自己那条判据（会把「被短路」看成「命中」）。
                //   ② `offensive` 那一格：`HandleOffensiveButton` 最后一跳是 `OpenOffensiveCardWindow()`，
                //      而它要先 `ChosenOffensiveCard()` 查得到卡 —— 没选卡时**亮着也返回 false**。
                //      ⇒ 本段先给它选一张真卡（`RuleCore.ChooseOffensiveCard` 只写 `ctx` 三个字段、不换环境）。
                //   ③ `cameraReset` 那一格：`SetHudButtonActiveForTest` **只 `SetActive`、不起 tween**
                //      ⇒ 不会有 `DOPunchScale` 把 `localScale` 改掉（那会让命中区跟着缩）。
                Debug.Log(P + "--- A964（E4）：藏起来的钮不许响应 · 5 档 × 两态 ---");
                string hiddenResp964 = "";
                string[] btns964 = { "settings", "chat", "cemetery", "offensive", "cameraReset" };
                for (int bi964 = 0; bi964 < btns964.Length; bi964++)
                {
                    string which = btns964[bi964];
                    var w964 = drv964.HudButtonWorldPosForTest(which);
                    Check(w964 != Vector3.zero,
                          $"★ A964/E4：（前提）`HudButtonWorldPosForTest(\"{which}\")` 取得到坐标"
                        + " —— 键表（`HudButtonPieceForTest`，**唯一一份 switch**）与 `SetHudButtonActiveForTest`"
                        + "**同一张表**，少加一处 = 静默半条（取不到就返回 `Vector3.zero`，下面是空跑）");
                    if (which == "offensive" && drv964.Ctx != null)
                    {
                        var ch964 = CardPresentation.OffensiveCards.Choices("Ultramarines");
                        if (ch964.Count > 1)
                            RuleCore.ChooseOffensiveCard(drv964.Ctx, 0, ch964[1].idx, ch964[1].envSO);
                    }

                    // ---- 态 A：**藏起来** ----
                    drv964.SetHudButtonActiveForTest(which, false);
                    CloseAll964();
                    int frameWas964 = drv964.AutoZoom != null ? drv964.AutoZoom.FramingApplyCount : 0;
                    bool hidTick964 = Click964(which);
                    bool hidSide964 = Side964(which)
                                   || (which == "cameraReset" && drv964.AutoZoom != null
                                       && drv964.AutoZoom.FramingApplyCount != frameWas964);

                    // ---- 态 B：**亮着** ----
                    drv964.SetHudButtonActiveForTest(which, true);
                    CloseAll964();
                    int frameWas964b = drv964.AutoZoom != null ? drv964.AutoZoom.FramingApplyCount : 0;
                    bool visTick964 = Click964(which);
                    bool visSide964 = Side964(which)
                                   || (which == "cameraReset" && drv964.AutoZoom != null
                                       && drv964.AutoZoom.FramingApplyCount != frameWas964b);

                    if (hidTick964 || hidSide964)
                        hiddenResp964 += (hiddenResp964.Length > 0 ? "," : "") + which;

                    hits964.Add($"E4\t{which}\tTick*ForTest / 副作用\t亮:{visTick964}/{visSide964} · 藏:{hidTick964}/{hidSide964}"
                              + $"\t{(hidTick964 || hidSide964 ? "藏起来仍响应" : "藏起来不响应")}\tcooldown={drv964.ChatCooldownLeft:F2}");

                    // 🔴 **2026-10-19（`T09` A2）：那条「`_settingsBtn` 藏起来照样接管」的白名单【已核销】。**
                    //   原因：那颗钮现在走 uGUI（`BattleHudButton` 的 `IPointerClickHandler`），
                    //   而 `ClickHudButtonForTest` 自带 `activeInHierarchy` 闸 ⇒ 关着 = 收不到点击
                    //   （原版 `SetActive(false)` 的节点收不到射线，同一条）。⇒ 五颗一视同仁。
                    Check(!hidTick964 && !hidSide964,
                          $"★ A964/E4：`{which}` **藏起来之后不许响应**"
                        + $"（喂它自己的中心：接管={hidTick964} · 有副作用={hidSide964}）"
                        + " —— 原版那颗是 uGUI 钮，`SetActive(false)` 之后**收不到点击**；"
                        + "2026-10-19（`T09` A2）起五颗**全部**是 uGUI ⇒ 关着的钮由 `ClickHudButtonForTest` 的"
                        + " `activeInHierarchy` 闸挡掉（`offensive` 自 A1 起同一条）"
                        + "｜🧨 改坏法：把 `ClickHudButtonForTest` 的 `activeInHierarchy` 闸删掉 ⇒ 本条红"
                        + "（🔴 **这就是本探针的【已知阳性判别式】= `E12`** —— 扫完 0 条是否可信就看它）");

                    // 🔴 **灭自证（两态的另一半）**：一个「恒返回 false」的病实现会让上面全绿。
                    //    ⚠️ `chat` 那一格**只看接管、不看副作用**：`HandleChatPopup` 打开气泡前有一道
                    //    **4 秒冷却**（`_chatCooldown`，原版 `CHAT_INTERACTABLE_COOLDOWN`），而冷却
                    //    **是生产状态**（上一段 A462 说过一句台词就置上去了）⇒ 拿「气泡有没有开」当
                    //    「有没有响应」会**假红**。冷却那一格照样 `return true`，接管才是判据。
                    bool visMust964 = visTick964
                                   && (which == "chat" ? true : visSide964);
                    if (which == "chat" && visTick964 && !visSide964) chatDependsOnCooldown964 = true;
                    Check(visMust964,
                          $"★ A964/E4（**灭自证**）：`{which}` **亮着 ⇒ 必须接管"
                        + (which == "chat" ? "" : " + 必须有副作用") + "**"
                        + $"（接管={visTick964} · 副作用={visSide964}"
                        + (which == "chat" ? $" · 聊天冷却还剩 {drv964.ChatCooldownLeft:F2}s（>0 时气泡本来就不开）" : "")
                        + "）—— 与上一条配对：「恒返回 false」的病实现会让上一条绿、本条红");
                }

                // 🔴 **白名单台账**（2026-10-19 `T09` A2 起**空了** —— 五颗全是 uGUI，藏起来都不响应）。
                //    · 多一颗 ⇒ **新漏网**（真缺陷）；
                //    · 以后再有人退回手搓命中 ⇒ 在这里冒出来。
                Check(hiddenResp964 == "",
                      $"★ A964/E4（**白名单台账**）：「藏起来还会响应」的钮**一颗都不许有**"
                    + $"（实得「{hiddenResp964}」）—— 多一颗 = 新漏网"
                    + "；2026-10-19（`T09` A2）之前唯一那条白名单（`settings`，`ImageQuad.Contains` 不看 `activeSelf`）"
                    + "已随那颗钮迁 uGUI 而核销");

                // ================================================================
                //  二、`E2` —— **命中区 ⊇ 实绘矩形**（**报告式**；§A964 续 ② 裁定）
                // ================================================================
                //  ⛔ 这里只断**生产函数自己就必须成立**的两条：
                //     (a) **视觉中心 / 实绘内侧那一点必中**（命中区没覆盖实绘 ⇒ 红）
                //     (b) **明显在实绘之外那一点必不中**（命中区无界 / 恒 true ⇒ 红）
                //     其余（谁压谁、装饰件叠同一矩形…）一律进 TSV，交调度台逐条判。
                //  🔴 **本段第一次跑时「0 条违」是可信的**，因为 E4 那两条已知阳性判别式已经先跑过。
                Debug.Log(P + "--- A964（E2）：命中区覆盖（报告式）---");
                const float PxPerUnit964 = 108f;    // 世界单位 ↔ 画布 px（与 `BattleDriver.Px` 同一换算）

                // ---- row 1：重置镜头钮（**硬写 px 矩形**那一族）----
                {
                    drv964.SetHudButtonActiveForTest("cameraReset", true);
                    var ctr = drv964.CameraResetButtonWorldPos;
                    var drw = drv964.CameraResetButtonDrawnPx;          // 实绘尺寸（px）
                    float ex = 0.45f * drw.x * 0.5f / PxPerUnit964;     // 实绘半宽 × 0.45
                    float ey = 0.45f * drw.y * 0.5f / PxPerUnit964;
                    float ox = 3.0f  * drw.x * 0.5f / PxPerUnit964;     // 实绘半宽 × 3（必定在外）
                    float oy = 3.0f  * drw.y * 0.5f / PxPerUnit964;
                    bool in964 = drv964.CameraResetButtonHit(ctr)
                              && drv964.CameraResetButtonHit(ctr + new Vector3(ex, 0f, 0f))
                              && drv964.CameraResetButtonHit(ctr + new Vector3(0f, ey, 0f));
                    bool out964 = !drv964.CameraResetButtonHit(ctr + new Vector3(ox, 0f, 0f))
                               && !drv964.CameraResetButtonHit(ctr + new Vector3(0f, oy, 0f));
                    hits964.Add($"E2\t重置镜头钮\tCameraResetButtonHit\t实绘 {drw.x:F3}×{drw.y:F3} px"
                              + $"\t内侧中={in964} · 外侧不中={out964}\t原版 m_RaycastPadding=(−8,−8,−8,−8)（负=外扩）");
                    Check(in964,
                          $"★ A964/E2：重置镜头钮 —— **实绘矩形内的中心 + 0.45 半宽处都打得中**"
                        + $"（实绘 {drw.x:F3}×{drw.y:F3} px，命中区 = 原版 rect 64.443×61.846 四边各外扩 8）"
                        + "｜🧨 改坏法：`CameraResetHitPxW/H` 写回旧口径「往里缩」（`rect − pad`）⇒ 半宽只剩 24.22 px ⇒ 红");
                    Check(out964,
                          "★ A964/E2（**灭自证**）：重置镜头钮 —— **3 倍实绘半宽处打不中**（命中区是**有界**的）"
                        + " —— 与上一条配对：「不设界 / 恒 return true」会让上一条绿、本条红");
                }

                // ---- row 2：设置面板四颗 + 三根音量滑块 ----
                {
                    var sp964 = drv964.Settings;
                    if (sp964 != null) { CloseAll964(); sp964.Show(); }
                    Check(sp964 != null && sp964.Visible, "★ A964/E2：（前提）设置面板开起来了");
                    if (sp964 != null && sp964.Visible)
                    {
                        // `Auto Zoom` 那一行喂的就是 A445 段用的同一个点（`AutoZoomBoxWorldPos`）
                        // 🔴 **2026-10-22**：「对手难度」那颗已删（原版没有那个入口）⇒ 本探针只剩
                        //    投降 / AutoZoom 两颗。
                        bool a964 = sp964.HitResign(sp964.ResignWorldPos);
                        bool c964b = sp964.HitAutoZoom(sp964.AutoZoomBoxWorldPos);
                        hits964.Add($"E2\t设置面板 投降/AutoZoom\tHit{nameof(SettingsPanel.HitResign)} 等"
                                  + $"\t视觉中心\t{a964}/{c964b}\tClose 那颗没有公开中心读口（见报告「没覆盖」）");
                        Check(a964, "★ A964/E2：设置面板**「投降」钮的视觉中心必中**"
                                  + "（`HitResign` 是**硬写 px 矩形** `300×90` + `RectContains`，⛔ 不是 `Contains`）"
                                  + "｜🧨 改坏法：把 `ResignWPx/HPx` 写小到小于那颗钮 ⇒ 红");
                        Check(c964b, "★ A964/E2：设置面板**「Auto Zoom」那一行的视觉中心必中**"
                                   + "（走 `AzHitPx` 那两块**原版矩形**，⛔ 不是「行框整个」）");

                        int slidN964 = 0, slidBad964 = 0;
                        for (int si964 = 0; si964 < sp964.SliderCount; si964++)
                        {
                            var sl964 = sp964.SliderAt(si964);
                            if (sl964 == null || !sl964.Visible) continue;
                            slidN964++;
                            // 轨道中心 / 手柄中心 / 左右两沿 —— 四点**都必须算命中**。
                            // 🔴 手柄在**右端会探出轨道**（原版那两颗 Image 的 `m_RaycastTarget` 都是 1）
                            //    ⇒ 那不是缺陷、是**照原版**做的（判据写在 `WfSlider.Contains` 上面那段）。
                            // ⚠️ **2026-10-19（A1301①）**：本件的 `Contains` 已**不再走 `HitBand`**
                            //    （那是**单矩形近似**：整条轨道宽都取 `max(半轨道, 半手柄)`）——
                            //    现在 = 「轨道那块 ∪ 手柄按 `m_RaycastPadding(−25,−25,−25,−25)` 外扩后的框」
                            //    的**真并集**。这四点在新口径下照样全中（逐点算过）。老口径 + 那 −25 的
                            //    判别式 → 上面「17. 设置面板…」那节的 A1301① 五条。
                            if (!sl964.Contains(sl964.WorldPos) || !sl964.Contains(sl964.HandleWorldPos)
                             || !sl964.Contains(sl964.LeftWorld) || !sl964.Contains(sl964.RightWorld))
                                slidBad964++;
                        }
                        hits964.Add($"E2\t音量滑块 ×{slidN964}\tWfSlider.Contains（轨道 ∪ 手柄外扩框）\t轨道/手柄/两沿\t{(slidBad964 == 0 ? "全中" : slidBad964 + " 条不中")}\t手柄探出轨道是【原版行为】");
                        Check(slidN964 > 0 && slidBad964 == 0,
                              $"★ A964/E2：三根音量滑块（实建 {slidN964} 根）—— **轨道中心 / 手柄中心 / 左右两沿都算命中**"
                            + "（判据只此一份 = `WfSlider.Contains`；⛔ 不许在任一侧另写一份）"
                            + "｜🧨 改坏法：把 `Contains` 的手柄那一半去掉（只按轨道判）⇒ 值接近 1 时手柄上那一点判不中 ⇒ 红");
                        sp964.Hide();
                    }
                }

                // ---- row 3：战斗日志面板的每一行 ----
                {
                    // 🔴 **夹具（2026-10-15 第三十二会话 · 诊断 `BT-4`）：本行的「行」只来自
                    //    `Ctx.ActionLog` 里【非 `Draw`】的条目** —— `RefreshBattleLog` 的
                    //    `case EvtKind.Draw:` 是 `skipRow = true`（主对话 2026-10-18 裁定：原版**只在抽到
                    //    【已布设的陷阱】时才记**，普通抽牌照原版**一次都不该印**；`skipRow` 那个口径是
                    //    `ee784b5` 才引进的，而这条断言加在它之前 ⇒ 红的时机与那条口径改动吻合）。
                    //    本局从 `Begin` 到这儿**一个动作都没做过** ⇒ `ActionLog` 全是回合开始那一抽的
                    //    `Draw` ⇒ 面板 `FilledRows == 0` ⇒ 下面那条 `rowsN964 > 0` **恒红**
                    //    （不是面板坏了、也不是 `RowAt` 坏了）。
                    //    ⇒ 先**真打完若干回合**（我方 `SimulateEndTurn` → `SimulateAiTurn` 让 AI 部署/攻击
                    //      —— 与 `DriveTacticAndCheck` 同一个驱动形状），**试到 `ActionLog` 里出现
                    //      一条非 `Draw` 的记录为止**（上限 6 回合；⛔ 不写死「走几个回合」，那会随
                    //      种子/牌序漂）。驱动之后仍是**我方回合**（`SimulateAiTurn` 收尾会 `EndTurnAndAdvance`）。
                    //    ⚠️ 判据是**引擎的 `ActionLog`**，⛔ 不是往面板里手塞一行 —— 那才是恒真的假绿。
                    for (int t964 = 0; t964 < 6 && !HasNonDrawEvt964(drv964.Ctx); t964++)
                    {
                        drv964.SimulateEndTurn();
                        drv964.SimulateAiTurn();
                        Step(0.3f);
                    }
                    var log964 = drv964.BattleLog;
                    if (log964 != null && !log964.Visible) drv964.ShowBattleLog();
                    log964 = drv964.BattleLog;
                    // 🔴 **2026-10-22（用户口径「战斗里原版没有的设计不要」）补充**：上面那 6 回合只保证
                    //    `ActionLog` 里有「非 Draw」的**事件** —— 而 2026-10-22 起**后果类事件（Deploy /
                    //    Hit / Heal / Death / Return / Trigger）不再产出行**（原版 `CemeteryActionType`
                    //    只有九种动作）⇒ 那 6 回合里若只出了这些，面板仍是 **0 行**。
                    //    ⇒ 再加一道：**驱动到面板真有行为止**（上限 6 回合，⛔ 不写死回合数 —— 会随种子漂）。
                    for (int t2 = 0; t2 < 6 && log964 != null && log964.FilledRows == 0; t2++)
                    {
                        drv964.SimulateEndTurn();
                        drv964.SimulateAiTurn();
                        Step(0.3f);
                        drv964.ShowBattleLog();      // Show + Refresh（幂等）
                        log964 = drv964.BattleLog;
                    }
                    Check(log964 != null && log964.Visible, "★ A964/E2：（前提）战斗日志面板开起来了");
                    if (log964 != null && log964.Visible)
                    {
                        int rowsN964 = 0, rowsBad964 = 0;
                        int filled964 = log964.FilledRows;
                        for (int r964 = 0; r964 < filled964; r964++)
                        {
                            var bg964 = log964.RowBg(r964);
                            if (bg964 == null || !bg964.gameObject.activeSelf) continue;   // `RowAt` 也跳过这一类
                            Vector3 wp964;
                            if (!log964.RowCenterWorld(r964, out wp964)) continue;
                            rowsN964++;
                            // 中心 + 横向 0.45 半宽（同一行、只挪 x ⇒ 不会落到邻行）
                            if (log964.RowAt(wp964) != r964) rowsBad964++;
                            if (log964.RowAt(wp964 + new Vector3(bg964.WorldW * 0.45f, 0f, 0f)) != r964) rowsBad964++;
                        }
                        hits964.Add($"E2\t日志面板 {rowsN964} 行\tBattleLogPanel.RowAt\t行底板 quad 的中心 + 0.45 半宽"
                                  + $"\t{(rowsBad964 == 0 ? "全中" : rowsBad964 + " 条不中")}\t命中区就是行底板 quad 本身（比原版宽，已记账）");
                        Check(rowsN964 > 0 && rowsBad964 == 0,
                              $"★ A964/E2：战斗日志面板（{rowsN964} 行）—— **每行的中心 + 0.45 半宽都判回该行**"
                            + "（命中判定 = `RowAt`，它量的就是**行底板那颗 quad 的真实矩形**）"
                            + "｜🧨 改坏法：把 `RowAt` 的 `WorldW/WorldH` 换成写死的常量（与原版 43.134 行高脱钩）⇒ 红");
                        log964.Hide();
                    }
                }

                // ---- row 4：`ChatPopup` 6 颗台词钮 ----
                {
                    var pop964 = drv964.ChatPopup;
                    Check(pop964 != null && pop964.Ready, "★ A964/E2：（前提）`ChatPopup` 建起来了");
                    if (pop964 != null && pop964.Ready)
