                //  ⚠️ **2026-10-18 更正（铁律 5）**：上句对 `HitContinue` **已不再成立** ——
                //     `A1061` 就照这里说的「另开一件、另配断言」办了：`MultiCardDisplay.HitContinue`
                //     按订正后的原版判据重算（条那颗 `Image` 的 `m_RaycastPadding = (0,−40,0,−40)`
                //     ⇒ 横向不变、上下各 +40；圆钮 `RT=0` ⇒ 那颗**不吃射线**），
                //     配套断言 = 本段 `E2④` 新增的两条**口径判别式**（`A1061①②`）。
                //     `HitMyDeckPile` / `Contains` 两条**仍未动**。
                //  ⛔ **位置**：本段落在 **模型③ 之后** —— ⑥ 那一行走 `SimulateUseAbility` 真弹一次
                //     技能面板（会动局面、会选目标），摆在模型③前面会把红挪到模型③那一段上。
                Debug.Log(P + "--- A964（E2 补遗）：7 行只读口 · 两态 ---");
                {
                    var drvE964 = drv964;

                    // ---- 补 1：**手牌各张**（口：`CardInteraction.HitCardForTest` / `HandCardPointForTest`）----
                    {
                        var hi964 = drvE964.interaction;
                        int hn964 = hi964 != null ? hi964.HandCardCountForTest : 0;
                        Check(hi964 != null && hn964 > 0,
                              "★ A964/E2①：（前提）手牌里有牌（`CardInteraction` 在、`_cards` 非空）"
                            + $"（实得 {hn964} 张）—— 空手牌时下面两条是空跑");
                        if (hi964 != null && hn964 > 0)
                        {
                            int hCnt964 = 0, hBad964 = 0, hEdge964 = 0, hMid964 = 0, hFar964 = 0;
                            for (int k964 = 0; k964 < hn964; k964++)
                            {
                                Vector3 c964;
                                if (!hi964.HandCardPointForTest(k964, 0f, 0f, out c964)) continue;
                                hCnt964++;
                                if (hi964.HitCardForTest(c964) != k964) hBad964++;
                                // 实绘矩形内另一点：局部 **+0.45 半高**。⛔ 别改成横向 ——
                                // 手牌是扇形叠压，横向那点会落进**左边邻牌**（z 更小 ⇒ 判给它），
                                // 那是叠压的**语义**、不是缺陷（`A964 续 ②` 的「报告式」裁定）；
                                // 竖直方向邻牌中心隔着 ≥1.339 世界单位 > 卡半宽 1.10 ⇒ 干净。
                                // 🔴 **2026-10-17（`W13` · 主对话裁定）：`0.40` → 回 `0.45`。**
                                //   本会话早先 `W4` 按「新命中矩形上沿 1.42565」把取样点放宽到 `0.40` ——
                                //   **那是在迁就当时错的实现**。批② 把实现改成原版 `BoxCollider2D` 之后
                                //   底矩形 = `1.97 × 3.02`、in-hand 档**上沿仍是 1.51** ⇒
                                //   `0.45 × 3.3313 = 1.499085 < 1.51` ⇒ **原值本来就是对的**。
                                //   判据 = `Core/CardView.cs` 文件头（主面 `1.97×3.02 @ (0,0)`）。
                                // ⚠️ `0.45` 的余量只剩 `1.51 − 1.499085 = 0.0109` 卡单位（前台 250 px/卡单位 ≈ 2.7 px，很薄）
                                //   ⇒ 另补一条更内侧的 **`0.35`** 作**稳定判别**（覆盖实绘靠它兜底）。
                                Vector3 e964;
                                if (hi964.HandCardPointForTest(k964, 0f, 0.45f, out e964)
                                    && hi964.HitCardForTest(e964) == k964) hEdge964++;
                                Vector3 m964;
                                if (hi964.HandCardPointForTest(k964, 0f, 0.35f, out m964)
                                    && hi964.HitCardForTest(m964) == k964) hMid964++;
                                // 灭自证那一半：挪到手牌上方 10 世界单位（手牌是窄带）⇒ 一张都不许中
                                if (hi964.HitCardForTest(c964 + new Vector3(0f, 10f, 0f)) != -1) hFar964++;
                            }
                            hits964.Add($"E2①\t手牌 ×{hCnt964}\tCardInteraction.HitCardForTest（= 私有 HitTest 本体）"
                                      + $"\t中心中 {hCnt964 - hBad964}/{hCnt964} · 0.45 半高中 {hEdge964}/{hCnt964}"
                                      + $" · 0.35 半高中 {hMid964}/{hCnt964}"
                                      + $"\t中心判错 {hBad964} · 上方 10 单位误中 {hFar964}\t卡是扇形 ⇒ 只在卡的局部系取点");
                            Check(hCnt964 > 0 && hBad964 == 0 && hEdge964 == hCnt964,
                                  $"★ A964/E2①：手牌 {hCnt964} 张 —— **每张的视觉中心 + 实绘矩形内的 0.45 半高点都判回它自己**"
                                + $"（中心中 {hCnt964 - hBad964}/{hCnt964} · 内侧点中 {hEdge964}/{hCnt964}）"
                                + "｜🧨 改坏法：`HitTest` 里 `c.Contains(world)` 失效、或卡的 z 排序反了 ⇒ 红");
                            Check(hCnt964 > 0 && hMid964 == hCnt964,
                                  $"★ A964/E2①（稳定判别）：0.35 半高那点（{hMid964}/{hCnt964}）"
                                + " —— 比 0.45 离边远 0.33 卡单位，命中矩形一旦退回批①那套小的就必红（0.45 只有 ~1 px 余量）");
                            Check(hFar964 == 0,
                                  $"★ A964/E2①（**灭自证**）：手牌上方 10 世界单位处**一张都判不中**（误中 {hFar964} 张）"
                                + " —— 与上一条配对：「命中区无界 / 恒 return 0」会让上一条绿、本条红");
                        }
                    }

                    // ---- 🆕 2026-10-19（`T03`）：`CardView.Contains` 的**三处调用点**各补「边界上 / 外 1 px」----
                    //  背景：`T03` §六-4 点名「手牌 / 场上 / 换牌那三条路今天**一条边界断言都没有**」；
                    //  上面 `A964/E2①②` 那两条只断「中心 / 0.45 内侧必中」，**钉不住边在哪**。
                    //  判据 = 原版 `2DCard` 上的 `BoxCollider2D` 主面（`Core/CardView.cs` 文件头）：
                    //    · 常态 `1.97 × 3.02 @ y 0`（半宽 0.985 / 半高 1.51）
                    //    · in-hand `1.97 × 3.0502 @ y −0.0151`（= 主面 × `colliderHeightMultiplierInHand 1.01`，
                    //      **只往下长、上沿仍是 1.51**）
                    //  ⛔ 期望值一律**字面量**（1.97 / 3.02 / 1.01），⛔ 不从 `CardView.HitHalf*` 反推（自证）。
                    //  手法 = 在**卡自己的命中标架**里二分夹逼（同 `A156` 那组）：先找「命中→不命中」的边界，
                    //    再断「它离原版值 ≤ 1 px」，最后断「边界外 1 px 必不中 / 边界内 1 px 必中」。
                    //  第 1 处：手牌 —— `CardInteraction.HitTest`（经 `HitCardForTest`，就是生产本体）。
                    {
                        var hiT03 = drvE964.interaction;
                        int nT03 = hiT03 != null ? hiT03.HandCardCountForTest : 0;
                        Check(hiT03 != null && nT03 > 0, "★ T03：（前提）手牌非空 —— 下面四条边界要拿它");
                        if (hiT03 != null && nT03 > 0)
                        {
                            // 只取**最前面那张**（z 最小）：`HitTest` 取 z 最小 ⇒ 只有它能保证
                            // 「边界上的点判回它自己」；扇形手牌互相叠压，别的卡 z 更大 ⇒ 即使含住该点也不赢。
                            int kT03 = -1; float zMinT03 = float.MaxValue;
                            for (int i = 0; i < nT03; i++)
                            {
                                var cv = hiT03.HandCardForTest(i);
                                if (cv != null && cv.transform.position.z < zMinT03)
                                { zMinT03 = cv.transform.position.z; kT03 = i; }
                            }
                            var hvT03 = kT03 >= 0 ? hiT03.HandCardForTest(kT03) : null;
                            Check(hvT03 != null, "★ T03：（前提）取得到最前面那张手牌的 `CardView`");
                            if (hvT03 != null)
                            {
                                Check(hvT03.IsHandFaceForTest,
                                      "★ T03：（前提）手牌卡的脸型 = `CardFace.Hand`（⇒ 原版 in-hand 档 `1.97×3.0502 @ −0.0151`）");
                                const float halfW03 = 1.97f * 0.5f;                       // 0.985
                                const float halfH03 = 3.02f * 1.01f * 0.5f;               // 1.5251
                                const float dy03    = -(halfH03 - 3.02f * 0.5f);           // −0.0151
                                float pxU03 = Mathf.Abs(hvT03.transform.lossyScale.x) * PxPerUnit964;  // 1 卡单位 = ? px
                                Check(pxU03 > 1f, $"★ T03：（前提）卡的换算非退化（1 卡单位 = {pxU03:F2} px）");
                                if (pxU03 > 1f)
                                {
                                    float one03 = 1f / pxU03;                             // 1 屏幕 px（卡局部单位）
                                    System.Func<Vector3, bool> hitT03 = p => hiT03.HitCardForTest(p) == kT03;
                                    // 局部系二分：inside → outside，回传收敛到的那个坐标分量
                                    // 🔴 **2026-10-20（W58 · BTFIX3）**：与 `edgeM03`（换牌那一份）同形 ——
                                    //   原签名**只回 x**（`ix + (ox-ix)*lo`），纵向两条传 `ix = ox = 0`
                                    //   ⇒ 无论二分收敛到哪都回 **0**（日志 91431/91595 实得 0.0000）。
                                    //   加 `vertical` ⇒ 回**插值后的那个轴**；命中判断本身没动（横向一直绿）。
                                    System.Func<bool, float, float, float, float, float> edge03 =
                                        (vertical, ix, iy, ox, oy) =>
                                        {
                                            float lo = 0f, hi = 1f;
                                            for (int k = 0; k < 40; k++)
                                            {
                                                float t = (lo + hi) * 0.5f;
                                                if (hitT03(hvT03.HitLocalToWorldForTest(
                                                        ix + (ox - ix) * t, iy + (oy - iy) * t))) lo = t;
                                                else hi = t;
                                            }
                                            float lx = ix + (ox - ix) * lo, ly = iy + (oy - iy) * lo;
                                            return vertical ? ly : lx;
                                        };
                                    float eL03 = edge03(false, -halfW03 + 0.05f, 0f, -halfW03 - 0.08f, 0f);
                                    float eR03 = edge03(false,  halfW03 - 0.05f, 0f,  halfW03 + 0.08f, 0f);
                                    float eT03 = edge03(true, 0f, dy03 + halfH03 - 0.05f, 0f, dy03 + halfH03 + 0.08f);
                                    float eB03 = edge03(true, 0f, dy03 - halfH03 + 0.05f, 0f, dy03 - halfH03 - 0.08f);
                                    // 边界上（±1 px）+ 外 1 px。`<=` 是闭区间 ⇒ 边界内侧 1 px 必中。
                                    bool okL03 = Mathf.Abs(eL03 - (-halfW03)) <= one03
                                              && hitT03(hvT03.HitLocalToWorldForTest(eL03 + one03, 0f))
                                              && !hitT03(hvT03.HitLocalToWorldForTest(eL03 - one03, 0f));
                                    bool okR03 = Mathf.Abs(eR03 - halfW03) <= one03
                                              && hitT03(hvT03.HitLocalToWorldForTest(eR03 - one03, 0f))
                                              && !hitT03(hvT03.HitLocalToWorldForTest(eR03 + one03, 0f));
                                    bool okT03 = Mathf.Abs(eT03 - (dy03 + halfH03)) <= one03
                                              && hitT03(hvT03.HitLocalToWorldForTest(0f, eT03 - one03))
                                              && !hitT03(hvT03.HitLocalToWorldForTest(0f, eT03 + one03));
                                    bool okB03 = Mathf.Abs(eB03 - (dy03 - halfH03)) <= one03
                                              && hitT03(hvT03.HitLocalToWorldForTest(0f, eB03 + one03))
                                              && !hitT03(hvT03.HitLocalToWorldForTest(0f, eB03 - one03));
                                    hits964.Add($"T03\t手牌（第 {kT03} 张 · 最前）\tCardInteraction.HitCardForTest"
                                              + $"\t原版 in-hand 1.97×3.0502 @ −0.0151 卡单位"
                                              + $"\t边 L{eL03:F4}/R{eR03:F4}/T{eT03:F4}/B{eB03:F4}（期望 ∓0.985 / −0.0151±1.5251）"
                                              + $"\t1 px = {one03:F5} 卡单位");
                                    Check(okL03 && okR03,
                                          $"★ T03：手牌 x 两侧边界 = 原版 **±0.985** 卡单位（实得 {eL03:F4} / {eR03:F4}），"
                                        + "且**边界内 1 px 必中 / 外 1 px 必不中**"
                                        + "｜🧨 改坏法：`HitHalfW` 退回整卡半宽 1.04635（多认 15.3 px）或把 `<=` 改 `<` ⇒ 红");
                                    Check(okT03 && okB03,
                                          $"★ T03：手牌 y 上下边界 = 原版 in-hand **上沿 {dy03 + halfH03:F4} / 下沿 {dy03 - halfH03:F4}**"
                                        + $"（实得 {eT03:F4} / {eB03:F4}），且**边界内 1 px 必中 / 外 1 px 必不中**"
                                        + "｜🧨 改坏法：把 `CardFace.Hand` 那一档删掉（回常态 3.02 ⇒ 下沿少 5 px）或上沿跟着下移 ⇒ 红");
                                }
                            }
                        }
                    }

                    // ---- 补 2：**场上单位**（口：`BattleDriver.HitUnitSlotForTest`）----
                    {
                        int side964u = drvE964.MySideForTest;
                        // 🔴🔴 **2026-10-21（战斗线 `新账-64`）：本块所有探针点一律先过这一跳。**
                        //   `HitSlot` 的入参是 **`WorldPointer()` 那个正交指针平面的点**；
                        //   下面这些点全是「卡的**原始世界坐标**」（`transform.position` /
                        //   `TransformPoint(卡局部系)`）—— 真 3D 战场上两者差 1.49–1.56 世界单位。
                        //   以前直接喂 ⇒ 这组断言**根本没覆盖生产指针空间**，那正是「我方整排点不到」
                        //   能静默到今天的原因（诊断 → `资料/普查产出_1021/W61_战斗线_战将点击诊断.md` §4·3）。
                        //   桥 = `BattleDriver.PointerAtWorldForTest`（= `boardCam.WorldToScreenPoint`
                        //   → `LayoutSpace.ScreenToWorld(…, cam)`）。⚠️ `HitSlotByContainsForTest` **不包**：
                        //   它是「改前那一版」的对照物，判据本来就在**战场世界**里（`Contains` 用手算矩形）。
                        System.Func<Vector3, Vector3> Ptr = p => drvE964.PointerAtWorldForTest(p);
                        int uSlot964 = drvE964.Ctx != null ? FreeSlot(drvE964.Ctx, side964u) : -1;
                        Check(uSlot964 >= 0, "★ A964/E2②：（前提）我方棋盘上有一个空格能摆探针单位");
                        if (uSlot964 >= 0)
                        {
                            ClearEffects();
                            drvE964.Ctx.Players[side964u].Board[uSlot964] =
                                new UnitState(CardByName(StarterCards.Tide(), "Tide Minion"), false) { Exhausted = false };
                            drvE964.RefreshAll();
                            var uv964 = drvE964.MyUnits.ContainsKey(uSlot964) ? drvE964.MyUnits[uSlot964] : null;
                            Check(uv964 != null, "★ A964/E2②：（前提）那个单位建出了视图");
                            if (uv964 != null)
                            {
                                var uc964 = uv964.transform.position;
                                var ud964 = new Vector2(uv964.transform.lossyScale.x * CardView.Width,
                                                        uv964.transform.lossyScale.y * CardView.Height);
                                // ⛔ 偏移同样在**卡的局部系**里取（棋盘上的单位也带摆放角）
                                // 🔴 **2026-10-17（`W13` · 主对话裁定）：`0.40` → 回 `0.45`。**
                                //   同一支 `Contains`：批② 之后底矩形 = 原版 `BoxCollider2D` `1.97×3.02`
                                //   ⇒ 半高 **1.51**，`0.45 × Height = 1.499085 < 1.51` ⇒ **原值本来就是对的**；
                                //   早先那个 `0.40` 是迁就错实现（上沿 1.42565）放的宽。⛔ 别翻回去。
                                //   ⚠️ 余量只有 0.0109 卡单位（很薄）⇒ 另补 **`0.35`** 作**稳定判别**。
                                var uin964  = uv964.transform.TransformPoint(new Vector3(0f, 0.45f * CardView.Height, 0f));
                                var uinM964 = uv964.transform.TransformPoint(new Vector3(0f, 0.35f * CardView.Height, 0f));
                                var uout964 = uv964.transform.TransformPoint(new Vector3(0f, 3f    * CardView.Height, 0f));
                                bool inU964  = drvE964.HitUnitSlotForTest(side964u, Ptr(uc964)) == uSlot964
                                            && drvE964.HitUnitSlotForTest(side964u, Ptr(uin964)) == uSlot964;
                                bool inM964  = drvE964.HitUnitSlotForTest(side964u, Ptr(uinM964)) == uSlot964;
                                bool outU964 = drvE964.HitUnitSlotForTest(side964u, Ptr(uout964)) != uSlot964;
                                hits964.Add($"E2②\t场上单位（槽 {uSlot964}）\tBattleDriver.HitUnitSlotForTest（= 私有 HitSlot 本体）"
                                          + $"\t实绘 {ud964.x * PxPerUnit964:F2}×{ud964.y * PxPerUnit964:F2} px"
                                          + $"\t中心/0.45 内侧中={inU964} · 0.35 内侧中={inM964} · 外侧不中={outU964}"
                                          + $"\t探针单位 = `Tide Minion`（量完即摘）");
                                Check(inU964,
                                      $"★ A964/E2②：场上单位的**视觉中心 + 实绘矩形内的 0.45 半高点都判回它自己**（槽 {uSlot964}）"
                                    + "（命中 = `HitSlot`，量的就是 `CardView.Contains` = 卡自己的局部矩形）"
                                    + "｜🧨 改坏法：`HitSlot` 的 `v.Contains(world)` 失效、或格的 z 排序反了 ⇒ 红");
                                Check(inM964,
                                      $"★ A964/E2②（稳定判别）：0.35 半高那点也判回它自己（槽 {uSlot964}）"
                                    + " —— 离边 0.35×3.3313=1.166 卡单位，命中矩形退回批①那套小的也仍然绿 ⇒ 它只是**稳定**那一半，"
                                    + "判「矩形够不够大」靠上面 0.45 那条");
                                Check(outU964,
                                      "★ A964/E2②（**灭自证**）：卡**外侧 3 倍半高**处**判不中**（命中区有界）"
                                    + " —— 与上一条配对：「恒命中某个槽」会让上一条绿、本条红");

                                // ---- 🆕 2026-10-19（`T03`）：**第 2 处调用点** = 场上 `BattleDriver.HitSlot` ----
                                //  判据 = 原版 `2DCard` 的 `BoxCollider2D` 主面 **1.97 × 3.02 @ y 0**
                                //  （常态档；场上 `CardFace.Board` 不倾摆 ⇒ 与 `A2093` 的标架结论同向）。
                                //  手法同手牌那一组：局部系二分找边 → 比字面量 ≤ 1 px → 边界内/外 1 px。
                                Check(!uv964.IsHandFaceForTest,
                                      "★ T03：（前提）场上卡的脸型 ≠ `CardFace.Hand`（⇒ 常态档 `1.97×3.02 @ 0`）");
                                const float halfW03u = 1.97f * 0.5f;      // 0.985
                                const float halfH03u = 3.02f * 0.5f;      // 1.51
                                float pxU03u = Mathf.Abs(uv964.transform.lossyScale.x) * PxPerUnit964;
                                Check(pxU03u > 1f, $"★ T03：（前提）场上卡的换算非退化（1 卡单位 = {pxU03u:F2} px）");
                                if (pxU03u > 1f)
                                {
                                    float one03u = 1f / pxU03u;
                                    System.Func<Vector3, bool> hitU03 =
                                        p => drvE964.HitUnitSlotForTest(side964u, Ptr(p)) == uSlot964;
                                    // 🔴 **2026-10-20（W58 · BTFIX3）**：同 `edge03` —— 原签名只回 x，
                                    //   纵向两条传 `ix = ox = 0` ⇒ 恒回 0（日志 91595）。加 `vertical` 回插值轴。
                                    System.Func<bool, float, float, float, float, float> edgeU03 =
                                        (vertical, ix, iy, ox, oy) =>
                                        {
                                            float lo = 0f, hi = 1f;
                                            for (int k = 0; k < 40; k++)
                                            {
                                                float t = (lo + hi) * 0.5f;
                                                if (hitU03(uv964.HitLocalToWorldForTest(
                                                        ix + (ox - ix) * t, iy + (oy - iy) * t))) lo = t;
                                                else hi = t;
                                            }
                                            float lx = ix + (ox - ix) * lo, ly = iy + (oy - iy) * lo;
                                            return vertical ? ly : lx;
                                        };
                                    float eL03u = edgeU03(false, -halfW03u + 0.05f, 0f, -halfW03u - 0.08f, 0f);
                                    float eR03u = edgeU03(false,  halfW03u - 0.05f, 0f,  halfW03u + 0.08f, 0f);
                                    float eT03u = edgeU03(true, 0f, halfH03u - 0.05f, 0f, halfH03u + 0.08f);
                                    float eB03u = edgeU03(true, 0f, -halfH03u + 0.05f, 0f, -halfH03u - 0.08f);
                                    bool okL03u = Mathf.Abs(eL03u - (-halfW03u)) <= one03u
                                               && hitU03(uv964.HitLocalToWorldForTest(eL03u + one03u, 0f))
                                               && !hitU03(uv964.HitLocalToWorldForTest(eL03u - one03u, 0f));
                                    bool okR03u = Mathf.Abs(eR03u - halfW03u) <= one03u
                                               && hitU03(uv964.HitLocalToWorldForTest(eR03u - one03u, 0f))
                                               && !hitU03(uv964.HitLocalToWorldForTest(eR03u + one03u, 0f));
                                    bool okT03u = Mathf.Abs(eT03u - halfH03u) <= one03u
                                               && hitU03(uv964.HitLocalToWorldForTest(0f, eT03u - one03u))
                                               && !hitU03(uv964.HitLocalToWorldForTest(0f, eT03u + one03u));
                                    bool okB03u = Mathf.Abs(eB03u - (-halfH03u)) <= one03u
                                               && hitU03(uv964.HitLocalToWorldForTest(0f, eB03u + one03u))
                                               && !hitU03(uv964.HitLocalToWorldForTest(0f, eB03u - one03u));
                                    hits964.Add($"T03\t场上单位（槽 {uSlot964}）\tBattleDriver.HitUnitSlotForTest"
                                              + $"\t原版常态 1.97×3.02 @ 0 卡单位"
                                              + $"\t边 L{eL03u:F4}/R{eR03u:F4}/T{eT03u:F4}/B{eB03u:F4}（期望 ∓0.985 / ±1.51）");
                                    Check(okL03u && okR03u,
                                          $"★ T03：场上卡 x 两侧边界 = 原版 **±0.985** 卡单位（实得 {eL03u:F4} / {eR03u:F4}），"
                                        + "且**边界内 1 px 必中 / 外 1 px 必不中**"
                                        + "｜🧨 改坏法：`HitHalfW` 退回整卡半宽（1.04635）或把命中当 `z` 排序用错 ⇒ 红");
                                    Check(okT03u && okB03u,
                                          $"★ T03：场上卡 y 上下边界 = 原版常态 **±1.51** 卡单位（实得 {eT03u:F4} / {eB03u:F4}），"
                                        + "且**边界内 1 px 必中 / 外 1 px 必不中**"
                                        + "｜🧨 改坏法：把场上的卡误判成 `CardFace.Hand`（下沿多长 5 px）或矩形写回 2.8913 ⇒ 红");
                                }

                                // ---- 🆕 2026-10-20（`W57` · 战斗线 `T09` 步骤 B2b）：`HitSlot` 换真 collider ----
                                //  判据：`BattleDriver.HitSlot` 的命中已从手算 `CardView.Contains` 换成
                                //  `CardView.HitByCollider`（真 `BoxCollider2D` + `Physics2D.OverlapPoint`，B1 交付）；
                                //  槽号选择 / 重叠优先级（`transform.position.z` **最小**）**逐位不变**。
                                //  下面四段各自独立：① 逐点同判 ② 重叠取 z 最小 ③ 灭自证（真 collider）④ 灭自证（`SyncTransforms`）。
                                {
                                    float b2bCardH = CardView.Height * Mathf.Abs(uv964.transform.lossyScale.y);
                                    bool b2bHasCol = uv964.ColliderForTest != null;
                                    Check(b2bHasCol,
                                          "★ B2b（前提）：场上那张卡有一颗真 `BoxCollider2D`"
                                        + "（没建 ⇒ 下面「一致 / 灭自证」全部退化成手算 `Contains` = 空跑）");
                                    if (b2bHasCol)
                                    {
                                        // ① 逐点同判：生产口（真 collider） vs 改前那一版（手算 `Contains`）。
                                        //    采样点**复用**上面 E2②/T03 那四个（中心 / 0.45 / 0.35 / 3× 半高），⛔ 不另造一套。
                                        int sCen = drvE964.HitSlotForTest(side964u, Ptr(uc964));
                                        int cCen = drvE964.HitSlotByContainsForTest(side964u, uc964);
                                        int sIn  = drvE964.HitSlotForTest(side964u, Ptr(uin964));
                                        int cIn  = drvE964.HitSlotByContainsForTest(side964u, uin964);
                                        int sM   = drvE964.HitSlotForTest(side964u, Ptr(uinM964));
                                        int cM   = drvE964.HitSlotByContainsForTest(side964u, uinM964);
                                        int sOut = drvE964.HitSlotForTest(side964u, Ptr(uout964));
                                        int cOut = drvE964.HitSlotByContainsForTest(side964u, uout964);
                                        Check(sCen == uSlot964 && sCen == cCen && sIn == cIn && sM == cM && sOut == cOut,
                                              "★ B2b①：`HitSlot`（真 collider 投影）与改前那版（手算 `Contains`）在**四个采样点逐点同判**"
                                            + $"（中心 {sCen}/{cCen} · 0.45 半高 {sIn}/{cIn} · 0.35 半高 {sM}/{cM} · 3× 半高 {sOut}/{cOut}）"
                                            + " —— 0° 倾摆下两判据逐点一致（判据网格 → `B1` §3·1）"
                                            + "｜🧨 任一方口径漂了（真 collider 的 size/offset 没跟 `HitRect`）⇒ 红"
                                            + "；⚠️ 真 collider 那一侧先过 `Ptr`（`新账-64`：生产指针在正交平面上）");
                                        Check(drvE964.HitSlotHitCountForTest(side964u, Ptr(uc964)) >= 1,
                                              "★ B2b①（前提）：中心的真 collider 命中数 ≥ 1（下面「重叠取 z」要先有命中）");

                                        // ② 重叠优先级**逐位不变**：把另一张我方单位临时搬到同一世界点、z 一前一后
                                        //    ⇒ `HitSlot` 必须取 **z 小**那张（`Physics2D` 没有 z、查询返回顺序也不是渲染顺序）。
                                        int otherSlot = -1;
                                        CardView otherV = null;
                                        foreach (var kv in drvE964.MyUnits)
                                            if (kv.Key != uSlot964 && kv.Value != null) { otherSlot = kv.Key; otherV = kv.Value; break; }
                                        bool otherTemp = false;
                                        if (otherV == null)
                                        {
                                            int s2 = FreeSlot(drvE964.Ctx, side964u);
                                            if (s2 >= 0)
                                            {
                                                drvE964.Ctx.Players[side964u].Board[s2] =
                                                    new UnitState(CardByName(StarterCards.Tide(), "Tide Minion"), false) { Exhausted = false };
                                                drvE964.RefreshAll();
                                                if (drvE964.MyUnits.ContainsKey(s2) && drvE964.MyUnits[s2] != null)
                                                { otherSlot = s2; otherV = drvE964.MyUnits[s2]; otherTemp = true; }
                                            }
                                        }
                                        Check(otherV != null, "★ B2b②（前提）：有第二张我方单位视图可当重叠探针");
                                        if (otherV != null)
                                        {
                                            Vector3 pA0 = uv964.transform.position;
                                            Vector3 pB0 = otherV.transform.position;
                                            // 🔴 **2026-10-21（`新账-64`）**：`shared` 原来写 `z = 0` —— 现在**必须用卡自己的 z**。
                                            //   `HitSlot` 改按 collider 的**透视投影**判命中 ⇒ 同一 x/y、不同 z 的点
                                            //   投影到屏幕上是**不同的点**（指针要落在「卡画出来那个位置」上）。
                                            Vector3 shared = pA0;
                                            Vector3 ptrShared = Ptr(shared);
                                            // z 用**小偏移**（−0.10 / −0.20 / −0.30）而不是原来的 ±999/±1000：
                                            //   投影之后 z 参与透视（`boardCam` 在 z ≈ −13.57 ⇒ z = −999 跑到相机**背后**，
                                            //   `CardHit` 会判「投影无效」）⇒ 全用负偏移就再也验不到「取 z 最小」。
                                            //   0.1 世界单位在深度 ≈7 处只有 ~1.4% 的缩放差 ⇒ 两张卡的投影矩形仍稳稳盖住
                                            //   同一个指针点；「不会有第三张卡插进这两个 z 之间」照旧成立（同行步距 0.82 > 卡宽 0.75，
                                            //   别的格在屏幕上不重叠；本方法只遍历同一侧的单位）。
                                            uv964.transform.position  = new Vector3(shared.x, shared.y, shared.z - 0.10f);
                                            otherV.transform.position = new Vector3(shared.x, shared.y, shared.z - 0.20f);
                                            int nHitOverlap = drvE964.HitSlotHitCountForTest(side964u, ptrShared);
                                            int pickB = drvE964.HitSlotForTest(side964u, ptrShared);   // B 的 z 更小 ⇒ 取 B
                                            uv964.transform.position  = new Vector3(shared.x, shared.y, shared.z - 0.30f);  // A 翻到最前
                                            int pickA = drvE964.HitSlotForTest(side964u, ptrShared);
                                            uv964.transform.position  = pA0;
                                            otherV.transform.position = pB0;
                                            if (otherTemp)
                                            {
                                                drvE964.Ctx.Players[side964u].Board[otherSlot] = null;
                                                drvE964.RefreshAll();
                                            }
                                            Check(nHitOverlap >= 2 && pickA == uSlot964 && pickB == otherSlot,
                                                  "★ B2b②：两张卡叠在同一点 ⇒ 取 **z 最小**那张（前景），换 z 顺序 ⇒ 答案跟着换"
                                                + $"（重叠命中 {nHitOverlap} 张 · A 在前 ⇒ 槽 {pickA}（期望 {uSlot964}）"
                                                + $" · B 在前 ⇒ 槽 {pickB}（期望 {otherSlot}））"
                                                + "｜🧨 改成「取查询返回的第一颗」或「取字典序第一张」⇒ 红"
                                                + "（`Physics2D` 的返回顺序不是渲染顺序）");
                                            uv964.transform.position = pA0;   // 双保险（上面已复原）
                                        }

                                        // ③ 灭自证（真 collider）：临时把 collider 放大 1.2× ⇒ 「常态边外一点点」(1.05, 0) 必翻成命中；
                                        //    同一刻手算 `Contains` 仍判**在外**（它不跟 collider 走）⇒ 证明断言量的是真 collider。
                                        var colB = uv964.ColliderForTest;
                                        Vector2 size0B = colB.size;
                                        var pEdgeB = uv964.HitLocalToWorldForTest(1.05f, 0f);      // 常态半宽 0.985 ⇒ 在外
                                        var ptrEdgeB = Ptr(pEdgeB);                                // `新账-64`：先换到指针平面
                                        bool beforeHitB      = drvE964.HitSlotForTest(side964u, ptrEdgeB) == uSlot964;
                                        bool beforeContainsB = uv964.Contains(pEdgeB);
                                        colB.size = size0B * 1.2f;
                                        Physics2D.SyncTransforms();                               // 尺寸改了也让查询看到（幂等）
                                        bool enlargedHitB    = drvE964.HitSlotForTest(side964u, ptrEdgeB) == uSlot964;
                                        bool enlargedContB   = uv964.Contains(pEdgeB);
                                        colB.size = size0B;                                       // ⛔ 必须复原（同一张卡后面还要用）
                                        Physics2D.SyncTransforms();
                                        bool restoredHitB    = drvE964.HitSlotForTest(side964u, ptrEdgeB) == uSlot964;
                                        Check(!beforeHitB && !beforeContainsB && enlargedHitB && !enlargedContB && !restoredHitB,
                                              "★ B2b③（**灭自证**）：collider 放大 1.2× ⇒ (1.05, 0) 那点**翻成命中**、复原后又不中"
                                            + "（同一刻手算 `Contains` 一直判在外 ⇒ 两条判据独立）"
                                            + $"（改前 {beforeHitB}/{beforeContainsB} · 放大后 {enlargedHitB}/{enlargedContB} · 复原后 {restoredHitB}）"
                                            + "｜🧨 `HitSlot` 写回 `Contains`、或断言拿我们自己的常量反推 ⇒ 红");

                                        // ④ 灭自证（`SyncTransforms`）：同一帧内改 `transform.position` ⇒ 命中**立刻跟着走**。
                                        //    `Physics2DSettings.m_AutoSyncTransforms = 0`（现读）⇒ 去掉同步后这里读到的是
                                        //    **上一帧**的 collider 位置（画面完全正常 = 静默）。
                                        Vector3 pMove0  = uv964.transform.position;
                                        Vector3 pMoveTo = pMove0 + new Vector3(0f, 2f * b2bCardH, 0f);
                                        uv964.transform.position = pMoveTo;
                                        bool movedHitB = drvE964.HitSlotForTest(side964u, Ptr(pMoveTo)) == uSlot964;
                                        bool oldGoneB  = drvE964.HitSlotForTest(side964u, Ptr(pMove0)) != uSlot964;
                                        uv964.transform.position = pMove0;
                                        bool backHitB  = drvE964.HitSlotForTest(side964u, Ptr(pMove0)) == uSlot964;
                                        Check(movedHitB && oldGoneB && backHitB,
                                              "★ B2b④（**灭自证** · `SyncTransforms`）：同一帧内把卡挪走 2 个卡高 ⇒ "
                                            + "新位置必中 / 旧位置必不中 / 挪回来又中"
                                            + $"（{movedHitB}/{oldGoneB}/{backHitB}；`m_AutoSyncTransforms = 0`）"
                                            + "｜🧨 删掉 `HitSlot`（或 `HitByCollider`）里那句 `Physics2D.SyncTransforms()`"
                                            + " ⇒ 读到上一帧的位置 ⇒ 红");
                                    }
                                }
                            }
                            drvE964.Ctx.Players[side964u].Board[uSlot964] = null;
                            drvE964.RefreshAll();
                        }
                    }

                    // ---- 🆕 2026-10-21（战斗线 `新账-64`）：**点我方战将画出来的位置必须命中槽 4** ----
                    //  判据/根因 → `资料/普查产出_1021/W61_战斗线_战将点击诊断.md`：
                    //  `HitSlot` 原来拿「UI 正交平面」的指针点去问 `Physics2D`，而 3D 棋盘卡的 collider 在透视战场世界
                    //  （我方行两个平面纵向差 **1.49–1.56** 世界单位 ≫ collider 半高 0.54/0.60）⇒ **我方整排（含战将）恒 −1**；
                    //  敌方行只差 0.09、半高 1.04 ⇒ 碰巧能点（真机 `click_log #7/#8`：点敌方战将位置弹出的是**我方**督军）。
                    //  修法 = `BattleDriver.CardHit`（collider 四角 → `boardCam.WorldToScreenPoint`
                    //  → `LayoutSpace.ScreenToWorld(…, cam)` → 轴对齐矩形）。
                    //  ⚠️ 覆盖两档（铁律 5·c）：**我方战将**（原来点不到的那一档）+ **敌方战将**（碰巧能点的那一档）。
                    {
                        int side64 = drvE964.MySideForTest;
                        var wv64  = drvE964.BoardViewAt(BoardSpec.WarlordSlot, true);
                        var fv64  = drvE964.BoardViewAt(BoardSpec.WarlordSlot, false);
                        Check(wv64 != null, "★ 新账-64（前提）：**我方**战将（槽 4）的视图在场");
                        Check(fv64 != null, "★ 新账-64（前提）：**敌方**战将（槽 4）的视图在场");
                        Check(drvE964.cam != null && drvE964.boardCam != null,
                              "★ 新账-64（前提）：两台相机都在（HUD 正交 `cam` + 战场透视 `boardCam`）"
                            + " —— 少了任一台就走 2D 档，下面两条验的不是这条修法");
                        if (wv64 != null && fv64 != null && drvE964.cam != null && drvE964.boardCam != null)
                        {
                            Vector3 wCenter64 = wv64.transform.position;
                            // 前提（= 本 bug 能成立的那个「跨空间」量）：同一张卡，在**两套坐标**里的纵向归一化位置
                            //   差得远 —— 差太小的话「原始世界点」与「指针点」几乎重合，下面两条就没有判别力。
                            float vpY64 = drvE964.boardCam.WorldToViewportPoint(wCenter64).y;
                            float nzY64 = LayoutSpace.ToNormalized(wCenter64).y;
                            Check(Mathf.Abs(vpY64 - nzY64) > 0.10f,
                                  "★ 新账-64（前提）：战将卡心的**透视投影**纵向位置与「拿原始世界坐标当指针点」差 > 0.10"
                                + $"（viewport {vpY64:F4} vs 正交归一化 {nzY64:F4}，差 {Mathf.Abs(vpY64 - nzY64):F4}）"
                                + " —— 差太小 ⇒ 这条修法在批处理里验不出来（与真机 `click_log` 的 161–168 px 同源）");

                            var ptrMe64 = drvE964.PointerAtWorldForTest(wCenter64);
                            int hitMe64 = drvE964.HitSlotForTest(side64, ptrMe64);
                            Check(hitMe64 == BoardSpec.WarlordSlot,
                                  $"★ 新账-64：点**我方战将画出来的屏幕位置**必须命中 `WarlordSlot={BoardSpec.WarlordSlot}`"
                                + $"（实得 {hitMe64}）"
                                + "｜🧨 **修复前此条必红** —— 旧判据拿正交平面的点去问 3D collider ⇒ 我方整排恒 −1");

                            // 灭自证：同一 x、往上挪**一整个卡高**（卡局部系 `CardView.Height`）⇒ 不许命中 4。
                            //   「恒返回 4 / 命中区无界」会让上一条绿、本条红。
                            Vector3 up64 = wv64.transform.TransformPoint(new Vector3(0f, CardView.Height, 0f));
                            int hitUp64 = drvE964.HitSlotForTest(side64, drvE964.PointerAtWorldForTest(up64));
                            Check(hitUp64 != BoardSpec.WarlordSlot,
                                  "★ 新账-64（**灭自证**）：同一 x 上移**一个卡高**（卡局部 y += `CardView.Height`）"
                                + $"⇒ 不许命中 4（实得 {hitUp64}）"
                                + " —— 与上一条配对：「战将恒命中」会让上一条绿、本条红");

                            // 另一档：敌方战将（改前「碰巧能点」那一行）—— 修完必须仍然能点，且**点回它自己**
                            //   （真机上点它是弹出**我方**督军窗 ⇒ 这条同时挡住「两行串味」）。
                            var ptrFoe64 = drvE964.PointerAtWorldForTest(fv64.transform.position);
                            int hitFoe64 = drvE964.HitSlotForTest(1 - side64, ptrFoe64);
                            Check(hitFoe64 == BoardSpec.WarlordSlot,
                                  "★ 新账-64（另一档 · 敌方）：点**敌方战将画出来的位置**必须命中它自己的槽 4"
                                + $"（实得 {hitFoe64}）"
                                + "｜🧨 **回归**：这一行改前就「碰巧能点」（敌方两平面只差 0.09、半高 1.04）"
                                + " ⇒ 本条是「别把能点的改坏」那一半；串味由下一条挡");
                            // 串味那一半：同一个指针点，**我方那一侧一个都不许中**
                            //   （旧判据下我方战将的 collider y 区间 [0.06, 1.27] 恰好含住敌方行的指针点 y≈1.21
                            //    ⇒ `_myUnits` 先查 ⇒ 点敌方弹出我方；修完两行各归各的）。
                            int mineAtFoe64 = drvE964.HitSlotForTest(side64, ptrFoe64);
                            Check(mineAtFoe64 < 0,
                                  "★ 新账-64（**灭自证** · 两行串味）：同一个「敌方战将位置」的指针点，**我方那一侧必须一个都不中**"
                                + $"（实得槽 {mineAtFoe64}）"
                                + "｜🧨 旧判据下正是这一条坏掉：我方战将 collider 的 y 区间含住了敌方行的指针点"
                                + " ⇒ 点敌方战将弹出**我方**督军窗");
                        }
                    }

                    // ---- 补 3：**设置面板「关闭」**（口：`SettingsPanel.CloseWorldPos` / `CloseDrawnSize`）----
                    {
                        var sp964e = drvE964.Settings;
